local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["item:99-year-old-port"] = {n="99 Jahre alter Portwein",s="Der 99 Jahre alte Portwein ist eine außergewöhnlich seltene Flasche eines edlen Jahrgangstropfens, die aus Booty Bay als persönliches Geschenk für Gazlowe verschifft wurde. Nach einem Frachtunfall an den Docks von Ratchet wurde er von einem Verrückten namens Mad Magglish an sich gerissen, der in die gewundenen Tunnel vor den Höhlen des Wehklagens floh.",h="Der 99 Jahre alte Portwein ist eine außergewöhnlich seltene Flasche eines edlen Jahrgangstropfens, die aus...",kw={"99 jahre alter portwein","bigglefuzz","gazlowe","mad magglish","portwein","ratchet","revilgaz","die höhlen des wehklagens"},ang={["class:Rogue"]="Mad Magglish verlässt sich auf laienhafte Heimlichtuerei, um im Dunkeln vor den Höhlen des Wehklagens herumzuschleichen, doch ein erfahrener Schurke kann ihn leicht aus den Schatten aufscheuchen."},sec={{t="Ein Frachtunfall mit wertvoller Ladung",b="Der Transport wertvoller Fracht über das große Meer birgt stets Gefahren, doch Kranführer Bigglefuzz machte die Lage bei einer routinemäßigen morgendlichen Entladung in Ratchet noch deutlich schlimmer. Beim Versuch, eine überwältigende Lieferung aus Booty Bay abzufertigen, überlud der Goblin seinen Kran und ließ ein ganzes Gebirge von Kisten krachend auf die Docks stürzen. Im entstandenen Chaos schnappte sich der Stadtverschrobene – eine berüchtigte Gestalt namens Mad Magglish – eine außergewöhnlich alte Flasche 99 Jahre alten Portwein und flüchtete in die Hügel in Richtung der Höhlen des Wehklagens."},{t="Ein diplomatischer Jahrgang",b="Der gestohlene Portwein war kein gewöhnlicher Brand; er war von Baron Revilgaz von den Blackwater Raiders als geschätztes diplomatisches Geschenk für Gazlowe, den Chefingenieur und Herrscher von Ratchet, gesandt worden. Der Verlust einer solch kostbaren Sendung bedrohte Bigglefuzz' Lebensunterhalt und steigerte die Spannungen mit dem Hafenmeister beträchtlich. Nachdem der schwer fassbare Dieb bis in die finsteren äußeren Grotten der Höhlen verfolgt worden war, lauerte er dort mit der ungeöffneten Beute im Schatten, was die Hafenarbeiter zwang, externe Söldner anzuheuern, um sie zurückzuholen, bevor Gazlowe von diesem Missgeschick erfährt."}},faq={{q="Für wen war der 99 Jahre alte Portwein ursprünglich bestimmt?",a="Die Flasche wurde von Baron Revilgaz, dem Herrscher von Booty Bay, als wertvolles persönliches Geschenk an Gazlowe, den Boss von Ratchet, geschickt.",al={"für wen ist der portwein","wer bekommt den portwein","gazlowe geschenk"}},{q="Wie gelangte Mad Magglish an den Portwein?",a="Kranführer Bigglefuzz versuchte, mehr Fracht abzuladen, als sein Kran heben konnte, wodurch Kisten über die Docks von Ratchet geschleudert wurden. Mad Magglish nutzte das Chaos aus, um die Jahrgangsflasche an sich zu reißen und zu fliehen.",al={"wie wurde er gestohlen","wer hat den portwein gestohlen","dock unfall"}},{q="Wohin hat Mad Magglish die Flasche gebracht?",a="Magglish floh landeinwärts durch das Brachland und verschanzte sich in den felsigen Vorkammern und äußeren Tunneln, die in die Höhlen des Wehklagens führen.",al={"wo ist mad magglish","wo ist der portwein versteckt","portwein fundort"}},{q="Warum hat Bigglefuzz den Portwein nicht selbst zurückgeholt?",a="Bigglefuzz verfolgte den Dieb bis an die Schwelle der Höhlen des Wehklagens, weigerte sich jedoch aus Angst vor den Bestien und verderbten Druiden, die die Höhlen heimsuchen, hineinzugehen.",al={"warum bigglefuzz nicht nachsetzte","kranführer feige"}}},fp="16,288,24.521.0,18.522.1,50.122.0,42.205.0,39.130.0,48.164.0"}
P.entries["item:a-bloodstained-journal-page"] = {n="Eine blutbefleckte Tagebuchseite",s="Ein zerrissenes, makabres Pergament, das während der Ermittlungen zu Stalvan Mistmantle sichergestellt wurde. Mit getrocknetem Blut bedeckt, dient es als entscheidendes Beweisstück, das den verschwundenen Hauslehrer direkt mit grausamen Verbrechen im Dämmerwald in Verbindung bringt.",h="Ein zerrissenes, makabres Pergament, das während der Ermittlungen zu Stalvan Mistmantle sichergestellt wurde.",kw={"blutbefleckt","daltry","dunkelhain","dämmerwald","ebonlocke","handschrift","tagebuch","stalvan"},ang={["faction:Alliance"]="Für die Beschützer des Reiches ist dieses düstere Dokument der entscheidende Beweis, den Dunkelhains Nachtwache benötigt, um einen Mörder aufzuspüren, der sich in ihrer Mitte verbirgt."},sec={{t="Ein düsteres Beweisstück",b="Kommandantin Althea Ebonlocke wacht aufmerksam über Dunkelhain, doch bloße Verdächtigungen rechtfertigen kein formelles Vorgehen gegen das finstere Erbe eines Mannes. Diese zerrissene, blutbespritzte Seite aus Stalvan Mistmantles persönlichem Tagebuch liefert den materiellen Beweis, der nötig ist, um das Schlimmste zu bestätigen. Trotz der Blutspuren bleibt die Handschrift lesbar genug, um von den städtischen Beamten analysiert zu werden."},{t="Handschrift und Schuld",b="Um jeden Zweifel auszuräumen, bevor der Gerechtigkeit Genüge getan wird, verlässt sich Kommandantin Ebonlocke auf Amtmann Daltry, den Verwalter des Registers im Rathaus von Dunkelhain. Jahrelanges Archivieren städtischer Unterschriften hat Daltry zu einer Autorität für die örtlichen Handschriften gemacht. Nach dem Abgleich der blutbefleckten Seite mit den städtischen Aufzeichnungen bestätigt Daltry zweifelsfrei, dass es sich um Stalvans Handschrift handelt, und besiegelt damit die Schuld des Hauslehrers."}},faq={{q="Was ist diese blutbefleckte Tagebuchseite?",a="Es ist ein herausgerissenes Blatt aus Stalvan Mistmantles Tagebuch, das mit getrocknetem Blut getränkt ist. Kommandantin Althea Ebonlocke nutzt es als endgültigen materiellen Beweis für Stalvans mörderische Taten.",al={"blutbefleckte tagebuchseite","stalvan tagebuchseite","blutige seite"}},{q="Wer kann bestätigen, wer diese Seite verfasst hat?",a="Amtmann Daltry im Rathaus von Dunkelhain. Als Hüter des Stadtregisters gleicht er die Schrift auf der Seite mit alten archivierten Unterschriften ab, um Stalvans Handschrift zu verifizieren.",al={"wer liest die seite","amtmann daltry tagebuch","wer identifiziert handschrift"}},{q="Warum muss Althea Ebonlocke diese Seite untersuchen lassen?",a="Kommandantin Althea verdächtigt Stalvan schon lange, doch sie benötigt unumstößliche Beweise, bevor sie ihn offiziell für schuldig erklärt. Die Bestätigung, dass die Handschrift mit dem Register übereinstimmt, räumt jeden letzten Zweifel aus.",al={"warum althea seite braucht","warum handschrift prüfen"}},{q="Wohin führt diese Seite in den Ermittlungen?",a="Sobald Amtmann Daltry die Schrift bestätigt hat, verfügt Kommandantin Ebonlocke über den eindeutigen Beweis für Stalvans Gräueltaten, was der Nachtwache den Weg ebnet, ein für alle Mal mit ihm abzurechnen.",al={"was geschieht nach der seite","stalvan reihe danach"}}},fp="27,228,24.378.0,21.376.1,39.162.0,36.173.0,50.213.0,47.179.1"}
P.entries["item:a-clue-to-sanders-treasure"] = {n="A Clue to Sanders' Treasure",s="A Clue to Sanders' Treasure ist ein verwittertes Pergament, das von dem berüchtigten Piraten Captain Sanders hinterlassen wurde. Es dient als zweiter Schritt einer Schatzsuche, die über die Klippen und Küsten von Westfall verstreut ist.",h="A Clue to Sanders' Treasure ist ein verwittertes Pergament, das von dem berüchtigten Piraten Captain Sanders...",kw={"fass","schornstein","hinweis","pirat","sanders","schatz","westfall"},sec={{t="Das Rätsel eines Piraten",b="Dieses Pergament, das nach dem Verfolgen von Captain Sanders' erster Schatzkarte entdeckt wurde, liefert Hinweise weiter landeinwärts nach Westfall. Die gekritzelte Notiz weist den Finder direkt nach Osten von der Küste weg und fordert ihn auf, die Klippen hinauf zur Hauptstraße zu steigen. Sanders versteckte seinen nächsten Wegpunkt in einem alten Fass neben den bröckelnden Steinruinen eines verlassenen Schornsteins, was Suchende tiefer in das unruhige Farmland führt."}},faq={{q="Was ist dieser Hinweis?",a="Es ist eine handschriftliche Notiz von Captain Sanders, die jeden leitet, der schlau genug ist, seiner Spur zu einem weiteren versteckten Behälter in Westfall zu folgen.",al={"sanders hinweis","hinweis auf sanders schatz","was ist a clue to sanders treasure"}},{q="Wohin führt dieser Hinweis?",a="Der Hinweis führt Suchende direkt nach Osten die Küstenklippen hinauf zur Straße von Westfall, wo ein altes Fass nahe einem zerstörten Schornstein liegt.",al={"wohin muss ich gehen","ziel des hinweises","ort des schornsteins"}},{q="Wer war Captain Sanders?",a="Captain Sanders war ein Pirat, dessen Vermächtnis durch die Schatzverstecke und Rätsel fortlebt, die er an den Küsten und in den Landstrichen von Westfall verbarg.",al={"wer ist captain sanders","sanders geschichte","captain sanders"}}},fp="27,219,17.414.0,18.150.0,26.129.0,24.139.0"}
P.entries["item:a-dusty-unsent-letter"] = {n="Ein verstaubter, nie abgeschickter Brief",s="Ein verstaubter, nie abgeschickter Brief ist ein vergessenes Pergament, das aus einer alten Fußtruhe in Westfall geborgen wurde. Er liefert einen entscheidenden Beweis dafür, dass der schwer fassbare Stalvan Mistmantle vor seinem Verschwinden in Moonbrook lebte.",h="Ein verstaubter, nie abgeschickter Brief ist ein vergessenes Pergament, das aus einer alten Fußtruhe in...",kw={"amtmann daltry","dunkelhain","ein verstaubter, nie abgeschickter brief","unglückseliger geist","moonbrook","stalvan mistmantle","die legende von stalvan"},ang={["faction:Alliance"]="Stalvans Spuren zusammenzusetzen hilft Dunkelhain dabei, genaue Aufzeichnungen über Reisende und Ausgestoßene zu führen, die von Westfall bis in den Dämmerwald durch menschliche Siedlungen streifen."},sec={{t="Ein Hinweis im Staub",b="Bei der Suche nach der Vergangenheit des mysteriösen Stalvan Mistmantle entdecken Ermittler diesen unverschickten Brief, der in einer alten Fußtruhe in Moonbrook versteckt liegt. Moonbrooks Stadtchroniken enthielten keine Erwähnung von Stalvan, weshalb die Beamten in Dunkelhain seiner dortigen Anwesenheit skeptisch gegenüberstanden. Diese unversandte Korrespondenz liefert das fehlende Bindeglied und bestätigt, dass Stalvan eine Zeit lang in der Siedlung von Westfall lebte. Doch ihre Existenz wirft auch unheilvolle Fragen auf, da ihre Bergung einen rachsüchtigen Unglückseligen Geist aufschreckt, der die Überreste von Stalvans Vergangenheit mit bitterer Bosheit bewacht."},{t="Aktualisierung des Registers",b="Vor Amtmann Daltry im Rathaus von Dunkelhain gebracht, dient der Brief als handfester Beweis, um das Register der Stadt zu aktualisieren. Daltry bemerkt, wie seltsam es ist, dass die Korrespondenz nie abgeschickt wurde, was auf die plötzlichen Aufbrüche und die geheimnisvolle Spur hindeutet, die Stalvan quer durch die südlichen Königreiche der Allianz hinterließ."}},faq={{q="Wo ist dieser Brief zu finden?",a="Der Brief wird aus einer verlassenen Fußtruhe in Moonbrook in Westfall geborgen, versteckt zwischen den baufälligen Häusern, die nun von der Bruderschaft der Defias überrannt sind.",al={"fundort des briefs","wo man den verstaubten nie abgeschickten brief findet","moonbrook-brief"}},{q="Warum wurde der Brief nie abgeschickt?",a="Die genauen Gründe bleiben ungewiss, wenngleich Amtmann Daltry dies höchst verdächtig findet. Es deutet darauf hin, dass Stalvan Mistmantle Moonbrook möglicherweise in aller Eile verließ oder seine Korrespondenz aufgab, bevor er weiterzog.",al={"warum nicht abgeschickt","stalvan-brief unverschickt","für wen war der brief"}},{q="Wer muss diesen Brief sehen?",a="Der Brief muss zu Amtmann Daltry gebracht werden, der das Stadtregister im Rathaus von Dunkelhain verwaltet.",al={"wem gebe ich den brief","amtmann daltry brief","brief abgeben"}},{q="Warum greift ein Geist an, wenn man ihn findet?",a="Das Antasten der Fußtruhe beschwört einen Unglückseligen Geist herauf, der an Stalvans heimgesuchtes Vermächtnis gebunden ist. Er greift jeden an, der in seinem vergessenen Leben herumschnüffelt, und belegt Eindringlinge mit dem schwächenden Curse of Stalvan.",al={"unglückseliger geist","warum geist erscheint","curse of stalvan"}}},fp="21,195,18.564.0,21.306.1,27.165.0,30.197.0,29.110.0,41.202.0"}
P.entries["item:a-faded-journal-page"] = {n="Eine verblasste Tagebuchseite",s="Eine verblasste Tagebuchseite ist ein altes Pergament, das aus einer Truhe im Obergeschoss von Marshal Haggards abgelegenem Haus im Wald von Elwynn geborgen wurde. Es dient als entscheidender Hinweis bei der Aufdeckung der düsteren Geschichte rund um Stalvan Mistmantle.",h="Eine verblasste Tagebuchseite ist ein altes Pergament, das aus einer Truhe im Obergeschoss von Marshal...",kw={"dunkelhain","wald von elwynn","verblasste tagebuchseite","marshal haggard","smitts","stalvan"},ang={["faction:Alliance"]="Die Entdeckung dieser vergessenen Aufzeichnung hilft dabei, ein längst erkaltetes Mysterium zu lösen, das die Bewohner auf beiden Seiten des Flusses zwischen Elwynn und dem Dämmerwald beunruhigt hat."},sec={{t="Pergament in der Truhe",b="Zurückgelassen in einer alten Truhe, als sich der pensionierte Marshal Haggard nahe der östlichen Grenze des Walds von Elwynn niederließ, lag dieses verwitterte Pergament jahrelang unberührt. Da Haggards schwindende Sehkraft ihn daran hinderte, es zu entziffern, blieb die Seite unbeachtet, bis Abenteurer sie bargen, die der Legende von Stalvan Mistmantle nachgingen."},{t="Die Spur nach Dunkelhain",b="Obwohl Haggard den brüchigen Text nicht lesen konnte, schickte er Ermittler über den Fluss zur Scarlet Raven Tavern im Dämmerwald. Der Schankwirt, Schankwart Smitts, erkannte die markante Handschrift sofort bei der Untersuchung der Seite und verknüpfte den Tagebucheintrag direkt mit der grimmigen Saga, die die Region heimsucht."}},faq={{q="Wo ist die verblasste Tagebuchseite zu finden?",a="Die Seite wird in einer Truhe im Obergeschoss des Hauses bei Marshal Haggard entdeckt, das im östlichen Wald von Elwynn nahe der Flussgrenze zum Dämmerwald liegt.",al={"fundort der seite","wo ist die verblasste tagebuchseite","fundort der truhe"}},{q="Warum konnte Marshal Haggard die Seite nicht selbst lesen?",a="Marshal Haggard ist ein alternder Veteran, dessen Sehkraft stark nachgelassen hat, sodass er fast blind ist und die verblasste Schrift auf dem Pergament nicht entziffern kann.",al={"warum hat haggard sie nicht gelesen","marshal haggard blindheit"}},{q="Wer erkennt die Handschrift auf der Tagebuchseite?",a="Schankwart Smitts, der Schankwirt der Scarlet Raven Tavern in Dunkelhain, erkennt die Handschrift sofort, als ihm die Seite vorgelegt wird.",al={"wer kennt die handschrift","wer liest die seite"}},{q="Was beschützt die Truhe mit der Seite?",a="Das Öffnen der Truhe im Obergeschoss stört einen feindseligen Unglückseligen Geist auf, der Ermittler angreift, bevor die Seite sicher untersucht werden kann.",al={"truhengeist","was greift an der truhe an"}}},fp="20,215,22.343.0,22.315.1,38.153.0,51.165.0,51.141.0,44.127.0"}
P.entries["item:a-letter-to-grelin-whitebeard"] = {n="Ein Brief für Grelin Whitebeard",s="Diese versiegelte Korrespondenz ist an Grelin Whitebeard gerichtet, einen erfahrenen Zwerg, der in der verschneiten Wildnis des Coldridgetals stationiert ist. Aus der Berghauptstadt Ironforge gesandt, dient sie als seltene Depesche mit Neuigkeiten und Anweisungen, die den abgelegenen Außenposten erreicht.",h="Diese versiegelte Korrespondenz ist an Grelin Whitebeard gerichtet, einen erfahrenen Zwerg, der in der...",kw={"das coldridgetal","dun morogh","grelin whitebeard","ironforge","brief","postzustellung"},ang={["race:Dwarf"]="Das Überbringen von Depeschen über die eisigen Pässe von Dun Morogh ist eine grundlegende Pflicht für junge Zwergengebirgsjäger und Rekruten, die sich einen Namen machen wollen."},sec={{t="Eine Depesche aus dem Berg",b="Das Leben im verschneiten Kessel des Coldridgetals kann einsam sein, besonders für jene, die jenseits der Sicherheit von Anvilmar stationiert sind. Briefe wie dieser stellen die entscheidende Verbindung dar, die Späher und Gelehrte im Feld mit den Hallen von Ironforge verbindet. Südwärts über die Bergpfade getragen, bringt das Schreiben Nachricht aus der Hauptstadt zu Grelin Whitebeards Lager in der Wildnis."}},faq={{q="Wer ist Grelin Whitebeard?",a="Grelin Whitebeard ist ein zwergischer Späher und Forscher, der in den südöstlichen Ausläufern des Coldridgetals lagert. Er verlässt sich auf Boten aus Anvilmar, um über Angelegenheiten und Anweisungen aus Ironforge auf dem Laufenden gehalten zu werden.",al={"grelin whitebeard","wer ist grelin","empfänger"}},{q="Woher stammt dieser Brief?",a="Die Korrespondenz stammt aus der Zwergenhauptstadt Ironforge und wurde über den örtlichen Postkurier des Coldridgetals weitergeleitet, um ins Feld getragen zu werden.",al={"herkunft des briefes","wer hat den brief geschickt","woher kommt es"}},{q="Was steht in dem Brief?",a="Der genaue Inhalt ist für Grelin Whitebeard selbst versiegelt, wenngleich er beim Öffnen bemerkt, dass er lang ersehnte Kunde und Neuigkeiten aus den Hallen von Ironforge bringt.",al={"briefinhalt","was steht darin","brieftext"}}},fp="29,270,28.367.0,25.210.0,32.165.0,26.165.0"}
P.entries["item:a-mysterious-message"] = {n="Eine mysteriöse Nachricht",s="Eine mysteriöse Nachricht ist ein Schriftstück, das von einem Kurier abgefangen wurde, der durch Westfall reiste. Das unter Verschwörern adressierte Schreiben liefert der Volksmiliz konkrete Beweise, die Edwin van Cleef direkt mit der Führung der Bruderschaft der Defias in Verbindung bringen.",h="Eine mysteriöse Nachricht ist ein Schriftstück, das von einem Kurier abgefangen wurde, der durch Westfall...",kw={"blacknails","defias messenger","edwin van cleef","gryan stoutmantle","moonbrook","eine mysteriöse nachricht","westfall"},ang={["class:Rogue"]="Das abgefangene Schreiben gewährt Schurken einen Einblick in die operative Sicherheit, die Kurierwege und die verschlüsselten Botschaften der Defias-Unterwelt.",["faction:Alliance"]="Für die Champions der Allianz, die Westfall beistehen, beweist das Abfangen dieses Dokuments, dass die Unruhen auf den Feldern des Königreichs kein bloßes willkürliches Banditenteum sind, sondern ein gezielter Aufstand unter der Führung von Edwin van Cleef."},sec={{t="Abgefangene Befehle",b="Diese Nachricht, die von einem Kurier zwischen den Defias-Aktivitäten bei Moonbrook, dem Goldküstensteinbruch und dem Jangoschacht befördert wurde, bedeutet einen entscheidenden Durchbruch bei Gryan Stoutmantles Ermittlungen. Wochenlang vermutete die Volksmiliz eine organisierte Führung hinter dem Aufstand der Banditen, doch es fehlte an unumstößlichen Beweisen. Das Abfangen dieses Schreibens bestätigt zweifelsfrei, dass Edwin van Cleef die Bestrebungen der Bruderschaft in der gesamten Region befehligt und sein Netzwerk über verschlüsselte Ränge und Mittelsmänner lenkt."},{t="Geflüster über Schwarznagel",b="Neben der Bestätigung von VanCleefs übergeordneter Autorität spielt das mysteriöse Schreiben auf weitere Gestalten innerhalb der Verschwörung an, darunter einen schattenhaften Verbündeten namens „Blacknails“. Obwohl das gesamte Ausmaß ihres Untergrundnetzwerks verborgen bleibt, liefert die Entschlüsselung des Dokuments der Volksmiliz das nötige Druckmittel, um gefangene Beutelschneider umzudrehen und die wahre Festung der Bruderschaft aufzuspüren."}},faq={{q="Was enthüllt diese Nachricht der Volksmiliz?",a="Die Nachricht liefert Gryan Stoutmantle den definitiven Beweis dafür, dass Edwin van Cleef die Operationen der Bruderschaft der Defias in ganz Westfall aktiv leitet, und bestätigt damit den schlimmsten Verdacht der Miliz darüber, wer die Gesetzlosen befehligt.",al={"was steht auf der notiz","eine mysteriöse nachricht lore","was steht in der nachricht"}},{q="Wer ist Blacknails?",a="Blacknails ist ein im abgefangenen Text genannter Verbündeter oder Agent. Über seine Identität oder seinen Aufenthaltsort ist kaum etwas Weiteres dokumentiert, was ihn zu einer der schattenhaften Gestalten macht, die tief im Netzwerk der Defias operieren.",al={"wer ist blacknails","blacknails lore","defias blacknails"}},{q="Wer transportiert diese Nachricht?",a="Die Nachricht wird von einem Defias Messenger befördert, der die staubigen Straßen von Westfall zwischen Moonbrook, dem Goldküstensteinbruch und dem Jangoschacht bereist, um die Aktionen der Banditen zu koordinieren.",al={"wer hat die nachricht","wer lässt eine mysteriöse nachricht fallen","defias kurier"}},{q="Was geschieht, nachdem Gryan Stoutmantle sie gelesen hat?",a="Nachdem VanCleefs Verwicklung bestätigt ist, verlagert die Miliz ihren Schwerpunkt auf das Aufspüren des Hauptquartiers der Defias. Ein gefangener Dieb erklärt sich im Austausch für sein Leben bereit, Späher direkt zu ihrem geheimen Versteck zu führen.",al={"wie geht es weiter","reaktion von stoutmantle","nach einer mysteriösen nachricht"}}},fp="20,276,18.504.0,22.408.1,54.229.0,18.215.0,25.179.0,46.198.1"}
P.entries["item:a-simple-compass"] = {n="Ein einfacher Kompass",s="Ein einfacher Kompass ist ein altes persönliches Erinnerungsstück des Stadtarchitekten von Stormwind, Baros Alexston. Verwahrt in einer kleinen Truhe auf dem niedergebrannten Gehöft seiner Familie in Westfall, dient er als geschätztes Andenken an seine Jugend, bevor er in der Hauptstadt zu Ansehen gelangte.",h="Ein einfacher Kompass ist ein altes persönliches Erinnerungsstück des Stadtarchitekten von Stormwind, Baros...",kw={"alexston","baros","anfänge","truhe","kompass","bauernhof","stormwind","westfall"},ang={["faction:Alliance"]="Baros Alexston dabei zu helfen, sein verlorenes Andenken wiederzuerlangen, verdeutlicht den menschlichen Tribut des Defias-Aufstands und zeigt, wie selbst angesehene Persönlichkeiten in Stormwind ihre Familienheime an die Unruhen in Westfall verloren haben.",["race:Human"]="Für die Menschen des Königreichs symbolisiert der Kompass den scharfen Kontrast zwischen den sicheren, vergoldeten Höfen von Stormwind und den verlassenen, gesetzlosen Grenzlanden von Westfall."},sec={{t="Ein Andenken aus Jugendtagen",b="Lange bevor Baros Alexston zu einem Meisterarchitekten wurde, der bedeutende Bauwerke auf dem Cathedral Square leitete, wuchs er bei der Arbeit auf dem Hof seiner Familie in Westfall auf. Der einfache Kompass war sein allererstes Navigationsinstrument und weckte vermutlich sein frühes Interesse an Geometrie, technischem Zeichnen und Erkundung. Als Alexstons Bauernhof den Überfällen der Bruderschaft der Defias zum Opfer fiel und niederbrannte, blieb der Kompass inmitten der Ruinen in einer stabilen Truhe zurück – unversehrt, selbst als das umliegende Ackerland von Banditen überrannt wurde."},{t="Sentimentalitätswert",b="Baros' Vater gelang es, der Zerstörung des Gehöfts zu entkommen, doch er konnte den Besitz der Familie nicht mit in Sicherheit bringen. Während das Instrument für einen Meisterbaumeister innerhalb der steinernen Mauern von Stormwind kaum praktischen Nutzen besitzt, ist seine emotionale Bedeutung nach wie vor immens. Es Baros zurückzubringen, bietet ihm eine seltene, unversehrte Verbindung zu seinen bescheidenen Anfängen und der friedlichen ländlichen Umgebung seiner Kindheit."}},faq={{q="Was ist Ein einfacher Kompass?",a="Es ist ein bescheidener, nichtmagischer Taschenkompass, der Baros Alexston gehörte, als er ein Junge war und auf dem Hof seiner Familie in Westfall lebte.",al={"einfacher kompass","alexston kompass","baros kompass"}},{q="Wo befindet sich der Kompass?",a="Er ist in Alexstons Truhe verstaut, die in den ausgebrannten Ruinen von Alexstons Bauernhof steht, direkt westlich der Späherkuppe in Westfall.",al={"wo findet man den kompass","kompass fundort","alexstons truhe fundort"}},{q="Wer möchte diesen Kompass zurückhaben?",a="Der Kompass gehört Baros Alexston, dem Stadtarchitekten von Stormwind, den man nahe dem Rathaus auf dem Cathedral Square findet.",al={"wer braucht den kompass","kompass abgeben","wem gehört der kompass"}},{q="Warum wurde der Kompass auf dem Hof zurückgelassen?",a="Der Hof der Familie Alexston wurde von Gesetzlosen der Defias überfallen, niedergebrannt und eingenommen. Baros' Vater musste um sein Leben fliehen und konnte den schwereren Besitz nicht mitnehmen, sodass die Truhe in den Trümmern verborgen blieb.",al={"warum blieb der kompass zurück","was geschah mit dem bauernhof"}}},fp="16,281,18.508.0,17.420.0,25.133.0,29.153.0,32.128.0,44.216.0"}
P.entries["item:a-stack-of-letters"] = {n="Ein Stapel Briefe",s="Ein Stapel Briefe ist ein kleines Bündel Korrespondenz, das durch den Bergpass in das Coldridgetal gebracht wurde. Obwohl ursprünglich angenommen wurde, dass er gänzlich Talin Keeneye gehört, enthält das Bündel Mitteilungen für mehrere Späher, die in der eisigen Wildnis stationiert sind.",h="Ein Stapel Briefe ist ein kleines Bündel Korrespondenz, das durch den Bergpass in das Coldridgetal gebracht...",kw={"anvilmar","das coldridgetal","postbeförderung im coldridgetal","grelin whitebeard","ein stapel briefe","talin keeneye"},ang={["race:Dwarf"]="Für junge Gebirgsjäger, die ihre Reise im Coldridgetal beginnen, ist das Überbringen von Post zwischen verschneiten Lagern eine frühe Einführung in die rauen Straßen und die verstreuten Wächter, die Dun Morogh bewachen."},sec={{t="Durch den Pass",b="Das Erreichen abgelegener Lager in den schroffen Bergen von Dun Morogh ist zermürbende Arbeit, und Postläufer verlassen sich oft auf vorbeikommende Reisende, um Post aus Anvilmar hinauszutragen. Dieses Bündel Briefe traf durch den Pass ein, bestimmt für Späher, die tiefer im Coldridgetal stationiert sind. Während man glaubte, es sei einzig für Talin Keeneye in seinem Lager am See bestimmt, offenbart das Durchsehen des Pakets Schriftstücke für andere Außenposten im Schnee, darunter den Gebirgsjäger Grelin Whitebeard."}},faq={{q="Was befindet sich in dem Stapel Briefe?",a="Das Bündel enthält persönliche Korrespondenz und Depeschen für Zwerge, die im Coldridgetal stationiert sind. Während man glaubte, es sei gänzlich für Talin Keeneye nahe dem gefrorenen See bestimmt, offenbart das Durchsehen mindestens einen an Grelin Whitebeard adressierten Brief.",al={"was ist in den briefen","stapel briefe inhalt","für wen sind die briefe"}},{q="Wer schickt diese Briefe in das Coldridgetal?",a="Die Briefe kamen durch den Pass, der in das Coldridgetal führt, und trafen in Anvilmar ein, bevor sie einem Reisenden übergeben wurden, der bereit war, sie die Straße hinab zu befördern.",al={"woher kamen die briefe","wer schickte die briefe"}},{q="Wer erhält die Briefe?",a="Das Paket wird zuerst dem Zwergenspäher Talin Keeneye in seinem Lager am gefrorenen See direkt übergeben. Nachdem er den Stapel durchgesehen hat, entdeckt er einen Brief, der Grelin Whitebeard gehört.",al={"wer bekommt die briefe","ziel der brieflieferung"}}},fp="18,270,16.459.0,36.251.0,44.162.0,25.187.0"}
P.entries["item:a-torn-journal-page"] = {n="Eine zerrissene Tagebuchseite",s="Eine zerrissene Tagebuchseite ist ein zerfleddertes Stück Pergament, das aus einer alten Frachtkiste an den Kanälen von Stormwind geborgen wurde. Sie dient als wesentlicher handfester Hinweis auf die Identität und die finstere Vergangenheit von Stalvan Mistmantle und verbindet die düsteren Geschehnisse im Dämmerwald mit Aufzeichnungen, die im Wald von Elwynn aufbewahrt werden.",h="Eine zerrissene Tagebuchseite ist ein zerfleddertes Stück Pergament, das aus einer alten Frachtkiste an den...",kw={"kanäle","dämmerwald","die legende von stalvan","marshal haggard","versiegelte kiste","stalvan mistmantle","stormwind","zerrissene tagebuchseite"},ang={["faction:Alliance"]="Die Tagebuchseite veranschaulicht, wie ungelöste Verbrechen und vergessene Aufzeichnungen aus Stormwind und Elwynn hinausgreifen, um die gebeutelte Grenzsiedlung im Dämmerwald heimzusuchen."},sec={{t="Ein Hinweis in den Kanälen",b="Entdeckt am Boden einer versiegelten Vorratskiste an den Kanälen von Stormwind – versteckt unter alten Büchern, Familienerbstücken und einer Keramikvase –, wurde dieses Fragment inmitten vergessener persönlicher Habseligkeiten zurückgelassen. Obwohl beschädigt und abgenutzt, weist die Handschrift auf der Seite eine markante Schriftart auf, die direkt in die Vergangenheit von Stalvan Mistmantle führt und Ermittler dazu veranlasst, nach jenen zu suchen, die die Hand, die sie verfasste, noch erkennen könnten."},{t="Auf den Spuren von Mistmantle",b="Da der Text verwittert und schwer zu entziffern ist, muss die Seite zu jemandem gebracht werden, der mit den älteren Aufzeichnungen des Königreichs vertraut ist. Ihre Entdeckung führt Ermittler aus Stormwind hinaus zu Marshal Haggard, einem alternden Offizier, der im Wald von Elwynn lebt und dessen schwindendes Augenlicht sich noch immer an die charakteristische Handschrift aus einem früheren Kapitel der tragischen Mistmantle-Saga erinnert."}},faq={{q="Wo wird die zerrissene Tagebuchseite gefunden?",a="Die Seite wird in einer versiegelten Vorratskiste an den Kanälen von Stormwind gefunden, vergraben unter vergessenen Haushaltsgegenständen, Jagdtrophäen und einer alten Keramikvase.",al={"fundort zerrissene tagebuchseite","wo man die zerrissene tagebuchseite findet","versiegelte kiste stormwind"}},{q="Aus wessen Tagebuch stammt diese Seite?",a="Die Seite ist Teil der persönlichen Aufzeichnungen von Stalvan Mistmantle, einem ehemaligen Hauslehrer, dessen dunkle Vergangenheit und plötzliches Verschwinden zum Gegenstand von Ermittlungen im Dämmerwald und im Wald von Elwynn wurden.",al={"wer die tagebuchseite schrieb","verfasser der zerrissenen seite","wer stalvan ist"}},{q="Wer kann die Handschrift auf der zerrissenen Seite lesen?",a="Marshal Haggard, ein betagter, nahezu erblindeter Offizier im Ruhestand, der in der Nähe des Holzfällerlagers des Osttals im östlichen Wald von Elwynn lebt, erkennt den Schriftstil aus einer Zeit wieder, bevor sein Augenlicht schwand.",al={"zu wem man die zerrissene seite bringt","wer die zerrissene tagebuchseite liest","marshal haggard tagebuch"}},{q="Warum ist der Fund der Seite für den Dämmerwald von Bedeutung?",a="Der Stadtrat von Dunkelhain setzt die Geschichte von Stalvan Mistmantle zusammen, um die Wahrheit hinter beunruhigenden Vorkommnissen und lange vergrabenen Verbrechen aufzudecken, die mit seinem Namen verknüpft sind.",al={"warum dämmerwald sich für tagebuch interessiert","stalvan verbindung dämmerwald"}}},fp="19,302,20.446.0,28.370.1,37.176.0,38.191.0,46.204.0,45.175.0"}
P.entries["item:abercrombie-s-crate"] = {n="Calvinius' Kiste",s="Calvinius' Kiste ist ein verloren gegangener Behälter mit empfindlichen Werkzeugen und gesammelten Kräutern, der dem exzentrischen Einsiedler Calvinius gehört. Sie liegt verlassen nahe dem Eingang des Ogerhorts Vul'Gol im südlichen Dämmerwald, nachdem der alte Mann von marodierenden Ogern vertrieben wurde.",h="Calvinius' Kiste ist ein verloren gegangener Behälter mit empfindlichen Werkzeugen und gesammelten Kräutern...",kw={"calvinius","calvinius' kiste","dämmerwald","ogerhort","ogerdiebe","vul'gol"},ang={["faction:Alliance"]="Sich direkt in das Herz des Ogerhorts Vul'Gol zu wagen, um verlorene Güter zu bergen, verdeutlicht die wachsende Monsterbedrohung, die den südlichen Dämmerwald heimsucht.",["profession:Herbalism"]="Calvinius begibt sich vordergründig in die dunkelsten Gefilde des Waldes, um seltene Flora zu suchen, was die Bergung seines Botanikersets zu einer vertrauten Aufgabe für einheimische Kräuterkundige macht."},sec={{t="An die Oger verloren",b="Als Calvinius weit von seiner Hütte im westlichen Dämmerwald umherstreifte, um Pflanzen zu sammeln, kreuzte er den Weg einer feindseligen Ogerbande. Auf der Flucht um sein Leben ließ der alte Einsiedler seine Kiste mit kostbaren Instrumenten und geernteten Pflanzen fallen. Die Oger schleppten seine Habseligkeiten zurück in ihre Festung im Ogerhort Vul'Gol und ließen die schwere Truhe achtlos nahe ihrem Höhleneingang stehen."},{t="Merkwürdiger Inhalt",b="Obwohl Calvinius behauptet, die Kiste enthalte bloß harmlose Werkzeuge und gesammelte Pflanzen, deutet seine ekstatische, verdächtige Reaktion bei ihrer Wiederbeschaffung auf etwas weitaus Dunkleres hin. In einem Versprecher dankt der Einsiedler beinahe dem 'Nek-', bevor er innehält, was beunruhigende Fragen darüber aufwirft, welchem Handwerk diese gestohlenen Werkzeuge eigentlich dienen sollten."}},faq={{q="Wo befindet sich die Kiste?",a="Die Kiste liegt verlassen im Freien direkt neben dem Höhleneingang am Ogerhort Vul'Gol, einem von Ogern bevölkerten Lager in den südlichen Hügeln des Dämmerwalds.",al={"fundort der kiste","wo ist calvinius' kiste","vul'gol kiste"}},{q="Warum hat Calvinius sie verloren?",a="Calvinius sammelte weit von seinem Zuhause entfernt Kräuter, als ihn eine Gruppe von Ogern überfiel. Unbewaffnet und verängstigt floh er zu Fuß und ließ seine Vorräte zurück, die die Oger in ihren Unterschlupf trugen.",al={"wie bekamen die oger die kiste","warum ist die kiste bei den ogern"}},{q="Was befindet sich in der Kiste?",a="Calvinius beschreibt den Inhalt als seltene Kräuter und spezialisierte Erntewerkzeuge. Seine seltsame Begeisterung und sein Versprecher bei Erhalt der Kiste deuten jedoch darauf hin, dass sie Instrumente enthalten könnte, die weitaus unheimlicher sind als gewöhnliche Gartenscheren.",al={"inhalt der kiste","was hat calvinius verloren"}},{q="Warum dankt Calvinius beinahe 'dem Nek-'?",a="Als er seine Kiste zurückerhält, platzt Calvinius mit 'Dem Nek-... sei Dank!' heraus, bevor er sich hastig korrigiert, um dem Abenteurer zu danken. Dies deutet stark darauf hin, dass seine Loyalität oder Dankbarkeit eher der Nekromantie als dem Licht gilt.",al={"calvinius nek versprecher","dem nek sei dank bedeutung"}}},fp="19,261,17.387.0,17.355.1,27.151.0,28.200.0,25.239.1,45.223.1"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="Admiral Proudmoores Befehle",s="Admiral Proudmoores Befehle sind schriftliche Schlachtpläne, die von den Streitkräften von Kul Tiras erbeutet wurden, welche sich entlang der Küste von Durotar verschanzen. Verfasst vor der Niederlage des Großadmirals bei Theramore, umreißen die Dokumente anhaltende militärische Strategien, die die junge Heimat der Orcs weiterhin bedrohen.",h="Admiral Proudmoores Befehle sind schriftliche Schlachtpläne, die von den Streitkräften von Kul Tiras erbeutet...",kw={"benedict","durotar","kul tiras","befehle","orgrimmar","proudmoore","tiragarde","vol'jin"},ang={["faction:Horde"]="Diese Dokumente geben jenen in der Horde recht, die argumentierten, dass Waffenstillstände mit Menschen niemals von Dauer sein würden, und beweisen, dass die Streitkräfte von Kul Tiras von dem Moment ihrer Landung an einen Vernichtungskrieg führen wollten.",["race:Troll"]="Für die Darkspear-Trolle werden diese Befehle direkt an ihren Häuptling Vol'jin übergeben, was seinen langjährigen Rat an Thrall bestätigt, dass die menschliche Präsenz entlang der Küste eine unmittelbare Gefahr darstellt."},sec={{t="Ein Vermächtnis des Hasses",b="Selbst nach dem Tod von Großadmiral Daelin Proudmoore bei Theramore weigern sich seine Expeditionstruppen nachzugeben. Diese taktischen Direktiven, die aus der Garnison von Lieutenant Benedict in Burg Tiragarde geborgen wurden, beschreiben langfristige Manöver und Befestigungen, die darauf ausgelegt sind, die Horde zu schwächen. Die Befehle beweisen, dass die Offensive des Großadmirals in Durotar kein überstürzter Raubzug war, sondern ein organisierter Feldzug, der so strukturiert war, dass er weit über sein eigenes Ableben hinaus andauern sollte. Für die Horde bieten die geborgenen Dokumente wichtige Einblicke in die Operationen von Kul Tiras und mögliche Verstärkungen, die ihre Grenzen bedrohen."},{t="Überbringung an Grommash Hold",b="Da sie die in den Plänen dargelegte strategische Gefahr erkennen, schicken Kundschafter der Horde die sichergestellten Papiere direkt zu Grommash Hold in Orgrimmar. Übergeben an Häuptling Vol'jin, der Kriegshäuptling Thrall als Berater dient, bestätigen die Befehle den anhaltenden Verdacht des Anführers der Darkspear, dass die menschliche Aggression eine aktive Gefahr bleibt. Die Informationen drängen die Führung der Horde dazu, sich auf weitere Übergriffe entlang der Küste vorzubereiten."}},faq={{q="Was sind Admiral Proudmoores Befehle?",a="Es sind militärische Direktiven, die von Großadmiral Daelin Proudmoore vor seinem Fall bei Theramore verfasst wurden. Sie weisen die verbliebenen Soldaten von Kul Tiras in Durotar an, Küstenstützpunkte zu befestigen und Krieg gegen die Horde zu führen.",al={"proudmoores befehle","was sind die befehle","admiral proudmoores befehle gegenstand"}},{q="Wo wurden diese Befehle geborgen?",a="Die Befehle werden in Durotar während des anhaltenden Kampfes gegen die an Burg Tiragarde stationierten Reste von Kul Tiras nahe der Südostküste sichergestellt.",al={"wo finde ich die befehle","befehle fundort","wer droppt die befehle"}},{q="Wer muss diese Befehle sehen?",a="Sie werden zu dem Häuptling der Darkspear, Vol'jin, gebracht, der sich in Grommash Hold im Valley of Wisdom von Orgrimmar an der Seite von Kriegshäuptling Thrall aufhält.",al={"bei wem abgeben","wer will die befehle","befehle abgeben"}},{q="Warum kämpfen Soldaten von Kul Tiras immer noch in Durotar?",a="Obwohl Admiral Proudmoore in der Schlacht fiel, blieben seine Untergebenen wie Lieutenant Benedict seiner Mission zur Auslöschung der Orcs treu ergeben. Die Befehle lieferten vorausgeplante Strategien für die Garnison, um Durotar selbst ohne die direkte Aufsicht des Großadmirals weiterhin zu bedrängen.",al={"warum sind menschen in durotar","warum burg tiragarde feindselig","daelin tot warum kampf"}}},fp="27,299,18.577.0,25.419.1,37.219.0,34.150.0,30.144.0,53.286.0"}
P.entries["item:ados-fragment"] = {n="Ados-Fragment",s="Das Ados-Fragment ist ein beschriftetes Steinstück, das aus Whelgars Ausgrabungsstätte im Sumpfland geborgen wurde. Zusammen mit drei weiteren Bruchstücken bildet es den Goazstein, ein uraltes Relikt mit rätselhaften Inschriften der Titanen.",h="Das Ados-Fragment ist ein beschriftetes Steinstück, das aus Whelgars Ausgrabungsstätte im Sumpfland geborgen...",kw={"ados-fragment","ausgrabung","goazstein","alte götter","relikt","titanen","sumpfland","whelgar"},ang={["race:Dwarf"]="Für die Forscherliga ist die Bergung von Titanenrelikten wie dem Ados-Fragment von entscheidender Bedeutung, um die wahren Ursprünge des Zwergenvolkes und ihrer uralten Schöpfer aufzudecken."},sec={{t="Ein Teil des Goazsteins",b="In den schlammigen Gräben von Whelgars Ausgrabungsstätte freigelegt, ist das Ados-Fragment eines von vier fehlenden Stücken, die zur Rekonstruktion des Goazsteins benötigt werden. Bevor Raptoren die Ausgrabungsstätte überrannten, begann Ausgrabungsleiter Whelgar mit der Übersetzung der Haupttafel, musste jedoch feststellen, dass die Inschriften an entscheidenden Stellen abbrachen. Die verstreuten Teile – namens Ados, Modr, Golm und Neru – gingen in den Ruinen verloren, verborgen in uralten Behältern und Erdhügeln inmitten lauernder Bestien."},{t="Die Titanenschrift",b="Das Zusammensetzen des Ados-Fragments mit den anderen drei Teilen ermöglicht es Ausgrabungsleiter Whelgar, die vollständige, in den Goazstein gemeißelte Titanenschrift zu entziffern. Der zusammengefügte Text erwähnt einen großen göttlichen Plan und eine unheilvolle Prophezeiung und offenbart schließlich eine unheilvolle Verkündigung: „Alte Götter... Angekettet unter dem Land.“ Diese Enthüllung deutet darauf hin, dass die Titanen in vergangenen Zeitaltern urzeitliche Wesenheiten unter Azeroth eingekerkert haben."}},faq={{q="Was ist das Ados-Fragment?",a="Es ist ein abgebrochener Teil einer uralten Steintafel namens Goazstein, die in Whelgars Ausgrabungsstätte im Sumpfland entdeckt wurde. Es enthält eingemeißelte Schriftzeichen der weltformenden Titanen.",al={"ados-fragment","was ist ados","goazstein fragment ados"}},{q="Wo ist das Fragment zu finden?",a="Es ist auf der Ausgrabungsstätte im südlichen Sumpfland vergraben, meist versteckt in uralten Relikten oder lockeren Erdhaufen, umgeben von territorialen Raptoren.",al={"wo ist das ados-fragment","ados fundort","wie findet man ados"}},{q="Was besagt das Fragment?",a="Für sich allein genommen ist das Fragment unvollständig. Zusammen mit den Fragmenten Modr, Golm und Neru beschreibt die Tafel einen göttlichen Plan, eine unheilvolle Prophezeiung und erwähnt Alte Götter, die unter dem Land angekettet sind.",al={"ados-fragment text","was steht auf ados","goazstein übersetzung"}},{q="Wer möchte dieses Fragment?",a="Ausgrabungsleiter Whelgar, ein Zwerg der Forscherliga, der die verwüstete Ausgrabungsstätte beaufsichtigt, sucht danach, um die Übersetzung des Goazsteins zu vollenden.",al={"wer braucht das ados-fragment","ados-fragment abgeben","whelgar ados"}}},fp="13,228,25.475.0,16.417.1,26.177.0,28.158.0,27.204.1,24.132.0"}
P.entries["item:agamand-family-axe"] = {n="Axt der Familie Agamand",s="Die Axt der Familie Agamand ist ein uraltes Erbstück, das in der Gruft der Familie Agamand im nördlichen Tirisfal aufbewahrt wird. Einst ein kriegerisches Symbol der wohlhabenden Mühleneigner-Dynastie, wird sie von Coleman Farthing gesucht, um der untoten Familie ihre verbliebene Würde zu nehmen.",h="Die Axt der Familie Agamand ist ein uraltes Erbstück, das in der Gruft der Familie Agamand im nördlichen...",kw={"agamand","gruft der agamands","axt der familie agamand","agamands mühlen","coleman farthing","erbstück","tirisfal"},ang={["class:Warrior"]="Die in der Gruft aufbewahrten Erbstückwaffen zeigen, dass das Geschlecht der Agamands neben seinem Reichtum und seinen Getreidespeichern auch kriegerische Traditionen pflegte.",["race:Undead"]="Für die Verlassenen ist die Plünderung der Agamand-Erbstücke eine tief empfundene Abrechnung mit der einstigen Aristokratie Lordaerons, die der Seuche genauso leicht anheimfiel."},sec={{t="Eine Waffe der Agamands",b="Vor dem Dritten Krieg herrschte die Agamand-Dynastie als wohlhabende Grundbesitzer über die nördlichen Hügel von Tirisfal und unterhielt ausgedehnte Mühlen sowie eine private Familiengruft. Die Axt der Familie Agamand ruhte unter den Waffen der Ahnen, die an der Seite verstorbener Patriarchen und Krieger beigesetzt worden waren. Sie blieb auf unterirdischen Waffenständern unversehrt, selbst als die Geißel das Anwesen überrannte und seine Bewohner abschlachtete."},{t="Gehässige Vergeltung",b="Als die Geißel die gefallenen Agamands als geistlose Knechte des Lichkönigs auferstehen ließ, überlebte ihr ehemaliger Diener Coleman Farthing – im Untod – mit bitterem Hass auf seine alten Herren. Farthing gibt der Familie die Schuld an seinem eigenen Untergang und beauftragt Wanderer der Verlassenen, die Gruft zu betreten, die Waffenständer von Axt, Schwert, Streitkolben und Dolch zu befreien und die letzten Spuren des Agamand-Erbes zu tilgen."}},faq={{q="Wo befindet sich die Axt der Familie Agamand?",a="Die Axt ruht auf einem Waffenständer in der Gruft der Familie Agamand, die am nördlichen Rand von Agamands Mühlen im nördlichen Tirisfal liegt.",al={"fundort der axt","wo ist die axt","ort der agamand-axt"}},{q="Wer will die Axt der Familie Agamand?",a="Coleman Farthing, ein in Brill ansässiger Verlassener, sucht die Waffe zusammen mit dem Dolch, dem Streitkolben und dem Schwert der Familie, um seinen ehemaligen Herren ihre Ehre zu rauben.",al={"wer braucht die axt","coleman farthing quest","wer will agamand-erbstücke"}},{q="Warum hasst Coleman Farthing die Familie Agamand?",a="Die Agamands beschäftigten Farthing zu Lebzeiten und waren seinen Angaben zufolge während der Invasion der Geißel direkt für seinen Tod verantwortlich. Er rächt sich, indem er ihre Gruft plündert, während sie als untote Diener über das Anwesen streifen.",al={"warum will farthing erbstücke","hintergrundgeschichte coleman farthing","farthings groll"}},{q="Ist die Axt der Familie Agamand eine benutzbare Waffe?",a="Nein. Die Axt ist ein Relikt der Ahnen, das lediglich als Questziel geborgen wird, um die Schändung der Familiengruft zu beweisen.",al={"kann ich die axt anlegen","axt werte"}}},fp="18,264,24.391.0,20.398.0,40.143.0,33.155.0,50.211.0,42.119.0"}
P.entries["item:agamand-family-dagger"] = {n="Dolch der Familie Agamand",s="Der Dolch der Familie Agamand ist ein ererbtes Erbstück der gefallenen Agamand-Dynastie und ruht auf Waffenständern in ihrer uralten Gruft im nördlichen Tirisfal. Coleman Farthing trachtet nach dieser Klinge zusammen mit dem Rest ihres Familienarsenals, um seinen einstigen Herren ihr verbliebenes Erbe und ihre Ehre zu entreißen.",h="Der Dolch der Familie Agamand ist ein ererbtes Erbstück der gefallenen Agamand-Dynastie und ruht auf...",kw={"agamand","agamands mühlen","coleman farthing","gruft","dolch","erbstück","geißel","tirisfal"},ang={["class:Rogue"]="Sich an den auferstandenen Untoten in der Gruft vorbeizuschleichen, um kostbare Familienklingen von Waffenständern zu stehlen, verkörpert den klassischen Unterwelt-Einbruch, der zu einem Akt kalter Rache wird.",["race:Undead"]="Die Agamand-Erbstücke spiegeln die bittere Kluft zwischen den überlebenden Verlassenen von Lordaeron und ihren einstigen Meistern wider, die der willenlosen Knechtschaft unter der Geißel anheimfielen."},sec={{t="Ein Erbe in der Gruft",b="Vor dem Dritten Krieg besaß die Familie Agamand weitläufige Ländereien und Getreidemühlen auf den sanften Wiesen von Tirisfal. Wie der Rest der Waffen ihrer Ahnenreihe überstand der Dolch der Familie Agamand die von der Geißel angerichteten Verheerungen, eingeschlossen in der Familiengruft nördlich von Agamands Mühlen. Beschützt von den ruhelosen, untoten Überresten des Gesindes und willenlosen Dienern des Lichkönigs, verkörpert der Dolch das Ansehen und kriegerische Erbe, das die Familie einst über ihre Diener und Pächter erhob."},{t="Eine hasserfüllte Beschlagnahme",b="Für Coleman Farthing, einen in Brill weilenden Verlassenen, der im Dienst der Agamands starb, verkörpert die Klinge bitteren Groll statt edler Abstammung. Farthing macht die Familie unmittelbar für seinen Tod verantwortlich und schickt Abenteurer in die Gruft der Familie Agamand, um den Dolch zusammen mit dem Familienschwert, der Axt und dem Streitkolben zu bergen. Indem er ihrem Grab diese uralten Waffen entreißt, will Farthing den nun der Geißel verfallenen Patriarchen die letzten Reste ihrer Würde rauben und sicherstellen, dass das Andenken an die Agamands vollends ausgelöscht wird."}},faq={{q="Was ist der Dolch der Familie Agamand?",a="Er ist eine Ahnenwaffe der wohlhabenden Familie Agamand aus Tirisfal. Er wurde zusammen mit anderen Waffen in der Familiengruft beigesetzt, die seither unter die Kontrolle der Geißel gefallen ist.",al={"agamand dolch","was ist der agamand dolch","familien dolch tirisfal"}},{q="Wo ist der Dolch der Familie Agamand zu finden?",a="Er liegt auf einem Agamand-Waffenständer tief in der Gruft der Familie Agamand, die am nördlichen Ende von Agamands Mühlen in Tirisfal liegt.",al={"wo findet man den agamand dolch","agamand dolch standort","dolch waffenständer fundort"}},{q="Warum will Coleman Farthing diesen Dolch?",a="Coleman Farthing stand zu Lebzeiten im Dienst der Agamands und gibt ihnen die Schuld an seinem Untergang. Er verlangt den Dolch und andere Erbstücke, um seinen ehemaligen Meistern die Ehre zu nehmen und ihren Ruin zu vollenden.",al={"warum will farthing den dolch","farthing agamand quest","warum agamand gruft ausrauben"}},{q="Welche anderen Waffen gehören zu diesem Erbstückset?",a="Zusammen mit dem Dolch umfasst das Erbstückset das Schwert der Familie Agamand, die Axt der Familie Agamand und den Streitkolben der Familie Agamand, die allesamt auf Waffenständern in der Familiengruft verteilt sind.",al={"weitere agamand erbstücke","agamand waffenliste","was ist noch in der gruft"}}},fp="21,305,21.520.0,22.524.0,34.194.0,41.139.0,43.193.0,47.181.0"}
P.entries["item:agamand-family-mace"] = {n="Streitkolben der Familie Agamand",s="Der Streitkolben der Familie Agamand ist ein uraltes Erbstück, das in der Gruft der Familie Agamand im nördlichen Tirisfal aufbewahrt wird. Einst ein Symbol des Stolzes einer wohlhabenden Dynastie des nördlichen Lordaeron, ist er nun das Ziel boshafter Vergeltung geworden, nach dem ihr ehemaliger Diener Coleman Farthing trachtet.",h="Der Streitkolben der Familie Agamand ist ein uraltes Erbstück, das in der Gruft der Familie Agamand im...",kw={"gruft der familie agamand","streitkolben der familie agamand","agamand-erbstücke","agamands mühlen","coleman farthing","tirisfal"},ang={["race:Undead"]="Die Entweihung der Grüfte der Agamands veranschaulicht, wie anhaltender irdischer Groll und Bitterkeit die Verlassenen oft dazu treiben, alte Rechnungen aus dem Leben zu begleichen."},sec={{t="Ein Erbe in Trümmern",b="Vor dem Dritten Krieg besaß die Familie Agamand weitläufiges Ackerland und Windmühlen in den nördlichen Ausläufern von Tirisfal. Wie der Rest der regionalen Aristokratie fiel auch sie der Seuche des Untodes zum Opfer. Die Agamands wurden als geistlose Knechte im Dienste des Lichkönigs wiedererweckt und streifen nun über ihr zerstörtes Anwesen, während ihre uralten Familienschätze tief in der Familiengruft eingeschlossen blieben. Der Streitkolben der Familie Agamand lagert unter diesen Waffen – ein Sinnbild einer vergessenen Abstammungslinie, die nun zu schlurfender Geißel herabgesunken ist."},{t="Die Rache eines Dieners",b="Der Streitkolben ist eines von vier kriegerischen Erbstücken, auf die es Coleman Farthing abgesehen hat – ein ehemaliger Angestellter, der der Familie die Schuld an seinem Untergang während des Falls von Lordaeron gibt. Als Verlassener wiederauferstanden, trachtet Farthing danach, den geistlosen Agamands jeden noch verbliebenen Hauch von Würde und Ehre zu rauben. Indem er den Streitkolben zusammen mit dem Ahnenschwert, der Axt und dem Dolch beschaffen lässt, will Farthing sicherstellen, dass das Andenken und der Stolz seiner früheren Herren für immer aus den Landen getilgt werden, die sie einst beherrschten."}},faq={{q="Wo befindet sich der Streitkolben der Familie Agamand?",a="Der Streitkolben lagert auf einem Waffenständer in der Gruft der Familie Agamand, die sich am äußersten nördlichen Ende von Agamands Mühlen in Tirisfal befindet.",al={"wo ist der streitkolben","agamand streitkolben fundort","agamand streitkolben finden"}},{q="Wer verlangt nach dem Streitkolben der Familie Agamand?",a="Coleman Farthing, ein Verlassener mit Wohnsitz in Brill, fordert den Streitkolben zusammen mit den anderen Familienerbstücken ein, um eine alte Rechnung mit seinen früheren Herren zu begleichen.",al={"wer braucht den streitkolben","wer nimmt den agamand streitkolben","coleman farthing erbstueck"}},{q="Warum möchte Coleman Farthing, dass die Erbstücke gestohlen werden?",a="Farthing diente den Agamands zu Lebzeiten und gibt ihnen die direkte Schuld an seinem Tod. Ihren Familienehren den letzten Stoß zu versetzen, indem er ihre geschätzten Waffen aus ihrer Gruft stiehlt, ist seine Art der Vergeltung.",al={"warum erbstuecke stehlen","coleman farthing motiv","warum hass auf die agamands"}},{q="Was geschah mit der Familie Agamand?",a="Die Familie Agamand herrschte über die blühenden Agamands Mühlen im nördlichen Lordaeron, bis die Seuche sie heimsuchte. Nun durchstreifen ihre wiedererweckten Leichen das Anwesen und die Grüfte als geistlose Knechte der Geißel.",al={"wer waren die agamands","was geschah mit den agamands","agamand geschichte"}}},fp="19,284,16.528.0,21.482.1,41.137.0,34.153.0,52.186.0,36.205.0"}
P.entries["item:agamand-family-sword"] = {n="Schwert der Familie Agamand",s="Das Schwert der Familie Agamand ist eine angelaufene Klinge der Ahnen, die in der Gruft der Familie Agamand im nördlichen Tirisfal aufbewahrt wird. Einst ein stolzes Symbol der wohlhabenden Mühlenbesitzerdynastie, wird es von dem Verlassenen Coleman Farthing gesucht, um die letzten Spuren des Erbes seiner früheren Herren zu tilgen.",h="Das Schwert der Familie Agamand ist eine angelaufene Klinge der Ahnen, die in der Gruft der Familie Agamand...",kw={"agamand","gruft","farthing","erbstück","mühlen","geißel","schwert","tirisfal"},ang={["class:Warrior"]="Einst ein glänzendes Sinnbild der Aristokratie von Lordaeron, liegt die Klinge nun vernachlässigt in einem unheiligen Grab – ein Relikt zugrunde gegangenen kriegerischen Stolzes.",["race:Undead"]="Für die Verlassenen bedeutet die Rückforderung von Artefakten des einstigen Adels von Tirisfal eine Abrechnung mit einer lebendigen Vergangenheit, die sie nicht zu beschützen vermochte."},sec={{t="Ein Erbe im Grab",b="Vor dem Dritten Krieg verfügte die Agamand-Dynastie über immensen Reichtum und Einfluss auf den weiten Mühlenländereien im nördlichen Tirisfal. Als die Geißel über Lordaeron hinwegfegte, fand die Familie ein grausames Ende und ihre Körper wurden zu geistlosen Knechten des Lichkönigs erweckt. Ihre Ahnenwaffen, darunter das zeremonielle Familienschwert, wurden in der Gruft der Familie Agamand am nördlichen Rand der Mühlen weggeschlossen. Diese Klingen von ihren Waffenständern zu reißen, dient nicht bloß der Plünderung, sondern als gezielter Akt, um jegliche verbliebene Erinnerung und den adligen Stand des gefallenen Hauses zu brechen."},{t="Vergeltung aus dem Jenseits",b="Das Schwert wird von Coleman Farthing begehrt, einem in Brill ansässigen Verlassenen, der zu Lebzeiten für die Agamands arbeitete. Farthing hegt einen bitteren Groll gegen seine einstigen Herren und gibt ihren Entscheidungen die Schuld an seinem Tod während des Untergangs des Königreichs. Indem er Abenteurer aussendet, um das Schwert zusammen mit der Axt, dem Dolch und dem Streitkolben der Dynastie an sich zu bringen, trachtet Farthing danach, den schlurfenden Agamands ihr letztes Quäntchen Ehre zu rauben und sicherzustellen, dass die Würde ihrer Blutlinie vollends erlischt."}},faq={{q="Was ist das Schwert der Familie Agamand?",a="Es ist eine Ahnenwaffe der Agamands, einer prominenten Adelsfamilie, die vor dem Fall von Lordaeron die gewaltigen Getreidemühlen im nördlichen Tirisfal betrieb.",al={"lore zum schwert der agamands","was ist das schwert der familie agamand"}},{q="Wo befindet sich das Schwert?",a="Das Schwert ruht auf einem Waffenständer in der Gruft der Familie Agamand am nördlichen Rand von Agamands Mühlen in Tirisfal, verteidigt von Knechten der Geißel und auferstandenen Mitgliedern der Agamand-Blutlinie.",al={"wo ist das agamand-schwert","fundort schwert agamand"}},{q="Warum will Coleman Farthing dieses Schwert?",a="Coleman Farthing stand zu Lebzeiten im Dienst der Familie Agamand und gibt ihr die Schuld an seinem vorzeitigen Tod. Er trachtet nach den Erbwaffen der Familie, um ihnen ihre verbliebene Ehre zu nehmen und das Andenken an ihre Dynastie auszulöschen.",al={"wer will das schwert","warum will farthing erbstücke"}},{q="Was geschah mit der Familie Agamand?",a="Die Agamands wurden während der Invasion der Geißel in Lordaeron niedergemetzelt. Anders als die freisinnigen Verlassenen bleiben die verstorbenen Familienmitglieder in geistloser Knechtschaft an den Lichkönig gebunden und suchen ihr angestammtes Anwesen sowie die Gruft heim.",al={"wer sind die agamands","geschichte von agamands mühlen"}}},fp="20,282,20.584.0,31.472.1,33.175.0,27.203.0,42.213.0,36.230.0"}
P.entries["item:ahanu-s-leather-goods"] = {n="Ahanus Lederwaren",s="Ahanus Lederwaren ist eine gebündelte Lieferung fertiger Lederrüstungen und Vorräte, die auf den Hochebenen von Thunder Bluff hergestellt wurden. Das vom Lederverarbeiter Ahanu vorbereitete Paket ist für das Crossroads im Brachland bestimmt, um umherziehende Jäger und Abenteurer zu versorgen.",h="Ahanus Lederwaren ist eine gebündelte Lieferung fertiger Lederrüstungen und Vorräte, die auf den Hochebenen...",kw={"ahanu","crossroads","devrak","jahan hawkwing","lederwaren","tal","thunder bluff","windreiter"},ang={["race:Tauren"]="Die Lieferung veranschaulicht das wachsende Handelsnetz, das die angestammte Heimat Mulgore mit den weiteren Gebieten der Horde im Brachland verbindet."},sec={{t="Handel über die Hochebenen",b="Die Nachschublinien der Horde hängen vom praktischen Handel zwischen etablierten Festungen und Außenposten an der Grenze ab. In Thunder Bluff verarbeitet der Handwerker Ahanu rohe Felle zu fertiger Kleidung und Ausrüstung und bereitet diese Lieferung speziell für den Handel jenseits von Mulgore vor. Das Bündel ist für Jahan Hawkwing bestimmt, einen Händler, der im geschäftigen Herzen des Brachlands bei Crossroads tätig ist. Da das Reisen über Land durch die Ebenen langsam ist, führt der Transport des Bündels Boten an das von den Tauren unterhaltene Luftkuriernetzwerk heran, das auf Tal und Devraks ausgebildete Windreiter setzt, um Waren rasch über weite Strecken zu befördern."}},faq={{q="Was befindet sich in Ahanus Lederwaren?",a="Das Paket enthält fertige Lederwaren, die von Ahanu in Thunder Bluff aus rohen Fellen hergestellt wurden. Sie sind als praktische Rüstung und Ausrüstung gedacht, die bereit für den Verkauf an Reisende ist.",al={"was sind die lederwaren","ahanu paket inhalt","was ist im bündel"}},{q="Wer erhält dieses Paket?",a="Das Paket wird an Jahan Hawkwing bei Crossroads geliefert. Er verkauft fertige Waren an den Zustrom von Jägern, Kriegern und Abenteurern, die durch das zentrale Brachland ziehen.",al={"wer bekommt die lederwaren","wohin geht es","jahan lederlieferung"}},{q="Warum wird dieses Paket per Windreiter geflogen?",a="Schwere Handelsgüter zu Fuß über die Aufzüge und durch das Brachland zu tragen, kostet Zeit. Ahanu schickt Kuriere zu Thunder Bluffs Windreitermeister Tal, um zu demonstrieren, wie geflügelte Kuriere Fracht rasch zu fernen Posten wie Crossroads befördern können.",al={"warum das paket fliegen","windreiter lieferung thunder bluff","flugmeister paket"}}},fp="21,262,22.627.0,37.172.0,25.174.0,41.251.0"}
P.entries["item:alaric-s-remains"] = {n="Alarics sterbliche Überreste",s="Alarics sterbliche Überreste sind die geborgenen Knochen einer Person, die einst in einem flachen Grab im Silberwald beigesetzt wurde. Sein verweilender Geist bittet Reisende, das, was von ihm übrig ist, an den Gnollen der Moderfelle vorbei in die Türme von Burg Fenris zu tragen.",h="Alarics sterbliche Überreste sind die geborgenen Knochen einer Person, die einst in einem flachen Grab im...",kw={"alaric","alarics sterbliche überreste","burg fenris","moderfelle","flaches grab","silberwald","die versteckte nische","thule rabenklaue"},ang={["class:Mage"]="Das verborgene Versteck, das Alaric enthüllt, enthält Relikte, die mit Thule Rabenklaue und den in Dalaran ausgebildeten Arkanisten in Verbindung stehen, die einst in Burg Fenris studierten und Intrigen schmiedeten.",["race:Undead"]="Verlassene Reisende empfinden oft Mitgefühl für Geister, deren sterbliche Ruhe gestört wurde, wenngleich Alaric eher friedliche Abgeschiedenheit als den Dienst unter der Dunklen Fürstin sucht."},sec={{t="Eine letzte Bitte",b="Die aus einem unscheinbaren flachen Grab im Silberwald ausgegrabenen Überreste gehören Alaric, einem ehemaligen Bewohner der Insel Fenris. Anstatt in einer ungeschützten Grube zu verweilen, sehnt sich sein Geist nach dem Ort, den er zu Lebzeiten schätzte. Er bittet jeden, der seine Knochen ausgräbt, seine schlecht sitzenden Stiefel zurückzulassen und seine skelettierten Überreste direkt in die Burg zu bringen, um fernab der auf dem Festland herumstreunenden Aasfresser eine friedliche Zuflucht zu finden."},{t="Die Nische in der Burg",b="Alaric führt den Träger zum südwestlichen Turm von Burg Fenris, vorbei an den verseuchten unteren Bereichen in eine ruhige Kammer. Versteckt hinter einem staubigen Regal liegt eine verborgene Nische, die ein Artefakt enthält, das einst von Thule Rabenklaue und seinen Magierkollegen geschätzt wurde. Als Gegenleistung dafür, dass man ihm eine ungestörte Ruhestätte gewährt, die vor den unersättlichen Gnollen der Moderfelle verschlossen ist, überlässt Alaric denjenigen, die seine Knochen nach Hause trugen, den verborgenen Schmuck."}},faq={{q="Wer war Alaric?",a="Alaric war vor ihrem Ruin ein Bewohner von Burg Fenris und verbrachte das, was er als die schönsten Tage seines Lebens betrachtete, in ihren Hallen. Nach seinem Tod wurde er eilig in einem flachen Grab im Silberwald verscharrt, bis sein Geist einen Vorbeigehenden dazu anleitete, seine Knochen nach Hause zu tragen.",al={"wer ist alaric","alaric lore","wer war dieser typ"}},{q="Wohin sollen Alarics sterbliche Überreste gebracht werden?",a="Seine sterblichen Überreste sollen in eine verborgene Nische hinter einem staubigen Regal im südwestlichen Turm von Burg Fenris auf der Insel Fenris gelegt werden.",al={"wohin alaric bringen","staubiges regal ort","wo ist die nische"}},{q="Warum möchte Alaric, dass seine Überreste hinter einem Regal versiegelt werden?",a="Burg Fenris brachte ihm im Leben großen Trost, und er möchte lieber in ihren Steinmauern als in einem Erdloch ruhen. Das dichte Verschließen der verborgenen Nische schützt sein Skelett zudem davor, von den in der Burg herumstreifenden Gnollen der Moderfelle verschlungen oder geschändet zu werden.",al={"warum burg fenris","warum die nische","warum den koerper verstecken"}},{q="Warum sagte er, man solle seine Stiefel zurücklassen?",a="Als er die Bergung seiner Knochen aus dem flachen Grab anleitete, bemerkte Alaric beiläufig, dass ihm seine Stiefel zu Lebzeiten ohnehin nie gepasst hätten, und ließ sie als nutzlosen Ballast zurück.",al={"stiefel zuruecklassen","alarics stiefel","stiefel passten nie"}},{q="Was befindet sich außer einer Ruhestätte noch in der verborgenen Nische?",a="Die geheime Nische birgt einen Gegenstand, der einst von Thule Rabenklaue und seinen früheren Gefährten geschätzt wurde, zusammen mit magischen Besitztümern, die Alaric bereitwillig jedem vermacht, der willens ist, seine sterblichen Überreste zur Ruhe zu betten.",al={"schatz in verborgener nische","was ist hinter dem regal","thules gegenstand"}}},fp="16,237,15.426.0,22.424.1,15.280.0,42.146.0,55.256.0,41.171.0,57.194.0"}
P.entries["item:alien-egg"] = {n="Fremdartiges Ei",s="Das Fremdartige Ei ist ein ungewöhnliches und geheimnisvolles Gelege, das von einheimischen Windnattern in den Schluchten von Tausend Nadeln bewacht wird. Trotz seiner unvertrauten Erscheinung verteidigen die heimischen Nattern das Ei erbittert, als wäre es ihr eigenes. Seine Anwesenheit hat die Neugier und Sorge der Taurenspäher geweckt, die auf dem Freiwindposten stationiert sind.",h="Das Fremdartige Ei ist ein ungewöhnliches und geheimnisvolles Gelege, das von einheimischen Windnattern in...",kw={"fremdartiges ei","freiwindposten","hagar lightninghoof","tausend nadeln","windnatter"},ang={["class:Hunter"]="Windnattern gehören zu den am meisten verehrten Bestien des Ödlands von Kalimdor, und das Aufspüren eines ihrer seltensten und am besten bewachten Gelege stellt jeden Jagdinstinkt auf die Probe.",["race:Tauren"]="Die Tauren des Freiwindpostens wachen unablässig über die Schlucht unter ihnen und betrachten das Erscheinen unbekannter Kreaturen als böses Omen oder als direkte Bedrohung für ihre exponierte Klippensiedlung."},sec={{t="Die Brut einer Natter",b="Das Fremdartige Ei, das am Fuße der hoch aufragenden Nadeln südlich und nordöstlich des Freiwindpostens entdeckt wurde, hebt sich deutlich von der typischen Fauna des Schluchtbodens ab. Anstatt das merkwürdige Gelege aufzugeben oder zu zerstören, bewachen die einheimischen Nattern der Nadeln es erbittert neben ihren eigenen Nestern. Hagar Lightninghoof, ein Taurenkrieger, der von den Höhen des Freiwindpostens aus Wache hält, versuchte, das Exemplar zu bergen, um festzustellen, ob es eine Bedrohung für die Siedlungen auf den Mesas darstellt oder lediglich eine ungewöhnliche Variante des lokalen Reptilienlebens ist."},{t="Die Brut von Arikara",b="Als es zum Freiwindposten gebracht und einer genaueren Untersuchung unterzogen wird, bricht die geheimnisvolle Schale sofort auf. Sie enthält keinen außerirdischen Eindringling, sondern den jungen Nachwuchs von Arikara, einer legendären geflügelten Natter, die in den Schluchten verehrt und gefürchtet wird. Die junge Kreatur erhebt sich sogleich in die Lüfte, was eine Kette von Ereignissen auslöst, die die örtlichen Verteidiger dazu bringt, sich dem Zorn der großen Natter selbst zu stellen."}},faq={{q="Warum wird das Ei als 'fremdartig' bezeichnet?",a="Der Begriff 'fremdartig' wird im traditionellen Sinne von völlig fremd und den örtlichen Taurenspähern unvertraut verwendet, anstatt anzudeuten, dass es aus dem Weltall stammt. Seine Färbung und Zeichnung unterschieden sich gänzlich von gewöhnlichen Windnatterngelegen, wie man sie in Tausend Nadeln findet.",al={"fremdartiges ei name","warum fremdartig","ist es aus dem weltall"}},{q="Wo ist das Fremdartige Ei zu finden?",a="Das Ei liegt auf dem Schluchtboden nahe dem Fuß der Mesawände, sowohl südlich als auch nordöstlich des Freiwindpostens in Tausend Nadeln. Es wird ausnahmslos von feindseligen Windnattern umringt und bewacht.",al={"ei standort","wo ist das fremdartige ei","fremdartiges ei finden"}},{q="Warum bewachen die einheimischen Nattern das Ei?",a="Das Ei gehört zur Brut von Arikara, einer mächtigen und uralten Windnatter von Tausend Nadeln. Die niederen Nattern erkennen das Ei instinktiv als eines der ihren an und verteidigen es erbittert gegen alle herannahenden Reisenden.",al={"warum nattern es beschützen","nattern bewachen ei"}},{q="Was geschieht, wenn Ihr das Ei zu Hagar Lightninghoof bringt?",a="Nach der Übergabe an Hagar Lightninghoof am Freiwindposten bricht das Ei auf und gibt ein Young Arikara frei. Die neugeborene Natter steigt sofort in den Himmel empor, was tiefere Sorgen über die Rückkehr ihres gefährlichen Elternteils weckt.",al={"hagar ei abgeben","was schlüpft"}}},fp="9,333,17.548.0,20.438.1,30.274.0,33.201.0,40.228.1,59.217.1"}
P.entries["item:alterac-granite"] = {n="Alteracgranit",s="Alteracgranit ist ein geschätzter, widerstandsfähiger Stein, der im bergigen Gelände des nördlichen Lordaeron abgebaut wird, insbesondere rund um Darrow Hill im Vorgebirge von Hillsbrad. Von Meistersteinmetzen für seine außergewöhnliche Beständigkeit und Maserung verehrt, wählt ihn König Magni Bronzebeards königlicher Steinmetz aus, um ein dauerhaftes Denkmal für gefallene Soldaten zu meißeln.",h="Alteracgranit ist ein geschätzter, widerstandsfähiger Stein, der im bergigen Gelände des nördlichen Lordaeron...",kw={"alteracgranit","darrow hill","hillsbrad","ironforge","marblesten","sully balloo","thandol-übergang"},ang={["profession:Mining"]="Bergleute und Prospektoren schätzen Alteracgranit für seinen sauberen Bruch und seine außergewöhnliche Dichte, die ihn von gewöhnlichem Felsgestein abhebt.",["race:Dwarf"]="Zwergensteinmetze stellen Materialqualität über alles, was diesen robusten Gebirgsstein unverzichtbar macht, um einen Mitbürger von Ironforge zu ehren."},sec={{t="Stein des Gedenkens",b="Als König Magni Bronzebeard ein Denkmal zum Gedenken an Sully Balloo in Auftrag gab – einen tapferen zwergischen Verteidiger, der bei der Tragödie am Thandol-Übergang ums Leben kam –, genügte gewöhnlicher Bruchstein nicht. Großsteinmetz Marblesten, der mit der Bildhauerei des Denkmals in Ironforge betraut war, bestand darauf, Alteracgranit zu beschaffen. Bekannt als einer der feinsten Steine in den gesamten Östlichen Königreichen, gewährleistet seine legendäre Haltbarkeit, dass das Abbild und das Andenken an einen gefallenen Helden über Generationen hinweg unversehrt fortbestehen können."},{t="Unter Gefahren gebrochen",b="Die Beschaffung von Alteracgranit ist alles andere als eine einfache Aufgabe. Der Stein lagert um Darrow Hill in den nördlichen Ausläufern des Vorgebirges von Hillsbrad, nahe den ruinierten Gebieten von Alterac. Da die Region von feindseligen Wildtieren, lauernden Briganten des Syndikats und schwelenden Konflikten heimgesucht wird, erfordert das Bergen unversehrter Platten dieses makellosen Steins kühne Abenteurer, die bereit sind, tief in umkämpfte Lande vorzudringen, um ihn für die Handwerker von Ironforge zu sichern."}},faq={{q="Wofür wird Alteracgranit verwendet?",a="Alteracgranit wird von Großsteinmetz Marblesten in Ironforge in Auftrag gegeben, um ein königliches Denkmal zu Ehren von Sully Balloo zu meißeln, einem Zwergensoldaten, der bei der Verteidigung des Thandol-Übergangs fiel.",al={"alteracgranit verwendung","warum alteracgranit","marblesten stein"}},{q="Wo ist Alteracgranit zu finden?",a="Er wird von Steinvorkommen bei Darrow Hill gesammelt, gelegen im nördlichen Gebiet des Vorgebirges von Hillsbrad nahe der Grenze von Alterac.",al={"alteracgranit fundort","wo gibt es alteracgranit","darrow hill granit"}},{q="Warum verlangte Großsteinmetz Marblesten ausdrücklich diesen Stein?",a="Großsteinmetz Marblesten betrachtet Alteracgranit als einen der feinsten und widerstandsfähigsten Bildhauersteine überhaupt und hält ihn für das einzige Material, das eines von König Magni in Auftrag gegebenen, dauerhaften königlichen Denkmals würdig ist.",al={"warum marblesten granit will","warum alterac stein"}},{q="Wer war Sully Balloo?",a="Sully Balloo war ein Zwergensoldat, der während der Kämpfe am Thandol-Übergang starb. König Magni Bronzebeard gab zu seinen Ehren ein Denkmal in Auftrag, um sein Opfer für die Allianz zu würdigen.",al={"sully balloo","wer starb am thandol-übergang"}}},fp="15,339,18.494.0,17.442.0,33.174.0,35.134.0,60.203.0,21.191.0"}
P.entries["item:altered-snapjaw-shell"] = {n="Veränderte Schnappkieferschale",s="Eine Veränderte Schnappkieferschale ist der Panzer einer Süßwasserschildkröte, die die üppigen Oasen des Brachlands bewohnt. Druiden, die die Region erforschen, untersuchen diese mutierten Schalen, um zu verstehen, wie seltsame unterirdische Spalten die örtliche Tierwelt verzerren.",h="Eine Veränderte Schnappkieferschale ist der Panzer einer Süßwasserschildkröte, die die üppigen Oasen des...",kw={"veränderte wesen","veränderte schnappkieferschale","brachland","die blühende oase","oasenschnappkiefer","die brackige oase","tonga runetotem"},ang={["class:Druid"]="Für Druiden ist die Untersuchung der verzerrten Panzer der Oasentiere ein wesentlicher Schritt, um jedes verborgene Ungleichgewicht zu identifizieren, das die Gewässer des Brachlands stört."},sec={{t="Zeichen des Verfalls",b="Die Süßwasserschildkröten, die in der blühenden und der brackigen Oase leben, haben spürbare, unnatürliche Veränderungen durchgemacht. Man vermutet, dass sie aus Quellen trinken, die von geheimnisvollen unterirdischen Rissen gespeist werden, und die Oasenschnappkiefer weisen veränderte Panzer auf, die Forscher in Crossroads faszinieren. Tonga Runetotem, ein Taurendruide, der den Zustand des Landes ergründen möchte, sammelt diese Schalen, um festzustellen, ob die aus den Tiefen der Erde emporquellenden Energien eine unnatürliche Verderbnis oder etwas weitaus Seltsameres sind."}},faq={{q="Was macht diese Schildkrötenschalen verändert?",a="Die Schnappkiefer leben in den Quellen der blühenden Oase und der brackigen Oase, die von tiefen unterirdischen Spalten gespeist werden. Die seltsamen Energien, die in die Oasengewässer sprudeln, haben die physische Biologie der Kreaturen verändert, die daraus trinken, was zu sichtbar verzerrten Panzern führt.",al={"warum sind schalen verändert","was ist veränderte schnappkieferschale","schnappkieferschale mutation"}},{q="Wer benötigt diese Schalen und warum?",a="Tonga Runetotem, ein in Crossroads stationierter Druide, bittet Jäger, sie zu erbeuten. Er glaubt, dass die Untersuchung physischer Veränderungen an einheimischen Tieren der Schlüssel zur Feststellung ist, welche Art von Macht oder Verderbnis die Wasserversorgung des Brachlands beeinträchtigt.",al={"wer braucht veränderte schnappkieferschalen","tonga runetotem schalen","veränderte wesen quest abgabe"}},{q="Wo sind diese Schnappkiefer zu finden?",a="Oasenschnappkiefer bewohnen die Gewässer und schlammigen Ufer sowohl der blühenden Oase als auch der brackigen Oase, die südlich und südöstlich von Crossroads liegen.",al={"oasenschnappkiefer standort","wo gibt es veränderte schalen","schnappkieferschale fundorte"}}},fp="21,241,19.495.0,39.279.0,31.238.0,31.150.0"}
P.entries["item:ambercorn"] = {n="Bernsteinkorn",s="Bernsteinkorn ist eine heilige Nuss, die von den hohen, uralten Bäumen in ganz Mulgore herabfällt. Durchdrungen von natürlicher Magie dient sie als lebenswichtiges Reagenz für schamanische Gebräue der Tauren und wird vor allem verwendet, um bei den Prüfungen der Jugend spirituelle Visionen hervorzurufen.",h="Bernsteinkorn ist eine heilige Nuss, die von den hohen, uralten Bäumen in ganz Mulgore herabfällt.",kw={"bernsteinkorn","bloodhoof","mulgore","ritus der sicht","tauren-prüfung","wasser der seher","zarlman two-moons"},ang={["class:Shaman"]="Die schamanische Tradition ehrt natürliche Katalysatoren wie das Bernsteinkorn und erkennt an, dass die Erdenmutter spirituelle Magie in die physische Ernte ihrer Bäume und Böden bettet.",["race:Tauren"]="Jeder junge Taure, der sich den traditionellen Riten der Erdenmutter unterzieht, lernt, das Bernsteinkorn als wesentliche Zutat für die Visionssuche zu erkennen, die seinen spirituellen Pfad offenbart."},sec={{t="Gaben des Blätterdachs",b="Unter den kräftigen Ästen der großen Bäume Mulgores gesammelt, sind Bernsteinkörner für die Tauren mehr als gewöhnliche Nüsse. Reich an der spirituellen Lebenskraft des Landes bergen sie verborgene magische Eigenschaften, die die Mystiker der Tauren seit Generationen verstehen und nutzen. Junge Jäger und Wanderer lernen früh, ihren Blick auf das Gras unter dem Blätterdach zu richten und die Gaben der Erdenmutter zu ehren, die frei von oben herabfallen."},{t="Das Gebräu des Sehers",b="In Bloodhoof verlässt sich der Seher Zarlman Two-Moons auf Bernsteinkorn, wenn er junge Tauren auf den Ritus der Sicht vorbereitet. Zusammen mit Steinen aus den unberührten Wasserbrunnen der Ebenen wird Bernsteinkorn zum wirkmächtigen Wasser der Seher aufgebrüht. Das Trinken dieses zeremoniellen Elixiers vor den Flammen der Ahnen verändert die Sinne eines Initiierten und offenbart ein Geisttier als Führer, das ihn zu seiner nächsten Bestimmung geleiten soll."}},faq={{q="Was ist ein Bernsteinkorn?",a="Bernsteinkorn ist eine Samenkapsel oder Nuss, die von den großen, uralten Bäumen Mulgores herabfällt. Sie birgt eine angeborene Naturmagie, die auf die Geister des Landes eingestimmt ist.",al={"bernsteinkorn","was sind bernsteinkörner"}},{q="Wo ist Bernsteinkorn zu finden?",a="Sie liegen verstreut direkt auf dem Boden unter den Kronen der mächtigen Bäume in den Graslanden von Mulgore, insbesondere in den Gebieten rund um Bloodhoof.",al={"bernsteinkorn fundort","wo findet man bernsteinkorn","wie bekommt man bernsteinkorn"}},{q="Wofür wird Bernsteinkorn verwendet?",a="Seher der Tauren kombinieren Bernsteinkorn mit Brunnensteinen, um das Wasser der Seher zu brauen – eine zeremonielle Flüssigkeit, die während des Ritus der Sicht getrunken wird, um spirituelle Führer zu offenbaren.",al={"bernsteinkorn zweck","was bewirkt bernsteinkorn"}},{q="Wer verlangt nach Bernsteinkorn in Bloodhoof?",a="Zarlman Two-Moons, ein angesehener Seher in Bloodhoof, beauftragt Initiierte mit dem Sammeln von Bernsteinkorn als Teil der Prüfungen, die erforderlich sind, um die eigene Verbindung zur Erdenmutter zu beweisen.",al={"wer braucht bernsteinkorn","bernsteinkorn questgeber"}}},fp="9,241,19.422.0,15.425.0,21.150.0,29.181.0,27.162.0,44.185.0"}
P.entries["item:amethyst-phial"] = {n="Amethystphiole",s="Die Amethystphiole ist ein zartes zeremonielles Gefäß, das jungen Nachtelfenabenteurern von Corithras Moonrage in Dolanaar anvertraut wird. Sie wurde eigens dafür gefertigt, geweihtes Wasser aus dem wichtigsten Mondbrunnen unter dem Orakelbaum zu schöpfen und zu bewahren.",h="Die Amethystphiole ist ein zartes zeremonielles Gefäß, das jungen Nachtelfenabenteurern von Corithras...",kw={"amethystphiole","corithras moonrage","krone der erde","dolanaar","mondbrunnen","die lichtung des orakels","orakelbaum","teldrassil"},ang={["class:Druid"]="Druiden betrachten das Gefäß als entscheidendes Werkzeug zur Überwachung der Lebensenergien und der schleichenden Verderbnis, die das Ökosystem des Weltenbaums bedrohen.",["race:NightElf"]="Für die Kaldorei ist das Füllen dieser Phiole eine feierliche Pflicht, die sie direkt mit den beunruhigenden Makeln von Teldrassils ungesegneter Schöpfung konfrontiert."},sec={{t="Gefäß geweihter Wasser",b="Eingeweihten auf Teldrassil anvertraut, ist die Amethystphiole das letzte Gefäß, das bei der Pilgerreise zur Krone der Erde verwendet wird. Corithras Moonrage beauftragt Reisende damit, sie in die fernsten nordwestlichen Ausläufer des Geästs zu tragen, eingebettet in Die Lichtung des Orakels. Dort, unter dem uralten Blätterdach des Orakelbaums, liegt der erste und mächtigste Mondbrunnen der Insel. Die Phiole wird behutsam in diese strahlenden Wasser getaucht, um die Essenz von Elunes Anmut zu schöpfen, was es Druiden und Priesterinnen ermöglicht, das unberechenbare Wachstum des Weltenbaums zu studieren und zu pflegen."},{t="Die Bürde ungesegneten Wachstums",b="Das Sammeln dieser Probe ist mehr als ein gewöhnlicher Ritus der Andacht. Teldrassil wurde unter der Führung von Erzdruide Fandral Staghelm ohne den Segen der Drachenaspekte erschaffen, die sich weigerten, einen ihrer Ansicht nach anmaßenden Akt gutzuheißen. Infolgedessen leidet das Geäst unter einer beunruhigenden Verderbnis, und die Kaldorei bleiben sterblich. Das Füllen der Amethystphiole dient sowohl als spirituelles Ritual als auch als fortlaufende Untersuchung, die es Forschern in Dolanaar ermöglicht, die Reinheit von Teldrassils geweihten Wassern genau zu prüfen."}},faq={{q="Wofür wird die Amethystphiole verwendet?",a="Die Phiole wird Abenteurern von Corithras Moonrage übergeben, um Wasser aus dem ersten und mächtigsten Mondbrunnen auf Teldrassil zu schöpfen, der sich auf der Lichtung des Orakels unter dem großen Orakelbaum befindet.",al={"amethystphiole zweck","was tun mit amethystphiole","amethystphiole verwendung"}},{q="Wo fülle ich die Amethystphiole?",a="Sie muss in den Mondbrunnen getaucht werden, der weit im Nordwesten von Dolanaar, hinter den Toren von Darnassus, in dem abgelegenen Hain namens Die Lichtung des Orakels liegt.",al={"wo amethystphiole füllen","amethystphiole standort","lichtung des orakels mondbrunnen"}},{q="Warum ist das Wasser von der Lichtung des Orakels so wichtig?",a="Der Mondbrunnen unter dem Orakelbaum gilt als der erste und mächtigste Brunnen, der auf dem Weltenbaum errichtet wurde. Seine Wasser sind tief von der Essenz Elunes durchdrungen, was sie unverzichtbar macht, um die spirituelle und körperliche Gesundheit von Teldrassil zu überwachen.",al={"warum lichtung des orakels wasser","orakelbaum mondbrunnen macht","bedeutung des orakelbrunnens"}},{q="Wer schickt Euch aus, um diese Phiole zu benutzen?",a="Corithras Moonrage, ein in Dolanaar stationierter Nachtelfendruide, übergibt die Phiole als Teil der rituellen Aufgaben, die darauf abzielen, die beunruhigende Natur von Teldrassils Wachstum zu verstehen.",al={"wer gibt amethystphiole","corithras moonrage phiole","wer will die amethystphiole"}}},fp="14,241,23.550.0,28.517.1,36.187.0,35.160.0,52.258.0,32.174.0"}
P.entries["item:an-undelivered-letter"] = {n="Ein niemals zugestellter Brief",s="Ein niemals zugestellter Brief ist ein lange vergessenes Schriftstück, das im Lion's Pride Inn in Goldhain zurückgelassen wurde. Vor Jahren von dem schwer fassbaren Stalvan Mistmantle verfasst, dient er als entscheidender Hinweis bei der Aufdeckung der finsteren Geschichte seiner Vergangenheit.",h="Ein niemals zugestellter Brief ist ein lange vergessenes Schriftstück, das im Lion's Pride Inn in Goldhain...",kw={"kanalviertel","kurier","folsom","goldhain","lion's pride inn","bote","mistmantle","stalvan"},ang={["faction:Alliance"]="Der vergessenen Route dieses Boten zu folgen, führt Ermittler aus dem ländlichen Herzen von Goldhain in die vornehmen Viertel von Stormwind."},sec={{t="Eine Flucht um Mitternacht",b="Vor Jahren trieb ein Unwetter einen reisenden Kurier auf der Suche nach einer trockenen Bleibe in das Lion's Pride Inn. Gegen Mitternacht floh der verängstigte Bote im Nachtgewand die Treppe hinab und verschwand im strömenden Regen, um nie wiederzukehren. Er ließ im zweiten Stock eine Truhe voller Habseligkeiten zurück, darunter einen von Stalvan Mistmantle geschriebenen Brief, der an ein Anwesen im Kanalviertel von Stormwind gerichtet war."},{t="Den Gelehrten aufspüren",b="Der ungeöffnete Brief blieb in den oberen Räumen des Gasthauses unberührt, bis Ermittler der Gegenwart begannen, Stalvans Spuren durch den Wald von Elwynn nachzugehen. Die Übergabe des lange verschollenen Schriftstücks an Verwalter Folsom in der Hauptstadt schlägt die Brücke dieses Geheimnisses von den ruhigen Hallen der Taverne direkt in das Herz von Stormwind."}},faq={{q="Wo wird der nicht zugestellte Brief gefunden?",a="Er liegt in einer Aufbewahrungstruhe im zweiten Stock des Lion's Pride Inn in Goldhain, direkt am Fußende des Bettes in einem der Gästezimmer.",al={"wo ist der brief","fundort aufbewahrungstruhe","lion's pride truhe"}},{q="Warum wurde der Brief nie zugestellt?",a="Der Bote, der ihn bei sich trug, suchte im Lion's Pride Inn Schutz vor einem Regensturm. Gegen Mitternacht geriet er plötzlich in Panik, stürmte im Nachtgewand die Treppe hinunter und rannte in das Unwetter hinaus, wobei er seine Truhe und deren Inhalt zurückließ.",al={"warum nicht zugestellt","was geschah mit dem boten","kurier geflohen"}},{q="Wer hat diesen Brief geschrieben?",a="Der Brief wurde von Stalvan Mistmantle verfasst, der zur selben Zeit wie der verängstigte Bote einige Nächte im Gasthaus verbracht hatte.",al={"wer hat den brief geschickt","stalvan autor","absender"}},{q="Wohin soll der Brief gebracht werden?",a="Er ist an das Kanalviertel von Stormwind adressiert, wo er zu Verwalter Folsom nahe dem Park gebracht werden kann.",al={"wer erhält den brief","ziel stormwind","brief kanalviertel"}}},fp="21,222,17.401.0,19.307.1,38.150.0,35.223.0,22.140.0,35.115.0"}
P.entries["item:anaya-s-pendant"] = {n="Anayas Anhänger",s="Anayas Anhänger ist ein Andenken, das der rastlose Geist von Anaya Dawnrunner in den Ruinen von Ameth'Aran bei sich trägt. Es dient als tragisches Zeichen des Gedenkens für ihren Geliebten Cerellean Whiteclaw, der die Zerschlagung nur überlebte, um Jahrtausende später festzustellen, dass ihr Geist noch immer gequält umherwandelt.",h="Anayas Anhänger ist ein Andenken, das der rastlose Geist von Anaya Dawnrunner in den Ruinen von Ameth'Aran...",kw={"ameth'aran","anaya dawnrunner","auberdine","cerellean whiteclaw","dunkelküste","in ewiger liebe","anhänger","brunnen der ewigkeit"},ang={["class:Druid"]="Wie viele Druiden, die Shan'do Stormrage in den Smaragdgrünen Traum folgten, schlief Cerellean jahrtausendelang in der Hoffnung, seiner Trauer zu entkommen, nur um in der wachenden Welt bei verbliebenen Geistern zu erwachen.",["race:NightElf"]="Der Anhänger ist eine ergreifende Erinnerung an die bleibenden Narben, die der Krieg der Ahnen hinterließ, als während der Großen Zerschlagung zahllose Leben und Lieben zerrissen wurden."},sec={{t="Ein Andenken über Jahrtausende hinweg",b="Vor zehntausend Jahren, während der kataklysmischen Zerstörung des Brunnens der Ewigkeit, verfiel die uralte Kaldorei-Stadt Ameth'Aran in Schutt und Asche. Im Glauben, seine geliebte Anaya sei umgekommen, trug Cerellean Whiteclaw seine tiefe Trauer an der Seite von Shan'do Malfurion Stormrage in den langen Schlummer. Als er schließlich erwachte, wanderte er durch die Dunkelküste, nur um herauszufinden, dass Anayas gequälte Erscheinung noch immer durch Ameth'Aran schwebte und eben diesen Anhänger bei sich trug. Unfähig, es über das Herz zu bringen, selbst die Hand gegen sie zu erheben, bittet Cerellean vorbeikommende Reisende darum, ihren Geist zu erlösen und das Erbstück zu bergen."},{t="Abschied und Frieden",b="Die Rückgabe des Anhängers an Cerellean in Auberdine gestattet es dem verweilenden Geist von Anaya Dawnrunner, sich ein letztes Mal kurz vor ihm zu manifestieren. Befreit von den Qualen, die sie an die heimgesuchten Ruinen von Ameth'Aran banden, schwindet ihr Geist friedlich in die Nacht und lässt Cerellean allein mit dem Anhänger und seiner bleibenden Erinnerung an ihre uralte Liebe zurück."}},faq={{q="Woher stammt Anayas Anhänger?",a="Der Anhänger wird vom Geist von Anaya Dawnrunner geborgen, die durch die uralten Kaldorei-Ruinen von Ameth'Aran im Süden der Dunkelküste wandelt.",al={"wo man anayas anhänger bekommt","wie bekomme ich anayas anhänger","wer lässt anayas anhänger fallen"}},{q="Wer sucht nach Anayas Anhänger?",a="Er gehört Cerellean Whiteclaw, einem trauernden Nachtelfen, der sich in der Küstenstadt Auberdine an der Dunkelküste aufhält.",al={"wem gebe ich anayas anhänger","cerellean whiteclaw quest","anayas anhänger abgeben"}},{q="Warum konnte Cerellean den Anhänger nicht selbst holen?",a="Cerellean entdeckte den Geist seiner verlorenen Liebe, wie er durch die Ruinen von Ameth'Aran zog, doch selbst nach zehntausend Jahren des Kummers brachte er es nicht über das Herz, selbst die Hand gegen sie zu erheben.",al={"warum cerellean anaya nicht tötete","warum cerellean hilfe braucht"}},{q="Was geschieht, wenn Ihr Cerellean den Anhänger zurückbringt?",a="Wenn der Anhänger zu Cerellean nach Auberdine zurückgebracht wird, erscheint Anayas Geist für einen kurzen Abschied vor ihm, bevor er friedlich vergeht und Cerellean endlich gestattet, um ihr Andenken zu trauern.",al={"was mit anaya passiert","cerellean reaktion"}}},fp="15,273,27.579.0,17.343.1,37.136.0,26.111.0,52.191.0,54.193.1"}
P.entries["item:ancient-moonstone-seal"] = {n="Altes Mondstein-Siegel",s="Das Alte Mondstein-Siegel ist ein mächtiges Relikt der Zauberei der Hochgeborenen, das lange vor der Zerschlagung geschmiedet wurde. Erfüllt von wirkmächtiger arkaner bindender Magie, diente es als Anker, der den Geist von Asterion in den Ruinen von Bashal'Aran gefangen hielt.",h="Das Alte Mondstein-Siegel ist ein mächtiges Relikt der Zauberei der Hochgeborenen, das lange vor der...",kw={"ameth'aran","altes mondstein-siegel","asterion","athrikus","bashal'aran","dunkelküste","deth'ryll","hochgeborene","mondstein"},ang={["class:Mage"]="Der Mondstein demonstriert die anhaltende Macht der uralten Bannmagie der Elfen, indem er sein bindendes Feld über zehntausend Jahre lang ununterbrochen aufrechterhielt.",["race:NightElf"]="Das Siegel ist ein mahnendes Relikt der ungezügelten arkanen Macht und der grausamen Versklavungspraktiken der Hochgeborenen vor der Großen Zerschlagung."},sec={{t="Ein Gefängnis der Zauberei der Hochgeborenen",b="Geschmiedet von Asterions früherem Meister, dem mächtigen Zauberer der Hochgeborenen Athrikus Narassin, wurde das Alte Mondstein-Siegel geschaffen, um als unzerbrechlicher metaphysischer Anker zu dienen. Als der Brunnen der Ewigkeit noch stand und Königin Azshara herrschte, nutzte Athrikus das Artefakt, um Asterions Seele an die Säulen von Bashal'Aran zu binden. Über zehntausend Jahre später blieb Asterion ein unkörperlicher Gefangener seiner Magie, unfähig, den Schutzzauber mit irgendeiner ihm zur Verfügung stehenden Kraft oder einem Zauber zu brechen."},{t="Zerstörung in Ameth'Aran",b="Nach den Verheerungen der Großen Zerschlagung fiel das Siegel schließlich in die Klauen der Deth'ryll-Satyren, welche die umliegende Wildnis der Dunkelküste heimsuchen. Da gewöhnliche Gewalt dem verzauberten Stein der Hochgeborenen nichts anhaben kann, erfordert die Zerstörung des Artefakts, es der uralten blauen Flamme auszusetzen, die in den Zwillingsruinen von Ameth'Aran im Süden fortdauert. Das Siegel in diesem arkanen Feuer zu verbrennen, zerschlägt Athrikus' Bindezauber dauerhaft und entlässt Asterions Geist endlich in die sterbliche Welt."}},faq={{q="Was ist das Alte Mondstein-Siegel?",a="Es ist ein uraltes magisches Relikt, das von dem Zauberer der Hochgeborenen Athrikus Narassin geschaffen wurde. Es dient als arkaner Schlüssel, der den Geist von Asterion an seinen Schrein in den Ruinen von Bashal'Aran bindet.",al={"was ist mondstein-siegel","siegel von asterion","bashal'aran siegel"}},{q="Wer besitzt das Siegel, bevor es geborgen wird?",a="Das Siegel fiel in die Hände der Deth'ryll-Satyren, welche die Ruinen um Bashal'Aran an der Dunkelküste bewohnen, die seine Anwesenheit nutzten, um niedere Grell-Diener zu befehligen.",al={"wer hat das siegel","wo findet man mondstein-siegel","wer droppt mondstein-siegel"}},{q="Wie kann das Siegel zerstört werden?",a="Gewöhnliche Waffen oder zeitgenössische Magie können dem Relikt nichts anhaben. Es muss in die uralte, ewige Flamme geworfen werden, die noch immer in den Zwillingsruinen von Ameth'Aran im Süden brennt.",al={"wie bricht man das siegel","mondstein-siegel zerstören","wo zerstöre ich das siegel"}},{q="Was geschieht, wenn das Siegel zerstört wird?",a="Das Verbrennen des Siegels in den Flammen von Ameth'Aran bricht die uralten Binde-Verzauberungen, die Asterion festhalten, und schenkt seinem Geist die Freiheit, die Welt nach Jahrtausenden der Gefangenschaft zu durchstreifen.",al={"was bewirkt das brechen des siegels","asterion befreit"}}},fp="22,238,29.469.0,25.498.1,35.190.0,46.165.0,30.180.0,40.186.1"}
P.entries["item:ancient-statuette"] = {n="Antike Statuette",s="Die antike Statuette ist ein versunkenes Relikt, das an den Ufern des Zoramstrands im nordwestlichen Ashenvale geborgen wurde. Das kleine Bildnis, nach dem der Nachtelf Talen sucht, stammt aus den überfluteten Ruinen der antiken Stadt Zoram.",h="Die antike Statuette ist ein versunkenes Relikt, das an den Ufern des Zoramstrands im nordwestlichen...",kw={"antike statuette","ashenvale","naga","ruinen von zoram","statuette","talen","zoram","der zoramstrand"},ang={["faction:Alliance"]="Die Bergung dieses Artefakts hilft Talen dabei, das Erbe der Nachtelfen vor den vordringenden Naga entlang der Küste von Ashenvale zu dokumentieren und zurückzufordern.",["race:NightElf"]="Die Statuette ist ein seltenes erhaltenes Fragment der antiken Zivilisation der Kaldorei von vor der Großen Zerschlagung, das jahrtausendelang unter dem Meer konserviert wurde."},sec={{t="Ein Relikt im Seichtwasser",b="Die Gewässer vor dem nordwestlichen Ashenvale verbergen die versunkenen Überreste von Zoram, einer Stadt der Nachtelfen aus der Zeit vor der Zerschlagung, die vor zehntausend Jahren in den Fluten versank. In jüngster Zeit erforschte der Entdecker Talen die versunkenen Ruinen von einem kleinen Boot aus auf der Suche nach verschollenen historischen Relikten. Als ein bösartiger Angriff der Naga ihn an Land trieb, ließ Talen auf seiner Flucht die meisten seiner Habseligkeiten zurück und verlor die antike Statuette, die er geborgen hatte, im Sand der Gezeitenlinie nahe seinem zerstörten Kahn."},{t="Geheimnisse von Zoram",b="Talen betrachtet die Statuette als seinen wertvollsten Besitz und als die einzige Rechtfertigung dafür, der von Ungeheuern heimgesuchten Küste getrotzt zu haben. Anstatt bloß ein dekoratives Steinartefakt zu sein, dient das Bildnis seiner Ansicht nach als unverzichtbarer Schlüssel zur Entschlüsselung der Architektur, Geschichte und arkanen Geheimnisse, die unter der Brandung des Zoramstrands verborgen liegen."}},faq={{q="Was ist die antike Statuette?",a="Sie ist ein Artefakt aus den versunkenen Ruinen der antiken Nachtelfenstadt Zoram vor der nordwestlichen Küste von Ashenvale.",al={"was ist die statuette","antike statuette geschichte","was ist dieser gegenstand"}},{q="Wer sucht nach der Statuette?",a="Der Gelehrte der Nachtelfen, Talen, sucht nach ihr. Er glitt mit einem Boot über die versunkenen Ruinen, als Naga ihn überfielen, was ihn dazu brachte, das Relikt auf seiner lebensrettenden Flucht am Strand fallen zu lassen.",al={"wer sucht die statuette","talen statuette","wer verlor die statuette"}},{q="Warum ist die Statuette von Bedeutung?",a="Talen glaubt, dass die Statuette die Geheimnisse der antiken Stadt Zoram birgt und als Schlüssel dienen könnte, um die in den Ruinen unter den Wellen verborgene Geschichte zu lüften.",al={"warum will talen sie","zweck der statuette"}},{q="Warum lauern Naga dort, wo sie gefunden wurde?",a="Naga haben die Küstengewässer und Ruinen des Zoramstrands verseucht und greifen aggressiv jeden Oberflächenbewohner an, der sich den versunkenen Überresten ihres überfluteten Territoriums nähert.",al={"warum sind naga am strand","zoramstrand naga"}}},fp="17,226,23.470.0,16.340.0,30.140.0,33.180.0,31.165.0,48.178.0"}
P.entries["item:andron-s-ledger"] = {n="Androns Geschäftsbuch",s="Androns Geschäftsbuch ist ein Aufklärungsdokument, das von Andron Gant in Undercity erbeutet wurde. Es beschreibt heimliche Aktivitäten im Detail, die die unerwartete Verwicklung des Syndikats in regionale Angelegenheiten aufdecken und so die direkte Aufmerksamkeit von Varimathras erregen.",h="Androns Geschäftsbuch ist ein Aufklärungsdokument, das von Andron Gant in Undercity erbeutet wurde.",kw={"alterac","andron gant","androns geschäftsbuch","die todespirscher","mennet carkad","rogues' quarter","syndikat","varimathras"},ang={["class:Rogue"]="Das Bergen und Entziffern von Androns Geschäftsbuch dient Euch als Bewährungsprobe, besiegelt Eure offizielle Aufnahme bei den Todespirschern durch Mennet Carkad und bringt Euch die persönliche Anerkennung von Varimathras ein.",["race:Undead"]="Das Buch entlarvt die Einmischung des Syndikats und zeigt, dass die lebenden Menschenadligen von Alterac noch immer versuchen, die Souveränität der Verlassenen zu bedrohen."},sec={{t="Die Enttarnung des Syndikats",b="Dieses Geschäftsbuch, das aus dem Bücherregal von Andron Gant in Undercity geborgen wurde, enthält weitaus mehr Geheimdienstinformationen, als Die Todespirscher ursprünglich erwartet hatten. Sein Inhalt offenbart, dass das Syndikat – die Überreste des gefallenen menschlichen Adels von Alterac – in der Region aktiv agiert. Beim Durchsehen der Einträge erkennt Todespirscher Mennet Carkad sofort den strategischen Wert des Dokuments und begreift, dass die ruinierten Lords von Alterac erneut Ränke schmieden. Das Buch liefert der Führung der Verlassenen handfeste Beweise für Operationen des Syndikats und verwandelt einen Routineauftrag in einen bedeutenden Geheimdiensterfolg."},{t="Eine Angelegenheit für den Schreckenslord",b="Da die Enthüllung regionale Bedrohungen für das Reich der Verlassenen betrifft, schickt Mennet Carkad den Überbringer los, um das Geschäftsbuch direkt zu Varimathras in das Royal Quarter zu bringen. Als Schreckenslord-Majordomus von Sylvanas Windrunner überwacht Varimathras die innere Sicherheit und die Spionage über Die Todespirscher. Das Geschäftsbuch bringt das Lob von Varimathras ein und beweist sowohl die Kompetenz des Todespirscher-Netzwerks als auch die Verlässlichkeit des Agenten, der es ans Licht gebracht hat."}},faq={{q="Was ist Androns Geschäftsbuch?",a="Es ist ein Aufzeichnungsbuch, das aus dem Bücherregal von Andron Gant in Undercity beschafft wurde und geheime Informationen über die Truppenbewegungen und Operationen des Syndikats in Lordaeron enthält.",al={"androns geschaeftsbuch","was ist dieses buch","andron geschaeftsbuch"}},{q="Wer ist Andron Gant?",a="Andron Gant ist ein Verlassener, der einen Laden nahe dem Apothecarium in Undercity betreibt. Lord Varimathras verdächtigte ihn, heimlich einer externen Gruppe zu helfen, weshalb Die Todespirscher einen Agenten entsandten, der sich als sein erwarteter Bote ausgab, um an sein Buch zu gelangen.",al={"wer ist andron","andron gant"}},{q="Warum ist das im Buch erwähnte Syndikat wichtig?",a="Das Geschäftsbuch enthüllt, dass das Syndikat – bestehend aus dem in Ungnade gefallenen Adel des einstigen Königreichs Alterac – aktiv in lokale Komplotte verwickelt ist, wodurch die Verlassenen frühzeitig vor dessen Manövern gewarnt werden.",al={"warum syndikat wichtig ist","was enthuellt das geschaeftsbuch"}},{q="Wer erhält das Geschäftsbuch?",a="Es wird zunächst zu Mennet Carkad im Rogues' Quarter gebracht, der seinen Inhalt prüft und dann anordnet, es direkt zu Lord Varimathras in die Halle der Dunklen Fürstin zu überbringen.",al={"wer bekommt androns geschaeftsbuch","zu wem bringe ich das buch"}},{q="Was bringt die Übergabe des Geschäftsbuches einem Schurken ein?",a="Die Übergabe des Geschäftsbuches und die Aufdeckung der Verwicklung des Syndikats schließen die Einweihung des Agenten bei den Todespirschern ab und bringen die formelle Aufnahme in die geheime Attentätergilde der Verlassenen ein.",al={"aufnahme bei den todespirschern","den todespirschern beitreten"}}},fp="15,244,24.613.1,26.462.2,24.172.0,19.240.0,55.200.0,24.186.0,52.196.0"}
P.entries["item:another-clue-to-sanders-treasure"] = {n="Another Clue to Sanders' Treasure",s="Another Clue to Sanders' Treasure ist ein verwitterter Pergamentfetzen, den der berüchtigte Pirat Captain Sanders hinterlassen hat. Aus einem alten Fass geborgen, enthält er Richtungsverse, die Glücksjäger zu einem einsamen Wahrzeichen auf den Klippen von Westfall weisen.",h="Another Clue to Sanders' Treasure ist ein verwitterter Pergamentfetzen, den der berüchtigte Pirat Captain...",kw={"klippen","captain sanders","hinweis","pergament","sanders schatz","westfall","windmühle"},ang={["class:Rogue"]="Das Entziffern kryptischer Wegbeschreibungen und das Durchstöbern vergessener Verstecke am Meer gehören zum Handwerkszeug eines jeden, der ein Auge für verborgene Beute hat."},sec={{t="Eine Spur auf den Küstenklippen",b="Captain Sanders achtete sorgfältig darauf, seine gestohlenen Reichtümer niemals offen herumliegen zu lassen. Anstatt eine einzige Karte zu zeichnen, die auf einmal beschlagnahmt werden könnte, teilte er seine Anweisungen in eine Abfolge von Rätseln und vergrabenen Wegmarken auf. Dieser Pergamentfetzen setzt die Fährte fort und weist denjenigen, der ihn besitzt, an, sich vom vorherigen Versteck nach Norden zu wenden und nach einem weggeworfenen Krug zu suchen, der in der Nähe einer einsamen Windmühle hoch über den Klippen am Meer steht."}},faq={{q="Was steht auf diesem Hinweis?",a="Das Pergament weist den Finder an, sich vom versteckten Fass nach Norden zu wenden und in gerader Linie zu gehen, bis er neben einer einsamen Windmühle entlang der Meeresklippen einen leeren Krug entdeckt.",al={"was besagt der hinweis","sanders hinweistext","wegbeschreibung auf hinweis"}},{q="Wer war Captain Sanders?",a="Captain Sanders war ein Pirat, dessen Taten Verstecke gestohlener Waren an den Küsten und Klippen von Westfall hinterließen. Anstatt eine intakte Karte zu hinterlassen, schuf er eine Schnitzeljagd aus verborgenen Wegmarken in der gesamten Region.",al={"wer ist sanders","captain sanders hintergrund","sanders westfall pirat"}},{q="Wohin führt dieser Hinweis als Nächstes?",a="Folgt man den Anweisungen des Hinweises, gelangt man nach Norden entlang der Küstenklippen zu einer einsamen Windmühle auf den Anhöhen, wo ein leerer Krug Der nächste Schritt auf Sanders' Fährte bereithält.",al={"wohin als nächstes","sanders windmühlen hinweis","wo ist der krug"}}},fp="33,253,29.422.0,29.172.0,24.222.0,31.168.0"}
P.entries["item:arikara-serpent-skin"] = {n="Arikaras Schlangenhaut",s="Arikaras Schlangenhaut ist die schuppige Haut der mythischen Windnatter Arikara vom Düsterwolkengipfel. Zurückgebracht zum Weißgipfelposten dient sie als greifbarer Beweis dafür, dass die rachesuchende Bestie herbeigerufen und erschlagen wurde.",h="Arikaras Schlangenhaut ist die schuppige Haut der mythischen Windnatter Arikara vom Düsterwolkengipfel.",kw={"arikara","cairne bloodhoof","düsterwolkengipfel","brandpulver","motega firemane","schlangenhaut","weißgipfelposten"},ang={["class:Shaman"]="Das Ritual, verzaubertes Pulver auf einem heiligen Feuer einzusetzen, um eine Geisterbestie der Ahnen zur Materialisierung zu zwingen, zeugt von der mächtigen, wenn auch manipulativen Ritualkunst, die in Thunder Bluff praktiziert wird.",["race:Tauren"]="Die Haut versinnbildlicht einen Konflikt zwischen uralten Mythen und der gegenwärtigen Führung, wobei Magatha Grimmtotems Behauptungen über Cairne Bloodhoof unter den Stämmen Unbehagen hervorrufen."},sec={{t="Trophäe eines herbeigerufenen Zorns",b="Arikara ist eine furchterregende Windnatter aus uralten Legenden der Tauren, von der gemunkelt wird, dass sie angesichts des kulturellen Wandels Vergeltung an Cairne Bloodhoof üben will. Mithilfe von verzaubertem Brandpulver, das unter der Leitung von Älteste Magatha Grimmtotem hergestellt wurde, entzünden Champions das Hochheilige Feuer auf den Begräbnisanhöhen des Düsterwolkengipfels, um die Geisterbestie in das Reich des Fleisches zu zwingen. Das Abziehen der Schlangenhaut bringt Arikaras Schlangenhaut hervor – ein unverkennbares Relikt vom Tod der Bestie."},{t="Eine beunruhigende Offenbarung",b="Wird sie zu Motega Firemane am Weißgipfelposten gebracht, beweist die Haut zwar den Tod der Schlange, wirft jedoch unbequeme Fragen auf. Magatha Grimmtotem behauptete steif und fest, Arikara habe Cairne Bloodhoof gezielt aus uraltem Zorn gejagt, doch die Untersuchung der getöteten Kreatur lässt Motega ratlos zurück, warum solch ein Geist ihren Obersten Häuptling wahrhaftig bedrohen sollte. Obwohl der Balg die unmittelbare Gefahr bannt, hinterlässt er anhaltendes Misstrauen gegenüber Magathas wahren Absichten."}},faq={{q="Was ist Arikaras Schlangenhaut?",a="Es ist die schuppige Haut von Arikara, einer legendären Windnatter, die auf dem Düsterwolkengipfel in Tausend Nadeln herbeigerufen und besiegt wurde.",al={"schlangenhaut","arikaras haut","was ist diese haut"}},{q="Wer benötigt Arikaras Schlangenhaut?",a="Motega Firemane am Weißgipfelposten benötigt die Haut zusammen mit dem Rest des Brandpulvers als Beweis dafür, dass die Schlange keine Bedrohung mehr darstellt.",al={"wer nimmt die haut","bei wem abgeben","wer will arikaras haut"}},{q="Warum wurde Arikara überhaupt herbeigerufen?",a="Magatha Grimmtotem behauptete, dass Veränderungen der Taurentraditionen die Ahnenschlange Arikara erzürnt hätten und sie deshalb Oberster Häuptling Cairne Bloodhoof nachstelle. Sie wies an, die Bestie hervorzulocken und zu erschlagen, bevor Cairne Schaden zugefügt werden könne.",al={"warum arikara beschwören","warum arikara töten"}},{q="Woher bekommt man die Haut?",a="Sie wird direkt von Arikara erbeutet, nachdem man sie herbeiruft, indem man verzaubertes Brandpulver auf das Hochheilige Feuer des Lebens wirft, das sich auf einer Begräbnisnadel auf dem Düsterwolkengipfel befindet.",al={"wo gibt es arikaras schlangenhaut","arikara standort"}}},fp="20,231,26.474.0,22.458.1,33.136.0,35.152.0,44.245.0,31.176.0"}
P.entries["item:arnak-s-hoof"] = {n="Arnaks Huf",s="Arnaks Huf ist der makabre Totennachweis des Kriminellen Arnak Grimtotem. Nachdem er einen Taurenkollegen ermordet und dessen Schwester entführt hatte, wurde Arnak von den Verteidigern des Freiwindpostens zum Tode verurteilt und auf den Klippen des Düsterwolkengipfels zur Strecke gebracht.",h="Arnaks Huf ist der makabre Totennachweis des Kriminellen Arnak Grimtotem.",kw={"arnak","arnak grimtotem","arnaks huf","klippenbehüter longhorn","düsterwolkengipfel","freiwindposten","lakota windsong","tausend nadeln"},ang={["faction:Horde"]="Die Beseitigung von Arnak festigt die Autorität des Freiwindpostens in Tausend Nadeln und schwächt den heimtückischen Einfluss der Grimtotem, der die Versorgungswege der Horde bedroht.",["race:Tauren"]="Für die Tauren der Ebenen ist das Nehmen von Arnaks Huf ein Akt der Stammesgerechtigkeit gegen einen Abtrünnigen, dessen mörderisches Treiben Schande und Blutvergießen über Tausend Nadeln brachte."},sec={{t="Kopfgeld auf einen Ausgestoßenen",b="Arnak Grimtotem erlangte in Tausend Nadeln traurige Berühmtheit als Gesetzloser, dessen Brutalität selbst die ohnehin umstrittenen Grenzen der Clanpolitik der Tauren überschritt. Nachdem er einen anderen Tauren ermordet und die Schwester des Opfers, Lakota Windsong, entführt hatte, wurde ein offizielles Kopfgeld auf seinen Tod ausgesetzt. Arnak verschanzte sich auf den Höhen des Düsterwolkengipfels, umgeben von Wachen der Grimtotem. Ihn zu töten und seinen abgetrennten Huf an sich zu nehmen, dient Klippenbehüter Longhorn am Freiwindposten als unumstößlicher Beweis dafür, dass der Mörder endlich für seine Verbrechen zur Rechenschaft gezogen wurde."}},faq={{q="Wofür wird Arnaks Huf verwendet?",a="Arnaks Huf dient als physischer Beweis für den Tod des Gesetzlosen Arnak Grimtotem. Er wird bei Klippenbehüter Longhorn am Freiwindposten abgegeben, um das Kopfgeld abzuschließen und die versprochene Belohnung einzufordern.",al={"arnaks huf abgeben","was tun mit arnaks huf","wer braucht arnaks huf"}},{q="Wer war Arnak Grimtotem?",a="Arnak war ein Abtrünniger der Grimtotem, der wegen Mordes und Entführung gesucht wurde. Er tötete einen Stammesangehörigen der Tauren und hielt die Schwester des Opfers, Lakota Windsong, auf den Klippen des Düsterwolkengipfels gefangen.",al={"wer ist arnak","arnak grimtotem geschichte","warum wird arnak gesucht"}},{q="Wo ist Arnak Grimtotem zu finden?",a="Arnak befindet sich auf den Klippen des Düsterwolkengipfels im Norden von Tausend Nadeln, erreichbar über Hängebrücken nahe den Felsen in Richtung Die Hügel von Razorfen. Er hält seine Gefangene, Lakota Windsong, auf demselben Felsvorsprung fest.",al={"arnak grimtotem standort","wo ist arnak","arnak finden"}}},fp="12,256,20.533.0,30.200.0,24.183.0,31.211.0"}
P.entries["item:astor-s-letter-of-introduction"] = {n="Astors Vorstellungsschreiben",s="Astors Vorstellungsschreiben ist ein Dokument, das von Astor Hadren getragen wird, einem Kurier, der zwischen dem Silberwald und Undercity reist. Von angehenden Todespirschern an sich genommen, dient der Brief als Tarnung, um eine mutmaßliche Verschwörung rund um den Ladenbesitzer Andron Gant zu infiltrieren.",h="Astors Vorstellungsschreiben ist ein Dokument, das von Astor Hadren getragen wird, einem Kurier, der zwischen...",kw={"andron gant","apothecarium","astor hadren","die todespirscher","mennet carkad","silberwald","undercity","varimathras"},ang={["class:Rogue"]="Die Beschaffung und Verwendung von Astors Brief ist eine grundlegende Feldübung für Schurken der Verlassenen, die Aufnahme bei den Todespirschern anstreben, und stellt ihre Fertigkeiten in Attentat, Diebstahl und Täuschung auf die Probe.",["race:Undead"]="Das Komplott um den Brief verdeutlicht die interne Paranoia innerhalb von Undercity, wo Lord Varimathras Die Todespirscher einsetzt, um Subversion unter der Bevölkerung der Verlassenen im Keim zu ersticken."},sec={{t="Die Beglaubigung eines Kuriers",b="Astor Hadren diente als diskreter Kurier, der zwischen dem Silberwald und der Hauptstadt verkehrte. Sein persönliches Vorstellungsschreiben belegt die Vertrauenswürdigkeit des Überbringers gegenüber illegalen Kontakten in der Stadt. Als der Ausbilder der Todespirscher Mennet Carkad verdächtigen undichten Stellen innerhalb von Undercity nachgehen musste, machten Astors Reisen ihn zu einem unmittelbaren Ziel. Indem ein Agent Hadren ausschaltet oder seiner Papiere beraubt, kann er dessen Identität annehmen und geheime Mitteilungen abfangen, die allein für Astors Augen bestimmt waren."},{t="Die Falle im Apothecarium",b="Mennet Carkad nutzt den wiederbeschafften Brief, um Andron Gant zu täuschen, einen Buchhändler und Ladenbesitzer nahe dem Apothecarium. Gant wird von Lord Varimathras verdächtigt, Informationen der Verlassenen an eine unbekannte dritte Partei weiterzugeben. Bewaffnet mit Astors Brief gibt sich ein verdeckter Agent als der erwartete Kontakt aus und nutzt Gants argloses Vertrauen, um die Identität seiner Mitverschwörer aufzudecken und Beweise für seinen Verrat zu sichern."}},faq={{q="Wofür wird Astors Vorstellungsschreiben verwendet?",a="Es dient als Identitätsnachweis, um den Händler Andron Gant zu täuschen. Durch das Vorzeigen des Briefes gibt sich ein Agent als der Kurier Astor Hadren aus, um Gants geheime Machenschaften aufzudecken.",al={"zweck des briefes","was bewirkt der brief","astors vorstellungsschreiben nutzen"}},{q="Wer war Astor Hadren?",a="Astor Hadren war ein Abgesandter und Bote, der die Straßen zwischen dem Silberwald und Undercity bereiste und Korrespondenz für private Parteien beförderte, bevor er von Agenten der Todespirscher abgefangen wurde.",al={"wer ist astor","astor hadren hintergrund","wer hatte den brief"}},{q="Warum will Mennet Carkad diesen Brief?",a="Mennet Carkad benötigt den Brief, um Rekruten zu prüfen, die den Todespirschern beitreten wollen, und um eine verdeckte Operation gegen Andron Gant durchzuführen, den Lord Varimathras des Verrats verdächtigt.",al={"warum mennet ihn braucht","carkads plan"}},{q="Schöpft Andron Gant Verdacht, dass der Brief gestohlen ist?",a="Nein. Mennet merkt an, dass Gant nicht den Verstand besitzt, ein falsches Spiel zu vermuten, und Gant akzeptiert den Überbringer des Briefes ohne Zögern als den gewöhnlichen Boten, der von seinen Mitverschwörern gesandt wurde.",al={"bemerkt gant etwas","wird andron getäuscht"}}},fp="30,269,23.494.0,29.434.1,48.178.0,21.203.0,40.174.0,46.158.1"}
P.entries["item:ataeric-s-staff"] = {n="Ataerics Stab",s="Ataerics Stab ist ein mächtiger magischer Kanalisator, der von Erzmagier Ataeric geführt wird, einem hochrangigen Zauberer aus Dalaran im Silberwald. Er dient sowohl als Fokus zur Manipulation lokaler Ley-Linien als auch als physischer Beweis für die Niederlage des Erzmagiers für die Verlassenen im Grabmal.",h="Ataerics Stab ist ein mächtiger magischer Kanalisator, der von Erzmagier Ataeric geführt wird, einem...",kw={"erzmagier ataeric","ataerics stab","dalaran","ley-knoten","das grabmal","schattenpriester allister","silberwald","der wirker"},ang={["class:Mage"]="Der Stab veranschaulicht die fokussierten Werkzeuge, die Dalarans Erzmagier nutzen, um schlummernde Ley-Knoten anzuzapfen und wiederzuerwecken.",["race:Undead"]="Die Bergung des Stabs stoppt Dalarans wachsende Kontrolle über die magischen Reserven des Silberwalds und sichert die westlichen Grenzen der Verlassenen."},sec={{t="Ein Kanalisator für Ley-Magie",b="Dieser von Erzmagier Ataeric getragene Stab wurde genutzt, um Ley-Energien im südlichen Silberwald zu lenken und nutzbar zu machen. Unter der Führung von Dalaran versuchte Ataeric, einen uralten Ley-Energieknoten nahe den Grenzen des Gebiets der Magokratie zu reaktivieren. Der Stab fungierte als unverzichtbares Werkzeug zum Weben dieser gewaltigen Umgebungsströmungen, was den Erzmagier zu einer gewaltigen Bedrohung für nahegelegene Siedlungen der Verlassenen machte."},{t="Trophäe des Grabmals",b="Beunruhigt über Dalarans magische Ausbreitung ordnete Schattenpriester Allister die Ermordung von Ataeric an und forderte die Beschaffung des Stabs. Nachdem Ataeric getötet und sein Stab geborgen worden war, fielen die konzentrierten Ley-Energien wieder in einen Ruhezustand zurück. Das Bringen des Stabs zum Grabmal markierte einen entscheidenden Sieg gegen Dalarans Ambitionen, auch wenn die Verlassenen hinsichtlich der in der Erde verbleibenden latenten Macht weiterhin wachsam bleiben."}},faq={{q="Wem gehört Ataerics Stab?",a="Der Stab gehört Erzmagier Ataeric, einem hochrangigen Zauberer aus Dalaran, der im Silberwald stationiert ist, um die Reaktivierung eines mächtigen Ley-Knotens zu überwachen.",al={"wem gehört ataerics stab","ataeric besitzer","wer lässt diesen stab fallen"}},{q="Warum will Schattenpriester Allister Ataerics Stab?",a="Schattenpriester Allister im Grabmal verlangt den Stab als Bestätigung für den Tod von Erzmagier Ataeric und um sicherzustellen, dass Dalarans Bemühungen zur Manipulation der Ley-Linien der Region vollständig gebrochen sind.",al={"warum will allister den stab","zweck stab grabmal","wer nimmt den stab"}},{q="Was passiert, sobald der Stab Erzmagier Ataeric abgenommen wird?",a="Sobald Ataeric getötet und sein Stab entfernt wurde, verflüchtigen sich die von Dalaran gewobenen Ley-Energien und verfallen in einen Ruhezustand, womit die unmittelbare magische Bedrohung für die Verlassenen endet.",al={"was passiert mit der ley-linie","nach dem besiegen von ataeric"}},{q="Wo findet man Ataerics Stab?",a="Er wird direkt von der Leiche von Erzmagier Ataeric erbeutet, der sich unter anderen Magiern und Wächtern von Dalaran nahe Dalarans Präsenz im südlichen Silberwald befindet.",al={"woher bekommt man ataerics stab","ataeric aufenthaltsort"}}},fp="15,258,22.398.0,23.409.0,35.149.0,53.196.0,59.170.1,31.165.0"}
P.entries["item:athrikus-narassin-s-head"] = {n="Athrikus Narassins Kopf",s="Dieser abgetrennte Kopf ist der Beweis für den Tod von Athrikus Narassin, einem uralten Hexenmeister, der finstere Rituale an der nördlichen Darkshore leitete. Er stammt von den Höhen der verfallenen Turmspitze und dient als Bestätigung dafür, dass die dämonischen Aktivitäten rund um den Turm von Althalaxx zerschlagen wurden.",h="Dieser abgetrennte Kopf ist der Beweis für den Tod von Athrikus Narassin, einem uralten Hexenmeister, der...",kw={"althalaxx","athrikus narassin","kultisten","darkshore","teufelsmagie","abgetrennter kopf","hexenmeister"},ang={["class:Warlock"]="Athrikus' Beherrschung der Teufelsmächte machte ihn zu einem furchterregenden Anwender, doch seine unvorsichtige Sichtbarkeit in Althalaxx wurde ihm zum Verhängnis.",["race:NightElf"]="Die Beseitigung von Athrikus Narassin tilgt eine schwärende dämonische Plage aus uralten Ruinen der Kaldorei an den nördlichen Gestaden von Kalimdor."},sec={{t="Die Plage von Althalaxx",b="Von der Spitze des Turms von Althalaxx aus befehligte Athrikus Narassin einen Zirkel finsterer Hexer, die entlang der Küste von Darkshore Teufelsmagie ausübten. Uralt und fest verwurzelt koordinierte Narassin dämonische Beschwörungen, welche die umliegende Wildnis bedrohten. Seinen Kopf zu fordern, bricht die Führung des Zirkels und vertreibt ihre unmittelbare Präsenz in der Region, auch wenn die verbleibende Verderbnis künftige Wachsamkeit erforderlich machen wird."}},faq={{q="Wer war Athrikus Narassin?",a="Athrikus Narassin war ein uralter und mächtiger Hexenmeister, der die im Turm von Althalaxx an der nördlichen Darkshore verschanzten Kultisten anführte. Er leitete die dämonischen Rituale des Zirkels von der obersten Spitze des Turms aus.",al={"wer ist athrikus","athrikus geschichte","wer ist der hexenmeister"}},{q="Warum wird sein Kopf benötigt?",a="Späher der Allianz, die den Turm von Althalaxx überwachen, benötigen einen unwiderlegbaren Beweis dafür, dass der Meisterhexenmeister getötet wurde. Das Vorzeigen seines abgetrennten Kopfes bestätigt sein Ableben und kennzeichnet den Schlag gegen die dämonischen Streitkräfte als Erfolg.",al={"warum den kopf nehmen","zweck von athrikus kopf","wozu dient der kopf"}},{q="Wo befindet sich Athrikus Narassin?",a="Er hält sich ganz oben auf der Spitze des Turms von Althalaxx an der nördlichen Darkshore auf, schwer bewacht von seinen ergebenen Kultisten und beschworenen Dämonen.",al={"wo findet man athrikus","athrikus aufenthaltsort","turm von althalaxx spitze"}},{q="Beseitigt sein Tod die dämonische Bedrohung vollständig?",a="Während Athrikus' Tod den finsteren Ritualisten einen schweren Schlag versetzt und ihre derzeitigen Operationen zerstreut, glauben die Späher, dass sich die dämonischen Streitkräfte letztendlich neu formieren werden, was eine anhaltende Verteidigung von Darkshore erfordert.",al={"sind die dämonen fort","ist der turm gereinigt","wurde der kult besiegt"}}},fp="24,269,21.439.0,26.213.0,23.225.0,35.149.0,57.203.0"}
P.entries["item:bag-of-empty-ooze-containers"] = {n="Tasche mit leeren Brühschlammerbehältern",s="Die Tasche mit leeren Brühschlammerbehältern ist ein Set steriler Glaswaren, das von der Gnomforscherin Laris Geardawdle in Ironforge bereitgestellt wird. Für heikle Feldsammlungen vorbereitet, enthält sie leere Probengläser, die dazu bestimmt sind, unberührte, unverworbene Schlammproben aus ganz Azeroth einzufangen.",h="Die Tasche mit leeren Brühschlammerbehältern ist ein Set steriler Glaswaren, das von der Gnomforscherin Laris...",kw={"tasche mit leeren brühschlammerbehältern","empty pure sample jar","ironforge","laris geardawdle","brühschlammerbehälter","reines probenglas","schlamm"},ang={["faction:Alliance"]="Laris Geardawdle koordiniert ihre ökologische Forschung von Ironforge aus und schickt Abenteurer der Allianz tief in ungezähmte Gebiete wie den Un'Goro-Krater, um entscheidende Feldproben zu beschaffen.",["race:Gnome"]="Die langlebigen, chemikalienbeständigen Gläser in der Tasche spiegeln den typischen gnomischen Erfindungsreichtum wider und ermöglichen es Feldforschern, gefährliche, ätzende Wildtierproben sicher zu transportieren."},sec={{t="Feldforschungsausrüstung",b="Bei der Erforschung der bizarren Biologie von Azeroths Brühschlammern erkannte Laris Geardawdle, dass Schlammkreaturen die Verderbnis ihrer Umgebung rasch in sich aufnehmen und widerspiegeln. Nachdem die Gnomwissenschaftlerin verdorbene Rückstände aus Orten wie dem Teufelswald studiert hatte, gab sie diese robusten Probengläser in Auftrag, um ätzenden Proben standzuhalten und gleichzeitig ihren natürlichen Zustand zu bewahren. Die Tasche enthält genügend Gläser für Forscher, um sauberen, unverschmutzten Schlamm aus wilden, unberührten Regionen zu sammeln – allen voran aus der urzeitlichen Wildnis des Un'Goro-Kraters, wo uralte klebrige Schlämme frei von dämonischer Verderbnis gedeihen."}},faq={{q="Was befindet sich in der Tasche mit leeren Brühschlammerbehältern?",a="Die Tasche enthält zehn Empty Pure Sample Jars, speziell gefertigte Glasgefäße, die dazu dienen, ätzende Schlammproben sicher aufzubewahren, ohne die Probe zu zersetzen oder zu kontaminieren.",al={"was ist in der tasche","tascheninhalt","inhalt brühschlammerbehälter"}},{q="Wer hat diese Behälter bereitgestellt?",a="Sie werden von Laris Geardawdle bereitgestellt, einer exzentrischen Gnomforscherin, die von der Hall of Explorers in Ironforge aus operiert und die Umweltanpassungen von Schlamm studiert.",al={"wer gibt die brühschlammertasche","laris geardawdle tasche","wer gibt tasche mit leeren brühschlammerbehältern"}},{q="Welche Art von Schlämmen soll mit diesen Gläsern gesammelt werden?",a="Die Gläser sind für reine, unverworbene Schlammproben gedacht. Anders als die verheerten Exemplare aus dem Teufelswald kann unberührter Schlamm von den klebrigen Schlämmen gesammelt werden, die den Un'Goro-Krater bewohnen.",al={"welcher schlamm gehört in die gläser","ziel für reine probengläser","wo gläser füllen"}},{q="Warum benötigt Laris reine Schlammproben?",a="Laris erkannte, dass Schlämme die Eigenschaften ihrer Umgebung wie ein biologischer Schwamm aufsaugen. Um zu verstehen, wie diese Anpassung funktioniert, benötigt sie ein unverworbenes Referenzexemplar, um es mit verunreinigten Schlämmen aus verheerten Regionen zu vergleichen.",al={"warum reinen schlamm sammeln","geardawdle forschungsziel","warum reine schlämme"}}},fp="28,267,24.585.0,48.171.0,30.176.0,51.186.0,38.235.0"}
P.entries["item:balnir-snapdragons"] = {n="Balnirlöwenmäulchen",s="Balnirlöwenmäulchen sind leuchtende Blumen, die auf Balnirs Bauernhof im östlichen Tirisfal kultiviert werden. Da sie von Natur aus empfänglich für magische Strömungen sind, dienen sie den Verlassenen als feinfühlige Indikatoren, um das Vordringen des Verderbens der Geißel aus den angrenzenden Pestländern zu erkennen.",h="Balnirlöwenmäulchen sind leuchtende Blumen, die auf Balnirs Bauernhof im östlichen Tirisfal kultiviert werden.",kw={"anastasia hartwell","balnirs bauernhof","balnirlöwenmäulchen","invincible","mage quarter","pestländer","tirisfal","vara balnir"},ang={["class:Mage"]="Magier der Verlassenen erforschen Balnirlöwenmäulchen als rohe magische Leiter und nutzen ihre natürliche Empfindsamkeit, um zu messen, wie magische Seuchen die umgebenden Leylinien verzerren.",["race:Undead"]="Für die Verlassenen bieten die Blumen eine praktische Überwachung an ihrer Ostgrenze und warnen die Forscher von Undercity davor, wenn die Verderbnis des Lichkönigs den Boden von Tirisfal überwältigt."},sec={{t="Eine Blüte im Ruin",b="Ursprünglich vor dem Fall von Lordaeron von Vara Balnir gehegt, überstanden diese farbenfrohen Blüten wie durch ein Wunder den Tod der Familie Balnir und den Aufstieg der Geißel. Selbst als Prinz Arthas zum entweihten Gehöft zurückkehrte, um sein Streitross Invincible zu erwecken, standen die Löwenmäulchen in voller Blüte, unberührt von der Fäulnis, die das umliegende Königreich heimsuchte. Ihre anhaltende Widerstandskraft gegen dunkle Magie macht sie zu einem bemerkenswerten Blickfang inmitten des Verfalls von Tirisfal."},{t="Magische Barometer",b="Weil Löwenmäulchen ungewöhnlich empfindlich auf atmosphärische Magie reagieren, fungieren sie als lebende Barometer für magische Seuchen. Anastasia Hartwell und die Magier der Verlassenen in Undercity verlangen nach frischen Exemplaren aus den Blumenkästen des Gehöfts. Durch die Übergabe der Pflanzen an die Königliche Apothekervereinigung hofft Undercity, die Flora zu analysieren und zu ermitteln, wie tief die Seuche des Lichkönigs bereits über die Grenze hinweg in den Boden von Tirisfal eingesickert ist."}},faq={{q="Wo sind Balnirlöwenmäulchen zu finden?",a="Sie wachsen in Blumenkästen und Gartenbeeten rund um das verfallene Balnirs Bauernhof, gelegen in den östlichen Weiten von Tirisfal nahe der Grenze zu den Westlichen Pestländern.",al={"balnirlöwenmäulchen fundort","wo sind die blumen","balnir blumen ort"}},{q="Warum verlangt Anastasia Hartwell nach diesen Löwenmäulchen?",a="Löwenmäulchen nehmen latente magische Energien leicht auf. Anastasia Hartwell möchte, dass den Apothekern von Undercity frische Exemplare geliefert werden, um festzustellen, ob das magische Verderben der Pestländer aktiv nach Tirisfal übergreift.",al={"warum löwenmäulchen sammeln","balnirs bauernhof questziel","anastasia hartwell löwenmäulchen"}},{q="Wer baute diese Blumen ursprünglich an?",a="Sie waren der ganze Stolz von Vara Balnir, die sie auf dem Bauernhof ihrer Familie hegte, bevor der Dritte Krieg die ländlichen Siedlungen Lordaerons auslöschte.",al={"wer pflanzte balnirlöwenmäulchen","vara balnir blumen","familie balnir löwenmäulchen"}},{q="Hat die Geißel die Balnir-Blumen vernichtet?",a="Nein. Bemerkenswerterweise blieben die Löwenmäulchen selbst nach der Ermordung der Balnirs in voller Blüte. Arthas bemerkte ihr Überleben, als er zum Gehöft zurückkehrte, um sein Pferd Invincible zu erwecken, wenngleich er vermied, sie zu berühren, damit seine tödliche Gegenwart die Blütenblätter nicht welken ließ.",al={"löwenmäulchen durch seuche zerstört","arthas balnir blumen"}}},fp="18,267,15.462.0,18.429.0,38.171.0,51.228.0,34.146.0,43.257.0"}
P.entries["item:baron-longshore-s-head"] = {n="Baron Küstenschippers Kopf",s="Dieser abgetrennte Kopf ist der Beweis für den Tod von Baron Longshore, dem Kapitän des Schiffs Heedless der Südmeerfreibeuter. Gazlowe setzte ein öffentliches Kopfgeld auf die identifizierbaren Überreste des Piraten aus, um Ratchets Handelsschifffahrt entlang der Händlerküste zu schützen.",h="Dieser abgetrennte Kopf ist der Beweis für den Tod von Baron Longshore, dem Kapitän des Schiffs Heedless der...",kw={"baron longshore","kopfgeld","gazlowe","gilneas","heedless","die händlerküste","ratchet","südmeerfreibeuter"},ang={["race:Human"]="Gazlowes Kopfgeld bemerkt, dass Longshore aus der isolationistischen Nation Gilneas stammte, bevor er sich mit den Südmeerfreibeutern der Hochseepiraterie zuwandte."},sec={{t="Ein Kopfgeld auf einen Freibeuter",b="Von Lagern entlang der Händlerküste südlich von Ratchet aus leitete Baron Longshore im Auftrag der Südmeerfreibeuter Überfälle auf regionale Handelsschiffe. Sein Flaggschiff, die Heedless, stellte eine direkte Bedrohung für die Handelsrouten der Goblins dar, die Kalimdor mit den Östlichen Königreichen verbinden. Gazlowe, der Chefingenieur von Ratchet, setzte ein Kopfgeld auf Longshore aus, das einen eindeutigen Beweis des Ablebens verlangt. Die Übergabe des Piratenkopfs erfüllt den Vertrag und sichert eine finanzielle Belohnung von der Hafenbehörde."}},faq={{q="Wer war Baron Longshore?",a="Er war ein Piratenkapitän, der aus dem Menschenkönigreich Gilneas stammte. Als Anführer von Südmeerfreibeutern aus Lagern entlang der Händlerküste südlich von Ratchet terrorisierte er an Bord seines Schiffs, der Heedless, die Schifffahrtsrouten.",al={"baron longshore","wer ist longshore","kapitän longshore"}},{q="Wer will Baron Küstenschippers Kopf?",a="Gazlowe, der Goblin-Anführer von Ratchet, hat den Steckbrief ausgehängt. Die Südmeerfreibeuter machten Jagd auf Handelsschiffe aus Ratchet, was Gazlowe dazu veranlasste, Longshores identifizierbare Überreste zu fordern, um sicherzustellen, dass der Handel seines Hafens ungestört bleibt.",al={"wer will den kopf","bei wem abzugeben","gazlowe kopfgeld"}},{q="Wo ist Baron Longshore zu finden?",a="Longshore patrouilliert in drei Piratenlagern der Südsee an der Küste südlich von Ratchet, direkt nördlich von der Feste Northwatch entlang der Händlerküste.",al={"wo ist longshore","longshore aufenthaltsort","baron longshore spawn"}},{q="Welches Schiff befehligte Baron Longshore?",a="Er befehligte die Heedless, ein gefürchtetes Schiff, das Handelsschiffe überfiel, die auf dem Großen Meer vor der Küste des Brachlands verkehrten.",al={"longshore schiff","die heedless","heedless schiff"}}},fp="22,247,22.499.0,24.211.0,33.242.0,31.151.0,38.128.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="Fass mit Gerstenbräu",s="Das Fass mit Gerstenbräu ist ein Fass mit kräftigem Starkbier, das von der Familie Gerstenbräu gebraut wurde, um ihr Braukönnen gegenüber ihren Hauptkonkurrenten unter Beweis zu stellen. Es wird heimlichen Boten anvertraut, die den Auftrag haben, die Brauerei Donnerbräu in Kharanos zu infiltrieren, um eine schlaue Geschmackstest-Sabotage zu inszenieren.",h="Das Fass mit Gerstenbräu ist ein Fass mit kräftigem Starkbier, das von der Familie Gerstenbräu gebraut wurde...",kw={"bier","gerstenbräu","brauerei","dun morogh","kharanos","marleth","starkbier","donnerbräu"},ang={["class:Rogue"]="Eine Kellerwache abzulenken und schwere Schmuggelware in ein bewachtes Lager zu schleichen, bietet eine amüsante, harmlose Übung in klassischer Zwergenlist.",["race:Dwarf"]="Für Zwerge ist das Brauen von Bier sowohl eine Kunst als auch ein Blutsport; die Teilnahme an Kellerintrigen darüber, wessen Rezept überlegen ist, ist praktisch ein Zeitvertreib in Dun Morogh."},sec={{t="Eine bittere Fehde in Dun Morogh",b="Das Brauen ist unter den Zwergen von Dun Morogh ein ernstes Geschäft, und nur wenige Rivalitäten brennen heißer als die Fehde zwischen den Donnerbräus und den Gerstenbräus. Während die Donnerbräus aus ihrer belebten Brauerei in Kharanos großes Ansehen und eine stolze Stellung genießen, weigert sich Marleth Gerstenbräu, in ihrem Schatten zu stehen. Anstatt sich nur auf offene Tavernen zu verlassen, braut Marleth das feurige Starkbier, um zu beweisen, dass seine Rezepte unübertroffen sind – in der Hoffnung, dass ahnungslose Gäste, die es probieren, erkennen, dass die Donnerbräus kein Monopol auf feine Zwergengetränke haben."},{t="List im Keller",b="Das Fass soll direkt in die Keller unter der Brauerei Donnerbräu geschmuggelt werden und den Platz mit einem Fass des lokalen Favoriten, Donnerbier, tauschen. Die Absicht ist weder giftig noch zerstörerisch, sondern ein frecher Zwergenstreich, der auf verletzten Stolz abzielt: sicherzustellen, dass die nächste oben servierte Charge heimlich stattdessen Gerstenbräus wirksames Starkbier ist."}},faq={{q="Was befindet sich im Fass mit Gerstenbräu?",a="Es enthält Marleth Gerstenbräus unverkennbares Starkbier, ein kräftiges Zwergengebräu, das geschaffen wurde, um mit den berühmten Rezepten der Familie Donnerbräu zu konkurrieren.",al={"inhalt fass mit gerstenbräu","welche art bier","was ist das starkbier"}},{q="Warum möchte Marleth dieses Fass austauschen?",a="Marleth gibt zu, dass die Donnerbräus gute Getränke herstellen, aber er möchte sie Demut lehren, indem er die Kellergäste versehentlich sein eigenes Gebräu kosten lässt, damit sie sehen, dass die Braukunst der Gerstenbräus genauso gut, wenn nicht sogar besser ist.",al={"warum fässer tauschen","bittere rivalen grund","warum marleth bier einschleicht"}},{q="Wohin gehört dieses Fass?",a="Es wird hinab in den Keller unter der Brauerei Donnerbräu in Kharanos gebracht und in die Regale getauscht, wo ein Fass Donnerbier angezapft werden soll.",al={"wohin fass bringen","fass mit gerstenbräu ort","brauereikeller"}},{q="Soll das Gebräu jemandem schaden?",a="Nein. Es ist einfach ein starkes, konkurrierendes Zwergenbier. Die Rivalität zwischen den Familien ist intensiv und voller Konkurrenzdenken, aber es ist eine Frage des beruflichen Stolzes und keine Bosheit.",al={"ist das bier vergiftet","ist es gift","wird es jemandem schaden"}}},fp="28,287,27.543.0,24.337.1,48.135.0,42.215.0,26.155.0,33.171.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="Fass mit Schimmerstarkbier",s="Ein frisch gebrautes Fass von Rejold Gerstenbräus experimentellem Zwergenstarkbier, hergestellt in den kalten Weiten von Dun Morogh. Es ist dafür bekannt, Trinkern einen kräftigen Schub zu verleihen, der angeblich ihre Sicht erhellt, und ist als Geschenk für die Wachen auf den hohen Gebirgspässen gedacht.",h="Ein frisch gebrautes Fass von Rejold Gerstenbräus experimentellem Zwergenstarkbier, hergestellt in den kalten...",kw={"fass mit schimmerstarkbier","dun morogh","zwergenbier","loch modan","gebirgsjäger gerstenbräu","rejold gerstenbräu","schimmerstarkbier"},ang={["profession:Cooking"]="Zwergenbiere erweitern häufig die Grenzen kulinarischer Experimente und vereinen starke Gärung mit robusten Gebirgszutaten, um beißendem Wetter standzuhalten.",["race:Dwarf"]="Das Brauen ist ein kultureller Eckpfeiler der Gesellschaft von Ironforge, und einem Verwandten auf Wache ein frisch vollendetes Starkbier zu bringen, ist eine ehrenvolle Gebirgstradition."},sec={{t="Der Stolz eines Brauers",b="Nachdem Rejold Gerstenbräu in ganz Dun Morogh seltene Zutaten gesammelt hatte, braute er das Schimmerstarkbier – der jüngste Triumph der geschichtsträchtigen Gerstenbräu-Familie. Zwergenbrauer nehmen ihr Handwerk todernst und wetteifern ständig darum, herzhafte Gebräue zu kreieren, die der eisigen Kälte der Berge trotzen können. Rejolds neuestes Rezept soll nicht nur den Magen wärmen, sondern auch die Sinne derjenigen schärfen, die im eisigen Wind Wache halten."},{t="Vorräte für die Wache",b="Dieses spezielle Fass ist für Gebirgsjäger Wellart Barleybrew bestimmt, der am südlichen Turm entlang des Passes nach Loch Modan Wache hält. An der einsamen Grenze trotzen die Gebirgsjäger knochenbleichender Kälte und langen Wachschichten zwischen Scharmützeln mit Troggs und wilden Tieren. Ein frisches Fass Familienbier dient sowohl als willkommener Geschmack der Heimat als auch als belebendes Tonikum, das stark genug ist, um einen müden Wachposten schwören zu lassen, er könne klar durch die Dunkelheit blicken."}},faq={{q="Was befindet sich im Fass mit Schimmerstarkbier?",a="Es enthält Schimmerstarkbier, ein brandneues Zwergenrezept, das von Rejold Gerstenbräu kreiert wurde. Das Getränk ist berühmt für seinen bemerkenswert starken Kick, der jedem, der es probiert, ein energiegeladenes Gefühl und ein buchstäbliches Funkeln in den Augen verleiht.",al={"was ist schimmerstarkbier","was für ein bier ist das","schimmerstarkbier getränk"}},{q="Wer hat dieses Fass Starkbier hergestellt?",a="Das Starkbier wurde von Rejold Gerstenbräu gebraut, einem Mitglied des renommierten Gerstenbräu-Klans von Dun Morogh, der viel Zeit damit verbracht hat, ein Rezept zu perfektionieren, um seine Verwandten zu beeindrucken.",al={"wer braute schimmerstarkbier","schimmerstarkbier brauer","rejold gerstenbräu"}},{q="Für wen ist dieses Fass bestimmt?",a="Es ist für Rejolds Bruder bestimmt, Gebirgsjäger Wellart Barleybrew, der am südlichen Wachturm entlang der Straße nach Loch Modan stationiert ist.",al={"wer bekommt das fass","wohin geht das starkbier","wellart barleybrew"}},{q="Welche Wirkung hat Schimmerstarkbier auf jemanden, der es trinkt?",a="Abgesehen von einem kräftigen Rausch verleiht das Starkbier den Trinkern einen intensiven Energieschub, der ihre Augen funkeln lässt und ihnen das Gefühl gibt, in stockfinsterer Nacht sehen zu können, was es bei wachsamen Gebirgsjägern überaus beliebt macht.",al={"schimmerstarkbier wirkung","lässt es einen im dunkeln sehen","was bewirkt schimmerstarkbier"}}},fp="23,272,16.452.0,22.454.0,39.221.0,30.150.0,29.145.0,61.208.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="Fass mit Donnerbier",s="Das Fass mit Donnerbier ist ein geschätztes Fass des unverwechselbaren Gebräus aus Kharanos, direkt aus dem Keller der Brauerei Donnerbräu geschmuggelt. Ausgetauscht gegen ein explosives Fass von Marleth's Scalder, dient es als unbestreitbarer Beweis für ein falsches Spiel in einer eskalierenden Brauereirivalität.",h="Das Fass mit Donnerbier ist ein geschätztes Fass des unverwechselbaren Gebräus aus Kharanos, direkt aus dem...",kw={"fass mit donnerbier","brewnall","dun morogh","kharanos","marleth gerstenbräu","donnerbier","donnerbräu"},ang={["class:Rogue"]="Sich in einen bewachten Keller zu schleichen und schwere Bierfässer auszutauschen, ohne Alarm zu schlagen, ist ein klassischer, praktischer Beweis für Heimlichkeit und Raffinesse.",["race:Dwarf"]="Für Zwerge ist das Bierbrauen ein ernstes Geschäft und hohe Politik; das geschätzte Fass eines rivalisierenden Clans in dessen eigenem Keller auszutauschen, ist eine kühne Beleidigung."},sec={{t="Ein bitterer Handel",b="In Dun Morogh sitzt der Konkurrenzkampf zwischen rivalisierenden Braumeistern tief, und nur wenige Streitigkeiten sind erbitterter als die Fehde zwischen den Donnerbräus aus Kharanos und den Gerstenbräus aus Brewnall. Marleth Gerstenbräu braute ein feuriges Starkbier namens Marleth's Scalder zusammen, um die Vorräte seiner Rivalen im Keller zu sabotieren. Dieses schwere Fass mit Donnerbier wurde bei dem Austausch entwendet und direkt unter den Augen der örtlichen Wachen weggeschafft – als handfester Beweis dafür, dass der Tausch geglückt ist."}},faq={{q="Was befindet sich in diesem Fass?",a="Es enthält Donnerbier, das berühmte Starkbier, das von der Familie Donnerbräu unten in Kharanos gebraut wird. Es ist in ganz Dun Morogh als kräftiges, starkes Zwergenbier bekannt.",al={"inhalt von donnerbier","was ist donnerbier"}},{q="Woher stammt dieses Fass?",a="Es wurde direkt aus dem Lagerkeller der Brauerei in Kharanos entwendet, mitgenommen während der heimlichen Lieferung von Marleths rivalisierendem Gebräu.",al={"wo bekommt man es","donnerbier fundort"}},{q="Wer will dieses Fass haben?",a="Marleth Gerstenbräu, der sich in Brewnall im Westen aufhält. Er erwartet, dass ihm das Fass als Beweis dafür gebracht wird, dass sein Scalder erfolgreich unter den Fässern der Donnerbräus platziert wurde.",al={"wem bringt man donnerbier","marleth gerstenbräu quest"}},{q="Warum wurde das Fass entwendet?",a="Marleth wollte einen handfesten Beweis dafür, dass es jemandem gelungen ist, sich in den Keller von Donnerbräu zu schleichen, an der Brauereiwache vorbeizukommen und die Vorräte seiner Konkurrenten zu sabotieren.",al={"warum donnerbier stehlen","bittere rivalen geschichte"}}},fp="21,266,14.450.0,27.154.0,32.140.0,22.181.0,25.158.0"}
P.entries["item:barrow-key"] = {n="Grabhügel-Schlüssel",s="Der Grabhügel-Schlüssel ist einer von drei druidischen Schlüsseln, die im Krallenbau auf dem Steinkrallengipfel versteckt sind. Er wird in einem Grabhügelversteck unter Verschluss gehalten, um die uralten Schätze zu schützen, die im Hort des Baus versiegelt sind.",h="Der Grabhügel-Schlüssel ist einer von drei druidischen Schlüsseln, die im Krallenbau auf dem...",kw={"grabhügel-schlüssel","klauen-schlüssel","torhüterschlüssel","schläfer-schlüssel","der steinkrallengipfel","der krallenbau","hort des krallenbaus","der höhlenbau"},ang={["class:Druid"]="Der Schlüssel ist Teil eines uralten Sicherheitsritus, den die Druiden des Krallenbaus schufen, um heilige Besitztümer in ihrem unterirdischen Sanktum zu schützen.",["faction:Horde"]="Agenten der Horde im Steinkrallengebirge entlocken gefangenen Nachtelfen Informationen, um diesen Schlüssel zu finden und den privaten Hort der Druiden zu plündern."},sec={{t="Schutzvorkehrung eines Wächters",b="In den unterirdischen Grabhügeln des Krallenbaus errichteten die Nachtelfen-Druiden kunstvolle Schutzvorrichtungen, um ihre Relikte vor Eindringlingen zu schützen. Der Grabhügel-Schlüssel ist ein Teil dieses vielschichtigen Schlosses und verborgen in einem speziellen Versteck tief in den unterirdischen Gängen. Um an ihn zu gelangen, ist der Torhüterschlüssel erforderlich, wodurch sichergestellt wird, dass nur jene mit Wissen über das Verteidigungsnetzwerk der Druiden ihn jemals an sich nehmen können."},{t="Das Öffnen des Horts",b="Zusammen mit dem Klauen-Schlüssel und dem Schläfer-Schlüssel passt der Grabhügel-Schlüssel zu drei kunstvoll verzierten Schlüssellöchern in einem Steinaltar tief im Krallenbau. Werden alle drei gleichzeitig gedreht, lösen sich die Schutzzauber auf und offenbaren den verborgenen Hort druidischer Relikte jedem, dem es gelingt, die Barriere zu brechen."}},faq={{q="Wofür wird der Grabhügel-Schlüssel verwendet?",a="Der Grabhügel-Schlüssel wird zusammen mit dem Klauen-Schlüssel und dem Schläfer-Schlüssel verwendet, um den Hort des Krallenbaus aufzuschließen – eine Steintruhe tief im Steinkrallengipfel, die geschützte Relikte der Druiden birgt.",al={"zweck des grabhügel-schlüssels","was öffnet der grabhügel-schlüssel","nutzen des grabhügel-schlüssels"}},{q="Wo ist der Grabhügel-Schlüssel versteckt?",a="Er ist in einem Grabhügelversteck eingeschlossen – das einer verborgenen Wandfackel ähnelt – und befindet sich tief in den gewundenen Tunneln des Krallenbaus auf dem Steinkrallengipfel.",al={"grabhügel-schlüssel fundort","wo ist der grabhügel-schlüssel","grabhügel-schlüssel finden"}},{q="Wie öffnet man das Versteck mit dem Grabhügel-Schlüssel?",a="Ihr müsst zuerst den Torhüterschlüssel beschaffen, den die Druiden in einer kleinen Laterne nahe dem Haupteingang des Krallenbaus versteckt haben.",al={"grabhügelversteck öffnen","grabhügel-schlüssel freischalten","torhüterschlüssel grabhügel"}},{q="Wer hat den Grabhügel-Schlüssel im Krallenbau versteckt?",a="Die Nachtelfen-Druiden des Steinkrallengipfels ersannen das ausgeklügelte Sicherheitssystem, um ihre mächtigen Artefakte vor feindlichen Händen zu bewahren, und versteckten die einzelnen Schlüssel in verschiedenen Winkeln des Baus.",al={"wer schuf den grabhügel-schlüssel","wer versteckte die schlüssel im krallenbau"}}},fp="10,195,22.413.0,19.315.1,32.174.0,31.149.0,52.136.0,43.205.0"}
P.entries["item:bartleby-s-mug"] = {n="Bartlebys Becher",s="Bartlebys Becher ist das persönliche Trinkgefäß des starrsinnigen Raufbolds Bartleby in Stormwind. Erst nach einer Kneipenschlägerei herausgegeben und bis auf den letzten Tropfen geleert, dient er als Beweis für die Fähigkeit eines Kriegers, einen unkooperativen Widersacher mit Nachdruck zu überzeugen.",h="Bartlebys Becher ist das persönliche Trinkgefäß des starrsinnigen Raufbolds Bartleby in Stormwind.",kw={"bartleby","bartlebys becher","burlguard","stormwind","kneipenschlägerei","die ausbildung eines kriegers"},ang={["class:Warrior"]="Diesen Becher Bartleby zu entreißen ist ein früher Übergangsritus für junge Krieger der Allianz, der sie lehrt, sich auf pure Entschlossenheit und Waffengewalt zu verlassen, wenn Worte versagen."},sec={{t="Die Trophäe eines Raufbolds",b="Für den gewöhnlichen Schankstammgast ist Bartlebys Becher nichts weiter als schlichtes Trinkgeschirr, das von einem berüchtigt starrköpfigen Trinker fest umklammert wird. Für einen unerfahrenen Krieger, der in Stormwind ausgebildet wird, ist das Entreißen des Gefäßes von Bartleby jedoch eine Prüfung reiner körperlicher Überlegenheit. Bartleby gibt seinen geliebten Becher nicht her, bis er zur Unterwerfung geprügelt wurde – und selbst dann besteht er darauf, jeden letzten Tropfen auszutrinken, bevor er ihn als Trophäe übergibt."}},faq={{q="Wofür wird Bartlebys Becher verwendet?",a="Bartlebys Becher dient als Siegesbeweis bei einer Ausbildungsprüfung für Krieger. Bringt man ihn zum Ausbilder zurück, zeigt dies, dass der Krieger mit einem starrsinnigen Kneipenraufbold fertigwerden und ihn dazu zwingen konnte, seinen wertvollsten Besitz herauszugeben.",al={"bartlebys becher zweck","warum brauche ich bartlebys becher","was bewirkt der becher"}},{q="Wem gehört der Becher ursprünglich?",a="Der Becher gehört Bartleby, einem streitlustigen Trinker, der seine Zeit mit Trinken und Raufen verbringt. Er weigert sich, den Becher herauszugeben, bis ihn ein angehender Krieger in einem Faustkampf besiegt – und selbst dann erst, nachdem er seinen Trunk geleert hat.",al={"wer ist bartleby","bartlebys besitzer","wer hat den becher"}},{q="Wer verlangt nach Bartlebys Becher?",a="Der Becher wird zu Burlguard gebracht, einem Kriegerlehrer in Stormwind, der die Schlägerei beobachtet und den Becher als Beweis verlangt, bevor er die Kampfausbildung des Kriegers fortsetzt.",al={"wer will den becher","wem gebe ich bartlebys becher","bartlebys becher abgeben"}}},fp="14,258,17.433.0,32.228.0,28.222.0,28.167.0"}
P.entries["item:bathran-s-hair"] = {n="Bathranshaar",s="Bathranshaar ist ein seltenes, zartes Kraut, das in den Ruinen von Bathrans Schlupfwinkel im nordwestlichen Ashenvale zu finden ist. In den Überlieferungen der Nachtelfen wird es für seine mächtigen heilsamen Eigenschaften gerühmt, und man glaubt, dass die Pflanze Leiden des Geistes ebenso wie die des Fleisches lindert.",h="Bathranshaar ist ein seltenes, zartes Kraut, das in den Ruinen von Bathrans Schlupfwinkel im nordwestlichen...",kw={"ashenvale","bathranshaar","bathrans schlupfwinkel","maestras posten","orendil broadleaf","pflanzenbündel"},ang={["profession:Herbalism"]="Ausgebildete Kräuterkundige sind bei der Suche nach Bathranshaar deutlich im Vorteil, da ihr geschulter Blick für wilde Pflanzen es ihnen ermöglicht, die versteckten Pflanzenbündel im Schutt aufzuspüren.",["race:NightElf"]="Für die Kaldorei ist der Schutz heiliger Pflanzen wie Bathranshaar vor der Entweihung durch Schänder der Verlassenen sowohl eine Frage des Überlebens als auch der Bewahrung ihrer uralten Heimat."},sec={{t="Ein Heilmittel für den Geist",b="Gewachsen in den Schatten der uralten Ruinen nördlich von Maestras Posten, wird Bathranshaar seit langem von den Heilern der Nachtelfen geschätzt. Anders als gewöhnliche Heilpflanzen, die einfache körperliche Wunden lindern, besitzt dieses Kraut regenerative Eigenschaften, von denen man sagt, dass sie tiefe Leiden des Geistes heilen. Als ein junger Nachtelf in Astranaar einer heimtückischen, unnachgiebigen Krankheit zum Opfer fällt, sucht der Kräuterkundige Orendil Broadleaf nach Strängen dieser seltenen Pflanze, um ein lebenswichtiges Heilmittel zu brauen."},{t="Sammeln inmitten der Ruinen",b="Bathranshaar zu finden, ist gefährlich geworden. Das Kraut liegt in weggeworfenen Pflanzenbündeln und unter Laubhaufen, die über Bathrans Schlupfwinkel nahe der Grenze zur Dunkelküste verstreut sind. Erschwerend kommt hinzu, dass Apotheker der Verlassenen und ihre untoten Handlanger eine Präsenz in den Ruinen errichtet haben, um die lokalen botanischen Ressourcen für ihre eigenen dunklen, unheilvollen Gebräue zu ernten."}},faq={{q="Wofür wird Bathranshaar verwendet?",a="Das Kraut wird von Heilern der Nachtelfen verwendet, um schwere Leiden zu behandeln, die über gewöhnliche Krankheiten hinausgehen. Konkret mischt Orendil Broadleaf es zu einem heilenden Trank, der ein sterbendes Kind retten soll, dessen Geist dahinschwindet.",al={"was bewirkt bathranshaar","bathranshaar zweck","bathranshaar verwendung"}},{q="Wo wächst Bathranshaar?",a="Es ist ausschließlich in Bathrans Schlupfwinkel zu finden, einer alten Ruinensiedlung im nördlichen Ashenvale, östlich der Hauptstraße, die nach Norden zur Dunkelküste führt.",al={"wo findet man bathranshaar","bathranshaar fundort","wo ist bathranshaar"}},{q="Warum interessieren sich die Verlassenen für Bathrans Schlupfwinkel?",a="In Ashenvale eingedrungene Verlassene haben in den Ruinen ein Lager aufgeschlagen, um einheimische Pflanzen und magische Reagenzien zu sammeln. Ihre Anwesenheit beunruhigt die ansässigen Nachtelfen, die fürchten, was die untoten Alchemisten aus der Flora der Region herstellen wollen.",al={"warum sind untote in bathrans schlupfwinkel","verlassene in bathrans schlupfwinkel","untote bathran"}},{q="Wer ist Orendil Broadleaf?",a="Orendil Broadleaf ist ein Kräuterkundiger, der an Maestras Posten im westlichen Ashenvale stationiert ist. Er arbeitet unermüdlich daran, die einheimische Flora zu erforschen und Arzneien herzustellen, um Reisende und verwundete Verteidiger des Waldes zu heilen.",al={"orendil broadleaf","wer sucht bathranshaar"}}},fp="14,252,23.451.0,24.381.1,32.224.0,31.151.0,51.238.0,25.201.0"}
P.entries["item:battleboar-flank"] = {n="Kampfeberflanke",s="Kampfeberflanken sind herzhafte Fleischstücke von den bösartigen Kampfebern, die von den Borstennacken-Stachelebern in Mulgore abgerichtet werden. Sie werden von jungen Jägern rund um Camp Narache gesammelt und dienen sowohl als Beweis für die Beseitigung von Bedrohungen als auch als nahrhafte Verpflegung für den Stamm der Tauren.",h="Kampfeberflanken sind herzhafte Fleischstücke von den bösartigen Kampfebern, die von den...",kw={"kampfeber","kampfeberflanke","dornrankenklamm","borstennacken","camp narache","grull hawkwind","mulgore","red cloud mesa"},ang={["profession:Cooking"]="Obwohl das Fleisch von Tieren stammt, die für den Kampf aufgezogen wurden, und daher zäh und streng schmeckt, liefert die Flanke reichlich nahrhaftes, sättigendes Fleisch, wenn man sie langsam zu gemeinschaftlichen Lagereintöpfen verkocht.",["race:Tauren"]="Die Jagd auf die vordringenden Kampfeber lehrt die jungen Tauren, dass die Verteidigung ihrer Heimat Hand in Hand mit der heiligen Pflicht geht, die Gaben der Erdenmutter zu achten und zu nutzen."},sec={{t="Nahrung aus der Bedrohung durch die Borstennacken",b="Die Borstennacken-Stacheleber, die in der Dornrankenklamm lauern, haben bösartige Kampfeber abgerichtet, um in die Jagdgründe der Tauren vorzudringen. Während diese aggressiven Bestien eine unmittelbare Gefahr für die heranwachsenden jungen Tauren in Camp Narache darstellen, wird nichts, was der Natur entnommen wird, vergeudet. Grull Hawkwind weist angehende Jäger an, neben den Schnauzen auch die Flanken dieser erlegten Bestien zu erbeuten. Die Flankenstücke liefern reichhaltiges, stärkendes Fleisch, das zu einem herzhaften Eintopf für die Dorfjugend eingekocht wird, wodurch eine Kriegswaffe der Stacheleber in lebenswichtige Nahrung für den Stamm verwandelt wird."}},faq={{q="Wofür wird eine Kampfeberflanke verwendet?",a="Kampfeberflanken werden von jungen Jägern in Camp Narache auf Geheiß von Grull Hawkwind gesammelt. Das Fleisch wird zu Eintopf verarbeitet, um die jungen Tauren des Dorfes zu ernähren, sodass besiegte Feinde auch zum Erhalt des Stammes beitragen.",al={"kampfeberflanke verwendung","was ist kampfeberflanke","warum kampfeberfleisch sammeln"}},{q="Wo findet man Kampfeberflanken?",a="Sie werden von den aggressiven Kampfebern und Borstennackenkampfebern erbeutet, die nahe der Dornrankenklamm östlich von Camp Narache auf der Red Cloud Mesa herumstreifen.",al={"kampfeberflanke herkunft","wo droppen kampfeber flanken","wer droppt kampfeberflanken"}},{q="Warum dringen die Kampfeber in das Land der Tauren ein?",a="Die Kampfeber werden von den Borstennacken-Stachelebern gezüchtet und darauf abgerichtet, feindselig und bösartig zu sein. Da die Spannungen zwischen den Borstennacken und den Tauren zunehmen, treiben die Stacheleber diese abgerichteten Bestien in die traditionellen Jagdgründe des Stammes, um die Neuankömmlinge zu bedrängen.",al={"warum greifen kampfeber an","stacheleber eber mulgore","dornranken kampfeber"}}},fp="16,266,38.545.0,36.226.0,34.149.0,51.256.0"}
P.entries["item:battleboar-snout"] = {n="Kampfeberschnauze",s="Kampfeberschnauzen werden von den aggressiven Ebern erbeutet, die von den Stachelebern der Bristleback in Mulgore abgerichtet werden. Von jungen Taurenjägern gesammelt, dienen sie sowohl als Beweis für die Dezimierung einer invasiven Bedrohung als auch als herzhafte Zutaten für die Stammesküche in Camp Narache.",h="Kampfeberschnauzen werden von den aggressiven Ebern erbeutet, die von den Stachelebern der Bristleback in...",kw={"kampfeber","kampfeberschnauze","dornrankenklamm","bristleback","camp narache","grull hawkwind","red cloud mesa"},ang={["profession:Cooking"]="Zähe Fleischstücke wie Schnauzen müssen langsam über dem Feuer gekocht werden, was sie zu Grundzutaten in den Lagerfeuereintöpfen des Stammes macht.",["race:Tauren"]="Die Schnauze zusammen mit dem Fleisch zu verwerten, ehrt das Gleichgewicht der Erdenmutter: Ein vordringendes Raubtier wird gezügelt und versorgt gleichzeitig die Jugend in Camp Narache mit Nahrung."},sec={{t="Trophäen und Vorräte",b="Im Schatten der Red Cloud Mesa richten die Bristleback-Stacheleber in der Dornrankenklamm bösartige Kampfeber ab, um die Jagdgründe der Tauren auszukundschaften. Wenn junge Krieger von Grull Hawkwind ausgesandt werden, um diesen Übergriffen Einhalt zu gebieten, dient die Schnauze als unbestreitbarer Beweis für ein erlegtes Tier. Anstatt irgendeinen Teil der Beute zu verschwenden, verwenden die Tauren diese Schnauzen zusammen mit Flankenfleisch, um nahrhafte, kräftigende Eintöpfe für ihre Jugend zuzubereiten."}},faq={{q="Wofür werden Kampfeberschnauzen verwendet?",a="Grull Hawkwind bittet junge Jäger in Camp Narache darum, sie zusammen mit Fleischflanken zu sammeln. Sie dienen als Beweis dafür, dass die bedrohlichen Eber erlegt wurden, und werden in Kochtöpfe geworfen, um Eintopf für die Jugend des Stammes zuzubereiten.",al={"verwendung kampfeberschnauze","warum schnauzen behalten","was macht grull mit schnauzen"}},{q="Woher stammen diese Schnauzen?",a="Sie werden von Kampfebern und Kampfebern der Bristleback abgeschnitten, die an den Rändern der Red Cloud Mesa und in der gesamten Dornrankenklamm im Osten zu finden sind.",al={"wo kampfeber finden","wer lässt schnauzen fallen","kampfeber standort"}},{q="Warum dringen die Kampfeber in das Land der Tauren ein?",a="Die Kampfeber wurden von den feindseligen Bristleback-Stachelebern darauf abgerichtet, außerordentlich bösartig zu sein, und dringen aus der Dornrankenklamm in die traditionellen Jagdgründe des Stammes vor.",al={"warum greifen eber an","stacheleber eber","dornrankenklamm kampfeber"}}},fp="16,258,23.445.0,36.227.0,32.149.0,51.180.0"}
P.entries["item:battleworn-axe"] = {n="Kampferprobte Axt",s="Kampferprobte Äxte sind grobe, schartenbesetzte Waffen, die von den Blackrock-Orcs getragen werden, welche in das Rotkammgebirge einfallen. Marshal Marris nimmt diese geborgenen Klingen in Seenhain als handfesten Beweis für getötete Eindringlinge entgegen, die die einheimische Bevölkerung bedrohen.",h="Kampferprobte Äxte sind grobe, schartenbesetzte Waffen, die von den Blackrock-Orcs getragen werden, welche in...",kw={"kampferprobte axt","blackrock","seenhain","marris","orc","rotkammgebirge","steinwacht","waffe"},ang={["faction:Alliance"]="Jede nach Seenhain zurückgebrachte Axt bedeutet einen Eindringling weniger, der die schutzlosen Bürger des Rotkamms bedroht, während Stormwinds Hauptstreitkräfte andernorts gebunden sind.",["profession:Blacksmithing"]="Trotz ihrer schartigen Schneiden und abgesplitterten Klingen zeugen diese groben Eisenwaffen von den widerstandsfähigen, wuchtigen Schmiedetraditionen, die typisch für die Rüstung der Blackrock sind."},sec={{t="Trophäe eines Eindringlings",b="Diese schweren, eingekerbten Äxte dienen als Standardausrüstung für die Plünderer der Blackrock, die aus der Brennenden Steppe nach Süden in das Rotkammgebirge vordringen. Für Marshal Marris und die bedrängte Stadtwache von Seenhain erfüllt das Sammeln dieser Waffen zwei Zwecke: Es stellt sicher, dass ein weiterer marodierender Orc gefallen ist, und liefert physische Beweise dafür, wie schwer bewaffnet die vorrückende Kriegsschar tatsächlich ist."},{t="Die Bedrohung in den Hügeln",b="Die Blackrock-Eindringlinge haben Burg Steinwacht befestigt und im Südosten des Rotkamms Stützpunkte errichtet, wodurch die Stadtbewohner praktisch in Seenhain gefangen sind. Indem man den Angreifern ihre kampferprobten Waffen abnimmt, verringert man unmittelbar die Bewaffnung der Kriegsschar und macht gleichzeitig die Straßen für Reisende der Allianz wieder passierbar."}},faq={{q="Was ist eine Kampferprobte Axt?",a="Eine Kampferprobte Axt ist die robuste, stark abgenutzte Nahkampfwaffe der Blackrock-Orcs im Rotkammgebirge. Sie wird von Abenteurern als Beweis für erschlagene Eindringlinge gesammelt.",al={"kampferprobte axt infos","was sind diese äxte","blackrock-axt"}},{q="Wer benötigt diese Äxte in Seenhain?",a="Marshal Marris, der Kommandant der Stadtwache von Seenhain, verlangt nach ihnen, um sich zu vergewissern, dass die Bedrohung durch die Blackrock aktiv von den Ländereien der Stadt zurückgedrängt wird.",al={"wer nimmt kampferprobte äxte an","kampferprobte axt questgeber","marshal marris äxte"}},{q="Woher stammen diese Äxte?",a="Sie werden von Blackrock-Orcs im gesamten Rotkammgebirge erbeutet, insbesondere rund um Burg Steinwacht im Norden und in den Lagern der Orcs im Südosten.",al={"wo droppen kampferprobte äxte","kampferprobte axt farmen","welche orcs haben sie"}},{q="Warum befinden sich die Orcs überhaupt im Rotkammgebirge?",a="Der Blackrockclan marschierte aus der Brennenden Steppe durch die Gebirgspässe nach Süden, eroberte Burg Steinwacht und marodierte durch den Norden und Osten des Rotkamms, um Seenhain in die Enge zu treiben.",al={"warum sind blackrock-orcs im rotkammgebirge","steinwacht-invasion","bedrohung durch die blackrock grund"}}},fp="14,237,20.358.0,23.317.0,25.171.0,34.151.0,30.164.0,48.186.0"}
P.entries["item:berard-s-journal"] = {n="Berards Tagebuch",s="Berards Tagebuch ist eine Sammlung von Forschungsnotizen, die von Apotheker Berard verfasst wurden, bevor er dem Fluch von Erzmagier Arugal zum Opfer fiel. Das in Pyrewood zurückgelassene Buch dokumentiert Berards Studien über eine uralte Seuche, die einst das Wasserleben des Lake Lordamere auslöschte, was es für die Königliche Apothekervereinigung äußerst wertvoll macht.",h="Berards Tagebuch ist eine Sammlung von Forschungsnotizen, die von Apotheker Berard verfasst wurden, bevor er...",kw={"apotheker berard","apotheker renferrel","berards tagebuch","lake lordamere","apothekermeister faranell","pyrewood","königliche apothekervereinigung","silberwald"},ang={["faction:Horde"]="Der Vorstoß nach Pyrewood zur Bergung verlorener Forschung hilft den Verlassenen dabei, eine feste defensive Bastion im gesamten Silberwald zu errichten.",["race:Undead"]="Jeder Schnipsel giftigen Wissens hilft der Königlichen Apothekervereinigung dabei, eine Waffe zu sichern, die in der Lage ist, die Verlassenen sowohl gegen die Geißel als auch gegen lebende Feinde zu verteidigen."},sec={{t="Verlorene Forschung am Lake Lordamere",b="Bevor Erzmagier Arugal seine Schattenmagie über den Silberwald entfesselte, galt Apotheker Berard als einer der vielversprechendsten Köpfe der Königlichen Apothekervereinigung. In Pyrewood stationiert, konzentrierte er seine Arbeit auf eine uralte, bösartige Pestilenz, die Jahrhunderte zuvor alles Leben im Lake Lordamere vernichtet hatte. Als Arugals Fluch die Siedlung erfasste, wurde Berards Verstand gebrochen und er wurde zu einem weiteren willenlosen Knecht. Seine detaillierten Feldnotizen blieben auf einem Bücherregal in seinen Gemächern im Gasthaus von Pyrewood zurück."},{t="Brennstoff für die neue Seuche",b="Obwohl Berard selbst für die Gesellschaft verloren war, überlebte seine Forschung unbeschadet. Apotheker Renferrel im Grabmal erkennt den strategischen Wert des Tagebuchs und entsendet Agenten der Verlassenen in das feindselige Dorf, um es zu bergen. Die zusammengetragenen Notizen über das uralte Seetoxin liefern dem Apothekermeister Faranell und der Vereinigung im Apothecarium entscheidende Vorarbeiten und dienen als wichtige Grundlage für das Brauen der neuen Seuche der Verlassenen."}},faq={{q="Wer war Apotheker Berard?",a="Apotheker Berard war ein begabtes Mitglied der Königlichen Apothekervereinigung, das in Pyrewood lebte. Er betrieb wichtige Forschungen über historische Toxine, als Erzmagier Arugal seinen Fluch über die Region legte, Berards Verstand brach und ihn versklavte.",al={"wer ist berard","berard lore","apotheker berard"}},{q="Wo ist Berards Tagebuch zu finden?",a="Das Tagebuch liegt auf einem Bücherregal in Berards altem Arbeitszimmer im oberen Stockwerk des Gasthauses in Pyrewood, tief im südlichen Silberwald.",al={"berards tagebuch finden","tagebuch fundort","wo ist das buch"}},{q="Welche Forschung ist im Tagebuch festgehalten?",a="Das Tagebuch beschreibt Berards Erkenntnisse über eine urzeitliche Seuche, die in alten Zeiten sämtliche Wasserlebewesen im Lake Lordamere vollständig vernichtete. Die Königliche Apothekervereinigung hofft, diese toxischen Eigenschaften für ihre eigenen chemischen Waffen nutzbar zu machen.",al={"was steht im tagebuch","berards forschung","inhalt des tagebuchs"}},{q="Warum will Apotheker Renferrel das Tagebuch haben?",a="Renferrel versucht, alle nützlichen wissenschaftlichen Aufzeichnungen zu retten, bevor sie zerstört werden oder für immer verloren sind. Berards einzigartige Einblicke in die Seuche des Lake Lordamere liefern entscheidende Komponenten, die Apothekermeister Faranell in Undercity benötigt, um die neue Seuche der Verlassenen zu entwickeln.",al={"warum will renferrel es","renferrel tagebuch quest"}}},fp="16,331,31.542.0,23.440.1,26.248.0,32.154.0,41.247.0,47.272.0"}
P.entries["item:bernice-s-necklace"] = {n="Bernices Halskette",s="Bernices Halskette ist ein sentimentales Erbstück, das Tantchen Bernice Stonefield vom Hof der Stonefields im Wald von Elwynn gehört. Ursprünglich von ihrem verstorbenen Ehemann während seines Militärdienstes als Glücksbringer getragen, ging das Schmuckstück nahe der Tiefenschachtmine verloren und wurde von einem opportunistischen Kobold an sich gerissen.",h="Bernices Halskette ist ein sentimentales Erbstück, das Tantchen Bernice Stonefield vom Hof der Stonefields im...",kw={"tantchen bernice","bernices halskette","billy maclure","tiefenschachtmine","goldzahn","glücksbringer","stonefield"},ang={["faction:Alliance"]="Die Halskette ist eine stille Mahnung an den schweren Tribut, den Stormwinds langwierige Feldzüge von gewöhnlichen Bauernfamilien im gesamten Wald von Elwynn fordern."},sec={{t="Der verlorene Glücksbringer eines Soldaten",b="Obwohl das Stück vor Ort als Bernices Halskette bekannt ist, gehörte es ursprünglich dem verstorbenen Ehemann von Tantchen Bernice Stonefield. Als Veteran der Feldzüge Stormwinds trug er den Glücksbringer als Zeichen des guten Schicksals in die Schlacht. Laut Bernice schlug die Tragödie nur ein einziges Mal zu, nämlich während seines letzten Feldzugs – der einen Expedition, bei der er vergaß, seine Glückskette mitzunehmen. Nach seinem Tod blieb das Andenken einer von Bernices wertvollsten Besitztümern auf dem Hof der Stonefields."},{t="Von Plünderern gestohlen",b="Das Erbstück verschwand, nachdem der junge Billy Maclure beim Spielen nahe der Tiefenschachtmine erwischt wurde, wo er das glänzende Schmuckstück beim Erkunden fallen ließ. Das Glitzern erregte die Aufmerksamkeit von Goldzahn, einem berüchtigten Kobold, der in einer Höhle auf den Hügeln über der Mine lauerte. Wie alle seiner Art von hellen und wertvollen Schmuckstücken angezogen, hortete Goldzahn die Halskette unter seinen unterirdischen Plündergütern, bis sie für die trauernde Witwe wiederbeschafft werden konnte."}},faq={{q="Wem gehörte diese Halskette ursprünglich?",a="Die Halskette gehörte ursprünglich dem verstorbenen Ehemann von Tantchen Bernice Stonefield, der sie während seiner Feldzüge für Stormwind als Glücksbringer trug.",al={"wer besaß die halskette","bernices halskette besitzer","ehemann halskette"}},{q="Wie landete die Halskette bei den Kobolden?",a="Billy Maclure nahm die Halskette und ließ sie fallen, als er nahe der Tiefenschachtmine umherstreifte. Der große Kobold Goldzahn bemerkte das glänzende Stück, schnappte es sich und trug es zurück in seine Höhle auf dem Bergrücken über der Mine.",al={"wie ging sie verloren","warum hat goldzahn sie","wer nahm die halskette"}},{q="Warum ist die Halskette so wichtig für Tantchen Bernice?",a="Sie dient als geschätztes Andenken an ihren verstorbenen Ehemann. Bernice bemerkt traurig, dass er stets daran glaubte, sie würde ihn im Kampf beschützen, und das einzige Mal, dass er im Krieg fiel, war der Tag, an dem er die Halskette versehentlich zurückgelassen hatte.",al={"warum will bernice sie","geschichte von bernices ehemann","ist die halskette magisch"}},{q="Wer ist Goldzahn?",a="Goldzahn ist ein bekannter koboldischer Plünderer, der sein Lager in den Hügeln direkt über der Tiefenschachtmine im Wald von Elwynn aufgeschlagen hat. Er ist dafür bekannt, glänzende Schmuckstücke zu sammeln, und beanspruchte die verlorene Halskette für sich, nachdem sie in der Nähe fallengelassen worden war.",al={"was ist goldzahn","goldzahn geschichte","wer hat die halskette"}}},fp="18,294,22.488.0,20.428.1,35.155.0,45.215.0,51.211.0,17.215.0"}
P.entries["item:besseleth-s-fang"] = {n="Besseleths Fangzahn",s="Besseleths Fangzahn ist der gewaltige Giftzahn, der von der riesigen Spinne Besseleth im Sishircanyon erbeutet wird. Als Beweis für ihr Ableben mitgeführt, steht er für die Beseitigung einer tödlichen Bedrohung, die den Pfaden im Steinkrallengebirge nachstellte.",h="Besseleths Fangzahn ist der gewaltige Giftzahn, der von der riesigen Spinne Besseleth im Sishircanyon...",kw={"arachnophobie","besseleth","besseleths fangzahn","maggran earthbinder","sishircanyon","steinkrallengebirge","sonnenfels","weberpass"},ang={["class:Hunter"]="Das Erbeuten des zwei Fuß langen Giftzahns einer dominanten Spinnenmatriarchin dient als unbestrittener Beweis für das Fährtenlese- und Kampfgeschick eines Jägers.",["faction:Horde"]="Die Beseitigung der Canyonspinne trägt dazu bei, die heiklen Bergpfade zu sichern, die die Grenze zum Brachland mit Sonnenfels verbinden."},sec={{t="Trophäe des Canyonpirschers",b="Der Sishircanyon wird seit langem von aggressiven Spinnentieren heimgesucht, doch keines versetzt Reisende in größere Furcht als Besseleth. Zu monströsen Ausmaßen herangewachsen, machten sie und ihre Brut die Schlucht zu einer Todesfalle für Wanderer, die nachts den Weberpass bezwingen wollten. Der Zahn selbst misst fast zwei Fuß in der Länge und trieft von wirksamem Gift, was ihn zu einem unverkennbaren Beweis für die Tötung der Brutkönigin macht. Die Vorlage dieser grausigen Trophäe bringt den örtlichen Verteidigern Erleichterung, die unter ihren giftigen Bissen gelitten haben."}},faq={{q="Wofür wird Besseleths Fangzahn verwendet?",a="Der Fangzahn dient als handfester Beweis dafür, dass die Spinnenmatriarchin Besseleth erschlagen wurde. Maggran Earthbinder in Sonnenfels setzte ein Kopfgeld auf die Bestie aus, nachdem er einen fast tödlichen Angriff ihrer Fangzähne überlebt hatte, und er belohnt jeden, der ihm die Trophäe bringt.",al={"besseleth fangzahn verwendung","wer will besseleths fangzahn","fangzahn abgeben"}},{q="Woher stammt dieser Fangzahn?",a="Der Fangzahn wird direkt von Besseleth erbeutet, einer riesigen Raubspinne, die im Sishircanyon haust, welcher westlich der Hauptstraße südlich der Scherwindklippe im Steinkrallengebirge liegt.",al={"besseleth fangzahn bekommen","wo ist besseleth","besseleth aufenthaltsort"}},{q="Warum wollte Maggran Earthbinder Besseleths Tod?",a="Besseleth und ihre Brut stellen regelmäßig Reisenden nach, die auf den Straßen in Richtung Sonnenfels unterwegs sind, insbesondere im Schutze der Nacht. Maggran Earthbinder wurde persönlich von ihren Fangzähnen überfallen und verwundet, was ihn dazu veranlasste, ein Kopfgeld auszusetzen, um die Pfade zu sichern.",al={"warum besseleth toeten","maggran kopfgeld spinne","warum kopfgeld auf besseleth"}},{q="Wer hat das Kopfgeld für den Fangzahn ausgeschrieben?",a="Das Kopfgeld wurde von Maggran Earthbinder autorisiert und an einem Steckbrief entlang der Hauptstraße südlich der Abzweigung zur Scherwindklippe ausgehängt, um vorbeiziehende Reisende vor den Gefahren des Sishircanyons zu warnen.",al={"steckbrief steinkrallengebirge spinne","arachnophobie questgeber"}}},fp="16,228,28.512.0,34.256.0,31.185.0,48.259.0,35.196.0"}
P.entries["item:bethor-s-scroll"] = {n="Bethors Rolle",s="Bethors Rolle enthält magische Beschwörungsformeln, die von Bethor Iceshard niedergeschrieben wurden, um der dunklen Zauberei seines früheren Kollegen Thule Rabenklaue entgegenzuwirken. Die Rolle wurde erschaffen, um Apotheker Renferrel beim Brauen eines schützenden Tranks zu helfen, und ist überlebenswichtig gegen die Nekromantie der Geißel, die die Insel Fenris bewacht.",h="Bethors Rolle enthält magische Beschwörungsformeln, die von Bethor Iceshard niedergeschrieben wurden, um der...",kw={"apotheker renferrel","bethor iceshard","bethors rolle","insel fenris","moderfell","silberwald","das grabmal","thule rabenklaue"},ang={["class:Mage"]="Die Schriftrolle veranschaulicht die zerrissene Vergangenheit der Kirin Tor und zeigt, wie tiefes Wissen über die unverkennbare Magie eines befreundeten Zauberwirkers in eine mächtige Gegenmaßnahme verwandelt werden kann.",["race:Undead"]="Verlassene Zauberwirker und Apotheker vereinen auf diesem Pergament ihre jeweiligen Talente, indem sie Dalarans alte arkane Ausbildung mit der neuen alchemistischen Handwerkskunst des Grabmals verschmelzen."},sec={{t="Der Verrat eines Kollegen",b="Bei der Untersuchung von verdorbenem Eiter, der von Moderfellgnollen geborgen wurde, erkannte Bethor Iceshard das Werk von Thule Rabenklaue. Einst ein vielversprechender junger Magier der Kirin Tor, verriet Thule seine Brüder, um dem Lichkönig zu dienen, als die Geißel an die Macht gelangte. Als Bethor erfuhr, dass Thule überlebt hatte und von der Insel Fenris aus Angriffe der Moderfelle im gesamten Silberwald leitete, nutzte er sein genaues Wissen über das Zauberhandwerk seines ehemaligen Kollegen, um diese Schriftrolle zu verfassen."},{t="Den Nekromanten bekämpfen",b="Die Schriftrolle ist von mächtigen arkanen Formeln durchdrungen, die nicht als Angriffswaffe gedacht sind, sondern als Brauanleitung für die Königliche Apothekervereinigung. Ausgehändigt an Apotheker Renferrel im Grabmal liefert die Rolle genau die Gegenbeschwörungen, die erforderlich sind, um einen wiederherstellenden Trank zu synthetisieren, der die schwächenden Verhexungen brechen kann, die Thule um seine Festung webt."}},faq={{q="Was steht auf Bethors Rolle?",a="Die Schriftrolle beschreibt spezialisierte arkane Beschwörungen, die von Bethor Iceshard formuliert wurden. Da er einst an der Seite von Thule Rabenklaue studiert hatte, kannte Bethor die bevorzugten Zauber des Nekromanten und trug die genauen Formeln ein, die zum Brauen eines alchemistischen Gegentrankes erforderlich waren.",al={"was steht auf der rolle","inhalt von bethors rolle","was steht auf der schriftrolle"}},{q="Wer erhält diese Schriftrolle?",a="Die Schriftrolle muss zu Apotheker Renferrel gebracht werden, der im Grabmal im Silberwald stationiert ist. Renferrel nutzt die darin gebundene Magie, um einen schützenden Trank herzustellen.",al={"wem gebe ich die schriftrolle","bethors rolle abgabe","wer bekommt die schriftrolle"}},{q="Warum benötigt Apotheker Renferrel magische Beschwörungsformeln für einen Trank?",a="Apotheker Renferrel ist eher auf Alchemie als auf traditionelle Zauberei spezialisiert und räumt ein, dass er selten solch offensichtliche Mächte in seine Gebräue einwebt. Gewöhnliche Gegengifte können die Flüche der Geißel, die Thule abschirmen, jedoch nicht durchdringen, weshalb Bethors arkane Formeln erforderlich sind, um das Gebräu wirksam zu machen.",al={"warum braucht ein apotheker zauber","zaubertrank renferrel"}},{q="Wer war Thule Rabenklaue, bevor er sich der Geißel zuwandte?",a="Vor dem Dritten Krieg war Thule ein vielversprechender junger menschlicher Magier und ein Weggefährte von Bethor Iceshard. Als der Lichkönig seine untoten Heere sammelte, verließ Thule seine Mitzauberer und schwor der Geißel seine Treue.",al={"wer ist thule rabenklaue","thule hintergrundgeschichte","thule und bethor"}}},fp="15,290,22.461.0,26.368.1,35.255.0,25.175.0,69.286.0,54.225.0"}
P.entries["item:bingles-blastencapper"] = {n="Bingles Superspreng",s="Bingles Superspreng ist ein spezieller Sprengsatz, der von dem Gnomenpiloten Bingles Blastenheimer entworfen wurde. Er ging verloren, als sein Gyrokopter in den Loch stürzte, und wurde von einheimischen Troggs gestohlen, was Bingles' Pläne zur Unterstützung der Befreiung von Gnomeregan gefährdete.",h="Bingles Superspreng ist ein spezieller Sprengsatz, der von dem Gnomenpiloten Bingles Blastenheimer entworfen...",kw={"bingles","superspreng","blastenheimer","sprengstoffe","gnomeregan","gyrokopter","loch modan","trogg"},ang={["profession:Engineering"]="Der Superspreng demonstriert das klassische Gespür gnomischer Ingenieurskunst: komplex, hochexplosiv und verheerend, wenn er aus großer Höhe abgeworfen wird.",["race:Gnome"]="Jedes Werkzeug und jede Munition zählt im Kampf um die Rückeroberung von Gnomeregan, und die Wiederbeschaffung von Bingles' Sprengstoff stellt sicher, dass der gnomische Erfindergeist aus der Luft gegen die troggischen Invasoren zurückschlagen kann."},sec={{t="Eine volatile Erfindung",b="Bingles Superspreng stellt den Höhepunkt der persönlichen Munition des Piloten Bingles Blastenheimer dar. Gebaut, um entscheidende Luftangriffe gegen die Troggs und Lepragnome zu fliegen, die Gnomeregan überrannten, befand sich der Sprengsatz an Bord seines Gyrokopters, als ein mechanisches Versagen ihn in die Fluten des Lochs stürzen ließ. Während Bingles überlebte, plünderten Troggs, die die nördlichen Inseln des Sees heimsuchen, sein Wrack und schleppten die unberechenbare Waffe in ihre Lager."},{t="Luftunterstützung für Gnomeregan",b="Für Bingles ist der Superspreng weit mehr als einfaches Bergungsgut. Die verbannten Gnome bereiten sich aktiv darauf vor, ihre radioaktive Heimat zurückzuerobern, und Bingles betrachtet seinen Gyrokopter sowie seine charakteristische Munition als lebenswichtige Bestandteile des bevorstehenden Luftangriffs. Die Bergung dieser Munition verhindert, dass die einheimischen Troggs von Loch Modan versehentlich eine Katastrophe auslösen, und bewahrt eine wertvolle Waffe für den gnomischen Widerstand."}},faq={{q="Was ist Bingles Superspreng?",a="Es handelt sich um einen speziellen, mächtigen Sprengsatz, der von Bingles Blastenheimer entwickelt wurde und für Luftangriffe gedacht ist, um den Feldzug der Gnome gegen die Besatzer von Gnomeregan – Troggs und Lepragnome – zu unterstützen.",al={"was ist bingles superspreng","superspreng","bingles sprengstoff"}},{q="Wie landete der Superspreng im Loch?",a="Bingles stürzte mit seinem Gyrokopter in die Fluten des Lochs. Bevor er seine Ausrüstung sichern konnte, plünderten Troggs von den nahegelegenen Inseln sein abgestürztes Fluggerät und entwendeten neben dem Sprengsatz auch sein Werkzeug.",al={"warum ist es im loch","wie hat bingles es verloren","absturz"}},{q="Wer besitzt den Superspreng derzeit?",a="Die Troggs, die auf den nördlichen Inseln des Lochs hausen, haben das Gerät von der Absturzstelle geplündert und halten es in ihrem primitiven Lager bewacht.",al={"wer stahl den superspreng","wer hat es","troggs"}},{q="Warum braucht Bingles den Superspreng zurück?",a="Ohne sein Werkzeug und seine unverkennbare Munition kann Bingles weder seinen Gyrokopter reparieren noch einen Bombenangriff aus der Luft starten, um die Rückeroberung von Gnomeregan zu unterstützen.",al={"warum zurueckholen","warum ist superspreng wichtig","fuer gnomeregan"}}},fp="22,254,20.451.0,26.421.0,31.197.0,45.217.0,36.140.0,49.157.0"}
P.entries["item:bingles-hammer"] = {n="Bingles Hammer",s="Bingles Hammer ist ein Ingenieurswerkzeug von Bingles Blastenheimer, einem exzentrischen Gnomenflieger, der in Loch Modan gestrandet ist. Nachdem seine Flugmaschine in den Loch gestürzt war, plünderten feindselige Troggs den Hammer zusammen mit seiner restlichen Spezialausrüstung. Bingles benötigt ihn zurück, um sein Fluggerät zu reparieren und die Kriegsanstrengungen zur Befreiung von Gnomeregan zu unterstützen.",h="Bingles Hammer ist ein Ingenieurswerkzeug von Bingles Blastenheimer, einem exzentrischen Gnomenflieger, der...",kw={"bingles","blastenheimer","gnomeregan","hammer","loch modan","toolbucket","trogg"},ang={["profession:Engineering"]="Jeder Handwerker weiß, dass ein feiner, von Gnomen gefertigter Hammer unersetzlich ist – insbesondere, wenn man vor der Aufgabe steht, einen experimentellen Gyrokopter in der Wildnis wiederaufzubauen.",["race:Gnome"]="Jedes wiederbeschaffte Werkzeug bringt die Luftoffensive von Gnomeregan einen Schritt näher an ihren Start gegen die Eindringlinge, die Eure angestammte Heimat gestohlen haben."},sec={{t="Der Werkzeugsatz eines gestrandeten Fliegers",b="Als der Pilot Bingles Blastenheimer in die Gewässer des Lochs stürzte, war sein Überleben nur das erste seiner Probleme. Troggs, welche die Süßwasserinseln bewohnten, plünderten rasch die Absturzstelle und stahlen seinen spezialisierten Werkzeugkasten sowie hochwirksame Sprengstoffe. Unter der gestohlenen Ausrüstung befand sich auch sein Hammer – ein unverzichtbares Werkzeug, um die verbeulte Zelle zu reparieren und die mechanischen Baugruppen des Gyrokopters neu zu kalibrieren. Ohne dieses unentbehrliche Werkzeug und den Rest seiner Ausrüstung bleibt Bingles gänzlich flugunfähig und kann keine Unterstützungsflüge für die Truppen der Gnomenbefreiung durchführen, die um die Rückeroberung von Gnomeregan kämpfen."}},faq={{q="Wo kann Bingles Hammer gefunden werden?",a="Der Hammer befindet sich in einem von Bingles's Toolbuckets, die auf den von Troggs heimgesuchten Inseln im nördlichen Teil des Lochs verstreut sind.",al={"hammer fundort","wo ist bingles hammer","hammer finden"}},{q="Wem gehört dieser Hammer?",a="Er gehört Bingles Blastenheimer, einem abenteuerlustigen Gnomeningenieur und Piloten, der mit seiner Flugmaschine an den Ufern von Loch Modan abgestürzt ist.",al={"wem gehört der hammer","bingles hammer besitzer"}},{q="Warum ist dieses Werkzeug so wichtig für Bingles?",a="Bingles benötigt sein vollständiges Werkzeugset, um seinen abgestürzten Gyrokopter wieder aufzubauen, mit dem er in die Schlacht fliegen will, um den Luftangriff gegen die Troggs und Lepragnome zu unterstützen, die Gnomeregan besetzen.",al={"warum hammer gebraucht","bingles hammer nutzen"}},{q="Wer hat Bingles Hammer gestohlen?",a="Einheimische Troggs, die auf den Seeinseln leben, überfielen die Absturzstelle und machten sich mit den Werkzeugeimern des Piloten sowie seinen maßgefertigten Blastencapper-Sprengstoffen davon.",al={"wer hat den hammer gestohlen","trogg diebe"}}},fp="15,353,28.599.0,35.147.0,31.139.0,41.198.0,26.145.0"}
P.entries["item:bingles-screwdriver"] = {n="Bingles Schraubendreher",s="Bingles Schraubendreher ist ein unverzichtbares Ingenieurswerkzeug von Bingles Blastenheimer, einem Gnomenpiloten, der mit seinem Gyrokopter in den Gewässern von Loch Modan abstürzte. Nach dem Absturz plünderten einheimische Troggs das Wrack und verstreuten Bingles' Werkzeugeimer und Spezialausrüstung über die nördlichen Inseln des Lochs.",h="Bingles Schraubendreher ist ein unverzichtbares Ingenieurswerkzeug von Bingles Blastenheimer, einem...",kw={"bingles","blastenheimer","gyrokopter","loch modan","schraubendreher","werkzeugeimer","troggs"},ang={["profession:Engineering"]="Jeder Tüftler weiß, dass ein fein kalibrierter Schraubendreher für komplizierte Gyrokopterrotoren und empfindliche Abzugsmechanismen unverzichtbar ist.",["race:Gnome"]="Jedes geborgene Werkzeug bringt Bingles einen Schritt näher daran, sein Fluggerät wieder aufzubauen und einen Luftkrieg gegen die Troggs und Lepragnome zu führen, die Euer Volk aus Gnomeregan vertrieben haben."},sec={{t="Die lebenswichtige Ausrüstung eines Piloten",b="Als Bingles Blastenheimer in den Loch stürzte, verlor er mehr als nur seine Flugmaschine – er verlor die Spezialausrüstung, die für deren Reparatur erforderlich war. Unter der verstreuten Ausrüstung befand sich sein treuer Schraubendreher, verstaut in einem von mehreren Werkzeugeimern, die von opportunistischen Troggs auf den nahegelegenen Inseln entwendet worden waren. Für einen in der Wildnis gestrandeten Ingenieur sind Feinjustierungswerkzeuge wie dieser Schraubendreher unersetzlich, insbesondere beim Zusammenbau empfindlicher Gyrokoptermechanismen oder beim Umgang mit flüchtiger Munition."},{t="Vorbereitungen für die Rückeroberung",b="Bingles ist nicht bloß ein Freizeitflieger; er dient einer größeren Sache, die sich der Befreiung der gefallenen Stadt Gnomeregan von Troggs und Lepragnomen widmet. Seine Mission beruht darauf, Flugmechanik mit seiner hochexplosiven Blastencapper-Munition zu kombinieren, um einen Luftangriff gegen die unterirdische Bedrohung zu führen. Das Wiederbeschaffen dieses Schraubendrehers zusammen mit seinem Schraubenschlüssel und seinem Hammer ist entscheidend, um seinen Gyrokopter wieder zusammenzusetzen und die gnomische Luft-Gegenoffensive am Leben zu erhalten."}},faq={{q="Wo findet man Bingles Schraubendreher?",a="Er wird aus einem von Bingles's Toolbuckets geborgen, die auf den Inseln im nördlichen Loch Modan verstreut liegen, wohin örtliche Troggs das Bergungsgut des Piloten nach seinem Absturz geschleppt haben.",al={"fundort des schraubendrehers","bingles schraubendreher finden","wo ist der schraubendreher"}},{q="Warum ist der Schraubendreher für Bingles so wichtig?",a="Bingles benötigt seine wichtigsten Ingenieurswerkzeuge, um seinen abgestürzten Gyrokopter wieder aufzubauen und seine speziellen Sprengstoffe für den Feldzug zur Rückeroberung von Gnomeregan vorzubereiten.",al={"warum bingles ihn braucht","wofür er gut ist"}},{q="Wer hat den Schraubendreher überhaupt gestohlen?",a="Troggs, die auf den Inseln im Loch hausen, überfielen Bingles nach seiner Bruchlandung und trugen seine Werkzeugeimer sowie seine Blastencapper-Sprengstoffe davon.",al={"wer nahm die werkzeuge","wer stahl bingles werkzeuge"}},{q="Welche anderen Werkzeuge hat Bingles bei dem Absturz verloren?",a="Neben seinem Schraubendreher verlor Bingles seinen Schraubenschlüssel, seinen Hammer und seinen Vorrat an flüchtigen Blastenheimer-Blastencapper-Sprengstoffen.",al={"weitere werkzeuge von bingles","was fehlt noch"}}},fp="20,310,19.507.0,29.476.0,36.162.0,47.151.0,45.148.0,47.130.0"}
P.entries["item:bingles-wrench"] = {n="Bingles Schraubenschlüssel",s="Bingles Schraubenschlüssel ist ein wichtiges Ausrüstungsstück gnomischer Ingenieurskunst und gehört dem Piloten Bingles Blastenheimer. Er ging verloren, als Bingles mit seiner Flugmaschine im Loch bruchlandete, und wurde von den einheimischen Troggs zusammen mit dem Rest seines Werkzeugsatzes weggeschleppt.",h="Bingles Schraubenschlüssel ist ein wichtiges Ausrüstungsstück gnomischer Ingenieurskunst und gehört dem...",kw={"bingles","blastenheimer","gyrokopter","loch modan","werkzeugeimer","troggs","schraubenschlüssel"},ang={["profession:Engineering"]="Ein Handwerker weiß, dass ein Ingenieur ohne seinen maßgefertigten Schraubenschlüssel völlig am Boden ist, besonders im Angesicht plünderwütiger Troggs.",["race:Gnome"]="Jedes wiederbeschaffte Werkzeug bringt den gnomischen Widerstand einen Schritt näher daran, den Kampf zurück in die verstrahlten Hallen von Gnomeregan zu tragen."},sec={{t="Bergung auf den Inseln",b="Nachdem Bingles Blastenheimer mit seinem Gyrokopter in den ruhigen Gewässern des Lochs abgestürzt war, wurde sein Überleben schnell zur Zerreißprobe. Troggs, welche die kleinen nördlichen Inseln bewohnen, plünderten die Absturzstelle, stahlen seine Spezialvorräte und verteilten seine Werkzeuge auf verschiedene Eimer in ihren Lagern. Bingles Schraubenschlüssel ist eines von drei entscheidenden Handwerkzeugen, die neben seinen hochexplosiven Blastencapper-Sprengstoffen benötigt werden. Ohne ihn hat Bingles keine Hoffnung, seinen abgestürzten Gyrokopter zu reparieren, was seine geplante Luftoffensive zur Unterstützung der exilierten Gnome bei der Rückeroberung von Gnomeregan zum Stillstand bringt."}},faq={{q="Wem gehört dieser Schraubenschlüssel?",a="Der Schraubenschlüssel gehört Bingles Blastenheimer, einem exzentrischen Gnomenpiloten, der mit seinem Gyrokopter im Loch in Loch Modan abgestürzt ist.",al={"wer ist bingles","bingles besitzer","schraubenschlüssel besitzer"}},{q="Warum ist der Schraubenschlüssel für Bingles so wichtig?",a="Bingles benötigt seine Spezialwerkzeuge, um seine beschädigte Flugmaschine zu reparieren und seine explosive Sprengladung scharfzumachen, damit er einen Luftangriff gegen die Troggs und Lepragnome starten kann, die Gnomeregan besetzen.",al={"warum braucht bingles seinen schraubenschlüssel","schraubenschlüssel zweck","wofür ist schraubenschlüssel"}},{q="Wo landete der Schraubenschlüssel nach dem Absturz?",a="Der Schraubenschlüssel wurde von einheimischen Troggs geplündert und in einem von Bingles' gestohlenen Werkzeugeimern versteckt, die über die nördlichen Inseln des Lochs verstreut sind.",al={"wo ist bingles schraubenschlüssel","schraubenschlüssel fundort","bingles schraubenschlüssel finden"}},{q="Was wurde neben dem Schraubenschlüssel sonst noch gestohlen?",a="Zusammen mit seinem Schraubenschlüssel erbeuteten die Troggs Bingles Schraubendreher, Bingles Hammer und seine experimentellen Blastenheimer Blastencapper-Sprengstoffe.",al={"andere vorräte","fehlende werkzeuge","was haben die troggs noch genommen"}}},fp="15,244,22.570.0,31.125.0,42.195.0,44.145.0,43.147.0"}
P.entries["item:black-claw-stout"] = {n="Blackclaw-Starkbier",s="Blackclaw-Starkbier ist ein tödliches Getränk, das von Zardeth von den Blackclaw unter den Straßen von Stormwind zubereitet wurde. Unter dem Deckmantel eines gewöhnlichen Tavernengetränks gebraut, dient es als Attentatsinstrument gegen einen lästigen Adligen.",h="Blackclaw-Starkbier ist ein tödliches Getränk, das von Zardeth von den Blackclaw unter den Straßen von...",kw={"blackclaw-starkbier","hall of petitioners","lord wishock","gift","slaughtered lamb","stormwind keep","zardeth"},ang={["class:Warlock"]="Das Gebräu steht beispielhaft für die raffinierten, halsabschneiderischen Methoden, mit denen Stormwinds Hexenmeisterzirkel politische Bedrohungen direkt vor der Nase der Stadtwache beseitigt.",["faction:Alliance"]="Das Gebräu durch Stormwind Keep zu tragen, offenbart, wie verwundbar die Adligen der Hauptstadt gegenüber verdeckten Attentaten sind, die aus dem Inneren ihrer eigenen Stadt heraus orchestriert werden."},sec={{t="Ein giftiger Trunk",b="Hinter den schattigen Schankräumen des Geschlachteten Lamms lauern Hexenmeister und Verschwörer, unbemerkt von der Stadtwache von Stormwind. Als ein Adliger namens Lord Wishock wiederholt damit droht, ihre Untergrundoperationen zu beenden, während er oben scheinheilig unbezahlte Zeche prellt, beschließt Zardeth von den Blackclaw, die Rechnung zu begleichen. Das Blackclaw-Starkbier wurde eigens hergestellt, um Wishocks Schwäche für starken Alkohol auszunutzen, und birgt eine tödliche Dosis, getarnt als gewöhnliche Tavernen-Erfrischung."},{t="Stilles Attentat",b="Direkt in die Hall of Petitioners in Stormwind Keep gebracht, nutzt das Starkbier Wishocks hochmütige Arroganz und seinen Durst aus. Der Adlige hält die Lieferung fälschlicherweise für die Aufmerksamkeit eines diensteifrigen Bediensteten und leert das Gebräu auf der Stelle mit Freuden. Das Gift wirkt nahezu augenblicklich und bringt einen der hartnäckigsten und lästigsten politischen Kritiker des Kults direkt vor den Augen des königlichen Hofes zum Schweigen."}},faq={{q="Was ist das Blackclaw-Starkbier?",a="Es ist ein tödliches, vergiftetes Gebräu, das von Zardeth von den Blackclaw in den Katakomben unter dem Geschlachteten Lamm im Mage Quarter von Stormwind zubereitet wurde.",al={"was ist dieses getränk","blackclaw-starkbier lore","giftgebräu"}},{q="Wer ist die Zielperson des Starkbiers?",a="Die Zielperson ist Lord Wishock, ein anmaßender Adliger, der sich in der Hall of Petitioners herumtreibt und seine Zeit damit verbrachte, für die Schließung der Hexenmeister-Zuflucht zu werben, während er dort auf Pump trank.",al={"wer trinkt es","wer stirbt durch blackclaw-starkbier","wishock zielperson"}},{q="Wer hat das Gebräu erschaffen?",a="Es wurde von Zardeth von den Blackclaw gebraut, einer finsteren Gestalt, die aus den Krypten unter dem Geschlachteten Lamm heraus operiert.",al={"schöpfer von blackclaw-starkbier","wer hat das gemacht","zardeth gebräu"}},{q="Was passiert, wenn jemand davon trinkt?",a="Das Gebräu wirkt sofort tödlich. Sobald Lord Wishock das überreichte Starkbier trinkt, entfaltet das Gift umgehend seine Wirkung und tötet ihn auf der Stelle in der Hall of Petitioners.",al={"stirbt wishock","blackclaw-starkbier wirkung"}}},fp="16,240,15.501.0,19.384.1,25.143.0,31.178.0,21.119.0,36.165.1"}
P.entries["item:black-feather-quill"] = {n="Schwarzer Federkiel",s="Der Schwarze Federkiel ist ein heiliges Nachtelfenrelikt, das von den Druiden der Klaue während ihrer Riten des Winterschlafs und des Erwachens verwendet wird. Verwahrt in einer dafür vorgesehenen Truhe in den Grabhügeln von Ban'ethil, ist er einer von mehreren lebenswichtigen Foki, die benötigt werden, um schlummernde Druiden sicher aus dem Smaragdgrünen Traum zurückzurufen.",h="Der Schwarze Federkiel ist ein heiliges Nachtelfenrelikt, das von den Druiden der Klaue während ihrer Riten...",kw={"athridas bearmantle","grabhügel von ban'ethil","schwarzer federkiel","truhe der schwarzen feder","dolanaar","druiden der klaue","relikte des erwachens"},ang={["class:Druid"]="Für Druiden steht der Federkiel für die heiligen Werkzeuge, die die Schüler der Klaue an die wache Welt binden, während ihre Geister mit dem Smaragdgrünen Traum kommunizieren.",["race:NightElf"]="Nachtelfen betrachten die Entweihung der Reliktkisten von Ban'ethil durch Furbolgs der Gnarlpine als eine weitere schmerzhafte Erinnerung an die fortschreitende Verderbnis von Teldrassil."},sec={{t="Ein Gefäß des Erwachens",b="Der Druidismus der Nachtelfen stützt sich auf tief eingestimmte, heilige Gegenstände, um die Schwelle zwischen der wachen Welt und dem Smaragdgrünen Traum zu überwinden. Der Schwarze Federkiel bildet zusammen mit dem Rabenkrallentalisman, dem Saphir des Himmels und der Rune des Nistens das zentrale Set an Ritualgegenständen, die erforderlich sind, um den empfindlichen Winterschlaf der Druiden der Klaue zu beenden. Ohne diese Foki riskiert ein schlummernder Druide, auf unbestimmte Zeit im Traum gefangen zu bleiben und nicht mehr in seinen wachen Körper zurückkehren zu können."},{t="Die Bedrohung in Ban'ethil",b="Als verdorbene Furbolgs der Gnarlpine die Grabhügel von Ban'ethil überrannten, gerieten die heiligen Truhen, in denen diese Schätze aufbewahrt wurden, in Gefahr. Unbewacht in den verwinkelten Tiefen zurückgelassen, mussten die Relikte auf Befehl von Athridas Bearmantle in Dolanaar rasch geborgen werden, bevor die gefangenen Druiden für immer an den Traum verloren gingen."}},faq={{q="Wofür wird der Schwarze Federkiel verwendet?",a="Der Federkiel ist eines der vier Relikte des Erwachens, die notwendig sind, um Druiden der Klaue sicher aus ihrem rituellen Winterschlaf im Smaragdgrünen Traum zu wecken.",al={"schwarzer federkiel zweck","warum schwarzer federkiel gebraucht wird","was der federkiel bewirkt"}},{q="Wo wird der Schwarze Federkiel aufbewahrt?",a="Er wird in der Truhe der schwarzen Feder tief im Inneren der Grabhügel von Ban'ethil im zentralen Teldrassil aufbewahrt.",al={"schwarzer federkiel fundort","wo ist die truhe der schwarzen feder","federkiel fundort"}},{q="Warum können die Druiden nicht ohne den Federkiel und die anderen Relikte aufwachen?",a="Der druidische Winterschlaf erfordert das Eintreten in den Smaragdgrünen Traum unter empfindlichen Verzauberungen. Das Brechen dieser Trance erfordert bestimmte heilige Foki; ohne sie kann der schlummernde Geist nicht richtig zu seinem physischen Körper zurückfinden.",al={"warum druiden relikte zum aufwachen brauchen","können druiden von selbst aufwachen"}},{q="Wer verlangt nach dem Schwarzen Federkiel?",a="Athridas Bearmantle in Dolanaar weist Abenteurer an, den Federkiel zusammen mit den anderen Relikten des Erwachens zu bergen, um die gefährdeten Druiden zu retten.",al={"wer braucht den federkiel","schwarzer federkiel questgeber"}}},fp="19,297,20.476.0,23.306.0,41.144.0,38.117.0,64.227.0,37.144.0"}
P.entries["item:blackened-skull"] = {n="Geschwärzter Schädel",s="Ein geschwärzter Schädel ist der verkohlte Schädelrest eines Darkeye Bonecasters, der in Agamands Mühlen umhergeht. Todeswache Dillinger in Brill verlangt diese grausigen Trophäen als Beweis für die Ausdünnung der geistlosen Streitkräfte der Geißel, die Tirisfal bedrohen.",h="Ein geschwärzter Schädel ist der verkohlte Schädelrest eines Darkeye Bonecasters, der in Agamands Mühlen...",kw={"agamands mühlen","geschwärzter schädel","brill","darkeye bonecaster","todeswache dillinger","schartige rippe","geißel","die überrannte mühle"},ang={["class:Mage"]="Die Untersuchung des versengten Knochens offenbart, wie rohes, instabiles nekromantisches Zauberwirken direkt durch die eigene physische Hülle des skelettierten Zauberwirkers brennt.",["race:Undead"]="Für die Verlassenen ist das Bezwingen der Darkeye Bonecasters eine Frage des reinen Überlebens, um zu verhindern, dass ihr einstiger Meister einen Stützpunkt direkt vor ihrer Haustür errichtet."},sec={{t="Trophäe der Bonecaster",b="Verkohlt und von nekromantischen Energien durchdrungen, werden diese Schädel von den Darkeye Bonecasters geborgen, die Agamands Mühlen heimsuchen. Diese skelettierten Zauberwirker richten ihre nekromantische Bosheit gleichermaßen gegen die Lebenden wie gegen die Verlassenen und versuchen, einen Vorposten für die Armeen des Lichkönigs im nördlichen Tirisfal zu errichten. Das Vorzeigen ihrer zerstörten Schädel bei Todeswache Dillinger dient als handfester Beweis dafür, dass die mystische Vorhut der Geißel zerschlagen wird."}},faq={{q="Woher stammen geschwärzte Schädel?",a="Sie werden aus den Überresten von Darkeye Bonecasters geborgen, den skelettierten Zauberwirkern, die die Felder und Gebäude rund um Agamands Mühlen im nördlichen Tirisfal durchstreifen.",al={"geschwärzter schädel herkunft","wer lässt geschwärzte schädel fallen","wo man geschwärzte schädel bekommt"}},{q="Warum verlangt Todeswache Dillinger geschwärzte Schädel?",a="Todeswache Dillinger beauftragt Verteidiger der Verlassenen damit, geschwärzte Schädel und gekerbte Rippen als Beweis für den aktiven Kampf gegen die Geißel zu sammeln. Die Verlassenen können es nicht zulassen, dass die geistlosen Diener des Lichkönigs so nahe an Brill und Unterstadt Fuß fassen.",al={"dillinger schädel","warum schädel sammeln","mühlen überrannt schädel"}},{q="Warum sind die Schädel geschwärzt?",a="Die Verkohlung und Verfärbung sind das Ergebnis der unbeständigen dunklen Magie, die von den Bonecasters gewirkt wird und beim Zaubern ihre eigenen spröden, wiederbelebten Knochen versengt.",al={"warum ist er geschwärzt","geschwärzter schädel lore"}},{q="Was tut die Geißel bei Agamands Mühlen?",a="Die Geißel versucht, das verlassene Agamands Mühlen als vorgeschobenen Aufmarschort zu befestigen, um von dort aus tiefergehende Angriffe und Überfälle in ganz Tirisfal zu starten.",al={"agamands mühlen geißel","warum ist die geißel bei den mühlen"}}},fp="15,242,25.453.0,36.174.0,52.262.0,29.172.0,43.162.0"}
P.entries["item:bloodfeather-belt"] = {n="Blutfedergürtel",s="Ein Blutfedergürtel ist ein grober Lederriemen, der von den Blutfederharpien getragen wird, die das nördliche Teldrassil heimsuchen. Schildwache Arynia Cloudsbreak sammelt diese Gürtel als Beweis dafür, dass die örtlichen Nester geräumt wurden, die auf Die Lichtung des Orakels übergreifen.",h="Ein Blutfedergürtel ist ein grober Lederriemen, der von den Blutfederharpien getragen wird, die das nördliche...",kw={"arynia cloudsbreak","blutfeder","blutfedergürtel","harpyie","die lichtung des orakels","teldrassil","die verzauberte lichtung"},ang={["faction:Alliance"]="Schildwache Arynia Cloudsbreak beizustehen stellt sicher, dass die lebenswichtigen Berichte der uralten Bäume von Teldrassil die Führung in Darnassus ohne Unterbrechung erreichen.",["race:NightElf"]="Die Blutfederbrut entweiht das natürliche Blätterdach von Teldrassil, und Die Lichtung des Orakels von ihren kreischenden Nestern zu befreien, ist eine essenzielle Pflicht für jeden Beschützer der Heimat der Kaldorei."},sec={{t="Trophäen aus den Nestern",b="Die Blutfederharpien haben sich aggressiv in den Ästen rund um Die Lichtung des Orakels eingenistet, bedrohen den uralten Orakelbaum und ersticken den Reiseverkehr im nördlichen Teldrassil. Als ein Läufer mit Berichten für Darnassus von der Schar überfallen und getötet wurde, rief Schildwache Arynia Cloudsbreak Reisende dazu auf, direkt gegen ihre Nester vorzugehen. Den gefallenen Harpyien die Gürtel abzunehmen, dient als greifbarer Beweis dafür, dass ihre Zahl dezimiert wird, um die Pfade zu sichern und die Verbindung zur Hauptstadt wiederherzustellen."}},faq={{q="Warum verlangt Schildwache Arynia Cloudsbreak nach diesen Gürteln?",a="Arynia Cloudsbreak und ihre kleine Abteilung von Schildwachen sind dort stationiert, um den heiligen Orakelbaum vor den umliegenden Blutfedernestern zu schützen. Da die Harpyien kürzlich einen nach Darnassus entsandten Boten getötet haben, verlangt Arynia die Gürtel als handfesten Beweis dafür, dass Abenteurer die Nester säubern und die Reihen der Schar ausdünnen.",al={"warum arynia gürtel will","zweck blutfedergürtel","warum gürtel sammeln"}},{q="Woher stammen die Blutfedergürtel?",a="Sie werden von den Blutfederharpien erbeutet, die in den Bäumen und Felsen rund um Die Lichtung des Orakels im nördlichen Teldrassil hausen. Alle Harpyienarten dieses Schwarms, einschließlich Windhexen, Zauberinnen, Schurkinnen und Furien, tragen sie bei sich.",al={"wer lässt blutfedergürtel fallen","wo man gürtel bekommt","fundort blutfedergürtel"}},{q="Warum stellen Harpyien auf der Lichtung des Orakels ein Problem dar?",a="Die Harpyien haben sich in unmittelbarer Nähe des Orakelbaums eingenistet, eines uralten und verehrten Baumes, der über die Gesundheit des Weltenbaums wacht. Ihre aggressive Gegenwart schneidet die Schildwachen ab, die die Lichtung bewachen, und unterbricht gewaltsam die Übermittlung von Nachrichten nach Darnassus.",al={"harpyien lichtung des orakels","warum gibt es harpyien in teldrassil","harpyienbedrohung orakelbaum"}}},fp="17,234,23.505.0,54.329.0,38.237.0,46.263.0"}
P.entries["item:bloodfury-ripper-s-remains"] = {n="Überreste der Blutfurienzerfetzerin",s="Überreste der Blutfurienzerfetzerin sind der physische Beweis, der von der Matriarchin der Bloodfury-Harpyien im Verbrannten Tal erbeutet wurde. Diese von Maggran Earthbinder in Sonnenfels gesuchte Trophäe bestätigt den Tod der wilden Anführerin der Brut und versetzt der Harpyienpräsenz, die die örtliche Taurensiedlung bedroht, einen entscheidenden Schlag.",h="Überreste der Blutfurienzerfetzerin sind der physische Beweis, der von der Matriarchin der Bloodfury-Harpyien...",kw={"bloodfury-zerfetzerin","das verbrannte tal","harpyien","maggran earthbinder","überreste","steinkrallengebirge","sonnenfels"},ang={["faction:Horde"]="Das Beseitigen wilder Gefahren wie der Bloodfury-Matriarchin gewährleistet sicheres Geleit für Karawanen und Späher der Horde, die zwischen dem Brachland und dem Steinkrallengebirge reisen.",["race:Tauren"]="Die Bloodfury-Harpyien bedrohen unmittelbar die Sicherheit von Sonnenfels, was das Bergen der Überreste ihrer Anführerin zu einem Akt der Hingabe zum Schutz der friedlichen Taurensiedlungen im Steinkrallengebirge macht."},sec={{t="Durchtrennung der Blutlinie",b="Die Bloodfury-Harpyien, die in den versengten Ruinen des Verbrannten Tals nisten, stellen seit Langem eine grausame Bedrohung für die Reisenden und Schamanen des Steinkrallengebirges dar. Während das Ausdünnen ihrer Zahl die unmittelbare Gefahr verringert, erkennt Maggran Earthbinder aus Sonnenfels, dass eine wahre Erleichterung die Beseitigung ihrer Führung erfordert. Die Bloodfury-Zerfetzerin herrscht beinahe wie eine Königin über ihre Schar und leitet deren territoriale Aggression. Ihre Überreste zu nehmen ist der wesentliche Beweis für ihr Ende, stürzt die verbleibenden Harpyien in Verwirrung und schenkt den Tauren Seelenfrieden, die sich darum bemühen, ihre schroffen Lande zu heilen und zu sichern."}},faq={{q="Wofür werden die Überreste der Blutfurienzerfetzerin verwendet?",a="Sie dienen als unbestreitbarer physischer Beweis für den Tod der Bloodfury-Zerfetzerin. Maggran Earthbinder in Sonnenfels verlangt sie, um zu bestätigen, dass die königengleiche Anführerin der örtlichen Harpyien endgültig beseitigt wurde.",al={"was bewirken die überreste","zweck der überreste","wer will die überreste"}},{q="Wo kann die Bloodfury-Zerfetzerin gefunden werden?",a="Die Bloodfury-Zerfetzerin durchstreift die westlichen und nordwestlichen Hügelketten des Verbrannten Tals im südlichen Steinkrallengebirge und hebt sich durch ihr auffälliges blaues Gefieder von ihrer purpur-weißen Schar ab.",al={"aufenthaltsort der bloodfury-zerfetzerin","wo ist die zerfetzerin","bloodfury-zerfetzerin finden"}},{q="Warum will Maggran Earthbinder ihren Tod?",a="Maggran glaubt, dass das bloße Ausdünnen gewöhnlicher Harpyien deren Überfälle auf die umliegenden Lande niemals stoppen wird. Das Erschlagen ihrer Matriarchin bricht ihre Hierarchie und schwächt ihre Fähigkeit, sich gegen Sonnenfels zu formieren.",al={"warum bloodfury-zerfetzerin töten","maggrans beweggrund","warum zerfetzerin tot"}}},fp="26,326,22.609.0,45.216.0,36.194.0,43.218.0"}
P.entries["item:bloodstone-choker"] = {n="Blutsteinhalsschmuck",s="Der Blutsteinhalsschmuck ist ein dunkler magischer Talisman aus Blutstein, der sich ursprünglich im Besitz des Hexenmeisterlehrers Gakin der Dunkelbinder befand. Er wurde von einer verräterischen Schülerin gestohlen, die zur Bruderschaft der Defias floh, und dient als mächtiger Ritualfokus, der die Leere durchdringen kann, um einen Leerwandler herbeizurufen und zu binden.",h="Der Blutsteinhalsschmuck ist ein dunkler magischer Talisman aus Blutstein, der sich ursprünglich im Besitz...",kw={"blutsteinhalsschmuck","defias","gakin der dunkelbinder","surena caledon","die bindung","zum geschlachteten lamm","leerwandler","hexenmeister"},ang={["class:Warlock"]="Für Hexenmeister der Allianz ist die Wiederbeschaffung des Blutsteinhalsschmucks ein entscheidender Übergangsritus, der die grundlegende Zauberkunst mit dem Befehligen gewaltiger dämonischer Diener verbindet.",["faction:Alliance"]="Surena Caledons Flucht zur Bruderschaft der Defias veranschaulicht, wie gewöhnliche Geächtete in Elwynn aktiv nach gefährlichen okkulten Relikten suchen, um ihre Rebellion gegen Stormwind voranzutreiben."},sec={{t="Ein gestohlener Kanalisator",b="In den verborgenen Kammern unterhalb des Gasthauses Slaughtered Lamb in Stormwind aufbewahrt, war der Blutsteinhalsschmuck eines der geschätzten Ritualwerkzeuge von Gakin der Dunkelbinder. Seine Ruhe fand ein jähes Ende, als Surena Caledon, eine angehende Hexenmeisterin unter Gakins Anleitung, ihren Mentor verriet und das Amulett stahl. Surena floh in die Wälder von Elwynn, um sich mit der geächteten Bruderschaft der Defias zu verbünden, und nahm den verzauberten Halsschmuck sowohl als Abzeichen der Macht als auch als Verhandlungsmasse mit. Seine Wiederbeschaffung erfordert, sie bei Brackwells Kürbisbeet zur Strecke zu bringen, bevor die Banditen seine gefährlichen Energien für ihre eigenen Pläne nutzen können."},{t="Die Zähmung der Leere",b="Aus Blutstein gehauen, besitzt der Halsschmuck die schlummernde mystische Autorität, die erforderlich ist, um die sterbliche Welt mit den sich windenden Schatten des Wirbelnden Nethers zu verbinden. Sobald er zu Gakin zurückgebracht wurde, wird er in den Krypten unter der Taverne sogleich auf die Probe gestellt. Ein Hexenmeister muss die Magie des Halsschmucks am unterirdischen Beschwörungskreis kanalisieren, um einen feindseligen Leerwandler aus der Leere zu reißen. Nur indem ein Praktizierender das wütende Wesen im direkten Kampf bezwingt, während er den Talisman führt, kann er die Willenskraft beweisen, die nötig ist, um einen solchen Wächter zu befehligen."}},faq={{q="Was ist der Blutsteinhalsschmuck?",a="Er ist eine verzauberte Halskette aus Blutstein, die von Hexenmeistern als ritueller Kanalisator verwendet wird. Sie besitzt genug magische Kraft, um die Realität zu zerreißen und einen widerspenstigen Leerwandler aus dem Nether zu beschwören.",al={"blutsteinhalsschmuck","was ist der halsschmuck","was bewirkt der halsschmuck"}},{q="Wem gehörte der Halsschmuck ursprünglich?",a="Er gehört Gakin der Dunkelbinder, einem Meisterhexenmeister, der Auszubildende in den geheimen Kellerebenen unter Zum Geschlachteten Lamm im Mage Quarter von Stormwind ausbildet.",al={"wem gehört der halsschmuck","gakin halsschmuck","woher stammt der halsschmuck"}},{q="Warum wurde der Halsschmuck gestohlen?",a="Surena Caledon, eine Schülerin unter Gakin, kehrte ihren Studien den Rücken und stahl den Halsschmuck, bevor sie floh, um sich der Bruderschaft der Defias anzuschließen. Sie suchte nach Macht und verbündete sich mit den Banditen, die sich im Wald von Elwynn verstecken.",al={"wer hat ihn gestohlen","warum stahl surena ihn","surena caledon halsschmuck"}},{q="Wie wird der Halsschmuck in der Ausbildung von Hexenmeistern eingesetzt?",a="Nach seiner Wiederbeschaffung wird der Halsschmuck über dem Beschwörungskreis in den Krypten unter Zum Geschlachteten Lamm aktiviert. Er lockt einen Leerwandler hervor, den der angehende Hexenmeister besiegen und unterwerfen muss, um die Herrschaft über den Dämon zu erlangen.",al={"halsschmuck benutzen","leerwandler ritual halsschmuck","die bindung halsschmuck"}}},fp="17,307,16.598.1,15.530.0,30.192.0,32.165.0,26.211.0,43.226.0"}
P.entries["item:blueleaf-tuber"] = {n="Blaulaubknolle",s="Blaulaubknollen sind außergewöhnlich seltene Wurzelgemüse, die verborgen unter dem dornigen Gelände des Krals von Razorfen wachsen. Weltweit als exotische kulinarische Delikatesse geschätzt, sind sie mit bloßem Auge fast unmöglich zu entdecken.",h="Blaulaubknollen sind außergewöhnlich seltene Wurzelgemüse, die verborgen unter dem dornigen Gelände des Krals...",kw={"brachland","blaulaubknolle","mebok mizzyrix","ratchet","der kral von razorfen","schnüfflererdhörnchen","knolle"},ang={["profession:Cooking"]="Weltweit als geschätzte kulinarische Delikatesse bekannt, sind diese Wurzeln trotz ihres Wachstums im unwirtlichen Schmutz der Borstennackenhöhlen bei den wohlhabendsten Feinschmeckern begehrt."},sec={{t="Eine seltene unterirdische Delikatesse",b="Obwohl sie im Brachland heimisch sind, wachsen Blaulaubknollen ausschließlich in den unterirdischen Tiefen unter dem Kral von Razorfen. Verborgen unter dichten Wurzelsystemen und den Dornen der Borstennacken, bleiben sie gewöhnlichen Sammlern verborgen. Trotz ihrer rauen Wachstumsbedingungen erzielen sie exorbitante Preise bei wohlhabenden Feinschmeckern und Händlern weltweit, die ihren einzigartigen Geschmack schätzen."},{t="Ernte mit Unterstützung von Erdhörnchen",b="Da die Wurzeln von Oberflächenbewohnern kaum zu erkennen sind, ersann der geschäftstüchtige Goblin Mebok Mizzyrix in Ratchet eine ungewöhnliche Erntemethode. Durch das Abrichten einheimischer Schnüfflererdhörnchen darauf, die Knollen aus fünfzig Schritt Entfernung am Geruch aufzuspüren, können Abenteurer, angeleitet durch spezielle Kommandostöcke, die Wurzeln aus dem Boden ausgraben, bevor Borstennackenpatrouillen Wind von dem Eindringen bekommen."}},faq={{q="Wofür werden Blaulaubknollen verwendet?",a="Blaulaubknollen werden als seltene kulinarische Delikatessen gehandelt. Wohlhabende Kunden und exotische Händler zahlen Spitzenpreise für ihren unverwechselbaren Geschmack und ihre Seltenheit.",al={"knollennutzen","warum blaulaubknollen sammeln","wofür sind knollen"}},{q="Wo sind Blaulaubknollen zu finden?",a="Sie wachsen ausschließlich tief unter der Erde im südlichen Brachland, inmitten der Dornen und unterirdischen Höhlen des Krals von Razorfen.",al={"wo wachsen blaulaubknollen","knollenfundort","wo gibt es knollen"}},{q="Warum benötigt man ein Erdhörnchen, um sie auszugraben?",a="Die Knollen wachsen verborgen unter der Muttererde und können weder von Menschen- noch von Goblinaugen gesehen werden. Schnüfflererdhörnchen sind darauf abgerichtet, sie aus fünfzig Schritt Entfernung zu wittern und auf Befehl auszugraben.",al={"warum schnüfflererdhörnchen","zweck der erdhörnchen","warum erdhörnchen"}},{q="Wer kauft diese Knollen?",a="Mebok Mizzyrix, ein Goblin-Unternehmer mit Sitz in Ratchet, kauft sie auf, um sie mit beträchtlichem Gewinn an wohlhabende Käufer und internationale Kontakte weiterzuverkaufen.",al={"wer will blaulaubknollen","wer kauft knollen","mebok knollen"}}},fp="14,233,27.356.0,26.382.0,34.143.0,35.122.0,40.188.0,22.146.0"}
P.entries["item:book-stresses-of-iron"] = {n="Buch: Belastbarkeit von Eisen",s="The Stresses of Iron ist ein wissenschaftlicher metallurgischer Text von Margulf Blaggon. Ursprünglich in der Royal Library von Stormwind Keep aufbewahrt, wurde er zum Gegenstand eines Botengangs zwischen Mönchen, nachdem er zum Abschreiben an die Abtei von Nordhain ausgeliehen worden war.",h="The Stresses of Iron ist ein wissenschaftlicher metallurgischer Text von Margulf Blaggon.",kw={"bruder kristoff","bruder paxton","margulf blaggon","metallurgie","milton sheaf","abtei von nordhain","royal library","stresses of iron"},ang={["profession:Blacksmithing"]="Dieser von Margulf Blaggon verfasste Wälzer befasst sich eingehend mit den strukturellen Festigkeiten und den praktischen Grenzen der Bearbeitung von Eisen."},sec={{t="Ein ausgeliehener Band",b="The Stresses of Iron wurde von Margulf Blaggon verfasst und behandelt die praktischen sowie theoretischen Eigenschaften der Metallurgie. Das in der Royal Library in Stormwind Keep unter der Obhut von Milton Sheaf aufbewahrte Buch wurde an die Abtei von Nordhain verliehen, damit Bruder Paxton seinen Inhalt für seine eigene Sammlung von Hand abschreiben konnte. Paxtons Abschrift dauerte weitaus länger als erwartet, sodass Bruder Kristoff auf dem Cathedral Square ungeduldig auf die Rückkehr des Textes in die Stadt wartete."}},faq={{q="Worum geht es in dem Buch?",a="The Stresses of Iron ist ein akademisches Handbuch über Metallurgie und Metallbearbeitung, verfasst von dem Gelehrten Margulf Blaggon.",al={"was ist stresses of iron","stresses of iron thema","buchinhalt"}},{q="Warum befand sich das Buch in der Abtei von Nordhain?",a="Bruder Paxton lieh sich den Band aus Stormwinds Royal Library aus, um dessen Text für seine persönliche Sammlung akribisch von Hand abzuschreiben, bevor er das Original zurückgab.",al={"warum hatte paxton es","warum in nordhain"}},{q="Wer forderte die Rückgabe des Buches?",a="Bruder Kristoff, der auf dem Cathedral Square stationiert war, bat dringend um den Text, was einen Abenteurer dazu veranlasste, dessen Verbleib zwischen der Royal Library und Nordhain nachzugehen.",al={"wer braucht das buch","wer wartet darauf"}}},fp="22,247,17.466.0,23.121.0,37.159.0,29.173.0"}
P.entries["item:bottle-of-disease"] = {n="Krankheitsflasche",s="Eine Krankheitsflasche ist eine Phiole mit virulenten Gebräuen, die von den in Ashenvale operierenden Verlassenen gebraut wurden. Diese Phiolen, die in einem Lager nahe dem Dor'danil-Grabhügel gefunden wurden, stellen einen unheilvollen Versuch der Untoten dar, die Pest in die unberührte Wildnis der Nachtelfen einzuschleusen.",h="Eine Krankheitsflasche ist eine Phiole mit virulenten Gebräuen, die von den in Ashenvale operierenden...",kw={"ashenvale","die pest","krankheitsflasche","der dor'danil-grabhügel","forest song","verlassene","verlassenenkrankheit","kayneth stillwind"},ang={["class:Druid"]="Verseuchte Gemische und künstliche Seuchen stellen den Gegenpol zum natürlichen Gleichgewicht dar und erfordern das rasche Eingreifen jedes Druiden, der sich dem Schutz des Waldes verschrieben hat.",["race:NightElf"]="Die Entweihung des Bodens von Ashenvale durch untote Seuchen ist ein unverzeihlicher Frevel an den Kaldorei, insbesondere wenn sie vor den Toren des Dor'danil-Grabhügels zusammengebraut werden."},sec={{t="Die Pest in den heiligen Wäldern",b="Tief unter dem uralten Blätterdach des östlichen Ashenvale sind die Verlassenen weit hinter die Frontlinien der Warsongvorhut geschlichen. In einem Außenposten nahe dem Dor'danil-Grabhügel brauen untote Alchemisten üble Seuchen und versiegeln sie in Glasflaschen. Für die Nachtelfen, die Forest Song bewachen, sind diese Phiolen ein klarer Beweis für eine heimliche, tückische Offensive, die darauf abzielt, den Waldboden und die Tierwelt zu vergiften, anstatt sich auf offene Kämpfe einzulassen."},{t="Kayneth Stillwinds Nachforschungen",b="Kayneth Stillwind, ein in Forest Song stationierter Schildwachen-Nachtelf, sucht nach Beweisen für die finsteren Absichten der Verlassenen. Die Bergung einer Krankheitsflasche ermöglicht es Stillwind, ihren Inhalt direkt zu analysieren. Die Nachtelfen fürchten, dass diese Gebräue nicht bloß Kriegswaffen gegen bewaffnete Wachen sind, sondern kalkulierte Reagenzien, die darauf ausgelegt sind, heilige Grabhügel zu verderben und Geist und Körper der Verteidiger des Waldes zu brechen."}},faq={{q="Was befindet sich in der Krankheitsflasche?",a="Die Flasche enthält synthetische Gifte und magische Seuchen, die von Apothekern der Verlassenen gebraut wurden. Diese üblen Mischungen sollen lebendes Fleisch und den Boden verderben und spiegeln die umfassenderen Experimente der Königlichen Apothekervereinigung mit virulenten Seuchen wider.",al={"was ist in der flasche","inhalt krankheitsflasche","trank der verlassenen"}},{q="Wo sind diese Flaschen zu finden?",a="Sie befinden sich in einem abgelegenen Lager der Verlassenen südlich von Forest Song, nahe dem Eingang zum Dor'danil-Grabhügel im östlichen Ashenvale.",al={"wo krankheitsflasche finden","krankheitsflasche standort","lager der verlassenen ashenvale"}},{q="Wer möchte die Krankheitsflasche haben?",a="Kayneth Stillwind, ein Nachtelfenbeschützer am Außenposten von Forest Song, beauftragt Abenteurer der Allianz damit, eine Flasche zu beschaffen, damit er ihren Inhalt analysieren und die wahren Absichten der Horde ergründen kann.",al={"wer nimmt krankheitsflasche","krankheitsflasche abgeben","kayneth stillwind quest"}},{q="Warum brauen die Verlassenen in Ashenvale Seuchen?",a="Die Nachtelfen vermuten, dass die Verlassenen beabsichtigen, den heiligen Wald heimlich zu infizieren und die nahe gelegenen Grabhügel zu entweihen, wodurch das natürliche Ökosystem vergiftet und der Widerstand der Nachtelfen von innen heraus geschwächt werden soll.",al={"warum verlassene in ashenvale","ziel der untoten in ashenvale","verlassene grabhügel"}}},fp="17,281,26.448.0,33.411.1,37.245.0,30.155.0,32.201.0,51.201.0"}
P.entries["item:bottle-of-moonshine"] = {n="Flasche mit Fusel",s="Eine Flasche mit Fusel ist eine hochprozentige Spirituose, die in der düsteren Siedlung Dunkelhain verkauft wird. Barkeeper Daniels aus Seenhain sucht dringend nach einer Flasche, um die Taverne des Ortes wieder aufzustocken, da Übergriffe der Blackrock-Orcs die regulären Versorgungslieferungen abgeschnitten haben.",h="Eine Flasche mit Fusel ist eine hochprozentige Spirituose, die in der düsteren Siedlung Dunkelhain verkauft...",kw={"barkeeper daniels","flasche mit fusel","dunkelhain","trockene zeiten","dämmerwald","seenhain","fusel","scarlet raven tavern"},ang={["faction:Alliance"]="Das Heranschaffen von Spirituosen aus Dunkelhain nach Seenhain verdeutlicht die brüchigen Nachschublinien, die die verstreuten Siedlungen des Königreichs Stormwind in Krisenzeiten miteinander verbinden."},sec={{t="Hochprozentige Linderung",b="Seenhain wird vom Blackrockclan belagert, was den örtlichen Gastwirt Barkeeper Daniels in eine arge Notlage bringt, da die regulären Versorgungskarawanen ausbleiben. Um die Moral der Stadtwachen und der bedrängten Stadtbevölkerung aufrechtzuerhalten, schickt Daniels Boten durch die südlichen Königreiche, um regionale Spezialitäten zu beschaffen. Darunter befindet sich eine kräftige Flasche mit Fusel, die in der Scarlet Raven Tavern im benachbarten Dämmerwald gebraut und verkauft wird, wo die Einheimischen hochprozentige Getränke bevorzugen, um die schleichende Furcht der Wälder abzuwehren."}},faq={{q="Wo kann ich eine Flasche mit Fusel finden?",a="Eine Flasche mit Fusel kann beim Barkeeper in der Scarlet Raven Tavern in Dunkelhain erworben werden, gelegen in den finsteren Gefilden des Dämmerwalds.",al={"wo man fusel kaufen kann","dunkelhain fusel fundort","flasche mit fusel händler"}},{q="Wer möchte diese Flasche?",a="Barkeeper Daniels, der Gastwirt von Seenhain im Rotkammgebirge, verlangt diese Flasche zusammen mit mehreren anderen regionalen Getränken, um seinen Keller während einer andauernden Orc-Belagerung gefüllt zu halten.",al={"wer braucht fusel","fusel quest abgabe","barkeeper daniels fusel"}},{q="Warum geht Seenhain der Alkohol aus?",a="Feindselige Blackrock-Orcs haben das Rotkammgebirge überrannt, Straßen überfallen und Handelswege gekappt. Reguläre Nachschublieferungen sind ausgeblieben, sodass die Tavernenregale von Seenhain praktisch leer sind.",al={"warum trockene zeiten","seenhain nachschubmangel","rotkamm alkoholmangel"}}},fp="19,241,17.497.0,39.146.0,22.186.0,39.200.0"}
P.entries["item:bottle-of-zombie-juice"] = {n="Flasche mit Zombiesaft",s="Eine Flasche mit Zombiesaft ist eine potente, übelriechende Spirituose, die aus der stechenden Faulblüte des Dämmerwalds gebraut wird. Sie wird aus der Taverne in Dunkelhain bezogen und angeblich von dem einsiedlerischen Calvinius verlangt, um die Kälte der düsteren Wälder abzuwehren.",h="Eine Flasche mit Zombiesaft ist eine potente, übelriechende Spirituose, die aus der stechenden Faulblüte des...",kw={"calvinius","flasche mit zombiesaft","dunkelhain","dämmerwald","saftlieferung","faulblüte","zombiesaft"},ang={["faction:Alliance"]="Botengänge zwischen Dunkelhain und der schattenhaften Wildnis helfen dabei, die geplagten Bewohner des Dämmerwalds miteinander in Verbindung zu halten, selbst wenn die Aufgaben zweifelhaft erscheinen.",["profession:Herbalism"]="Kräuterkundige, die mit dem Dämmerwald vertraut sind, erkennen Faulblüten als Zutat an, die für gewöhnliche Stärkungstonika ungeeignet ist, was ihre Destillation zu einem Getränk umso beunruhigender macht."},sec={{t="Ein beizendes Gebräu",b="Aus Faulblüten gebraut, die in den schattigen Böden des Dämmerwalds gesammelt werden, ist Zombiesaft ein bemerkenswert scharfes Gebräu. Der Schankwirt, der ihn ausgibt, warnt davor, dass das Getränk stark genug ist, um die Toten zu erwecken. Während gewöhnliche Leute einen weiten Bogen um solch abscheuliche Destillate machen, behauptet der exzentrische Einsiedler Calvinius, es sei das Einzige, was ihn in den feuchten, kalten Nächten an seiner einsamen Hütte warmhalten könne."},{t="Fragwürdiger Durst",b="Obwohl Calvinius darauf beharrt, die Spirituose diene lediglich als feuriger Schlummertrunk, deutet sein Versprecher bei Erhalt der Flasche – bei dem er beinahe die „Dummheit“ statt der Güte des Boten lobt – darauf hin, dass das Gebräu einem finstereren, unheilvolleren Zweck dienen könnte als einfacher Wirtshauswärme."}},faq={{q="Woraus wird Zombiesaft hergestellt?",a="Zombiesaft ist eine destillierte Spirituose, die aus Faulblüten hergestellt wird, einer übelriechenden Pflanze, die in den verdorbenen Böden des Dämmerwalds wächst.",al={"zombiesaft zutaten","was ist in zombiesaft"}},{q="Wer möchte diese Flasche geliefert bekommen?",a="Die Flasche wird von Calvinius verlangt, einem exzentrischen Einsiedler, der in einer einsamen Hütte an den westlichen Grenzen des Dämmerwalds lebt.",al={"wer braucht zombiesaft","für wen ist zombiesaft","zombiesaft lieferung"}},{q="Warum will Calvinius Zombiesaft?",a="Calvinius behauptet, er brauche das feurige Getränk, um seine alten Knochen in den bitteren, dunklen Nächten des Dämmerwalds warmzuhalten, auch wenn sein seltsames Verhalten vermuten lässt, dass er andere Verwendungen für ein so potentes Gebräu haben könnte.",al={"warum trinkt calvinius ihn","calvinius zombiesaft grund"}},{q="Können Spieler die Flasche mit Zombiesaft trinken?",a="Nein, diese spezielle Flasche ist ein Questgegenstand, der ausschließlich für die Lieferung an Calvinius bestimmt ist, und Eure Hauptaufgabe besteht darin, sie sicher zu seiner Hütte zu bringen.",al={"kann man zombiesaft trinken","ist zombiesaft konsumierbar"}}},fp="22,249,20.398.0,19.287.1,31.130.0,32.136.0,39.204.0,45.142.0"}
P.entries["item:bottom-of-gelkak-s-key"] = {n="Unterteil von Gelkaks Schlüssel",s="Das Unterteil von Gelkaks Schlüssel ist eines von drei Fragmenten eines zerbrochenen mechanischen Aufziehschlüssels, der dem schiffbrüchigen Gnomenpiraten Gelkak Gyromast gehört. Nachdem sein Schiff vor der Küste der Darkshore untergegangen war, wurde das Stück von den an der Küste heimischen Riffkriechern geplündert.",h="Das Unterteil von Gelkaks Schlüssel ist eines von drei Fragmenten eines zerbrochenen mechanischen...",kw={"kriecher","darkshore","erster maat","gelkak","gyromast","schlüssel","bergung","schiffbruch"},ang={["profession:Engineering"]="Ingenieure werden das Teil als Fragment eines speziellen Aufziehwerkzeugs erkennen, das für den Antrieb komplexer Uhrwerk-Automaten entwickelt wurde.",["race:Gnome"]="Gnome werden zu schätzen wissen, dass Gyromast sich selbst als Schiffbrüchiger an einer feindseligen Küste auf den Erfindergeist von Uhrwerken verließ statt auf eine Mannschaft aus Fleisch und Blut."},sec={{t="Von Kriechern beansprucht",b="Als das Schiff von Gelkak Gyromast vor der Küste der Darkshore von Dreschadon versenkt wurde, wurde der Gnom zusammen mit seinen Habseligkeiten an Land gespült. Zu seinen wertvollsten Besitztümern gehörte der Aufziehschlüssel, mit dem er seinen mechanischen Ersten Maat aktivierte. Der Schlüssel zerschellte an den Küstengesteinen in drei verschiedene Teile, und einheimische Aasfresser stürzten sich sogleich auf die Trümmer. Das Unterteil des Schlüssels wurde von den aggressiven Krebstieren an sich gerissen, die durch die Brandung streifen – insbesondere den Riff- und Gezeitenkriechern, die den Unrat entlang der Flutlinie durchkämmen."},{t="Wiederzusammensetzung",b="Gelkak kann sein mechanisches Besatzungsmitglied nicht aktivieren, ohne das untere Fragment wieder mit dem mittleren und oberen Teil zu vereinen, die von Küsten-Murlocs und Waldschreitern des Binnenlands weggeschleppt wurden. Nur wenn er dieses schwere Segment aus den Panzern der Küstenkrabben herausbricht, kann der Gnomenpirat hoffen, sein Konstrukt wiederherzustellen und Rache für seine ruinierte Expedition zu nehmen."}},faq={{q="Wofür wird das Unterteil von Gelkaks Schlüssel verwendet?",a="Es ist eines von drei Teilen, die benötigt werden, um den Aufziehschlüssel des gestrandeten Piraten Gelkak Gyromast zu reparieren, der zur Reaktivierung seines mechanischen Ersten Maats gebraucht wird.",al={"was macht gelkaks schlüssel","zweck von unterteil von gelkaks schlüssel","warum brauche ich gelkak schlüsselunterteil"}},{q="Woher stammt dieser Schlüsselteil?",a="Er wird an der Küste der Darkshore gefunden, eingesammelt von einheimischen Krabben wie Verkrusteten Gezeitenkriechern und Wütenden Riffkriechern entlang des Wassersaums.",al={"wo findet man unterteil von gelkaks schlüssel","wer lässt unterteil von gelkaks schlüssel fallen","fundort gelkak schlüsselunterteil"}},{q="Warum ist der Schlüssel in drei Teile zerbrochen?",a="Als Gelkaks Schiff von Dreschadon zerstört wurde, wurde er an Land gespült und der Schlüssel prallte auf die Küstenfelsen, wobei er in Fragmente zerbrach, die sich unter der einheimischen Tierwelt verteilten.",al={"warum zerbrach gelkaks schlüssel","wie zerbrach der schlüssel"}},{q="Wer ist Gelkak Gyromast?",a="Gelkak Gyromast ist ein gestrandeter Gnomenpirat, der an den Ufern der Darkshore sein Lager aufgeschlagen hat, nachdem ein Angriff von Dreschadon sein Schiff zerstört und seine Ausrüstung verstreut hat.",al={"wer ist gelkak","gelkak gyromast geschichte"}}},fp="22,256,19.545.0,10.356.1,44.167.0,36.144.0,40.173.0,23.147.0"}
P.entries["item:branch-of-cenarius"] = {n="Zweig des Cenarius",s="Der Zweig des Cenarius ist ein heiliges Relikt der Dryaden, das von dem niederträchtigen Satyr Geltharis im östlichen Ashenvale gestohlen wurde. Die Wiederbeschaffung dieses Erbstücks war der letzte Wunsch der sterbenden Dryade Anilia, die bei seiner Verteidigung gegen die Verderber des Waldes umkam.",h="Der Zweig des Cenarius ist ein heiliges Relikt der Dryaden, das von dem niederträchtigen Satyr Geltharis im...",kw={"anilia","ashenvale","zweig des cenarius","dryade","forest song","geltharis","illiyana","satyr"},ang={["class:Druid"]="Als Schüler des Cenarius empfinden Druiden die persönliche Verpflichtung, jedes Artefakt, das den Namen des Waldherrn trägt, vor der Schändung durch die dämonischen Satyrn zu bewahren.",["race:NightElf"]="Für die Nachtelfen von Ashenvale ist die Unterstützung der Dryaden und die Rückbeschaffung ihrer verlorenen Ahnenschätze eine heilige Pflicht gegenüber der Natur."},sec={{t="Ein heiliger Ast, dem Schatten anheimgefallen",b="Von den Töchtern des Cenarius verehrt, verkörpert der Zweig des Cenarius sowohl den Segen des Waldherrn als auch die tiefe Verbindung, die seine Dryaden mit Ashenvale aufrechterhalten. Der Zweig wurde von den Dryadenschwestern Anilia und Illiyana in hohen Ehren gehalten, bis eine Schar verdorbener Satyrn sie überfiel. Der Anführer der Satyrn, Geltharis, riss das Relikt an sich und verwundete Anilia nahe den verderbten Ruinen im östlichen Ashenvale tödlich. Mit ihren letzten Atemzügen deutete Anilia nach Norden in Richtung des Bogens, wo Geltharis lauert, und flehte um einen Champion, der den heiligen Ast aus seinen Klauen entreißen und ihn in die Hände der Dryaden in Forest Song zurückbringen möge."}},faq={{q="Was ist der Zweig des Cenarius?",a="Der Zweig des Cenarius ist ein geschätztes Naturrelikt, das den Dryaden von Ashenvale teuer ist. Da er den Namen und den Segen des Halbgottes Cenarius trägt, dient er als heiliges Symbol für ihre Obhut über den uralten Wald.",al={"lore zum zweig des cenarius","was ist dieser zweig","dryadenzweig"}},{q="Wer hat den Zweig des Cenarius gestohlen?",a="Das Relikt wurde von dem niederträchtigen Satyr Geltharis gestohlen, der einen Hinterhalt auf die Dryaden im östlichen Ashenvale anführte. Geltharis streckte die Dryade Anilia nieder und floh mit dem Zweig in seinen Klauen hinter einen steinernen Torbogen im Norden.",al={"wer nahm den zweig","wer stahl ihn","wer lässt zweig des cenarius fallen"}},{q="Wem gehört der Zweig?",a="Der Zweig gehört den Dryaden von Forest Song. Da Anilia bei seiner Verteidigung starb, wird das Relikt zu ihrer trauernden Schwester Illiyana zurückgebracht, womit Anilias letzter Wunsch erfüllt wird.",al={"wer bekommt den zweig","wer will den zweig","wem übergeben"}},{q="Wo wird der Zweig geborgen?",a="Der Zweig befindet sich bei Geltharis, der nördlich der Ruinen im östlichen Ashenvale lauert, unweit der Grenze zu Azshara, wo Anilia zusammenbricht.",al={"fundort des zweigs","wo ist geltharis","wo findet man den zweig"}}},fp="18,222,31.608.0,31.220.0,33.224.0,30.178.1,30.140.0"}
P.entries["item:brass-collar"] = {n="Messinghalsband",s="Das Messinghalsband ist ein robustes Halsband, das von Princess getragen wird, einer preisgekrönten Sau im Besitz der Familie Brackwell. Es dient Mutter Stonefield als handfester Beweis dafür, dass die gefräßige Bestie erlegt wurde, bevor sie die Ernte ihres Hofes ruinieren konnte.",h="Das Messinghalsband ist ein robustes Halsband, das von Princess getragen wird, einer preisgekrönten Sau im...",kw={"brackwells kürbisbeet","messinghalsband","wald von elwynn","mutter stonefield","princess","princess must die","hof der stonefields"},ang={["faction:Alliance"]="Für junge Abenteurer, die der Landbevölkerung von Elwynn beistehen, ist das Erbeuten von Princess' Halsband ein klassischer Ritus des Erwachsenwerdens bei der Schlichtung kleinstädtischer Bauernfehden."},sec={{t="Eine Trophäe bäuerlicher Rivalität",b="Princess ist kein gewöhnliches Schwein; sie ist ein riesiges, preisgekröntes Schwein der Familie Brackwell, das auf deren Kürbisbeet östlich des Maclure-Anwesens umherstreift. Zum Unglück ihrer Nachbarn wird ihre preisgekrönte Größe durch einen unersättlichen Appetit auf die Feldfrüchte auf dem Hof der Stonefields genährt. Da Mutter Stonefield es leid ist, ihr wertvolles Gemüse an den herumstreunenden Vielfraß zu verlieren, sucht sie jemanden, der bereit ist, die gewaltige Sau zu erlegen. Da Princess ein auffälliges Messingband um den Hals trägt, dient ihr Halsband als unbestreitbarer Beweis dafür, dass das marodierende Schwein die Felder der Stonefields nie wieder plündern wird."}},faq={{q="Woher stammt das Messinghalsband?",a="Das Halsband wird von Princess erbeutet, einer riesigen, preisgekrönten Sau, die auf Brackwells Kürbisbeet im östlichen Wald von Elwynn hinter der Maclure-Farm herumwühlt.",al={"messinghalsband herkunft","wer lässt messinghalsband fallen","wo bekommt man messinghalsband"}},{q="Warum möchte Mutter Stonefield das Halsband haben?",a="Princess schleicht sich regelmäßig zum Hof der Stonefields, um Mutter Stonefields Prachtgemüse zu verschlingen. Das Halsband an sich zu nehmen beweist Mutter Stonefield, dass das Tier endlich erlegt wurde, bevor es den Rest ihrer Ernte vernichten konnte.",al={"warum stonefield halsband will","mutter stonefield halsband zweck"}},{q="Wem gehört Princess?",a="Princess gehört den Brackwells, darf sich jedoch auf deren Kürbisbeet zusammen mit ihren kleineren Ebergewährten frei bewegen.",al={"princess besitzer","wem gehört das schwein"}},{q="Kann außer Princess noch jemand diesen Gegenstand fallenlassen?",a="Nein. Das Messinghalsband gibt es nur bei Princess; es wurde eigens so angefertigt, dass es um den enormen Halsumfang der preisgekrönten Sau der Brackwells passt.",al={"weitere halsband beute","wo sonst messinghalsband finden"}}},fp="12,230,28.593.0,38.158.0,39.223.0,18.132.0,46.123.0"}
P.entries["item:bristleback-attack-plans"] = {n="Angriffspläne der Borstennacken",s="Die Angriffspläne der Borstennacken sind grobe Karten und taktische Notizen, die von den Stachelebern der Dornrankenklamm verfasst wurden. Sie skizzieren eine koordinierte Belagerung, die direkt darauf abzielt, die Taurensiedlung Camp Narache zu überrennen.",h="Die Angriffspläne der Borstennacken sind grobe Karten und taktische Notizen, die von den Stachelebern der...",kw={"angriffspläne","dornrankenklamm","borstennacken","camp narache","häuptling hawkwind","mulgore","stacheleber"},ang={["faction:Horde"]="Das Vereiteln der Borstennacken-Offensive stellt sicher, dass die Horde einen sicheren, unbedrohten Stützpunkt in den heiligen Ebenen von Mulgore behält.",["race:Tauren"]="Die Aufdeckung dieses Komplotts verteidigt genau die Übungsplätze, an denen junge Tauren ihre ersten Riten ablegen, und schützt Eure Ältesten sowie Neulinge vor einer brutalen Belagerung durch die Stacheleber."},sec={{t="Eine Verschwörung gegen die Mesa",b="Tief in einer Erdhöhle in der Dornrankenklamm verborgen, enthüllen diese gekritzelten taktischen Skizzen, dass die Borstennacken-Stacheleber nicht mehr nur an den Grenzen der Red Cloud Mesa plänkeln. Stattdessen plante ihre Führung einen organisierten, anhaltenden Angriff, um nach Camp Narache vorzustoßen und die jungen Tauren auszulöschen, die dort trainieren. Die Übergabe dieser Karte an Häuptling Hawkwind ermöglicht es dem Stamm, Boten nach Bloodhoof zu schicken, um Verstärkung anzufordern und die drohende Invasion abzuwehren, bevor sie beginnen kann."}},faq={{q="Was enthalten die Angriffspläne der Borstennacken?",a="Die Pläne bestehen aus einer taktischen Karte und groben Anweisungen, die eine groß angelegte Belagerung von Camp Narache beschreiben, was darauf hindeutet, dass sich die Stacheleber für einen langwierigen Angriff anstatt für sporadische Überfälle formieren.",al={"was sind die angriffspläne","was ist auf der karte","angriffspläne der borstennacken"}},{q="Wo sind diese Pläne zu finden?",a="Sie liegen verlassen auf dem Erdboden einer erhöht gelegenen Höhle in der Dornrankenklamm, gleich an einem Seitenpfad oberhalb der Hütte des Häuptlings der Borstennacken.",al={"wo sind die pläne","wo finde ich die karte","fundort angriffspläne der borstennacken"}},{q="Was unternimmt Häuptling Hawkwind, sobald er die Pläne erhält?",a="Häuptling Hawkwind erkennt die drohende Gefahr für die Mesa und nutzt die Informationen, um Hilfe und Krieger aus Bloodhoof herbeizurufen, um die Verteidigung von Camp Narache zu verstärken.",al={"was macht hawkwind","reaktion von camp narache","häuptling hawkwind reaktion"}},{q="Warum greifen die Borstennacken Camp Narache an?",a="Der Stamm der Borstennacken beansprucht die territoriale Vorherrschaft über die dornigen Schluchten und betrachtet die Präsenz der Tauren auf der Mesa aggressiv als Eindringen, was sie dazu treibt, die Siedlung vollständig vertreiben zu wollen.",al={"warum greifen stacheleber an","motiv der borstennacken"}}},fp="24,212,23.494.0,45.200.0,28.143.0,55.171.1,47.208.0"}
P.entries["item:bristleback-belt"] = {n="Gürtel der Borstennacken",s="Ein Gürtel der Borstennacken ist ein grob gefertigtes Ausrüstungsteil, das von den Stachelebern getragen wird, welche die Dornrankenklamm heimsuchen. Für junge Tauren, die im Camp Narache erwachsen werden, dient das Sammeln dieser Gürtel als handfester Beweis ihres Mutes während des Ritus der Kraft.",h="Ein Gürtel der Borstennacken ist ein grob gefertigtes Ausrüstungsteil, das von den Stachelebern getragen...",kw={"gürtel","dornrankenklamm","borstennacken","camp narache","häuptling hawkwind","stacheleber","red cloud mesa","ritus der kraft"},ang={["faction:Horde"]="Das Eindämmen der aggressiven Stacheleber von Mulgore sichert die südlichen Grenzen des Kernlandes der Horde im zentralen Kalimdor.",["race:Tauren"]="Das Erbeuten des Gürtels eines gefallenen Borstennackens ist ein Initiationsritus für jeden Jugendlichen auf der Red Cloud Mesa und markiert den ersten Schritt zur Anerkennung durch die Ältesten in Thunder Bluff."},sec={{t="Beweis des Ritus",b="Der Stamm der Red Cloud prüft jeden Jugendlichen, der sich den Respekt in Thunder Bluff verdienen möchte, durch die uralten Riten der Erdenmutter. Die erste Prüfung, der Ritus der Kraft, verlangt vom Initianden, den Stamm vor aktiven Bedrohungen zu schützen. Da die feindseligen Borstennacken-Stacheleber immer wieder Nahrungsvorräte des Stammes plündern und Jagdgesellschaften außerhalb von Camp Narache überfallen, fordert Häuptling Hawkwind die Gürtel dieser Eindringlinge. Die Rückkehr mit zwölf Gürteln zum Häuptling beweist, dass ein Initiand der Gefahr direkt entgegentreten und einen Schlag zur Verteidigung des Stammes führen kann."},{t="Handwerk der Stacheleber",b="Diese Gürtel, die den Kriegern und Schamanen der Borstennacken in der gesamten Dornrankenklamm abgenommen werden, sind aus grobem Leder, Schnüren und Schrott gefertigt. Obwohl sie als Kleidung für einen Taurenkrieger wertlos sind, sind sie von unverkennbarer Stacheleber-Machart und dienen als unmissverständlicher Beweis für einen getöteten Feind. Sie in den Kreis des Lagers zurückzubringen, erfüllt die Tradition, ohne die natürlichen Gaben des Landes an bedeutungslosen Trophäen zu verschwenden."}},faq={{q="Wofür werden Gürtel der Borstennacken verwendet?",a="Häuptling Hawkwind in Camp Narache verlangt zwölf Gürtel der Borstennacken als physischen Beweis dafür, dass ein Initiand den Ritus der Kraft abgeschlossen hat, den ersten der traditionellen Riten der Erdenmutter.",al={"wozu gürtel der borstennacken","gürtel der borstennacken zweck","wofür ist dieser gürtel"}},{q="Woher stammen Gürtel der Borstennacken?",a="Sie werden von Borstennacken-Stachelebern und Schamanen der Borstennacken erbeutet, die in der Dornrankenklamm direkt östlich von Camp Narache auf der Red Cloud Mesa hausen.",al={"woher gürtel der borstennacken","wer droppt gürtel der borstennacken","gürtel der borstennacken fundort"}},{q="Warum verlangt Häuptling Hawkwind Gürtel statt Köpfe oder Waffen?",a="Gürtel sind unverkennbare persönliche Gegenstände der Stacheleber, die leicht gesammelt und transportiert werden können, ohne die Grundsätze der Erdenmutter gegen das Nehmen von verschwenderischen, grausamen Trophäen zu verletzen.",al={"warum gürtel","hawkwind beweis"}},{q="Warum geraten die Borstennacken ins Visier?",a="Die Borstennacken sind von der Dornrankenklamm aus auf das Land des Stammes vorgedrungen, haben Camp Narache im Schutz der Nacht überfallen und taurische Jagdtrupps auf der Hochebene aus dem Hinterhalt angegriffen.",al={"warum borstennacken töten","stacheleber bedrohung mulgore"}}},fp="16,239,17.547.0,14.412.0,36.190.0,37.150.0,63.189.0,40.168.0"}
P.entries["item:bristleback-quilboar-tusk"] = {n="Stacheleberhauer der Borstennacken",s="Stacheleberhauer der Borstennacken werden von den erschlagenen Borstennackenstachelebern im nördlichen und zentralen Brachland erbeutet. Als Beweis für das Blutbad gesammelt, dienen sie dem trauernden Orc-Krieger Mankrik als grausige Zeichen der Rache.",h="Stacheleberhauer der Borstennacken werden von den erschlagenen Borstennackenstachelebern im nördlichen und...",kw={"brachland","borstennacken","von hass zerfressen","crossroads","mankrik","stacheleber","hauer"},ang={["faction:Horde"]="Die Stacheleber bedrohen das Crossroads und die Versorgungswege im Brachland; das Sammeln der Hauer unterstützt sowohl Mankriks private Vendetta als auch die umfassenderen Bemühungen der Horde, die Region zu befrieden.",["race:Orc"]="Orcs verstehen Blutschulden und Kriegertrauer, weshalb Mankriks brutale Suche nach sechzig Stacheleber-Trophäen eine Frage geteilter Ehre ist."},sec={{t="Trophäen der Rache",b="Borstennackenstacheleber bewohnen Dickichte und dornige Höhlen im gesamten Brachland und verteidigen ihr Territorium erbittert gegen die Ausbreitung der Horde. Ihre Hauer sind markantes, gezacktes Elfenbein, das im Nahkampf als natürliche Waffe eingesetzt wird. Für Mankrik, einen im Crossroads stationierten erfahrenen Krieger, dessen Frau bei einem bösartigen Überfall der Stacheleber verschollen ging, stellen diese Hauer mehr als bloße Jägertrophäen dar. Dutzende von ihnen zu sammeln, ist ein Akt purer Vergeltung – eine blutige Abrechnung, die sicherstellen soll, dass die Borstennacken ebenso tief leiden wie er."}},faq={{q="Wer will diese Hauer?",a="Mankrik, ein im Crossroads im Brachland stationierter Orc-Krieger, verlangt nach ihnen. Nach einem tragischen Hinterhalt, der ihn von seiner Frau trennte, sucht er Vergeltung an den Borstennackenstachelebern.",al={"wer braucht borstennackenhauer","wer nimmt stacheleberhauer der borstennacken","hauer abgeben"}},{q="Warum will Mankrik so viele Hauer?",a="Mankrik ist von Trauer und Wut zerfressen, nachdem er von Plünderern der Stacheleber überwältigt und für tot zurückgelassen wurde. Das Zusammentragen von sechzig Hauern liefert ihm den greifbaren Beweis, dass der Stamm der Borstennacken im Gegenzug unerbittlich dezimiert wird.",al={"warum 60 hauer","warum will mankrik hauer","mankrik rache"}},{q="Welche Stacheleber tragen diese Hauer bei sich?",a="Sie werden von Mitgliedern des Stammes der Borstennacken erbeutet, die das nördliche und zentrale Buschland sowie die Dornenlager des Brachlands durchstreifen.",al={"wo droppen borstennackenhauer","wer droppt stacheleberhauer der borstennacken"}},{q="Dienen diese Hauer einem anderen Zweck als Mankriks Blutrache?",a="Nein. Während Hauer von Stachelebern mitunter für Stammesverzierungen oder Handelswaren verwendet werden, werden diese speziellen Trophäen einzig gesammelt, um Mankriks Rachedurst zu stillen.",al={"borstennackenhauer verwendung","kann man mit stacheleberhauern herstellen"}}},fp="25,231,21.526.0,22.195.0,36.217.0,33.138.0,63.171.0"}
P.entries["item:brock-s-list"] = {n="Brocks Liste",s="Brocks Liste ist eine Depesche, die vom Bergbaulehrer Brock Stoneseeker in Thelsamar verfasst wurde. Sie enthält die Namen der besten Bergbauschüler, die sich Ehren-Hacken aus den Gildenhallen in Ironforge verdient haben.",h="Brocks Liste ist eine Depesche, die vom Bergbaulehrer Brock Stoneseeker in Thelsamar verfasst wurde.",kw={"brocks liste","golnir bouldertoe","great forge","ironforge","loch modan","bergbau","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="Für Schürfer steht Brocks Liste für die offizielle Anerkennung von Lehrlingen, die über einfachen Schotter hinauswachsen und in die stolzen Traditionen der Bergbaugilde Tiefenschacht eintreten.",["race:Dwarf"]="Das Pergament spiegelt das handwerkliche Erbe der Zwerge wider und ehrt Jugendliche, die sich mit Spitzhacke und Schaufel unter Khaz Modan hervorgetan haben."},sec={{t="Die Auszeichnung eines Bergarbeiters",b="Der Bergbau ist das Lebenselixier der Zwergenzivilisation, und angehende Schürfer müssen ihr Können unter Beweis stellen, bevor ihnen ernsthafte Arbeiten in den Adern von Khaz Modan anvertraut werden. In Thelsamar stellt der örtliche Bergbaulehrer dieses Pergament zusammen, um Schüler zu belohnen, die sich in ihren Lektionen hervortun. Das Dokument verzeichnet jene, die sich Ehren-Hacken verdient haben – begehrte Symbole der Kompetenz, die in der Hauptstadt geschmiedet werden."},{t="Der Weg zur Great Forge",b="Da die Ehrenwerkzeuge in der Hauptstadt graviert und von dort verteilt werden müssen, wird das Pergament Reisenden anvertraut, die nach Ironforge aufbrechen. Auf dem Rücken eines Greifen vom Horst in Thelsamar transportiert, gelangt Brocks Liste direkt zu Golnir Bouldertoe bei der Bergbaugilde Tiefenschacht in der Great Forge, wo die Namen der geehrten Schüler in Stein und Stahl graviert werden."}},faq={{q="Was ist Brocks Liste?",a="Es ist ein Verzeichnis, das vom Bergbaulehrer Brock Stoneseeker in Thelsamar verfasst wurde. Es führt die Lehrlinge auf, die in ihrer Bergbauausbildung Bestnoten erzielt und sich für zeremonielle Spitzhacken qualifiziert haben.",al={"brocks liste","was ist dieser gegenstand","brocks liste zweck"}},{q="Wem überbringe ich Brocks Liste?",a="Zuerst zeigt Ihr die Liste Thorgrum Borrelson, dem Greifenmeister in Thelsamar, um Euch die Reise zu sichern. Anschließend bringt Ihr sie direkt zu Golnir Bouldertoe bei der Bergbaugilde Tiefenschacht in der Great Forge von Ironforge.",al={"wohin mit der liste","wer bekommt brocks liste","brocks liste abgeben"}},{q="Warum benötigt Golnir Bouldertoe dieses Dokument?",a="Golnir beaufsichtigt die Werkzeuge der Bergbaugilde Tiefenschacht in Ironforge. Er hat eine Kiste mit Ehren-Hacken vorbereitet und benötigt Brocks schriftliches Verzeichnis, um den Namen jedes Schülers in seine Belohnung zu meißeln.",al={"warum golnir","warum braucht ironforge die liste"}},{q="Warum wird die Liste per Greif und nicht zu Fuß verschickt?",a="Obwohl die Gebirgspässe durch Loch Modan zurück nach Dun Morogh führen, ist ein Greifenflug über den Horstmeister Thorgrum Borrelson der schnellste und sicherste Weg, um Gildenangelegenheiten direkt in die Great Forge zu befördern.",al={"warum nach ironforge fliegen","warum einen greifen nehmen"}}},fp="12,201,21.384.0,27.365.0,21.191.0,33.217.0,46.199.0,49.221.0"}
P.entries["item:broken-and-battered-samophlange"] = {n="Zerbrochenes und ramponiertes Samophlang",s="Das Zerbrochenes und ramponiertes Samophlang ist ein rätselhaftes mechanisches Gerät, das aus Operationen der Venture Company im Brachland geborgen wurde. Nachdem ein verpfuschter Bastelversuch seine strukturelle Integrität auf ein kritisches Tief gebracht hat, muss es zu Goblinexperten in Orgrimmar gebracht werden, die seine Funktionsweise vielleicht tatsächlich verstehen.",h="Das Zerbrochenes und ramponiertes Samophlang ist ein rätselhaftes mechanisches Gerät, das aus Operationen der...",kw={"brachland","maschinenwerkstatt","nogg","orgrimmar","rilli greasygob","samophlang","venture company","wenikee boltbucket"},ang={["faction:Horde"]="Die Bergung industriellen Schrotts aus Unternehmungen der Venture Company im Brachland bringt wertvolle technische Geheimnisse direkt in die Goblin-Maschinenwerkstätten von Orgrimmar.",["profession:Engineering"]="Das willkürliche Anbringen von Anzeigen und Hebeln an einem ohnehin instabilen Mechanismus der Venture Company dient als klassische Warnung vor planlosen Modifikationen ohne Bauplan."},sec={{t="Zur Unkenntlichkeit verbastelt",b="Ein Samophlang ist eine obskure, geschützte Maschinerie, die von der Venture Company für ihre Rohstoffoperationen im nördlichen Brachland entworfen wurde. Als Wenikee Boltbucket versuchte, ein solches zu inspizieren und zu modifizieren, brachte sie überflüssige Messgeräte, Hebel und Anzeigen an, um dessen Stabilität zu messen. Anstatt den Mechanismus zu stabilisieren, zerstörte ihre amateurhafte Bastelei dessen strukturelle Integrität und hinterließ ihn ramponiert und am Rande des Verfalls. Da sie erkannte, dass noch mehr Spielereien nur zum völligen Ausfall führen würden, schickte sie die zerbrechliche Konstruktion zu jemandem mit echter Fabrikerfahrung."},{t="Der Weg nach Orgrimmar",b="Die Rettung des zerbrochenen Geräts erfordert den Sachverstand von jemandem, der direkt an den Produktionslinien der Venture Company gearbeitet hat. Dies führt Reisende zu Rilli Greasygob, einem ehemaligen Angestellten der Venture Company, der nun in Noggs Maschinenwerkstatt im Valley of Honor in Orgrimmar tätig ist. Die Übergabe eines derart ramponierten Apparats fällt dem Ingenieur sofort ins Auge und zeichnet jeden, der wagemutig genug ist, Goblinoperationen zu plündern, entweder als bemerkenswert kühn oder als waghalsig aus."}},faq={{q="Was ist ein Samophlang?",a="Ein Samophlang ist ein spezialisiertes Maschinenteil, das von der Venture Company für ihre industriellen Operationen im Brachland hergestellt wurde. Seine genaue innere Mechanik ist ein arkanes Geheimnis der Goblin-Ingenieurskunst, das nur wenige Außenstehende vollends begreifen.",al={"was ist dieser gegenstand","was macht ein samophlang","samophlang zweck"}},{q="Warum ist das Samophlang zerbrochen und ramponiert?",a="Wenikee Boltbucket versuchte, es mit zusätzlichen Messgeräten zu modifizieren, um seine strukturelle Integrität zu prüfen. Ihre Anbauten schlugen völlig fehl, beeinträchtigten die Stabilität des Geräts und beschädigten seine empfindlichen inneren Komponenten.",al={"wer hat das samophlang beschädigt","warum ist es beschädigt","wenikee hat es zerstört"}},{q="Wer kann diesen beschädigten Apparat reparieren?",a="Das Gerät erfordert jemanden, der Erfahrung mit Maschinerie der Venture Company hat. Es wird zu Rilli Greasygob gebracht, einem Ingenieur, der in Noggs Maschinenwerkstatt im Valley of Honor in Orgrimmar arbeitet.",al={"zu wem bringe ich das","wohin gehört das samophlang","wer repariert es"}},{q="Woher stammte diese Maschinerie ursprünglich?",a="Sie stammte aus den Bohr- und Förderoperationen der Venture Company im nördlichen Brachland, wo Goblin-Ingenieure sie nutzen, um schwere Fördermaschinen anzutreiben.",al={"samophlang herkunft","wo wurde es gefunden","venture company herkunft"}}},fp="31,309,27.565.0,21.445.0,22.229.0,43.222.0,35.182.0,46.169.0"}
P.entries["item:broken-samophlange"] = {n="Zerbrochenes Samophlang",s="Das Zerbrochene Samophlang ist ein rätselhaftes mechanisches Gerät, das aus dem nördlichen Brachland geborgen wurde. Trotz seines beschädigten Zustands faszinieren seine internen Zahnräder und beweglichen Teile Ingenieure, die neugierig genug sind, um seine wahre Funktion zu ergründen.",h="Das Zerbrochene Samophlang ist ein rätselhaftes mechanisches Gerät, das aus dem nördlichen Brachland geborgen...",kw={"brachland","zerbrochenes samophlang","zahnräder","der mor'shan-schutzwall","samophlang","undermine","wenikee boltbucket"},ang={["faction:Horde"]="Das Gerät taucht inmitten der Territorien der Horde im Brachland auf, was zu einer Zusammenarbeit zwischen lokalen Außenposten, Tüftlern und neutralen Handelskontakten führt.",["profession:Engineering"]="Das Samophlang stellt für Ingenieure ein klassisches, unwiderstehliches Rätsel dar: eine komplizierte Maschine mit empfindlichen internen Zahnrädern, deren Zweck nur ergründet werden kann, indem man sie zerlegt und wieder zum Laufen bringt."},sec={{t="Ein verblüffender Mechanismus",b="Das Samophlang bleibt eine der seltsameren Vorrichtungen, die man im nördlichen Brachland finden kann. Selbst in zerbrochenem Zustand zeugt der Mechanismus von bemerkenswerter interner Handwerkskunst, angefüllt mit beweglichen Baugruppen und feinen Zahnrädern. Sein Entdecker beschädigte den empfindlichen Apparat versehentlich, bevor seine vollständige Funktionsweise dokumentiert werden konnte. Eifrig darauf bedacht, neugierigen Kollegen in Undermine funktionierende Ergebnisse zu liefern, suchte der Finder nach jemandem, der geschickt genug war, um ihn wiederherzustellen, und wandte sich an Wenikee Boltbucket – eine geschickte Tüftlerin, die nahe dem Grenzaußenposten Der Mor'shan-Schutzwall stationiert ist."},{t="Die Hände einer Tüftlerin gesucht",b="Bei der Untersuchung des ruinierten Apparats kann selbst ein wissbegieriger Verstand wie der von Wenikee nicht sofort ableiten, wozu ein Samophlang eigentlich gedacht ist. Die verlockenden Geräusche des internen Uhrwerks und seine dynamische Bewegung wecken jedoch sofort ihr Interesse. Anstatt den ruinierten Schrott wegzuwerfen, inspiriert das Geheimnis seines Entwurfs sie zu dem Versuch, ihn zu reparieren und seine Mechanismen unter voller Leistung arbeiten zu sehen."}},faq={{q="Was ist ein Samophlang?",a="Seine genaue Funktion ist ein Rätsel, selbst für die Tüftler, die versuchen, es zu reparieren. Während sein Name Betrachter vor ein Rätsel stellt, offenbart der Umgang mit dem Gerät komplexe Zahnräder und bewegliche Teile, die für einen unbekannten industriellen Zweck entworfen wurden.",al={"samophlang zweck","was macht ein samophlang","samophlang definition"}},{q="Warum ist das Samophlang zerbrochen?",a="Sein ursprünglicher Entdecker ging bei seinen Manipulationen unsachgemäß mit der empfindlichen Maschinerie um. Als er bemerkte, dass das Gerät blockierte, bevor seine Geheimnisse mit Kollegen in Undermine geteilt werden konnten, suchte er nach einem Experten, um es wieder in Gang zu bringen.",al={"wie ging es kaputt","zerbrochenes samophlang lore"}},{q="Wer ist Wenikee Boltbucket?",a="Wenikee Boltbucket ist eine wissbegierige Tüftlerin im nördlichen Brachland, knapp südlich des Mor'shan-Schutzwalls an der Grenze zu Ashenvale. Sie besitzt die ingenieurstechnische Neugier, die nötig ist, um seltsame Vorrichtungen zu untersuchen und zu rekonstruieren.",al={"wo ist wenikee","boltbucket standort"}},{q="Warum sind Goblins in Undermine daran interessiert?",a="Goblin-Ingenieure und -Unternehmer sind stets darauf bedacht, einzigartige mechanische Technologie nachzubauen. Die Kunde von dem seltsamen Gerät erreichte Kontakte in Undermine und rief sofortiges Interesse bezüglich jeglicher Vorteile hervor, die es bieten könnte.",al={"undermine interesse","warum interessiert es goblins"}}},fp="18,223,20.553.0,24.409.0,22.209.0,30.228.0,26.230.0,46.234.0"}
P.entries["item:broken-tools"] = {n="Zerbrochene Werkzeuge",s="Zerbrochene Werkzeuge sind die zertrümmerten Überreste von Spitzhacken zwergischer Prospektoren, die absichtlich auf einem Amboss zerstört wurden. Sie dienen Baine Bloodhoof als handfester Beweis dafür, dass die invasive Zwergenausgrabung, die Mulgores Land und Tierwelt bedroht, gestört wurde.",h="Zerbrochene Werkzeuge sind die zertrümmerten Überreste von Spitzhacken zwergischer Prospektoren, die...",kw={"baine bloodhoof","zerbrochene werkzeuge","ausgrabungsstätte","zwergen-buddelei","schmiede","mulgore","spitzhacke der prospektoren"},ang={["profession:Blacksmithing"]="Die systematische Zerstörung feiner zwergischer Schmiedearbeit auf einem Amboss verwandelt die Schmiede des Handwerkers in ein Instrument zur Verteidigung des Territoriums.",["race:Tauren"]="Für die Tauren stellt das Überbringen der ruinierten Werkzeuge an Baine die Verteidigung der Erdenmutter gegen das invasive Ausheben dar, welches die einheimischen Bestien peinigt."},sec={{t="Sabotage der Grabung",b="Nordwestlich von Bloodhoof haben zwergische Ausgräber ihr Lager aufgeschlagen, um in die Hügel von Mulgore vorzudringen. Während die Zwerge nach vergrabener uralter Geschichte suchen, betrachten die Tauren ihre aggressive Grabung als direkte Schändung der Erdenmutter. Der Lärm und die Zerstörung beunruhigen die einheimische Tierwelt, insbesondere die umherstreifenden Kodoherden. Anstatt die Ausgräber lediglich zu vertreiben, weist der junge Baine Bloodhoof Verteidiger an, die eisernen Spitzhacken der Prospektoren zu beschlagnahmen und sie an einer Schmiede zu zerschlagen, wodurch die Expedition daran gehindert wird, noch tiefer in die Erde einzudringen."}},faq={{q="Was sind diese Zerbrochenen Werkzeuge?",a="Es sind die ruinierten Köpfe und zersplitterten Schäfte von Spitzhacken der Prospektoren, die den zwergischen Ausgräbern in Mulgore abgenommen und an einer Schmiede vorsätzlich zerschlagen wurden.",al={"zerbrochene werkzeuge","was sind zerbrochene werkzeuge","zertrümmerte spitzhacken"}},{q="Warum will Baine Bloodhoof, dass sie zerstört werden?",a="Baine glaubt, dass das Aufreißen des Bodens das Land entweiht und Mulgores Tierwelt, insbesondere die Kodos, erzürnt. Das Zerschlagen ihrer Werkzeuge stoppt die Grabungen und sendet die klare Botschaft, dass das Land seine Weisheit nicht an rücksichtslose Ausgrabungen preisgeben wird.",al={"warum spitzhacken zerstören","warum baine zerbrochene werkzeuge will","baine zwergen-buddelei"}},{q="Wo können diese Spitzhacken zerbrochen werden?",a="Jede funktionstüchtige Schmiede ist dafür geeignet. Ihr könnt die Schmiede direkt an der zwergischen Ausgrabungsstätte nutzen oder eine in Bloodhoof bzw. oben in Thunder Bluff aufsuchen.",al={"wie man spitzhacken zerbricht","wo ist die schmiede","spitzhacke der prospektoren zerbrechen"}},{q="Warum graben die Zwerge in Mulgore?",a="Die Zwerge glauben, dass tief unter dem Boden von Mulgore uralte Geheimnisse und Relikte der Antike begraben liegen. Bei ihrer obsessiven Suche nach ihren Ursprüngen höhlen sie häufig fremde Länder aus, ohne Rücksicht auf die einheimischen Bewohner zu nehmen.",al={"warum zwerge in mulgore","zwergengrabungsstätte mulgore"}}},fp="12,250,18.570.0,28.152.0,45.239.0,32.165.0,35.218.0"}
P.entries["item:bundle-of-crocolisk-skins"] = {n="Bündel Krokiliskenhäute",s="Das Bündel Krokiliskenhäute ist ein hergerichtetes Paket aus gegerbten Reptilienhäuten, die in den gefährlichen Sümpfen des Sumpflands erbeutet wurden. Bestimmt für die Lederverarbeiter im Hafen von Menethil, dient es als wertvolle Handelsware zur Herstellung robuster Stiefel und widerstandsfähiger Hafenausrüstung.",h="Das Bündel Krokiliskenhäute ist ein hergerichtetes Paket aus gegerbten Reptilienhäuten, die in den...",kw={"krokilisk","einar","james halloran","leder","der hafen von menethil","sida","häute","sumpfland"},ang={["faction:Alliance"]="Außerhalb lebende Jäger liefern die Materialien, mit denen die Garnison und die Bürger vom Hafen von Menethil für die rauen, sumpfigen Elemente gerüstet bleiben."},sec={{t="Handel im Sumpfland und häuslicher Zwist",b="In den weitläufigen Wasserwegen des Sumpflands wimmelt es von Krokilisken, deren zähe, wasserabweisende Häute ein unverzichtbares Gut für die Küstensiedlung Der Hafen von Menethil sind. Jäger, die den Mooren trotzen, sammeln und gerben diese Häute, bevor sie sie gen Westen an örtliche Handwerker wie James Halloran schicken. Dieses spezielle Bündel nahm jedoch einen ungewöhnlichen Umweg über die Hände eines Abenteurers: Der Jäger Einar suchte lediglich deshalb nach einem Boten, um nicht in die Stadt zurückkehren und dem Zorn seiner frustrierten Frau Sida entgegentreten zu müssen."}},faq={{q="Wofür wird das Bündel Krokiliskenhäute verwendet?",a="Das Bündel besteht aus rohen, gegerbten Sumpfhäuten, die für James Halloran bestimmt sind, einen Gerber im Hafen von Menethil. Halloran verarbeitet die widerstandsfähigen Häute zu langlebigen Stiefeln, Gürteln und Lederrüstungen, die sich bestens dafür eignen, im feuchten, überfluteten Terrain des Sumpflands zu bestehen.",al={"krokiliskenhäute verwendung","wofür sind diese häute","bündel häute zweck"}},{q="Wer hat diese Krokiliskenhäute gesammelt?",a="Die Häute wurden von dem Jäger Einar draußen in den Sümpfen erbeutet und gebündelt. Obwohl er seine Handelswaren gewöhnlich selbst in die Stadt bringt, bittet er stattdessen vorbeireisende Wanderer, sie zu transportieren, um einem Streit mit seiner Frau Sida aus dem Weg zu gehen.",al={"wer schnürte das bündel","wer sammelte die häute","einar krokilisken"}},{q="Wer ist James Halloran?",a="James Halloran ist ein praktizierender Lederverarbeiter und Gerber in der Hafenstadt Der Hafen von Menethil. Er kauft rohe und gegerbte Häute von einheimischen Sumpfjägern, um Stiefel, gegerbtes Leder und praktische Ausrüstung für Seeleute, Soldaten und Stadtbewohner herzustellen.",al={"james halloran rolle","wer ist halloran","gerber menethil"}}},fp="25,265,37.497.0,47.262.0,35.234.0,22.239.0"}
P.entries["item:bundle-of-wood"] = {n="Kleinholzbündel",s="Kleinholzbündel sind zusammengebundene Holzstapel, die von Arbeitern nahe dem Holzfällerlager des Osttals im östlichen Wald von Elwynn geschlagen wurden. Kürzlich aufgrund von herumstreifenden Wildtieren zurückgelassen, stellen sie wichtige Lieferungen dar, die zur Erfüllung lokaler Holzverträge benötigt werden.",h="Kleinholzbündel sind zusammengebundene Holzstapel, die von Arbeitern nahe dem Holzfällerlager des Osttals im...",kw={"kleinholzbündel","osttal","elwynn","holzfällerlager","bauholz","raelen","nutzholz"},ang={["faction:Alliance"]="Jedes geborgene Bündel unterstützt direkt die Wiederaufbaubemühungen von Stormwind und stellt sicher, dass lebenswichtige Holzlieferungen Siedlungen in ganz Elwynn und Westfall rechtzeitig erreichen."},sec={{t="Zurückgelassenes Holz",b="Das Holzfällerlager des Osttals dient als primäre Holzquelle für das Königreich Stormwind und transportiert frisch geschlagenes Holz gen Westen, um die städtische Infrastruktur und Bauprojekte aufrechtzuerhalten. Kürzlich drangen aggressive Wildtiere – namentlich Waldbären und herumstreifende Wölfe – in die Haine nordwestlich des Lagers vor. Verängstigte Holzfäller flohen um ihr Leben und ließen frisch gesammelte Kleinholzbündel dort zurück, wo sie zwischen den Bäumen lagen. Angesichts knapper Lieferfristen sind die Aufseher des Lagers auf mutige Reisende angewiesen, die sich an den Raubtieren vorbeischleichen und das geschlagene Holz bergen, bevor Verträge gebrochen werden."}},faq={{q="Warum wurden diese Holzbündel im Wald zurückgelassen?",a="Die Arbeiter, die nordwestlich des Holzfällerlagers des Osttals Holz schlugen, wurden von aggressiven Wölfen und Bären überrumpelt und vertrieben, sodass ihre geschlagenen Bündel verstreut auf dem Waldboden zurückblieben.",al={"warum holz am boden","warum holz zurückgelassen","verlassenes holz elwynn"}},{q="Wer benötigt dieses gesammelte Holz?",a="Raelen, ein Aufseher im Holzfällerlager des Osttals, benötigt das gesammelte Holz dringend, um eine bevorstehende Holzlieferfrist einzuhalten.",al={"wer will das holz","raelen bauholz","holz abgeben"}},{q="Wo sind diese Bündel zu finden?",a="Sie liegen direkt nordwestlich des Holzfällerlagers des Osttals verstreut auf dem Boden, innerhalb der dichten Baumgrenze, die von Elwynns Bären und Wölfen bewohnt wird.",al={"kleinholzbündel fundort","wo ist das holz","osttal holzorte"}},{q="Warum haben die Stadtwachen die Bestien nicht beseitigt?",a="Raelen wandte sich bezüglich der Bestienplage an Deputy Rainer, doch die örtlichen Marschälle und Wachen sind überall in Elwynn überlastet, was die Holzarbeiter dazu zwingt, Hilfe von außerhalb zu suchen, um ihr Holz schnell wiederzubeschaffen.",al={"warum keine wachen","deputy rainer holz","wachen beim osttal"}}},fp="14,238,16.594.0,54.205.0,30.132.0,30.148.0,48.207.0"}
P.entries["item:burning-blade-medallion"] = {n="Medaillon der Burning Blade",s="Das Medaillon der Burning Blade ist ein dunkler Talisman, der von Kultisten getragen wird, die im Tal der Prüfungen lauern. Bewacht von dunkler Magie in den Tiefen vom Koven der Burning Blade dient es als direkter Beweis für eine dämonische Verderbnis, die versucht, die jungen Krieger von Durotar zu unterwandern.",h="Das Medaillon der Burning Blade ist ein dunkler Talisman, der von Kultisten getragen wird, die im Tal der...",kw={"koven der burning blade","medaillon der burning blade","durotar","teufelspirscher","talisman","das tal der prüfungen","yarrog baneshadow","zureetha fargaze"},ang={["class:Warlock"]="Während dunkle Magie von den Hexenmeistern der Horde unter strenger Disziplin ausgeübt wird, repräsentiert das Medaillon das abtrünnige, ungebundene Teufelswirken der Burning Blade, das die Stabilität von Durotar bedroht.",["race:Orc"]="Das Medaillon verkörpert den fortwährenden Schatten der dämonischen Verderbnis, die einst das Volk der Orcs versklavte und nun junge Initianden bedroht, noch bevor sie überhaupt das Tal der Prüfungen verlassen."},sec={{t="Ein Zeichen der Verderbnis",b="Tief in den verwinkelten Höhlen vom Koven der Burning Blade entdeckt, wird das Medaillon von Yarrog Baneshadow getragen, einem Agenten des finsteren Kults der Burning Blade. Durch die Weissagungen von Zureetha Fargaze identifiziert, bündelt das Schmuckstück finstere Macht inmitten der Wichtel-Vertrauten und Teufelspirscher des Kults. Das Niederstrecken seines Trägers und das Erbeuten des Medaillons vereitelt einen heimtückischen Versuch, die Übungsplätze der Horde von Durotar selbst aus zu untergraben."}},faq={{q="Was ist das Medaillon der Burning Blade?",a="Es ist ein magischer Talisman, der von Yarrog Baneshadow getragen wird, einem Agenten des Kults der Burning Blade, der sich in Durotar verbirgt. Das Medaillon dient als Fokus dunkler Magie und als Abzeichen der Loyalität unter den Kultisten.",al={"burning blade talisman","koven medaillon","yarrogs medaillon"}},{q="Wer möchte, dass das Medaillon geborgen wird?",a="Zureetha Fargaze, eine Orcseherin, die vor dem Höhlenbau im Tal der Prüfungen stationiert ist, verlangt nach dem Medaillon, um den dämonischen Einfluss auszumerzen und die örtlichen Machenschaften des Kults zu untersuchen.",al={"wer nimmt das medaillon","wo gibt man das medaillon ab","zureetha fargaze quest"}},{q="Wo ist das Medaillon zu finden?",a="Es befindet sich tief im Koven der Burning Blade, einer versteckten Höhle nordwestlich des Höhlenbaus im Tal der Prüfungen. Es wird von Yarrog Baneshadow bewacht, der auf den oberen Felsvorsprüngen der Höhle lauert.",al={"wo ist yarrog baneshadow","fundort medaillon der burning blade","wie man das medaillon findet"}},{q="Was bedeutet die Anwesenheit des Medaillons für Durotar?",a="Seine Entdeckung bestätigt, dass der Kult der Burning Blade Agenten direkt auf die Übungsplätze der Horde geschleust hat, was darauf hindeutet, dass die Kultisten weit größere und gefährlichere Ambitionen im gesamten Heimatland der Orcs hegen.",al={"warum sind kultisten im tal der prüfungen","ist die burning blade in durotar"}}},fp="23,268,20.452.0,36.208.0,34.171.0,29.192.0,52.215.0"}
P.entries["item:burning-blood-quest-item"] = {n="Burning Blood (quest item)",s="Brennendes Blut ist eine unnatürliche Flüssigkeit, die von den wilden Nightbane-Worgen erbeutet wird, die im Dämmerwald umherstreifen. Der Rüstungsschmied Grimand Elmore aus Stormwind benötigt zwanzig Phiolen dieser feurigen Essenz, um mit fortgeschrittenen Schmiedetechniken zu experimentieren.",h="Brennendes Blut ist eine unnatürliche Flüssigkeit, die von den wilden Nightbane-Worgen erbeutet wird, die im...",kw={"brennendes blut","dämmerwald","furen longbeard","grimand elmore","gutspill","nightbane","rolands verdammnis","worgen"},ang={["class:Warrior"]="Grimand Elmore verwendet dieses flüchtige Reagenz, um modernste Schmiedemethoden zu testen, und belohnt angehende Krieger, die es erbeuten, mit langlebiger, maßgefertigter Plattenrüstung.",["profession:Blacksmithing"]="Meisterschmiede blicken gelegentlich über herkömmliche Kohle und Wasser hinaus und nutzen exotische Reagenzien wie brennendes Worgenblut, um schwere Metalle unter extremen Temperaturen abzuschrecken und zu härten."},sec={{t="Ein flüchtiges Reagenz",b="Die verfluchten Nightbane-Worgen, die den Dämmerwald heimsuchen, glühen vor einem seltsamen, unnatürlichen Zorn, und ihr Blut brennt mit wahrhafter Hitze. Diese sengende Flüssigkeit kann von den Bestien gewonnen werden, die die heimgesuchten Wälder und die verlassene Ausgrabungsstätte von Rolands Verdammnis durchstreifen. Obwohl ihre Gewinnung grotesk ist, besitzt die feurige Substanz seltene metallurgische Eigenschaften, die von Meisterschmieden begehrt werden, um widerstandsfähige Platten abzuschrecken und zu härten."},{t="Elmores Experiment",b="Grimand Elmore, ein erfahrener Handwerker, der im Dwarven District von Stormwind arbeitet, möchte neuartige Schmiedemethoden testen, die von seinem Rivalen Furen Longbeard entwickelt wurden. Um festzustellen, ob diese radikalen Schmiedetechniken etwas taugen, benötigt Elmore brennendes Blut zusammen mit einem dichten brennenden Stein, der sich im Besitz des Worgenhäuptlings Gutspill befindet. Denjenigen, die bereit sind, sich dem räuberischen Rudel zu stellen und mit der brodelnden Flüssigkeit zurückzukehren, wird eine robuste Kriegerrüstung versprochen, geschmiedet in der Hitze seiner Esse."}},faq={{q="Was ist Brennendes Blut?",a="Brennendes Blut ist eine sengende, flüchtige Körperflüssigkeit, die von den Nightbane-Worgen im Dämmerwald stammt. Seine unnatürliche Hitze macht es zu einem wertvollen Reagenz für spezialisierte Experimente in der Rüstungsschmiedekunst.",al={"brennendes blut lore","was ist brennendes blut","worgenblut"}},{q="Woher stammt Brennendes Blut?",a="Es wird von den verschiedenen Nightbane-Worgen gesammelt, die die Wälder des Dämmerwalds durchstreifen, insbesondere von jenen, die sich um die verlassene Mine von Rolands Verdammnis scharen.",al={"woher brennendes blut","wer droppt brennendes blut","fundort brennendes blut"}},{q="Warum benötigt Grimand Elmore es?",a="Grimand Elmore möchte die innovativen Rüstungsschmiedetechniken testen, die von Furen Longbeard entwickelt wurden. Durch die Kombination des kochenden Blutes mit einem brennenden Stein beabsichtigt er, ein außergewöhnliches Stück Kettenrüstung für einen abenteuerlustigen Krieger zu schmieden.",al={"warum grimand brennendes blut braucht","grimand elmore blut quest"}},{q="Warum brennt das Blut der Nightbane?",a="Die Worgen des Dämmerwalds sind unnatürliche Unholde, die durch dunkle und chaotische Magie herbeigerufen wurden. Der Fluch, der durch das Nightbane-Rudel fließt, verzerrt ihre Physiologie und erfüllt ihre Adern mit einer feurigen, unnatürlichen Virulenz.",al={"warum haben worgen brennendes blut","ist worgenblut feuer"}}},fp="26,230,18.410.0,19.456.0,22.184.0,35.156.0,32.239.0,42.210.0"}
P.entries["item:burning-rock"] = {n="Brennender Fels",s="Der Brennende Fels ist ein ungewöhnliches, schwelendes Mineral, das dem Anführer der Nightbane-Worgen, Gutspill, tief in Rolands Verdammnis im Dämmerwald abgenommen wurde. Schmiedemeister Grimand Elmore in Stormwind benötigt dieses seltene Kuriosum zusammen mit feurigem Worgenblut, um spezialisierte, verzauberte Rüstungen für vielversprechende Krieger zu schmieden.",h="Der Brennende Fels ist ein ungewöhnliches, schwelendes Mineral, das dem Anführer der Nightbane-Worgen...",kw={"brennender fels","dämmerwald","furen longbeard","grimand elmore","gutspill","nightbane-worgen","rolands verdammnis"},ang={["class:Warrior"]="Grimand Elmore wirbt erfahrene Krieger an, um Rolands Verdammnis für diesen Stein zu trotzen, und belohnt ihre Tapferkeit mit einer maßgeschmiedeten Rüstung, die aus seiner Hitze gefertigt wurde.",["profession:Blacksmithing"]="Der Brennende Fels dient als exotische Hitzequelle und demonstriert die unorthodoxen Schmelz- und Härtemethoden, die von den Rüstungsschmieden aus Stormwind und Ironforge erforscht wurden."},sec={{t="Eine schwelende Beute",b="Der Brennende Fels, getragen von Gutspill, einem wilden Nightbane-Worgen, der in den baufälligen Schächten von Rolands Verdammnis lauert, ist eine Anomalie unter den unterirdischen Schrecken des Dämmerwalds. Da er eine unnachgiebige, übernatürliche Hitze ausstrahlt, erregte er die Aufmerksamkeit von Grimand Elmore in Stormwind. Um experimentelle Schmiedetechniken seines Kollegen Furen Longbeard zu erproben, nutzt Grimand die Eigenwärme des Felsens und das kochende Blut der einheimischen Worgen, um widerstandsfähige Rüstungsplatten für erfahrene Kämpfer zu härten."}},faq={{q="Wo ist der Brennende Fels zu finden?",a="Er befindet sich im Besitz von Gutspill, einem bösartigen Worgen-Alpha, der in der Mine von Rolands Verdammnis im östlichen Dämmerwald haust.",al={"brennender fels fundort","wer droppt brennenden fels","woher bekommt man brennenden fels"}},{q="Wer benötigt den Brennenden Fels?",a="Grimand Elmore, ein fähiger Zwergenschmied im Dwarven District von Stormwind, benötigt den Felsen, um experimentelle metallurgische Techniken zu erproben.",al={"wer braucht brennenden fels","bei wem brennenden fels abgeben","grimand elmore brennender fels"}},{q="Warum benötigt Grimand Elmore ihn?",a="Grimand beabsichtigt, von Furen Longbeard entwickelte Handwerkstechniken zu testen. In Kombination mit dem kochenden Blut der Nightbane-Worgen liefert der schwelende Stein die intensive Hitze, die zum Schmieden einer einzigartigen Rüstung erforderlich ist.",al={"brennender fels verwendung","wozu brennender fels","was bewirkt brennender fels"}},{q="Welche Verbindung hat dieser Fels zu den Worgen?",a="Die Nightbane-Worgen von Rolands Verdammnis besitzen seltsame, feurige physiologische Eigenschaften, wie etwa Brennendes Blut. Gutspill, ihr Rudelführer, verwahrt den Brennenden Fels tief in der Mine, doch ob sie ihn ausgegraben oder mitgebracht haben, bleibt ein Rätsel.",al={"warum haben worgen den brennenden fels","gutspill brennender fels lore"}}},fp="12,308,18.488.0,32.114.0,27.157.0,32.216.0,50.255.0"}
P.entries["item:cache-of-zanzil-s-altered-mixture"] = {n="Behälter mit Zanzils veränderter Mixtur",s="Der Behälter mit Zanzils veränderter Mixtur ist ein Vorrat an wirksamem Gift, der in einer verschlossenen Kiste im Turm der Venture Company nahe dem Schlickermoor aufbewahrt wird. Benannt nach dem Dschungeltroll-Hexendoktor Zanzil, dient er als entscheidendes Ziel für die Shattered-Hand in Orgrimmar.",h="Der Behälter mit Zanzils veränderter Mixtur ist ein Vorrat an wirksamem Gift, der in einer verschlossenen...",kw={"veränderte mixtur","gallywix","geldkassette","gift","die shattered-hand","shenthul","das schlickermoor","venture company","zanzil"},ang={["class:Rogue"]="Die Beschaffung der Mixtur dient als unverzichtbarer Übergangsritus für Hordeschurken, um ihre Beherrschung von Schlossknacken, Taschendiebstahl und Giftmischerei im Dienste der Shattered-Hand zu beweisen.",["faction:Horde"]="Der giftbeladene Turm der Venture Company nördlich des Schlickermoors stellt eine unmittelbare Umwelt- und Sicherheitsbedrohung für Durotar und das Brachland dar."},sec={{t="Ein giftiges Unternehmen",b="Nördlich des Schlickermoors im Brachland unterhält die Venture Company einen Turm-Außenposten. Ein Behälter mit einer veränderten Mixtur, die den Namen des berüchtigten Troll-Hexendoktors Zanzil trägt, liegt verschlossen in der privaten Geldkassette von Obervorarbeiter Puzik Gallywix auf der Spitze des Turms. Ein Gift hat alles im Turm geschwächt, sodass die dortigen Goblin-Bewohner jedem Eindringling hilflos ausgeliefert sind, der kühn genug für einen Angriff ist."},{t="Beschaffung für die Shattered-Hand",b="Die Anwesenheit derart gefährlicher alchemistischer Substanzen so nah an Durotar erregte sofort die Aufmerksamkeit der Shattered-Hand, der geheimen Schurkengilde, die unter Orgrimmar agiert. Mit dem Ziel, die Bedrohung zu neutralisieren und die Mixtur für eigene nachrichtendienstliche Studien zu sichern, entsandte Meisterausbilder Shenthul Agenten, um den Turm zu stürmen, Gallywix hinzurichten und die Schatulle des Vorarbeiters zu knacken. Die Bergung des flüchtigen Behälters erfordert beträchtliches Geschick beim Infiltrieren, da die Handhabung des kontaminierten Behälters die Gefahr birgt, den Dieb seinen tödlichen, schwächenden Toxinen auszusetzen."}},faq={{q="Was ist Zanzils veränderte Mixtur?",a="Es ist ein wirksames Gift, das den Namen des Troll-Hexendoktors Zanzil trägt. Ein Vorrat davon ist im Turm der Venture Company nahe dem Schlickermoor eingeschlossen, wo ein Gift alles im Inneren geschwächt hat.",al={"was ist zanzils mixtur","was ist der behälter","zanzils trank"}},{q="Wo befindet sich der Behälter?",a="Die Mixtur lagert in Gallywix' Schatulle ganz oben auf dem Turm der Venture Company, der sich direkt nördlich des Schlickermoors im nordöstlichen Brachland befindet.",al={"wo ist die mixtur","wo ist zanzils behälter","fundort der mixtur"}},{q="Warum will die Shattered-Hand die Mixtur haben?",a="Shenthul und die Shattered-Hand wollen eine gefährliche Operation der Venture Company direkt vor der Haustür der Horde unterbinden und gleichzeitig die seltene Substanz erbeuten, um ihr eigenes Wissen über Gifte und taktische Toxine zu vertiefen.",al={"wer will die mixtur","warum will shenthul sie","mission der shattered-hand"}},{q="Wie öffnet man die Kiste mit dem Behälter?",a="Die Kiste erfordert fortgeschrittenes Geschick im Schlossknacken, um ihre physischen Mechanismen zu überwinden, wodurch sie nur für ausgebildete Agenten zugänglich ist, die wissen, wie man unter gefährlichen Bedingungen mit feinen Zuhaltungen umgeht.",al={"wie öffnet man gallywix' schatulle","zanzils kiste öffnen","schlossknacken zanzils behälter"}}},fp="33,265,18.395.0,31.565.1,33.198.0,25.155.0,45.218.0,47.204.0"}
P.entries["item:cactus-apple"] = {n="Kaktusapfel",s="Kaktusäpfel sind zähe, feuchtigkeitsreiche Früchte, die von der rauen Flora im Tal der Prüfungen in Durotar geerntet werden. Da sie in der trockenen Wüstenhitze gedeihen, werden sie von den einheimischen Orcs als seltene, erfrischende Nahrungsquelle geschätzt.",h="Kaktusäpfel sind zähe, feuchtigkeitsreiche Früchte, die von der rauen Flora im Tal der Prüfungen in Durotar...",kw={"kaktusapfel","kaktusapfel surprise","wüstenfrucht","durotar","galgar","das tal der prüfungen"},ang={["profession:Cooking"]="Für Köche, die in der Wildnis von Durotar überleben wollen, ist die Ernte von Wüstenkakteen eine grundlegende Lektion darin, stachelige, unwirtliche Wüstenvegetation in eine feuchtigkeitsspendende Mahlzeit zu verwandeln.",["race:Orc"]="Junge Orcs, die sich den Prüfungen in Durotar unterziehen, lernen schnell, dass das Bestehen im roten Canyon bedeutet, jeden noch so knappen Tropfen Feuchtigkeit zu nutzen, den die Natur zu bieten hat."},sec={{t="Wüstenernte",b="Die sonnenverbrannte Erde von Durotar bietet wenig Luxus und zwingt ihre Bewohner dazu, jede widerstandsfähige Pflanze zu nutzen, die den Elementen trotzt. Kaktusäpfel wachsen in Büscheln um die dicken Kakteen herum, die das Tal der Prüfungen säumen. Obwohl sie schwer zu ernten sind, ohne sich ein paar Dornen einzufangen, spendet die Frucht in der drückenden Hitze des Canyons lebenswichtige Feuchtigkeit. Ein einheimischer Orc namens Galgar sammelt diese Früchte, um seine berühmte Kaktusapfel Surprise zuzubereiten – eine kühlende Süßspeise, die Rekruten während ihrer harten Grundausbildung eine willkommene Erleichterung verschafft."}},faq={{q="Wo wachsen Kaktusäpfel?",a="Sie wachsen wild im roten Staub des Tals der Prüfungen im südlichen Durotar und liegen für gewöhnlich am Fuße der stämmigen Kaktuspflanzen, die im gesamten Becken verteilt sind.",al={"fundorte von kaktusäpfeln","wo man kaktusäpfel findet","kaktusapfel-stelle"}},{q="Was ist Kaktusapfel Surprise?",a="Es ist ein gekühltes, erfrischendes Gericht, das von Galgar, einem Einheimischen aus dem Tal der Prüfungen, zubereitet wird. Aus frisch gesammelten Kaktusäpfeln zaubert er einen süßen Imbiss, der sofortige Erleichterung von Durotars unbarmherziger Wüstenhitze verschafft.",al={"was ist galgars surprise","rezept für kaktusapfel","galgars leckerei"}},{q="Wer verlangt nach diesen Äpfeln?",a="Galgar, ein im Tal der Prüfungen stationierter Orc, tauscht Portionen seines kühlenden Desserts mit jedem jungen Rekruten, der bereit ist, loszuziehen und sechs frische Äpfel mitzubringen.",al={"questgeber für kaktusäpfel","wer kaktusäpfel will","galgars äpfel"}}},fp="12,219,14.536.0,28.166.0,30.207.0,26.165.0"}
P.entries["item:calor-s-note"] = {n="Calors Notiz",s="Calors Notiz ist ein Fetzen verblassten Pergaments, den der Waldläufer Calor verfasst hat, um Meister Jonathan Carevin einen bewährten Abenteurer zu empfehlen. Sie dient als Einführung in einen schattenhaften Kader, der neben der offiziellen Stadtwache von Dunkelhain, jedoch unabhängig von ihr, operiert.",h="Calors Notiz ist ein Fetzen verblassten Pergaments, den der Waldläufer Calor verfasst hat, um Meister...",kw={"calor","calors notiz","dunkelhain","dämmerwald","jonathan carevin","die nachtwache","empfehlung","worgen"},ang={["class:Paladin"]="Jonathan Carevin begrüßt den Überbringer mit 'Ruhm unter dem Licht', was eine ideologische Verbundenheit mit heiligen Kriegern signalisiert, die sich der Säuberung von Dämmerwald von Dämonen und Untoten verschrieben haben.",["faction:Alliance"]="Da die Armee von Stormwind im Dämmerwald vollkommen fehlt, bilden inoffizielle Gruppierungen wie Carevins Zirkel und die Nachtwache das einzige Bollwerk der südlichen Grenze gegen die Finsternis."},sec={{t="Eine seltene Empfehlung",b="Dämmerwald bietet Fremden nur sehr wenig Herzlichkeit, und Calor ist bekanntermaßen schwer zu beeindrucken. Wer Begegnungen mit den blutrünstigen Worgen überlebt, die durch die Wälder streifen, verdient sich seinen Respekt, was ihn dazu veranlasst, diese kurze Botschaft zu verfassen. Nach Dunkelhain gebracht, dient die verblasste Notiz als Beweis der Glaubwürdigkeit und stellt einen Außenstehenden direkt bei Jonathan Carevin vor."},{t="Ein privater Kreuzzug",b="Während Dunkelhain für die öffentliche Verteidigung auf die Nachtwache vertraut, führen Calor und Carevin einen finstereren, heimlicheren Kampf. Calor beklagt offen, dass sie der Stadtwache zahlenmäßig unterlegen sind, und hofft auf genügend fähige Kämpfer, um ihren privaten Krieg voranzutreiben. Das Überbringen der Notiz gewährt Zutritt zu Carevins Kampagne gegen Dämonen, Untote und die heimlichen Sympathisanten, die den Verfall von Dämmerwald begünstigen."}},faq={{q="Was ist Calors Notiz?",a="Es ist eine handgeschriebene Nachricht, die von Calor auf einem Fetzen verblassten Pergaments verfasst wurde. Sie dient als persönliches Empfehlungsschreiben, das die Kampfkraft und Zuverlässigkeit eines Abenteurers gegen die Schrecken von Dämmerwald bezeugt.",al={"calors notiz","was ist diese notiz","was steht auf der notiz"}},{q="Wer erhält die Notiz?",a="Die Notiz ist an Jonathan Carevin gerichtet, eine strenge Gestalt in Dunkelhain, die den entschlossenen Kampf gegen die dunklen Mächte koordiniert, welche die Region bedrohen.",al={"wem gebe ich die notiz","wer bekommt calors notiz","jonathan carevin notiz"}},{q="Wie steht Calor zur Nachtwache?",a="Calor hält die Nachtwache für unzureichend angesichts der wahren Bedrohungen, die im Dämmerwald lauern. Bei der Übergabe der Notiz äußert er den Wunsch, genügend fähige Verbündete anzuwerben, um der Miliz zahlenmäßig überlegen zu sein, in der Hoffnung, das dringliche Werk, das seine kleine Gruppierung allein vorantreibt, endlich vollenden zu können.",al={"calor und die nachtwache","warum will calor die nachtwache zahlenmäßig übertreffen"}},{q="Welche Art von Kampf ficht Jonathan Carevin?",a="Meister Carevin führt einen unerbittlichen Kampf gegen Dämonen, Untote und sterbliche Kollaborateure, die ihnen im Dämmerwald zur Hand gehen. Er schätzt Wachsamkeit und Hingabe an das Heilige Licht und schenkt nur erprobten Personen sein Vertrauen.",al={"carevins anliegen","was macht carevin","gegen wen kämpft carevin"}}},fp="12,256,21.344.0,17.383.0,21.218.0,22.163.0,38.272.0,48.227.0"}
P.entries["item:candle-of-beckoning"] = {n="Kerze des Heranlockens",s="Die Kerze des Heranlockens ist eine verzauberte Ritualkerze, die von dem zurückgezogen lebenden Nekromanten Gunther Arcanus am Blendwassersee aufbewahrt wird. Das Platzieren und Entzünden der Kerze auf einem Altar auf einer nahegelegenen kleinen Insel beschwört einen rastlosen Geist namens Lillith Nefara herbei.",h="Die Kerze des Heranlockens ist eine verzauberte Ritualkerze, die von dem zurückgezogen lebenden Nekromanten...",kw={"blendwassersee","kerze des heranlockens","gunther arcanus","lillith nefara","treuebeweis","der schlummernde schatten","tirisfal"},ang={["class:Mage"]="Gunthers Fähigkeit, Geister an rituelle Gegenstände wie diese Kerze zu binden, demonstriert seine Meisterschaft über die Künste der Nekromantie und Beschwörung abseits der sanktionierten Lehren der Kirin Tor.",["race:Undead"]="Für Abgesandte der Verlassenen, die von Unterstadt entsandt wurden, ist die Verwendung von Gunthers Ritualkerze ein notwendiger Schritt, um den äußerst unabhängigen Nekromanten davon zu überzeugen, dass Ihr keine Knechte des Lichkönigs seid."},sec={{t="Eine Loyalitätsprüfung",b="In einer Kiste neben dem einsamen Magier Gunther Arcanus auf seiner Insel im Blendwassersee aufbewahrt, dient die Kerze des Heranlockens als Werkzeug in einem dunklen Beschwörungsritual. Gunther ist ein äußerst unabhängiger untoter Zauberer, der sich aus eigener Kraft dem Befehl des Lichkönigs widersetzte und sowohl der Geißel als auch den Verlassenen gegenüber misstrauisch bleibt. Um zu beweisen, dass Eure Loyalität nicht dem Lichkönig gilt, weist Gunther Euch an, eine dieser Kerzen nach Südwesten zu einer kleineren Insel zu bringen. Dort, auf einen alten, blutbefleckten Tisch gestellt, durchdringt die Flamme der Kerze den Schleier zwischen den Welten, um Lillith Nefara, Der Schlummernde Schatten, zu erwecken und heranzulocken, damit sie zur Ruhe gebettet werden kann."}},faq={{q="Wofür wird die Kerze des Heranlockens verwendet?",a="Die Kerze wird verwendet, um den Schatten Lillith Nefara zu beschwören. Indem Ihr sie auf dem alten, blutbefleckten Ritualtisch auf der kleineren Insel südwestlich von Gunther Arcanus' Lager platziert und anzündet, wird der schlummernde Geist in das physische Reich gezogen.",al={"was bewirkt kerze des heranlockens","verwendung von kerze des heranlockens","wie man kerze des heranlockens benutzt"}},{q="Woher bekommt man die Kerze des Heranlockens?",a="Ihr erhaltet die Kerze aus einer Kiste neben Gunther Arcanus auf seiner Insel im Blendwassersee im östlichen Tirisfal, während Ihr seine Loyalitätsprüfung ablegt.",al={"wo man kerze des heranlockens findet","wie man kerze des heranlockens bekommt","fundort der kerzenkiste"}},{q="Wer wird durch die Kerze beschworen?",a="Das Entzünden der Kerze beschwört Lillith Nefara herbei, einen rachsüchtigen geisterhaften Schatten, der an die Inseln des Sees gebunden ist. Sie zu besiegen, ist erforderlich, um zu beweisen, dass Ihr nicht der Geißel dient.",al={"wen sie beschwoert","beschwoerungsziel der kerze","wer ist lillith nefara"}},{q="Warum besitzt Gunther Arcanus diese Kerzen?",a="Gunther nutzt die Kerzen und das damit verbundene Ritual als Prüfung. Er begegnet Außenstehenden mit Misstrauen, hütet seine Autonomie gegenüber der Geißel eifersüchtig und verlangt von jedem, der sein Bündnis sucht, die von ihm herbeigerufenen rastlosen Toten zu stellen und zu vernichten.",al={"warum gunther kerzen hat","gunther ritualkerzen"}}},fp="19,244,20.642.0,41.240.0,41.179.0,30.169.0,44.236.0"}
P.entries["item:cantation-of-manifestation"] = {n="Inkantation der Manifestation",s="Die Inkantation der Manifestation ist eine spezialisierte arkane Beschwörungsformel auf einer Pergamentrolle, die von Magiern verwendet wird, um ungesehene magische Anomalien zu enthüllen. In Undercity stellt Anastasia Hartwell sie Lehrlingen zur Verfügung, die unsichtbare magische Wesen untersuchen, welche Algernons Laden im Apothecarium heimsuchen.",h="Die Inkantation der Manifestation ist eine spezialisierte arkane Beschwörungsformel auf einer Pergamentrolle...",kw={"algernon","anastasia hartwell","apothecarium","inkantation der manifestation","eindaemmungskassette","magic quarter","rissbrut","undercity"},ang={["class:Mage"]="Die Inkantation der Manifestation ist ein wesentliches Werkzeug in Eurer frühen Ausbildung, das Euch lehrt, verborgene arkane Strömungen aufzuspüren und unbeständige Risswesen einzudämmen.",["race:Undead"]="Verlassene Zauberwirker im Magic Quarter halten arkane Schwankungen unter strenger Kontrolle, um sicherzustellen, dass magische Risse die Stabilität von Undercity nicht gefährden."},sec={{t="Enthüllung des Unsichtbaren",b="Die Inkantation der Manifestation enthält einen gezielten Zauber, der darauf ausgelegt ist, magische Schleier zu durchdringen und unkörperliche, unsichtbare Wesen in das sichtbare Spektrum zu zwingen. Sie wird im Magic Quarter von Undercity in der Nähe von Anastasia Hartwell aufbewahrt und fähigen Magiern anvertraut, die den Auftrag haben, abtrünnige magische Anomalien einzudämmen. Wird sie in einem Gebiet laut vorgelesen, das unter arkaner Instabilität leidet – wie etwa Algernons alchemistischer Werkstatt im Apothecarium –, zwingen die Worte verirrte Rissbruten dazu, sich zu materialisieren, sodass der Zaubernde sie bezwingen und für weitere Studien in Eindämmungskassetten sperren kann."}},faq={{q="Was bewirkt die Inkantation der Manifestation?",a="Sie ist eine magische Schriftrolle, die einen Zauber wirkt, der unsichtbare arkane Anomalien aufdeckt. Wird sie in Bereichen aufgesagt, in denen magische Risse oder Störungen auftreten, zwingt sie ungesehene Kreaturen – wie etwa Rissbruten – ins Sichtfeld, damit sie bekämpft und gefangen genommen werden können.",al={"was ist die inkantation der manifestation","zweck der inkantation","wie funktioniert die inkantation"}},{q="Wo finde ich die Inkantation in Undercity?",a="Sie liegt direkt hinter der Magierlehrerin Anastasia Hartwell auf dem Boden, welche sich im Magic Quarter von Undercity befindet.",al={"fundort inkantation undercity","wo ist die inkantation der manifestation","inkantation in undercity finden"}},{q="Warum muss diese Schriftrolle laut Anastasia Hartwell verwendet werden?",a="In Algernons alchemistischem Laden unten im Apothecarium ist eine seltsame magische Störung ausgebrochen. Ungesehene, vollständig aus Magie bestehende Wesen begannen, die Räumlichkeiten zu durchstreifen, und Hartwell benötigt jemanden, der die Schriftrolle vor Ort verliest, um die Kreaturen zu enthüllen und einzufangen, bevor sich der Riss verschlimmert.",al={"warum inkantation nutzen","hartwell quest motiv","anastasia stoerung"}},{q="Darf ich die Schriftrolle nach der Verwendung behalten?",a="Nein. Sobald Ihr die Rissbruten manifestiert und in Eindämmungskassetten eingefangen habt, müsst Ihr die Inkantation der Manifestation zusammen mit den Kassetten zu Anastasia Hartwell zurückbringen.",al={"inkantation behalten","verliert man die inkantation","inkantation zurueckbringen"}}},fp="26,298,23.573.0,44.249.0,44.121.0,50.268.0,43.184.0"}
P.entries["item:canvas-scraps"] = {n="Segeltuchreste",s="Segeltuchreste sind Überreste von robustem Gewebe, das von menschlichen Invasoren und Zentaurenstämmen mitgeführt wird, die nach Durotar vordringen. In Klingenhügel sammelt der alternde Veteran Furl Scornbrow diese geborgenen Stofffetzen, um daraus nützliche Reisesäcke für frische Rekruten der Horde zu nähen.",h="Segeltuchreste sind Überreste von robustem Gewebe, das von menschlichen Invasoren und Zentaurenstämmen...",kw={"segeltuchreste","akzeptiert euer schicksal","durotar","furl scornbrow","kolkar","kul tiras","klingenhügel"},ang={["faction:Horde"]="Jeder geborgene Rest, der Invasoren aus Kul Tiras oder Kolkar-Plünderern abgenommen wird, hilft dabei, neue Verteidiger auszurüsten, die Thralls Ruf in ganz Durotar folgen.",["profession:Tailoring"]="Während einfaches gewebtes Segeltuch von Kriegern vor allem als Rohmaterial geborgen wird, dient es als robuste Grundlage für die Herstellung praktischer Taschen in der rauen Wüste."},sec={{t="Trophäen von Durotars Feinden",b="Segeltuch ist kein Stoff, der in den rauen Lederverarbeitungstraditionen der Orcs heimisch ist, doch unter den Feinden von Durotar ist es reichlich vorhanden. Die Marinesoldaten und Matrosen von Kul Tiras, die sich entlang der östlichen Küste verschanzt haben, tragen schwere Segeltuchausrüstung und Segeltuchreste von ihren Marineausflügen bei sich. Weiter im Landesinneren verwenden die umherstreifenden Kolkar-Zentauren grobe Stoffreste wieder, die sie aus Nachschubkarawanen und vergangenen Konflikten erbeutet haben. Das Besiegen dieser Feinde bringt strapazierfähige Überreste ein, die aus ihren Lagern und ihrer Ausrüstung geborgen werden können."},{t="Das Handwerk eines Veteranen",b="Oben auf dem Razor Hill Watchtower hält der Veteran Furl Scornbrow Ausschau nach Invasoren, während er seine Hände nützlicher Arbeit widmet. Obwohl seine besten Kampftage hinter ihm liegen, verwendet der Krieger, der einst an der Seite von Thrall stand, geborgene feindliche Stoffe wieder, um robuste Tragebeutel für jüngere Soldaten herzustellen. Indem er die Materialien von Kul Tiras und den Kolkar gegen sie selbst verwendet, rüstet Furl die neue Generation von Verteidigern aus, die für die Sicherung der Grenzen der Horde kämpfen."}},faq={{q="Woher stammen Segeltuchreste?",a="Sie werden von menschlichen und zentaurischen Feinden in ganz Durotar erbeutet. Ihr könnt sie von den Streitkräften von Kul Tiras erbeuten, die Burg Tiragarde und das östliche Ufer besetzen, oder von Kolkarschauflern und Kolkarausläufern, die in der Nähe ihrer Lager im Landesinneren lauern.",al={"wer lässt segeltuchreste fallen","wo man segeltuchreste bekommt","segeltuchreste farmen"}},{q="Warum will Furl Scornbrow diese Reste haben?",a="Furl Scornbrow ist ein alternder Orc-Veteran, der im Razor Hill Watchtower stationiert ist und nicht mehr an vorderster Front kämpfen kann. Um der Horde weiterhin nützlich zu sein, nutzt er den geborgenen Stoff, um praktische Reisesäcke für junge Abenteurer zu nähen.",al={"wer braucht segeltuchreste","wofür segeltuchreste verwendet werden","furl scornbrow segeltuch"}},{q="Warum tragen die Truppen von Kul Tiras und die Zentauren Segeltuch bei sich?",a="Die Expedition von Kul Tiras traf an Bord von Kriegsschiffen in Durotar ein und unterhält Lager an der Küste, weshalb Segeltuch und gewebte Stoffe alltägliche Bedarfsgegenstände sind. Die Kolkar-Zentauren gelangen an ähnliche grobe Stoffe, indem sie Karawanen überfallen, Küsten absuchen und Reisende ausplündern, die die trockenen Ebenen durchqueren.",al={"warum zentauren segeltuch haben","segeltuchreste menschen lore"}}},fp="13,252,29.493.0,17.441.0,33.234.0,42.235.0,53.294.0"}
P.entries["item:cask-of-merlot"] = {n="Fässlein mit Merlot",s="Ein Fässlein mit Merlot ist ein Fass feinen Rotweins, der in Stormwind hergestellt und verkauft wird. Es dient als eine von mehreren regionalen Spirituosenspezialitäten, die der Gastwirt von Seenhain während der durch die Invasion der Schwarzfelsorcs verursachten Versorgungsengpässe benötigt.",h="Ein Fässlein mit Merlot ist ein Fass feinen Rotweins, der in Stormwind hergestellt und verkauft wird.",kw={"barkeeper daniels","fässlein mit merlot","trockene zeiten","galina winery","seenhain","merlot","roberto pupellyverbos","stormwind"},ang={["faction:Alliance"]="Das Holen des Fasses unterstreicht den scharfen Kontrast zwischen dem sicheren Luxus des Kanalviertels von Stormwind und den umkämpften Grenzorten, die im Rotkammgebirge unter Belagerung stehen."},sec={{t="Ein Geschmack der Hauptstadt",b="Im Herzen des Königreichs geerntet und vergoren, stammt dieses Fässlein mit Merlot direkt aus den Kellern der Galina Winery, gelegen an den Kanälen am Rande des Trade District von Stormwind. Winzer Roberto Pupellyverbos verwaltet dort die Jahrgänge und bedient die feineren Gaumen der Hauptstadt. Anders als der herbe Fusel aus dem Dämmerwald oder die rustikalen Spirituosen aus Elwynn repräsentiert der Merlot das verfeinerte Handwerk menschlicher Winzer, die im relativen Schutz der Stadtmauern arbeiten."},{t="Nachschub für Seenhain",b="Als der Schwarzfelsclan in das Rotkammgebirge einfiel, brachen die Versorgungswege zusammen und schnitten Seenhain von seinen gewöhnlichen Händlerlieferungen ab. Angesichts durstiger und verängstigter Einheimischer beauftragt Barkeeper Daniels hilfsbereite Kuriere mit einer königreichweiten Reise, um die Keller seiner Taverne wieder aufzufüllen. Die Beschaffung dieses Fasses sorgt dafür, dass die Verteidiger und Flüchtlinge, die am Immerruhsee ausharren, etwas Mildes haben, um ihre Rationen hinunterzuspülen."}},faq={{q="Wo kann ich ein Fässlein mit Merlot finden?",a="Es wird von Roberto Pupellyverbos in der Galina Winery verkauft. Der Laden liegt an den Kanälen am Rande des Trade District in Stormwind.",al={"fässlein mit merlot fundort","wo merlot kaufen","wer verkauft fässlein mit merlot","stormwind weinhändler"}},{q="Warum benötigt Barkeeper Daniels diesen Wein?",a="Seenhains regelmäßige Handelslieferungen wurden durch die Invasion der Schwarzfelsorcs im Rotkammgebirge unterbrochen. Barkeeper Daniels hat fast keinen Alkohol mehr und schickt Abenteurer durch das südliche Azeroth, um regionale Spezialitäten zu beschaffen, damit seine Gäste zufrieden bleiben.",al={"trockene zeiten quest merlot","warum will daniels wein","seenhain merlot zweck"}},{q="Welche anderen Getränke werden neben dem Merlot gesammelt?",a="Daniels verlangt außerdem einen Schlauch mit süßem Rum aus Goldhain, eine Flasche mit Fusel aus Dunkelhain und ein Fässchen Donnerbräulagerbier von Grimbooze Donnerbräu aus den Hügeln von Westfall.",al={"trockene zeiten getränke","daniels alkohol liste","weitere alkohole trockene zeiten"}},{q="Ist die Galina Winery in Gefahr?",a="Das Weingut bleibt hinter den steinernen Schutzwällen von Stormwind sicher. Während abgelegenere Gebiete wie Westfall und das Rotkammgebirge unter Banditen und Orcüberfällen leiden, laufen Handel und Weinherstellung im Kanalviertel der Hauptstadt ungestört weiter.",al={"galina winery lore","weingut in stormwind"}}},fp="14,237,22.489.0,20.421.0,34.150.0,40.245.0,53.179.0,31.241.0"}
P.entries["item:cask-of-scalder"] = {n="Fässlein mit Gerstenbräu",s="Ein schweres Fässlein mit feurigem Gerstenbräu-Scalder, das tapferen Abenteurern auf ihrer Reise nach Stormwind überreicht wird. Es dient sowohl als durststillendes Geschenk als auch als informelle Währung unter alten Bekannten.",h="Ein schweres Fässlein mit feurigem Gerstenbräu-Scalder, das tapferen Abenteurern auf ihrer Reise nach...",kw={"bier","gerstenbräu","fässlein mit gerstenbräu","dwarven district","furen longbeard","schildschmied","stormwind"},ang={["class:Warrior"]="Für einen Krieger, der nach verlässlichem Schutz sucht, ist die Sicherung von Furen Longbeards legendärer Schmiedekunst durch ein Fässlein edlen Bieres ein unverzichtbarer Übergangsritus.",["race:Dwarf"]="Nichts besiegelt ein Geschäft oder begleicht eine alte Verpflichtung unter Zwergen so gut wie die Lieferung eines frischen Fässleins von Gerstenbräus feinstem Erzeugnis."},sec={{t="Ein zwergischer Handel",b="Gerstenbräu-Scalder ist ein berühmtes Starkbier, das selbst den kältesten Zwerg erwärmen kann. Reisenden anvertraut, die ihren Mut im Rethban-Spießrutenlauf bewiesen haben, wird dieses Fässlein direkt zu Furen Longbeard im Dwarven District von Stormwind geschickt. Longbeard, ein meisterhafter Schildschmied, betrachtet trockene Zeiten als einen unerträglichen Zustand, was dieses potente Gebräu zum perfekten Hebel macht, um einen alten Gefallen einzufordern und sich hochwertige Zwergenhandwerkskunst zu sichern."}},faq={{q="Was befindet sich im Fässlein mit Gerstenbräu?",a="Das Fässlein ist mit Gerstenbräu-Scalder gefüllt, einem kräftigen und feurigen Gebräu, das von der Familie Barleybrew hergestellt wird. Es wird von Zwergen wegen seines starken Geschmacks und seiner wärmenden Wirkung geschätzt.",al={"welches getränk ist hierin","scalder-bier","gerstenbräu-scalder"}},{q="Für wen ist dieses Fässlein bestimmt?",a="Das Fässlein ist für Furen Longbeard bestimmt, einen erfahrenen Zwergenschildschmied, der im Dwarven District in der Stadt Stormwind arbeitet.",al={"wer bekommt das fässlein","wohin muss ich das bringen","scalder-empfänger"}},{q="Warum wird dieses Fässlein an Furen Longbeard geliefert?",a="Furen schuldet Yorus Gerstenbräu einen Gefallen. Die Übergabe dieses geschätzten Fässleins stillt Furens Durst während der von ihm so genannten 'trockenen Zeiten' und bewegt ihn dazu, einen robusten, außergewöhnlichen Schild für den Boten zu schmieden.",al={"warum furen scalder will","gefallen für schildschmied","zweck des fässleins"}}},fp="15,190,17.434.0,35.166.0,30.130.0,52.200.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="Fässlein mit Schimmerstarkbier",s="Das Fässlein mit Schimmerstarkbier ist ein versiegeltes Fass von Rejold Gerstenbräus wirkungsvollem neuem Starkbier, gebraut in den kalten Höhen von Dun Morogh. Bekannt für seinen beachtlichen Tritt und seine berauschende Kraft, wird es als geistvolles Geschenk für befreundete zwergische Gebirgsjäger ostwärts über das Gebirge geschickt.",h="Das Fässlein mit Schimmerstarkbier ist ein versiegeltes Fass von Rejold Gerstenbräus wirkungsvollem neuem...",kw={"fässlein mit schimmerstarkbier","dun morogh","kadrell","loch modan","rejold gerstenbräu","schimmerstarkbier","thelsamar"},ang={["race:Dwarf"]="Für Zwerge ist das Teilen feinen Starkbiers zwischen Patrouillen eine geachtete Tradition, welche die weit verstreuten Gebirgsjäger über die schroffen Gipfel von Khaz Modan hinweg verbindet."},sec={{t="Eine geistvolle Lieferung",b="In Kharanos von Rejold Gerstenbräu gebraut, erwarb sich Schimmerstarkbier schnell hohes Ansehen unter den einheimischen Gästen und Gebirgsjägern, die den schneidenden Frösten von Dun Morogh trotzten. Beeindruckt von dem Gebräu seines Bruders gab Gebirgsjäger Gerstenbräu ein Fass in Auftrag, das durch den östlichen Pass nach Loch Modan geschafft werden sollte. Zwerge schätzen kräftige Getränke sehr, sowohl als gesellschaftliches Grundnahrungsmittel wie auch als praktischen Schutz gegen die eisige Gebirgskälte, und das Teilen eines frischen Jahrgangs mit weit entfernten Kameraden ist eine altehrwürdige militärische Tradition."},{t="Ein zwergischer Muntermacher",b="Als es von Gebirgsjäger Kadrell auf seiner Wache in Thelsamar geöffnet und probiert wird, macht das Gebräu seinem Ruf alle Ehre. Weit entfernt von gewöhnlichem Wirtshausbier soll ein einziger Schluck Schimmerstarkbier die Glieder erleichtern und einem Soldaten das Gefühl geben, fliegen zu können – genau die Art von belebendem Trank, auf die ein zwergischer Späher angewiesen ist, während er lange, einsame Patrouillen entlang der Höhenstraßen geht."}},faq={{q="Was ist Schimmerstarkbier?",a="Schimmerstarkbier ist ein wirkungsvolles zwergisches Starkbier, gebraut von Rejold Gerstenbräu in Dun Morogh. Es wird für seinen kräftigen Tritt hoch geschätzt und ist dafür bekannt, den Körper zu beleben und die Kälte fernzuhalten.",al={"was ist schimmerstarkbier","schimmerstarkbier lore","wer braute schimmerstarkbier"}},{q="An wen wird das Fass geschickt?",a="Das Fass wird zu Gebirgsjäger Kadrell gesandt, einer Wache, die an der Straße durch die Siedlung Thelsamar in Loch Modan stationiert ist.",al={"wer bekommt das fass","wohin geht das fass","empfänger des fasses"}},{q="Warum wird Starkbier über das Gebirge geschickt?",a="Zwergische Gebirgsjäger teilen häufig außergewöhnliche Gebräue mit ihren Kameraden auf weit entfernten Patrouillen. Nachdem er Rejolds gelungene Kreation gekostet hatte, wollte sein Bruder Kadrell mit einer Kostprobe von Dun Moroghs feinstem neuem Rezept verwöhnen.",al={"warum lieferung","warum bier liefern","warum an kadrell senden"}},{q="Welche Wirkung hat Schimmerstarkbier auf den Zecher?",a="Das Starkbier ist überraschend wirkungsvoll. Bei der Verkostung ruft Gebirgsjäger Kadrell aus, dass es ihm den Kopf verdreht, seine Glieder erleichtert und ihm das Gefühl gibt, fliegen zu können.",al={"wie stark ist schimmerstarkbier","wirkung von schimmerstarkbier"}}},fp="21,274,19.512.0,20.395.0,22.190.0,30.138.0,34.223.0,51.169.0"}
P.entries["item:cats-eye-emerald"] = {n="Katzenaugensmaragd",s="Der Katzenaugensmaragd ist ein außergewöhnlich großer, faustgroßer Edelstein, der in der Felsadermine im nördlichen Brachland ausgegraben wurde. Begehrt wegen seines immensen Marktwertes, wurde er rasch zum Gegenstand von Ränkespielen außerhalb der Reihen der Venture Company.",h="Der Katzenaugensmaragd ist ein außergewöhnlich großer, faustgroßer Edelstein, der in der Felsadermine im...",kw={"boss kupferstecker","felsadermine","katzenaugensmaragd","smaragd","ratchet","das schlickermoor","venture company","werftmeister dizzywig"},ang={["class:Rogue"]="Einen gewaltigen, unzureichend bewachten Edelstein direkt vor den Augen der korrupten Zuchtmeister der Venture Company zu stehlen, ist der Inbegriff von Opportunismus.",["profession:Mining"]="Die Entdeckung eines makellosen, faustgroßen Edelsteins in einer ansonsten schmutzigen Industrieausgrabung wie der Felsadermine stellt den ultimativen Glückstreffer dar, von dem jeder Bergmann träumt."},sec={{t="Ein faustgroßes Vermögen",b="Als Arbeiter beim Aushub der Felsadermine der Venture Company nordöstlich des Schlickermoors auf einen gewaltigen Smaragd stießen, verbreitete sich die Nachricht wie ein Lauffeuer über die Savanne. Solch seltene, hochkarätige Edelsteine bleiben in goblinbeherrschten Gebieten selten lange geheim. Werftmeister Dizzywig in Ratchet bekam durch den stetigen Handelsklatsch zwischen seinen Docks und Booty Bay Wind von der Entdeckung und schmiedete sogleich Pläne, sich die Beute für den freien Markt in Undermine zu sichern."},{t="Im Besitz der Handelsgesellschaft",b="Anstatt auf legalem Wege in die üblichen Handelskanäle zu gelangen, wurde der Edelstein von der Führung der Venture Company im Inneren der Mine streng bewacht. Vorarbeiter, Vollstrecker und leitende Aufseher wie Boss Kupferstecker verteidigten ihre wertvolle Beute wachsam sowohl gegen rivalisierende Kartelle als auch gegen geschäftstüchtige Glücksritter, die auf Dizzywigs versprochenen Anteil von fünfzig Prozent aus waren."}},faq={{q="Was ist der Katzenaugensmaragd?",a="Es ist ein ungewöhnlich riesiger Smaragd, etwa so groß wie eine Faust, der bei Grabungsarbeiten im nördlichen Brachland gefunden wurde. Seine Reinheit und Größe machen ihn auf dem weltweiten Markt ein Vermögen wert.",al={"was ist der katzenaugensmaragd","katzenaugen edelstein","welche art edelstein ist das"}},{q="Wo wurde der Edelstein entdeckt?",a="Er wurde von Bergleuten der Venture Company in der Felsadermine ausgegraben, die nordöstlich des Schlickermoors im nördlichen Brachland liegt.",al={"wo wurde er gefunden","edelstein fundort","felsadermine smaragd"}},{q="Wer will den Smaragd in Ratchet haben?",a="Werftmeister Dizzywig, der Goblin, der die Schifffahrt und Fracht an den Docks von Ratchet beaufsichtigt, will den Stein an wohlhabende Käufer über Handelsverbindungen nach Undermine verkaufen.",al={"wer kauft den smaragd","dizzywig smaragd","wer vergibt quest für smaragd"}},{q="Wer hält den Stein in der Mine unter Verschluss?",a="Der Smaragd befindet sich in der Felsadermine im Besitz leitender Aufseher der Venture Company und wird von Vorarbeitern, Vollstreckern oder Boss Kupferstecker selbst getragen.",al={"wer lässt den smaragd fallen","wer hat den katzenaugensmaragd","wo findet man den katzenaugensmaragd"}}},fp="16,248,20.470.0,18.366.0,29.187.0,29.141.0,33.161.0,41.140.0"}
P.entries["item:cenarion-lunardust"] = {n="Lunarstaub des Cenarius",s="Lunarstaub des Cenarius ist ein heiliges Pulver, das jungen Taurendruiden von Turak Runetotem auf den Höhen von Thunder Bluff verliehen wird. Es dient dazu, die Wächterbestie Lunaclaw an einem uralten Moonkin Stone an der Grenze zwischen Mulgore und dem Brachland zu erwecken.",h="Lunarstaub des Cenarius ist ein heiliges Pulver, das jungen Taurendruiden von Turak Runetotem auf den Höhen...",kw={"körper und herz","lunarstaub des cenarius","druide der klaue","lunaclaw","lunarstaub","moonkin stone","turak runetotem"},ang={["class:Druid"]="Für Taurendruiden ist dieser Staub der entscheidende Katalysator im heiligen Übergangsritus, der die uralte Kunst des Bärengestaltwandels freischaltet.",["race:Tauren"]="Der Staub verbindet die jungen Shu'halo direkt mit den Lehren des Zirkels des Cenarius und zeugt von ihrer tieferen Verbundenheit mit der Natur und den wilden Geistern von Kalimdor."},sec={{t="Ein Ritus von Körper und Herz",b="Eingeweihten anvertraut, die bereit sind, ihren Platz unter den Druiden der Klaue einzunehmen, trägt der Lunarstaub des Cenarius den Segen des Zirkels des Cenarius in sich. Wenn er über dem Moonkin Stone westlich von Camp Taurajo verstreut wird, beschwört der leuchtende Staub Lunaclaw herauf, eine heilige Bestie, die dazu bestimmt ist, den Eingeweihten zu prüfen. Das Besiegen dieses Wächters stellt sowohl die körperliche Ausdauer als auch die geistige Entschlossenheit auf die Probe und erlaubt es dem jungen Druiden, die Stärke von Körper und Herz aufzunehmen, die erforderlich ist, um die Bärengestalt anzunehmen."}},faq={{q="Wofür wird Lunarstaub des Cenarius verwendet?",a="Er wird über den Moonkin Stone gestreut, der sich in den Hügeln zwischen Mulgore und dem Brachland, direkt westlich von Camp Taurajo, befindet. Das Auftragen des Staubs beschwört Lunaclaw herauf, eine mächtige Bestie, die Eingeweihte besiegen müssen, um ihre Stärke zu beweisen.",al={"was macht lunarstaub","wie benutzt man lunarstaub des cenarius","lunarstaub zweck"}},{q="Wer vergibt den Lunarstaub des Cenarius?",a="Turak Runetotem, der Druidenlehrer auf der Anhöhe der Ältesten in Thunder Bluff, gibt den Staub an Taurendruiden aus, welche die Prüfung der Bärengestalt absolvieren.",al={"wer gibt lunarstaub","wo gibt es lunarstaub des cenarius","turak runetotem staub"}},{q="Was passiert, wenn Ihr Euren Lunarstaub des Cenarius verliert?",a="Wenn Ihr den Staub verliert oder Eure Prüfung gegen Lunaclaw nicht besteht, müsst Ihr zu Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff zurückkehren, um einen weiteren Beutel zu erhalten.",al={"lunarstaub verloren","brauche mehr lunarstaub","woher noch einen lunarstaub bekommen"}},{q="Warum muss sich ein Druide Lunaclaw stellen?",a="Lunaclaw ist der Beschützer des Steins und verkörpert das Gleichgewicht zwischen körperlicher Kraft und innerer Entschlossenheit. Indem ein angehender Druide der Klaue das Wesen herausfordert und bezwingt, verinnerlicht er die Lehren von Körper und Herz, die nötig sind, um die Kräfte des Großen Bärengeistes zu nutzen.",al={"warum gegen lunaclaw kämpfen","wer ist lunaclaw","zweck von lunaclaw"}}},fp="18,242,24.474.0,36.224.0,36.145.0,49.152.0,31.267.0"}
P.entries["item:cenarion-moondust"] = {n="Mondstaub des Cenarius",s="Mondstaub des Cenarius ist ein heiliges Pulver, das Nachtelfendruiden anvertraut wird, die ihre Prüfungen ablegen, um Druiden der Klaue zu werden. Wenn er auf dem uralten Moonkin Stone in den Hügeln östlich von Auberdine verstreut wird, lockt er Lunaclaw hervor, den wilden Wächter der Höhle.",h="Mondstaub des Cenarius ist ein heiliges Pulver, das Nachtelfendruiden anvertraut wird, die ihre Prüfungen...",kw={"auberdine","körper und herz","mondstaub des cenarius","druide der klaue","lunaclaw","mathrengyl bearwalker","mondstaub","moonkin stone"},ang={["class:Druid"]="Für Nachtelfendruiden stellt der Umgang mit dem Mondstaub des Cenarius den krönenden Schritt auf dem Pfad zum Druiden der Klaue dar, der direkt zur Beherrschung der Bärengestalt führt.",["race:NightElf"]="Der Staub spiegelt die uralten Traditionen des Zirkels des Cenarius wider und verbindet Naturverehrung mit Mondritualen, um die Bestien von Darkshore zu ehren."},sec={{t="Ein Ritus der Klaue",b="Von Mathrengyl Bearwalker in Darnassus verliehen, dient Mondstaub des Cenarius als Katalysator für die letzte Prüfung von Körper und Herz eines jungen Druiden. Um mit dem Wächter Lunaclaw in Einklang zu treten und sich vor ihm zu beweisen, muss der Initiand zu den Mondkinhöhlen östlich von Auberdine in Darkshore reisen. Wird der Mondstaub auf dem uralten Moonkin Stone angewendet, beschwört er die Bestie, um den Initianden im Kampf zu prüfen, sodass der Druide die beharrliche Stärke verinnerlichen kann, die nötig ist, um die Bärengestalt zu kanalisieren."}},faq={{q="Wofür wird Mondstaub des Cenarius verwendet?",a="Er wird von Initianden der Nachtelfendruiden am Moonkin Stone in Darkshore verwendet, um Lunaclaw zu erwecken, wodurch ihre Stärke und Entschlossenheit geprüft wird, um sich die Macht der Bärengestalt zu verdienen.",al={"mondstaub verwendung","was bewirkt mondstaub des cenarius","zweck von mondstaub des cenarius"}},{q="Wo verwende ich den Mondstaub des Cenarius?",a="Er muss über dem Moonkin Stone in einer Mondkinhöhle verstreut werden, die in den Hügeln direkt östlich von Auberdine in Darkshore liegt.",al={"wo mondstaub verwenden","ort des moonkin stone","wo ist der lunaclaw-stein"}},{q="Wer gibt Mondstaub des Cenarius?",a="Mathrengyl Bearwalker, der Druidenlehrer in Die Enklave des Cenarius in Darnassus, übergibt ihn Initianden, die ihre Bereitschaft für die Prüfung von Körper und Herz bewiesen haben.",al={"wer gibt mondstaub","wo gibt es mondstaub des cenarius","mathrengyl mondstaub"}},{q="Was passiert, wenn ich den Mondstaub verliere?",a="Wurde der Mondstaub verlegt oder bei einem erfolglosen Versuch gegen Lunaclaw aufgebraucht, müssen Initianden nach Darnassus zurückkehren und Mathrengyl Bearwalker erneut bitten, die Prüfung zu erneuern.",al={"mondstaub des cenarius verloren","mondstaub verloren","mondstaub wiederholen"}}},fp="17,255,18.479.0,35.170.0,37.127.0,31.174.0,36.178.0"}
P.entries["item:centaur-bracers"] = {n="Zentaurenarmschienen",s="Zentaurenarmschienen sind einfache Armbänder aus Leder und Eisen, die getöteten Kolkarzentauren im gesamten Brachland abgenommen werden. Regthar Deathgate sammelt sie westlich des Crossroads als Beweis für ausgeschaltete Zentaurenräuber.",h="Zentaurenarmschienen sind einfache Armbänder aus Leder und Eisen, die getöteten Kolkarzentauren im gesamten...",kw={"brachland","kopfgeld","armschienen","zentaur","crossroads","deathgate","kolkar","regthar"},ang={["faction:Horde"]="Das Ausschalten von Kolkar-Plünderern unterstützt direkt die Expansion der Horde und hält die verwundbaren Karawanen-Versorgungslinien zwischen Durotar, Mulgore und dem Crossroads sicher.",["race:Tauren"]="Über Generationen hinweg litten die nomadischen Tauren unter den brutalen Übergriffen der Zentaurenklans; das Auslöschen der Kolkar aus dem Brachland bietet lang ersehnte Vergeltung und Sicherheit."},sec={{t="Ein erbittertes Kopfgeld",b="Der Stamm der Kolkar stellt eine unablässige Bedrohung für den Einfluss der Horde in den kargen Ebenen des Brachlands dar. Das Abstreifen der Armschienen von gefallenen Zentaurenkriegern dient als unbestreitbarer Beweis dafür, dass ein weiterer feindseliger Plünderer von den Handelswegen vertrieben wurde. Regthar Deathgate, ein Orc-Späher, der an den Klippen westlich des Crossroads stationiert ist, hat ein dauerhaftes Kopfgeld auf diese Trophäen ausgesetzt, um die Aggression des Stammes einzudämmen."}},faq={{q="Wer will diese Armschienen?",a="Regthar Deathgate, ein Späher der Horde, der auf einer Anhöhe westlich des Crossroads im Brachland lagert, nimmt sie als Beweis für Eure Bemühungen gegen die örtlichen Kolkarzentauren entgegen.",al={"wer nimmt zentaurenarmschienen","regthar deathgate abgabe","wer kauft zentaurenarmschienen"}},{q="Welche Zentauren tragen diese Armschienen?",a="Die Armschienen werden von Kolkarkriegern getragen, die die Oasen und Lager im nördlichen Brachland durchstreifen, wie etwa Die vergessenen Teiche und Die blühende Oase.",al={"wo armschienen farmen","kolkar armschienen beute","zentaurenarmschienen quelle"}},{q="Warum lässt Regthar sie sammeln?",a="Regthar versucht, die Zahl der Kolkar aktiv zu dezimieren, um das Territorium der Horde zu schützen. Das Sammeln von Trophäen wie den Armschienen stellt sicher, dass die Krieger die Marodeure tatsächlich eliminieren, anstatt sie nur zu verjagen.",al={"warum armschienen sammeln","regthar deathgate beweggrund","zweck von zentaurenarmschienen"}}},fp="15,199,15.413.0,24.160.0,34.151.0,37.207.0"}
P.entries["item:charred-horn"] = {n="Verkohltes Horn",s="Verkohlte Hörner sind die robusten, hitzegehärteten Hörner junger Schimären, die in den Felsen des Steinkrallengebirges hausen. Widerstandsfähig genug, um rauen Elementarkräften zu trotzen, dienen sie als essenzieller Härtungsbestandteil bei spezialisierten Rüstungsschmiedearbeiten.",h="Verkohlte Hörner sind die robusten, hitzegehärteten Hörner junger Schimären, die in den Felsen des...",kw={"verkohltes horn","schimäre","feuergehärteter panzer","furen longbeard","steinkrallengebirge"},ang={["class:Warrior"]="Furen Longbeard wirbt gezielt aufstrebende Krieger an, um diese Hörner quer durch Kalimdor zu beschaffen, und belohnt ihre gefahrvolle Reise mit maßgefertigtem, feuergehärtetem Kettenhemd.",["profession:Blacksmithing"]="Die Hörner dieser Bestien zeugen von einer exotischen Schmiedekunst, bei der das auf natürliche Weise flammengereifte biologische Material von Kalimdors Raubtieren genutzt wird, um Kettenglieder zu härten."},sec={{t="Eine seltene Schmiedekomponente",b="Verkohlte Hörner werden von flüggen und jungen Schimären erbeutet, die in den zerklüfteten Höhen des Steinkrallengebirges nisten, und sind wegen ihrer unnatürlichen Widerstandskraft gegen Flammen und stumpfe Gewalteinwirkung begehrt. Der Zwergenrüstungsschmied Furen Longbeard benötigt an seiner Schmiede in Stormwind eine Sammlung dieser Hörner, um feuergehärtetes Kettenhemd herzustellen. Zusammen mit giftigen Spinnenzähnen aus dem Sumpfland, Phlogiston aus Dem Kral von Razorfen und dem galvanisierten Horn einer Schimärenmatriarchin bieten diese verkalkten Hörner die grundlegende strukturelle Verstärkung, die zur Fertigung einer außergewöhnlich widerstandsfähigen Schutzrüstung erforderlich ist."}},faq={{q="Welche Kreaturen hinterlassen Verkohlte Hörner?",a="Sie werden von flüggen Schimären und jungen Schimären gesammelt, die im rauen Terrain des Steinkrallengebirges in Kalimdor heimisch sind.",al={"woher verkohltes horn","wer droppt verkohltes horn","verkohltes horn herkunft"}},{q="Wer in Stormwind möchte diese Hörner haben?",a="Der Meisterrüstungsschmied Furen Longbeard verlangt nach ihnen. Er nutzt ihre flammengehärtete Beschaffenheit als Rohmaterial, um ein außergewöhnlich robustes Kettenbrustteil für vielversprechende Krieger zu schmieden.",al={"wer braucht verkohltes horn","verkohltes horn abgeben","furen longbeard hörner"}},{q="Warum benötigt Furen so viele davon?",a="Furen benötigt zwölf Verkohlte Hörner, um genügend rohes, hitzebehandeltes Material zur angemessenen Verstärkung der Ringe und Platten seines feuergehärteten Kettenhemdes zur Verfügung zu haben.",al={"warum 12 verkohlte hörner","zweck von verkohltes horn"}},{q="Unterscheiden sich diese vom Galvanisierten Horn?",a="Ja. Verkohlte Hörner stammen in größerer Zahl von den kleineren, jüngeren Schimären des Steinkrallengebirges, während das Galvanisierte Horn eine einzelne, weitaus seltenere Trophäe ist, die direkt von einer Schimärenmatriarchin erbeutet wird.",al={"galvanisiertes horn vs verkohltes horn","unterschied zwischen hörnern"}}},fp="12,258,25.607.0,34.132.0,35.177.0,39.149.0,45.185.0"}
P.entries["item:chest-of-containment-coffers"] = {n="Truhe mit Verwahrungskästen",s="Die Truhe mit Verwahrungskästen enthält verzauberte Behälter, mit denen Magier instabile magische Phänomene einfangen. Sie dient als unverzichtbare Ausrüstung für jene, die ausgesandt werden, um unsichtbare Manaanomalien zu untersuchen und sicher einzudämmen.",h="Die Truhe mit Verwahrungskästen enthält verzauberte Behälter, mit denen Magier instabile magische Phänomene...",kw={"anastasia hartwell","apothecarium","arkane anomalie","verwahrungskasten","magic quarter","rissbrut"},ang={["class:Mage"]="Die Truhe liefert grundlegende Feldwerkzeuge für Magier, die lernen, mit flüchtigen arkanen Manifestationen umzugehen und lebende Exemplare für Studienzwecke zu sichern.",["race:Undead"]="Magier der Verlassenen nutzen diese Kästen, um magische Anomalien abzusichern, die in der Nähe des Apothecariums auftreten, ohne dass ungeprüfte arkane Mächte ihr Werk verderben."},sec={{t="Gefäße für das Unsichtbare",b="Magische Experimente und plötzliche dimensionale Risse bringen häufig flüchtige, unsichtbare Anomalien hervor, die gänzlich aus arkaner Kraft bestehen. Gewöhnliche physische Käfige vermögen es nicht, Wesen festzuhalten, die rein aus Magie geformt sind. Die Truhe mit Verwahrungskästen versorgt Magier mit spezialisierten, verzauberten Kästen, die darauf ausgelegt sind, diese überwältigten Kreaturen lebendig einzufangen und zu binden. In der Nähe ranghoher Ausbilder wie Anastasia Hartwell in Undercity und Jennea Cannon in Stormwind aufbewahrt, bietet die Truhe die nötige Ausrüstung für Initianden, die damit betraut sind, Anomalien zu untersuchen, ehe diese ihre Umgebung destabilisieren können."},{t="Arkane Verwahrungsprotokolle",b="Als sich im Apothecarium in Algernons Laden unsichtbare Störungen manifestierten, entsandten die Ausbilder der Verlassenen mit diesen Kästen ausgerüstete Magier, um den Vorfall einzudämmen. Das Einfangen eines Risswesens erfordert, es mit einer speziellen Schriftrolle sichtbar zu machen, seine Gestalt durch Zauber zu schwächen und es in einem der Kästen aus dieser Truhe festzusetzen. Die gefüllten Behälter gestatten es den Forschern der Verlassenen, sie gefahrlos zu sezieren, zu studieren und zu ergründen, ob es sich bei solchen Störungen um zufällige Risse in den Ley-Linien oder um vorsätzliche arkane Angriffe handelt."}},faq={{q="Was befindet sich in der Truhe mit Verwahrungskästen?",a="Die Truhe enthält spezialisierte, leere Verwahrungskästen. Magier entnehmen diese Gefäße, um überwältigte magische Kreaturen wie Rissbruten bei gefährlichen Feldeinsätzen zu sichern und einzufangen.",al={"was enthält die truhe","inhalt verwahrungskästen","truheninhalt"}},{q="Wo ist diese Truhe zu finden?",a="In Undercity steht sie direkt hinter Magierlehrerin Anastasia Hartwell im Magic Quarter. Eine entsprechende Truhe befindet sich auch in Stormwind hinter Jennea Cannon im Wizard's Sanctum.",al={"truhe mit verwahrungskästen standort","wo ist die truhe mit verwahrungskästen","standort der kasten truhe"}},{q="Warum benötigen Magier diese Kästen anstelle gewöhnlicher Käfige?",a="Die untersuchten Kreaturen sind Rissbruten, die rein aus ungreifbarer arkaner Energie bestehen. Gewöhnliche Materialien können sie nicht halten; nur magisch verzauberte Verwahrungskästen vermögen es, eine arkane Anomalie physisch einzufangen und zu stabilisieren.",al={"warum verwahrungskästen nutzen","wofür sind verwahrungskästen","wie funktionieren verwahrungskästen"}},{q="Was geschieht mit den Kästen, sobald sie gefüllt sind?",a="Gefüllte Kästen werden ranghohen Ausbildern zu Studienzwecken übergeben. Die gefangenen Kreaturen werden analysiert, um herauszufinden, ob eine arkane Störung ein zufälliger natürlicher Riss oder ein gezielter Angriff von außen war.",al={"was passiert mit gefangenen rissbruten","nutzen gefüllter verwahrungskasten","warum kreaturen fangen"}}},fp="28,226,22.578.0,28.527.1,48.185.0,30.194.0,56.222.0,49.216.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="Häuptling Spitzhauer Dornenmantels Kopf",s="Häuptling Spitzhauer Dornenmantels Kopf wird als grimmiger Beweis für den Sieg über den Anführer der Bristleback-Stacheleber genommen, die Red Cloud Mesa bedrohen. Geborgen aus den Tiefen der Dornrankenklamm, wird er Kriegerheldin Windfeather überreicht, um das Ende einer anhaltenden Bedrohung für junge Taurenkrieger zu besiegeln.",h="Häuptling Spitzhauer Dornenmantels Kopf wird als grimmiger Beweis für den Sieg über den Anführer der...",kw={"dornranken","bristleback","kopf","mulgore","sharptusk","thornmantle","windfeather"},ang={["class:Hunter"]="Für Jäger verkörpert Sharptusk die ultimative Beute: einen intelligenten Feind, der fähig ist, selbst Jagd auf andere zu machen, was ein Scharmützel ums Überleben in eine wahre Prüfung des Fährtenlesens und der Treffsicherheit verwandelt.",["race:Tauren"]="Den Kopf eines furchterregenden Gegners zu erbeuten markiert einen wichtigen Meilenstein für junge Tauren und beweist, dass sie die Entschlossenheit und das Geschick besitzen, die neu errichtete Heimat ihres Volkes zu beschützen."},sec={{t="Trophäe der Jagd",b="Die Tauren schaffen sich ihre friedliche Heimat in Mulgore durch Wachsamkeit und Stärke. Die in der Dornrankenklamm verschanzten Bristleback-Stacheleber führten, angetrieben von ihrem wilden Häuptling Sharptusk Thornmantle, einen aggressiven Feldzug gegen die Stämme von Camp Narache. Seinen Kopf abzutrennen geschieht nicht aus sinnloser Grausamkeit, sondern dient als endgültiger Beweis seines Ablebens und als deutliche Warnung an die überlebenden Stacheleber-Klans, die die Grenzen der Mesa bedrängen."},{t="Eine Lektion der Jagd",b="Kriegerheldin Windfeather verlangt den Kopf des Häuptlings als Übergangsritus für angehende Jäger und Verteidiger des Stammes. Für die Tauren stellt das Antreten gegen einen Gegner, der schlau genug ist, Vergeltung zu üben und eine ganze Kriegsschar zu organisieren, eine wesentliche Prüfung des kriegerischen Könnens dar. Das Vorzeigen von Sharptusks Kopf erfüllt diese Prüfung und verschafft dem jungen Kämpfer ein festes Ansehen unter den Kriegern von Red Cloud Mesa."}},faq={{q="Warum möchte Kriegerheldin Windfeather den Kopf von Sharptusk Thornmantle?",a="Kriegerheldin Windfeather verlangt einen unbestreitbaren Beweis dafür, dass der Häuptling der Bristleback-Stacheleber gefallen ist. Seinen Kopf zurückzubringen zeigt, dass Sharptusk keine Überfälle mehr gegen Camp Narache leiten wird, und signalisiert den verbliebenen Stachelebern, dass ihrer Aggression mit entschlossener Härte begegnet wird.",al={"warum seinen kopf nehmen","grund für sharptusks kopf","windfeather kopfanfrage"}},{q="Wer war Häuptling Sharptusk Thornmantle?",a="Häuptling Sharptusk Thornmantle war der Anführer der Bristleback-Stacheleber, welche die Dornrankenklamm am östlichen Rand von Red Cloud Mesa bewohnten. Unter seinem Befehl schikanierten und attackierten die Bristlebacks unaufhörlich junge Taurenkrieger.",al={"wer ist sharptusk","sharptusk thornmantle lore","stacheleberhäuptling mulgore"}},{q="Wo wird diese Trophäe erbeutet?",a="Der Kopf wird erbeutet, indem man Häuptling Sharptusk Thornmantle in seinem behelfsmäßigen Stammesdorf tief im Inneren der Dornrankenklamm östlich von Camp Narache bezwingt.",al={"wo finde ich den kopf","fundort sharptusks kopf"}}},fp="34,295,18.458.0,20.398.0,66.288.0,36.232.0,30.161.0"}
P.entries["item:chok-sul-s-head"] = {n="Chok'suls Kopf",s="Chok'suls Kopf dient als grausiger physischer Beweis für den Tod des Ogerhäuptlings von Mo'grosh. Wird er zu Magistrat Bluntnose in Thelsamar gebracht, sichert er ein offizielles Kopfgeld, das von den örtlichen Zwergenbehörden ausgesetzt wurde.",h="Chok'suls Kopf dient als grausiger physischer Beweis für den Tod des Ogerhäuptlings von Mo'grosh.",kw={"chok'sul","chok'suls kopf","loch modan","magistrat bluntnose","mo'grosh","oger","der stonewroughtdamm","thelsamar"},ang={["race:Dwarf"]="Die Ausschaltung von Chok'sul entlastet die ländlichen Siedlungen von Ironforge direkt und schützt lebenswichtige städtische Monumente wie den Stonewroughtdamm vor roher Zerstörung."},sec={{t="Beweis für den Fall des Häuptlings",b="Die Oger der Festung Mo'grosh stellen eine ständige Bedrohung für die Siedlungen von Loch Modan dar und verüben Angriffe auf Thelsamar, die Ausgrabungsstätten und den lebenswichtigen Stonewroughtdamm. Magistrat Bluntnose setzte ein Kopfgeld auf den Grobian aus, von dem man annahm, dass er diese Angriffe koordinierte: Chok'sul. Angesichts des Chaos in den nordöstlichen Hügeln verlangt der Magistrat unbestreitbare Beweise, bevor er Gelder der Gemeinde freigibt. Der abgetrennte Kopf des Ogerhäuptlings liefert die makabre Gewissheit, die der Zwergenrat benötigt, um den Auftrag als erfüllt anzusehen."}},faq={{q="Wer war Chok'sul?",a="Chok'sul war ein Ogerhäuptling, der in der Festung Mo'grosh im nordöstlichen Loch Modan stationiert war. Zwergenbeamte glauben, dass er der Drahtzieher hinter koordinierten Überfällen auf Thelsamar, den Stonewroughtdamm und nahe gelegene Ausgrabungsstätten war.",al={"wer ist choksul","choksul lore","chok'sul identität"}},{q="Warum will Magistrat Bluntnose den Kopf?",a="Magistrat Bluntnose hat ein öffentliches Kopfgeld für Chok'suls Beseitigung mit allen Mitteln ausgesetzt. Da die Ogerüberfälle die Region stark belastet haben, verlangt der Magistrat einen unumstößlichen Beweis für den Tod des Häuptlings, bevor er eine finanzielle Entschädigung aus den Kassen von Thelsamar auszahlt.",al={"warum will bluntnose kopf","choksul kopf zweck","wer will choksuls kopf"}},{q="Wo trieb Chok'sul sein Unwesen?",a="Chok'sul befehligte seine Kriegsschar von der Festung Mo'grosh aus, einer stark befestigten Ogerbastion in den zerklüfteten Hügeln des nordöstlichen Loch Modan.",al={"wo ist choksul","festung mo'grosh standort","choksul aufenthaltsort"}},{q="Welche Bedrohungen ging von Chok'sul für die Region aus?",a="Man nahm an, dass er aggressive Angriffe gegen Thelsamar und die nahe gelegene Infrastruktur der Zwerge koordinierte, darunter den Stonewroughtdamm und örtliche archäologische Ausgrabungsstätten.",al={"warum wird choksul gesucht","was hat choksul getan"}}},fp="15,204,29.539.0,17.240.0,44.284.0,27.149.0,45.174.0"}
P.entries["item:clarice-s-pendant"] = {n="Clarice' Anhänger",s="Clarice' Anhänger ist ein kleines Andenken, das Clarice Foster gehört, einer untoten Bewohnerin des Grabmals. Einst ein Geschenk ihres früheren Ehemanns Yuriv, dient der Schmuck heute nur noch als bittere Erinnerung an eine verlassene Familie und an eine verfehlte Hingabe an das Licht.",h="Clarice' Anhänger ist ein kleines Andenken, das Clarice Foster gehört, einer untoten Bewohnerin des Grabmals.",kw={"clarice foster","clarice' anhänger","verlassene","das grabmal","silberwald","grabmal","bis dass der tod uns scheidet","yuriv"},ang={["class:Paladin"]="Clarice' Verachtung für Yurivs Kreuzzug ist eine unbequeme Mahnung an den persönlichen Preis und die zerstörten Familien, die der heilige Eifer hinterlassen hat.",["race:Undead"]="Der Anhänger unterstreicht die Tragödie und Verbitterung, die viele Verlassene teilen, deren lebende Angehörige sie oft für Kreuzzüge im Stich ließen, die am Ende niemanden beschützen konnten."},sec={{t="Ein bitteres Andenken",b="Clarice' Anhänger steht für die zerrüttete menschliche Vergangenheit, die vielen Verlassenen gemein ist. Bevor der Dritte Krieg Lordaeron verschlang, verließ Clarice' Ehemann Yuriv sie und ihre Kinder, um sich dem Kampf gegen die Untoten anzuschließen, wobei er verkündete, dass die Hingabe an das Heilige Licht Vorrang vor allem anderen habe. Anstatt seine Heimat zu retten, fand Yuriv den Tod und ließ seine Familie zurück, die schließlich genau jener Geißel erlag, die er zu bekämpfen ausgezogen war. Für Clarice ist der Anhänger kein geschätztes Andenken, sondern ein kränkendes Schmuckstück, das ein Leben symbolisiert, in dem sie stets hinter Fanatismus und Pflicht zurückstehen musste."},{t="Ruhe auf Yurivs Grab",b="In dem Wunsch, die verbliebenen emotionalen Bande zu ihrem früheren Leben und ihrem treulosen Ehemann zu kappen, schickt Clarice einen Abenteurer aus, um das Schmuckstück direkt an Yurivs Grab beim Grabmal zurückzulegen. Die Grabstätte ist vernachlässigt und geschändet, begraben unter Unkraut und Müll. Als der Anhänger schließlich auf die gemeißelten Hände des Sarges gelegt wird, verblasst sein Edelstein merklich, wodurch auch die letzte verbliebene Wärme aus Clarice' früherem Leben erlischt."}},faq={{q="Wem gehört Clarice' Anhänger?",a="Der Anhänger gehört Clarice Foster, einer verlassenen Frau, die im Grabmal im Silberwald weilt. Er wurde ihr zu Lebzeiten von ihrem Ehemann Yuriv geschenkt, bevor dieser in den Krieg zog.",al={"wem gehört der anhänger","wessen anhänger ist das","clarice foster"}},{q="Wer war Yuriv?",a="Yuriv war zu Lebzeiten Clarice' Ehemann. Er verließ Clarice und die gemeinsamen Kinder, um im Namen des Heiligen Lichts gegen die aufkeimende Bedrohung durch die Untoten zu kämpfen, nur um den Tod zu finden und in einem vernachlässigten Grab beim Grabmal begraben zu werden.",al={"clarice ehemann","wer ist yuriv","yuriv grab"}},{q="Warum möchte Clarice den Anhänger loswerden?",a="Clarice nimmt es Yuriv übel, dass er seinen Kreuzzug und seine Hingabe an das Licht über sie und ihre Kinder gestellt hat. Sein Opfer bewirkte nichts – er starb dennoch, und sie blieb zurück, nur um letztlich in den Untod auferweckt zu werden; genau jenen Zustand, den er auszurotten versucht hatte.",al={"warum anhänger wegwerfen","warum hasst clarice yuriv","clarice anhänger quest"}},{q="Was geschieht, wenn der Anhänger auf Yurivs Grab gelegt wird?",a="Wenn er auf das Relief gelegt wird, das auf Yurivs Grab gemeißelt ist, verblasst der im Anhänger eingefasste Edelstein merklich, was das endgültige, kalte Ende ihrer Verbindung symbolisiert, während ein eisiger Wind über den Friedhof weht.",al={"was passiert an yurivs grab","anhänger auf grab"}}},fp="17,254,14.572.0,25.437.1,27.184.0,14.213.0,48.259.0,57.214.1"}
P.entries["item:claw-key"] = {n="Klauen-Schlüssel",s="Der Klauen-Schlüssel ist einer von drei druidischen Schlüsseln, die im Krallenbau auf dem Steinkrallengipfel versteckt sind. Zusammen mit dem Grabhügel-Schlüssel und dem Schläfer-Schlüssel wird er benötigt, um den verzauberten Talon Den Hoard zu öffnen.",h="Der Klauen-Schlüssel ist einer von drei druidischen Schlüsseln, die im Krallenbau auf dem Steinkrallengipfel...",kw={"grabhügelbau","klauen-schlüssel","druidenversteck","torhüterschlüssel","der steinkrallengipfel","der krallenbau","talon den hoard","der höhlenbau"},ang={["class:Druid"]="Benannt nach den legendären Druiden der Klaue, spiegelt dieser Schlüssel die heiligen Traditionen und Schutzzauber wider, die von den Nachtelfen-Grabhügelbewohnern geschaffen wurden.",["faction:Horde"]="Das Verhör gefangener Nachtelfen ermöglicht es der Horde, die uralten Verteidigungsanlagen der Druiden zu umgehen und die auf dem Steinkrallengipfel aufbewahrten heiligen Artefakte zu plündern."},sec={{t="Schutzzauber des Krallenbaus",b="Die Nachtelfendruiden errichteten den Krallenbau hoch oben auf dem Steinkrallengipfel als Zuflucht und Aufbewahrungsort für mächtige Relikte. Um sicherzustellen, dass diese Schätze vor Eindringlingen geschützt blieben, versteckten sie sie hinter einem mehrstufigen Sicherheitssystem. Der Schatz selbst ist durch drei verschiedene verzauberte Schlösser versiegelt: den Grabhügel-Schlüssel, den Schläfer-Schlüssel und den Klauen-Schlüssel. Jeder Schlüssel ist in einem speziellen druidischen Versteck verborgen, das einer Fackel ähnelt und sich in den gewundenen Tunneln des Grabhügelbaus befindet."},{t="Das Aufbrechen der Verstecke",b="Die Druiden ließen die Schlüssel nicht unbewacht oder frei zugänglich zurück. Um das Versteck zu öffnen, das den Klauen-Schlüssel enthält, muss zuerst der Torhüterschlüssel erbeutet werden, der nahe dem Eingang des Grabhügels versteckt ist. Einmal geborgen, dient der Klauen-Schlüssel als entscheidender Bestandteil, um das Siegel der Druiden zu brechen und die tief im Berg verborgenen Reichtümer an sich zu bringen."}},faq={{q="Wofür wird der Klauen-Schlüssel verwendet?",a="Der Klauen-Schlüssel ist einer von drei Schlüsseln, die benötigt werden, um den Talon Den Hoard zu öffnen, eine geschützte Steintruhe im Herzen des Krallenbaus auf dem Steinkrallengipfel.",al={"klauen-schlüssel verwendung","was öffnet der klauen-schlüssel","schlüssel für talon den hoard"}},{q="Wo ist der Klauen-Schlüssel zu finden?",a="Er ist in einem als Fackel getarnten Druidenversteck in den Tunneln des Krallenbaus auf dem Steinkrallengipfel deponiert. Das Öffnen des Verstecks erfordert den Torhüterschlüssel vom Eingang des Baus.",al={"klauen-schlüssel fundort","wo ist der klauen-schlüssel","klauen-schlüssel finden"}},{q="Welche anderen Schlüssel werden neben dem Klauen-Schlüssel benötigt?",a="Um den Talon Den Hoard zu öffnen, müsst Ihr den Klauen-Schlüssel, den Grabhügel-Schlüssel und den Schläfer-Schlüssel sammeln, die alle in separaten Verstecken im gesamten Bau zu finden sind.",al={"andere schlüssel","krallenbau schlüssel","schlüssel für den höhlenbau"}},{q="Warum haben die Druiden diese Schlüssel versteckt?",a="Die Nachtelfendruiden erbauten den Krallenbau, um mächtige Relikte vor neugierigen Blicken zu verbergen, und nutzten ein komplexes System aus Schlüsseln und versteckten Lagern, um Eindringlinge abzuschrecken.",al={"warum schlüssel versteckt sind","lore zum krallenbau"}}},fp="8,191,22.466.0,20.344.0,30.150.0,32.175.0,50.149.0,35.166.0"}
P.entries["item:cliffspring-river-sample"] = {n="Cliffspring-Probe",s="Eine Glasphiole mit trübem, übelriechendem Wasser, das am Fuß des Wasserfalls des Cliffsprings in Darkshore geschöpft wurde. Die im Auftrag von Thundris Windwirker in Auberdine gesammelte Probe liefert den handfesten Beweis für eine um sich greifende Verderbnis, die die Küstensiedlung bedroht.",h="Eine Glasphiole mit trübem, übelriechendem Wasser, das am Fuß des Wasserfalls des Cliffsprings in Darkshore...",kw={"auberdine","blackwood","cliffspring","teufelswald","probe","thundris","rohr","wasserfall","windwirker"},ang={["class:Druid"]="Druiden sind feinfühlig auf das Gleichgewicht natürlicher Gewässer eingestimmt, weshalb die unnatürliche Toxizität der Cliffspring-Probe für sie eine dringende Priorität darstellt, die es zu untersuchen und zu reinigen gilt.",["race:NightElf"]="Für die Nachtelfen von Auberdine ist jede Verderbnis der Gewässer des nördlichen Kalimdors ein ernstes Omen für die fortschreitende Plage, die sich vom Teufelswald ausbreitet."},sec={{t="Eine verdorbene Strömung",b="Der Cliffspring fließt von den schroffen östlichen Höhen von Darkshore herab, rauscht an uralten Steinbrücken vorbei und mündet schließlich am Nebelrand ins Meer. In letzter Zeit sind die kristallklaren Gewässer des Flusses faulig und sichtlich verdorben geworden. Aus Furcht, dass das giftige Wasser bald Auberdines Küste und Wasserversorgung verseuchen wird, beauftragte der Nachtelf Thundris Windwirker Reisende damit, diese Wasserprobe direkt aus dem Becken unter dem unteren Wasserfall des Flusses zu entnehmen. Die Probe bestätigt das Schlimmste: Unnatürliche Fäulnis treibt stetig flussabwärts in Richtung Küste."},{t="Echos aus dem Teufelswald",b="Obwohl die einheimischen Blackwood-Furbolgs die flussaufwärts gelegenen Ufer bewohnen und unter seinem verfinsternden Einfluss leiden, deutet die Wasserprobe auf ein weitaus tiefer sitzendes Übel hin als bloßen Unfug der Stämme. Thundris erkennt, dass die üble Natur der Verderbnis ihren Ursprung hoch oben auf den Klippen im Osten hat, in den verheerten Weiten des Teufelswalds. Die verdorbene Probe dient als endgültiger Beweis dafür, dass die dämonische Krankheit, die die Berggipfel heimsucht, nach unten in Darkshores Wassereinzugsgebiete sickert, was die Verteidiger von Auberdine dazu zwingt, eine Gegenmaßnahme vorzubereiten."}},faq={{q="Wo wird die Cliffspring-Flussprobe gesammelt?",a="Sie wird aus dem Becken unter dem ersten Wasserfall entlang des Cliffsprings geschöpft, der nördlich von Auberdine liegt. Reisende müssen dem Fluss landeinwärts folgen, bis sie den Wasserfall unter einer darüberliegenden Brücke erreichen.",al={"wo bekomme ich die probe","cliffspring standort","wasserfallbecken probe"}},{q="Warum benötigt Thundris Windwirker dieses Wasser?",a="Thundris befürchtet, dass die Faulheit des Flusses die Küstengewässer nahe Auberdine verseuchen wird. Das Sammeln und Untersuchen einer physischen Probe ermöglicht es ihm, das Wesen des Makels zu analysieren und einen Plan zu entwickeln, um ihm entgegenzuwirken.",al={"warum wasser sammeln","thundris fluss quest","zweck der flussprobe"}},{q="Was führt dazu, dass der Cliffspring verdirbt?",a="Obwohl die verdorbenen Blackwood-Furbolgs entlang des Flusses hausen, vermutet Thundris, dass der wahre Ursprung weiter östlich im Teufelswald liegt, dessen anhaltende dämonische Verderbnis in die Quellgebiete der Berge sickert.",al={"was hat den fluss vergiftet","warum ist das wasser verdorben","quelle der flussverderbnis"}},{q="Sind die Blackwood-Furbolgs für das Gift verantwortlich?",a="Sie verschlimmern das Problem an den Flussufern, sind jedoch nicht die eigentliche Ursache. Die Furbolgs sind selbst der umfassenderen Verderbnis zum Opfer gefallen, die aus den verwüsteten Ländern im Osten herabgespült wird.",al={"haben die furbolgs das getan","blackwood furbolg verderbnis","vergiften furbolgs das wasser"}}},fp="24,275,17.572.0,17.522.1,48.206.0,45.211.0,51.197.0,54.199.0"}
P.entries["item:cloth-request"] = {n="Stoff-Anforderung",s="Die Stoff-Anforderung ist ein Bestellschein, der von dem Stormwind-Händler Harlan Bagley verfasst wurde. Gerichtet an Rema Schneider im Canal Tailor and Fit Shop, erbittet die Notiz frische Ballen und Strickwaren, um Bagleys sich rapide leerende Regale wieder aufzufüllen.",h="Die Stoff-Anforderung ist ein Bestellschein, der von dem Stormwind-Händler Harlan Bagley verfasst wurde.",kw={"canal tailor shop","stoff-anforderung","harlan bagley","rema schneider","nachschub","stormwind"},ang={["faction:Alliance"]="Der Ansturm auf robuste Gewänder spiegelt das spürbare Unbehagen wider, das die Bürgerschaft von Stormwind erfasst hat, die sich trotz des Fehlens offizieller Ankündigungen der Regentschaft auf Konflikte vorbereitet.",["profession:Tailoring"]="Die Anforderung verdeutlicht den geschäftigen internen Textilhandel in Stormwind, wo Nachbarschaftsschneider wie die Schneiders Gesetzlose und Ausstatter mit Webwaren versorgen."},sec={{t="Ein Ansturm auf robuste Waren",b="Diese von Harlan Bagley verfasste Handelsanforderung bittet die Schneider des Kanalviertels um frischen Nachschub an Strickwaren und Stoff. Bagley bemerkt einen plötzlichen, beunruhigenden Anstieg des Handels: Gewöhnliche Bürger und Reisende decken sich massenhaft mit Rüstungen und robuster Kleidung ein, als würden sie sich für eine brutale Jahreszeit rüsten. Als sie Rema Schneider überbracht wird, lässt die Anforderung den Schneider verwundert und wachsam zurück. Rema fragt sich, warum sich die Stadtbewohner still und heimlich wappnen, obwohl das House of Nobles keinen offenen Krieg ausgerufen hat, was den leisen Verdacht schürt, dass die Anführer der Krone Unruhen verschweigen."}},faq={{q="Was ist die Stoff-Anforderung?",a="Es ist eine schriftliche Nachschubanforderung von Ladenbesitzer Harlan Bagley, in der er Schneider Rema Schneider um neue Ladungen Stoff und Strickwaren bittet, um seinen Laden wieder aufzufüllen.",al={"was ist stoff-anforderung","stoff-anforderung gegenstand","harlan bestellschein"}},{q="Warum braucht Harlan Bagley mehr Stoff?",a="Bagleys Geschäft war ungewöhnlich belebt. Stadtbewohner und Reisende haben Rüstungen und robuste Kleidung in großen Mengen aufgekauft und seine Vorräte erschöpft.",al={"warum harlan stoff braucht","warum bagley keine vorräte mehr hat","bagley nachschub grund"}},{q="Wohin muss diese Anforderung gebracht werden?",a="Die Bestellung wird zu Rema Schneider im Canal Tailor and Fit Shop gebracht, der an den Wasserstraßen von Stormwind liegt.",al={"wohin mit der stoff-anforderung","wer erhält stoff-anforderung","stoff-anforderung abgabe"}},{q="Warum kaufen die Menschen in Stormwind so viel Rüstung und Kleidung?",a="Weder die Händler noch das gemeine Volk wissen es mit Gewissheit. Rema Schneider findet den plötzlichen Andrang beunruhigend und fragt sich, ob der Adelsrat sich anbahnende Feindseligkeiten oder Gefahren vor der Öffentlichkeit verbirgt.",al={"warum leute rüstung kaufen","ist stormwind im krieg","rema schneider verdacht"}}},fp="13,237,21.579.0,26.157.0,39.155.0,35.114.0,62.195.0"}
P.entries["item:cloven-hoof"] = {n="Gespaltener Huf",s="Der Gespaltene Huf ist ein geheimnisvolles Relikt, das tief in Tausend Nadeln vom Zentaurenstamm der Galak bewacht wird. Es wird im Inneren einer uralten heiligen Flamme in der Spalthufhöhle aufbewahrt und strahlt eine uncharakteristische übernatürliche Energie aus, die Taurengelehrte unbedingt verstehen wollen.",h="Der Gespaltene Huf ist ein geheimnisvolles Relikt, das tief in Tausend Nadeln vom Zentaurenstamm der Galak...",kw={"uralte feuerschale","gespaltener huf","galak","rau cliffrunner","die heilige flamme","spalthufklippe","spalthufhöhle"},ang={["class:Shaman"]="Die Verwendung ritueller Elemente, um magische Flammen gefahrlos zu löschen und erfüllte Relikte zu bergen, unterstreicht die subtile Natur spiritueller Nachforschungen in Kalimdor.",["race:Tauren"]="Über Generationen hinweg litten die nomadischen Tauren unter den unerbittlichen Angriffen der Zentauren. Die Aufdeckung der Herkunft und magischen Geheimnisse hinter Relikten wie dem Gespaltenen Huf bietet wertvolles Wissen im Kampf gegen ihre historischen Widersacher."},sec={{t="Ein heiliges Zentaurenrelikt",b="In einer uralten Feuerschale in den tiefsten Tiefen der Spalthufhöhle aufbewahrt, ist der Gespaltene Huf eines der wertvollsten Relikte der Galakzentauren. Das Artefakt ist ununterbrochen von einer magischen Flamme umhüllt, sodass gesegnetes Wasser erforderlich ist, um das Feuer kurzzeitig zu löschen und es berühren zu können. Die Zentaurengesellschaft ist berüchtigt für ihre Brutalität und in gewalttätige Klans zersplittert, doch ihre Verehrung für die Feuerschale deutet auf eine rituelle Bedeutung hin, die direkt mit ihren Ursprüngen verknüpft ist. Taurenbeobachter wie Rau Cliffrunner am Freiwindposten glauben, dass die seltsame Aura, die von dem Huf ausgeht, entscheidende Einblicke in das Volk liefern könnte, das die Ebenen von Kalimdor seit Generationen heimsucht."}},faq={{q="Wo wird der Gespaltene Huf aufbewahrt?",a="Der Gespaltene Huf ruht in einer uralten Feuerschale ganz hinten in der Spalthufhöhle, einer Höhle in der Spalthufklippe nördlich des Freiwindpostens. Er wird von Elitekriegern der Galakzentauren schwer bewacht.",al={"gespaltener huf aufenthaltsort","gespaltener huf fundort","spalthufhöhle relikt"}},{q="Warum will Rau Cliffrunner den Gespaltenen Huf haben?",a="Rau Cliffrunner möchte das Artefakt untersuchen, um mehr über die Ursprünge und die Magie der Zentauren zu erfahren. Er spürt eine seltsame Energie, die von dem Relikt ausgeht, und hofft, damit lange verborgene Geheimnisse über die feindseligen Klans zu lüften.",al={"warum gespaltenen huf holen","rau cliffrunner quest","wer sucht gespaltenen huf"}},{q="Wie wird der Gespaltene Huf aus der Feuerschale geborgen?",a="Das Relikt ist von magischem Feuer umhüllt und kann nicht direkt an sich genommen werden. Eine Phiole mit speziellem Wasser muss in die uralte Feuerschale gegossen werden, um die heilige Flamme vorübergehend zu löschen, sodass der Huf sicher ergriffen werden kann, bevor das Feuer wieder aufflammt.",al={"gespaltenen huf bekommen","heilige flamme löschen","gefüllte geätzte phiole nutzen"}},{q="Wer sind die Galakzentauren, die ihn bewachen?",a="Der Stamm der Galak ist die dominierende Zentaurenfraktion, die die nördlichen Bereiche von Tausend Nadeln besetzt hält. Sie haben ihre Festung an der Spalthufklippe und verteidigen ihr hochheiliges Feuer aggressiv gegen Außenstehende.",al={"galak zentauren","spalthufklippe zentauren","wer bewacht die flamme"}}},fp="11,259,22.647.0,30.200.0,46.215.0,50.240.0,38.203.0"}
P.entries["item:comar-s-heart"] = {n="Comar's Heart",s="Comar's Heart ist eine makabre Ritualkomponente, herausgeschnitten aus Comar Villard, einem treuen menschlichen Wanderer, der die Sümpfe des Sumpflands auf der Suche nach seiner verlorenen Frau durchstreift. Hexenmeister der Verlassenen in Undercity begehren dieses Relikt reiner Hingabe, um die Beschwörungsriten einer Sukkubus zu speisen.",h="Comar's Heart ist eine makabre Ritualkomponente, herausgeschnitten aus Comar Villard, einem treuen...",kw={"carendin halgar","comar villard","comar's heart","herzen der reinen","sukkubus","tempel der verdammten","undercity","sumpfland"},ang={["class:Warlock"]="Comar's Heart an sich zu nehmen, veranschaulicht die kalte, pragmatische Grausamkeit der Dämonologie: Unbefleckte sterbliche Tugend ist lediglich ein Köder, der genutzt wird, um eine Sukkubus in Eure Dienerschaft zu locken.",["race:Undead"]="Für die Verlassenen unterstreicht das Ernten des Herzens eines treuen menschlichen Liebenden den vollständigen emotionalen Bruch zwischen den Lebenden und den Untoten in Lordaeron."},sec={{t="Ein Leuchtfeuer der Reinheit",b="Um eine Kreatur zu binden, die so launisch und raubtierhaft ist wie eine Sukkubus, müssen Hexenmeister den Dämon mit wahrer Reinheit und Hingabe anlocken. Die Jünger von Carendin Halgar in Undercity machen Comar Villard als einen der wenigen Männer aus, die eine derart unbefleckte Treue besitzen. Während seine Frau in den Wirren verloren ging, die die Östlichen Königreiche heimsuchten, wandert Comar beharrlich über die durchnässten Straßen des Sumpflands und weigert sich, seine Suche aufzugeben. Genau diese unerschütterliche Liebe zeichnet ihn für das Schlachten vor und macht sein noch schlagendes Herz zum idealen Köder für einen dämonischen Diener."},{t="Der Preis der Verführung",b="Die Beschaffung des Herzens verlangt von den Lehrlingen der Verlassenen, weit nach Süden durch umkämpfte Gebiete vorzudringen, vorbei am Thandol-Übergang und tief hinein in die von der Allianz beherrschten Sümpfe. Zurückgebracht in den Tempel der Verdammten neben Dalins Herz, wirkt das Organ völlig alltäglich, trotz der tiefen Güte, die es einst antrieb. Doch für die Sinne des Nethers ist die verbliebene Tugend, die von Comars Fleisch ausgeht, ein berauschender Köder – stark genug, um eine Sukkubus durch den dimensionalen Schleier in die Knechtschaft des Hexenmeisters zu ziehen."}},faq={{q="Wer war Comar Villard?",a="Comar Villard war ein ergebener Mensch, der das gefährliche Sumpfland nach jeder Spur seiner verschwundenen Frau absuchte. Seine unendliche Liebe und seine standhafte Weigerung, die Hoffnung aufzugeben, machten ihn als einen Mann von wahrhaft reinem Herzen bekannt.",al={"wer ist comar","comar villard geschichte","warum comar toeten"}},{q="Warum benötigen Hexenmeister Comar's Heart?",a="Hexenmeister von Undercity benötigen das Herz eines vollkommen reinen und ehrenhaften Sterblichen, um eine Sukkubus anzulocken und zu binden. Der Dämon fühlt sich naturgemäß dazu hingezogen, echte Tugend zu verderben und sich an ihr zu laben, was Comars unerschütterliche Hingabe zu einem unwiderstehlichen Köder macht.",al={"warum comars herz benoetigt","wofuer ist comars herz","sukkubus herz geschichte"}},{q="Wo ist Comar Villard zu finden?",a="Er wandert entlang der Hauptstraße im nördlichen Sumpfland, knapp südlich des Thandol-Übergangs, der das Arathihochland und Khaz Modan verbindet.",al={"comar villard aufenthaltsort","wo ist comar","wie findet man comar"}},{q="Wer schickt Hexenmeister los, um das Herz zu beschaffen?",a="Die Aufgabe wird von den Hexenmeisterlehrern in Undercity unter der Leitung von Carendin Halgar im Tempel der Verdammten vergeben, als Teil der rituellen Ausbildung eines Lehrlings zur Beschwörung einer Sukkubus.",al={"wer will comars herz","wer vergibt herzen der reinen","carendin halgar herz"}}},fp="13,268,18.556.0,22.505.1,22.204.0,35.239.0,29.133.0,40.188.0"}
P.entries["item:consecrated-rune"] = {n="Geweihte Rune",s="Eine Geweihte Rune ist ein beschrifteter heiliger Gegenstand, der angehenden Zwergenpaladinen überreicht wird, die im Coldridgetal ausgebildet werden. Er dient als einführende Vorladung von Bromos Grummner, die Novizen anweist, sich in Anvilmar zu melden und ihre formellen Pflichten als Ritter der Silbernen Hand aufzunehmen.",h="Eine Geweihte Rune ist ein beschrifteter heiliger Gegenstand, der angehenden Zwergenpaladinen überreicht...",kw={"anvilmar","bromos grummner","das coldridgetal","geweihte rune","das heilige licht","paladin","silberne hand"},ang={["class:Paladin"]="Für Zwergenpaladine bedeutet der Erhalt dieser Rune ihren formellen Eintritt in die Reihen der Ritter der Silbernen Hand unter der Anleitung von Bromos Grummner.",["race:Dwarf"]="Die Rune spiegelt die Einbindung menschlicher heiliger Traditionen in die kriegerische Kultur der Zwerge wider, verwurzelt in dem gemeinsamen Bündnis und dem gegenseitigen Respekt zwischen Ironforge und der Menschheit."},sec={{t="Ein Ruf zur Silbernen Hand",b="Novizen der Zwergenpaladine, die sich im Coldridgetal beweisen, erhalten eine Geweihte Rune, sobald sie grundlegende kämpferische Fähigkeiten gezeigt haben. Versehen mit heiligen Worten und gesegnet durch das Heilige Licht, stammt die Rune von Bromos Grummner, dem Paladinlehrer, der sich in Anvilmar aufhält. Zwerge hegen tiefen Respekt vor den Traditionen des Heiligen Lichts, die ihnen von ihren menschlichen Verbündeten nähergebracht wurden. Das Lesen der Rune dient sowohl als offizielle Vorladung als auch als symbolischer Übergangsritus, der den Platz des Novizen unter den Rittern der Silbernen Hand bestätigt."}},faq={{q="Wofür wird die Geweihte Rune verwendet?",a="Die Rune ist eine schriftliche Vorladung, die von Zwergenpaladin-Novizen gelesen werden soll. Sie weist sie an, Bromos Grummner in Anvilmar aufzusuchen, um ihre Paladinausbildung voranzutreiben.",al={"geweihte rune zweck","was macht die rune","geweihte rune questgegenstand"}},{q="Wer schickt die Geweihte Rune?",a="Sie wird von Bromos Grummner gesendet, dem Zwergenpaladinlehrer, der in Anvilmar im Coldridgetal stationiert ist.",al={"wer gab mir geweihte rune","rune herkunft","bromos grummner rune"}},{q="Warum folgen Zwergenpaladine den Traditionen der Silbernen Hand?",a="Zwerge lernten viel über das Heilige Licht und die Wege der Silbernen Hand von menschlichen Mentoren. Sie bringen der Geschichte und den Traditionen des Ordens sowie dem Glauben, dass ein einziges Opfer das Schicksal von Azeroth verändern kann, große Ehrfurcht entgegen.",al={"zwergenpaladin silberne hand","warum sind zwerge paladine","zwerge und heiliges licht"}}},fp="16,275,28.546.0,38.169.0,31.105.0,65.222.0"}
P.entries["item:console-key"] = {n="Konsolenschlüssel",s="Der Konsolenschlüssel ist ein mechanischer Überbrückungsschlüssel, den Tüftler Sniggles an der Ausgrabungsstätte der Venture Company im Brachland bei sich trägt. Er entriegelt das Hauptsteuerterminal, in dem sich der Samophlansch befindet, sodass das Gerät geborgen werden kann, nachdem die Vorrichtung abgeschaltet wurde.",h="Der Konsolenschlüssel ist ein mechanischer Überbrückungsschlüssel, den Tüftler Sniggles an der...",kw={"brachland","konsolenschlüssel","steuerkonsole","samophlange","tinkerer sniggles","venture company"},ang={["faction:Horde"]="Tüftler Sniggles den Konsolenschlüssel abzunehmen trägt dazu bei, die ausbeuterischen Industrieoperationen der Venture Company im Herzen des Brachlands zu stören.",["profession:Engineering"]="Die Venture Company verwendet maßgeschneiderte schlüsselbasierte Verriegelungen, um empfindliche Ingenieursprototypen wie den Samophlansch vor Konkurrenten zu schützen."},sec={{t="Sicherung der Vorrichtung",b="Die Venture Company unterhält einen weitläufigen Industrieaußenposten im nördlichen Brachland, der auf spezielle dampfbetriebene Maschinerie angewiesen ist, die von einem rätselhaften Gerät namens Samophlansch gesteuert wird. Um unbefugte Manipulationen zu verhindern, ist die Konsole der Vorrichtung fest verschlossen. Nur der leitende Techniker vor Ort, Tüftler Sniggles, trägt den Konsolenschlüssel bei sich, der benötigt wird, um das Gehäuse des Terminals aufzubrechen und die Stromzufuhr der Anlage vollständig zu kappen."},{t="Abschalten der Anlage",b="Die Steuerkonsole zu deaktivieren erfordert mehr als bloße Gewalt. Sobald die Hilfsventile betätigt wurden und die interne Vorrichtung in einen Ruhezustand heruntergekühlt ist, unterbricht das Einstecken des Konsolenschlüssels die letzten Schaltkreise. Das Drehen des Schlüssels entzieht dem Terminal die verbleibende Energie und entriegelt das Gehäuse, sodass der Samophlansch sicher aus der Maschinerie herausgehebelt werden kann."}},faq={{q="Was öffnet der Konsolenschlüssel?",a="Er entriegelt die Hauptsteuerkonsole an der Anlage der Venture Company im nördlichen Brachland, wodurch der Samophlansch freigelegt und dem Terminal die Energie entzogen wird, sobald die Maschinerie im Leerlauf läuft.",al={"wofür ist der konsolenschlüssel","was öffnet der konsolenschlüssel","konsolenschlüssel nutzen"}},{q="Wer hat den Konsolenschlüssel bei sich?",a="Der Schlüssel wird von Tüftler Sniggles aufbewahrt, einem Ingenieur der Venture Company, der in einer Hütte nordöstlich der primären Konsolenvorrichtung stationiert ist.",al={"wer lässt konsolenschlüssel fallen","woher bekommt man den konsolenschlüssel","tüftler sniggles schlüssel"}},{q="Warum ist die Konsole überhaupt verschlossen?",a="Die Venture Company betreibt firmeneigene und gefährliche Industrietechnik. Das Verriegeln des Terminals verhindert, dass sich einmischende Konkurrenten oder aufsässige Arbeiter die Maschinerie sabotieren oder wertvolle Komponenten wie den Samophlansch entwenden.",al={"warum brauche ich einen schlüssel","warum ist der samophlansch verschlossen"}},{q="Kann man den Schlüssel benutzen, bevor die Ventile geschlossen wurden?",a="Der Schlüssel ist dafür vorgesehen, die Konsole zu entriegeln, nachdem die Vorrichtung heruntergefahren wurde und die Messgeräte auf Null stehen. Der Versuch, an einer aktiven Konsole zu manipulieren, birgt das Risiko eines vollständigen mechanischen Rückschlags.",al={"schlüssel zuerst benutzen","kann ich die konsole einfach öffnen"}}},fp="11,253,22.419.0,21.360.1,33.179.0,28.132.0,45.222.0,52.186.0"}
P.entries["item:control-console-operating-manual"] = {n="Steuerkonsolen-Bedienungsanleitung",s="Die Steuerkonsolen-Bedienungsanleitung ist ein technisches Dokument, das detailliert beschreibt, wie die Maschinen an der Forschungsstätte der Venture Company südwestlich des Schlickermoors bedient werden. Sie enthält Anweisungen, die erforderlich sind, um die Ventile sicher zu schließen und die geheimnisvolle Vorrichtung, bekannt als Samophlansch, abzuschalten.",h="Die Steuerkonsolen-Bedienungsanleitung ist ein technisches Dokument, das detailliert beschreibt, wie die...",kw={"brachland","steuerkonsole","gobliningieurskunst","bedienungsanleitung","samophlansch","das schlickermoor","venture company"},ang={["faction:Horde"]="Die Anleitung gewährt Ermittlern der Horde einen Einblick in die invasiven industriellen Machenschaften, die die Venture Company im gesamten nördlichen Brachland aufgebaut hat.",["profession:Engineering"]="Die Anleitung veranschaulicht die typische Ingenieursphilosophie der Goblins: Systeme unter extremem Druck und mit minimaler Sicherheit, die durch eine chaotische Anordnung von Hebeln und Ventilen anstelle ausgewogener Sicherheitsvorkehrungen gesteuert werden."},sec={{t="Entschlüsselung von Goblin-Maschinen",b="Die Venture Company betreibt eine abgelegene Bohr- und Forschungsstätte im nördlichen Brachland, südwestlich des Schlickermoors. Nach typischer Goblin-Art läuft ihre komplexe Maschinerie über eine chaotische Anordnung von Messgeräten, Druckventilen und miteinander verbundenen Mechanismen, die darauf ausgelegt sind, ein Gerät namens Samophlansch zu nutzen. Ohne ordnungsgemäße Betriebsverfahren birgt die Manipulation derart unbeständiger Konstruktionen das Risiko verheerender Fehlzündungen oder vollständiger Systemsperren. Diese Bedienungsanleitung umreißt die genaue Abfolge der Ventilbetätigungen, die erforderlich sind, um den Kernapparat sicher zu lösen, ohne einen explosiven Ausfall auszulösen."}},faq={{q="Wofür wird die Steuerkonsolen-Bedienungsanleitung verwendet?",a="Sie liefert die Betriebsanweisungen zur Bedienung der Steuerkonsole der Venture Company südwestlich des Schlickermoors und leitet Euch dabei an, die entsprechenden Ventile zu schließen, damit der Samophlansch gelöst werden kann.",al={"was bringt die anleitung","anleitung nutzen","warum habe ich die bedienungsanleitung"}},{q="Was ist ein Samophlansch?",a="Selbst Forscher außerhalb der Venture Company verstehen nicht vollends, was ein Samophlansch bewirkt. Es scheint sich um einen komplexen, von Goblins konstruierten Kernmechanismus zu handeln, der mit ihren Bohr- und Industrieaktivitäten im Brachland verbunden ist.",al={"was macht der samophlansch","samophlansch lore","was ist das für eine maschine"}},{q="Wer hat diese Anleitung verfasst?",a="Die Anleitung wurde von Technikern der Venture Company verfasst, die den Forschungsaußenposten beaufsichtigten. Sie sollte sicherstellen, dass ihre Arbeiter die Konsole bedienen und optimale Druckwerte an den Steuerventilen aufrechterhalten konnten.",al={"wer hat die anleitung geschrieben","autor der anleitung"}},{q="Was passiert, wenn ich die Anleitung verliere?",a="Die Konsole selbst verfügt über klare Anzeigen und Messwerte, die den Ventildruck angeben. Das bedeutet, dass ein geschickter Abenteurer die Anzeigen der Konsole direkt ablesen und die Schalter bedienen kann, ohne den gedruckten Text in der Hand haben zu müssen.",al={"anleitung verloren","bedienungsanleitung gelöscht"}}},fp="32,289,28.603.0,54.215.0,22.230.0,22.209.0,34.214.0"}
P.entries["item:corroded-shrapnel"] = {n="Zerfressenes Schrapnell",s="Zerfressenes Schrapnell besteht aus gezackten Metallsplittern, die tief im Holz der verderbten Urtume des Steinkrallengebirges stecken. Geborgen aus gefallenen Beschützern wie Verkohlten und Geschwärzten Urtumen, liefert dieser Schrott den physischen Beweis für die abscheulichen Waffen, welche die Venture Company bei ihrem Rückzug einsetzte.",h="Zerfressenes Schrapnell besteht aus gezackten Metallsplittern, die tief im Holz der verderbten Urtume des...",kw={"verkohltes urtum","zerfressenes schrapnell","gaxim","kaela shadowspear","steinkrallengebirge","urtum","venture company"},ang={["class:Druid"]="Zu sehen, wie die majestätischen Urtume von Kalimdor durch industrielle Goblinmunition und schwärende Metallsplitter entstellt wurden, führt drastisch vor Augen, welchen Tribut die ungehemmte Ausbeutung der Wildnis abverlangt.",["race:Gnome"]="Gaxims Streben nach dem verseuchten Schrapnell zeigt den praktischen, wissenschaftlichen Ansatz, mit dem Gnome an ökologische Anomalien herangehen, die traditionelle Waldhüter vor ein Rätsel stellen."},sec={{t="Überreste industriellen Ruins",b="Als die Venture Company aus den Hainen des Steinkrallengebirges zurückgedrängt wurde, feuerten die Goblins brutale, rücksichtslose Munition ab, um ihre Flucht zu decken. Schrapnells dieser explosiven Waffen bohrten sich in die verteidigenden Urtume des Tals und gruben sich tief in ihre Rinde und ihr Kernholz. Statt zu heilen, verfielen die uralten Wächter langsam dem Verderben; ihr Holz schwärzte sich und ihr Zorn wandte sich gegen jeden, der das Tal betrat. Die verrosteten, verunreinigten Splitter, die aus diesen verwundeten Beschützern geborgen werden, werden von Kaela Shadowspear gesucht, damit der Gnom Gaxim Rustfizzle die genauen Mechanismen der Verderbnis analysieren kann."}},faq={{q="Woher stammt dieses Schrapnell?",a="Zerfressenes Schrapnell wird aus den Körpern verderbter Urtume im Steinkrallengebirge geborgen, darunter Verkohlte Urtume, Geschwärzte Urtume und Rachsüchtige Urtume.",al={"wo finde ich schrapnell","zerfressenes schrapnell beute","wer hinterlaesst schrapnell"}},{q="Warum steckt das Schrapnell in den Urtumen?",a="Die Venture Company feuerte explosive, gezackte Munition auf die Urtume ab, als die Waldwächter sich erhoben, um die Holzfäller der Goblins aus dem Tal zu vertreiben. Die Metallsplitter bohrten sich während des Gefechts in ihre Rinde und blieben für immer darin stecken.",al={"wie kam schrapnell in urtume","warum sind urtume voller metall"}},{q="Ist das Schrapnell für die Verderbnis der Waldurtume verantwortlich?",a="Laut Kaela Shadowspear glaubt der Gnom Gaxim, dass die Seuche, welche die Urtume heimsucht, direkt mit der üblen chemischen oder metallischen Zusammensetzung der von den fliehenden Goblins eingesetzten Waffen zusammenhängt.",al={"hat schrapnell urtume verderbt","warum sind urtume wuetend"}},{q="Wer möchte das Schrapnell untersuchen?",a="Die Nachtelfe Kaela Shadowspear bittet um eine Probe, um sie an den Gnomerfinder Gaxim weiterzuleiten, der ihre Eigenschaften untersuchen will, um das Wesen des Leidens der Urtume aufzudecken.",al={"wer braucht das schrapnell","schrapnell abgeben"}}},fp="17,302,27.617.0,35.162.0,44.225.0,63.202.0,34.189.0"}
P.entries["item:corrupt-manifestation-s-bracers"] = {n="Verderbte Manifestations-Armschienen",s="Verderbte Manifestations-Armschienen sind die physischen Überreste, die von einem verderbten Wasserelementar an der Küste des Silberwalds geborgen wurden. Von Schamanen-Initianden während der Quest „Ruf des Wassers“ erbeutet, dienen sie als wichtiger Bestandteil eines elementaren Reinigungsrituals auf dem Kohlenbecken von Everfount.",h="Verderbte Manifestations-Armschienen sind die physischen Überreste, die von einem verderbten Wasserelementar...",kw={"brazier of everfount","ruf des wassers","verderbte manifestations-armschienen","schamanenquest","silberwald","wasserelementar"},ang={["class:Shaman"]="Das Bergen und Reinigen dieser Armschienen ist die letzte Feuerprobe bei der Quest „Ruf des Wassers“, die die Macht eines Schamanen beweist, verzerrte Elemente zu beruhigen und wiederherzustellen."},sec={{t="Ein reinigendes Opfer",b="Als die Seuche der Geißel durch Lordaeron fegte, verschonte sie auch die Naturgeister des Landes nicht. Entlang der nebligen Ufer des Silberwalds westlich vom Grabmal fiel ein einst heiliger Wasserschrein dem Verderben zum Opfer und verwandelte die dort beheimatete Wassermanifestation in einen aggressiven, verdorbenen Schatten. Schamanen-Initianden werden ausgesandt, um die Kreatur zu bezwingen und ihre Armschienen zu bergen. Zusammen mit reinstem Wasser auf dem Kohlenbecken von Everfount werden diese Fesseln in die Flammen geworfen, um die Entweihung aufzuheben und einen makellosen Elementargeist herbeizurufen."}},faq={{q="Wofür werden diese Armschienen verwendet?",a="Sie werden während eines Reinigungsrituals zusammen mit Tropfen reinen Wassers auf das Kohlenbecken von Everfount gelegt. Dieser Ritus vertreibt die anhaltende Verderbnis am Schrein im Silberwald und lockt einen reinen Geist des Wassers hervor.",al={"was bewirken armschienen","ruf des wassers armschienen","verderbte armschienen nutzen"}},{q="Woher stammen die Armschienen?",a="Sie stammen aus den Überresten einer verderbten Schwachen Wassermanifestation, die sich in der Nähe eines verdorbenen Elementarschreins an der Küste des Silberwalds westlich vom Grabmal befindet.",al={"woher bekommt man armschienen","fundort verderbte manifestation"}},{q="Warum wurde das Wasserelementar verderbt?",a="Das Elementar wurde durch die Seuche und die dunklen Mächte verzerrt, die die Ländereien von Lordaeron heimsuchten, wodurch die lokalen Geister von der Zwiesprache mit den Schamanen abgeschnitten wurden.",al={"warum ist wasser verderbt","silberwald wasserverderbnis"}}},fp="31,283,20.539.0,32.208.0,31.175.0,43.152.0"}
P.entries["item:corrupted-brain-stem"] = {n="Verderbter Hirnstamm",s="Verderbte Hirnstämme sind biologische Proben, die von den entstellten Naga und Satyren gesammelt werden, welche die Blackfathom-Tiefe und die Küste von Ashenvale bewohnen. Gershala Nightwhisper aus Auberdine sucht nach ihnen, um die körperlichen Missbildungen zu erforschen, die durch rücksichtslose magische Verderbnis entstanden sind. Durch die Untersuchung dieser Gehirne hoffen nachtelfische Gelehrte zu verstehen und möglicherweise zu verhindern, dass die Blutelfen ein ähnliches Schicksal ereilt.",h="Verderbte Hirnstämme sind biologische Proben, die von den entstellten Naga und Satyren gesammelt werden...",kw={"ashenvale","auberdine","blackfathom-tiefe","verderbter hirnstamm","gershala nightwhisper","naga","erforschung der verderbnis","satyr"},ang={["faction:Alliance"]="Späher der Allianz, die nach Ashenvale entsandt wurden, trotzen den Tiefen von Blackfathom, um den Gelehrten von Auberdine dabei zu helfen, die aufkeimenden Bedrohungen in ganz Azeroth zu verstehen.",["race:NightElf"]="Für Nachtelfen ist das Sammeln dieser Überreste eine düstere Erinnerung an die tragische Geschichte ihres Volkes und an die monströsen Folgen ungezügelter arkaner und teuflischer Einmischung."},sec={{t="Anatomie der Transformation",b="Die Satyren und Naga von Kalimdor sind lebende Beweise für die verzerrende Macht verbotener Magie und dämonischer Pakte. Vor langer Zeit wurden leichtfertige Hochgeborene der Kaldorei unwiderruflich in schlangenartige Wasserbestien und dämonische, gehörnte Unholde verwandelt. Die von diesen Kreaturen gewonnenen Hirnstämme weisen schwere körperliche Mutationen auf und liefern den direkten anatomischen Beweis dafür, wie tief sich verderbende Energien in das Nervensystem einst elfischer Wesen graben."},{t="Gershalas Warnung",b="In der Küstensiedlung Auberdine beobachtet die Nachtelfe Gershala Nightwhisper die beunruhigenden Gerüchte um die Blutelfen der Östlichen Königreiche. Aus Furcht, dass deren Flirt mit dämonischer Zauberei eine weitere Generation von Monstern auf Azeroth hervorbringen könnte, beauftragt Gershala Abenteurer damit, sich in die Blackfathom-Tiefe zu wagen. Durch das Sezieren des Gewebes von Naga und Satyren hofft die Forscherin, den Pfad der magischen Degeneration nachzuzeichnen, bevor eine weitere elfische Kultur verloren geht."}},faq={{q="Welche Kreaturen hinterlassen einen Verderbten Hirnstamm?",a="Sie werden von Naga und Satyren gesammelt, die sich in der Blackfathom-Tiefe und an den umliegenden Küsten von Ashenvale aufhalten, darunter Blackfathomorakel, Meerhexen und Satyren der Fallenroot.",al={"wer droppt hirnstämme","verderbter hirnstamm beute","wo gibt es hirnstämme"}},{q="Wer benötigt diese Hirnstämme und warum?",a="Gershala Nightwhisper, die im Hafen von Auberdine an der Dunkelküste stationiert ist, erbittet sie zur Durchführung anatomischer Forschungen über magische Verderbnis.",al={"wer braucht verderbten hirnstamm","gershala quest","hirnstämme abgeben"}},{q="Was erhoffen sich die Nachtelfen von diesen Proben zu lernen?",a="Gershala fürchtet, dass der Einsatz dämonischer Magie durch die Blutelfen diese in Monster verwandeln wird, ähnlich wie die uralten Hochgeborenen zu Naga und Satyren wurden. Die Untersuchung dieser Hirnstämme hilft dabei herauszufinden, wie dämonische Energien die elfische Biologie verändern.",al={"warum naga satyr erforschen","erforschung der verderbnis lore","verbindung zu blutelfen"}},{q="Sind diese auch außerhalb der Höhlen der Blackfathom-Tiefe zu finden?",a="Ja. Bestimmte Satyren der Fallenroot und Gezeitenpriesterinnen der Blackfathom, die sich außerhalb des Höhleneingangs entlang der Küste von Ashenvale aufhalten, tragen sie ebenfalls bei sich.",al={"außerhalb von blackfathom","ashenvale hirnstämme","droppen oberflächen mobs sie"}}},fp="20,403,25.444.0,18.475.0,44.186.0,36.136.0,58.226.0,60.144.0"}
P.entries["item:corrupted-kor-gem"] = {n="Verderbter Kor-Edelstein",s="Ein Verderbter Kor-Edelstein ist ein mächtiger magischer Kanalisator, der durch die finsteren Riten der Naga rund um die Blackfathom-Tiefe verzerrt wurde. Zauberwirker begehren solche Steine wegen ihrer Fähigkeit, schiere arkane Kraft zu speichern, doch der verderbte Zustand des Edelsteins verlangt nach einer Läuterung, ehe er für rechtschaffenes Handwerk dienen kann.",h="Ein Verderbter Kor-Edelstein ist ein mächtiger magischer Kanalisator, der durch die finsteren Riten der Naga...",kw={"blackfathom-tiefe","verderbter kor-edelstein","kor-edelstein","naga","läuterung","thundris windwirker","flutpriesterin"},ang={["class:Paladin"]="Paladine, die heilige Waffen schmieden wollen, müssen einen Kor-Edelstein bergen und läutern – als Zeugnis ihrer Fähigkeit, dem Bösen entgegenzutreten und die Dunkelheit zu rechtschaffener Stärke zu wandeln.",["race:NightElf"]="Nachtelfen-Gelehrte wie Thundris Windwirker erkennen die Gefahr, die von den nach Darkshore vordringenden Naga-Relikten ausgeht, und hüten das Wissen, das zur Läuterung dieser uralten Steine erforderlich ist."},sec={{t="Gefäße verderbter Macht",b="Kor-Edelsteine besitzen von Natur aus die seltene Eigenschaft, erhebliche magische Energien aufzunehmen und einzuschließen, was sie zu unschätzbaren Foki für Zauberer und verzauberte Schmiedekunst macht. Entlang der Küste nahe den Ruinen der Blackfathom-Tiefe beanspruchen die dort ansässigen Naga-Orakel und Flutpriesterinnen diese Steine jedoch für ihre eigenen finsteren Rituale. Durch üble Verzauberungen verzerren die Schlangenwesen den Stein und durchtränken ihn mit bösartiger, aus dem Meer geborener Verderbnis. Obwohl diese Durchdringung die Natur des Edelsteins verunreinigt, bleibt die verborgene Kernkraft gewaltig, was all jene anlockt, die außergewöhnliche magische Foki benötigen und sie den Naga entreißen wollen."},{t="Läuterung und Schmiedekunst",b="Ein Verderbter Kor-Edelstein kann nicht sicher zu heiligen Rüstgütern verarbeitet werden, ohne zuvor geläutert worden zu sein. Nachtelfen-Gelehrte wie Thundris Windwirker aus Auberdine verstehen die uralten Methoden, die nötig sind, um das Verderben der Naga hinwegzufegen. Die Läuterung des Steins schmälert zwar seine unbeständige rohe Kraft bis zu einem gewissen Grad, stabilisiert ihn jedoch, sodass heilige Streiter – insbesondere Paladine, die unter der Anleitung von Handwerkern wie Jordan Stilwell gesegnete Rüstungen schmieden – den Stein nutzen können, ohne der heimtückischen Dunkelheit zu verfallen."}},faq={{q="Wofür wird ein Kor-Edelstein verwendet?",a="Kor-Edelsteine dienen als mächtige Leiter und Speicher für arkane Energie. Zauberwirker nutzen sie, um gewaltige Kraftreserven für ihre Beschwörungsformeln bereitzuhalten, während geschickte Schmiede sie in verzauberte Waffen einbetten, um magische Mächte zu kanalisieren.",al={"was sind kor-edelsteine","zweck des kor-edelsteins","kor-edelstein geschichte"}},{q="Wo sind Verderbte Kor-Edelsteine zu finden?",a="Verderbte Kor-Edelsteine werden von zauberwirkenden Naga getragen – namentlich den Flutpriesterinnen der Blackfathom und den Orakeln der Blackfathom –, die außerhalb und innerhalb der uralten Ruinen hausen, welche an der Grenze von Ashenvale und Darkshore zur Blackfathom-Tiefe führen.",al={"wo findet man verderbten kor-edelstein","kor-edelstein fundort","wer lässt kor-edelstein fallen"}},{q="Warum muss der Edelstein geläutert werden?",a="Die Naga sättigen die Steine während ihrer Rituale mit übler Magie. Der Versuch, einen verderbten Edelstein für heiliges Handwerk zu verwenden, könnte die Schmiede oder den Träger verderben, weshalb ein Meister der Natur oder des Lichts wie Thundris Windwirker das Böse austreiben muss, bevor er zu einer Waffe verarbeitet wird.",al={"kor-edelstein reinigen","warum kor-edelstein läutern","ist der edelstein böse"}},{q="Schwächt die Reinigung des Edelsteins seine Macht?",a="Ja. Das Entfernen des Naga-Verderbens tilgt die wilde, bösartige Energie, die den Edelstein aufblähte, wodurch der Stein insgesamt etwas schwächer wird. Die verbleibende Restenergie ist jedoch rein, stabil und stark genug für geweihte Schmiedearbeiten.",al={"zerstört läuterung den edelstein","schwächer nach läuterung"}}},fp="17,288,24.601.0,25.484.1,27.238.0,35.236.0,29.280.0,40.227.0"}
P.entries["item:cougar-claws"] = {n="Pumaklauen",s="Pumaklauen werden von Flachlandcougars erbeutet, die die zentralen Ebenen von Mulgore durchstreifen. Sie dienen als unverzichtbares Material im Ritualhandwerk der Tauren und verkörpern das ungezähmte Gleichgewicht sowie die natürliche Wildheit der Raubtiere der Wildnis.",h="Pumaklauen werden von Flachlandcougars erbeutet, die die zentralen Ebenen von Mulgore durchstreifen.",kw={"säuberungstotem","pumaklauen","flachlandcougar","mulgore","mull thunderhorn","thunderhorn-totem"},ang={["class:Shaman"]="Schamanen erkennen, dass die Essenz einheimischer Raubtiere eine ungebrochene Verbindung zu den Geistern der Ebenen birgt, was sie zu unverzichtbaren Leitern für reinigende Schutzzauber und Säuberungstotems macht.",["race:Tauren"]="Das Sammeln dieser Klauen lehrt junge Tauren, dass die Jagd im Gleichgewicht und in spiritueller Notwendigkeit verwurzelt ist – im krassen Gegensatz zur rücksichtslosen Verschmutzung durch goblinische Unternehmungen."},sec={{t="Ein Gefäß des natürlichen Gleichgewichts",b="Der Flachlandcougar ist einer der Spitzenjäger in Mulgores weitläufigen Grasländern, der seiner Beute mit instinktiver Anmut nachstellt. In der Tradition der Tauren ist das Nehmen der Klauen eines solchen Raubtiers kein beiläufiges Abschlachten oder eine Trophäenjagd, sondern ein Weg, den natürlichen Geist der Bestie nutzbar zu machen. Als goblinische Machenschaften beginnen, die uralten Wasser der Ebenen zu entweihen, ruft Mull Thunderhorn junge Jäger dazu auf, diese Klauen zusammen mit jenen von Präriepirschern zu sammeln. Die Tauren glauben, dass die reinen, unberührten Raubtierinstinkte einheimischer Bestien in ein Ritualtotem eingewoben werden können, das imstande ist, unnatürliche Giftstoffe und üble Zauberei aus dem vergifteten Wasserbrunnen von Thunderhorn zu tilgen."}},faq={{q="Wofür werden Pumaklauen verwendet?",a="Mull Thunderhorn verwendet sie zusammen mit Pirscherklauen, um das Säuberungstotem von Thunderhorn herzustellen. Die Tauren weben den reinen Geist einheimischer Raubtiere in Ritualgegenstände ein, um Wasserbrunnen zu reinigen, die durch goblinische Industrieunternehmungen vergiftet wurden.",al={"pumaklauen verwendung","warum pumaklauen sammeln","zweck von pumaklauen"}},{q="Woher stammen Pumaklauen?",a="Sie werden von Flachlandcougars erbeutet, die die wogenden Ebenen von Mulgore durchstreifen, vor allem östlich und westlich von Bloodhoof.",al={"wo gibt es pumaklauen","pumaklauen herkunft","wer lässt pumaklauen fallen"}},{q="Warum benötigt Mull Thunderhorn Raubtierklauen, um einen Brunnen zu reinigen?",a="Schamanische und druidische Traditionen der Tauren verehren die Reinheit, mit der wilde Bestien jagen. Anders als die Goblins, die die Erde ausbeuten und entweihen, leben einheimische Raubtiere in vollkommenem Einklang mit dem Land, was ihre Essenz ideal macht, um künstlicher Verderbnis entgegenzuwirken.",al={"warum raubtierklauen","mull klauen grund","totem raubtierklauen"}},{q="Sind Pumaklauen noch für etwas anderes nützlich?",a="Abgesehen von der Herstellung des Ritualtotems für den Wasserbrunnen von Thunderhorn haben sie keinen besonderen Nutzen und werden üblicherweise an örtliche Händler verkauft.",al={"weitere verwendung pumaklauen","pumaklauen verkaufen"}}},fp="12,218,27.670.0,31.228.0,32.128.0,64.259.0,42.138.0"}
P.entries["item:courser-eye"] = {n="Rennerauge",s="Renneraugen sind biologische Reagenzien, die von den gehörnten Rennern erbeutet werden, welche das Hochland im Steinkrallengebirge durchstreifen. Hexendoktor Jin'Zil in Malaka'jin benötigt eine große Menge davon, um ein Gebräu zuzubereiten, das er spöttisch als Waldmagie bezeichnet.",h="Renneraugen sind biologische Reagenzien, die von den gehörnten Rennern erbeutet werden, welche das Hochland...",kw={"antlered courser","rennerauge","waldmagie","great courser","jin'zil","malaka'jin","steinkrallengebirge"},ang={["race:NightElf"]="Das Abschlachten der heiligen Renner von Stonetalon, nur um gefangene Schildwachen zu vergiften, gilt als ein schwerer Frevel gegen Elune und die Natur.",["race:Troll"]="Hexendoktor Jin'Zils rohe Verwendung tierischer Komponenten spiegelt die dunklere, pragmatische Seite der Trollalchemie und Mojo-Zauberei wider, die gegen Feinde der Horde eingesetzt wird."},sec={{t="Das Gebräu eines Trolls",b="Im abgelegenen Außenposten Malaka'jin braut Hexendoktor Jin'Zil verschiedene Stammesmischungen zusammen, um mit den Nachtelfen fertigzuwerden, die die Region streitig machen. Obwohl Hirschaugen keine ungewöhnliche Zutat im Voodoo und in der Volksalchemie sind, verlangt Jin'Zil dreißig Renneraugen auf einmal – weit mehr, als die typische Zauberkunst erfordert. Vermischt mit Schuppen von Feendrachen, Baumharz und Katzenschnurrhaaren dienen die Augen als Basis für ein tödliches Gebräu, das für die gefangenen Nachtelfen bestimmt ist, die in Käfigen hinten in seiner Höhle eingesperrt sind."}},faq={{q="Wo findet man Renneraugen?",a="Sie werden von den verschiedenen Rennern erbeutet – sowohl Antlered Coursers als auch Great Coursers –, die in den höheren Lagen des Steinkrallengebirges heimisch sind, insbesondere rund um den Mirkfallonsee und Der Steinkrallengipfel.",al={"rennerauge fundorte","wo gibt es rennerauge","wie bekommt man rennerauge"}},{q="Warum braucht Hexendoktor Jin'Zil so viele Augen?",a="Jin'Zil behauptet, dass man nie genug Augen haben kann, wenn man ein ordentliches Gebräu ansetzt. Er kombiniert sie mit Teilen der einheimischen Fauna, um ein starkes Gebräu herzustellen, das er auf seine gefangenen Nachtelfen loslässt.",al={"warum 30 augen","warum braucht jinzil augen","was macht jinzil mit renneraugen"}},{q="Was passiert, wenn Jin'Zil seinen Waldmagietrank vollendet?",a="Sobald die Renneraugen und die anderen Zutaten abgeliefert sind, setzt Jin'Zil das giftige Gebräu in seiner Höhle frei. Die Mixtur vergiftet die gefangenen Nachtelfen tödlich, deren Geister als Irrwische aufsteigen und in die Wildnis entschwinden.",al={"jinzil waldmagie ergebnis","was passiert mit den gefangenen in malakajin"}}},fp="11,250,20.483.1,29.207.0,48.206.1,60.224.1"}
P.entries["item:covert-ops-pack"] = {n="Geheimdienstpack",s="Das Geheimdienstpack ist ein Ausrüstungssatz mit spezieller Sprengausrüstung und Einsatzplänen, der für die Spionage der Allianz im Steinkrallengebirge zusammengestellt wurde. Die Tasche wurde entwickelt, um die unersättliche Präsenz der Venture Company in Der Scherwindklippe zu zerschlagen, und rüstet Agenten dafür aus, koordinierte Sabotageakte zu verüben und gleichzeitig hochkarätige technische Geheimdienstinformationen zu beschaffen.",h="Das Geheimdienstpack ist ein Ausrüstungssatz mit spezieller Sprengausrüstung und Einsatzplänen, der für die...",kw={"geheimdienstpack","felskesselsee","ng-5 sprengstoffe","plan alpha","plan beta","venture company","die scherwindklippe"},ang={["faction:Alliance"]="Die mit diesem Pack koordinierte verdeckte Operation unterstützt unmittelbar den Kampf der Schildwachen gegen die kommerzielle Verwüstung im Steinkrallengebirge.",["profession:Engineering"]="Das Pack verkörpert feinsten Gnomen-Erfindungsgeist, der gegen die Goblin-Industrie gewandt wird, indem maßgeschneiderte NG-5-Ladungen genutzt werden, um die Geheimnisse hinter den Maschinen der Venture Company zu lüften."},sec={{t="Sabotage nach Plan",b="Das Geheimdienstpack wird für verdeckte Schläge tief im Territorium der Venture Company ausgegeben und verbindet rohe Zerstörungskraft mit taktischer Präzision. Darin befinden sich farblich gekennzeichnete NG-5-Sprengstoffe samt passenden Fernzündern sowie ausführliche Anweisungen namens Plan Alpha und Plan Beta. Die Strategie setzt darauf, an zentralen Infrastrukturknotenpunkten – namentlich dem Sägewerk am Felskesselsee und der östlichen Mine – gewaltige Ablenkungen auszulösen. Während die Goblins herbeieilen, um Brände zu löschen und Maschinenausfälle zu begutachten, schleicht ein Infiltrator am Chaos vorbei, um wichtige Dokumente und Pläne zu entwenden."},{t="Ein Zusammenfluss von Interessen",b="Der Inhalt des Packs dient der Allianz im Steinkrallengebirge einem doppelten Zweck. Für die Schildwachen der Nachtelfen stören die Explosionen und der Diebstahl das erbarmungslose Abholzen und Aufreißen des heiligen Berghangs. Für die Tüftler der Allianz liegt die Hauptbelohnung in den Dokumenten selbst. Die Erbeutung der Konstruktionspläne der Venture Company gewährt seltene Einblicke in goblinische Schwermaschinen, offenbart mechanische Schwachstellen und ermöglicht es den Ingenieuren der Allianz, industrielle Neuerungen in ihre eigenen Entwürfe zu übernehmen."}},faq={{q="Was befindet sich im Geheimdienstpack?",a="Das Pack enthält zwei Paare farbiger Sprengladungen: rote und blaue NG-5-Sprengstoffe samt den passenden Fernzündern. Außerdem enthält es schriftliche Einsatzbesprechungen mit Einzelheiten zu Plan Alpha und Plan Beta.",al={"geheimdienstpack inhalt","was enthält das pack","gegenstände im geheimdienstpack"}},{q="Was ist der taktische Zweck der Sprengstoffe?",a="Die NG-5-Sprengstoffe werden an den Arbeitsstätten der Venture Company platziert, um laute, heftige Ablenkungen zu erzeugen. Sie sind nicht das eigentliche Endziel, sondern sollen das Wachpersonal weglocken, damit ein Agent unentdeckt in das Sägewerk und die Mine eindringen kann.",al={"warum bomben benutzen","wofür sind ng-5 sprengstoffe","alpha beta sprengung"}},{q="Auf welche Informationen zielt diese Operation ab?",a="Die Mission zielt auf Konstruktionspläne der Venture Company aus dem Sägewerk südlich des Felskesselsees ab, gefolgt von Geschäftsbriefen, die in der Scherwindmine am östlichen Ende der Klippe aufbewahrt werden.",al={"was stehlen wir","pack missionsziel","geheimdienst ziele"}},{q="Wer profitiert von den mit diesem Pack geborgenen Materialien?",a="Sowohl die Schildwachen der Nachtelfen, die das Steinkrallengebirge bewachen, als auch die Ingenieure der Allianz profitieren davon. Die Schildwachen erleben, wie die Abholzung gelähmt wird, während die Konstrukteure der Allianz die erbeuteten Pläne studieren, um Schwachstellen an den Schreddern der Venture Company aufzudecken und Anregungen für ihre eigene Technologie zu gewinnen.",al={"wer will die venture pläne","für wen ist das pack","schildwachen geheimdienst"}}},fp="15,339,18.584.0,25.515.0,35.202.0,47.250.0,45.191.0,58.280.0"}
P.entries["item:crate-of-crash-helmets"] = {n="Kiste mit Sturzhelmen",s="Eine schwere Nachschublieferung zwergischer Belagerungsmaschinen-Kopfbedeckungen, bestimmt für die Schimmernde Ebene in Tausend Nadeln. Die robusten Helme werden von den Brüdern Brassbolt dringend benötigt, um Testpiloten vor Gehirnerschütterungen zu schützen, die durch ihre experimentellen Raketenwagen verursacht werden.",h="Eine schwere Nachschublieferung zwergischer Belagerungsmaschinen-Kopfbedeckungen, bestimmt für die...",kw={"kiste mit sturzhelmen","illusionenrennbahn","raketenwagen","die schimmernde ebene","belagerungsmaschine","tausend nadeln","wizzle brassbolts"},ang={["profession:Engineering"]="Jeder Ingenieur versteht das heikle Gleichgewicht zwischen maximalem Antrieb und katastrophalem Versagen – und die absolute Notwendigkeit schwerer Rüstung, wenn Sicherheitsvorkehrungen nur ein nachträglicher Gedanke sind.",["race:Gnome"]="Für Gnome auf der Illusionenrennbahn sind Gehirnerschütterungen der Piloten schlicht die Kosten des Geschäfts, wenn man Goblinrivalen auf der Salzebene technisch übertrumpfen will."},sec={{t="Sicherheit bei hohen Geschwindigkeiten",b="Draußen auf der blendend weißen Weite der Schimmernden Ebene testen Gnomeningenieure die absoluten Grenzen des mechanischen Antriebs aus. Zum Unglück für die Testpiloten bewegen sich die von den Brüdern Brassbolt entworfenen experimentellen Raketenwagen viel schneller, als ihre Lenkung zuverlässig bewältigen kann. Da die Fahrer regelmäßig schwere Unfälle und Schädeltraumata erleiden, genügen gewöhnliche Lederkappen nicht mehr. Um zu verhindern, dass ihre Riege williger Waghalsiger gänzlich dahinscheidet, werden strapazierfähige zwergische Helme für Belagerungsmaschinen verpackt und über das Meer verschickt, damit die Fahrer bei Bewusstsein – und am Leben – bleiben."}},faq={{q="Was befindet sich in der Kiste mit Sturzhelmen?",a="Die Kiste enthält schwere Helme für Belagerungsmaschinen aus Beständen des zwergischen Militärs. Gefertigt, um Erschütterungsexplosionen und heftigen Fahrzeugaufprallen standzuhalten, bieten sie den stärksten verfügbaren Kopfschutz für Hochgeschwindigkeitstests.",al={"inhalt der kiste","welche helme sind das","sturzhelmart"}},{q="Wer benötigt diese Helme?",a="Sie werden zu Wizzle Brassbolts und seinem Bruder hinaus an die Illusionenrennbahn in der Schimmernden Ebene geschickt. Ihre waghalsigen Fahrzeugkonstruktionen schlagen Testpiloten wiederholt bewusstlos, was einen akuten Bedarf an ernsthaftem Kopfschutz schafft.",al={"wer bekommt die helme","für wen ist die kiste","ziel der helme"}},{q="Warum verunglücken die Brüder Brassbolt so oft?",a="Gnomisches Fahrzeugdesign stellt schiere Geschwindigkeit und das Ausreizen technologischer Grenzen über stabiles Fahrverhalten. Die Brüder bauten einen außergewöhnlich schnellen Raketenwagen, doch seine pure Geschwindigkeit macht Kollisionen auf der Salzebene fast unvermeidlich.",al={"warum verunglücken sie","raketenwagen probleme","gnomenrennen unfälle"}},{q="Wohin werden die Helme geliefert?",a="Die Lieferung muss in die Schimmernde Ebene gebracht werden, die riesige Salzebene im südöstlichen Bereich von Tausend Nadeln in Kalimdor.",al={"lieferort","wo ist wizzle","wohin gehört das"}}},fp="22,262,21.584.0,42.227.0,24.218.0,49.232.0,38.147.0"}
P.entries["item:crate-of-horseshoes"] = {n="Kiste mit Hufeisen",s="Die Kiste mit Hufeisen ist ein schweres Lieferpaket, das fünfzig im Wald von Elwynn geschmiedete Eisenhufeisen enthält. Bestimmt für Seenhain, stellt sie die lebenswichtige Handelsverbindung zwischen Goldhains Schmiede und den bedrängten Siedlern des Rotkammgebirges dar.",h="Die Kiste mit Hufeisen ist ein schweres Lieferpaket, das fünfzig im Wald von Elwynn geschmiedete...",kw={"kiste mit hufeisen","wald von elwynn","goldhain","seenhain","rotkammgebirge","schmied argus","verner osgood"},ang={["faction:Alliance"]="Kuriere, die Waren zwischen Elwynn und dem Rotkammgebirge transportieren, halten das fragile Handelsrückgrat des Königreichs aufrecht und versorgen entlegene Garnisonen, selbst während Stormwind militärische Verstärkung zurückhält.",["profession:Blacksmithing"]="Die Lieferung verdeutlicht die stetige Nachfrage nach einfachen Massenschmiedewaren entlang der Grenzstraßen des Königreichs, wo Orte wie Seenhain für die Instandhaltung ihrer Zugtiere vollständig vom Amboss in Goldhain abhängig sind."},sec={{t="Eine Lieferung nach Seenhain",b="Vom Hufschmied Schmied Argus in Goldhain gepackt und zugeschlagen, enthält diese wuchtige Kiste fünfzig frisch geschmiedete Hufeisen, die von Verner Osgood in Auftrag gegeben wurden. Die lokale Industrie von Seenhain leidet unter dem ständigen Druck der umliegenden Gnolle und Orcs, weshalb Handwerker wie Verner für lebensnotwendige Metallwaren auf den Wald von Elwynn angewiesen sind. Obwohl die Kiste Verners verzweifelten Bedarf an Ausrüstung deckt, legt Argus gewissenhaft eine strenge Rechnung bei, damit der Handwerker im Rotkammgebirge nicht vergisst, dass selbst das Überleben an der Grenze seinen stolzen Preis hat."}},faq={{q="Was befindet sich in der Kiste mit Hufeisen?",a="Die Kiste enthält fünfzig von Schmied Argus in Goldhain geschmiedete Eisenhufeisen sowie eine beiliegende Rechnung mit Zahlungsaufforderung an den Käufer.",al={"inhalt der kiste","was ist in der kiste","inhalt hufeisenkiste"}},{q="Wer hat diese Kiste bestellt?",a="Verner Osgood, ein in Seenhain im Rotkammgebirge ansässiger Händler und Handwerker, gab die Hufeisen in Auftrag, um seine Arbeit und die örtlichen Zugtiere einsatzbereit zu halten.",al={"wer will die hufeisen","verner hufeisen","empfaenger der kiste"}},{q="Wer hat diese Hufeisen hergestellt?",a="Schmied Argus, der ansässige Schmied von Goldhain im Wald von Elwynn, hat die Hufeisen geschmiedet und die Kiste für die Lieferung verpackt.",al={"wer hat die hufeisen gemacht","schmied in goldhain","schmied argus"}},{q="Warum benötigt Verner Hufeisen aus Elwynn?",a="Seenhain wird von feindseligen Blackrock-Orcs und Gnollen belagert, wodurch die Grenzsiedlung isoliert ist und unter einem Mangel an Rohstoffen sowie Handelsgütern leidet. Die örtlichen Arbeiter müssen grundlegende Versorgungsgüter aus sichereren Siedlungen wie Goldhain einführen.",al={"warum rotkamm hufeisen braucht","warum hufeisen importieren","seenhain versorgungsproblem"}}},fp="19,232,23.543.0,39.138.0,23.172.0,29.125.0,44.228.0"}
P.entries["item:crate-of-inn-supplies"] = {n="Kiste mit Gasthausvorräten",s="Die Kiste mit Gasthausvorräten ist ein im Coldridgetal gepacktes Paket, das für die Brauerei Donnerbräu in Kharanos bestimmt ist. Da der Gebirgspass von Troggs überrannt wurde, sind die regulären Nachschubwege unterbrochen, sodass das Gasthaus darauf angewiesen ist, dass durchreisende Wanderer die Waren transportieren.",h="Die Kiste mit Gasthausvorräten ist ein im Coldridgetal gepacktes Paket, das für die Brauerei Donnerbräu in...",kw={"anvilmar","coldridge","kiste","frosthammer","hands","kharanos","springsprocket","vorräte","tannok","troggs"},ang={["race:Dwarf"]="Das Transportieren dieser Vorräte markiert für einen jungen Zwerg den ersten Dienst außerhalb des Coldridgetals, bei dem er dem von Troggs verstopften Pass trotzt, um seinen Verwandten in Kharanos beizustehen.",["race:Gnome"]="Für neu eingetroffene Gnome ist das Tragen von Hands Springsprockets Paket eine praktische Gelegenheit, sich das Wohlwollen der einheimischen Zwerge zu verdienen, die die Gasthäuser von Dun Morogh führen."},sec={{t="Durch den Troggpass",b="Normalerweise fließen Waren reibungslos zwischen den ruhigen Übungsplätzen von Anvilmar und den geschäftigen Ortschaften von Dun Morogh. Jüngste Troggeinfälle haben jedoch den Coldridgepass abgeschnitten, wodurch zivile Kuriere festsitzen, bis bewaffnete Eskorten der Gebirgsjäger die Straßen räumen können. Diese von Hands Springsprocket gepackte, schwere Kiste enthält wichtige Tavernenvorräte, auf die Tannok Frosthammer in Kharanos angesichts der Störung schon ungeduldig wartet."}},faq={{q="Was befindet sich in der Kiste?",a="Die Kiste enthält allgemeine Tavernenvorräte, die aus dem Coldridgetal verschickt wurden, damit das Gasthaus in Kharanos für Reisende und Einheimische auf der Suche nach Wärme gut versorgt bleibt.",al={"inhalt der kiste","gasthausvorräte inhalt","was ist in der kiste"}},{q="Wer schickt die Kiste nach Kharanos?",a="Hands Springsprocket, der in der Nähe von Anvilmar stationiert ist, packt die Kiste und bittet Abenteurer, die das Coldridgetal verlassen, sie über den Gebirgspass zu tragen.",al={"wer vergibt die kiste","hands springsprocket","absender"}},{q="Warum konnte der normale Kurier sie nicht liefern?",a="Troggs haben den Coldridgepass überrannt, was das Reisen für reguläre Kuriere ohne vollständige Eskorte von Gebirgsjägern zu gefährlich macht. Abenteurer, die geübt genug sind, um sich den Weg freizukämpfen, sind die einzige unmittelbare Hoffnung des Gasthauses, die Waren zu erhalten.",al={"warum hands nicht selbst liefert","pass blockiert","warum ein abenteurer"}},{q="Wer nimmt die Vorräte in Empfang?",a="Tannok Frosthammer, der Gehilfe des Gastwirts in der Brauerei Donnerbräu in Kharanos, nimmt die Lieferung des Pakets entgegen.",al={"wer erhält die kiste","tannok frosthammer","gastwirt in kharanos"}}},fp="21,261,22.431.0,25.157.0,32.156.0,43.232.0,26.118.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="Kiste mit Lichtschmiedeblöcken",s="Die Kiste mit Lichtschmiedeblöcken enthält seltenes geweihtes Metall, das geborgen wurde, um ein Werkzeug zu schmieden, das den Nekromanten Morbent Fel besiegen kann. Sicher für den Transport verpackt, ist sie für die Ambosse im Dwarven District in Stormwind bestimmt.",h="Die Kiste mit Lichtschmiedeblöcken enthält seltenes geweihtes Metall, das geborgen wurde, um ein Werkzeug zu...",kw={"kiste","dwarven district","grimand elmore","barren","eisen","lichtgeschmiedet","morbent fel","stormwind"},ang={["class:Paladin"]="Diese Barren sind für das Heilige Licht außergewöhnlich empfänglich, wodurch daraus geschmiedete Waffen zu einer natürlichen Geißel für Nekromanten und ihre untoten Diener werden.",["profession:Blacksmithing"]="Die Arbeit mit lichtgeschmiedetem Eisen ist eine seltene Kunst; selbst erfahrene Waffenschmiede wie Grimand Elmore bekommen jahrelang kein solch klangvolles, heiliges Metall in die Finger."},sec={{t="Eine heilige Lieferung",b="Lichtgeschmiedetes Eisen ist ein außergewöhnlich seltenes Material, das von Natur aus dazu geeignet ist, heilige Macht gegen dunkle Wesenheiten zu kanalisieren. Sicher in dieser Kiste verstaut, verkörpern die Barren die Hoffnung des Dämmerwalds in seinem erbitterten Kampf gegen den Nekromanten Morbent Fel, an dessen schattenhaftem Schutz gewöhnlicher Stahl wirkungslos abprallt. Gewöhnliche Schmiede können nicht einfach mit diesem Metall arbeiten; es bedarf eines Handwerkers, der seine Eigenheiten versteht und seine heilige Natur respektiert."},{t="Der Waffenschmied von Stormwind",b="Die Kiste ist für Grimand Elmore bestimmt, einen geschickten Zwergenwaffenschmied, der sein Handwerk im Dwarven District von Stormwind ausübt. Da er seit Jahren nicht mehr mit lichtgeschmiedetem Eisen gearbeitet hat, willigt Grimand ein, das Metall zu einer geweihten Waffe zu schmieden – einem Rüstzeug, das mit der Kraft erfüllt ist, die nötig ist, um Morbent Fels Verteidigung zu zerschmettern und ihn niederzustrecken."}},faq={{q="Was befindet sich in dieser Kiste?",a="Die Kiste enthält Barren aus lichtgeschmiedetem Eisen, einem besonderen geweihten Metall, das gesammelt wurde, um eine Waffe herzustellen, die eigens dafür bestimmt ist, die magischen Schutzschilde des Nekromanten Morbent Fel zu durchdringen.",al={"kisteninhalt","was ist lichtgeschmiedetes eisen","was ist in der kiste"}},{q="Wer soll diese Kiste erhalten?",a="Die Kiste muss zu Grimand Elmore gebracht werden, einem erfahrenen Zwergenschmied bei den Ambossen im Dwarven District in Stormwind.",al={"zu wem bringe ich die kiste","empfänger der kiste","wohin gehört die kiste"}},{q="Warum wird lichtgeschmiedetes Eisen benötigt?",a="Der Nekromant Morbent Fel schirmt sich mit abscheulicher unheiliger Magie ab, an der herkömmliche Klingen abprallen. Lichtgeschmiedetes Eisen besitzt heilige Eigenschaften, die dunkle Zauberei durchdringen können.",al={"warum lichtgeschmiedetes eisen","warum kein normales eisen","morbent fel schwäche"}},{q="Wer hat die Kiste angefertigt?",a="Glorin Steelbrow hat das von Euch geborgene lichtgeschmiedete Eisen in die Kiste gepackt, damit Ihr es dem Meisterwaffenschmied Grimand Elmore in Stormwind überbringen könnt.",al={"wer packte die barren ein","wer gab die kiste"}}},fp="26,244,17.434.0,28.328.1,26.182.0,38.129.0,30.177.0,22.151.0"}
P.entries["item:crate-with-holes"] = {n="Kiste mit Löchern",s="Ein tragbarer Transportbehälter, der vom Goblin-Unternehmer Mebok Mizzyrix in Ratchet bereitgestellt wird. Mit Luftlöchern versehen, beherbergt er sicher einen abgerichteten Schnüffelnasengopher, der dazu dient, unterirdische kulinarische Köstlichkeiten in der Stacheleberfestung des Krals von Razorfen aufzuspüren.",h="Ein tragbarer Transportbehälter, der vom Goblin-Unternehmer Mebok Mizzyrix in Ratchet bereitgestellt wird.",kw={"blaulaubknollen","kiste mit löchern","mebok mizzyrix","ratchet","der kral von razorfen","schnüffelnasengopher"},sec={{t="Ein Schnüffler in der Kiste",b="Um an seltene Blaulaubknollen aus den dornigen Tiefen des Krals von Razorfen zu gelangen, verlässt sich der Goblinhändler Mebok Mizzyrix auf abgerichtete Schnüffelnasengopher statt auf blindes Graben. Da Gopher einem Abenteurer nicht einfach zu Fuß über die staubigen Pfade des Brachlands folgen können, packt Mebok jedes Tierchen in eine gut belüftete Holzkiste. Sobald sie in die feuchten, wurzelüberwucherten Gänge des Stacheleberbaus gebracht wurde, wird die Kiste entriegelt, sodass die Bestie im Inneren ihrem feinen Geruchssinn zu den vergrabenen Knollen folgen kann."}},faq={{q="Was befindet sich in der Kiste mit Löchern?",a="Die Kiste enthält einen lebendigen Schnüffelnasengopher, der von Mebok Mizzyrix abgerichtet wurde. Die in das Holz gebohrten Löcher ermöglichen es der Kreatur, während des Transports durch das Brachland zu atmen.",al={"was ist in der kiste","kisteninhalt","was ist drin"}},{q="Wo erhalte ich die Kiste mit Löchern?",a="Ihr könnt eine Kiste direkt von dem Stapel nehmen, der neben Mebok Mizzyrix in der Hafenstadt Ratchet an der Ostküste des Brachlands steht.",al={"kistenfundort","wo findet man die kiste mit löchern","meboks kiste"}},{q="Wie funktioniert die Kiste im Kral von Razorfen?",a="Das Öffnen der Kiste im Kral von Razorfen lässt den Schnüffelnasengopher frei. Wenn er mit einem Schnüffelnasenleitstecken angeleitet wird, nutzt der Gopher seine feine Nase, um unter der Erde verborgene Blaulaubknollen aufzuspüren.",al={"wie benutzt man die kiste mit löchern","kiste benutzen","gopher beschwören"}},{q="Warum sind Blaulaubknollen ohne den Gopher so schwer zu finden?",a="Blaulaubknollen wachsen tief unter der Erde in den Wurzelgeflechten des Krals von Razorfen. Sie sind für das gewöhnliche Auge unsichtbar, doch Schnüffelnasengopher können sie aus fünfzig Schritt Entfernung wittern.",al={"warum gopher benötigt","knollen finden","knollenfundort"}}},fp="16,265,18.509.0,36.170.0,36.153.0,46.216.0,59.181.0"}
P.entries["item:crawler-leg"] = {n="Kriecherbein",s="Ein Kriecherbein ist ein erbeutetes Gliedmaß der verschiedenen Krabben, die an der nebelverhangenen Küste der Darkshore lauern. Obwohl sie für die meisten Reisenden wertlos sind, eignen sich diese widerstandsfähigen, chitinösen Gliedmaßen überraschend gut für mechanische Improvisationen.",h="Ein Kriecherbein ist ein erbeutetes Gliedmaß der verschiedenen Krabben, die an der nebelverhangenen Küste der...",kw={"auberdine","dröhnkiste 827","kriecherbein","darkshore","reef crawler","tide crawler","wizbang cranktoggle"},ang={["profession:Engineering"]="Wizbang Cranktoggles Entscheidung, Krabbengliedmaßen als behelfsmäßige mechanische Hebel zu verwenden, spiegelt die klassische gnomische Feldimprovisation wider, bei der auf herkömmliche Metallgestänge verzichtet und stattdessen auf sofort verfügbare lokale Ressourcen zurückgegriffen wird.",["race:Gnome"]="Nur ein Gnom würde einen von aggressiven Krustentieren wimmelnden Strand sehen und zu dem Schluss kommen, dass deren abgetrennte Beine die idealen Ersatzteile für ein empfindliches Fernmeldetelekommunikationsnetzwerk sind."},sec={{t="Gnomischer Erfindergeist an der Küste",b="Die Krabben der Darkshore – von Zwerggezeitenkriechern bis hin zu größeren Riffkriechern – sind für ihre robusten, widerstandsfähigen Panzer bekannt. Während Nachtelfenschildwachen den abgetrennten Gliedmaßen des Küstengeziefers kaum Beachtung schenken, fand der exzentrische Gnomen-Ingenieur Wizbang Cranktoggle eine unerwartete Verwendung für sie. Von Auberdine aus entwarf Wizbang seine Prototypen von Fernkommunikationsgeräten, bekannt als Dröhnkisten, die mit improvisierten lokalen Komponenten betrieben werden sollten. Die segmentierten Gelenke und das strapazierfähige Chitin der Kriecherbeine liefern genau die mechanische Reibung und Hebelwirkung, die für die Reparatur von Dröhnkiste 827 erforderlich sind, welche sich an der Küste südlich der Stadt befindet."}},faq={{q="Wofür werden Kriecherbeine verwendet?",a="Kriecherbeine werden gesammelt, um Dröhnkiste 827 zu reparieren, eine experimentelle Kommunikationsstation, die vom Gnomen-Erfinder Wizbang Cranktoggle an der Küste der Darkshore südlich von Auberdine aufgestellt wurde.",al={"kriecherbein verwendung","warum kriecherbeine behalten","dröhnkiste kriecherbein"}},{q="Woher stammen Kriecherbeine?",a="Sie können von verschiedenen Krabbenarten an den Stränden der Darkshore erbeutet werden, darunter Pygmy Tide Crawlers, Young Reef Crawlers, Encrusted Tide Crawlers und Reef Crawlers.",al={"kriecherbein herkunft","welche krabben lassen kriecherbeine fallen","wo kriecherbein finden"}},{q="Warum benötigt eine mechanische Dröhnkiste Krabbenbeine?",a="Wizbang Cranktoggle konstruierte seine Maschinen bewusst so, dass Teile der heimischen Tierwelt für die laufende Wartung im Feld genutzt werden können. Die starren Gelenke und chitinösen Segmente der Kriecherbeine fügen sich direkt in die mahlenden Zahnräder der Dröhnkiste ein, um deren innere Mechanismen wiederherzustellen.",al={"warum krabben für maschine","dröhnkiste krabbenbeine lore","wie repariert kriecherbein dröhnkiste"}}},fp="11,231,30.641.0,31.191.0,32.179.0,45.270.0"}
P.entries["item:creeper-ichor"] = {n="Krabblersekret",s="Krabblersekret ist eine seltene, bösartige Flüssigkeit, die von den Mooskrabblern geerntet wird, die in den Wäldern des Vorgebirges von Hillsbrad lauern. Sie wird von der Königlichen Apothekervereinigung in Tarrens Mühle als wirksames biologisches Kampfmittel für die Entwicklung neuartiger Seuchen gegen die Lebenden gesucht.",h="Krabblersekret ist eine seltene, bösartige Flüssigkeit, die von den Mooskrabblern geerntet wird, die in den...",kw={"apotheker lydon","krabblersekret","creepthess","elixier des leidens","vorgebirge von hillsbrad","mooskrabbler","tarrens mühle"},ang={["race:Undead"]="Für Getreue der Verlassenen treibt die Beschaffung tödlicher Komponenten wie Krabblersekret den Feldzug der Königlichen Apothekervereinigung direkt voran, um die Lebenden aus Lordaeron zu tilgen."},sec={{t="Apothekerforschung in Hillsbrad",b="In Tarrens Mühle führt Apotheker Lydon Experimente durch, um tödliche neue Toxine herzustellen, mit dem Ziel, die umliegende menschliche Bevölkerung auszurotten. Lydon, der die reine Luft und das blühende Leben des Vorgebirges verabscheut, sucht nach natürlichen Toxinen und biologischen Katalysatoren, die der heimischen Tierwelt entstammen. Die giftigen Sekrete der riesigen Spinnentiere des Waldes, insbesondere das schwer zu findende Sekret ausgewachsener Mooskrabbler, dienen als ideale Basis für sein Elixier des Leidens. Vermengt mit anderen Reagenzien wie Graubärenzungen hilft diese Flüssigkeit den Verlassenen dabei, ihr Handwerk der tödlichen Alchemie zu perfektionieren."}},faq={{q="Welche Kreaturen liefern Krabblersekret?",a="Die Flüssigkeit wird von Mooskrabblern gewonnen, die das Vorgebirge von Hillsbrad bewohnen, darunter Giant Moss Creepers, Forest Moss Creepers, Elder Moss Creepers und das bemerkenswerte Spinnentier Creepthess.",al={"wo man krabblersekret bekommt","was krabblersekret fallen lässt","krabblersekret mobs"}},{q="Warum benötigt Apotheker Lydon diese Flüssigkeit?",a="Apotheker Lydon nutzt Krabblersekret als entscheidenden tödlichen Wirkstoff in seiner laufenden alchemistischen Forschung zum Brauen des Elixiers des Leidens, das darauf ausgelegt ist, die lebenden Menschen in Hillsbrad mit Seuchen zu überziehen und zu vernichten.",al={"warum lydon sekret will","elixier des leidens zweck","wofür krabblersekret verwendet wird"}},{q="Warum ist Krabblersekret so schwer zu finden?",a="Obwohl Mooskrabbler in den Wäldern rund um Tarrens Mühle weit verbreitet sind, sind brauchbare Vorkommen dieses speziellen, bösartigen Sekrets selten, sodass Jäger viele Spinnentiere erlegen müssen, bevor sie eine nutzbare Probe erbeuten.",al={"warum selten","krabblersekret droprate"}}},fp="13,270,32.579.0,35.188.0,42.195.0,42.220.0"}
P.entries["item:crocolisk-skin-classic"] = {n="Crocolisk Skin (Classic)",s="Krokiliskenhäute werden aus den zähen Bälgen der Krokilisken gewonnen, die die Inseln und Gewässer des Lochs in Loch Modan bewohnen. Von Händlern und Lederverarbeitern wegen ihrer Haltbarkeit geschätzt, erzielen sie trotz der Gefahr, die mit ihrer Beschaffung verbunden ist, einen ansehnlichen Preis.",h="Krokiliskenhäute werden aus den zähen Bälgen der Krokilisken gewonnen, die die Inseln und Gewässer des Lochs...",kw={"krokiliskenjagd","krokiliskenhaut","die weitschreiter-lodge","lochkrokilisk","loch modan","marek ironheart","der loch"},ang={["class:Hunter"]="Die Weitschreiter-Lodge respektiert jeden Fährtenleser, der bereit ist, zu den Inseln hinauszuzuwaten und ein um sich schlagendes Krokilisk für seinen Balg niederzuringen.",["race:Dwarf"]="Loch Modans berühmte Krokilisken sind bei Bergsteigern und Waldläufern der Lodge gleichermaßen als Härtetest bekannt."},sec={{t="Ein gefährliches Geschäft",b="In den kalten Gewässern des Lochs wimmelt es von aggressiven Krokilisken, die ihre Nester entlang der Inseln und Ufer des Sees errichten. Sie zu jagen ist keine leichte Aufgabe, denn diese wilden Bestien besitzen rasiermesserscharfe Zähne und dicke, widerstandsfähige Schuppen, die unachtsame Klingen abprallen lassen können. Trotz der Gefahren erlegen Jäger, die von der Weitschreiter-Lodge aus operieren, diese Kreaturen regelmäßig. Schneider, Lederverarbeiter und ferne Händler verlangen stets nach den Häuten, um strapazierfähige Kleidung und schützende Rüstungen herzustellen, was ein Bündel unbeschädigter Bälge zu einem wertvollen Handelsgut in der Region macht."}},faq={{q="Woher stammen Krokiliskenhäute?",a="Sie werden von den Lochkrokilisken und großen Lochkrokilisken erbeutet, die die Gewässer und Inseln des Lochs in Loch Modan bewohnen.",al={"woher man krokiliskenhaut bekommt","loch krokiliskenhaut quelle","wer krokiliskenhaut fallen lässt"}},{q="Wer kauft oder handelt mit diesen Bälgen in Loch Modan?",a="Marek Ironheart, ein erfahrener Zwergenjäger, der in der Weitschreiter-Lodge stationiert ist, sammelt sie zusammen mit Krokiliskenfleisch, um sie an durchreisende Händler und Handwerker zu verkaufen.",al={"wer krokiliskenhäute braucht","die weitschreiter-lodge krokiliskenhäute","marek ironheart häute"}},{q="Warum sind diese Häute so gefragt?",a="Händler schätzen die zähen, schuppigen Bälge für die Herstellung robuster Kleidung und Rüstungen. Da die Bestien wild und schwer zu töten sind, bringen Häute von guter Qualität einen verlässlichen Ertrag ein.",al={"wofür krokiliskenhäute genutzt werden","krokiliskenleder verwendung","warum krokilisken jagen"}},{q="Gilt die Jagd auf Krokilisken im Loch als gefährlich?",a="Ja. Die Krokilisken sind berüchtigt für ihre Aggressivität und besitzen kräftige Kiefer sowie gezackte Zähne, die in der Lage sind, Gliedmaßen abzutrennen. Einheimische Jäger wie Marek Ironheart erzählen oft Geschichten von beinahe tödlichen Begegnungen beim Versuch, ihre Beute zur Strecke zu bringen.",al={"sind loch krokilisken gefährlich","krokiliskenjagd gefahr"}}},fp="24,267,17.570.0,35.131.0,45.165.0,30.172.0,55.235.0"}
P.entries["item:crocolisk-tear-classic"] = {n="Crocolisk Tear (Classic)",s="Eine Krokiliskenträne ist ein sonderbares alchemistisches Reagenz, das von den Krokilisken erbeutet wird, die die Gewässer von Loch Modan bewohnen. Sie wird von Chefingenieur Hinderweir gesucht, um eine neutralisierende Mischung herzustellen, die in der Lage ist, Sprengsätze der Dunkeleisenzwerge zu entschärfen.",h="Eine Krokiliskenträne ist ein sonderbares alchemistisches Reagenz, das von den Krokilisken erbeutet wird, die...",kw={"krokiliskenträne","dunkeleisenzwerge","hinderweir","loch modan","reagenz","der stonewroughtdamm","der loch"},ang={["profession:Engineering"]="Zwergeningenieure wie Chefingenieur Hinderweir setzen oft unkonventionelle alchemistische Verbindungen ein, um hochentwickelte Sprengstoffe zu neutralisieren, wenn herkömmliche Werkzeuge nicht ausreichen."},sec={{t="Ein sonderbarer Bestandteil",b="Lochkrokilisken sind zähe Reptilien, die in den gemäßigten Gewässern von Loch Modan heimisch sind. Während Jäger oft ihre Häute und ihr Fleisch schätzen, entdeckte Chefingenieur Hinderweir einen unerwarteten Nutzen in ihren Sekreten. In Kombination mit starkem Spinnengift und resonanten Ogermineralien liefert die Träne eines Krokilisken die spezifischen chemischen Eigenschaften, die erforderlich sind, um den flüchtigen Sprengladungen der Dunkeleisenzwerge entgegenzuwirken, die den Stonewroughtdamm bedrohen."}},faq={{q="Wofür wird eine Krokiliskenträne verwendet?",a="Chefingenieur Hinderweir am Stonewroughtdamm benötigt eine Krokiliskenträne, um eine chemische Mischung herzustellen, die dazu dient, von Saboteuren der Dunkeleisenzwerge gelegte Sprengsätze zu entschärfen.",al={"krokiliskenträne verwendung","warum brauche ich krokiliskenträne","wer braucht krokiliskentränen"}},{q="Wo können Krokiliskentränen gesammelt werden?",a="Sie werden von Lochkrokilisken und großen Lochkrokilisken erbeutet, die die Gewässer und Untiefen des Lochs in Loch Modan bewohnen.",al={"wo droppen krokiliskentränen","krokiliskenträne fundort","wie man krokiliskentränen bekommt"}},{q="Welche anderen Materialien werden mit der Träne kombiniert?",a="Hinderweir kombiniert die Träne mit Lauerergift, das von den einheimischen Waldspinnen gewonnen wird, und einem Kristall der Mo'grosh von den Ogern der nordöstlichen Hügel, um das Entschärfungsmittel fertigzustellen.",al={"hinderweir zutaten","entschärfungsmaterialien","was wird noch mit krokiliskenträne benötigt"}}},fp="24,236,19.429.0,34.166.0,38.129.0,48.181.0"}
P.entries["item:crossroads-supply-crate"] = {n="Crossroads Supply Crate",s="Crossroads Supply Crates enthalten lebenswichtige Vorräte für die Siedlung Crossroads im Brachland. Nachdem eine Karawane entlang der staubigen Straßen überfallen worden war, landeten diese gestohlenen Güter verstreut in den örtlichen Lagern der Razormane-Stacheleber.",h="Crossroads Supply Crates enthalten lebenswichtige Vorräte für die Siedlung Crossroads im Brachland.",kw={"crossroads","crossroads supply crate","stacheleber","razormane","vorräte für crossroads","brachland","thork"},ang={["faction:Horde"]="Crossroads ist der zentrale Knotenpunkt, der Durotar, Mulgore und die nördliche Wildnis verbindet; die Sicherung seiner Vorräte schützt direkt das Reisen und die Logistik der Horde in ganz Kalimdor."},sec={{t="Geplünderte Vorräte",b="Die Siedlung Crossroads bildet das pulsierende Herz des Reiseverkehrs der Horde durch das zentrale Kalimdor, doch ihre Versorgung durch das trockene Ödland hindurch ist eine ständige Prüfung. Die Karawanenwege durch das Brachland werden unablässig von den einheimischen Razormane-Stachelebern belauert. Bei einem dieser Überfälle wurde eine lebenswichtige Nachschublieferung für die Siedlung geplündert. Die Kisten wurden in das dornige Gestrüpp und die Erdbauten nahegelegener Stacheleberlager geschleppt, sodass Thork, der Kommandant der Siedlung, Reisende anwerben muss, um sie zurückzuholen, bevor dem Außenposten Nahrung, Werkzeuge und lebensnotwendige Dinge gefährlich knapp werden."}},faq={{q="Was sind diese Vorratskisten?",a="Es handelt sich um Lieferungen von Nahrung, Werkzeugen und lebenswichtigen Vorräten, die zur Versorgung der Horde-Siedlung Crossroads bestimmt sind. Sie wurden von einer Versorgungskarawane geraubt, die auf den Straßen des Brachlands überfallen wurde.",al={"crossroads vorräte","was ist in den kisten","vorratskisten info"}},{q="Wer hat die Vorratskisten gestohlen?",a="Die Razormane-Stacheleber griffen die Karawane an und schleppten die Kisten in ihre nahegelegenen Dornenlager, um zu schmausen und die Beute zu horten.",al={"wer hat die kisten gestohlen","wer hat die karawane überfallen","stacheleber diebe"}},{q="Wer sucht nach diesen Kisten?",a="Thork, ein in Crossroads stationierter Orc-Offizier, verlangt die Rückgabe der gestohlenen Kisten, um sicherzustellen, dass die Garnison und die einheimischen Bewohner ordnungsgemäß versorgt bleiben.",al={"wer sucht die kisten","vorratskisten abgeben","thork vorräte"}},{q="Wo befinden sich die Kisten?",a="Sie liegen verstreut auf dem Boden in den verschiedenen Lagern der Razormane-Stacheleber im umliegenden Gebiet des Brachlands.",al={"fundorte der kisten","wo man vorratskisten findet","crossroads supply crate orte"}}},fp="23,236,20.603.0,29.196.0,28.137.0,32.159.0,29.141.0"}
P.entries["item:crude-flint"] = {n="Kunstloser Feuerstein",s="Stücke von Kunstlosem Feuerstein sind grobe Steine zum Entfachen von Feuer, die von den Mosshide-Gnollen im gesamten Sumpfland mitgeführt werden. Die Gnolle nutzen sie, um mit frisch geschlagenem Sumpfholz Flammen zu entzünden – ein Akt, der den örtlichen Beschützer, Rethiel den Sumpfhüter, zutiefst erzürnt.",h="Stücke von Kunstlosem Feuerstein sind grobe Steine zum Entfachen von Feuer, die von den Mosshide-Gnollen im...",kw={"kunstloser feuerstein","feuer-tabu","gnoll","sumpfhueter","mosshide","rethiel","feuerstein","wetlands"},ang={["class:Druid"]="Die Zerstörung lebender Flora bloß für das Behagen von Gnollen verstößt direkt gegen die Grundsätze der Natur, weshalb die Konfiszierung und Zerstörung dieser Feuersteine eine selbstverständliche Pflicht für jeden Hüter der Wildnis darstellt."},sec={{t="Zunder im Schlamm",b="Obwohl sie grob und unbearbeitet sind, bieten diese einfachen Schlagsteine den Mosshide-Gnollen ihr wichtigstes Mittel, um inmitten der feuchten Moore des Sumpflands Wärme zu erzeugen und Fleisch zu garen. Unglücklicherweise für das Ökosystem des Sumpfes fällen die Mosshides lebendes Holz, um ihre Feuerstellen und Lagerfeuer zu speisen. Diese rücksichtslose Ernte und Verbrennung lebender Äste zog den Zorn von Rethiel dem Sumpfhüter auf sich, der jeden geschlagenen Funken als Angriff auf das natürliche Gleichgewicht begreift."},{t="Die Vergeltung des Sumpfhüters",b="Entschlossen, das Abholzen der Bäume des Sumpfes zu beenden, beauftragt Rethiel vorbeikommende Abenteurer damit, das Mosshide-Rudel systematisch ihrer Feuersteine zu berauben. Anstatt den erbeuteten Feuerstein wiederzuverwenden, plant der Wächter, jedes geborgene Stück zu Staub zu zerschlagen und die Fragmente ins Meer zu werfen, um sicherzustellen, dass die Gnolle das lebende Holz des Sumpflands nicht mehr verbrennen können."}},faq={{q="Wofür wird Kunstloser Feuerstein verwendet?",a="Die Mosshide-Gnolle nutzen die kunstlosen Feuersteine als primitive Schlagsteine, um Feuer für Wärme und zum Kochen zu entfachen. Für Reisende werden sie im Auftrag von Rethiel dem Sumpfhüter gesammelt, um die Gnolle daran zu hindern, lebende Bäume in Brand zu setzen.",al={"kunstloser feuerstein verwendung","was macht kunstloser feuerstein","kunstloser feuerstein zweck"}},{q="Welche Kreaturen tragen Kunstlosen Feuerstein bei sich?",a="Die meisten erwachsenen und spezialisierten Mitglieder des Mosshide-Gnolltribus tragen sie bei sich, darunter Mosshide Brutes, Trappers, Fenrunners, Mistweavers, Mystics, Alphas und Gnawbone. Die kleineren Mosshide-Gnolle und Mongrels tragen sie nicht bei sich.",al={"wer droppt kunstlosen feuerstein","woher bekommt man kunstlosen feuerstein","welche gnolle haben feuerstein"}},{q="Warum möchte Rethiel, dass die Feuersteine zerstört werden?",a="Rethiel ist entsetzt darüber, dass die Gnolle lebende Bäume des Feuchtgebiets fällen und ihr Holz für Wärme verbrennen. Indem er ihre Schlagsteine zerstört und die Splitter ins Meer wirft, hofft er, ihnen dauerhaft die Fähigkeit zu nehmen, zerstörerische Feuer zu entfachen.",al={"warum kunstlosen feuerstein zerstoeren","rethiel feuerstein grund","feuer-tabu grund"}},{q="Sind diese Feuersteine wertvoll für Handwerke?",a="Nein. Trotz ihrer mineralischen Natur handelt es sich um grobe Steine, die sich nur zum Schlagen primitiver Funken eignen; ihnen fehlt die Reinheit oder Form, die von Schmieden oder Ingenieuren benötigt wird.",al={"kann man kunstlosen feuerstein beim schmieden nutzen","ist kunstloser feuerstein ein handwerksmaterial"}}},fp="11,247,20.466.0,29.363.0,29.223.0,34.227.0,43.258.0,39.155.0"}
P.entries["item:crystal-kelp-frond"] = {n="Kristalltangwedel",s="Crystal Kelp Fronds sind Wasserpflanzen-Abschnitte, die von den Murlocs gesammelt werden, welche den Kristallsee im Wald von Elwynn bewohnen. Obwohl sie ursprünglich aus dem Ozean stammen, tragen Murlocs diese Wedel ins Landesinnere, was sie zu einem ungewöhnlichen alchemistischen Reagenz macht, das von William Pestle in Goldhain begehrt wird.",h="Crystal Kelp Fronds sind Wasserpflanzen-Abschnitte, die von den Murlocs gesammelt werden, welche den...",kw={"kristalltang","kristalltangwedel","kristallsee","goldhain","unsichtbarkeitsschnaps","murloc","william pestle"},ang={["profession:Herbalism"]="Anders als gewöhnliche, im Boden wurzelnde Kräuter ist Kristalltang eine Wasserpflanze, die nicht in Standard-Kräutervorkommen in ganz Elwynn zu finden ist; Kräuterkundige und Sammler müssen ihn den einheimischen Murlocs, die ihn horten, direkt entreißen."},sec={{t="Ein seltenes aquatisches Reagenz",b="Kristalltang gedeiht typischerweise in den Tiefen salziger Ozeane, was sein Vorkommen in den Süßwasserbecken des Walds von Elwynn unerwartet macht. Die Murloc-Stämme, die sich an den Ufern des Kristallsees niedergelassen haben, sammeln und behalten diese Wedel aus ihren ganz eigenen Gründen. Alchemisten schätzen die Wedel für ihre eigenartigen, das Sehvermögen verzerrenden Eigenschaften, und William Pestle in Goldhain verwendet sie speziell als Kernzutat für einen Unsichtbarkeitsschnaps, der heimlichen Liebenden helfen soll, an den wachsamen Augen ihrer Familien vorbeizuschlüpfen."}},faq={{q="Wo wächst Kristalltang natürlicherweise?",a="Kristalltang ist eine Meerespflanze, die für gewöhnlich in Salzwassermeeren wächst. Sie ist in Süßwasserseen im Landesinneren nicht heimisch, doch Murloc-Stämme sammeln die Abschnitte und bringen sie in Süßwassergebiete wie den Kristallsee.",al={"wo wächst kristalltang","ursprung von kristalltang","tang lebensraum"}},{q="Warum besitzen die Murlocs am Kristallsee Meerestang?",a="Murlocs besitzen tiefe Verbindungen zur Küste und wandern zwischen Wasserwegen umher. Sie ernten den Tang aus den Küstengewässern und tragen ihn mit sich in ihre Lager im Landesinneren an Seen und Bächen.",al={"warum murlocs tang haben","murloc tang grund"}},{q="Wer in Goldhain benötigt Crystal Kelp Fronds?",a="William Pestle, ein Alchemist, der im Lion's Pride Inn in Goldhain arbeitet, benötigt den Tang. Er nutzt ihn, um einen speziellen Unsichtbarkeitsschnaps für Maybell Maclure zu brauen, damit sie sich von den Weinbergen ihrer Familie wegschleichen kann, um Tommy Joe Stonefield zu treffen.",al={"wer braucht kristalltang","william pestle tang"}},{q="Welche Eigenschaften besitzt Kristalltang?",a="Wenn sie von einem Alchemisten fachgerecht veredelt werden, können die ungewöhnlichen Eigenschaften der Kristalltangwedel wirksame Gemische zur Verschleierung hervorbringen – insbesondere einen Unsichtbarkeitsschnaps, der den Trinkenden vorübergehend unsichtbar macht.",al={"tang effekte","was bewirkt kristalltang"}}},fp="18,258,22.511.0,39.209.0,51.183.0,43.241.1,42.204.0"}
P.entries["item:crystal-phial"] = {n="Kristallphiole",s="Eine makellose Kristallphiole, die jungen Nachtelfen-Abenteurern vom Druiden Tenaron Stormgrip im Shadowglen anvertraut wird. Sie wird verwendet, um heiliges Wasser aus einem nahegelegenen Mondbrunnen zu schöpfen, was den Beginn einer Reihe von Riten darstellt, die den wachsenden Weltenbaum Teldrassil ehren und nähren sollen.",h="Eine makellose Kristallphiole, die jungen Nachtelfen-Abenteurern vom Druiden Tenaron Stormgrip im Shadowglen...",kw={"aldrassil","krone der erde","kristallphiole","mondbrunnen","shadowglen","teldrassil","tenaron stormgrip"},ang={["class:Druid"]="Druiden verehren Mondbrunnen zutiefst und nutzen deren heitere Eigenschaften, um natürliche Energien zu lenken und neues Wachstum zu fördern, ohne den Versuchungen der arkanen Zauberei zu erliegen.",["race:NightElf"]="Für junge Kaldorei, die ihre ersten Schritte außerhalb von Aldrassil wagen, ist das Füllen dieser Phiole ein grundlegender Übergangsritus, der sie direkt mit den Wassern von Elune und der Erholung ihres Volkes nach dem Dritten Krieg verbindet."},sec={{t="Ein Gefäß für heilige Wasser",b="Diese zarte Glasphiole, die jungen Nachtelfen auf Aldrassil überreicht wird, dient einem wichtigen zeremoniellen Zweck. Tenaron Stormgrip beauftragt junge Beschützer damit, sie zum Mondbrunnen nördlich des Astes zu tragen, um dessen leuchtendes Wasser zu schöpfen. Obwohl die Phiole einfach konstruiert ist, birgt sie Wasser, das vom heiligen Vermächtnis des Brunnen der Ewigkeit durchdrungen ist. Die Rückkehr mit einer Gefüllten Kristallphiole markiert den ersten Schritt der Pilgerreise von Krone der Erde und lehrt junge Kaldorei das heikle Gleichgewicht von Magie, Geschichte und Natur in ihrer neuen Inselheimat."}},faq={{q="Wofür wird die Kristallphiole verwendet?",a="Die Phiole dient dazu, gesegnetes Wasser aus dem Mondbrunnen nördlich von Aldrassil im Shadowglen zu sammeln. Sobald sie gefüllt ist, wird sie als Teil der Quest 'Krone der Erde' zu Tenaron Stormgrip zurückgebracht.",al={"kristallphiole zweck","verwendung der kristallphiole","was tun mit der phiole"}},{q="Wer gibt Euch die Kristallphiole?",a="Der Druide Tenaron Stormgrip händigt die leere Kristallphiole aus, wenn er jungen Abenteurern auf dem großen Ast von Aldrassil ihre ersten Aufgaben überträgt.",al={"wer gibt kristallphiole","wo kristallphiole erhalten"}},{q="Warum ist das Schöpfen von Mondbrunnenwasser bedeutsam?",a="Mondbrunnen enthalten geweihtes Wasser, das mit der Essenz des Brunnens der Ewigkeit und der Gnade von Elune verbunden ist. Das mit der Phiole geschöpfte Wasser dient dazu, die Nachwirkungen des Dritten Krieges zu begreifen und an Ritualen teilzunehmen, die der Pflege von Teldrassil gewidmet sind.",al={"warum mondbrunnenwasser","bedeutung von mondbrunnenwasser","mondbrunnen zweck"}},{q="Was geschieht, nachdem die Phiole gefüllt ist?",a="Sie wird zu einer Gefüllten Kristallphiole. Wenn Ihr sie zu Tenaron Stormgrip zurückbringt, schließt Ihr Eure erste Prüfung ab und erhaltet Zugang zu weiteren Lektionen über die Erschaffung und Pflege des Weltenbaums in ganz Teldrassil.",al={"nach dem füllen der phiole","gefüllte kristallphiole verwendung"}}},fp="13,258,26.540.0,35.200.0,32.147.0,44.252.0,39.194.0"}
P.entries["item:crystalized-scales"] = {n="Kristallisierte Schuppen",s="Kristallisierte Schuppen sind die verhärteten, mineralisierten Häute, die von Basilisken erbeutet werden, welche in rauen Umgebungen Kalimdors wie dem verbrannten Tal und Tausend Nadeln heimisch sind. Zu feinem Pulver zermahlen dienen diese ungewöhnlichen Schuppen als exotisches magisches Reagenz, das von Zauberwirkern in Stormwind begehrt wird.",h="Kristallisierte Schuppen sind die verhärteten, mineralisierten Häute, die von Basilisken erbeutet werden...",kw={"basilisk","das verbrannte tal","collin mauren","kristallisierte schuppen","reagenz","steinkrallengebirge","stormwind","tausend nadeln"},ang={["class:Mage"]="Für Anwender der Arkanmagie zeigen diese Schuppen, wie Umwelteinflüsse die magische Beschaffenheit von Bestien verändern und spezialisierte Reagenzien für einzigartige Zauberformeln hervorbringen.",["faction:Alliance"]="Die Beschaffung dieser Schuppen schlägt eine Brücke über die weite Distanz zwischen der Allianz-Hauptstadt Stormwind und den ungezähmten Weiten Kalimdors."},sec={{t="Ein seltenes Reagenz aus Kalimdor",b="Basilisken, die extremen Umweltbedingungen wie Hitze und Asche trotzen – insbesondere jene, die im verbrannten Tal im Steinkrallengebirge oder in den schimmernden Salzebenen von Tausend Nadeln leben –, entwickeln starre, mit Kristallen überzogene Häute. Diese kristallisierten Schuppen besitzen eine latente arkane Resonanz, was sie für gelehrte Magier jenseits des großen Meeres, die mit seltenen Zauberkünsten experimentieren, außerordentlich wertvoll macht."},{t="Maurens arkane Arbeit",b="Im Menschenkönigreich Stormwind sucht der Magier Collin Mauren aktiv nach Abenteurern, die an die Grenzen Kalimdors reisen, um sich diese Schuppen zu beschaffen. Indem er die kristallinen Mineralschichten zu Staub zermahlt, nutzt Mauren das partikelförmige Material als lebenswichtiges Reagenz für neu ersonnene Zauber und persönliche arkane Forschungen."}},faq={{q="Welche Kreaturen bringen kristallisierte Schuppen ein?",a="Sie werden vor allem von Basilisken erbeutet, die an raue Regionen angepasst sind, wie etwa den versengten, angesengten und geschwärzten Basilisken im verbrannten Tal im Steinkrallengebirge sowie den Salzsteinbasilisken in Tausend Nadeln.",al={"wo droppen schuppen","wer droppt kristallisierte schuppen","basiliskenschuppen quelle"}},{q="Wer in Stormwind sucht nach diesen Schuppen?",a="Collin Mauren, ein in Stormwind ansässiger Zauberer, beauftragt Reisende, die ins Steinkrallengebirge aufbrechen, damit, sie für seine magischen Experimente zu sammeln.",al={"wer will kristallisierte schuppen","collin mauren schuppen","wer nutzt diese schuppen"}},{q="Wie werden die Schuppen beim Zauberwirken verwendet?",a="Laut Collin Mauren liefert das Zermahlen der kristallinen Schuppen zu feinem Staub ein mächtiges Reagenz, das benötigt wird, um spezialisierte Zauber seiner eigenen Schöpfung zu speisen.",al={"warum sind kristallisierte schuppen magisch","schuppen zauberreagenz"}},{q="Können kristallisierte Schuppen nur im Steinkrallengebirge gefunden werden?",a="Während Mauren ausdrücklich Abenteurer bittet, die sich in Das verbrannte Tal im Steinkrallengebirge wagen, können ähnliche kristalline Häute auch von Salzsteinbasilisken in Tausend Nadeln erbeutet werden.",al={"tausend nadeln schuppen","andere orte für schuppen"}}},fp="18,292,23.382.0,20.324.0,40.215.0,41.142.0,40.161.0,51.185.0"}
P.entries["item:curative-animal-salve"] = {n="Heilende Tiersalbe",s="Heilende Tiersalbe ist ein pflanzliches Heilmittel, das von druidischen Kräuterkundigen gebraut wird, um Wildtiere zu beruhigen und zu heilen, die von sich ausbreitenden ökologischen Krankheiten befallen sind. Sowohl an der Dunkelküste als auch im Brachland hergestellt, dient sie als Erstbehandlung für kränkliche Kreaturen, die unter den unsichtbaren Verderbnissen des Landes leiden.",h="Heilende Tiersalbe ist ein pflanzliches Heilmittel, das von druidischen Kräuterkundigen gebraut wird, um...",kw={"alanndarian nightsong","heilende tiersalbe","heilung der kranken","macht über gift","kränkliches reh","kränkliche gazelle","tonga runetotem"},ang={["class:Druid"]="Die Verabreichung dieses Heilmittels ist eine grundlegende Prüfung beim Erlernen der Linderung von Giften und Krankheiten und beweist Eure Hingabe an die Mission des Zirkels des Cenarius in ganz Kalimdor.",["race:Tauren"]="Der Einsatz der Salbe im Brachland zeigt, wie Tauren-Druiden die Lehren von Cenarius verkörpern und im Einklang mit uralten Zirkelriten wirken, um die Erde zu heilen."},sec={{t="Die Heilung der Wildnis",b="Aus lokal gesammelten Kräuterreagenzien hergestellt, wird Heilende Tiersalbe in Chargen zu zehn Dosen zubereitet, um Wildtiere zu behandeln, die von der sich ausbreitenden Verderbnis gezeichnet sind. In den nebligen Wäldern der Dunkelküste weist Alanndarian Nightsong junge Druiden an, die Salbe auf kränkliche Rehe aufzutragen, die zwischen dem Cliffspring und den Grenzen von Ashenvale umherstreifen. Weit im Süden, in der trockenen Weite des Brachlands, braut Tonga Runetotem ein identisches Heilmittel, um kränkliche Gazellen zu behandeln, die nördlich von Crossroads grasen. Während beide Kräuterkundigen mit lokalen Kräften zusammenarbeiten, um größere Vorräte herzustellen, wenden Praktiker im Feld die Salbe direkt bei Tieren an, die unter Umweltleiden leiden."},{t="Symptome eines tieferen Leidens",b="Die direkte Anwendung der Salbe lindert die Leiden eines Tieres, doch der Zirkel des Cenarius betrachtet diese Gebrechen als bloße Symptome einer weitaus größeren Störung. In Moonglade beobachtet Dendrite Starblaze, dass weder die befallenen Rehe der Küste noch die leidenden Gazellen der Savanne zufällige Opfer sind. Vielmehr sind sie ahnungslose Leidtragende einer sich ausbreitenden Plage, die Kalimdor aus verschiedenen Richtungen heimsucht. Das Verabreichen der Salbe dient Initianden als grundlegender Ritus, der ihre Hingabe zum Schutz der natürlichen Welt und ihre Beherrschung der Künste zur Giftreinigung auf die Probe stellt."}},faq={{q="Wofür wird Heilende Tiersalbe verwendet?",a="Die Salbe wird direkt auf befallene Wildtiere aufgetragen, um deren Gebrechen zu heilen. Druiden nutzen sie, um kränkliche Rehe zu behandeln, die durch die Dunkelküste streifen, oder kränkliche Gazellen, die nördlich von Crossroads im Brachland grasen.",al={"zweck der heilenden tiersalbe","heilende tiersalbe anwenden","was bewirkt die salbe"}},{q="Wer bereitet die Salbe zu?",a="An der Dunkelküste bereitet Alanndarian Nightsong die Salbe in Auberdine aus gesammelten Reagenzien zu. Im Brachland braut Tonga Runetotem in Crossroads das Gebräu für Druiden der Horde.",al={"wer stellt die salbe her","woher kommt die salbe"}},{q="Warum sind die Rehe und Gazellen überhaupt krank?",a="Laut Dendrite Starblaze vom Zirkel des Cenarius sind die Wildtiere Opfer einer wachsenden Verderbnis und Fäulnis, die sich in ganz Kalimdor ausbreitet, und dienen als frühe Verluste einer das Gleichgewicht zerstörenden ökologischen Plage.",al={"warum sind tiere kränklich","was vergiftet rehe der dunkelküste","brachland gazellenkrankheit"}},{q="Wie viele Dosen enthält eine Charge?",a="Eine Standardcharge für den Feldeinsatz bietet genug Salbe für zehn einzelne Anwendungen, bevor die Kräutermischung vollständig aufgebraucht ist.",al={"wie viele aufladungen","wie viele anwendungen hat die salbe"}}},fp="21,285,17.678.0,28.582.0,39.205.0,23.181.0,54.210.0,36.128.0"}
P.entries["item:daffodil-bouquet"] = {n="Narzissenstrauß",s="Der Narzissenstrauß ist ein frischer Strauß leuchtender Blumen, der von der Kräuterkundigen Martie Jainrose in Seenhain gesammelt wurde. Gedacht als romantisches Zeichen der Wertschätzung von Wache Parker für Darcy, schürt das Geschenk ungewollt den örtlichen Klatsch und eine kleine Rivalität.",h="Der Narzissenstrauß ist ein frischer Strauß leuchtender Blumen, der von der Kräuterkundigen Martie Jainrose...",kw={"narzissenstrauß","narzissen","darcy","wache parker","seenhain","martie jainrose","rotkamm"},ang={["profession:Herbalism"]="Kräuterkundige, die Seenhain besuchen, werden den Strauß als das Werk ihrer Pflanzensammler-Kollegin Martie Jainrose erkennen, was das heimische Gewerbe des Sammelns von Wildblumen unterstreicht."},sec={{t="Ein verfängliches Geschenk",b="Als Wache Parker Darcy im Lakeshire Inn seine Dankbarkeit dafür ausdrücken möchte, dass sie ihm sein tägliches Mittagessen packt, fädelt er über die Kräuterkundige der Stadt, Martie Jainrose, eine Geste ein. Martie bereitet einen Narzissenstrauß vor und bemerkt, dass dies ihre persönlichen Lieblingsblumen sind. Als die leuchtenden Blüten jedoch Darcy überreicht werden, wecken sie sofort Misstrauen: Darcy erkennt in der Auswahl Marties charakteristische Blume und vermutet kleinliche Eifersucht von der anderen Frau, wobei sie halbernst scherzt, dass Martie die Stängel aus Bosheit vergiftet haben könnte."}},faq={{q="Wofür wird der Narzissenstrauß verwendet?",a="Der Strauß ist für Darcy im Lakeshire Inn bestimmt. Wache Parker arrangiert die Lieferung an sie als herzliches Dankeschön für das Mittagessen, das sie für ihn zubereitet und ihm in den Dienst schickt.",al={"narzissenstrauß verwendungszweck","was tun mit narzissenstrauß","wer bekommt die narzissen"}},{q="Wer hat diesen Strauß zusammengestellt?",a="Martie Jainrose, die örtliche Kräuterkundige und Blumenverkäuferin in Seenhain, sammelt und bindet den Strauß auf Anfrage. Sie wählt bewusst Narzissen aus, da es ihre Lieblingsblumen sind.",al={"wer hat den strauß gemacht","narzissenstrauß herkunft","woher kamen die blumen"}},{q="Warum reagiert Darcy misstrauisch auf die Blumen?",a="Darcy erkennt die Narzissen sofort als Marties Lieblingsblumen und nicht als eine Auswahl, die eigens für sie getroffen wurde. Indem sie Martie als eifersüchtige Rivalin bezeichnet, fragt sich Darcy scherzhaft, ob der Strauß aus Bosheit vergiftet wurde, nimmt die Geste aber dennoch an.",al={"warum ist darcy wütend","darcy vergiftete blumen","rivalität zwischen darcy und martie"}},{q="Sind die Narzissen tatsächlich vergiftet?",a="Nein. Darcys Verdacht ist bloß lokales Drama und theatralische Eifersucht zwischen den beiden Frauen aus Seenhain. Die Blumen sind völlig harmlos.",al={"ist der strauß vergiftet","hat martie die narzissen vergiftet"}}},fp="16,247,15.516.0,38.182.0,26.184.0,49.268.1,36.135.1"}
P.entries["item:daggerspine-scale"] = {n="Säbelflossenschuppe",s="Eine Säbelflossenschuppe ist eine zähe Reptilienschuppe, die von den Säbelflossen-Naga erbeutet wird, welche an den südlichen Küsten des Vorgebirges von Hillsbrad lauern. Von der Königlichen Apothekervereinigung begehrt, dienen diese Schuppen als entscheidender Katalysator zur Aktivierung virulenter Gebräue in den fortlaufenden Seuchenexperimenten der Verlassenen.",h="Eine Säbelflossenschuppe ist eine zähe Reptilienschuppe, die von den Säbelflossen-Naga erbeutet wird, welche...",kw={"daggerspine","säbelflossenschuppe","elixier der pein","hillsbrad","lydon","naga","königliche apothekervereinigung","undercity"},ang={["faction:Horde"]="Das Sammeln von Schuppen entlang der Südküste erfordert vorsichtige Navigation, da die Lager der Säbelflossen gefährlich nahe am Allianzhafen Southshore liegen.",["race:Undead"]="Die Beschaffung dieser Schuppen treibt die Forschungen der Königlichen Apothekervereinigung zur Entwicklung verheerender neuer Seuchen gegen die Feinde der Verlassenen direkt voran."},sec={{t="Forschung der Apotheker",b="Die Königliche Apothekervereinigung sucht ständig nach biologischen Reagenzien, um ihre Toxine, Seuchen und Gebräue zu verbessern. Bei der Verfeinerung des experimentellen Gebräus, das als Elixier der Pein bekannt ist, entdeckten die Apotheker, dass Schuppen der einheimischen Säbelflossen-Naga einzigartige reaktive Eigenschaften besaßen. In Kombination mit regenerativen Elixieren der Trolle und Murloc-Organen tragen die Schuppen dazu bei, ruhende Erreger in rohen Gemischen chemisch zu aktivieren. Ihre Beschaffung erfordert die Jagd entlang der felsigen Küste östlich von Southshore, wobei man sowohl dem bösartigen Naga-Stamm als auch den nahe gelegenen Streitkräften der Allianz trotzen muss."}},faq={{q="Wofür werden Säbelflossenschuppen verwendet?",a="Sie werden für Apotheker Lydon in Tarrens Mühle im Rahmen der Forschungen am Elixier der Pein gesammelt. In Kombination mit anderen Reagenzien aktivieren die Schuppen die ansteckenden Eigenschaften einer alchemistischen Morastschnauzenmixtur.",al={"säbelflossenschuppe verwendung","warum säbelflossenschuppen sammeln","was bewirken säbelflossenschuppen"}},{q="Woher stammen diese Schuppen?",a="Sie werden von Säbelflossen-Naga erbeutet – darunter Küstenpirscher, Küstenjäger, Kreischer, Sirenen und ihre Anführerin Lady Zephris –, welche die Küste des Vorgebirges von Hillsbrad direkt östlich der Menschensiedlung Southshore bewohnen.",al={"wo findet man säbelflossenschuppen","wer droppt säbelflossenschuppen","säbelflossenschuppe fundort"}},{q="Warum will die Königliche Apothekervereinigung Naga-Schuppen?",a="Die Apotheker der Vereinigung stellten fest, dass die widerstandsfähigen Schuppen des Säbelflossenstammes genau die chemischen Eigenschaften besitzen, die nötig sind, um bestimmte infektiöse Erreger in ihren experimentellen Pestilenz- und Krankheitsmischungen auszulösen.",al={"warum nagaschuppen","apotheker nagaschuppen"}}},fp="17,299,19.597.0,37.222.0,32.233.0,55.227.0"}
P.entries["item:dal-bloodclaw-s-skull"] = {n="Dal Blutklaues Schädel",s="Dal Blutklaues Schädel wird vom Häuptling der Thistlefur-Furbolgs im nördlichen Ashenvale erbeutet. Wenn er zu Raene Wolfrunner in Astranaar gebracht wird, dient er als greifbarer Beweis dafür, dass ein unmittelbar bevorstehender Angriff auf die Siedlung der Nachtelfen abgewendet wurde.",h="Dal Blutklaues Schädel wird vom Häuptling der Thistlefur-Furbolgs im nördlichen Ashenvale erbeutet.",kw={"ashenvale","astranaar","dal bloodclaw","furbolg","raene wolfrunner","schädel","thistlefur"},ang={["faction:Alliance"]="Das Erschlagen von Dal Bloodclaw sichert Astranaars Nordflanke und stellt sicher, dass die wichtigste Zuflucht der Allianz im zentralen Ashenvale verteidigt bleibt.",["race:NightElf"]="Für die Nachtelfen ist das Beseitigen gefallener Furbolganführer eine traurige Notwendigkeit; uralte Verbündete wurden durch die Verderbnis entstellt und gefährden nun Siedlungen wie Astranaar unmittelbar."},sec={{t="Der Untergang eines Häuptlings",b="Die Thistlefur-Furbolgs nördlich von Astranaar sind rasch an Zahl und Aggressivität gewachsen, verdorben zusammen mit weiten Teilen der uralten Wälder von Ashenvale. Aus Furcht davor, dass der wachsende Stamm bald den Mut aufbringen würde, direkt auf Astranaar zu marschieren, befahl die Nachtelfen-Schildwache Raene Wolfrunner das Ausdünnen ihrer Reihen und den Tod ihres Anführers, Dal Bloodclaw. Dal Blutklaues Schädel einzufordern dient nicht als Trophäe kleinlicher Rache, sondern als düsterer und unbestreitbarer Beweis dafür, dass die Führung des Stammes zerschlagen wurde, was den Verteidigern von Astranaar kostbare Zeit verschafft."}},faq={{q="Wer war Dal Bloodclaw?",a="Dal Bloodclaw war der Häuptling der Thistlefur-Furbolgs, die in Thistlefur Hold direkt nördlich von Astranaar hausen. Unter seiner Führung vermehrte sich der feindselige Stamm rasch und stellte eine drohende Gefahr für den nahegelegenen Außenposten der Nachtelfen dar.",al={"dal bloodclaw","wer ist bloodclaw","thistlefur-häuptling"}},{q="Warum will Raene Wolfrunner den Schädel?",a="Raene Wolfrunner benötigt einen Beweis dafür, dass der Häuptling der Thistlefur erschlagen wurde. Nach dem Tod von Dal Bloodclaw hoffen die Nachtelfen, dass die Verwirrung unter den überlebenden Furbolgs jegliche organisierten Pläne für einen Angriff auf Astranaar zunichtemacht.",al={"warum schädel","raene wolfrunner schädel","todesbeweis"}},{q="Warum sind die Thistlefur-Furbolgs so feindselig?",a="Wie viele Furbolgstämme in ganz Ashenvale sind auch die Thistlefur der um sich greifenden Verderbnis erlegen, die den Wald heimsucht, was sie von friedlichen Nachbarn des Waldes in gewalttätige und territoriale Bedrohungen verwandelt hat.",al={"warum furbolgs aggressiv","furbolg-verderbnis","thistlefur verrückt"}}},fp="21,238,22.573.0,22.231.0,41.221.0,43.221.0"}
P.entries["item:dalaran-mana-gem"] = {n="Manaedelstein aus Dalaran",s="Dalaran Mana Gems sind kristallisierte arkane Reserven, die von Personal der Kirin Tor im Silberwald mitgeführt werden. Verlassene Zauberwirker begehren diese Edelsteine als mächtige Rohstoffe zur Herstellung verzauberter Gewänder wie Roben des Zauberfeuers.",h="Dalaran Mana Gems sind kristallisierte arkane Reserven, die von Personal der Kirin Tor im Silberwald...",kw={"ambermill","manaedelstein aus dalaran","josef gregorian","kirin tor","leinen","manastein","silberwald","roben des zauberfeuers"},ang={["class:Mage"]="Auszubildende Magier der Verlassenen werden ausgesandt, um diese Edelsteine als Übergangsritus zu erbeuten, wodurch sie sowohl ihr kriegerisches Können als auch ihre Beherrschung erbeuteter arkaner Quellen unter Beweis stellen.",["race:Undead"]="Die Erbeutung verdeutlicht den kalten Pragmatismus der Verlassenen, die jegliche Sentimentalität gegenüber früheren menschlichen Kollegen in Dalaran ablegen, um das Überleben ihrer eigenen Fraktion zu sichern."},sec={{t="Gestohlene Arkana",b="Die Magier, Beschwörer und Wachen der Kirin Tor, die um Ambermill im Silberwald stationiert sind, tragen spezialisierte Manasteine bei sich, um ihre arkanen Energien zu bündeln und wieder aufzufüllen. Für die Verlassenen Zauberkundigen im Magic Quarter von Undercity stellen diese kristallinen Leiter eine leicht zugängliche Quelle konzentrierter magischer Essenz dar. Obwohl einige untote Magier ein gemeinsames akademisches Erbe mit Dalaran anerkennen, gebieten es pragmatische Notwendigkeit und eine Philosophie des Überlebens, unnachgiebige Rivalen ihrer magischen Ressourcen zu berauben."},{t="Das Weben des Zauberfeuers",b="Werden sie von gefallenen Agenten der Kirin Tor erbeutet, bringt man diese Edelsteine zusammen mit Ballen einfachen Leinens zu Schneidern wie Josef Gregorian in Undercity. Während gewöhnliche Handwerker arkane Macht nicht direkt kanalisieren können, vermögen geschickte Schneider die Manasteine in das Gewebe des Stoffes einzubinden. Diese Infusion verwandelt einfaches Garn in verzauberte Gewänder, die in der Lage sind, die Verbindung eines angehenden Zauberwirkers zum Arkanen zu stärken."}},faq={{q="Woher stammen Dalaran Mana Gems?",a="Sie werden von Streitkräften der Kirin Tor getragen, die im Silberwald stationiert sind, insbesondere rund um die Lager und Außenposten von Dalaran nahe Ambermill, südöstlich von Das Grabmal.",al={"wo manasteine farmen","dalaran edelstein beute","wer lässt manasteine fallen"}},{q="Wofür werden diese Edelsteine verwendet?",a="Verlassene Magier nutzen sie als essenzielle Verzauberungskomponenten. Werden sie zusammen mit Leinen zu Josef Gregorian in Undercity gebracht, liefern sie die magische Ladung, die zum Weben von Roben des Zauberfeuers erforderlich ist.",al={"verwendungszweck manastein","wozu dalaran mana gems gebraucht werden"}},{q="Warum tragen die Kirin Tor im Silberwald diese Edelsteine bei sich?",a="Mitglieder der Kirin Tor nutzen Manasteine als persönliche Reservoirs arkaner Macht, um ihr Zauberwirken, Schutzschilde und Beschwörungen in feindlichen Gebieten wie dem Silberwald aufrechtzuerhalten.",al={"warum dalaran zauberer edelsteine haben","kirin tor manasteine lore"}},{q="Warum haben es die Verlassenen auf Dalaranmagier abgesehen, um an diese Edelsteine zu gelangen?",a="Obwohl die Verlassenen akademische Wurzeln mit Dalarans magischer Tradition teilen, betrachten sie ihre lebenden Gegenstücke als Rivalen. Lehrmeister in Undercity erachten jeden Magier, der seinen arkanen Reichtum nicht verteidigen kann, als zu schwach zum Überleben, was das Erbeuten ihrer Komponenten rechtfertigt.",al={"verlassene gegen dalaran magier","warum dalaran für roben töten"}}},fp="16,232,13.549.0,21.423.0,37.169.0,29.187.0,56.187.0,56.259.0"}
P.entries["item:dalaran-pendant"] = {n="Anhänger aus Dalaran",s="Anhänger aus Dalaran sind magische Talismane, die von den im Dorf Ambermill im Silberwald stationierten Zauberern der Kirin Tor getragen werden. Die Verlassenen wollen diese Anhänger sammeln, um das arkane Wirken der Magi zu stören und die Quelle ihrer Macht zurückzuverfolgen.",h="Anhänger aus Dalaran sind magische Talismane, die von den im Dorf Ambermill im Silberwald stationierten...",kw={"allister","ambermill","anhänger aus dalaran","kirin tor","das grabmal","silberwald"},ang={["class:Mage"]="Die Anhänger dienen als Foki für das Weben der Kirin Tor und veranschaulichen, wie die Hexenmeister von Dalaran komplexe, gemeinschaftliche Magie koordinieren.",["race:Undead"]="Den Kirin Tor diese Anhänger zu entreißen, ist ein entscheidender Schritt zur Sicherung des Silberwalds gegen menschliche Zauberer, die versuchen, dort wieder Fuß zu fassen."},sec={{t="Amulette von Ambermill",b="Im Dorf Ambermill weben Hexenmeister, Beschwörer und Beschützer der Kirin Tor aktiv gewaltige arkane Zauber, die die Kontrolle der Verlassenen über den südlichen Silberwald bedrohen. Jeder dieser Agenten trägt einen eingestimmten Anhänger aus Dalaran. Im Grabmal beauftragt Schattenpriester Allister Agenten der Verlassenen damit, diese Anhänger zu beschaffen, um die Bemühungen der Magier zu bremsen und herauszufinden, wer ihr magisches Gewebe lenkt."}},faq={{q="Was ist der Anhänger aus Dalaran?",a="Er ist ein arkanes Amulett, das von den in Ambermill stationierten Beschwörern, Magiern und Beschützern der Kirin Tor getragen wird. Die Verlassenen sammeln sie ein, um das rituelle Wirken der Zauberer zu unterbrechen und ihr magisches Handwerk zu untersuchen.",al={"was ist anhänger aus dalaran","kirin tor halskette silberwald"}},{q="Wer trägt diese Anhänger?",a="Sie werden von den menschlichen Magiern, Beschwörern und Beschützern von Dalaran getragen, die Ambermill im Silberwald besetzt halten.",al={"wer droppt anhänger aus dalaran","woher bekommt man anhänger aus dalaran"}},{q="Warum möchte Schattenpriester Allister sie haben?",a="Schattenpriester Allister und sein Verbündeter Dalar benötigen die Anhänger, um das Zauberwirken der Magier zu verlangsamen und den mächtigen Magier ausfindig zu machen, der das Weben der magischen Energie in Ambermill lenkt.",al={"warum allister anhänger will","ambermill-nachforschungen anhänger"}},{q="Wo liegt Ambermill?",a="Ambermill liegt im südlichen Silberwald. Reisende, die vom Grabmal aus nach Süden ziehen, nehmen die östliche Abzweigung von der Hauptstraße, um das Dorf zu finden.",al={"ambermill standort","weg nach ambermill"}}},fp="15,250,20.406.0,28.198.0,27.115.0,42.176.0,27.149.0"}
P.entries["item:dalaran-status-report"] = {n="Statusbericht von Dalaran",s="Der Statusbericht von Dalaran ist eine Sammlung vertraulicher Geheimdienstinformationen, die von den in Ambermill im Silberwald stationierten Zauberern der Kirin Tor zusammengetragen wurden. Er beschreibt detailliert den geheimnisvollen, anhaltenden Wiederaufbau hinter Dalarans leuchtender Schutzkuppel und ist damit eine begehrte Beute für die Verlassenen und die Todespirscher von Undercity.",h="Der Statusbericht von Dalaran ist eine Sammlung vertraulicher Geheimdienstinformationen, die von den in...",kw={"ambermill","ambermill geldkassette","statusbericht von dalaran","die todespirscher","kirin tor","mennet carkad","werkzeuge des handwerks","varimathras"},ang={["class:Rogue"]="Mennet Carkad nutzt die Bergung dieses Berichts als Praxistest für die Ausbildung von Todespirschern in der feinen Kunst des Schlossknackens und der Infiltration gegen wachsame Magier.",["race:Undead"]="Die Überreste der Kirin Tor in Ambermill sind den Verlassenen im Silberwald ein Dorn im Auge, weshalb jegliche Informationen über ihre Operationen für die Sicherheit von Undercity von entscheidender Bedeutung sind."},sec={{t="Augen hinter dem violetten Schild",b="Seitdem die Geißel Dalaran plünderte und Archimonde seine hoch aufragenden Türme einstürzen ließ, blieb der zerstörte Stadtstaat hinter einem undurchdringlichen violetten Energieschild abgeriegelt. Außerhalb dieser Barriere haben die überlebenden Magi der Kirin Tor Vorposten-Enklaven errichtet, vor allem Ambermill im südöstlichen Silberwald. Von dieser befestigten Siedlung aus koordinieren die Magier die Logistik, bewachen umliegende Straßen und kommunizieren mit jenen, die innerhalb der Kuppel arbeiten. Der Statusbericht von Dalaran enthält ihre lokalen Lagebeurteilungen, Truppenverteilungen und Aufzeichnungen über die Wiederaufbaubemühungen hinter dem violetten Schutzbann."},{t="Eine Prüfung für Todespirscher",b="Die Kontrolle über Lordaeron erfordert absolute Wachsamkeit, und Lord Varimathras behält jegliche Überreste der Allianz und der Kirin Tor genau im Auge. Nachdem Verhörspezialisten der Verlassenen einem gefangenen Kirin Tor Geständnisse entlockt hatten, befahl der Schreckenslord den Todespirschern, den Statusbericht zu beschaffen. Tief im Inneren von Ambermill in einer verschlossenen Geldkassette verborgen, wurde das Dokument sowohl zu einer operativen Notwendigkeit als auch zu einer Reifeprüfung für frisch initiierte Schurken, die unter Mennet Carkad im Rogues' Quarter das Schlossknacken erlernen."}},faq={{q="Was ist der Statusbericht von Dalaran?",a="Es handelt sich um eine Reihe vertraulicher Dokumente der Kirin Tor, die den aktuellen Zustand, die Wiederaufbauarbeiten und die Lage von Dalaran umreißen und von den Magiern des Außenpostens Ambermill verfasst wurden.",al={"was ist dieser bericht","dalaran bericht","ambermill dokumente"}},{q="Wo wird der Bericht aufbewahrt?",a="Die Magier von Ambermill haben den Bericht in einer Geldkassette innerhalb ihrer Siedlung im südöstlichen Silberwald eingeschlossen, um ihn vor Eindringlingen und neugierigen Blicken zu schützen.",al={"wo ist der bericht","ambermill geldkassette fundort","wie findet man den statusbericht"}},{q="Warum will Undercity diesen Bericht?",a="Lord Varimathras und die Verlassenen betrachten die überlebenden Kirin Tor als aktive Bedrohung direkt vor ihrer Haustür. Die Bergung des Berichts ermöglicht es den Todespirschern, Dalarans militärische Stärke und geheime Wiederaufbauprojekte einzuschätzen.",al={"warum wollen die verlassenen das","varimathras dalaran bericht","ziel der todespirscher"}},{q="Wie haben die Todespirscher von dem Dokument erfahren?",a="Die Todespirscher entlockten die Existenz und den Aufenthaltsort des Dokuments direkt einem gefangenen Kirin Tor, der in Undercity festgehalten und verhört wurde.",al={"wie fand undercity das heraus","gestaendnis des gefangenen"}}},fp="21,309,29.632.0,21.518.1,34.185.0,25.172.0,40.223.0,51.147.0"}
P.entries["item:dalin-s-heart"] = {n="Dalins Herz",s="Dalins Herz ist eine makabre Ritualkomponente, die Dalin Forgewright herausgeschnitten wurde, einem ehrenhaften Mann, der nahe dem Greymane-Wall im Silberwald patrouilliert. Hexenmeister aus Undercity begehren es als Opfergabe makelloser Reinheit, dazu bestimmt, eine Sukkubus anzulocken und an ihren Dienst zu binden.",h="Dalins Herz ist eine makabre Ritualkomponente, die Dalin Forgewright herausgeschnitten wurde, einem...",kw={"carendin halgar","dalin forgewright","dalins herz","der greymane-wall","herzen der reinen","silberwald","sukkubus","undercity"},ang={["class:Warlock"]="Die Beschaffung dieses Herzens ist ein wesentlicher Übergangsritus für Hexenmeister der Verlassenen, die lernen, eine Sukkubus zu binden, und beweist ihren Willen, unbefleckte Tugend für dämonische Meisterschaft zu ernten.",["race:Undead"]="Die Jagd nach Dalins Herz verdeutlicht die bittere Realität von Lordaeron nach der Geißel, wo verbliebene lebende menschliche Altruisten vor dem Greymane-Wall zur Beute für die Verlassenen werden."},sec={{t="Ein reines Herz für dunkle Künste",b="Um eine Sukkubus zu beschwören und zu unterwerfen, benötigen die Hexenmeister von Undercity einen seltenen Köder: die physischen Herzen wahrhaft tugendhafter Sterblicher. Dalin Forgewright verdiente sich sein dunkles Schicksal durch selbstlose Hingabe, indem er seine Tage damit verbrachte, verzweifelte Flüchtlinge aus Lordaeron zu verteidigen, denen der Schutz am versiegelten Greymane-Wall verwehrt blieb. Sein unerschütterlicher Altruismus zeichnet ihn als Sinnbild des Guten in einem gefallenen Land aus, was sein Herz zu einer unwiderstehlichen Beute für dämonische Verführungsrituale im Temple of the Damned macht."}},faq={{q="Wer war Dalin Forgewright?",a="Dalin Forgewright war ein ehrenhafter Mensch, der sein Leben dem Schutz von Lordaeron-Flüchtlingen widmete, die vor den verschlossenen Toren des Greymane-Walls im südlichen Silberwald gestrandet waren.",al={"dalin forgewright","wer ist dalin","dalin lore"}},{q="Warum benötigen Hexenmeister Dalins Herz?",a="Hexenmeister-Beschwörer in Undercity benötigen das Herz eines wahrhaft reinen und ehrenhaften Mannes als rituellen Köder, um eine Sukkubus anzulocken und zu beherrschen.",al={"warum dalins herz","zweck von dalins herz","warum hexenmeister dalins herz wollen"}},{q="Wer nimmt Dalins Herz an?",a="Das Herz wird zu Carendin Halgar gebracht, einem Hexenmeisterlehrer im Temple of the Damned in Undercity.",al={"wer nimmt das herz","dalins herz abgabe","wohin mit dalins herz"}},{q="Welche andere Komponente wird neben diesem Herz benötigt?",a="Carendin Halgar benötigt sowohl Dalins Herz als auch Comar's Heart, welches Comar Villard gehört, einem treuen Ehemann, der auf der Suche nach seiner verlorenen Frau durch das Sumpfland wandert.",al={"herzen der reinen anderes herz","anderes herz benoetigt","zweites herz"}}},fp="13,271,26.478.0,26.182.0,35.143.0,26.116.0,52.160.0"}
P.entries["item:darkhound-blood"] = {n="Schattenhundblut",s="Schattenhundblut ist eine üble Körperflüssigkeit, die von den verderbten hundeartigen Bestien geerntet wird, welche die Felder und Wälder von Tirisfal durchstreifen. Es wird auf Geheiß der Royal Apothecary Society gesammelt und dient als frühes Reagenz bei deren finsteren Experimenten zur Entwicklung einer tödlichen neuen Seuche.",h="Schattenhundblut ist eine üble Körperflüssigkeit, die von den verderbten hundeartigen Bestien geerntet wird...",kw={"eine neue seuche","apotheker johaan","brill","schattenhund","schattenhundblut","royal apothecary society","tirisfal"},ang={["faction:Horde"]="Während sich in Brill finstere Experimente entfalten, begreifen nur wenige außerhalb des inneren Zirkels der Verlassenen das toxische Potenzial, das von der Royal Apothecary Society freigesetzt wird.",["race:Undead"]="Das Sammeln von Reagenzien wie Schattenhundblut ist eine unverzichtbare Aufgabe für die Verlassenen, um Fürstin Sylvanas und der Royal Apothecary Society dabei zu helfen, die ultimative Waffe gegen die Geißel zu schmieden."},sec={{t="Treibstoff für die neue Seuche",b="Unter dem Befehl von Fürstin Sylvanas Windrunner strebt die Royal Apothecary Society danach, eine virulente Seuche zu entwickeln, die in der Lage ist, Arthas und seine Geißel zu vernichten. Der in Brill stationierte Apotheker Johaan stellt die Theorie auf, dass die einheimischen Bestien, die von dunklen Energien verderbt und widerstandsfähig gegen den umgebenden Verfall sind, ungewöhnliche biologische Eigenschaften besitzen. Durch das Destillieren des Blutes wilder Schattenhunde will Johaan biologische Verbindungen aufdecken, die virulente nekrotische Erregerstämme abwehren oder verbreiten können."}},faq={{q="Wofür wird Schattenhundblut verwendet?",a="Es wird von Apotheker Johaan in Brill als grundlegendes Reagenz für die Forschungen der Royal Apothecary Society genutzt, um eine völlig neue Seuche zu brauen, die tödlicher ist als alles, was Azeroth je gesehen hat.",al={"schattenhundblut verwendung","warum schattenhundblut sammeln","schattenhundblut zweck"}},{q="Welche Kreaturen liefern dieses Blut?",a="Es wird von den verschiedenen Schattenhunden gewonnen, die Tirisfal durchstreifen, darunter verfluchte, ausgehungerte und altersschwache Schattenhunde.",al={"woher bekommt man schattenhundblut","wer droppt schattenhundblut","schattenhundblut quelle"}},{q="Warum stehen Schattenhunde im Fokus der Seuchenforschung?",a="Apotheker Johaan stellt die Theorie auf, dass das Blut von Bestien, die an die verderbten Lande von Tirisfal angepasst sind, die biologischen Geheimnisse bergen könnte, die zur Synthese einer unaufhaltsamen Seuche nötig sind.",al={"warum schattenhunde","apotheker johaan theorie","schattenhund eigenschaften"}}},fp="15,275,23.478.0,33.185.0,33.119.0,48.179.0"}
P.entries["item:darkshore-grouper"] = {n="Dunkelküstenbarsch",s="Der Dunkelküstenbarsch ist ein robuster Salzwasserfisch, der in den nebligen Küstengewässern entlang der Darkshore heimisch ist. Er wird sowohl als schmackhafter Grundfang als auch als sportliche Beute geschätzt, lässt sich jedoch von den Docks aus schwerer erbeuten, da die Aktivitäten der Murlocs die einheimischen Fischer von ihren Booten vertrieben haben.",h="Der Dunkelküstenbarsch ist ein robuster Salzwasserfisch, der in den nebligen Küstengewässern entlang der...",kw={"auberdine","angel der familie blump","darkshore","dunkelküstenbarsch","angeln","barsch","gubber blump","murloc"},ang={["profession:Cooking"]="Der Dunkelküstenbarsch dient als vielseitige Zutat für einfache Küstenrezepte und ist daher ein praktischer Fang für reisende Köche, die ihr Handwerk an der Küste verfeinern möchten.",["race:Dwarf"]="Der Zwergenangler Gubber Blump vertritt an den Gestaden von Kalimdor das stolze Fischererbe seiner Familie und belohnt jeden, der den Fangfertigkeiten seiner Sippe das Wasser reichen kann."},sec={{t="Ein Grundnahrungsmittel der verhüllten Küste",b="Der in den kalten Meeresgewässern von Darkshore beheimatete Dunkelküstenbarsch ist ein geschätzter Fang für Küstenangler. Der Fisch wird für seine kulinarische Vielseitigkeit geschätzt und findet seinen Weg in eine Reihe einfacher Küstengerichte, die von Reisenden und Bewohnern rund um Auberdine bevorzugt werden. Zwar kann er mit einfacher Angelausrüstung aus der Brandung gezogen werden, doch gilt das Anbeißen den Fischern als ebenso genussvoll wie der Verzehr."},{t="Die Murloc-Bedrohung",b="In der Vergangenheit fuhren Fischer wie Gubber Blump mit kleinen Booten auf tiefere Gewässer hinaus, um Barsche dutzendweise an Land zu ziehen. Zunehmende Übergriffe der Küstenmurlocs haben jedoch die meisten Boote um Auberdine an Land verbannt. Da die Angler auf die Küstenlinien und Docks beschränkt sind, vermuten die Einheimischen, dass die vordringenden Murlocs die örtlichen Barschbestände verschlingen, weshalb ein guter Fang ohne Geduld schwerer zu erzielen ist."}},faq={{q="Wo kann man Dunkelküstenbarsche finden?",a="Dunkelküstenbarsche werden gefangen, indem man eine Angelschnur im Salzwasser entlang der Küste von Darkshore auswirft, einschließlich der Gewässer rund um Auberdine.",al={"wo barsch angeln","dunkelküstenbarsch fundort","dunkelküstenbarsch fangen anleitung"}},{q="Wer in Auberdine verlangt nach Dunkelküstenbarschen?",a="Gubber Blump, ein Zwergenfischer, der sich in Auberdine aufhält, bittet Reisende darum, für ihn Dunkelküstenbarsche zu fangen, und bietet im Gegenzug eine geschätzte Angel der Familie Blump an.",al={"wer braucht barsch","gubber blump fisch","barsch questgeber"}},{q="Warum nutzen die Fischer keine Boote, um Barsche zu fangen?",a="Aggressive Murlocs haben sich entlang der Küste von Darkshore ausgebreitet, sodass Bootsausflüge auf das Wasser für die einheimischen Fischer viel zu gefährlich geworden sind.",al={"warum keine boote","auberdine fischerboote","murlocs barsch"}},{q="Muss man sich auf einer Quest befinden, um einen Dunkelküstenbarsch zu fangen?",a="Nein. Obwohl er das Ziel von Aufgaben ist, die von Einheimischen wie Gubber Blump vergeben werden, handelt es sich beim Dunkelküstenbarsch um einen regulären Salzwasserfisch, der von jedem Angler gefangen werden kann, der seine Schnur in den Gewässern von Darkshore auswirft.",al={"ist barsch ein questgegenstand","kann man barsch jederzeit angeln"}}},fp="17,267,30.384.0,17.397.0,37.148.0,41.157.0,50.139.0,58.198.0"}
P.entries["item:darksoul-shackle"] = {n="Dunkelseelenfessel",s="Eine Dunkelseelenfessel ist eine verzauberte Fessel, die von den Worgen der Moonrage Darksouls getragen wird, welche den Silberwald durchstreifen. Unter der Anleitung von Erzmagier Arugal gefertigt, werden diese Werkzeuge von Magiern der Verlassenen im Grabmal gesucht, um die wilde Magie zu ergründen, die die Region im Griff hat.",h="Eine Dunkelseelenfessel ist eine verzauberte Fessel, die von den Worgen der Moonrage Darksouls getragen wird...",kw={"arugal","dalar dawnweaver","dunkelseelenfessel","moonrage darksoul","das grabmal","silberwald","worgen"},ang={["class:Mage"]="Die Untersuchung dieser Fesseln zeigt, wie ein verzweifelter Zauberer rohe verzauberte Artefakte einsetzte, um instabile Beschwörungszauber zu stützen, die er nicht richtig kontrollieren konnte.",["race:Undead"]="Für die Verlassenen ist es unerlässlich, Arugals Griff um den Silberwald zu brechen, um ihre südlichen Grenzen zu schützen und die Überlegenheit der arkanen Gelehrsamkeit von Unterstadt gegenüber den Misserfolgen Dalarans zu beweisen."},sec={{t="Eine Krücke für wankende Magie",b="Als Erzmagier Arugal die Worgen auf den Silberwald losließ, erwies sich seine eigene arkane Meisterschaft als unzureichend, um die übernatürlichen Bestien vollständig zu lenken und zu erhalten. Um seine Unzulänglichkeiten auszugleichen, band er verzauberte Werkzeuge wie Dunkelseelenfesseln an seine Schöpfungen. Diese Fesseln kanalisieren externe Zauberei in die Moonrage Darksouls, stärken ihre übernatürliche Kraft und verankern den Fluch, der sie als Knechte an Burg Shadowfang bindet."},{t="Prüfung durch die Kirin Tor",b="Im Grabmal hält der Magier der Verlassenen, Dalar Dawnweaver, Arugal für einen gefährlichen Inkompetenten, dessen Einmischung die Verteidigung der Kirin Tor gegen die Geißel ruinierte. Durch das Sammeln von Dunkelseelenfesseln zusammen mit jenen, die von Moonrage Gluttons erbeutet wurden, extrahieren die Forscher der Verlassenen die im Metall verwobenen Restverzauberungen. Das Studium dieser Krücken offenbart die strukturellen Mängel in Arugals Zauberei und liefert den Verlassenen die nötigen arkanen Erkenntnisse, um eine Gegenmaßnahme gegen seine lupine Plage zu entwickeln."}},faq={{q="Was ist eine Dunkelseelenfessel?",a="Sie ist eine verzauberte Metallfessel, die von den Worgen der Moonrage Darksouls im Silberwald getragen wird. Sie wurde von Erzmagier Arugal gefertigt, um seine fehlerhafte Zauberkunst zu stützen und die Bestien unter seiner Kontrolle zu halten.",al={"was sind dunkelseelenfesseln","dunkelseelenfessel gegenstandswissen","was ist diese fessel"}},{q="Wer will Dunkelseelenfesseln?",a="Dalar Dawnweaver, ein Magier der Verlassenen, der im Grabmal im Silberwald stationiert ist, benötigt sie. Er studiert die Verzauberungen in den Fesseln, um eine Lösung für Arugals Worgenausbruch zu finden.",al={"wer braucht dunkelseelenfesseln","wer nimmt die fesseln","dalar dawnweaver quest"}},{q="Woher stammen diese Fesseln?",a="Sie werden von den Leichen der Moonrage Darksouls geborgen, aggressiven Worgen, die die nördlichen und östlichen Gebiete des Silberwalds heimsuchen.",al={"wer droppt dunkelseelenfesseln","dunkelseelenfessel mob","woher bekommt man dunkelseelenfessel"}},{q="Warum hat Arugal den Worgen Fesseln angelegt?",a="Laut Dalar Dawnweaver war Arugal kein ausreichend begabter Magier, um die Bestien allein durch bloße Macht zu befehligen. Er verließ sich auf verzauberte Gegenstände wie diese Fesseln, um die flüchtige Magie zu kanalisieren und aufrechtzuerhalten, die das Rudel zusammenhielt.",al={"warum tragen worgen fesseln","arugal fessel zweck"}}},fp="16,273,28.448.0,18.505.1,27.191.0,28.193.0,34.140.0,42.237.0"}
P.entries["item:darnassus-marzipan"] = {n="Marzipan aus Darnassus",s="Marzipan aus Darnassus ist eine festliche Süßware, die in der Hauptstadt der Nachtelfen für die herbstlichen Feierlichkeiten der Schlotternächte hergestellt wird. Gastwirte in Darnassus verteilen es an Bittsteller, die bereit sind, für ihre süße Belohnung zu tanzen.",h="Marzipan aus Darnassus ist eine festliche Süßware, die in der Hauptstadt der Nachtelfen für die herbstlichen...",kw={"süßigkeiten","darnassus","marzipan aus darnassus","schlotternächte","jesper","marzipan","leckereien"},ang={["faction:Alliance"]="Das Sammeln von Leckereien aus Darnassus, Ironforge und Stormwind verbindet die weit verstreuten Völker der Allianz durch die gemeinsamen Festlichkeiten der Schlotternächte.",["race:NightElf"]="Selbst die ernsten Kaldorei nehmen die heitereren Bräuche des Herbstes an und bieten Reisenden, die ihre Gastfreundschaft mit einem lebhaften Tanz ehren, zuckriges Marzipan an."},sec={{t="Ein Vorgeschmack auf den Weltenbaum",b="Während der Schlotternächte nehmen die Hauptstädte der Allianz an heiteren Streiche-oder-Süßes-Traditionen teil. Während die Zwerge scharfe Minzbonbons anbieten und Stormwind zähes Nougat herstellt, bereiten die Gastwirte von Darnassus zartes Marzipan für Besucher zu. Um ein Stück zu erhalten, müssen Besucher ein wenig Festtagsstimmung zeigen – genauer gesagt, auf Geheiß des Gastwirts tanzen. Das Konfekt ist eine von vier regionalen Leckereien, die von dem jungen Jesper gesucht werden, einem Waisenkind vor Stormwind, das nicht selbst reisen kann, um Süßigkeiten zu sammeln."}},faq={{q="Wofür wird Marzipan aus Darnassus verwendet?",a="Marzipan aus Darnassus ist eine von vier verschiedenen Süßigkeiten, die von Jesper benötigt werden, einem Waisenkind, das während der Schlotternächte vor den Toren von Stormwind verweilt. Wer es zusammen mit Süßigkeiten aus Ironforge, Gnomeregan und Stormwind abliefert, erhält im Gegenzug ein Bündel festlicher Kürbisköstlichkeiten.",al={"marzipan aus darnassus verwendung","was mache ich mit marzipan"}},{q="Wie erhält man Marzipan aus Darnassus?",a="Es wird während der Schlotternächte von den Gastwirten von Darnassus vergeben. Ein Gastwirt wird Euch bitten, einen kurzen Tanz aufzuführen, bevor er sich von der süßen Köstlichkeit trennt.",al={"marzipan aus darnassus bekommen","wo gibt es marzipan"}},{q="Warum kann Jesper sich das Marzipan nicht selbst holen?",a="Jesper ist ein Waisenkind, das unter den wachsamen Augen von Matron Nightingale nahe Stormwind behütet wird. Aus Furcht vor lauernden Gefahren außerhalb der sicheren Stadttore ist es ihm verboten, durch die Welt zu reisen, um Süßigkeiten zu sammeln, weshalb er auf Abenteurer angewiesen ist, die ferne Leckereien wie das Marzipan für ihn zusammentragen.",al={"warum braucht jesper süßigkeiten","warum kann jesper nicht gehen"}}},fp="18,222,25.516.0,36.265.0,37.158.0,42.298.0"}
P.entries["item:darthalia-s-sealed-commendation"] = {n="Darthalias versiegelte Belobigung",s="Darthalias versiegelte Belobigung ist eine offizielle Depesche, verfasst von der Kriegskommandantin der Verlassenen in Tarrens Mühle. Sie lobt den unerbittlichen Feldzug eines Soldaten gegen die Menschen von Hillsbrad und überbringt die Nachricht über jene Siege direkt an das Oberkommando von Undercity.",h="Darthalias versiegelte Belobigung ist eine offizielle Depesche, verfasst von der Kriegskommandantin der...",kw={"belobigung","darthalia","hillsbrad","southshore","tarrens mühle","undercity","varimathras"},ang={["faction:Horde"]="Die Belobigung markiert einen entscheidenden strategischen Sieg in Lordaeron und beweist der Führung von Undercity, dass die befestigten Stützpunkte der Allianz im südlichen Vorgebirge systematisch zerstört werden können.",["race:Undead"]="Ein hohes Lob von Darthalia zu erhalten und es direkt im Thronsaal vorzulegen, hebt das Ansehen eines Soldaten innerhalb der aufstrebenden Militärhierarchie der Dunklen Fürstin beträchtlich."},sec={{t="Bericht an das Oberkommando",b="Nach den erbitterten Zusammenstößen im Vorgebirge von Hillsbrad verfasste Hochexekutorin Darthalia diese versiegelte Depesche, um den Fall von Southshores Führung und die Verheerung der menschlichen Stellungen offiziell festzuhalten. Versiegelt, um die Beurteilung der Kommandantin vor neugierigen Blicken zu schützen, ist das Dokument an Varimathras gerichtet, den Schreckenslord-Berater von Fürstin Sylvanas Windrunner. Für die Führung der Verlassenen im Royal Quarter bieten solche Schreiben einen greifbaren Beweis dafür, dass die Enklaven der Allianz südlich von Lordaeron zerschlagen werden können, sodass die nördlichen Garnisonen sich auf die unerbittliche Bedrohung durch die Geißel konzentrieren können."}},faq={{q="Was ist Darthalias versiegelte Belobigung?",a="Es ist eine offizielle Kriegsauszeichnung, verfasst von Hochexekutorin Darthalia aus Tarrens Mühle. Das Dokument belobigt formell die Kampfleistung eines Streitres gegen die Allianz während des Kampfes um Hillsbrad und ist für das Oberkommando in Undercity bestimmt.",al={"versiegelte belobigung","darthalia brief","hillsbrad bericht"}},{q="Wer erhält diese Belobigung?",a="Die Belobigung muss direkt zu Schreckenslord Varimathras gebracht werden, der an der Seite von Fürstin Sylvanas Windrunner im Royal Quarter von Undercity die militärischen Operationen beaufsichtigt.",al={"zu wem bringen","belobigung abgeben","wer bekommt darthalias belobigung"}},{q="Warum kümmert sich Varimathras um die Kämpfe in Hillsbrad?",a="Obwohl die Verlassenen den Lichkönig und seine Geißel als ihre größte existenzielle Bedrohung aus dem Norden betrachten, stört die menschliche Präsenz in Hillsbrad ständig ihre Nachschublinien und die südliche Grenzsicherung. Varimathras schätzt Siege auf dem Schlachtfeld, die das Hindernis der Menschen beseitigen, damit sich die Streitkräfte von Undercity auf den größeren Krieg konzentrieren können.",al={"warum varimathras sich kümmert","hillsbrad schreckenslord","strategie der verlassenen hillsbrad"}}},fp="31,261,22.591.0,40.251.0,31.175.0,58.345.0"}
P.entries["item:deadmire-s-tooth"] = {n="Schlammwühlers Zahn",s="Schlammwühlers Zahn ist eine Trophäe des uralten Krokilisken namens Schlammwühler, der die trüben Gewässer der Marschen von Dustwallow durchstreift. Ihn zum Jäger Melor Stonehoof auf Thunder Bluff zu bringen beweist, dass dem alternden Raubtier ein barmherziger und ehrenvoller Tod gewährt wurde.",h="Schlammwühlers Zahn ist eine Trophäe des uralten Krokilisken namens Schlammwühler, der die trüben Gewässer...",kw={"krokilisk","schlammwühler","dustwallow","die anhöhe der jäger","melor stonehoof","stonemaul","thunder bluff","zahn"},ang={["class:Hunter"]="Für Jäger, die unter den Mentoren der Anhöhe der Jäger lernen, ist das Erbeuten dieses Zahns eine Lektion darin, dass die Jagd Respekt und Barmherzigkeit beinhalten muss und nicht bloß das Streben nach Trophäen.",["race:Tauren"]="Die Jagd nach Schlammwühler verkörpert den Kreislauf des Gleichgewichts der Erdenmutter, in dem betagte Raubtiere dem Frieden entgegengeführt werden, anstatt sie leiden zu lassen."},sec={{t="Eine Trophäe der Barmherzigkeit",b="In den Traditionen der Taurenjäger auf der Anhöhe der Jäger ist das Aufspüren wilder Bestien nicht bloß eine Prüfung kriegerischen Könnens oder gedankenloser Blutsport. Es ist ein spiritueller Bund des Gleichgewichts, der Ehrfurcht und gelegentlich der Barmherzigkeit. Schlammwühler war einst einer der prächtigsten Krokilisken in den Marschen von Dustwallow, doch sein hohes Alter verwandelte seine letzten Jahre in eine qualvolle Pein. Obwohl er immer noch den unbezwingbaren Geist und die furchterregende Wildheit seiner besten Tage besaß, wurden seine gewaltigen Knochen und sein versagender Körper zu einem Gefängnis endlosen Schmerzes. Das Erbeuten von Schlammwühlers Zahn dient Melor Stonehoof als physischer Beweis dafür, dass das langwierige Leiden der Bestie durch eine ehrenhafte Jagd endlich beendet wurde."}},faq={{q="Wofür wird Schlammwühlers Zahn verwendet?",a="Der Zahn wird zu Melor Stonehoof auf der Anhöhe der Jäger in Thunder Bluff gebracht. Er schließt die von ihm aufgetragene Jagd nach Schlammwühler ab und dient als Beweis dafür, dass dem uralten Raubtier eine barmherzige Erlösung zuteilwurde.",al={"schlammwühlers zahn abgeben","wer will schlammwühlers zahn","was tun mit schlammwühlers zahn"}},{q="Woher stammt Schlammwühlers Zahn?",a="Der Zahn wird direkt von Schlammwühler erbeutet, einem riesigen, blassen Krokilisken, der die Wasserwege der Marschen von Dustwallow durchstreift und oft in der Nähe des Flusses und der Inseln nördlich der Stonemaul Ruinen lauert.",al={"wo gibt es schlammwühlers zahn","wer droppt schlammwühlers zahn","schlammwühler standort"}},{q="Warum möchte Melor Stonehoof, dass Schlammwühler getötet wird?",a="Melor sieht Schlammwühler nicht als Monster an, sondern als eine edle Kreatur, die in ihrem hohen Alter quälende körperliche Pein erleidet. Die Jagd ist ein Akt der Gnade, der es der Flamme des Krokilisken erlaubt, friedlich weiterzuziehen, anstatt in langsamem Siechtum zu vergehen.",al={"warum schlammwühler töten","melor stonehoof grund","ist schlammwühler böse"}}},fp="16,270,17.677.0,34.204.0,38.195.0,46.238.0"}
P.entries["item:death-cap"] = {n="Todeskappe",s="Die Todeskappe ist ein seltener, wirkmächtiger Pilz, der verborgen in der schattigen Höhle hinter den Cliffspring Falls in Darkshore wächst. Von Nachtelfenalchemisten wegen ihrer einzigartigen Eigenschaften geschätzt, erfordert ihre Ernte das Vordringen in einen unterirdischen Bau, vor dem der Hain der Uralten ausdrücklich gewarnt hat.",h="Die Todeskappe ist ein seltener, wirkmächtiger Pilz, der verborgen in der schattigen Höhle hinter den...",kw={"auberdine","barithras moonshade","höhlenpilze","cliffspring falls","darkshore","todeskappe","der hain der uralten","schorfstängling"},ang={["profession:Herbalism"]="Obwohl das Sammeln der Todeskappe für Barithras keine fachmännische Sichel verlangt, wird jeder Kräuterkundige die Gefahr zu schätzen wissen, seltene Pilze in feuchten, verderbten Nischen unter Tage zu ernten.",["race:NightElf"]="Die Beschaffung der Todeskappe dient zwei Zwecken: Sie unterstützt Barithras' Trankherstellung in Auberdine und überprüft zugleich die unheilvollen Vorahnungen, die der Hain der Uralten geäußert hat."},sec={{t="Eine giftige Blüte in der Dunkelheit",b="Die Todeskappe wächst ausschließlich in der unterirdischen Feuchtigkeit der Höhle, die sich hinter den Cliffspring Falls entlang der nordöstlichen Gebirgszüge von Darkshore verbirgt. Im Gegensatz zu den reichlicher vorkommenden Schorfstänglingen, die den umgebenden Höhlenboden bedecken, ist die Todeskappe rar und unverwechselbar. Kräuterkundige der Nachtelfen wie Barithras Moonshade schätzen den Pilz für experimentelle Gebräue, wenngleich die Beschaffung auch nur eines einzigen Exemplars verlangt, einer Höhle zu trotzen, in der Gerüchten zufolge eine schwelende Verderbnis lauert."},{t="Omen von Cliffspring",b="Die Ernte einer Todeskappe ist ebenso sehr ein Aufklärungseinsatz wie ein alchemistischer Botengang. Wächter aus dem Hain der Uralten warnten die einheimischen Kaldorei davor, sich den Wasserfällen zu nähern, da sie eine finstere Präsenz spürten, die in der Dunkelheit Wurzeln schlug. Wer die Höhle betritt, um den Pilz zu pflücken, muss sich den lauernden Kräften stellen, die die feuchte Aushöhlung als ihren Unterschlupf beansprucht haben."}},faq={{q="Wo kann ich eine Todeskappe finden?",a="Todeskappen wachsen in der verborgenen Höhle hinter den Cliffspring Falls, die sich im Nordosten von Darkshore an der Felswand befindet.",al={"todeskappe fundort","wo ist todeskappe","cliffspring höhle pilz"}},{q="Wer benötigt diesen Pilz?",a="Barithras Moonshade, ein in der Küstensiedlung Auberdine ansässiger Alchemist, sucht die Todeskappe, um einen speziellen Trank zu brauen.",al={"wer braucht todeskappe","barithras pilz quest"}},{q="Warum hat Barithras Moonshade sie nicht selbst gesammelt?",a="Baumwächter aus dem Hain der Uralten warnten Barithras davor, die Höhle hinter den Cliffspring Falls zu betreten, da sie spürten, dass ein vordringendes Übel die Höhle zu seinem Versteck gemacht hatte.",al={"warum nicht selbst holen","barithras warnung"}},{q="Wie unterscheidet sich die Todeskappe von einem Schorfstängling?",a="Während Schorfstänglinge auf dem Boden der Cliffspring-Höhle relativ häufig vorkommen, ist die Todeskappe ein seltenerer, wirkmächtigerer Pilz, dessen Auffinden sorgfältiges Kundschaften erfordert.",al={"todeskappe vs schorfstängling","unterschied zwischen pilzen"}}},fp="9,273,25.485.0,19.361.1,29.125.0,24.132.0,50.177.0,50.166.0"}
P.entries["item:deepfury-s-orders"] = {n="Deepfurys Befehle",s="Deepfurys Befehle ist ein zerknülltes Pergament, das von der Leiche von Ol' Rustlocke unterhalb des Thandol-Übergangs geborgen wurde. Es enthält düstere Anweisungen der Dunkeleisenzwerge, die den auskundschaftenden Zwergenverteidiger überfielen.",h="Deepfurys Befehle ist ein zerknülltes Pergament, das von der Leiche von Ol' Rustlocke unterhalb des...",kw={"dunkeleisenzwerge","deepfury","befehle","rhag garmason","rustlocke","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Die abgefangenen Befehle enthüllen einen Sabotageversuch auf die wichtigste Überlandader zwischen Dun Morogh, dem Sumpfland und den nördlichen Außenposten der Allianz.",["race:Dwarf"]="Die Entdeckung der Machenschaften der Dunkeleisenzwerge unter dem Thandol-Übergang trifft die Zwerge von Ironforge schwer, da der Übergang eine der größten Ingenieurleistungen ihres Königreichs und eine lebenswichtige nördliche Handelsverbindung darstellt."},sec={{t="Ein Zugriff unterhalb des Übergangs",b="Beim Auskundschaften der Fundamente des Thandol-Übergangs wurde der Zwergenbrückenverteidiger Ol' Rustlocke in die Enge getrieben und bei einem plötzlichen Hinterhalt der Dunkeleisenzwerge getötet. Neben der geballten Faust des Spähers lagen diese Befehle, verfasst vom feindlichen Anführer Deepfury. Das Dokument dient als direkter Beweis für ein koordiniertes Komplott gegen die Brücke, die das Sumpfland mit dem Arathihochland verbindet."},{t="Die Bedrohung aufdecken",b="Das Überbringen von Deepfurys Befehlen an Rhag Garmason bestätigt die finstersten Befürchtungen der Brückengarnison. Weit entfernt von einem zufälligen Scharmützel haben die Dunkeleisenzwerge gezielte Operationen direkt unter dem gewaltigen Mauerwerk des Thandol-Übergangs inszeniert, was dringende Verstärkungsgesuche an Ironforge und Stormwind zur Folge hat."}},faq={{q="Was sind Deepfurys Befehle?",a="Es handelt sich um schriftliche Militärbefehle des Dunkeleisen-Kommandanten Deepfury, die neben der Leiche von Ol' Rustlocke unterhalb des Thandol-Übergangs gefunden wurden.",al={"deepfurys befehle","was sind diese befehle","deepfury pergament"}},{q="Wo werden die Befehle gefunden?",a="Das Pergament wird neben der geballten Faust von Ol' Rustlocke in den höhlenartigen Stützkonstruktionen unterhalb des Thandol-Übergangs im nördlichen Sumpfland entdeckt.",al={"wo sind die befehle","rustlocke aufenthaltsort","deepfurys befehle finden"}},{q="Wer war Ol' Rustlocke?",a="Ol' Rustlocke war ein am Thandol-Übergang stationierter Zwergenspäher, der hinabstieg, um seltsame Aktivitäten um die Brückenpfeiler zu untersuchen, und von Dunkeleisenzwergen überfallen wurde.",al={"wer ist rustlocke","ol rustlocke lore"}},{q="Wer erhält Deepfurys Befehle?",a="Die Befehle werden zu Rhag Garmason gebracht, dem Zwergenverteidiger, der oben am Thandol-Übergang stationiert ist und sie liest, um die Bedrohung durch die Dunkeleisenzwerge einzuschätzen.",al={"wem bringt man die befehle","rhag garmason"}}},fp="17,217,24.375.0,21.315.1,27.153.0,27.151.0,22.175.0,31.145.0"}
P.entries["item:deepmoss-egg"] = {n="Kluftmoosei",s="Kluftmooseier sind die geballten Gelege, die von Kluftmoosspinnen in den Klippen und Schluchten des Steinkrallengebirges gelegt werden. Von opportunistischen Goblinhändlern in Ratchet begehrt, sind sie dazu bestimmt, eine exotische kulinarische Delikatesse im Piratenhafen von Booty Bay zu werden.",h="Kluftmooseier sind die geballten Gelege, die von Kluftmoosspinnen in den Klippen und Schluchten des...",kw={"booty bay","kluftmoosei","kluftmoosspinne","mebok mizzyrix","ratchet","sishircanyon","steinkrallengebirge","die scherwindklippe"},ang={["profession:Cooking"]="Während menschliche, orkische und zwergische Köche zögern mögen, betrachten die Bewohner von Booty Bay aufgeschlagene Spinneneier als abenteuerliche Delikatesse, die gesalzene Goblinpreise wert ist."},sec={{t="Eine Delikatesse der Klippen",b="Kluftmoosspinnen nisten in den zerklüfteten Höhen des Steinkrallengebirges, insbesondere im gesamten Sishircanyon und unter den verbliebenen Bäumen der Scherwindklippe. Die von ihnen hinterlassenen Gelege enthalten lebensfähige Spinneneier, geschützt unter dicken Gespinstsäcken und feuchtem Bergmoos. Obwohl sie für die meisten Reisenden unappetitlich sind, haben diese Eiersäcke das Interesse des Goblinhandels geweckt."},{t="Booty Bays kulinarischer Trend",b="Im südlichen Hafen von Booty Bay sind Spinnenei-Omelettes zu einer exzentrischen gastronomischen Modeerscheinung geworden. Da die Vorräte vor Ort den Appetit wohlhabender Piraten und abenteuerlustiger Feinschmecker nicht decken können, koordiniert der Händler Mebok Mizzyrix aus Ratchet Lieferungen über Werftmeister Dizzywig. Abenteurer trotzen der giftigen Brut des Steinkrallengebirges, um frische Gelege zu ernten, und verwandeln gefährliche Spinnennester in lukrative Lieferverträge."}},faq={{q="Wo sind Kluftmooseier zu finden?",a="Sie befinden sich im Steinkrallengebirge nordwestlich des Brachlands. Gelege können gehäuft unter den überlebenden Bäumen in der Scherwindklippe sowie tiefer in den giftigen Höhlen des Sishircanyons gefunden werden.",al={"fundorte der eier","wo man kluftmooseier findet","fundort kluftmoosei"}},{q="Wer möchte diese Eier sammeln?",a="Der Goblin-Unternehmer Mebok Mizzyrix in Ratchet heuert Abenteurer an, um sie zu sammeln, und richtet Handelsrouten mit Werftmeister Dizzywig ein, um die Gelege über das Meer zu exportieren.",al={"wer kluftmooseier braucht","wer kluftmooseier kauft","mebok mizzyrix quest"}},{q="Wofür werden die Eier eigentlich verwendet?",a="Sie werden nach Booty Bay verschifft, wo Spinnenei-Omelettes zu einer beliebten, wenn auch bizarren kulinarischen Modeerscheinung unter den dortigen Piraten und Kunden geworden sind.",al={"verwendung spinneneier","warum spinneneier sammeln","spinnenomeletts"}},{q="Warum wird beim Sammeln vor dem Sishircanyon gewarnt?",a="Der Sishircanyon ist ein verseuchtes Brutgebiet voller ausgewachsener Spinnen, Netze und verschlungener Beute. Mebok warnt jene mit empfindlichem Magen davor und rät ihnen, stattdessen Eier unter den spärlichen Bäumen der Scherwindklippe zu sammeln.",al={"warnung vor sishircanyon","schwacher magen sishir"}}},fp="12,262,23.380.0,24.427.0,30.207.0,32.171.0,36.148.0,54.217.0"}
P.entries["item:defias-docket"] = {n="Liste der Defias",s="Die Liste der Defias ist eine Sammlung geheimer Einsatzbefehle der Bruderschaft der Defias, die versteckt in Addles Siedlung im westlichen Dämmerwald entdeckt wurde. Sie enthält detaillierte Geheimdienstinformationen über eine ehrgeizige Verschwörung der Defias und liefert eine entscheidende Spur bei der Suche nach dem verschwundenen Gesandten von Stormwind.",h="Die Liste der Defias ist eine Sammlung geheimer Einsatzbefehle der Bruderschaft der Defias, die versteckt in...",kw={"addles siedlung","liste der defias","geldkassette der defias","dämmerwald","elling trias","der vermisste diplomat","behüter backus"},ang={["class:Rogue"]="Die Akte dient als eindringliche Erinnerung an die ausgefeilte Verschlüsselungsarbeit und die verdeckte Logistik, welche die Bruderschaft der Defias hinter der Fassade gewöhnlicher Gesetzlosigkeit einsetzt.",["faction:Alliance"]="Die Dokumente in der Akte enthüllen ein koordiniertes, verräterisches Komplott, das auf die allerhöchsten Ebenen der Regierung von Stormwind abzielt."},sec={{t="Eine Spur in die Dunkelheit",b="Bei der Verfolgung von Hinweisen auf den vermissten Diplomaten des Königreichs werden Ermittler von Meister Elling Trias in den Dämmerwald verwiesen. Behüter Backus bemerkt jüngste und ungewöhnliche Bewegungen der Defias, die in Addles Siedlung zusammenlaufen, einem verfallenen Gehöft südlich der Straße, die von Westfall hineinführt. In einer Geldkassette auf dem Anwesen versteckt, enthält die Liste der Defias komplexe Aufzeichnungen über die Bewegungen der Bruderschaft, die weit über einfachen Straßenraub oder lokales Banditentum hinausgehen."},{t="Das Netz der Verschwörung",b="Bei näherer Betrachtung erwiesen sich die Papiere als derart kompliziert und politisch brisant, dass Behüter Backus sich weigerte, sie zu behalten, da er schwere Strafen seiner Vorgesetzten fürchtete, falls man ihn mit ihnen ertappte. Nach Stormwind in Trias' Käseladen zurückgebracht, offenbart die Akte, dass die Defias beträchtliche Ressourcen in einen ausgeklügelten Entführungsplan investiert haben, und verweist dabei auf bekannte Akteure der Unterwelt wie einen Agenten mit dem Codenamen „Faust“."}},faq={{q="Was ist die Liste der Defias?",a="Es handelt sich um ein offizielles Bündel schriftlicher Dokumente und Befehle der Bruderschaft der Defias, in dem ihre Pläne und die verdeckten Operationen aufgeführt sind, die sie im Dämmerwald und in Westfall durchgeführt haben.",al={"was ist die liste der defias","defias papiere","vermisster diplomat liste der defias"}},{q="Wo wird die Liste der Defias gefunden?",a="Sie ist in einer Defias-Geldkassette im baufälligen Bauernhaus in Addles Siedlung eingeschlossen, direkt südlich der Straße, die von Westfall in den westlichen Dämmerwald führt.",al={"fundort der liste der defias","wo findet man liste der defias","addles siedlung liste"}},{q="Warum wurde die Akte im Dämmerwald aufbewahrt?",a="Agenten der Defias nutzten Addles Siedlung als abgelegenen Stützpunkt zwischen Westfall und dem Dämmerwald, um eine Operation von hoher Priorität abseits der wachsamen Augen der wichtigsten Patrouillen von Stormwind zu koordinieren.",al={"warum im dämmerwald","defias in addles siedlung"}},{q="Wer analysiert die Akte?",a="Behüter Backus untersucht sie kurz, bevor er sie direkt zu Elling Trias nach Stormwind schickt, dessen privates Informantennetzwerk darauf spezialisiert ist, verdeckte Botschaften der Unterwelt zu entschlüsseln.",al={"wer erhält die liste","wer liest die liste"}}},fp="13,309,21.468.0,21.418.1,26.186.0,33.157.0,36.191.0,24.192.0"}
P.entries["item:defias-tower-key"] = {n="Turmschlüssel der Defias",s="Der Turmschlüssel der Defias ist ein Gegenstand, der den monströsen Wachen von Klavens Turm in Westfall gestohlen wird. Er wird von den mutierten Drohnen getragen, die das Gelände verteidigen, stellt einen entscheidenden Beweis für die gefährlichen Operationen der Bruderschaft der Defias dar und wird von den Geheimdienstagenten aus Stormwind gesucht.",h="Der Turmschlüssel der Defias ist ein Gegenstand, der den monströsen Wachen von Klavens Turm in Westfall...",kw={"agentin kearnen","turmschlüssel der defias","dämmerwaldkiste","klaven mortwake","klavens turm","missgestaltete defiasdrohne","mathias shaw","der si:7"},ang={["class:Rogue"]="Die Beschaffung des Turmschlüssels der Defias ist eine typische Prüfung für Schurken, die für den SI:7 arbeiten, und erfordert meisterhafte Beherrschung der Täuschung, des Taschendiebstahls sowie ein Verständnis für tödliche Gifte.",["faction:Alliance"]="Die Sicherung von Informationen aus Klavens Turm hilft Stormwind dabei, die Machenschaften der Bruderschaft der Defias mit der Venture Company und ihren Handel mit gefährlichen Trolltinkturen aufzudecken."},sec={{t="Eine Beute der entstellten Wache",b="Klavens Turm an der Küste von Westfall dient der Bruderschaft der Defias seit Langem als Festung, doch jüngste Lieferungen aus dem Dämmerwald brachten weitaus furchterregendere Wachen an seine Außenbezirke. Zu den Wächtern gehören missgestaltete Defiasdrohnen – untote, mit Stacheln übersäte Abscheulichkeiten, die durch giftige Gebräue erschaffen wurden. Um die Verteidigung zu durchdringen und den Einbruch in den Sicherheitsbereich zu beweisen, beobachten Agenten des SI:7 das Gelände und weisen Außendienstler an, die Taschen dieser grotesken Wachen zu leeren, anstatt sie frontal anzugreifen. Der Schlüssel dient als eindeutiger Beweis dafür, dass ein Infiltrator das Areal unbemerkt betreten hat."},{t="Die Aufdeckung der Dämmerwald-Verbindung",b="Die Beschaffung dieses Schlüssels ist der erste Schritt zur Aufdeckung einer unnatürlichen Verschwörung, die weit über gewöhnliche Straßenräuberei hinausgeht. Im Inneren des Turms steht eine Kiste mit Lieferungen aus dem Dämmerwald, die Klaven Mortwakes Tagebuch enthält. Wird dieser Fund zu Meister Mathias Shaw nach Stormwind gebracht, enthüllt die Mission, wie sich die Defias mit der Venture Company verschworen haben, um mit speziellen Trollgiften zu handeln, die von Zanzil dem Verbannten entdeckt wurden. Diese Mixturen ermöglichen es Alchemisten, das Untotendasein zu simulieren, was die grotesken, hustenden Abscheulichkeiten rund um den Turm erklärt."}},faq={{q="Wie erhält man den Turmschlüssel der Defias?",a="Der Schlüssel kann nicht von einem besiegten Gegner erbeutet werden. Ein Agent muss sich unbemerkt heranschleichen und eine der missgestalteten Defiasdrohnen bestehlen, die das Äußere von Klavens Turm in Westfall bewachen.",al={"woher bekomme ich den schlüssel","turmschlüssel der defias erhalten","wer droppt turmschlüssel der defias"}},{q="Was öffnet der Turmschlüssel der Defias?",a="Der Schlüssel öffnet weder die Turmtür noch die Dämmerwaldkiste im Inneren. Stattdessen dient er als Beweisstück für den Geheimdienst, das Meister Mathias Shaw verlangt, um zu überprüfen, ob ein Agent unentdeckt in den Bereich eingedrungen ist.",al={"öffnet er die dämmerwaldkiste","welche tür öffnet das","was schließt der defiasschlüssel auf"}},{q="Was sind die missgestalteten Defiasdrohnen, die den Turm bewachen?",a="Es handelt sich um Handlanger der Defias, die mithilfe giftiger alchemistischer Tinkturen der Trolle von Zanzil dem Verbannten im Schlingendorntal in untote Abscheulichkeiten verwandelt wurden. Ihre Körper wurden drastisch verändert, sodass sie nun mit Stacheln versehen sind, schlurfend gehen und an geschädigten Lungen leiden.",al={"wer hat den schlüssel","was sind die turmwachen","was ist der stachelzombie"}},{q="Wer entsendet Agenten, um diesen Schlüssel zu beschaffen?",a="Agentin Kearnen, eine Späherin des SI:7, die das Gelände um Klavens Turm beobachtet, weist Schurken im Außendienst an, sich den Schlüssel anzueignen und den Inhalt der Dämmerwaldkiste für Meister Mathias Shaw in Stormwind zu bergen.",al={"wer gibt die quest","wer will den schlüssel"}}},fp="16,280,30.620.0,34.543.1,39.180.0,36.234.0,56.269.1,42.199.0"}
P.entries["item:deliah-s-ring"] = {n="Deliahs Ring",s="Deliahs Ring ist ein graviertes Schmuckstück, das aus einem von den Rot Hide-Gnollen im Silberwald angehäuften Leichenhaufen geborgen wurde. Mit der Inschrift „Für Deliah“ versehen, weist das Andenken eine düstere Spur zurück zu einem Pestopfer, das aus den Massengräbern von Tirisfal gestohlen wurde.",h="Deliahs Ring ist ein graviertes Schmuckstück, das aus einem von den Rot Hide-Gnollen im Silberwald...",kw={"brill","deliah","deliahs ring","gravierter ring","insel fenris","hadrec","magistrat sevren","rot hide gnolle"},ang={["race:Undead"]="Der Ring veranschaulicht die kalte Realität der Existenz der Forsaken: Sterbliche Bindungen verfaulen oft zusammen mit dem Fleisch, wenngleich sich einige wenige noch an die Erinnerung an jene klammern, die sie im Leben liebten."},sec={{t="Ein Andenken im Morast",b="Der Ring, der an der pockennarbigen, relativ frischen Hand einer Leiche inmitten von Gnollhügeln im Silberwald entdeckt wurde, trägt die schlichte Inschrift: „Für Deliah“. Dieser Fund offenbart, dass die ansässigen Rot Hide-Gnolle nicht bloß Schlachtfelder plündern – sie überfallen aktiv die Massengräber von Tirisfal und transportieren menschliche sowie Leichen der Forsaken nach Süden zur Insel Fenris, um sie für ihre eigenen finsteren Zwecke zu nutzen."},{t="Verbindungen nach Brill",b="Als das Artefakt den Autoritäten der Forsaken vorgelegt wird, verweist Hochexekutor Hadrec damit nach Brill, wo Magistrat Sevren die Aufzeichnungen über die jüngst Verstorbenen führt. Sevren bestätigt, dass Deliah in Brill lebte, bevor sie der Seuche erlag, und dort beigesetzt wurde, ehe Grabräuber ihre sterblichen Überreste exhumierten. Wer den Spuren des Rings folgt, stößt auf die fortwährende Trauer derer, die sie zurückließ – und darauf, ob sterbliche Zuneigung den Übergang in den Untod überdauern kann."}},faq={{q="Wo wird Deliahs Ring gefunden?",a="Der Ring wird bei Nachforschungen in den Hügeln der Rot Hide-Gnolle im nördlichen Silberwald entdeckt, wo er an der Hand eines unversehrten Pestopfers unter den geplünderten Toten liegt.",al={"wo man deliahs ring findet","fundort von deliahs ring","wie bekommt man deliahs ring"}},{q="Wer war Deliah?",a="Deliah war eine frühere Bewohnerin von Brill, die an der Seuche starb. Ihr Leichnam wurde in den dortigen Massengräbern beigesetzt, bevor er von Rot Hide-Gnollen gestohlen und in den Silberwald verschleppt wurde.",al={"wer ist deliah","deliah lore","deliah aus brill"}},{q="Warum hatten die Rot Hide-Gnolle ihren Leichnam?",a="Die mit der Geißel verbündeten Rot Hide-Gnolle plündern die Gemeinschaftsgräber in Tirisfal, horten Leichen und transportieren sie zu ihrer Festung auf der Insel Fenris.",al={"warum gnolle leichen stehlen","rot hide leichendiebstahl","was machen gnolle mit leichen"}},{q="Welche Inschrift trägt der Ring?",a="Die Innenseite des Reifs ist mit den Worten „Für Deliah“ graviert, was darauf hindeutet, dass es sich um ein persönliches Geschenk eines Geliebten oder Ehemanns vor ihrem Tod handelte.",al={"ringgravur","was steht auf dem ring","für deliah ring"}}},fp="13,266,22.395.0,13.454.1,29.182.0,15.183.0,42.173.0,36.143.0"}
P.entries["item:delivery-to-mathias"] = {n="Lieferung für Mathias",s="Die Lieferung für Mathias ist ein versiegeltes Paket, das vielversprechenden Schurken von Keryn Sylvius in Goldhain anvertraut wird. Die Übergabe an Meister Mathias Shaw gewährt einem aufstrebenden Agenten Einlass in die inneren Abläufe des SI:7 in Stormwind.",h="Die Lieferung für Mathias ist ein versiegeltes Paket, das vielversprechenden Schurken von Keryn Sylvius in...",kw={"lieferung für mathias","goldhain","keryn sylvius","mathias shaw","old town","paket","der si:7","stormwind"},ang={["class:Rogue"]="Dieses Paket stellt für einen Schurken den Übergang von kleinen Hinterhofschlägereien in die klandestine Welt der königlichen Spionage unter Mathias Shaw dar.",["faction:Alliance"]="Das Überbringen verdeckter Depeschen zwischen regionalen Spähern und der Hauptstadt hält Stormwinds geheimen Spionageapparat gegen interne Umtriebe am Laufen."},sec={{t="Die Prüfung eines Kuriers",b="Für das ungeübte Auge wirkt das Überbringen eines einfachen Pakets vom Lion's Pride Inn zu den Kasernen von Stormwind wie alltägliche Kurierarbeit. Doch für angehende Schurken dient das Paket als Vorsprechen beim Geheimdienst von Stormwind. Von der örtlichen Ausbilderin Keryn Sylvius überreicht, bietet es unerfahrenen Beutelschneidern eine direkte Einführung bei Meister Mathias Shaw und prüft ihre Fähigkeit, sich in der Hauptstadt zu bewegen, unauffällig zu bleiben und diskreten Befehlen ohne Nachfragen Folge zu leisten."},{t="Tor zum SI:7",b="Die Zustellung des Pakets führt einen Agenten direkt in das Herz des Hauptquartiers des SI:7 in Old Town. Mathias Shaw nutzt solche Übergaben, um Scharlatane von echten Talenten zu trennen. Diejenigen, die das Paket fehlerfrei überreichen, werden mit heiklen Feldeinsätzen belohnt, beginnend mit verdeckter Aufklärung und Infiltration gegen die Schmuggler-Netzwerke der Defias im Wald von Elwynn."}},faq={{q="Was befindet sich in der Lieferung für Mathias?",a="Das Paket bleibt für den Kurier versiegelt. Da es von der Außendienst-Ausbilderin Keryn Sylvius an den Spionagemeister Mathias Shaw übergeben wird, enthält es wahrscheinlich Geheimdienstberichte, Beurteilungen von Auszubildenden oder vertrauliche Materialien über lokale Bedrohungen wie Die Bruderschaft der Defias in Elwynn.",al={"was ist im paket","inhalt der lieferung","paketinhalt"}},{q="Wer schickt diese Lieferung?",a="Die Lieferung wird von Keryn Sylvius übergeben, einer Schurken-Agentin und Ausbilderin, die im oberen Stockwerk des Lion's Pride Inn in Goldhain stationiert ist.",al={"wer gab mir dieses paket","absender des pakets","paket von keryn sylvius"}},{q="Wo befindet sich das Hauptquartier von Mathias Shaw?",a="Mathias Shaw befindet sich im zweiten Stock des SI:7-Gebäudes, das in der südöstlichen Ecke von Old Town innerhalb des Geländes der Kasernen von Stormwind liegt.",al={"wo ist mathias shaw","wohin muss das paket gebracht werden","standort von shaw"}},{q="Was geschieht, nachdem man das Paket Shaw überreicht hat?",a="Sobald Shaw Eure Fähigkeiten bestätigt, führt er Euch in die eigentliche Feldspionage ein. Er schickt Euch los, um Jerods Anlegestelle zu infiltrieren und einen Shipping Schedule von einem Hafenmeister der Defias zu stehlen.",al={"nächste quest nach der lieferung","was macht shaw","nach lieferung für mathias"}}},fp="19,223,16.454.0,15.375.0,39.274.0,24.132.0,46.153.0,49.179.1"}
P.entries["item:deviate-hide"] = {n="Deviatbalg",s="Deviatbälge sind die mutierten Häute, die von den in den Höhlen des Wehklagens hausenden Bestien abgezogen werden. Durch den verderbenden Traum von Erz Druide Naralex verzerrt, sind diese andersweltlichen Pelze bei Druiden begehrt, die den Makel des Alptraums in strapazierfähige Lederwaren umwandeln wollen.",h="Deviatbälge sind die mutierten Häute, die von den in den Höhlen des Wehklagens hausenden Bestien abgezogen...",kw={"brachland","deviatbalg","leder","nalpak","naralex","alptraum","pelze","die höhlen des wehklagens"},ang={["class:Druid"]="Für Druiden ist das Sammeln von Deviatbälgen eine harte Konfrontation mit der verderblichen Macht des Smaragdgrünen Alptraums über die Natur, auch wenn Jünger wie Nalpak versuchen, die verderbten Materialien für das praktische Überleben nutzbar zu machen."},sec={{t="Verderbte Pelze des Alptraums",b="Als der Nachtelfen-Druide Naralex unter dem Brachland in seinen tiefen Schlummer fiel, verwandelte sich sein Traum in einen Smaragdgrünen Alptraum, der die örtliche Höhlenökologie verzerrte. Die in den Tiefen lauernden Bestien wandelten sich in unnatürliche Deviat-Raubtiere mit zähen, mutierten Bälgen. Obwohl sie von Natur aus vom Bösen berührt sind, besitzen diese Pelze eine ungewöhnliche, geschmeidige Widerstandskraft, die sie für die Lederverarbeitung einzigartig macht. Nalpak, der hoch über dem Höhleneingang in der totenkopfförmigen Felsformation verweilt, sammelt diese Bälge, um ihre Eigenschaften zu studieren und sie zu robusten Nützlichkeitstaschen zu verarbeiten."}},faq={{q="Was unterscheidet einen Deviatbalg von normalem Leder?",a="Deviatbälge stammen von Kreaturen, die durch den aus Naralex' Schlummer sickernden Smaragdgrünen Alptraum verzerrt wurden. Diese Verderbnis verändert ihr Fleisch und verleiht ihnen eine seltsame, andersweltliche Haltbarkeit und Elastizität, die gewöhnlichen Bestienpelzen fehlt.",al={"deviatbalg lore","warum deviatbälge seltsam sind","natur der deviatpelze"}},{q="Wer sammelt diese Bälge?",a="Nalpak, ein Jünger von Naralex, der in der Augenhöhlenhöhle über dem Eingang zu den Höhlen des Wehklagens sein Lager aufgeschlagen hat, sucht diese Pelze. Er glaubt, dass trotz der bösartigen Natur der Deviatbestien ihre Materialien erlöst und zu nützlichen Lederwaren verarbeitet werden können.",al={"wer deviatbälge will","nalpak bälge","wer deviatbälge braucht"}},{q="Wo findet man Deviatbälge?",a="Sie werden von den verschiedenen Deviatbestien erbeutet, die in den Höhlen des Wehklagens unter dem Brachland umherstreifen, darunter Raptoren, Vipern, Krokilisken und Schreckenszähne.",al={"wo deviatbälge droppen","wie man deviatbälge bekommt"}}},fp="12,267,30.569.0,56.225.0,30.260.0,30.158.0"}
P.entries["item:devlin-s-remains"] = {n="Devlins sterbliche Überreste",s="Devlins sterbliche Überreste sind die gesammelten Skelettknochen von Devlin Agamand, dem jüngeren Sohn der wohlhabenden Familie, der Agamands Mühlen gehörten. Als geistloser Knecht der Geißel strich er über die Straßen nahe dem ruinierten Anwesen seiner Ahnen, bis er niedergestreckt wurde, um seine Knochen einem rachsüchtigen Überlebenden in Brill zu überbringen.",h="Devlins sterbliche Überreste sind die gesammelten Skelettknochen von Devlin Agamand, dem jüngeren Sohn der...",kw={"agamands mühlen","brill","coleman farthing","devlin agamand","devlins sterbliche überreste","die spuk-mühle","tirisfal"},ang={["race:Undead"]="Für die Verlassenen repräsentieren die Agamands den alten, privilegierten Adel von Lordaeron, dessen Versagen das einfache Volk sterben und als Monster wiederauferstehen ließ, was die Schändung von Devlins sterblichen Überresten zu einem Akt der Klassenvergeltung macht."},sec={{t="Ein bitteres Erbe",b="Zu Lebzeiten stand Devlin Agamand im Schatten seines älteren Bruders Thurman. Wo Thurman sanftmütig und groß war, blieb Devlin als körperlich gebrechlich und bösartig scharfzüngig in Erinnerung. Als die Seuche des Untodes das nördliche Tirisfal heimsuchte, versäumte es die Familie Agamand, ihre Ländereien und Arbeiter zu beschützen. Devlin gehörte zu den ersten Opfern und wurde als unersättlicher Ghul der Geißel wiedererweckt, dessen hektisches, wahnsinniges Geplapper die Straße hinauf zu Agamands Mühlen heimsuchte."},{t="Rache auf dem Kaminsims",b="Coleman Farthing, ein Verlassener in Brill, hegt einen tiefen und unnachgiebigen Groll gegen die gesamte Blutlinie der Agamands. Da er sie direkt dafür verantwortlich macht, seine Familie beim Eintreffen der Seuche im Stich gelassen zu haben, beauftragte Farthing Reisende damit, Devlin zur Ruhe zu betten und seine sterblichen Überreste zu bergen. Farthing wollte Devlins Knochen auf seinem Kaminsims ausstellen und die Genugtuung genießen, dass seine einstigen Herren unter seiner Ferse zu Staub und zerschmetterten Fragmenten geworden sind."}},faq={{q="Wer war Devlin Agamand zu Lebzeiten?",a="Devlin war der jüngere Sohn der Familie Agamand, jener wohlhabenden Grundbesitzer, die Agamands Mühlen im nördlichen Tirisfal erbauten. Anders als sein sanftmütiger und breitschultriger Bruder Thurman war Devlin schwach, kränklich und berüchtigt schlecht gelaunt, bekannt für seine bittere und scharfe Zunge.",al={"wer ist devlin","devlin agamand hintergrundgeschichte","über devlin"}},{q="Wo wurden Devlins sterbliche Überreste geborgen?",a="Sie wurden von Devlin Agamands von der Geißel beherrschtem Leichnam genommen, der sich südlich von Agamands Mühlen an der durch Tirisfal führenden Straße aufhielt.",al={"wo ist devlin","wo man devlin findet","devlin agamand aufenthaltsort"}},{q="Warum will Coleman Farthing diese Knochen haben?",a="Coleman Farthing verabscheut die Familie Agamand, da er glaubt, sie habe ihn und seine Angehörigen beim Ausbruch der Seuche im Stich gelassen und versagt. Er beabsichtigt, Devlins Knochen als Trophäe der Rache und Genugtuung auf seinem Kaminsims in Brill aufzustellen.",al={"warum farthing sterbliche überreste will","coleman farthing motiv","warum agamand knochen sammeln"}},{q="Gehört Devlin zu den Verlassenen?",a="Nein. Als Devlin der Seuche erlag, verfiel sein Verstand vollständig der Geißel. Er wanderte als geistloser untoter Ghul über die Ländereien nahe den Mühlen und faselte Wahnsinniges, bis er vernichtet wurde.",al={"ist devlin ein verlassener","gehörte devlin zur geißel"}}},fp="16,290,15.464.0,23.452.0,31.284.0,42.152.0,43.245.0,31.184.0"}
P.entries["item:dim-necrotic-stone"] = {n="Dunkler nekrotischer Stein",s="Dunkle nekrotische Steine sind schattenhafte Relikte, die von den Leichen der Stoßtruppen der Geißel erbeutet werden, wenn diese die Außenbezirke der großen Hauptstädte überfallen. Erfüllt von schwachen unheiligen Energien dienen sie als Beweis für kriegerische Siege und helfen der Argentumdämmerung dabei, die Vorhut der Untoten zu studieren.",h="Dunkle nekrotische Steine sind schattenhafte Relikte, die von den Leichen der Stoßtruppen der Geißel erbeutet...",kw={"argentumdämmerung","dunkler nekrotischer stein","lichkönig","nekrotischer stein","runenkreis","geißel","untote"},ang={["faction:Alliance"]="Rekruten der Allianz außerhalb von Stormwind, Ironforge und Darnassus sammeln diese Steine, um ihre Hauptstädte zu beschützen und die Verteidigungsbemühungen der Argentumdämmerung gegen den plötzlichen Ansturm der Untoten zu unterstützen.",["faction:Horde"]="Krieger der Horde erbeuten diese Trophäen von gefallenen Truppen der Geißel, die Orgrimmar, Thunder Bluff und die Ruinen über Undercity belagern, um ihre kriegerische Entschlossenheit unter Beweis zu stellen."},sec={{t="Trophäen aus den Lagern der Geißel",b="Wenn Nekropolen am Himmel erscheinen und der Lichkönig seine Streitkräfte entsendet, um die Außenbezirke von Städten wie Stormwind und Orgrimmar anzugreifen, tragen die einfallenden Skelettsoldaten, Geistererscheinungen und Monstrositäten Dunkle nekrotische Steine bei sich. Die Steine pulsieren vor Resten der unnatürlichen Magie, die die Untoten an ihre Meister bindet. Die Argentumdämmerung sammelt diese Steine von Freiwilligen, die bereit sind, die Reihen der Geißel zu lichten, und betrachtet sie als handfesten Beweis dafür, dass die Lager der Invasoren zerschlagen wurden."},{t="Verbindungen zu unheiliger Magie",b="Diese Steine stehen in engem Zusammenhang mit den leuchtenden Runenkreisen, welche die Geißel um ihre Landepunkte errichtet. Ermittler der Argentumdämmerung glauben, dass die Steine und die dazugehörigen Kreise unheilige Energien kanalisieren, um den Kontakt zwischen den Angriffstrupps an vorderster Front und den finsteren Verständen aufrechtzuerhalten, die sie von oben befehligen. Die Erforschung der Steine hilft den Verteidigern dabei, die magischen Methoden zu entschlüsseln, mit denen die Geißel ihre plötzlichen Angriffe in ganz Azeroth koordiniert."}},faq={{q="Woher stammen Dunkle nekrotische Steine?",a="Sie werden direkt von den Fußsoldaten der Geißel erbeutet, wie etwa Skelettsoldaten und Geistererscheinungen, die während der Geißelangriffe nahe den Außenbezirken der Hauptstädte beider Fraktionen angreifen.",al={"nekrotischer stein beute","wer lässt dunklen nekrotischen stein fallen","wie man dunkle nekrotische steine bekommt"}},{q="Warum will die Argentumdämmerung diese Steine haben?",a="Die Argentumdämmerung benötigt konkrete Beweise dafür, dass die Verteidiger die Vorhut der Untoten zurückdrängen, und nutzt die Artefakte, um die unheilige Energie und die Kommunikation zu studieren, welche die Invasoren verbindet.",al={"argentumdämmerung nekrotische steine","warum nekrotische steine abgeben","nekrotischer stein zweck"}},{q="Welche Verbindung besteht zwischen diesen Steinen und den leuchtenden Runenkreisen?",a="Sowohl die Steine als auch die Runenkreise strahlen dieselbe nekrotische Macht aus. Die Argentumdämmerung vermutet, dass die Runenkreise als finstere Kommunikationskanäle dienen, die sich derselben unheiligen Energie bedienen wie die Rückstände in den Steinen.",al={"runenkreise geißel","nekrotischer stein runenkreis","was sind die leuchtenden kreise"}},{q="Können diese Steine auch außerhalb von Stormwind gefunden werden?",a="Ja. Die Streitkräfte der Geißel rücken gegen Städte in ganz Kalimdor und den Östlichen Königreichen vor, darunter Ironforge, Darnassus, Orgrimmar, Thunder Bluff und Undercity, und tragen diese Steine überall bei sich, wo sie Lager aufschlagen.",al={"nekrotische steine andere städte","ironforge nekrotische steine","orgrimmar nekrotische steine"}}},fp="18,269,35.514.0,20.458.0,39.187.0,43.185.0,66.222.0,47.211.0"}
P.entries["item:dirt-caked-pendant"] = {n="Dirt-Caked Pendant",s="Der Dirt-Caked Pendant ist ein persönliches Andenken des gefangenen Orcs Dogran. Einem aufstrebenden Hexenmeister im Brachland übergeben, dient er als entscheidender emotionaler Köder, um in Orgrimmar eine Sukkubus anzulocken und zu binden.",h="Der Dirt-Caked Pendant ist ein persönliches Andenken des gefangenen Orcs Dogran.",kw={"verschlinger der seelen","dirt-caked pendant","dogran","gan'rul bloodeye","die liebesgabe","sukkubus","zankaja"},ang={["class:Warlock"]="Für Hexenmeister in der Ausbildung veranschaulicht der Anhänger die dunkle Kunst, sterbliche Trauer und Hingabe zu nutzen, um Dämonen aus dem Wirbelnden Nether zu befehligen.",["race:Orc"]="Der Anhänger verkörpert Dograns bittersüße Entscheidung: Statt seinem Clan und seiner Gefährtin als Krüppel zur Last zu fallen, opferte er sein Andenken, um sich das letzte Gefecht eines Kriegers zu erkaufen."},sec={{t="Ein tragisches Zeichen",b="Während seiner Qualen im Brachland vom gebrochenen Krieger Dogran bewahrt, steht der Dirt-Caked Pendant für seine unausgesprochene Liebe zu seiner Gefährtin Zankaja. Vergiftet und unheilbar verkrüppelt gab Dogran den Anhänger lieber auf, als ihr zur Last zu fallen, und zog es vor, im Kampf gegen seine Peiniger zu sterben. Einem Hexenmeister anvertraut, wurde das düstere Andenken nach Orgrimmar zurückgebracht, damit seine schwere Bürde aus Herzschmerz und Hingabe von den Hexenmeistern der Kluft der Schatten umfunktioniert werden konnte."},{t="Köder für einen Dämon",b="In den unterirdischen Tiefen der Kluft der Schatten erkennt Gan'rul Bloodeye das finstere Potenzial, das solchen Relikten innewohnt. Eine Sukkubus nährt sich von sterblicher Sehnsucht, Romantik und Tragödie. Indem Dograns Anhänger gereinigt und auf Hochglanz poliert wird, verwandelt der Hexenmeistermeister ein Symbol hingebungsvoller Liebe in einen unwiderstehlichen spirituellen Köder, der einen Verschlinger der Seelen herbeiruft, um ihn durch rituellen Kampf zu unterwerfen."}},faq={{q="Woher stammt der Dirt-Caked Pendant?",a="Der Anhänger wird von Dogran überreicht, einem im Brachland gefangenen Orckrieger, nachdem Ihr ihm Ken'ziglas Trunk verabreicht habt, um seine Sinne wiederzubeleben.",al={"herkunft des anhängers","woher bekommt man den anhänger","wer gibt den anhänger"}},{q="Welche Verbindung besteht zwischen dem Anhänger und Zankaja?",a="Zankaja ist Dograns Gefährtin in Orgrimmar. Dogran entschied sich dafür, den Anhänger abzugeben und sein Überleben vor ihr zu verbergen, damit sie nicht damit belastet wird, einen invaliden Krieger zu pflegen.",al={"wer ist zankaja","dogran und zankaja","bedeutung des anhängers"}},{q="Warum benötigt Gan'rul Bloodeye genau diesen Anhänger?",a="Sukkuben werden von starken sterblichen Emotionen angezogen, insbesondere von Romantik, Herzschmerz und Hingabe. Sobald er gereinigt ist, dient Dograns Anhänger als wirkungsvoller Fokus, um eine Sukkubus in den Beschwörungskreis zu rufen.",al={"warum anhänger benötigt","anhänger sukkubusköder","anhänger ganrul bloodeye"}},{q="Was geschieht, nachdem der Anhänger nach Orgrimmar gebracht wurde?",a="Gan'rul Bloodeye reinigt den Anhänger und nutzt dessen Verlockung, um Die Bindung einzuleiten, wodurch eine Sukkubus in den Kreis unter der Kluft der Schatten gelockt wird, damit der Hexenmeister sie bezwingen und unterwerfen kann.",al={"was als nächstes anhänger","was tun mit anhänger"}}},fp="18,208,14.494.1,16.409.1,44.143.0,44.169.1,53.196.0,57.184.1"}
P.entries["item:disarming-colloid"] = {n="Entschärfungspaste",s="Entschärfungspaste ist ein spezieller chemischer Wirkstoff, der entwickelt wurde, um der Flüchtigkeit von Seaforium-Sprengpulver entgegenzuwirken. Vom Zwerg Ashlan Stonesmirk im Sumpfland bereitgestellt, dient sie als entscheidende stabilisierende Komponente in einem neutralisierenden Gemisch, das eine katastrophale Zerstörung des Stonewroughtdamms verhindern soll.",h="Entschärfungspaste ist ein spezieller chemischer Wirkstoff, der entwickelt wurde, um der Flüchtigkeit von...",kw={"ashlan stonesmirk","dunkeleisen","entschärfungspaste","sprengstoffe","hinderweir","seaforium","der stonewroughtdamm","sumpfland"},ang={["profession:Engineering"]="Ingenieure erkennen in Seaforium eine hochentwickelte Sprengstoffverbindung von immenser Zerstörungskraft, die präzise chemische Gegenmittel wie diese Paste statt grober mechanischer Entschärfungsmethoden erfordert.",["race:Dwarf"]="Die Entdeckung von Seaforium, das auf den Stonewroughtdamm gerichtet ist, stellt eine direkte Bedrohung für meisterhafte Zwergenbaukunst und die Sicherheit des darüber gelegenen Loch Modan dar."},sec={{t="Ein chemischer Neutralisator",b="Als Ashlan Stonesmirk das ungewöhnliche Sprengpulver analysierte, das Saboteuren der Dunkeleisenzwerge im Sumpfland abgenommen worden war, erkannte er es sofort an seinem unverwechselbaren Geruch und den feinen Silberkristallen: Seaforium. Während es vollkommen trocken harmlos ist, wird Seaforium bei Kontakt mit Feuchtigkeit immens zerstörerisch, was es zu einer existenziellen Bedrohung für den wasserumspülten Stonewroughtdamm macht. Um diese Reaktion vor einer Detonation aufzuhalten, stellte Stonesmirk eine Entschärfungspaste bereit. In Kombination mit drei speziellen lokalen Reagenzien – Lauerergift, zerkleinertem Kristall der Mo'grosh und einer Krokiliskenträne – neutralisiert diese Paste die explosiven Eigenschaften der Seaforium-Verbindung wirksam."}},faq={{q="Wofür wird die Entschärfungspaste verwendet?",a="Sie dient als chemische Grundsubstanz, die zum Entschärfen von Seaforium-Sprengpulver benötigt wird. Gemischt mit Lauerergift, zerkleinertem Kristall der Mo'grosh und einer Krokiliskenträne neutralisiert sie die flüchtige Reaktion, die sonst eine katastrophale Explosion hervorrufen würde, sobald das Seaforium feucht wird.",al={"zweck der paste","was bewirkt entschaerfungspaste","seaforium entschaerfer"}},{q="Wer hat diese Paste hergestellt oder bereitgestellt?",a="Die Entschärfungspaste wird von Ashlan Stonesmirk zur Verfügung gestellt, einem im Sumpfland stationierten Späher der Allianz, der die Pläne der Dunkeleisenzwerge zur Sprengung des Stonewroughtdamms durchschaut.",al={"wer gibt die paste","ashlan paste"}},{q="Warum ist Seaforium im Sumpfland so gefährlich?",a="Seaforium-Pulver ist in trockenem Zustand chemisch träge, doch bei Kontakt mit Feuchtigkeit reagiert es hochgradig explosiv. Da das Sumpfland von Wasser durchtränkt ist und das Ziel der Stonewroughtdamm selbst ist, stellt jedes feuchte Seaforium eine unmittelbare Gefahr gewaltiger Verwüstung dar.",al={"warum ist seaforium gefaehrlich","feuchtes seaforium"}},{q="Wem muss diese Paste überbracht werden?",a="Ashlan Stonesmirk weist an, die Paste und die Nachricht über den Seaforium-Plan auf direktem Weg zu Chefingenieur Hinderweir am Stonewroughtdamm zu bringen.",al={"zu wem bringe ich die paste","abgabe der paste"}}},fp="17,315,22.666.0,35.277.0,37.175.0,46.279.0,38.152.0"}
P.entries["item:disarming-mixture"] = {n="Entschärfungsmixtur",s="Die Entschärfungsmixtur ist ein spezielles chemisches Gebräu, das von Chief Engineer Hinderweir am Stonewroughtdamm zubereitet wird. Es wurde entwickelt, um flüchtige Seaforium-Sprengstoffe zu neutralisieren, und wird verwendet, um Saboteure der Dark Iron daran zu hindern, das gewaltige Zwergenbauwerk zu zerstören, das die Gewässer von Loch Modan zurückhält.",h="Die Entschärfungsmixtur ist ein spezielles chemisches Gebräu, das von Chief Engineer Hinderweir am...",kw={"dark iron","entschärfungsmixtur","sprengstoffe","hinderweir","loch modan","pulverfass","seaforium","der stonewroughtdamm"},ang={["profession:Engineering"]="Die Entschärfungsmixtur demonstriert praktisches Gegen-Ingenieurwesen, das auf eine schnelle chemische Neutralisierung setzt, um flüchtige Seaforium-Ladungen unschädlich zu machen, ohne eine Detonation auszulösen.",["race:Dwarf"]="Die Erhaltung des Stonewroughtdamms ist entscheidend für den Schutz der umliegenden Täler und Tieflande, was den raschen Einsatz dieses Neutralisators für die Sicherheit der Zwerge unverzichtbar macht."},sec={{t="Ein chemischer Neutralisator",b="Als Saboteure der Dark Iron eine schwere Seaforium-Ladung unter dem Fundament des Stonewroughtdamms platzierten, waren gewöhnliche Methoden zur Entschärfung viel zu riskant. Da es an sofortiger Unterstützung durch die Mountaineer fehlte, entwickelte Chief Engineer Hinderweir aus speziellen Zutaten die Entschärfungsmixtur, um den Unterwassersprengstoff rasch zu neutralisieren. Wird die Lösung direkt in das platzierte Pulverfass eingerührt, neutralisiert sie die reaktiven Verbindungen und verwandelt eine katastrophale Explosion in ein harmloses, zischendes Nichts."}},faq={{q="Wofür wird die Entschärfungsmixtur verwendet?",a="Die Mixtur wurde formuliert, um ein großes Seaforium-Sprengstofffass zu neutralisieren, das von Aufständischen der Dark Iron unter Wasser am Fundament des Stonewroughtdamms platziert wurde.",al={"was bewirkt entschärfungsmixtur","verwendung von entschärfungsmixtur","zweck der entschärfungsmixtur"}},{q="Wer stellt die Entschärfungsmixtur her?",a="Chief Engineer Hinderweir, der Zwergeningenieur, der die Instandhaltung und Verteidigung am Stonewroughtdamm überwacht, mischt die erforderlichen Zutaten zusammen, um die Mixtur herzustellen.",al={"wer stellt entschärfungsmixtur her","wer gibt entschärfungsmixtur","hinderweir mixtur"}},{q="Warum war die Mixtur notwendig, anstatt die Bombe einfach zu entschärfen?",a="Seaforium-Sprengstoffe sind äußerst instabil und so manipuliert, dass sie detonieren. Die chemische Mixtur neutralisiert das reaktive Pulver im Inneren des Fasses direkt und beseitigt so die Explosionsgefahr unter Wasser am Damm.",al={"warum nicht normal entschärfen","warum chemikalien auf der bombe verwenden","warum entschärfungsmixtur"}}},fp="17,297,22.489.0,39.157.0,34.163.0,67.204.0"}
P.entries["item:divined-scroll"] = {n="Gefundene Rolle",s="Die Gefundene Rolle ist ein verzaubertes Pergament, das von den Nachtelfen der Silberwindzuflucht verwendet wird, um die Quelle der gestörten Gewässer von Ashenvale zu entlarven. Durch das Kanalisieren der Restmagie in intakten Wasserelementar-Armschienen offenbart die Schriftrolle die Identität des abtrünnigen Zauberkundigen, der sie herbeiruft.",h="Die Gefundene Rolle ist ein verzaubertes Pergament, das von den Nachtelfen der Silberwindzuflucht verwendet...",kw={"ashenvale","gefundene rolle","rolle der bestimmung","elementararmschienen","mystralsee","silberwindzuflucht","velene starstrike"},ang={["class:Mage"]="Die Schriftrolle basiert auf grundlegenden Prinzipien der Beschwörungsrückverfolgung und verdeutlicht, wie Elementarbindungen unweigerlich die unauslöschliche arkane Signatur des Magiers in sich tragen, der sie erschaffen hat.",["race:NightElf"]="Für die Schildwachen, die Ashenvale verteidigen, sind Wahrsagewerkzeuge wie diese Schriftrolle unerlässlich, um sterbliche Verschmutzer aufzuspüren, deren arkanes Einmischen die heiligen Gewässer des Waldes bedroht."},sec={{t="Den Beschwörer aufspüren",b="Die verdorbenen Gewässer des Mystralsees beunruhigen die Schildwachen, die Ashenvale bewachen, schon lange. Um genau festzustellen, wer die den See heimsuchenden Wasserelementare manipuliert, händigt Schildwache Velene Starstrike Reisenden eine unaufgeladene Rolle der Bestimmung aus. Durch das Sammeln intakter Armschienen direkt von den getöteten Elementaren und deren Verwendung als arkanes Reagenz gehen die latenten Bindungen im Metall auf das Pergament über. Die daraus resultierende Gefundene Rolle offenbart die magische Signatur des abtrünnigen Magiers hinter dem Befall."},{t="Der entlarvte Magier",b="Sobald sie mit Energie erfüllt ist, weist die Schrift auf der Gefundenen Rolle Schildwache Velene direkt auf einen sterblichen Schuldigen hin: einen rücksichtslosen Magier, der die unberührten Waldbecken vorsätzlich verdirbt. Gewappnet mit der auf dem Pergament niedergeschriebenen Enthüllung können die Schildwachen Vergeltung planen und Späher aussenden, um den Beschwörer zur Strecke zu bringen, der für die Entweihung ihrer heiligen Wildnis verantwortlich ist."}},faq={{q="Wofür wird die Gefundene Rolle verwendet?",a="Die Gefundene Rolle enthüllt die Identität des Zauberkundigen, der feindselige Wasserelementare in den Seen von Ashenvale herbeiruft und bindet, sodass Schildwache Velene Starstrike den Schuldigen direkt ins Visier nehmen kann.",al={"was macht die gefundene rolle","zweck der gefundenen rolle","warum gefundene rolle herstellen"}},{q="Wie wird die Gefundene Rolle hergestellt?",a="Sie wird erschaffen, indem Ihr die von Schildwache Velene Starstrike bereitgestellte unbeschriebene Rolle der Bestimmung auf fünf Intakte Elementararmschienen wirkt, die von besiegten Wasserelementaren rund um den Mystralsee gesammelt wurden.",al={"wie man gefundene rolle herstellt","gefundene rolle herstellen","wie bekomme ich die gefundene rolle"}},{q="Warum werden die Elementararmschienen benötigt, um die Rolle zu bestimmen?",a="Die Armschienen dienen als physische Fesseln, die die Elementare auf der sterblichen Ebene halten. Ihre verbleibenden Verzauberungen liefern die notwendige magische Signatur, damit die Rolle den spezifischen Zauberer identifizieren kann, der sie beschworen hat.",al={"warum intakte armschienen","zweck von elementararmschienen"}},{q="Wem bringe ich die Gefundene Rolle?",a="Überbringt die fertige Gefundene Rolle an Schildwache Velene Starstrike bei der Silberwindzuflucht an der Straße im südlichen Ashenvale.",al={"wo gebe ich die gefundene rolle ab","wer will die gefundene rolle"}}},fp="14,288,20.507.0,16.364.1,36.202.0,34.186.0,58.222.0,37.124.0"}
P.entries["item:divining-scroll"] = {n="Rolle der Bestimmung",s="Die Rolle der Bestimmung ist ein verzaubertes Pergament, das von Schildwache Velene Starstrike in der Silberwindzuflucht bereitgestellt wird. Seine Magie ermöglicht es Ermittlern, die magische Signatur der unnatürlichen Wasserelementare, die Ashenvale heimsuchen, zu ihrem Schöpfer zurückzuverfolgen.",h="Die Rolle der Bestimmung ist ein verzaubertes Pergament, das von Schildwache Velene Starstrike in der...",kw={"ashenvale","gefundene rolle","rolle der bestimmung","elementararmschienen","silberwindzuflucht","velene starstrike","wasserelementare"},ang={["class:Mage"]="Die Rolle ist ein Paradebeispiel für klassische Erkenntnismagie, die zur Verfolgung arkaner Resonanz eingesetzt wird, und enthüllt, dass ein anderer Anwender des Arkanen die Elementarbeschwörung in heiligen Hainen der Kaldorei missbraucht.",["race:NightElf"]="Für die Schildwachen, die Ashenvale beschützen, ist diese Rolle ein entscheidendes Werkzeug, um Eindringlinge zu entlarven, die die unberührten Gewässer des Waldes mit unnatürlicher Verderbnis schänden."},sec={{t="Aufspüren unnatürlicher Elementare",b="Als verderbte Wasserelementare begannen, aus den unberührten Gewässern von Ashenvale emporzusteigen, wussten die Schildwachen, dass diese Störung kein natürliches Phänomen war. Schildwache Velene Starstrike beschaffte diese Weissagungsrolle, um die verantwortliche Person zu identifizieren. Indem die Magie der Rolle durch intakte Elementararmschienen als fokussierendes Reagenz kanalisiert wird, extrahiert der Benutzer die Signatur des Beschwörers und verwandelt das leere Pergament in eine Gefundene Rolle, die den Schuldigen benennt."}},faq={{q="Wofür wird die Rolle der Bestimmung verwendet?",a="Die Rolle dient dazu, herauszufinden, wer die verderbten Wasserelementare erschaffen hat, die Ashenvale heimsuchen. Unter Verwendung intakter Elementararmschienen als Fokus kanalisiert das Pergament Wahrsagemagie, um die Aura des Zaubernden zu lesen und dessen Identität festzuhalten.",al={"was macht die rolle","rolle der bestimmung zweck","warum rolle der bestimmung nutzen"}},{q="Wer vergibt die Rolle der Bestimmung?",a="Schildwache Velene Starstrike übergibt die Rolle an Ermittler der Allianz in der Silberwindzuflucht im südlichen Ashenvale während ihrer Untersuchung der verunreinigten Gewässer.",al={"wer gibt rolle der bestimmung","woher bekommt man die rolle","velene starstrike rolle"}},{q="Warum werden intakte Elementararmschienen benötigt?",a="Die meisten Armschienen zersplittern im Kampf bis zur Unkenntlichkeit. Nur eine Handvoll intakter Armschienen birgt noch genügend restliche Bindungsmagie ihres Beschwörers, um als adäquater arkaner Fokus für den Weissagungszauber zu dienen.",al={"warum armschienen","intakte elementararmschienen","reagenz für rolle"}},{q="Was passiert nach der Verwendung der Rolle?",a="Sobald sie in Gegenwart von fünf intakten Armschienen aktiviert wird, wird der Gegenstand verbraucht und verwandelt sich in eine Gefundene Rolle, die offenbart, dass ein abtrünniger Magier die verderbten Elementare vorsätzlich in die Seen des Waldes beschwört.",al={"gefundene rolle","nach nutzung der rolle","in was verwandelt sie sich"}}},fp="15,245,28.456.0,37.231.0,33.165.0,40.205.0,38.207.1"}
P.entries["item:dogran-s-pendant"] = {n="Dograns Anhänger",s="Dograns Anhänger ist ein zutiefst persönlicher Talisman, der von dem gefallenen Orc Dogran getragen wurde und an die Tragödie seiner verlorenen Liebe Zankaja gebunden ist. In den schattenhaften Zirkeln der Hexenmeister von Orgrimmar wird die rohe emotionale Resonanz des Anhängers als Katalysator genutzt, um eine Sukkubus anzulocken und zu binden.",h="Dograns Anhänger ist ein zutiefst persönlicher Talisman, der von dem gefallenen Orc Dogran getragen wurde und...",kw={"cleft of shadow","dogran","dograns anhänger","gan'rul bloodeye","orgrimmar","sukkubus","die bindung","zankaja"},ang={["class:Warlock"]="Für Hexenmeister der Horde ist Dograns Anhänger der zentrale Talisman, um die Beherrschung des Nethers zu beweisen und das Ritual zur Beschwörung einer Sukkubus zu erlernen.",["faction:Horde"]="Der Anhänger symbolisiert die stillen persönlichen Tragödien, die sich im Brachland und in Durotar abspielen, eng verknüpft mit dem verborgenen Hexenmeisterzirkel, der in Orgrimmar agiert."},sec={{t="Ein Kanal des Herzschmerzes",b="Dograns Anhänger ist von persönlichem Kummer durchdrungen und markiert das tragische Schicksal eines Orcs, dessen Liebe zu Zankaja in Gefangenschaft und Tod endete. Für die Hexenmeister der Kluft der Schatten sind solch mächtige Emotionen nicht bloß Überreste von Trauer – sie sind magische Kanäle. Dämonen wie die Sukkubus weiden sich gierig an Liebe, Sehnsucht und Verletzlichkeit, was den Anhänger zu einem idealen Köder macht, um eine von ihnen durch den Wirbelnden Nether in Neeru Fireblades Beschwörungskreis zu ziehen."},{t="Unterwerfung und Gedenken",b="Unter der Anleitung von Gan'rul Bloodeye nutzt ein aufstrebender Hexenmeister den Anhänger, um den Dämon zu beschwören, ihn im Kampf zu unterwerfen und die absolute Beherrschung über seine verführerischen Manipulationen zu beweisen. Sobald das Ritual beendet ist, wird der Talisman an Gan'rul zurückgegeben, um wieder zu Zankaja gebracht zu werden, und dient als ernüchternde Mahnung, dass Übermut und verirrte Gefühle einen Hexenmeister schnell seine Seele kosten können."}},faq={{q="Wofür wird Dograns Anhänger verwendet?",a="Er dient als fokussierendes Reagenz, um eine Sukkubus in Neeru Fireblades Zelt in der Kluft der Schatten zu beschwören. Sobald der Dämon beschworen und besiegt ist, muss der Anhänger zu Gan'rul Bloodeye zurückgebracht werden.",al={"verwendung des anhängers","was mache ich mit dograns anhänger","dograns anhänger quest"}},{q="Warum reagiert eine Sukkubus auf den Anhänger?",a="Eine Sukkubus nährt sich von Begehren, Liebe und Leidenschaft und manipuliert diese. Da der Anhänger an die tragische Liebe zwischen Dogran und Zankaja gebunden ist, wirkt sein emotionales Gewicht als unwiderstehlicher Köder durch den Nether.",al={"warum sukkubus anhänger will","warum anhänger dämon beschwört","anhänger lore"}},{q="Wer war Dogran?",a="Dogran war ein Orc, dessen Gefangenschaft und Tod von Hexenmeistern der Horde über Kontakte wie Den blinden Cazul und Ken'zigla untersucht werden. Er hegte vor seinem vorzeitigen Ende eine tiefe romantische Bindung zu Zankaja.",al={"wer ist dogran","dogran geschichte"}},{q="Was geschieht mit dem Anhänger nach dem Beschwörungsritual?",a="Nachdem die beschworene Sukkubus besiegt wurde, bringt der Hexenmeister den Anhänger zu Gan'rul Bloodeye zurück, damit dieser das Relikt und den endgültigen Frieden zu Zankaja bringen kann.",al={"wer bekommt den anhänger","dograns anhänger abgeben"}}},fp="16,282,23.454.0,27.383.1,34.196.0,43.209.0,15.195.0,55.150.0"}
P.entries["item:dolanaar-delivery"] = {n="Dolanaar-Lieferung",s="Die Dolanaar-Lieferung ist ein Paket geernteter Kräuter, das von den druidischen Stätten von Shadowglen in das Dorf Dolanaar geschickt wird. Es wird jungen Reisenden anvertraut, die das geschützte Tal verlassen, und dient als einfache Botenaufgabe, um sie mit Gastwirt Keldamyr weiter die Straße hinunter in Kontakt zu bringen.",h="Die Dolanaar-Lieferung ist ein Paket geernteter Kräuter, das von den druidischen Stätten von Shadowglen in...",kw={"aldrassil","lieferung","dolanaar","kräuter","keldamyr","porthannius","shadowglen"},ang={["profession:Herbalism"]="Die Lieferung verdeutlicht die stetige Nachfrage nach Pflanzen, die rund um Aldrassil geerntet werden, um die abgelegenen Siedlungen von Teldrassil zu versorgen.",["race:NightElf"]="Die Annahme des Pakets markiert einen Übergangsritus für junge Kaldorei, die über die schützenden Äste von Shadowglen hinaus in das weitere Reich treten."},sec={{t="Ein Bündel aus Shadowglen",b="Dieses Paket wurde in den schattigen Hainen von Aldrassil geerntet und enthält frische Kräuter, die für die Siedlung Dolanaar gesammelt wurden. Porthannius, der durch anhaltende Angelegenheiten unter den Druiden von Shadowglen aufgehalten wird, verlässt sich auf angehende Abenteurer, die auf der Straße nach Süden ziehen, um das Bündel sicher zu Gastwirt Keldamyr zu bringen."},{t="Willkommen am Herdfeuer",b="Die Zustellung des Pakets führt den Reisenden direkt vor die Schwelle des Gasthauses von Dolanaar. Keldamyr nimmt die Waren dankbar entgegen und nutzt den Austausch, um müde Wanderer an die Notwendigkeit von Rast, Seelenfrieden und die Zuflucht eines Gasthausfeuers zu erinnern, bevor sie tiefer nach Teldrassil vordringen."}},faq={{q="Was befindet sich in der Dolanaar-Lieferung?",a="Das Paket enthält eine Auswahl frischer Kräuter, die in Shadowglen gesammelt wurden und dazu bestimmt sind, Gastwirt Keldamyr und die Gäste des Gasthauses von Dolanaar zu versorgen.",al={"welche kräuter sind enthalten","inhalt der dolanaar-lieferung","was ist im paket"}},{q="Wer verschickt diese Lieferung?",a="Porthannius, ein Elf, der in Shadowglen Geschäfte mit den Druiden erledigt, bereitet das Bündel vor, kann aber nicht die Zeit erübrigen, selbst nach Süden zu reisen.",al={"wer gibt die lieferung","wer hat die kräuter geschickt","porthannius lieferung"}},{q="Wer nimmt das Paket in Dolanaar entgegen?",a="Die Lieferung wird direkt zu Gastwirt Keldamyr gebracht, der das gemeinschaftliche Gasthaus im Herzen von Dolanaar leitet.",al={"zu wem bringe ich die kräuter","empfänger der dolanaar-lieferung","keldamyr kräuter"}},{q="Warum konnte Porthannius das Paket nicht selbst zustellen?",a="Porthannius hat dringende, unvollendete Angelegenheiten mit den um Aldrassil stationierten Druiden, was ihn dazu zwingt, nach einem reisenden Abenteurer zu suchen, der auf der Waldstraße nach Süden unterwegs ist.",al={"warum porthannius bleibt","warum porthannius mich schickt"}}},fp="17,266,24.310.0,21.305.0,37.144.0,24.144.0,37.110.0,52.171.0"}
P.entries["item:dragonmaw-war-banner"] = {n="Kriegsflagge der Dragonmaw",s="Dragonmaw War Banners sind Feldzeichen, die von den im Sumpfland verschanzten Dragonmaw-Orcs mitgeführt werden. Versehen mit der Ikonografie ihres Clans, dienen sie den zwergischen Verteidigern aus dem Hafen von Menethil als Kampfbeleg bei dem Versuch, die wachsende Orc-Bedrohung einzudämmen.",h="Dragonmaw War Banners sind Feldzeichen, die von den im Sumpfland verschanzten Dragonmaw-Orcs mitgeführt...",kw={"dragonmaw","grim batol","menethil","nek'rosh","stoutfist","kriegsflagge","sumpfland"},ang={["faction:Alliance"]="Den Dragonmaw die Banner zu entreißen, schwächt einen alten Feind der Allianz, noch ehe er die schreckliche Stärke wiedererlangen kann, über die er während des Zweiten Krieges verfügte.",["race:Dwarf"]="Für die Zwerge von Khaz Modan ist die Beseitigung der Dragonmaw-Banner aus dem Marschland von entscheidender Bedeutung, um die Handelskorridore zum Hafen von Menethil vor orcischen Überfallkommandos zu schützen."},sec={{t="Embleme einer fortwährenden Bedrohung",b="Nach dem Zweiten Krieg wurde der Dragonmaw-Clan zerschlagen, als er die Kontrolle über seine versklavten roten Drachen verlor. Die wütenden Lindwürmer wandten sich gegen ihre Peiniger und vertrieben die Überlebenden aus Grim Batol in die östlichen Hügel. In jüngster Zeit haben die verbliebenen Orcs unter Kriegshäuptling Nek'rosh erneut begonnen, Kräfte zu sammeln, und ihre Kriegsflaggen über Lagern nordöstlich vom Hafen von Menethil gehisst. Diese groben, imposanten Standarten stehen sowohl für ihren anhaltenden Trotz als auch für eine direkte Bedrohung der Siedlungen im Marschland."},{t="Beweis der Eroberung",b="Captain Stoutfist, stationiert im Hafen von Menethil, beauftragt Abenteurer der Allianz damit, in die Sumpflager vorzustoßen und diese Banner zurückzubringen. Als Trophäen, die Räubern, Zenturionen und Knochenbehütern entrissen wurden, bestätigen die Banner der Zwergengarnison, dass die Lager der Dragonmaw systematisch zerschlagen werden, bevor der Clan koordinierte Überfälle starten kann."}},faq={{q="Warum will Captain Stoutfist diese Banner?",a="Captain Stoutfist verlangt die Banner als handfesten Beweis dafür, dass Abenteurer das Lager der Dragonmaw nordöstlich vom Hafen von Menethil angegriffen haben, was bestätigt, dass ihre Reihen dezimiert wurden.",al={"warum banner sammeln","kriegsflaggen zweck","warum stoutfist banner will"}},{q="Wer trägt die Dragonmaw War Banners?",a="Die Banner werden von verschiedenen Dragonmaw-Kämpfern in ihren Lagern im Sumpfland getragen, darunter Räuber, Sumpfläufer, Zenturionen, Kampfmeister, Schattenbehüter, Knochenbehüter und Kriegshäuptling Nek'rosh selbst.",al={"wer dragonmaw-banner fallenlässt","wo man kriegsflaggen bekommt","welche orcs banner haben"}},{q="Warum befinden sich die Dragonmaw-Orcs im Sumpfland?",a="Gegen Ende des Zweiten Krieges verloren die Dragonmaw die Kontrolle über ihre gefangenen roten Drachen. Die befreiten Drachen machten erbarmungslos Jagd auf ihre einstigen Herren und zwangen die überlebenden Orcs, aus ihrer Festung in Grim Batol zu fliehen und sich im Sumpfland sowie den umliegenden Bergen zu zerstreuen.",al={"warum dragonmaw hier sind","sumpfland dragonmaw geschichte","dragonmaw lore"}},{q="Wer führt den Dragonmaw-Clan jetzt an?",a="Der Clan wird von Kriegshäuptling Nek'rosh angeführt, dem Sohn ihres früheren Kriegshäuptlings Nekros. Nek'rosh hat Rache an den roten Drachen geschworen, die sich gegen seinen Vater wandten und ihn töteten.",al={"dragonmaw anführer","wer ist nek'rosh","kriegshäuptling nek'rosh"}}},fp="20,264,29.519.0,17.360.0,46.180.0,38.217.0,43.268.0,33.172.0"}
P.entries["item:dried-seeds"] = {n="Getrocknete Samenkörner",s="Getrocknete Samenkörner sind leblos wirkende Hüllen, die Reisenden vom Taurendruiden Tonga Runetotem im Crossroads überreicht werden. Sie dienen als experimentelles Medium, um die anomale, lebensspendende Kraft zu testen, die aus den Rissen unter den Gewässern des Brachlands emporblubbert.",h="Getrocknete Samenkörner sind leblos wirkende Hüllen, die Reisenden vom Taurendruiden Tonga Runetotem im...",kw={"brachland","blubbernder riss","crossroads","getrocknete samenkörner","die brackige oase","tonga runetotem"},ang={["class:Druid"]="Druiden, die das seltsame Pflanzenwachstum im Brachland untersuchen, erkennen in diesen toten Samen ein entscheidendes Werkzeug zur Erforschung der wilden, ungezähmten Energien, die aus der Erde emporsteigen.",["faction:Horde"]="Abenteurer der Horde unterstützen Tonga Runetotem dabei, die ökologischen Geheimnisse zu lüften, die den trockenen Boden des Brachlands verwandeln."},sec={{t="Die Samen und die Oase",b="Für das flüchtige Auge wirken diese verdorrten Samen vollkommen unfruchtbar und frei von jeglichem Leben. In den Händen von Tonga Runetotem sind sie jedoch ein unverzichtbares Instrument druidischer Forschung. Fasziniert von den seltsamen Unterwasserschloten, die bei den Vergessenen Teichen entdeckt wurden, möchte Tonga herausfinden, ob ähnliche Risse unter der Brackigen Oase im Südosten existieren. Indem man diese toten Samen in den blubbernden Riss taucht, kann man aus erster Hand die geheimnisvollen Energien bezeugen, die durch die Oasen des Brachlands strömen – Energien, welche die wundersame Fähigkeit besitzen, Leben dort hervorzubringen, wo keines mehr sein sollte."}},faq={{q="Wofür werden die Getrockneten Samenkörner verwendet?",a="Die Getrockneten Samenkörner werden verwendet, um die magischen, lebensspendenden Eigenschaften des blubbernden Risses tief in der Brackigen Oase zu testen. Indem Ihr die toten Samen dem Wasser des Risses aussetzt, prüft Ihr, ob die anomale Energie unter der Oase pflanzliches Leben wiedererwecken kann.",al={"getrocknete samenkörner verwendung","was tun mit getrockneten samenkörnern","getrocknete samenkörner zweck"}},{q="Wer vergibt die Getrockneten Samenkörner?",a="Sie werden Abenteurern von Tonga Runetotem überreicht, einem Taurendruiden, der im Crossroads im Brachland stationiert ist und das plötzliche, unnatürliche Erblühen der Region erforscht.",al={"wer gibt getrocknete samenkörner","woher stammen getrocknete samenkörner"}},{q="Wo befindet sich der Riss, an dem sie verwendet werden?",a="Der Riss liegt untergetaucht im Wasser der Brackigen Oase, die sich südöstlich von Crossroads im Brachland befindet.",al={"wo getrocknete samenkörner einpflanzen","die brackige oase riss ort","blubbernder riss getrocknete samenkörner"}},{q="Was geschieht, wenn die Samen dem Riss ausgesetzt werden?",a="Die latente Energie des blubbernden Risses stellt die Vitalität der toten Hüllen auf wundersame Weise wieder her und bestätigt Tongas Theorie, dass unter den Oasen des Brachlands eine außergewöhnliche Kraft liegt, die aus dem Nichts Leben erschaffen kann.",al={"wachsen die samen","getrocknete samenkörner ergebnis"}}},fp="11,247,23.583.0,34.261.0,29.181.0,36.129.0,55.219.1"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="Durnans kochend heißes Morgengebräu",s="Durnans kochend heißes Morgengebräu ist ein frisch eingeschenktes, kochend heißes Zwergengetränk, das für Durnan Furcutter im Coldridgetal bestimmt ist. Da das Getränk in der eisigen Bergluft schnell seine Hitze verliert, muss es direkt nach Anvilmar gebracht werden, bevor es erkaltet.",h="Durnans kochend heißes Morgengebräu ist ein frisch eingeschenktes, kochend heißes Zwergengetränk, das für...",kw={"anvilmar","das coldridgetal","dun morogh","durnan furcutter","morgengebräu","kochend heiß"},ang={["race:Dwarf"]="Für einen Zwerg aus Dun Morogh gibt es kaum ein größeres Vergehen, als gutes Bier oder Morgengebräu im Bergfrost erkalten zu lassen."},sec={{t="Ein Wettlauf gegen die Kälte",b="In der schneidenden Kälte des Coldridgetals können nur wenige Annehmlichkeiten mit einem Becher frischen Morgengebräus mithalten, das kochend heiß serviert wird. Als sich ein Bote bei der Lieferung einer Runde an Grelin Whitebeard verspätet, droht der frische Becher, der für Durnan Furcutter in Anvilmar bestimmt ist, einzufrieren. Durnan erwartet sein Gebräu ausdrücklich kochend heiß, sodass nur ein kurzes Zeitfenster von wenigen Minuten bleibt, um den dampfenden Becher den verschneiten Pfad hinauf in die Berghalle zu tragen, bevor er vollständig abkühlt."}},faq={{q="Für wen ist das Gebräu bestimmt?",a="Das Gebräu ist für Durnan Furcutter bestimmt, einen Zwerg, der in der Siedlung Anvilmar im Coldridgetal stationiert ist.",al={"wer bekommt morgengebräu","durnan morgengebräu empfänger","wohin geht gebräu"}},{q="Warum muss die Lieferung so schnell erfolgen?",a="Die eisige Luft von Dun Morogh entzieht offenen Bechern rasch die Wärme. Durnan hat ausdrücklich kochend heißes Morgengebräu bestellt, und ein ungeheizter oder lauwarmer Becher wird ihn schlichtweg nicht zufriedenstellen.",al={"warum zeitlimit","gebräu wird kalt","warum morgengebräu beeilen"}},{q="Wo beginnt die Lieferung?",a="Das Getränk wird in der Nähe von Grelin Whitebeards Lager außerhalb von Anvilmar übergeben, nachdem der Bote erkennt, dass er die Schmiedehalle allein nicht rechtzeitig erreichen kann.",al={"woher kommt morgengebräu","wer schenkt das gebräu ein"}},{q="Was geschieht, sobald Durnan den Becher erhält?",a="Durnan unterbricht unverzüglich seine Pflichten in Anvilmar, um das dampfende Getränk zu genießen, solange es noch heiß ist.",al={"durnan reaktion","morgengebräu abgeben"}}},fp="26,255,23.436.0,29.112.0,48.170.0,34.152.0,42.124.0"}
P.entries["item:durotar-tiger-fur"] = {n="Durotar-Tigerfell",s="Durotar-Tigerfell wird von den wilden Tigern erbeutet, die die tropischen Echoinseln vor der Südostküste von Durotar durchstreifen. Die Darkspear sind stark auf diese Pelze angewiesen, um Kälteschutzdecken, robuste Zelte und widerstandsfähige Rüstungen herzustellen, während ihre Flüchtlingsbevölkerung stetig wächst.",h="Durotar-Tigerfell wird von den wilden Tigern erbeutet, die die tropischen Echoinseln vor der Südostküste von...",kw={"durotar-tiger","durotar-tigerfell","die echoinseln","praktische beute","sen'jin","trollpelz","vel'rin fang"},ang={["class:Hunter"]="Das Anschleichen an die Tiger der Echoinseln spiegelt klassische trollische Jagdriten wider und erfordert immense Geduld sowie Tarnung, um diesen lautlosen Inselfressfeinden aufzulauern.",["race:Troll"]="Für die Darkspear ist die Beschaffung von Tigerfellen eine doppelte Erinnerung: an ihren alltäglichen Überlebenskampf in Sen'jin und an den schmerzhaften Verlust ihrer rechtmäßigen Heimat auf den Echoinseln."},sec={{t="Eine lebenswichtige Ressource für die Darkspear",b="In der überfüllten Siedlung Sen'jin sind die Ressourcen stets knapp bemessen. Die Darkspear wägen das Überleben ihres Volkes gegen das empfindliche Ökosystem ihrer neuen Heimat ab und lassen die lokalen Tigerpopulationen ganz bewusst gedeihen, bis wachsende Bedürfnisse eine Ausdünnung erfordern. Die dicken, strapazierfähigen Felle der Durotar-Tiger werden sorgfältig gegerbt, um alltägliche Überlebensgüter herzustellen – von einfacher Schutzrüstung bis hin zu wärmenden Decken, die den Stamm bei jahreszeitlichen Wetterumschwüngen schützen."},{t="Die Jagd auf den Echoinseln",b="Um diese Pelze zu gewinnen, muss das offene Meer zu den Echoinseln überquert werden – dem üppigen Archipel südlich von Durotar, den die Darkspear einst ihre Heimat nannten, bevor der Hexendoktor Zalazane sie vertrieb. Neben den Gefahren, die von Zalazanes Knechten ausgehen, müssen Jäger im dichten Blätterdach auch mit der geduldigen, räuberischen Natur der Tiger selbst rechnen. Erfahrene Trolljäger wie Vel'rin Fang berichten davon, ganze Tage regungslos im Dschungeldickicht zu verharren, nur um einen einzigen sauberen Treffer zu landen."}},faq={{q="Woher bekommt man Durotar-Tigerfelle?",a="Sie werden durch das Erjagen von Durotar-Tigern gesammelt, die auf den Echoinseln heimisch sind – dem Archipel vor der Südostküste von Durotar.",al={"wo droppen tigerfelle","fundort durotar-tigerfell","wie man tigerfelle bekommt"}},{q="Warum benötigen die Trolle von Sen'jin diese Felle?",a="Vel'rin Fang aus Sen'jin sammelt sie, um die wachsende Siedlung der Darkspear mit Decken, Zelten und schützender Lederrüstung zu versorgen und sicherzustellen, dass der Stamm bei jahreszeitlichen Wetterwechseln nicht leidet.",al={"warum tigerpelze sammeln","wer braucht tigerfell","zweck von praktische beute"}},{q="Warum überjagen die Trolle die Tiger nicht?",a="Die Darkspear lassen die Tigerpopulation bewusst auf natürliche Weise gedeihen und leiten Ausdünnungen nur dann ein, wenn die Vorräte der Gemeinschaft zur Neige gehen und die Bestände an Unterkünften oder Kleidung durch die wachsende Bevölkerung erschöpft sind.",al={"tigerschutz","den bestand ausdünnen"}}},fp="17,283,34.484.0,22.492.0,38.139.0,53.203.0,41.206.0"}
P.entries["item:duskbat-wing"] = {n="Nachtsaugerflügel",s="Ein Nachtsaugerflügel ist ein Rohmaterial, das von den lederflügeligen Fledermäusen erbeutet wird, die durch die Düsternis rund um Deathknell flattern. In der an Ressourcen armen Verlassenen-Siedlung werden diese lederartigen Gliedmaßen geborgen und von örtlichen Schneidern zu robuster, behelfsmäßiger Rüstung für neuerweckte Soldaten umfunktioniert.",h="Ein Nachtsaugerflügel ist ein Rohmaterial, das von den lederflügeligen Fledermäusen erbeutet wird, die durch...",kw={"deathknell","nachtsauger","nachtsaugerflügel","novize elreth","aasfressertatze","die verdammten","tirisfal"},ang={["profession:Tailoring"]="Novize Elreth demonstriert die behelfsmäßige Überlebensschneiderei, die in Tirisfal erforderlich ist, indem er zähe Fledermausflügel als brauchbaren Leder- und Stoffersatz nutzt.",["race:Undead"]="Für frisch erweckte Verlassene ist das Sammeln dieser Flügel eine der allerersten Überlebensaufgaben, um sicherzustellen, dass Ihr in Euren ersten Scharmützeln nicht in Stücke fallt."},sec={{t="Improvisierter Schutz in Deathknell",b="Wenn sich neue Untote ihren Weg aus der Erde von Deathknell bahnen, tragen sie kaum mehr als Lumpen und spröde Knochen am Leib. Umgeben von den geistlosen Überresten der Geißel und einer feindseligen Tierwelt müssen die frischgebackenen Verlassenen jede Schutzausrüstung zusammenkratzen, die sie finden können. Novize Elreth, Gehilfe von Schattenpriester Sarvis, sammelt Nachtsaugerflügel zusammen mit Wolfspfoten, um Kleidung und Rüstung für frisch erweckte Krieger zusammenzuflicken und zu verstärken, bevor sie zum Kämpfen in die Wildnis geschickt werden."}},faq={{q="Wofür werden Nachtsaugerflügel verwendet?",a="In Deathknell verwendet Novize Elreth Nachtsaugerflügel zusammen mit Aasfresserpfoten als Rohmaterial, um Rüstungen und Kleidungsstücke für neuerweckte Rekruten der Verlassenen herzustellen, auszubessern und zu verstärken.",al={"nachtsaugerflügel verwendung","warum nachtsaugerflügel sammeln","zweck von nachtsaugerflügeln"}},{q="Woher stammen Nachtsaugerflügel?",a="Sie werden von Nachtsaugern und Ranzigen Nachtsaugern erbeutet, die die Haine und Hügel rund um das Dorf Deathknell in Tirisfal heimsuchen.",al={"wo man nachtsaugerflügel findet","nachtsaugerflügel quelle","wer lässt nachtsaugerflügel fallen"}},{q="Wer verlangt diese Flügel in Deathknell?",a="Novize Elreth, der in der Kapelle von Deathknell unter der Leitung von Schattenpriester Sarvis die Verwundeten versorgt und Ausrüstung herstellt, bittet die Rekruten darum, sie zu sammeln.",al={"wer braucht nachtsaugerflügel","nachtsaugerflügel abgeben","nachtsaugerflügel questgeber"}},{q="Warum verlassen sich die Verlassenen bei Rüstungen auf Fledermausteile?",a="Deathknell verfügt über so gut wie keine Nachschublinien oder traditionelle Fertigung. Die örtlichen Verwalter müssen zähe Felle, Pelze und lederartige Fledermausflügel von den einheimischen Raubtieren Tirisfals plündern, um rudimentäre Schutzkleidung für Rekruten zu schneidern, die in den Kampf ziehen.",al={"warum fledermausflügel für rüstung","fledermauslederrüstung verlassene"}}},fp="12,287,35.494.0,32.176.0,33.149.0,39.159.0,48.251.0"}
P.entries["item:dusky-crab-cakes"] = {n="Schwärzliche Krebsküchlein",s="Schwärzliche Krebsküchlein sind ein herzhaftes Gericht, das von Küchenchef Grual in Dunkelhain zubereitet wird, um den verzweifelten Hunger von Jitters zu stillen. Trotz ihres appetitlichen Namens wird die lokale Delikatesse tatsächlich aus klebrigen Spinnenbeinen zubereitet, die in den schattigen Wäldern gesammelt wurden. Ohne die wahren Zutaten zu kennen, hält der ausgehungerte Jitters sie für eine exquisite Mahlzeit.",h="Schwärzliche Krebsküchlein sind ein herzhaftes Gericht, das von Küchenchef Grual in Dunkelhain zubereitet...",kw={"dunkelhain","dämmerwald","schwärzliche krebsküchlein","grual","jitters","spinnenbeine"},ang={["profession:Cooking"]="Gruals Rezept beweist, dass ein kreativer Koch die Gliedmaßen riesiger Waldspinnentiere als Ersatz für Küstenkrabben verwenden kann, wenn die Zutaten knapp werden."},sec={{t="Eine fragwürdige Delikatesse",b="In der Düsternis des Dämmerwalds sind frische Vorräte rar und Köche müssen sich mit dem Fleisch begnügen, das der verfinsterte Wald hergibt. Als der verängstigte Herumtreiber Jitters von Hunger geplagt wird, bereitet Küchenchef Grual eine Portion seiner typischen „Krabbenküchlein“ zu. Für jeden Außenstehenden wirkt das Gericht wie ein harmloses Meeresfrüchte-Patty, doch Gruals Geheimzutat ist weit weniger appetitlich: die sehnigen, klebrigen Beine der monströsen Spinnentiere des Dämmerwalds. Die Küchlein werden von dem ausgehungerten Jitters rasch verschlungen, der völlig ahnungslos ist, was er da eigentlich isst."}},faq={{q="Woraus bestehen Schwärzliche Krebsküchlein eigentlich?",a="Obwohl sie Krebsküchlein genannt werden, bestehen sie heimlich aus klebrigen Spinnenbeinen, die von den riesigen Spinnentieren gesammelt wurden, die im Dämmerwald umherstreifen. Küchenchef Grual verwendet das Spinnenfleisch als Ersatz für echte Meeresfrüchte.",al={"krebsküchlein zutaten","was ist in schwärzlichen krebsküchlein","spinnenfleisch"}},{q="Wer isst die Schwärzlichen Krebsküchlein?",a="Die Küchlein werden für Jitters zubereitet, einen ängstlichen Mann, der in Dunkelhain Schutz sucht und über einen heftig knurrenden Magen klagt.",al={"wer bekommt die krebsküchlein","für wen sind diese","jitters essen"}},{q="Weiß Jitters, dass die Küchlein aus Spinnenbeinen bestehen?",a="Nein. Jitters hungert und verschlingt sie voller Freude, ohne das Rezept zu hinterfragen; er ist schlicht dankbar, dass sie genau das Richtige sind.",al={"weiß jitters bescheid","weiß er dass es spinne ist","jitters reaktion"}},{q="Wer kocht die Schwärzlichen Krebsküchlein?",a="Küchenchef Grual, der ansässige Koch in der Scarlet Raven Tavern in Dunkelhain, bereitet das Gericht mit den Spinnenbeinen zu, die man ihm bringt.",al={"wer macht die krebsküchlein","küchenchef grual","koch dunkelhain"}}},fp="16,329,23.544.1,43.202.0,30.127.0,52.118.0,31.127.0"}
P.entries["item:dust-devil-debris"] = {n="Staubteufeltrümmer",s="Staubteufeltrümmer bestehen aus dem wirbelnden Sand und den elementaren Überresten, die von den aggressiven Luftgeistern hinterlassen werden, die durch Westfall streifen. Magier schätzen diese geladenen Partikel als magische Reagenzien und nutzen ihre luftige Essenz, um Pergament zu verzaubern und Botschaftszauber in Schriftrollen zu binden.",h="Staubteufeltrümmer bestehen aus dem wirbelnden Sand und den elementaren Überresten, die von den aggressiven...",kw={"collin mauren","staubteufeltrümmer","staubteufel","botschaftszauber","schriftrolle","stormwind","westfall"},ang={["class:Mage"]="Staubteufeltrümmer veranschaulichen, wie elementare Überreste für praktische Schreibkunst und Kommunikationszauber kanalisiert werden können, wodurch das rohe elementare Chaos mit verfeinerter arkaner Disziplin verbunden wird."},sec={{t="Aus Luft gewobenes Pergament",b="Die trockenen Ebenen von Westfall sind zunehmend unruhiger geworden, heimgesucht von heftigen Wirbelwinden, die als Staubteufel bekannt sind. Werden sie niedergestreckt, fallen diese lebendigen Stürme zu einem Haufen geladenen Staubs und Sandes zusammen, der als Staubteufeltrümmer bezeichnet wird. Anstatt bloßer Schmutz zu sein, behalten diese Rückstände eine schwache Spur des elementaren Wirbels, der ihnen Leben einhauchte. Arkananwender wie Collin Mauren in Stormwind schätzen solches Material für spezialisierte Zauberei. Durch das Einflößen des Sandes in verzauberte Tinte und Pergament kann ein Zauberer einen luftigen Botschaftszauber auf eine Schriftrolle binden, was eine Fernkommunikation über das gesamte Königreich hinweg ermöglicht."}},faq={{q="Wofür werden Staubteufeltrümmer verwendet?",a="Collin Mauren, ein Zauberer, der im Mage Quarter von Stormwind ansässig ist, benötigt diese elementaren Trümmer, um eine spezielle Botschaftsschriftrolle herzustellen. Die verbleibende elementare Energie im Staub ermöglicht es ihm, feingliedrige Kommunikationsmagie auf Papier zu prägen.",al={"staubteufeltrümmer verwendung","warum staubteufeltrümmer beschaffen","trümmer zweck"}},{q="Woher stammen diese Trümmer?",a="Sie werden aus den Überresten von Staubteufeln geborgen, feindseligen Luftelementaren, welche die kargen Ackerflächen und Straßen von Westfall durchstreifen.",al={"wo trümmer finden","staubteufel beute","westfall trümmer"}},{q="Warum gibt es überhaupt Staubteufel in Westfall?",a="Da Westfall seit Jahren unter Dürre, Vernachlässigung und politischem Chaos leidet, ist das Land selbst instabil geworden. Rastlose Luftgeister nehmen als gewalttätige Wirbelwinde über den verlassenen Feldern Gestalt an und bedrohen Reisende wie auch einheimische Bauern gleichermaßen.",al={"warum elementare in westfall","ursprung der staubteufel in westfall"}},{q="Wer ist Collin Mauren?",a="Collin Mauren ist ein menschlicher Magier, der im Mage Quarter von Stormwind tätig ist. Er stellt seine arkane Expertise zur Verfügung, um verzauberte Schriftrollen und magische Komponenten für andere Praktizierende und neugierige Forscher herzustellen.",al={"collin mauren","wer braucht trümmer"}}},fp="17,275,23.592.0,35.248.0,33.125.0,39.233.0,21.207.0"}
P.entries["item:dwarven-tinder"] = {n="Zwergenzunder",s="Zwergenzunder ist eine speziell präparierte, brennbare Substanz, die von Streitkräften der Allianz im Sumpfland verwendet wird. Er wurde an Saboteure verteilt, die damit beauftragt waren, die Belagerungsmaschinen des Dragonmawklans einzuäschern, bevor diese gegen den Hafen von Menethil eingesetzt werden konnten.",h="Zwergenzunder ist eine speziell präparierte, brennbare Substanz, die von Streitkräften der Allianz im...",kw={"katapulte","dragonmaw","zwergenzunder","der hafen von menethil","nek'rosh","sabotage","sumpfland"},ang={["faction:Alliance"]="Da die Pässe von Dun Algaz umkämpft sind, ist das Verbrennen feindlicher Kriegsmaschinen, bevor sie den Hafen von Menethil erreichen, unerlässlich, um den wichtigsten Sumpfhafen der Allianz zu halten.",["race:Dwarf"]="Zwergische Ingenieure und Späher wissen um den Wert verlässlicher Feueranzünder, insbesondere in den ewig durchnässten, regengepeitschten Mooren des Sumpflands."},sec={{t="Sabotage am Dragonmawklan",b="Als Späher der Allianz entdeckten, dass Häuptling Nek'rosh im Lager des Dragonmawklans schwere Katapulte konstruiert hatte, sah sich der Hafen von Menethil einer unmittelbaren Krise gegenüber. Durch heftige Kämpfe in Dun Algaz von südlicher Verstärkung abgeschnitten, konnten die Verteidiger einer längeren Belagerung nicht standhalten. Die Lösung war präventive Sabotage. Zwergenzunder, der Freiwilligen beim Vorstoß in orkisches Territorium ausgehändigt wird, fängt durch einen geschlagenen Funken rasch Feuer und erzeugt Flammen, die intensiv genug sind, um verstärkte hölzerne Belagerungsmaschinen innerhalb von Minuten zu verzehren."}},faq={{q="Wofür wird Zwergenzunder verwendet?",a="Zwergenzunder wird verwendet, um die vom Dragonmawklan im Sumpfland gebauten Belagerungskatapulte zu entzünden und zu zerstören, wodurch ein Artillerieangriff auf den Hafen von Menethil verhindert wird.",al={"zweck von zwergenzunder","warum zwergenzunder verwenden","was bewirkt zwergenzunder"}},{q="Warum werden die Katapulte verbrannt, anstatt sie zu erbeuten?",a="Die Garnison des Hafens von Menethil ist stark in der Unterzahl und aufgrund der Blockade bei Dun Algaz von Verstärkungen aus Ironforge abgeschnitten. Die Verteidiger verfügen nicht über die nötigen Streitkräfte, um schwere Belagerungsmaschinen tief im feindlichen Gebiet des Dragonmawklans zu erobern oder zu bergen, weshalb ihre Zerstörung die einzig gangbare Verteidigung darstellt.",al={"warum die katapulte zerstören","warum nicht die belagerungsmaschinen nehmen"}},{q="Wer hat diesen Zunder vorbereitet?",a="Der Zunder wird von der im Hafen von Menethil stationierten Zwergengarnison bereitgestellt und speziell für eine schnelle, zuverlässige Entzündung bei militärischen Sabotageeinsätzen präpariert.",al={"wer stellte den zunder her","woher stammt der zwergenzunder"}}},fp="14,245,24.517.0,32.161.0,49.289.0,25.158.0"}
P.entries["item:ear-of-balgaras"] = {n="Balgaras' Ohr",s="Balgaras' Ohr dient als düsterer Beweis für den Tod von Balgaras dem Niederträchtigen, einem Hexenmeister der Dunkeleisenzwerge, der den Angriff auf Dun Modr anführte. Vom Leichnam des feigen Kommandanten geborgen, bringt es den Gebirgsjägern von Ironforge, die das nördliche Sumpfland verteidigen, Gewissheit und Abschluss.",h="Balgaras' Ohr dient als düsterer Beweis für den Tod von Balgaras dem Niederträchtigen, einem Hexenmeister der...",kw={"balgaras der niederträchtige","dunkeleisenzwerge","dun modr","balgaras' ohr","longbraid der grimmige","thandol-übergang","sumpfland"},ang={["class:Warlock"]="Balgaras wirkte Schatten- und Dämonenkünste aus dem Verborgenen heraus, sodass sein Sieg dem Niederstrecken eines ruchlosen Praktizierenden gleicht, der Unheil über die nördliche Straße gebracht hat.",["race:Dwarf"]="Für die Zwerge von Ironforge begleicht das Einfordern dieses Ohrs eine blutige Rechnung für die Verwandten, die während der Sabotage am Thandol-Übergang niedergemetzelt wurden."},sec={{t="Eine grimmige Trophäe",b="Dun Modr verfiel in Trümmer, als Invasoren der Dunkeleisenzwerge den Thandol-Übergang sabotierten und die örtliche Zwergengarnison auslöschten. Ihr Kommandant auf dem Schlachtfeld war Balgaras der Niederträchtige, ein ränkeschmiedender Hexenmeister, der seine Truppen aus den Schatten heraus lenkte, während er den persönlichen Kampf scheute. Für Longbraid den Grimmigen, den Offizier des Bergkönigs, der außerhalb des zerstörten Vorpostens stationiert ist, verlangte die Gerechtigkeit greifbare Beweise für den Fall des Rädelsführers. Das Abtrennen von Balgaras' Ohr liefert die unumstößliche Bestätigung, dass die Schreckensherrschaft des Hexenmeisters an der nördlichen Grenze beendet ist."},{t="Gerechtigkeit für die Gefallenen",b="Der Verlust von Dun Modr kostete Longbraid seinen Bruder sowie Dutzende tapfere Soldaten, die beim Einsturz der Westbrücke ums Leben kamen. Das Überbringen des Ohrs des Hexenmeisters repariert zwar weder den zerstörten Übergang noch erweckt es die Gefallenen wieder zum Leben, doch es destabilisiert die überlebenden Dunkeleisentruppen, die im nördlichen Sumpfland verstreut sind. Ohne Balgaras, der sie anleitet, können die Späher von Ironforge die verbleibenden Angreifer weitaus leichter in Schach halten, bevor ein neuer Kommandant aus dem Süden entsandt wird."}},faq={{q="Wer war Balgaras der Niederträchtige?",a="Balgaras der Niederträchtige war ein Hexenmeister der Dunkeleisenzwerge, der die Kriegsschar befehligte, die Dun Modr überfiel und die Westbrücke des Thandol-Übergangs zerstörte. Berüchtigt für seine Feigheit schickte er Wellen von Soldaten in den Tod, während er sich selbst vor Patrouillen der Allianz verborgen hielt.",al={"wer ist balgaras","balgaras lore","balgaras der niederträchtige"}},{q="Warum verlangt Longbraid der Grimmige ausdrücklich nach seinem Ohr?",a="Longbraid der Grimmige verlangte nach einem unanfechtbaren Beweis dafür, dass der schwer fassbare Hexenmeister tatsächlich getötet wurde. Ein abgetrenntes Ohr ist eine klassische Trophäe der Grenzkämpfe, die den Auftrag bestätigt, ohne dass der Überbringer einen ganzen Leichnam zurück in das Lager der Zwerge schleppen muss.",al={"warum ein ohr","warum das ohr abschneiden","longbraid beweis"}},{q="Was geschieht mit den Dunkeleisenzwergen, sobald Balgaras tot ist?",a="Beraubt ihres berechnenden Anführers verlieren die überlebenden Truppen der Dunkeleisenzwerge in Dun Modr ihren Zusammenhalt. Obwohl sie die Ruinen noch immer heimsuchen, glaubt Longbraid, dass sie nun desorganisiert genug sind, damit die Allianz die Lage kontrollieren kann, bevor die Feinde von Ironforge einen Ersatzkommandanten schicken können.",al={"was passiert nach balgaras' tod","dunkeleisenzwerge in dun modr"}}},fp="15,257,13.544.0,22.468.0,26.262.0,54.246.0,53.265.0"}
P.entries["item:ebonlocke-s-response-to-solomon"] = {n="Ebonlockes Antwort an Solomon",s="Ebonlockes Antwort an Solomon ist ein offizieller Brief aus der Feder von Lord Ello Ebonlocke, dem Bürgermeister von Dunkelhain. Nach Seenhain zurückgebracht, lehnt er das verzweifelte Ersuchen des Redridgegebirges um militärische Hilfe durch die Nachtwache rundheraus ab.",h="Ebonlockes Antwort an Solomon ist ein offizieller Brief aus der Feder von Lord Ello Ebonlocke, dem...",kw={"dunkelhain","dämmerwald","ebonlocke","seenhain","brief","bote","die nachtwache","redridge","solomon"},ang={["faction:Alliance"]="Der Brief offenbart den schieren Zusammenbruch des Kernlands der Allianz: Redridge, der Dämmerwald und Westfall wurden alle vom königlichen Hof in Stormwind im Stich gelassen."},sec={{t="Eine bittere Absage",b="Angesichts der Übergriffe der Blackrockorcs suchte Magistrat Solomon aus Seenhain nach Verstärkung aus dem Dämmerwald, nachdem Stormwind seine Gesuche ignoriert hatte. Lord Ello Ebonlockes Antwort ist vernichtend und kompromisslos. Ebonlocke betont, dass die Nachtwache nur deshalb existiert, weil Stormwind Dunkelhain im Stich ließ, als die verderbliche Magie die Wälder erstmals ergriff. Der Stadt ihre Verteidiger zu entziehen, um Redridge beizustehen, würde den Dämmerwald schutzlos zurücklassen und dafür sorgen, dass er dem Bösen anheimfällt, noch ehe die Miliz überhaupt den Waldrand erreicht."},{t="Die bröckelnde Grenze",b="Als Solomon den Brief erhält, erschüttert ihn diese Erkenntnis zutiefst. Da die Armee von Stormwind aus Westfall abgezogen wurde und die königliche Garde in Dunkelhain fehlt, ist die gesamte südliche Grenze des Königreichs der Verwahrlosung preisgegeben worden. Anstatt Ebonlockes Zorn abzutun, erkennt Solomon ein schreckliches Muster: Die plötzliche Vernachlässigung der abgelegenen Gebiete durch die Krone lässt auf Verrat auf den höchsten Machtebenen in Stormwind schließen."}},faq={{q="Was ist Ebonlockes Antwort an Solomon?",a="Es ist ein versiegelter Brief von Lord Ello Ebonlocke aus Dunkelhain, adressiert an Magistrat Solomon aus Seenhain. Darin weigert sich Ebonlocke, die Nachtwache zur Verteidigung von Redridge zu entsenden, und erklärt, dass der Dämmerwald seine eigenen Albträume kaum noch zurückhalten kann.",al={"ebonlocke brief","ebonlocke antwort","brief an solomon"}},{q="Warum schickt Dunkelhain keine Hilfe nach Seenhain?",a="Dunkelhain verfügt über keinerlei eigene königliche Truppen. Die Nachtwache wurde ausschließlich aus örtlichen Freiwilligen zusammengestellt, weil Stormwind die Region im Stich gelassen hat. Lord Ebonlocke warnt, dass Dunkelhain von Untoten und abscheulichen Kreaturen überrannt werden würde, noch bevor seine Wachen überhaupt den Wald verlassen hätten, sollten sie ausrücken.",al={"warum die nachtwache nicht hilft","warum hat dunkelhain abgelehnt","ebonlocke lehnt solomon ab"}},{q="Wie reagiert Magistrat Solomon auf den Brief?",a="Magistrat Solomon ist schockiert und beunruhigt. Die Nachricht, dass die königliche Garde Dunkelhain im Stich gelassen hat – genau wie sich die Armee aus Westfall zurückgezogen hat –, überzeugt ihn davon, dass finstere Machenschaften oder Verrat die Führung in Stormwind lähmen.",al={"solomons reaktion","was sagt solomon"}},{q="Wer hat diesen Brief geschrieben?",a="Der Brief wurde von Lord Ello Ebonlocke verfasst, dem bedrängten Bürgermeister von Dunkelhain und Anführer des Rats von Dunkelhain, der die Verteidigung der Stadt beaufsichtigt.",al={"wer ist ebonlocke","lord ebonlocke"}}},fp="31,225,16.500.0,22.425.1,40.249.0,43.286.0,48.223.1,22.153.0"}
P.entries["item:echeyakee-s-hide"] = {n="Echeyakees Balg",s="Echeyakees Balg ist das blasse Fell des legendären weißen Löwen, der im Brachland als Weißnebel bekannt ist. Von den Tauren als Verkörperung von Barmherzigkeit und Tod verehrt, dient der Balg bei Sergra Darkthorn im Crossroads als Beweis für das Können eines Jägers.",h="Echeyakees Balg ist das blasse Fell des legendären weißen Löwen, der im Brachland als Weißnebel bekannt ist.",kw={"brachland","crossroads","echeyakee","echeyakees balg","sergra darkthorn","weißer löwe","weißnebel"},ang={["class:Hunter"]="Das Fell des obersten Pürschers der Savanne zu erbeuten, ist ein früher Übergangsritus für Fährtenleser der Horde, die die Feinheiten der Wildnis meistern wollen.",["race:Tauren"]="Für die Tauren ist die Jagd auf Echeyakee eine heilige Prüfung der Gnade und Heimlichkeit, die den schnellen Geist von Weißnebel ehrt, anstatt bloße Eroberung zu suchen."},sec={{t="Trophäe von Weißnebel",b="In der Sprache Taur-ahe bedeutet Echeyakee Weißnebel. Das Raubtier verdiente sich diesen Titel unter den Savannenlöwen durch sein verstohlenes weißes Fell und die Schnelligkeit, mit der es Beute erlegte und deren Leben beendete, noch ehe Angst oder Schmerz einsetzen konnten. Um das Fell der Bestie zu erbeuten, muss die scheue Katze nahe riesigen Kodoknochen nordöstlich vom Crossroads mit einem zeremoniellen Horn herbeigerufen werden. Sergra Darkthorn diesen Balg zu überbringen bedeutet nicht nur, kriegerisches Geschick zu beweisen, sondern auch das lautlose, barmherzige Ende des Raubtiers zu ehren."}},faq={{q="Woher stammt Echeyakees Balg?",a="Der Balg wird durch das Erlegen von Echeyakee erbeutet, dem weißen Löwen, der inmitten riesiger Kodoskelette nordöstlich vom Crossroads im Brachland haust. Er muss mit dem Horn von Echeyakee herbeigerufen werden, das von Sergra Darkthorn bereitgestellt wird.",al={"woher bekommt man echeyakees balg","wie bekommt man echeyakees balg","echeyakee balg fundort"}},{q="Wer benötigt Echeyakees Balg?",a="Sergra Darkthorn, eine im Crossroads lebende Orc-Jägerin, beauftragt aufstrebende Jäger der Horde damit, die große Katze aufzuspüren und mit ihrem Fell zurückzukehren, um ihre Verbindung zur Wildnis zu beweisen.",al={"wer nimmt echeyakees balg an","echeyakees balg abgeben","wer braucht echeyakees balg"}},{q="Was bedeutet der Name Echeyakee?",a="In der Sprache der Tauren bedeutet Echeyakee übersetzt 'Weißnebel'. Der Name ehrt das blasse Fell der Katze und den Glauben, dass sie sich wie aufziehender Nebel über die Savanne bewegte und tötete, ohne langanhaltenden Schrecken oder Qualen zu verursachen.",al={"echeyakee übersetzung","bedeutung von echeyakee","tauren name echeyakee"}}},fp="16,250,19.499.0,38.216.0,27.183.0,34.217.0"}
P.entries["item:egalin-s-grimoire"] = {n="Egalins Zauberfoliant",s="Egalins Zauberfoliant ist ein geschätzter arkaner Foliant, der die grundlegenden Riten beschreibt, die zur Beschwörung und Beherrschung eines Leerwandlers erforderlich sind. Von einem Meisterhexenmeister verfasst, dient er als unverzichtbares Lehrwerk im Tempel der Verdammten in Undercity.",h="Egalins Zauberfoliant ist ein geschätzter arkaner Foliant, der die grundlegenden Riten beschreibt, die zur...",kw={"carendin halgar","kreatur der leere","egalin","egalins zauberfoliant","perrine","tempel der verdammten","leerwandler"},ang={["class:Warlock"]="Egalins Zauberfoliant enthält die präzisen Techniken, die erforderlich sind, um einen Leerwandler aus dem Nether zu ziehen und Eurem Willen zu unterwerfen – ein entscheidender Übergangsritus für jeden Praktizierenden.",["race:Undead"]="Die Bergung des Buches entzieht dem fanatischen Scharlachroten Kreuzzug den Besitz eines mächtigen magischen Artefakts, das direkt von den Praktizierenden von Undercity gestohlen wurde."},sec={{t="Das Werk eines Meisters",b="Von dem Meisterbeschwörer Egalin verfasst, beschreibt dieses Grimoire den heiklen und gefährlichen Vorgang, ein Wesen des Chaos aus dem Nether zu ziehen. Egalin war unter Praktizierenden für seine mühelose Beherrschung beschworener Leerwandler berühmt – eine Fähigkeit, die er an seine Schüler weitergab, darunter Carendin Halgar. Ohne die in diesem Werk niedergeschriebenen genauen Formeln und Kanalisierungsmethoden riskiert ein unvorbereiteter Beschwörer, von ebenjener Entität zerrissen zu werden, die er herbeiruft."},{t="Der scharlachrote Diebstahl",b="Das Grimoire wurde den Hexenmeistern der Verlassenen von einem Agenten des Scharlachroten Kreuzzugs namens Perrine gestohlen, der es in einer Kiste in einem Turm im westlichen Tirisfal versteckte. Trotz des Hasses der Fanatiker auf dunkle Magie schien der Dieb die wahre Tragweite des Buches kaum zu begreifen und behandelte es lediglich als beschlagnahmtes ketzerisches Beutegut, bis es von Initianden der Verlassenen geborgen wurde, die die Leere meistern wollten."}},faq={{q="Wer war Egalin?",a="Egalin war ein außergewöhnlich begabter Hexenmeister und der Mentor von Carendin Halgar. Man erinnert sich an ihn als den ersten unter ihnen, der einen Leerwandler beschwor, und dafür, dass er chaotische Entitäten mit absoluter Leichtigkeit beherrschte.",al={"wer ist egalin","egalin lore","wer schrieb das grimoire"}},{q="Warum ist Egalins Zauberfoliant so gefährlich?",a="Das Buch enthält die Beschwörungsformeln und Kanalisierungsmethoden, die nötig sind, um einen Leerwandler herbeizurufen. Versucht ein Hexenmeister das Ritual, ohne diese Anweisungen gründlich gemeistert zu haben, wird das beschworene Wesen der Leere ihn in Stücke reißen.",al={"was macht das grimoire","leerwandler foliant gefahr","warum gefaehrlich"}},{q="Wie gelangte der Scharlachrote Kreuzzug an das Buch?",a="Einem Agenten des Scharlachroten Kreuzzugs namens Perrine gelang es, den Folianten von den Hexenmeistern der Verlassenen zu stehlen. Er sperrte ihn in einer Kiste in einem Wachturm des Kreuzzugs im westlichen Tirisfal ein, offenbar ohne sich dessen wahren magischen Werts bewusst zu sein.",al={"wer stahl das buch","perrine zauberfoliant","warum haben es die kreuzfahrer"}},{q="Wer benötigt die Rückgabe dieses Grimoires?",a="Carendin Halgar, der Hexenmeisterlehrer, der im Tempel der Verdammten unterhalb von Undercity weilt, benötigt das Grimoire, um neuen Initianden beizubringen, wie man Leerwandler beschwört und bindet.",al={"wer will das grimoire","wer nimmt egalins grimoire an","carendin halgar buch"}}},fp="17,232,15.458.0,17.409.1,15.206.0,38.215.0,41.221.0,33.177.0"}
P.entries["item:electropeller"] = {n="Elektropeller",s="Ein Elektropeller ist ein spezialisiertes mechanisches Bauteil, das von dem Gnomen-Erfinder Wizbang Cranktoggle entwickelt wurde. Gedacht für den Antrieb einer explosiven Wasservogel-Attrappe, ging ein ganzer Beutel dieser Apparaturen bei einem unglückseligen nächtlichen Ausflug in den Süßwasserflüssen der Darkshore verloren.",h="Ein Elektropeller ist ein spezialisiertes mechanisches Bauteil, das von dem Gnomen-Erfinder Wizbang...",kw={"auberdine","cliffspring","darkshore","entenattrappe","elektropeller","der wildbend","wizbang cranktoggle"},ang={["profession:Engineering"]="Der Elektropeller ist klassische Gnomen-Tüftlerarbeit: ehrgeizig, motorisiert und gefährlich, entworfen für eine explosive Entenattrappe, die im Fluss landete, bevor sie jemals einen ordentlichen Testlauf absolvieren konnte.",["race:Gnome"]="Wizbang Cranktoggle führt die stolze Gnomentradition fort, wilden technischen Ehrgeiz mit verblüffenden Missgeschicken zu verbinden, indem er vorbeikommende Angler heiter darum bittet, die Ergebnisse seiner nächtlichen Experimente zu bergen."},sec={{t="Missgeschicke am Flussufer",b="Gnomeningenieurskunst erfordert Präzision, doch die Erfinder dahinter gehen nicht immer gleichermaßen methodisch vor. Wizbang Cranktoggle, ein exzentrischer Gnom, der von Auberdine aus operiert, ersann den Elektropeller als Antriebskomponente für eine experimentelle, selbstangetriebene, explodierende Entenattrappe. Als er nach dem einen oder anderen Drink zu viel die Gewässer der Darkshore erkundete, erlitt Cranktoggle einen Filmriss und kam Stunden später mit versengtem Haar und einem leeren Rucksack wieder zu Bewusstsein. Seine Sammlung von Elektropellern war in die Süßwasserströmungen gestürzt, sodass die Bauteile in den Flüssen und Seen der Darkshore verstreut blieben, bis geduldige Angler sie wieder bargen."}},faq={{q="Wofür wird ein Elektropeller verwendet?",a="Elektropeller sind motorisierte Antriebsmechanismen, die von Wizbang Cranktoggle entworfen wurden. Er erfand sie speziell, um eine experimentelle, selbstangetriebene, explodierende Entenattrappe anzutreiben, die er in der Darkshore entwickelte.",al={"elektropeller zweck","was macht ein elektropeller","warum entenattrappe"}},{q="Wie gelangten diese Teile in die Flüsse der Darkshore?",a="Wizbang Cranktoggle streifte nachts etwas berauscht durch die Darkshore, um nach einem Testgewässer zu suchen. Er verlor das Bewusstsein und wachte mit versengtem Haar wieder in Auberdine auf, nachdem er seinen gesamten Beutel voller Teile versehentlich in die Süßwasserströme fallen gelassen hatte.",al={"warum im wasser","wie gingen elektropeller verloren","cranktoggle fehler"}},{q="Wo können Elektropeller geborgen werden?",a="Sie treiben in den Binnensüßwassern der Darkshore, einschließlich des Cliffspring und des Wildbend, wo glückliche Angler sie aus dem Wasser fischen können.",al={"wo elektropeller angeln","elektropeller orte","cliffspring angeln"}},{q="Wer möchte diese Bauteile zurückhaben?",a="Wizbang Cranktoggle, ein in Auberdine ansässiger Gnom, benötigt zwölf von ihnen zurück, um seine Forschung an der Attrappe fortzusetzen.",al={"wer braucht elektropeller","wer ist cranktoggle","auberdine gnom quest"}}},fp="13,268,27.638.0,34.208.0,54.254.0,38.162.0,36.121.0"}
P.entries["item:elixir-of-pain"] = {n="Elixier der Schmerzen",s="Das Elixier der Schmerzen ist ein experimentelles alchemistisches Gebräu, das von in Tarrens Mühle stationierten Apothekern der Verlassenen hergestellt wird. Destilliert aus Blut, das im gesamten Vorgebirge gesammelt wurde, dient die Mischung dazu, biologische Kampfstoffe für die finsteren Pläne von Fürstin Sylvanas zu erproben.",h="Das Elixier der Schmerzen ist ein experimentelles alchemistisches Gebräu, das von in Tarrens Mühle...",kw={"apotheker","elixier der schmerzen","bauer ray","die felder von hillsbrad","königliche apothekervereinigung","stanley","sylvanas","tarrens mühle"},ang={["faction:Horde"]="Verbündete der Verlassenen werden oft herangezogen, um diese düsteren Tests zu unterstützen, und erleben so aus erster Hand die beunruhigenden Methoden der Forscher von Tarrens Mühle.",["race:Undead"]="Die rücksichtslosen Feldversuche der Königlichen Apothekervereinigung verdeutlichen die Entschlossenheit der Verlassenen, jedes erforderliche Mittel zur Entwicklung chemischer Waffen gegen die Lebenden einzusetzen."},sec={{t="Apotheker-Experimente",b="Die Königliche Apothekervereinigung arbeitet unermüdlich an neuen Rezepturen, um die Stellung der Verlassenen gegenüber ihren sterblichen Nachbarn und der Geißel zu stärken. Das Elixier der Schmerzen stellt einen solchen Versuch dar, gebraut aus frisch geernteten Zutaten aus dem Vorgebirge von Hillsbrad. Ohne Rücksicht auf die Lebenden zusammengebraut, dient der Trank als Machbarkeitsnachweis für explosive Substanzen, die der Dunklen Fürstin nutzen sollen."},{t="Feldtests an Stanley",b="Anstatt wertvolle militärische Ressourcen zu riskieren oder ihre Aktivitäten vor den Verteidigern von Hillsbrad frühzeitig zu offenbaren, suchen die Apotheker nach einem unauffälligen Testsubjekt. Das Elixier wird Stanley verabreicht, einem scheinbar harmlosen Haushund von Bauer Ray auf dem nördlichen Gehöft der Felder von Hillsbrad. Statt eines stillen Todes löst das giftige Gebräu jedoch eine brutale Mutation aus, die das arme Tier in einen rasenden, monströsen Wolf verwandelt."}},faq={{q="Was ist der Zweck des Elixiers der Schmerzen?",a="Das Elixier der Schmerzen ist ein experimenteller Trank, der entwickelt wurde, um biologische Wirkstoffe für die Königliche Apothekervereinigung zu testen. Seine Schöpfer hoffen, dass solche Rezepturen letztlich verheerende Gebräue hervorbringen, die Fürstin Sylvanas dienen und die Vorherrschaft der Verlassenen sichern.",al={"warum elixier der schmerzen herstellen","zweck des elixiers","was bewirkt das elixier"}},{q="Wer ist Stanley?",a="Stanley ist der Haushund von Bauer Ray auf dem nördlichen Bauernhof in den Feldern von Hillsbrad. Er wird von den Apothekern der Verlassenen als ahnungsloses Testobjekt auserwählt, um die physiologischen Auswirkungen ihres frisch gebrauten Elixiers zu beobachten.",al={"wer ist stanley","bauer ray hund","stanley hund"}},{q="Was passiert, wenn Stanley das Elixier trinkt?",a="Die flüchtigen Chemikalien im Elixier lassen Stanley gewaltsam zu einem wilden, bösartigen Wolf mutieren. Anstatt das Tier lediglich zu vergiften, verzerrt das Gebräu seine Gestalt und treibt es in eine aggressive Raserei.",al={"was passiert mit stanley","stirbt stanley","stanley wolf transformation"}},{q="Wo wird das Elixier getestet?",a="Der Test findet vor dem nördlichen Bauernhaus in den Feldern von Hillsbrad südwestlich von Tarrens Mühle statt. Stanley ruht für gewöhnlich nahe der Veranda von Bauer Rays Haus.",al={"wohin mit dem elixier","stanley aufenthaltsort","bauer ray bauernhof"}}},fp="14,273,26.416.0,24.395.1,42.247.0,15.223.0,44.211.1,27.178.0"}
P.entries["item:elixir-of-suffering"] = {n="Elixier des Leidens",s="Das Elixier des Leidens ist ein alchemistisches Gebräu, das von Apotheker Lydon in Tarrens Mühle hergestellt wird. Der im Auftrag der Royal Apothecary Society entwickelte Trank ist ein experimenteller Schritt auf dem Weg zu einer tödlichen Seuche, die sowohl lebende Menschen als auch die Geißel auslöschen soll.",h="Das Elixier des Leidens ist ein alchemistisches Gebräu, das von Apotheker Lydon in Tarrens Mühle hergestellt...",kw={"apotheker lydon","elixier des leidens","seuche der verlassenen","vorgebirge von hillsbrad","royal apothecary society","tarrens mühle","umpi"},ang={["race:Undead"]="Die Royal Apothecary Society arbeitet in ganz Lordaeron daran, eine Waffe zu erschaffen, die die Unabhängigkeit der Verlassenen von der Geißel und der lebenden Menschheit sichert, und Lydons giftige Experimente in Tarrens Mühle sind ein wesentlicher Schritt dahin."},sec={{t="Apotheker-Experimente",b="Im zerstörten Weiler Tarrens Mühle kombiniert Apotheker Lydon unermüdlich rohe Reagenzien aus der umliegenden Wildnis zu giftigen Tränken. Das Elixier des Leidens stellt einen frühen Meilenstein im übergeordneten Auftrag der Royal Apothecary Society dar: die Entwicklung einer neuen Seuche, die gleichermaßen Lebende wie Tote vernichten soll. Lydon testet das tödliche Gebräu an seinem unglückseligen Assistenten, einer Kröte namens Umpi, um dessen Wirksamkeit sicherzustellen."}},faq={{q="Was ist der Zweck des Elixiers des Leidens?",a="Das Elixier ist ein experimentelles Gebräu, das von Apotheker Lydon im Rahmen der Forschungen der Royal Apothecary Society hergestellt wird. Es soll tödliche Verbindungen testen, die für die neue Seuche der Verlassenen gegen die Menschheit und die Geißel bestimmt sind.",al={"warum elixier des leidens herstellen","was bewirkt das elixier","zweck des elixiers des leidens"}},{q="Wer ist Umpi?",a="Umpi ist eine gewöhnliche Kröte, die von Apotheker Lydon in Tarrens Mühle gehalten wird. Obwohl sie scherzhaft als Assistent bezeichnet wird, dient Umpi in erster Linie als unvorsätzliches Versuchsobjekt für frisch gebraute alchemistische Gifte.",al={"wer ist der frosch","wer ist die kröte","lydons assistent"}},{q="Was passiert, wenn Umpi das Elixier trinkt?",a="Nachdem der unglücklichen Amphibie das Elixier des Leidens verabreicht wurde, quakt sie und erliegt fast augenblicklich dem Gift, was die tödliche Wirksamkeit von Apotheker Lydons Rezeptur beweist.",al={"stirbt umpi","was passiert mit der kröte"}}},fp="19,273,26.437.0,47.232.0,12.202.0,41.186.1"}
P.entries["item:elune-s-tear"] = {n="Elunes Träne",s="Elunes Träne ist ein seltenes, leuchtendes Mineral, das auf der zentralen Insel des Irissees in Ashenvale gefunden wird. Da Nachtelfen-Kräuterkundige und -Heiler es als heiligen Segen der Mondgöttin verehren, suchen sie den Stein wegen seiner wirksamen Fähigkeit auf, magische Verderbnis und tödliche Krankheiten zu läutern.",h="Elunes Träne ist ein seltenes, leuchtendes Mineral, das auf der zentralen Insel des Irissees in Ashenvale...",kw={"ashenvale","astranaar","heilmittel","elunes träne","irissee","orendil","pelturas","relara"},ang={["class:Priest"]="Anhänger des Lichts und des Mondes erkennen die angeborene Macht des Steins an, Schatten und Fäulnis zu vertreiben, was die wiederherstellenden Wunder veranschaulicht, die der Priesterschaft der Elune zugeschrieben werden.",["race:NightElf"]="Für die Nachtelfen sind Reliquien, die den Namen von Elune tragen, heilige Gaben. Den Stein zur Rettung eines unschuldigen Kindes zu verwenden, spiegelt das ewige Band zwischen den Kaldorei und der heilenden Gnade der Mondmutter wider."},sec={{t="Ein heiliger Reinigungsstein",b="Abgeschieden auf der kleinen Insel im Irissee östlich von Astranaar gelegen, ist Elunes Träne ein mystischer Stein, von dem man glaubt, dass er die Reinheit der Mondgöttin selbst in sich trägt. Die umliegenden Gewässer und die Insel selbst werden von einheimischen Wasserelementaren heimgesucht, die von der allgegenwärtigen Naturmagie des Ortes angezogen werden. Der Stein ist unter den einheimischen Nachtelfen-Kräuterkundigen und -Heilern – wie Orendil Broadleaf – als Notfallheilmittel berühmt, das tief sitzende Verderbnis fortwaschen kann, wenn gewöhnliche Umschläge aus dem Wald versagen."},{t="Ein verzweifeltes Heilmittel",b="Als eine mysteriöse Auszehrungskrankheit die junge Nachtelfe Relara Whitemoon in Astranaar befällt, schöpft ihr Vater Pelturas alle gewöhnlichen Arzneien aus. Dem Rat des Apothekers Orendil folgend, sucht Pelturas nach Elunes Träne, um sie direkt zu einem stärkenden Sud zu brauen. Während dies unmittelbare Hoffnung gegen das seltsame Leiden schenkt, verlangt die hartnäckige Verderbnis, die Ashenvale plagt, oft nach noch größeren Reinigungsriten."}},faq={{q="Was ist Elunes Träne?",a="Elunes Träne ist ein seltenes magisches Mineral, das auf der Insel im Irissee in Ashenvale liegt. Nachtelfen betrachten es als heilige Reliquie, die von der reinigenden Berührung Elunes erfüllt ist und hauptsächlich dazu verwendet wird, unnatürliche Verderbnis und ansteckende Krankheiten zu heilen.",al={"elunes träne","was ist dieser stein","was bewirkt elunes träne"}},{q="Wo ist Elunes Träne zu finden?",a="Die Träne befindet sich auf der Insel inmitten des Irissees, östlich von Astranaar im zentralen Ashenvale gelegen. Reisende können sie erreichen, indem sie dem Bachpfad nördlich der Hauptstraße folgen.",al={"wo ist elunes träne","fundort stein irissee","elunes träne finden"}},{q="Warum benötigt Pelturas Whitemoon die Träne?",a="Pelturas sucht die Träne, um seine kranke Tochter Relara zu retten. Als herkömmliche Kräuterheilmittel die unnatürliche Krankheit, die ihren Körper befällt, nicht aufhalten können, rät der Apotheker Orendil, dass nur die wiederherstellende Reinheit des Steins das Leiden läutern kann.",al={"warum pelturas sie will","heilmittel relara","wer braucht elunes träne"}},{q="Was bewacht den Stein am Irissee?",a="Die Insel und die umliegenden Gewässer des Irissees werden von territorialen Wasserelementaren bewohnt, die von den unberührten und verzauberten Strömungen rund um die heilige Insel angezogen werden.",al={"gegner irissee","was schützt elunes träne"}}},fp="12,271,24.489.0,18.415.1,21.239.0,32.187.0,42.255.0,35.171.0"}
P.entries["item:embalming-ichor"] = {n="Einbalsamierungssekret",s="Einbalsamierungssekret ist eine unnatürliche Konservierungsflüssigkeit, die aus den Körpern der Rot Hide-Gnolle im nördlichen Tirisfal gewonnen wird. Sie erhält die belebte Existenz der Gnolle aufrecht und hat das große Interesse der Apotheker der Verlassenen geweckt, die ihre Eigenschaften analysieren wollen, um der Geißel entgegenzuwirken.",h="Einbalsamierungssekret ist eine unnatürliche Konservierungsflüssigkeit, die aus den Körpern der Rot...",kw={"apotheker","brill","einbalsamierungssekret","garrens schlupfwinkel","grabräuber","magistrat sevren","massengräber","rot hide"},ang={["profession:Herbalism"]="Die Konservierungsflüssigkeit im Inneren der Rot Hides demonstriert dunkle alchemistische Methoden, die Kräuterkundige und Alchemisten faszinieren, welche die Reagenzien der Seuche erforschen.",["race:Undead"]="Für die Verlassenen ist es von entscheidender Bedeutung, der Geißel frische Leichen aus den Massengräbern vorzuenthalten, um Tirisfal zu schützen und Rohstoffe für das eigene Überleben zu sichern."},sec={{t="Unnatürliche Konservierung",b="Die Rot Hide-Gnolle, die Garrens Schlupfwinkel und die nahen Massengräber heimsuchen, sind keine gewöhnlichen wilden Bestien; sie sind verrottende, konservierte Knechte, die von der Geißel eingesetzt werden, um Seuchenopfer auszugraben. Durch ihre verwesten Adern fließt Einbalsamierungssekret, eine üble Flüssigkeit, die ihr Fleisch künstlich konserviert und ihnen anhaltendes Untotendasein verleiht. Für Magistrat Sevren in Brill erfüllt die Beschaffung von Phiolen dieses Sekrets einen doppelten Zweck: Sie bestätigt die Vernichtung dieser Grabräuber und versorgt die Forscher der Königlichen Apothekervereinigung mit frischen Proben zum Sezieren, Studieren und Bewaffnen gegen die Schergen des Lichkönigs."}},faq={{q="Was ist Einbalsamierungssekret?",a="Es ist eine konservierende alchemistische Substanz, die in den belebten Körpern der Rot Hide-Gnolle in Tirisfal zu finden ist. Die Flüssigkeit erhält ihr verrottendes Fleisch und hält sie im Dienst der Geißel in Bewegung.",al={"einbalsamierungssekret","was ist sekret","gnoll flüssigkeit"}},{q="Wer möchte dieses Sekret sammeln lassen?",a="Magistrat Sevren, der über die Stadt Brill herrscht, befiehlt den Streitern der Verlassenen, es von getöteten Rot Hides zu erbeuten, damit die Königliche Apothekervereinigung ihre chemische Zusammensetzung untersuchen kann.",al={"wer braucht einbalsamierungssekret","magistrat sevren sekret","wer will sekret"}},{q="Warum graben die Rot Hide-Gnolle Gräber aus?",a="Die Geißel nutzt die Rot Hide-Gnolle, um die Leichen von Seuchenopfern zu exhumieren, die in den nördlichen Massengräbern nahe Garrens Schlupfwinkel begraben liegen, um Rohmaterial zur Verstärkung ihrer Reihen zu beschaffen.",al={"warum schänden gnolle gräber","massengräber tirisfal","gnoll geißel verbindung"}},{q="Was planen die Verlassenen mit der Flüssigkeit zu tun?",a="Die Apotheker in Undercity untersuchen das Sekret, um seine Geheimnisse zu lüften, in der Hoffnung, Gegenmaßnahmen oder neue alchemistische Formeln gegen die Geißel zu entwickeln.",al={"was macht sevren mit sekret","apotheker studie sekret","verwendung von einbalsamierungssekret"}}},fp="15,287,22.601.0,24.199.0,31.181.0,46.176.0,47.155.0"}
P.entries["item:emerald-dreamcatcher"] = {n="Smaragdgrüner Traumfänger",s="Der smaragdgrüne Traumfänger ist ein heiliges Nachtelfenamulett, das geschaffen wurde, um dem Smaragdgrünen Traum subtile Lebenskraft zu entziehen. Es wurde Tallonkai Swiftroot von den Druiden der Grabhügel von Ban'ethil verliehen und blieb in Starbreeze zurück, als die Furbolgs der Gnarlpine der Verderbnis anheimfielen und die Siedlung überrannten.",h="Der smaragdgrüne Traumfänger ist ein heiliges Nachtelfenamulett, das geschaffen wurde, um dem Smaragdgrünen...",kw={"grabhügel von ban'ethil","dolanaar","smaragdgrüner traumfänger","furbolg","gaerolas talvethren","starbreeze","tallonkai swiftroot","teldrassil"},ang={["class:Druid"]="Das Amulett ist eine direkte Verbindung zu den schlummernden Druiden der Grabhügel von Ban'ethil und zeigt, wie ihre Zwiesprache mit dem Smaragdgrünen Traum den darunterliegenden Kaldorei-Siedlungen Beistand leistet.",["race:NightElf"]="Die Wiederbeschaffung des Relikts ist ein kleiner Sieg gegen die um sich greifende Seuche, die Starbreeze und das umliegende Geäst von Teldrassil heimsucht."},sec={{t="Ein Geschenk aus Ban'ethil",b="Geschaffen unter der Obhut von Gaerolas Talvethren, dem druidischen Wächter der Grabhügel von Ban'ethil, ist der Smaragdgrüne Traumfänger ein verzaubertes Relikt, das nur wenigen Auserwählten zuteilwurde. Er wurde so geschaffen, dass er umgebende Energien direkt aus dem Smaragdgrünen Traum schöpft und jeden, der ihn trägt, mit Glück und Schutz segnet. Als Starbreeze an die rasenden Gnarlpine-Furbolgs fiel, blieb das Amulett in einer Kommode zurück – gestrandet inmitten von feindseligem, verdorbenem Gebiet."}},faq={{q="Was bewirkt der Smaragdgrüne Traumfänger?",a="Laut Tallonkai Swiftroot schöpft das Amulett rohe Energie aus dem Smaragdgrünen Traum und verleiht jedem, der es besitzt, Glück und Vitalität. Es gilt als ein seltenes Zeichen der Gunst der cenarischen Druiden.",al={"smaragdgrüner traumfänger kräfte","wozu dient der traumfänger","traumfänger geschichte"}},{q="Wer hat den Smaragdgrünen Traumfänger hergestellt?",a="Er wurde Tallonkai von Gaerolas Talvethren geschenkt, dem Druidenwächter, der über den schlafenden Zirkel des Cenarius in den Grabhügeln von Ban'ethil wacht.",al={"wer stellte den traumfänger her","wer gab tallonkai den traumfänger"}},{q="Warum wurde der Traumfänger in Starbreeze zurückgelassen?",a="Tallonkai hatte das Amulett in seiner Kommode in Starbreeze aufbewahrt. Als die örtlichen Gnarlpine-Furbolgs von der Verderbnis befallen wurden und gewalttätig wurden, musste die Siedlung aufgegeben werden, bevor er es an sich nehmen konnte.",al={"warum ließ tallonkai ihn zurück","wo ging der traumfänger verloren"}},{q="Warum sind die Furbolgs in Starbreeze feindselig?",a="Der Stamm der Gnarlpine auf ganz Teldrassil ist einer finsteren, sich ausbreitenden Verderbnis zum Opfer gefallen, die sie in eine aggressive Raserei treibt und die Nachtelfen dazu zwingt, aus abgelegenen Siedlungen wie Starbreeze zu fliehen.",al={"warum fiel starbreeze","starbreeze furbolgs"}}},fp="20,300,21.470.0,38.204.0,34.143.0,59.219.0,51.201.0"}
P.entries["item:empty-blue-waterskin"] = {n="Leerer blauer Wasserschlauch",s="Der Leere blaue Wasserschlauch ist ein rituelles Gefäß, das Initianden während der schamanischen Wasserprüfungen überreicht wird. Von der Einsiedlerin Brine im Brachland bereitgestellt, wird er nach Norden in die uralten Länder der Nachtelfen getragen, um eine heilige, unberührte Flüssigkeit zu beschaffen, die für die Erschaffung des Wassertotems erforderlich ist.",h="Der Leere blaue Wasserschlauch ist ein rituelles Gefäß, das Initianden während der schamanischen...",kw={"ashenvale","brachland","brine","ruf des wassers","leerer blauer wasserschlauch","die sternenstaubruinen","wassertotem"},ang={["class:Shaman"]="Das Tragen und Füllen dieses Wasserschlauchs ist ein entscheidender Meilenstein bei der Beherrschung der Geister des Wassers und bringt die reine Flüssigkeit hervor, die Ihr zum Erschaffen Eures dauerhaften Wassertotems benötigt.",["faction:Horde"]="Die Beschaffung des Wassers erfordert eine gefährliche Reise aus dem Brachland hinaus in feindliches Nachtelfengebiet im westlichen Ashenvale."},sec={{t="Ein heiliges Gefäß",b="Die Zwiesprache mit dem Geist des Wassers erfordert eine spürbare Verbindung zu reinen, ungestörten Quellen in ganz Kalimdor. Übergeben von der Einsiedlerin Brine an den südlichen Ufern des Brachlands, stellt der Leere blaue Wasserschlauch die letzte und gefährlichste Sammelaufgabe in der frühen Ausbildung eines Schamanen dar. Er ist dazu bestimmt, unberührtes Wasser direkt aus einem abgelegenen Brunnen tief in den uralten Sternenstaubruinen aufzunehmen, eingebettet in den umkämpften Grenzlanden von Ashenvale."},{t="Der Waldbrunnen",b="Das Füllen dieses einfachen Behälters erfordert vom Initianden, die Sicherheit des Hordegebiets hinter sich zu lassen und in uralte Haine vorzudringen, die von Naturbestien und Nachtelfen bewacht werden. Sobald er in die Wasser des zerstörten Heiligtums getaucht wird, verwandelt sich das Gefäß in einen Vollen blauen Wasserschlauch. Zusammen mit Proben aus dem Brachland und Tarrens Mühle ermöglicht sein Inhalt Brine das Brauen jenes Trankes, der nötig ist, um den Elementargeist des Wassers zu beschwören und zu besänftigen."}},faq={{q="Wofür wird der Leere blaue Wasserschlauch verwendet?",a="Er ist ein leerer Behälter, der während der Questreihe „Ruf des Wassers“ verwendet wird. Ein Initiand muss ihn zu einem heiligen Brunnen in den Sternenstaubruinen in Ashenvale tragen, wo er gefüllt und zu Brine zurückgebracht wird, um beim Brauen eines Tranks aus reinem Wasser zu helfen.",al={"was macht leerer blauer wasserschlauch","leerer blauer wasserschlauch nutzung","warum habe ich leeren blauen wasserschlauch"}},{q="Wer gibt Euch diesen Wasserschlauch?",a="Er wird von Brine überreicht, einer asketischen Schamanenmentorin, die allein in einer Hütte im Südlichen Brachland südlich von Camp Taurajo nahe der Grenze zum Razorfen lebt.",al={"wer gibt leeren blauen wasserschlauch","wo bekommt man blauen wasserschlauch"}},{q="Wo muss der Wasserschlauch gefüllt werden?",a="Er muss am zentralen Brunnen innerhalb der Sternenstaubruinen gefüllt werden, die tief im südwestlichen Ashenvale liegen, gleich hinter dem Mystralsee nahe dem Gebirgszug des Stonetalon.",al={"wo leeren blauen wasserschlauch füllen","blauer wasserschlauch fundort","wo fülle ich ihn"}},{q="Warum benötigt Brine Wasser aus Ashenvale?",a="Brine versucht, die reinste Phiole Wasser herzustellen, die auf Kalimdor bekannt ist. Die unberührten, heiligen Quellen der Nachtelfenruinen liefern die makellose letzte Zutat, die für die Zwiesprache mit den Elementargeistern des Wassers notwendig ist.",al={"warum ashenvale wasser","warum sternenstaubruinen wasser"}}},fp="20,268,15.466.0,19.424.0,42.228.0,29.143.0,35.178.0,41.218.0"}
P.entries["item:empty-brown-waterskin"] = {n="Leerer brauner Wasserschlauch",s="Der Leere braune Wasserschlauch ist ein elementares Gefäß, das Brine während der Prüfungen eines Schamanen im Brachland bereitstellt. Er wird verwendet, um Wasser aus einer nahegelegenen Oase zu schöpfen, und dient als erstes greifbares Werkzeug, um die heikle, umkämpfte Natur des Wassers in einem kargen Land kennenzulernen.",h="Der Leere braune Wasserschlauch ist ein elementares Gefäß, das Brine während der Prüfungen eines Schamanen im...",kw={"brachland","brine","ruf des wassers","stacheleber","sapta","schamane","wasserschlauch"},ang={["class:Shaman"]="Das Tragen dieses Wasserschlauchs ist ein Initiationsritus für Schamanen der Horde, die ihr Wassertotem anstreben, und verdeutlicht das Gleichgewicht zwischen der Ehrfurcht vor den Elementen und den harten Kämpfen des sterblichen Überlebens."},sec={{t="Eine Lektion der Knappheit",b="In den sonnenverbrannten Weiten des Brachlands ist Wasser weit mehr als eine Ressource; es ist das Leben selbst und ein ständiger Zündfunke für den Krieg. Die Einsiedlerin Brine vertraut einem Initianden diesen einfachen Lederschlauch als erste Prüfung von „Ruf des Wassers“ an. Die Aufgabe wirkt bescheiden – tragt das leere Gefäß hinab zum Wasserloch unterhalb ihrer Behausung und bringt es gefüllt zurück. Doch beim Schöpfen aus diesem einsamen Becken wird der Träger sogleich mit der harten Wahrheit des Landes konfrontiert: Jeder Tropfen Flüssigkeit wird von den hiesigen Stachelebern eifersüchtig bewacht, die die Oase als unschätzbaren Schatz betrachten, was den Initianden dazu zwingt zu begreifen, wie Wasser gleichermaßen das Leben nährt und Sterbliche zur Gewalt treibt."}},faq={{q="Wozu wird der Leere braune Wasserschlauch verwendet?",a="Er ist ein leerer Behälter, der Schamaneninitianden von Brine überreicht wird. Sein Zweck besteht darin, Wasser aus dem natürlichen Teich direkt unter ihrer Hütte im Brachland zu schöpfen, um einen gefüllten Wasserschlauch zu erhalten, der für die Zubereitung von Elementarsapta benötigt wird.",al={"zweck des wasserschlauchs","was bringt brauner wasserschlauch","nutzen leerer brauner wasserschlauch"}},{q="Wer vergibt diesen Wasserschlauch?",a="Brine, eine kundige Einsiedlerin, die in den südlichen Gefilden des Brachlands lebt, händigt das Gefäß an Schamanen aus, die sich auf ihre elementare Pilgerreise begeben, um mit den Geistern des Wassers in Einklang zu treten.",al={"wer gibt den wasserschlauch","questgeber brauner wasserschlauch","wo gibt es leeren wasserschlauch"}},{q="Warum verteidigen die Stacheleber die Wasserquelle?",a="Wasser ist im gesamten Brachland überaus rar. Für die Stacheleber bedeutet selbst ein kleines Wasserloch unermesslichen Reichtum und das nackte Überleben. Da Regen selten ist, bewachen sie jede Quelle mit wilder Gier und greifen jeden an, der es wagt, daraus zu schöpfen.",al={"warum stacheleber angreifen","stacheleber wasser","warum das becken bewacht wird"}},{q="Was geschieht, sobald der Schlauch gefüllt ist?",a="Sobald er in die Oase unterhalb von Brines Hügel getaucht wird, verwandelt er sich in einen Vollen braunen Wasserschlauch. Wenn Ihr ihn zu Brine zurückbringt, kann sie Euer Verständnis für das Gleichgewicht der Natur auf die Probe stellen, bevor sie Euch auf der Suche nach noch selteneren Wassern quer durch die Welt schickt.",al={"nach dem füllen tun","wasserschlauch abgeben","voller brauner wasserschlauch abgabe"}}},fp="21,255,20.652.0,43.227.0,28.186.0,48.245.0,37.219.0"}
P.entries["item:empty-cleansing-bowl"] = {n="Leere Säuberungsschale",s="Die Leere Säuberungsschale ist ein rituelles Gefäß, das von Thundris Windwirker überreicht wird, um bei der Untersuchung der Verderbnis der Blackwood-Furbolgs zu helfen. Wenn sie am Mondbrunnen von Auberdine gefüllt und mit Nahrungsproben kombiniert wird, entsteht eine Mischung, die in der Lage ist, den dämonischen Einfluss eines Satyrs vorübergehend zu brechen.",h="Die Leere Säuberungsschale ist ein rituelles Gefäß, das von Thundris Windwirker überreicht wird, um bei der...",kw={"auberdine","blackwood","säuberungsschale","darkshore","leere säuberungsschale","mondbrunnen","thundris windwirker","xabraxxis"},ang={["class:Druid"]="Die Verwendung von Mondbrunnenwasser zur Heilung unnatürlicher Gebrechen spiegelt die grundlegende druidische Berufung wider, das verwundete Gleichgewicht der Natur in ganz Darkshore wiederherzustellen.",["race:NightElf"]="Das Reinigungsritual veranschaulicht die Macht von Elunes Mondbrunnen, abscheuliche dämonische Befleckung aufzuheben, und weckt die Hoffnung, dass die alten Verbündeten der Nachtelfen unter den Furbolgs letztlich gerettet werden können."},sec={{t="Ein Gefäß der Läuterung",b="Die Leere Säuberungsschale, die Abenteurern von Thundris Windwirker in Auberdine anvertraut wird, ist dafür geschaffen, heiliges Wasser aus dem örtlichen Mondbrunnen aufzunehmen. Die Nachtelfen fanden heraus, dass die nördlichen Blackwood-Furbolgs einem von Satyrn gelenkten dämonischen Wahnsinn verfielen, welche ihren Willen durch verzauberte Talismane aufzwingen. Indem reines Mondwasser in die Schale geschöpft und mit den von den Furbolgs gesammelten Nüssen, Getreidearten und Früchten vermengt wird, bringt das Gefäß eine gesegnete Mahlzeit hervor, die den betroffenen Kreaturen vorübergehend den Verstand wiedergibt und den verantwortlichen Satyraufseher enttarnt."}},faq={{q="Was mache ich mit der Leeren Säuberungsschale?",a="Bringt die Schale zum Mondbrunnen von Auberdine und taucht sie in das gesegnete Wasser, um eine Gefüllte Säuberungsschale zu erhalten. Danach müsst Ihr Proben von Getreide, Nüssen und Früchten aus dem nördlichen Lager der Blackwood-Furbolgs sammeln, um sie damit zu kombinieren.",al={"leere säuberungsschale verwendung","wie leere säuberungsschale benutzt wird","wo säuberungsschale gefüllt wird"}},{q="Warum benötigen die Nachtelfen diese Schale, um die Furbolg-Verderbnis zu bekämpfen?",a="Die Blackwood-Furbolgs sind an die dunkle Magie von Satyr-Talismanen gebunden. Thundris Windwirker nutzt die Schale, um eine geweihte Mischung aufzubewahren, die die Furbolgs zeitweilig von ihrer Raserei heilt und ihren verborgenen Satyr-Beherrscher Xabraxxis hervorlockt.",al={"warum säuberungsschale","zweck der säuberungsschale"}},{q="Wer übergibt die Leere Säuberungsschale?",a="Thundris Windwirker, ein Gelehrter der Nachtelfen in Auberdine, händigt Euch die Schale aus, wenn er Euch damit beauftragt, den Ursprung der Blackwood-Verderbnis entlang des Cliffsprings aufzudecken.",al={"wer gibt säuberungsschale","säuberungsschale questgeber"}},{q="Was geschieht, sobald die Mischung zubereitet ist?",a="Wird die fertige Mischung nahe dem Lagerfeuer des nördlichen Lagers platziert, reinigt sie die umliegenden Furbolgs lange genug, um den Zorn des Satyrs Xabraxxis auf sich zu ziehen, sodass Ihr ihn bezwingen und seinen Talisman der Verderbnis an Euch nehmen könnt.",al={"säuberungsschale lagerfeuer","säuberungsschale platzieren"}}},fp="20,285,24.560.0,43.236.0,70.240.1,38.176.0,42.211.1"}
P.entries["item:empty-cliffspring-falls-sampler"] = {n="Leere Cliffspring Falls-Probe",s="Die Leere Cliffspring Falls-Probe ist eine spezielle Flasche, die Novizen der Nachtelfen-Druiden vom Zirkel des Cenarius anvertraut wird. Sie dient dazu, eine Wasserprobe an der Mündung der Höhle des Cliffspring an der Darkshore zu entnehmen, um ein übles Gift zu analysieren, das die örtliche Tierwelt verdirbt.",h="Die Leere Cliffspring Falls-Probe ist eine spezielle Flasche, die Novizen der Nachtelfen-Druiden vom Zirkel...",kw={"alanndarian nightsong","zirkel des cenarius","cliffspring falls","vergiftung heilen","darkshore","dendrite starblaze","probe"},ang={["class:Druid"]="Das Befüllen dieses Probefläschchens an der von Naga verseuchten Höhle ist ein Initiationsritus für junge Druiden, der direkt zum Erlernen von Vergiftung heilen führt.",["race:NightElf"]="Die Entweihung des unberührten Waldwassers der Darkshore durch lauernde Naga bedroht sowohl die wilden Bestien als auch die Siedlung Auberdine."},sec={{t="Untersuchung der verdorbenen Gewässer",b="Cliffspring Falls bildet die Hauptsüßwasserquelle für die nördliche Darkshore, weshalb jede Störung seines Quellgebiets eine tödliche Gefahr für das gesamte Ökosystem darstellt. Als die einheimischen Hirsche einem virulenten, zehrenden Gift zu erliegen begannen, überreichte Dendrite Starblaze vom Zirkel des Cenarius diese leeren Probefläschchen an junge Druiden, die aus Moonglade entsandt wurden. Die Druiden müssen tief in die Klippen nahe den Wasserfällen vordringen – direkt zum Eingang einer Höhle, die nun von feindseligen Naga überrannt ist –, um eine brauchbare Wasserprobe zu schöpfen."},{t="Ein Rezept für ein Heilmittel",b="Einmal gefüllt, birgt der Behälter eine trübe Flüssigkeit, die eine tiefere ökologische Verderbnis offenbart. Zu Alanndarian Nightsong in Auberdine gebracht, bestätigt die verunreinigte Probe, dass üble Wirkstoffe das Grundwasser vergiften. Durch die Untersuchung der im Glas eingeschlossenen Schadstoffe erlangen Alanndarian und die Druiden des Cenarius die nötigen Erkenntnisse, um ein Gegengift zu entwickeln und den Initianten mit grundlegenden druidischen Heilriten zu segnen."}},faq={{q="Was ist der Zweck dieses Probefläschchens?",a="Es ist ein leerer Behälter, der Druiden überreicht wird, um verdorbenes Wasser an der Mündung der Höhle bei Cliffspring Falls an der Darkshore zu sammeln. Die Probe ermöglicht es den Kräuterkundigen des Cenarius, das Gift zu analysieren und zu heilen, das die heimische Tierwelt befällt.",al={"probefläschchen verwendung","wofür ist cliffspring-probe","zweck leere probe"}},{q="Wo wird die Wasserprobe entnommen?",a="Die Probe muss direkt an der Mündung der Höhle nahe Cliffspring Falls hoch in den nordöstlichen Hügeln der Darkshore geschöpft werden. Feindselige Naga hausen am Höhleneingang, was die Probenentnahme gefährlich macht.",al={"wo probefläschchen füllen","ort cliffspring-probe","ort probenentnahme"}},{q="Wer erhält den gefüllten Behälter?",a="Das gefüllte Probefläschchen wird zu Alanndarian Nightsong gebracht, einer Heilerin der Nachtelfen und Vertreterin des Cenarius in der Küstensiedlung Auberdine.",al={"wer bekommt gefüllte probe","wo probe abgeben","alanndarian probe"}},{q="Warum wird an Cliffspring Falls eine Probe entnommen und nicht an anderen Flüssen?",a="Cliffspring Falls dient als primäre Süßwasserquelle für die nördliche Darkshore. Dendrite Starblaze führte die Krankheit, welche die Hirsche der Region schwächt, auf dieses Quellgebiet zurück, weshalb eine direkte Wasserprobe unerlässlich für die Entwicklung eines Heilmittels ist.",al={"warum cliffspring falls","was vergiftet darkshore","cliffspring gift"}}},fp="31,274,32.508.0,19.415.1,36.228.0,32.204.0,34.154.0,63.236.0"}
P.entries["item:empty-dreadmist-peak-sampler"] = {n="Leere Glutnebelgipfelprobe",s="Die Leere Glutnebelgipfelprobe ist ein spezielles cenarisches Gefäß, das Druiden der Horde anvertraut wird, um verdorbenes Wasser vom Gipfel des Glutnebelgipfels zu schöpfen. Die Untersuchung der üblen Flüssigkeit, die in dieser Phiole gesammelt wird, ist von entscheidender Bedeutung für die Diagnose und Heilung der sich ausbreitenden Fäulnis, welche die Tierwelt im nördlichen Brachland befällt.",h="Die Leere Glutnebelgipfelprobe ist ein spezielles cenarisches Gefäß, das Druiden der Horde anvertraut wird...",kw={"brachland","burning blade","dendrite starblaze","glutnebelgipfel","leere glutnebelgipfelprobe","die eigentliche ursache","tonga runetotem"},ang={["class:Druid"]="Der Erhalt dieses Probennehmers ist ein entscheidender Schritt beim Erlernen der Kunst des Giftkurierens und stellt die Hingabe eines Druiden auf die Probe, das Leiden in der Wildnis zu erkennen und zu lindern.",["faction:Horde"]="Druiden der Horde tragen diesen Probennehmer bei sich, um Tonga Runetotem im Crossroads dabei zu helfen, den ökologischen Verfall aufzuhalten, der die nördlichen Ebenen des Brachlands bedroht."},sec={{t="Der Fäulnis auf der Spur",b="Als eine üble Seuche begann, Gazellen zu schwächen und die empfindliche Ökologie des nördlichen Brachlands zu destabilisieren, vermutete der Druide Dendrite Starblaze, dass die wetterbeeinflussenden Teiche auf dem Glutnebelgipfel das Epizentrum darstellten. Er entsandte Druiden-Initianden mit leeren Probengefäßen, um den Höhen des Berges zu trotzen – die nun von der dämonenanbetenden Burning Blade heimgesucht werden – und direkt aus dem Teich auf dem Gipfel ungefiltertes Wasser zu entnehmen."},{t="Eine entscheidende Probe",b="Das Tragen eines leeren Probennehmers hinauf zu den schroffen Felsen ermöglicht es den Druiden, unverfälschte Beweise für das abscheuliche Werk des Kults zu sichern. Einmal gefüllt, wird das faulige Wasser zu Tonga Runetotem im Crossroads gebracht, wo seine fauligen Bestandteile als unverzichtbare Grundlage für das Brauen eines Heilmittels und den Schutz der einheimischen Fauna dienen."}},faq={{q="Was ist der Zweck der Leeren Glutnebelgipfelprobe?",a="Es ist ein leerer Behälter, der von Druiden verwendet wird, um eine Wasserprobe aus dem verdorbenen Teich auf dem Glutnebelgipfel zu entnehmen, um Tonga Runetotem dabei zu helfen, ein Heilmittel für die erkrankte Tierwelt zu brauen.",al={"was macht dieser gegenstand","glutnebelgipfel probennehmer verwendung","warum habe ich diesen probennehmer"}},{q="Wohin muss dieser Probennehmer gebracht werden?",a="Er muss bis ganz nach oben auf den Glutnebelgipfel gebracht werden, nordwestlich des Crossroads im Brachland, und in den hoch gelegenen Teich getaucht werden, in dem sich das Wasser sammelt.",al={"wo fülle ich den probennehmer","probennehmer ort","leere glutnebelgipfelprobe füllen"}},{q="Wer stellt den Probennehmer zur Verfügung?",a="Dendrite Starblaze, der im Auftrag des Zirkels des Cenarius handelt, stellt den Probennehmer bereit, bevor er den Druiden losschickt, um sich mit Tonga Runetotem abzustimmen.",al={"wer gibt den probennehmer","wer hat diese quest gestartet"}},{q="Warum ist es so wichtig, das Wasser auf dem Glutnebelgipfel zu beproben?",a="Die hochgelegenen Teiche des Glutnebelgipfels beeinflussen die regionalen Wettermuster und den Nebel. Da der Gipfel vom Kult der Burning Blade verdorben wurde, breitet sich das verseuchte Abwasser über die Ebenen aus und vergiftet die einheimischen Kreaturen.",al={"warum glutnebelgipfel teich","warum ist das wasser schlecht"}}},fp="28,298,18.434.0,18.308.1,56.174.0,41.152.0,25.143.0,58.208.0"}
P.entries["item:empty-leaden-collection-phial"] = {n="Leere bleierne Sammelphiole",s="Die Leere bleierne Sammelphiole ist ein abgeschirmter Behälter, der von Gnomen-Tüftlern entwickelt wurde, um radioaktiven Niederschlag aus den Ruinen von Gnomeregan zu sammeln. Hergestellt aus Blei, um den Träger vor tödlicher Kontamination zu schützen, wird sie von Abenteurern verwendet, die Ozzie Togglevolt in Kharanos beistehen. Ozzie hofft, dass das eingefangene Leuchten ein Heilmittel für ihre geplagten Artgenossen hervorbringen könnte – oder zumindest ein außerordentlich starkes Getränk.",h="Die Leere bleierne Sammelphiole ist ein abgeschirmter Behälter, der von Gnomen-Tüftlern entwickelt wurde, um...",kw={"leere bleierne sammelphiole","niederschlag","gnogaine","gnomeregan","kharanos","bleierne phiole","ozzie togglevolt","strahlung"},ang={["profession:Engineering"]="Die bleierne Phiole demonstriert die geradlinige Zweckmäßigkeit der Gnome: Schwermetall-Strahlenschutz kombiniert mit einer Saugvorrichtung, die darauf ausgelegt ist, unbeständige Umgebungspartikel sicher zu sammeln.",["race:Gnome"]="Die Verheerung von Gnomeregan bleibt eine offene Wunde für verbannte Gnome, was jeden experimentellen Versuch, den giftigen Niederschlag rückgängig zu machen, zu einer hochgradig persönlichen Angelegenheit macht – ganz gleich, wie exzentrisch der Forscher auch sein mag."},sec={{t="Ein abgeschirmtes Gefäß",b="Als die Belüftungsschächte von Gnomeregan die unterirdische Stadt mit giftiger Strahlung überfluteten, um die Trogg-Bedrohung auszulöschen, verwandelte sie stattdessen die überlebenden Verteidiger in Lepragnome und verstrahlte die eindringenden Bestien. Um den Niederschlag zu untersuchen und umzukehren, fertigte Ozzie Togglevolt die Leere bleierne Sammelphiole an. Hergestellt aus schwerem Blei, um die Benutzer vor der allgegenwärtigen Gefahr abzuschirmen, zieht die spezialisierte Phiole das giftige grüne Leuchten ein, das an den Körpern der verstrahlten Invasoren und Plünderer haftet, die die Ruinen durchstreifen. Einmal versiegelt, liefert die daraus resultierende Volle bleierne Sammelphiole die rohe, gefährliche Substanz, die für experimentelle Heilmittel benötigt wird."}},faq={{q="Wofür wird die Phiole verwendet?",a="Die Phiole dient dazu, gefährlichen radioaktiven Niederschlag von Irradiated Invaders und Irradiated Pillagers nahe den Oberflächentunneln von Gnomeregan einzuziehen und zu lagern. Das Einschließen des Niederschlags im Inneren verwandelt den Behälter zu Forschungszwecken in eine Volle bleierne Sammelphiole.",al={"was macht die phiole","wie leere bleierne sammelphiole benutzen","zweck der phiole"}},{q="Warum besteht die Phiole aus Blei?",a="Der radioaktive Niederschlag in Gnomeregan ist für unabgeschirmte Lebewesen tödlich und kann schwere Strahlenkrankheit verursachen oder Gnome in Lepragnome verwandeln. Die dichte Bleistruktur dient als Schutzbarriere, die den Sammler vor der unbeständigen, leuchtenden Kontamination im Inneren bewahrt.",al={"warum bleiphiole","warum aus blei"}},{q="Wer hat dieses Sammelgerät geschaffen?",a="Die Phiole wird von dem Gnomen-Tüftler Ozzie Togglevolt bereitgestellt, der seine chaotischen Experimente von Kharanos in Dun Morogh aus betreibt. Er überlässt den Behälter Abenteurern, die bereit sind, den giftigen Außenbezirken der zerstörten Stadt zu trotzen.",al={"wer baute die phiole","ozzie togglevolt phiole","wer gab mir diese phiole"}},{q="Was hofft Ozzie mit dem gesammelten Niederschlag zu erreichen?",a="Ozzie und sein Gefährte Razzle versuchen, ein Heilmittel für die von der Katastrophe geplagten Lepragnome zu erfinden. Wie bei vielen Unternehmungen der Gnome räumt Ozzie ein, dass sich die experimentelle Formel auch als Rezept für unglaublich starken Rum oder vielleicht als Heilmittel gegen Kahlheit herausstellen könnte.",al={"warum niederschlag sammeln","zweck von gnogaine","was stellt ozzie her"}}},fp="29,402,17.628.0,27.257.0,30.287.0,35.227.0,59.272.0"}
P.entries["item:empty-red-waterskin"] = {n="Leerer roter Wasserschlauch",s="Der Leere rote Wasserschlauch ist ein Lederbehälter, der angehenden Schamanen während ihrer Elementarprüfungen anvertraut wird. Er dient dazu, frisches, unverdorbenes Wasser aus einer überraschenden Quelle im von Seuchen heimgesuchten Ort Tarrens Mühle zu sammeln.",h="Der Leere rote Wasserschlauch ist ein Lederbehälter, der angehenden Schamanen während ihrer...",kw={"brine","ruf des wassers","leerer roter wasserschlauch","vorgebirge von hillsbrad","tarrens mühle","wassersapta"},ang={["class:Shaman"]="Diesen Wasserschlauch mit sich zu führen und zu füllen, ist ein grundlegender Schritt, um das Wassertotem zu meistern und Eure Sinne auf die widerstandsfähigen Geister des Wassers einzustimmen.",["race:Orc"]="Brine vergleicht den reinen Brunnen in Tarrens Mühle mit Kriegshäuptling Thrall – ein Leuchtfeuer unnachgiebiger Stärke und Hoffnung, das durch immenses Leid hindurch Bestand hat."},sec={{t="Ein Gefäß für reines Wasser",b="Von der Einsiedlerin Brine im Brachland überreicht, erfüllt dieser schlichte rote Schlauch einen unverzichtbaren spirituellen Zweck bei den Prüfungen rund um den Ruf des Wassers. Initianden haben die Aufgabe, ihn weit über das Meer ins Vorgebirge von Hillsbrad zu tragen, um dort den Ort Tarrens Mühle aufzusuchen. Obwohl das Dorf von den Verlassenen besetzt und vom Untod durchdrungen ist, schöpft ein einsamer Brunnen in seiner Mitte weiterhin süßes, unverfälschtes Quellwasser. Das Füllen des roten Wasserschlauchs fängt eine lebenswichtige Probe des Lebens ein, das inmitten des Verfalls fortbesteht und aus der Brine den Wassersapta destilliert."}},faq={{q="Wofür wird der Leere rote Wasserschlauch verwendet?",a="Er wird von Schamanen während der Questreihe „Ruf des Wassers“ genutzt, um Quellwasser aus dem Brunnen in Tarrens Mühle zu schöpfen, wodurch er zu einem Vollen roten Wasserschlauch wird.",al={"leerer roter wasserschlauch verwendung","was tun mit rotem wasserschlauch"}},{q="Wer vergibt diesen Wasserschlauch?",a="Brine, eine Wassereinsiedlerin, die nahe den südlichen Küsten des Brachlands lebt, übergibt ihn Schamaneninitianden, die sich den Elementarprüfungen unterziehen.",al={"wer gibt roten wasserschlauch","roter wasserschlauch questgeber"}},{q="Warum wird das Wasser ausgerechnet in Tarrens Mühle gesammelt?",a="Obwohl Tarrens Mühle unter die Kontrolle der Verlassenen gefallen ist, bleibt der zentrale Brunnen vollkommen unberührt von jeglichem Verderben. Für Brine ist diese reine Quelle ein mächtiges Elementarsymbol der Hoffnung und des unerschütterlichen Lebens, das auf unheiligem Boden fortbesteht.",al={"warum tarrens mühle wasser","tarrens mühle brunnen lore"}},{q="Was geschieht, nachdem der Wasserschlauch gefüllt wurde?",a="Sobald der Schlauch am Brunnen gefüllt ist, muss er zurück zu Brine ins Brachland gebracht werden, die das Wasser mit weiteren seltenen Proben kombiniert, um den Wassersapta zu brauen.",al={"wie weiter roter wasserschlauch","voller roter wasserschlauch abgabe"}}},fp="19,210,23.517.0,41.150.0,28.131.0,47.229.0,43.151.0"}
P.entries["item:empty-sampling-tube"] = {n="Leere Probenröhre",s="Die Leere Probenröhre ist eine von Thundris Windwirker in Auberdine bereitgestellte Glasphiole. Sie soll verderbtes Wasser aus dem Cliffspring sammeln, damit Nachtelfengelehrte das vordringende Verderbnis untersuchen können, das Darkshore bedroht.",h="Die Leere Probenröhre ist eine von Thundris Windwirker in Auberdine bereitgestellte Glasphiole.",kw={"auberdine","cliffspring","darkshore","leere probenröhre","nebelrand","thundris windwirker","wasserprobe"},ang={["class:Druid"]="Die Probenröhre stellt einen frühen Versuch dar, das dämonische Verderbnis des Teufelswalds zu diagnostizieren, das in Darkshores unberührte Flüsse sickert und die einheimische Tierwelt erkranken lässt.",["race:NightElf"]="Für die Nachtelfen von Auberdine ist die Untersuchung des Cliffspring von entscheidender Bedeutung, um zu verhindern, dass der verderbte Abfluss ihre Küstenzuflucht am Nebelrand vergiftet."},sec={{t="Das Wasser testen",b="Während die Wildnis von Darkshore der schleichenden Fäulnis anheimfällt, haben die natürlichen Wasserläufe begonnen, faulig zu werden. Thundris Windwirker, ein in Auberdine stationierter Forscher, stellt diese leere Glasröhre zur Verfügung, um handfeste Beweise aus dem Cliffspring zu sammeln. Die aus dem Becken unter dem ersten Wasserfall nördlich der Stadt entnommene Probe ermöglicht es den Nachtelfen-Naturforschern, die Natur des Verderbnisses zu untersuchen, das in Richtung Nebelrand gespült wird."},{t="Die Quelle aufspüren",b="Während feindselige Blackwood-Furbolgs Lager entlang der Flussufer bewohnen, vermutet Windwirker, dass sie bloß Opfer und Überträger sind und nicht der eigentliche Ursprung der Fäulnis. Das Füllen der Röhre bestätigt, dass die Verunreinigung von den verdorbenen Höhen des Teufelswalds im Osten herabfließt. Das gesammelte Exemplar dient als Grundlage für die Herstellung eines potenziellen Heilmittels und die Vorbereitung einer direkten Gegenmaßnahme gegen die Fäulnis."}},faq={{q="Was ist der Zweck der Leeren Probenröhre?",a="Es ist ein versiegeltes Glasgefäß, das verwendet wird, um eine Wasserprobe aus dem verdorbenen Cliffspring nördlich von Auberdine zu entnehmen. Die Probe wird zu Thundris Windwirker gebracht, damit er die üblen Substanzen analysieren kann, die sich in Darkshore ausbreiten.",al={"warum habe ich diese röhre","was macht die probenröhre","probenröhre zweck"}},{q="Wo soll die Wasserprobe entnommen werden?",a="Die Röhre muss am ersten Wasserfall entlang des Cliffspring gefüllt werden, der sich nördlich von Auberdine unter einer darüberliegenden Brücke befindet, genau dort, wo sich das Wasser staut, bevor es in den Nebelrand fließt.",al={"wo röhre füllen","cliffspring ort","probenröhre stelle"}},{q="Wer hat diese Röhre bereitgestellt?",a="Thundris Windwirker, ein Nachtelfen-Naturforscher, der die Umweltbedrohungen rund um Auberdine untersucht, vertraut die Röhre Abenteurern an, die bereit sind, der verdorbenen Wildnis zu trotzen.",al={"wer gibt die röhre","röhre questgeber","thundris windwirker"}},{q="Was verschmutzt den Cliffspring?",a="Obwohl die einheimischen Blackwood-Furbolgs die Flussufer bewohnen und die Verunreinigung verschlimmern, liegt die wahre Quelle des üblen Verderbnisses im verdorbenen Waldland des Teufelswalds hoch in den Bergen im Osten.",al={"warum ist der fluss grün","was hat das wasser verdorben","cliffspring verderbnis"}}},fp="19,232,18.435.0,18.407.1,47.229.0,47.192.0,23.170.0,40.201.1"}
P.entries["item:empty-water-tube"] = {n="Leere Wasserröhre",s="Die Leere Wasserröhre ist ein einfaches Glasgefäß, das in Auberdine ausgegeben wird, um heiliges Mondbrunnenwasser zu schöpfen. Sie dient dazu, die gesegnete Flüssigkeit zu dem seltsamen roten Kristall hinaufzutragen, der auf den östlichen Klippen der Dunkelküste thront.",h="Die Leere Wasserröhre ist ein einfaches Glasgefäß, das in Auberdine ausgegeben wird, um heiliges...",kw={"wenn das wasser fließt","auberdine","dunkelküste","leere wasserröhre","teufelswald","mondbrunnen","mondbrunnenwasserröhre","roter kristall"},ang={["class:Druid"]="Druiden verehren Mondbrunnen zutiefst und verlassen sich auf deren unberührtes Wasser, um Anomalien zu untersuchen und seltsame Störungen zu bereinigen, die aus verdorbenen Ländern wie dem Teufelswald herübergreifen.",["race:NightElf"]="Der Umgang mit geweihtem Mondbrunnenwasser ist eine heilige Pflicht für die Kaldorei, welche die Mondbrunnen als heilige, von der Göttin Elune gesegnete Reservoire verehren."},sec={{t="Ein Gefäß für gesegnetes Wasser",b="Schildwachen und Gelehrte, die den geheimnisvollen roten Kristall entlang des östlichen Gebirgskamms der Dunkelküste erforschen, benötigen reine Mondessenz, um dessen Beschaffenheit zu prüfen. Da gewöhnliches Glas oder Feldflaschen geweihtes Wasser leicht verunreinigen können, wird diese versiegelte Phiole eigens Forschern anvertraut, die den Mondbrunnen in Auberdine aufsuchen. Einmal gefüllt, wird ihr Inhalt die Berghänge hinaufgetragen, um zu beobachten, wie das fremdartige Mineral auf Elunes Magie reagiert."},{t="Erforschung des Schattens vom Teufelswald",b="Die Berge unmittelbar östlich der Dunkelküste grenzen an den Teufelswald, ein Reich, das von dämonischer Verderbnis vollkommen vergiftet ist. Auberdines Verteidiger vermuten, dass der unheilvolle purpurne Monolith nahe den Klippen eine finstere Verbindung zu jenem verwüsteten Wald aufweist. Indem sie Mondbrunnenwasser über sein Gitterwerk fließen lassen, hoffen die Forscher, dass das heilige Wasser die innere Struktur des Kristalls offenbart, ohne eine katastrophale Entladung der in seinem Inneren gefangenen Macht auszulösen."}},faq={{q="Welchem Zweck dient die Leere Wasserröhre?",a="Es ist ein leerer Behälter, der Euch in Auberdine überreicht wird, um Wasser direkt aus dem Mondbrunnen der Siedlung zu schöpfen, welches benötigt wird, um einen bizarren roten Kristall auf den östlichen Höhen der Dunkelküste zu untersuchen.",al={"zweck leere wasserröhre","warum habe ich leere wasserröhre","was tun mit wasserröhre"}},{q="Wo sollte die Röhre gefüllt werden?",a="Sie muss in den Mondbrunnen innerhalb von Auberdine getaucht werden. Durch das Füllen verwandelt sich der Gegenstand in eine Mondbrunnenwasserröhre.",al={"wo wasserröhre füllen","wo leere wasserröhre füllen","ort wasserröhre füllen"}},{q="Warum wird Mondbrunnenwasser für den Kristall benötigt?",a="Mondbrunnenwasser birgt die mächtige, reinigende Magie von Elune. Gelehrte glauben, dass das Gießen des Wassers über den geheimnisvollen roten Kristall mit dessen Oberfläche reagieren und Hinweise auf seinen Ursprung und seine Zusammensetzung enthüllen wird.",al={"warum mondbrunnenwasser","wirkung mondbrunnenwasser auf kristall","roter kristall mondbrunnenwasser"}},{q="Warum sind die Bewohner von Auberdine über den Kristall besorgt?",a="Der Kristall befindet sich nahe dem hohen Kamm mit Blick auf den Teufelswald, einen Wald, der von der Brennenden Legion schwer verdorben wurde. Einheimische Wächter fürchten, dass der Kristall, sollte er mit dieser verderbten Wildnis in Verbindung stehen, eine ernste Bedrohung für die Dunkelküste darstellen könnte.",al={"ist der kristall gefährlich","kristallgefahr dunkelküste","warum roten kristall untersuchen"}}},fp="16,215,27.424.0,24.452.1,44.200.0,32.121.0,45.199.0,56.227.0"}
P.entries["item:enchanted-gaea-seeds"] = {n="Verzauberte Gaeasamenkörner",s="Verzauberte Gaeasamenkörner sind speziell präparierte botanische Samen, die den verwüsteten Landschaften von Kalimdor neue Vitalität bringen sollen. Gestärkt durch druidische Magie und gesammelt in Sonnenfels, werden sie direkt in die von Asche erstickte Erde des verbrannten Tals gepflanzt, um der Zerstörung entgegenzuwirken und natürliches Wachstum neu zu entfachen.",h="Verzauberte Gaeasamenkörner sind speziell präparierte botanische Samen, die den verwüsteten Landschaften von...",kw={"das verbrannte tal","verzauberte gaeasamenkörner","gaeas samenkorn","wiedergeburt","steinkrallengebirge","sonnenfels","tammra windwhisper"},ang={["class:Druid"]="Die Samen veranschaulichen die grundlegende druidische Pflicht, den Zyklus der Wiedergeburt zu nähren und widerstandsfähiges Leben aktiv in ein von Ruin und Flächenbrand verzehrtes Reich zurückzuholen.",["race:Tauren"]="Für die Shu'halo von Sonnenfels ist das Pflanzen der verzauberten Samen ein Akt spiritueller Fürsorge, um die Erdenmutter zu ehren und verwundetes Land zurückzugewinnen."},sec={{t="Ein Funke in der Asche",b="Die verzauberten Gaeasamenkörner repräsentieren die druidischen Bemühungen der Horde, die tiefen Narben im Steinkrallengebirge zu heilen. Nachdem rohe Gaeasamen gesammelt und von Tammra Windfield in Sonnenfels rituell verzaubert wurden, besitzen sie genügend Widerstandskraft, um die allgegenwärtige Verderbnis und die elementare Fäulnis zu überwinden. Wenn sie in die fruchtbaren Erdhügel gedrückt werden, die unter dem Ruß des verbrannten Tals noch überdauern, schlagen diese Samen trotz der widrigen Bedingungen Wurzeln und verankern neues Leben in einer Landschaft, die von feindseligen Feuerelementaren und invasiven Harpyien beherrscht wird."},{t="Das Versprechen der Erneuerung",b="Das Ziel des Pflanzens dieser verzauberten Samen geht über einfache Gartenarbeit hinaus; es ist ein aktiver Versuch, das Blatt im Kampf um die Zukunft des Steinkrallengebirges zu wenden. Die in die Hüllen eingewobene Magie erlaubt es ihnen, verbliebener Verderbnis zu widerstehen und der einheimischen Flora wieder Halt zu geben. Wenn sie gedeihen, soll die wiederhergestellte Vegetation die aufgewühlten Feuerelementare beruhigen, die wilden Harpyien verdrängen und der rücksichtslosen Abholzung durch die unerbittlichen Holzfällerarbeiten der Venture Company entgegenwirken."}},faq={{q="Wofür werden verzauberte Gaeasamenkörner verwendet?",a="Sie werden in fruchtbare Erdhügel im verbrannten Tal gepflanzt. Ihr Zweck ist es, widerstandsfähige Flora sprießen zu lassen, die der Umweltverderbnis trotzt und das durch Feuer und Krieg zerstörte Land heilt.",al={"zweck der gaeasamen","was tun verzauberte gaeasamenkörner","warum gaeasamen pflanzen"}},{q="Wer hat diese Samen erschaffen oder verzaubert?",a="Rohe Gaeasamen werden in der umliegenden Wildnis gesammelt und zu Tammra Windfield in Sonnenfels gebracht. Sie verzaubert sie, damit sie im feindseligen, aschebedeckten Boden des verbrannten Tals überleben können.",al={"wer erschuf die samen","tammra windwhisper samen","wie gaeasamen hergestellt werden"}},{q="Warum müssen sie im verbrannten Tal gepflanzt werden?",a="Das verbrannte Tal ist das Zentrum der ökologischen Zerstörung im Steinkrallengebirge, überrannt von zornigen Feuerelementaren und Harpyien. Das direkte Einpflanzen der Samen in die verbliebenen Erdhügel bringt lebenswichtiges Leben hinein, das daran arbeitet, die Unruhe der Region zu lindern.",al={"wo pflanze ich sie ein","warum das verbrannte tal","pflanzen im verbrannten tal"}},{q="Welche Gefahren bedrohen die gepflanzten Samen?",a="Das verbrannte Tal wird schwer von feindseligen Feuerelementaren heimgesucht, die aus den Flammen geboren wurden, aggressiven Bloodfury-Harpyien, die in den Ruinen nisten, und der vordringenden industriellen Zerstörung durch die nahe gelegene Venture Company.",al={"gefahren im verbrannten tal","was zerstört das land"}}},fp="20,320,20.549.0,22.493.0,39.206.0,37.200.0,45.253.0,36.204.0"}
P.entries["item:enchanted-resonite-crystal"] = {n="Verzauberter Resonitkristall",s="Der Verzauberte Resonitkristall ist ein alchemistisch verändertes Mineral, das von Mor'rogal im Steinkrallengebirge mit schamanischer Magie erfüllt wurde. Er wurde eigens dafür geschaffen, das Resonitfass zu zerschlagen, welches einen schlummernden, uralten Irdene namens Goggeroc gefangen hält.",h="Der Verzauberte Resonitkristall ist ein alchemistisch verändertes Mineral, das von Mor'rogal im...",kw={"der irdene erhebt sich","verzauberter resonitkristall","goggeroc","mor'rogal","resonitfass","resonitkristall","steinkrallengebirge"},ang={["class:Shaman"]="Der Kristall veranschaulicht, wie elementare Manipulation selbst die uralte titanengeschmiedete Erdmagie destabilisieren kann, die lebenden Stein bindet.",["faction:Horde"]="Das Gleichgewicht im Steinkrallengebirge ist prekär, und Mor'rogal verlässt sich auf die Recken der Horde, um uralte Bedrohungen auszuschalten, bevor sie die regionalen Außenposten gefährden."},sec={{t="Brecher des uralten Steins",b="Rohe Resonitkristalle, die aus den tiefen Höhlen des Steinkrallengebirges geborgen werden, besitzen ungewöhnliche harmonische und erdverbundene Eigenschaften. Der Schamane Mor'rogal erkannte die Gefahr, die in einem versiegelten unterirdischen Fass schlummerte, und veränderte die rohen Mineralien mithilfe seiner Elementarkräfte. Der daraus resultierende Verzauberte Resonitkristall dient als präzises Werkzeug: Schlägt man damit gegen das verstärkte Resonitfass, bricht die Einfassung auf und weckt den riesigen Irdenen Goggeroc gewaltsam, während er von seinem langen Schlaf noch desorientiert ist."},{t="Die Bedrohung durch Goggeroc",b="Mor'rogal glaubte, dass ein unkontrollierter uralter Irdener eine Katastrophe für das empfindliche Gleichgewicht des Steinkrallengebirges und ganz Kalimdors bedeuten würde. Indem das Fass mit dem verzauberten Kristall zerschlagen wird, will Mor'rogal die Kreatur in einem geschwächten Zustand zum Erwachen zwingen, was ein kurzes Zeitfenster bietet, um Goggeroc zu vernichten, bevor seine volle elementare Macht zurückkehrt."}},faq={{q="Wofür wird der Verzauberte Resonitkristall verwendet?",a="Er dient dazu, das Resonitfass tief in den von Kobolden verseuchten Höhlen des Steinkrallengebirges zu zerschlagen und so den schlummernden Irdenen namens Goggeroc zu befreien.",al={"verzauberter resonitkristall verwendung","was bewirkt kristall","resonitfass zerschlagen"}},{q="Wer hat diesen verzauberten Kristall erschaffen?",a="Der Taurenschamane Mor'rogal erschuf ihn, indem er rohe Resonitkristalle mit seinen schamanistischen Kräften erfüllte, um das schlafende Wesen im Fass zu schwächen und freizulegen.",al={"wer erschuf kristall","mor'rogal kristall","verzauberter resonit schöpfer"}},{q="Warum muss Goggeroc erweckt und vernichtet werden?",a="Mor'rogal fürchtet, dass die unvergleichliche Macht eines rasenden uralten Irdenen das gesamte Steinkrallengebirge und Kalimdor gefährden würde. Wird er mit dem Kristall erweckt, ist er vorübergehend geschwächt, was einen Sieg über ihn überhaupt erst ermöglicht.",al={"warum goggeroc töten","ist goggeroc gefährlich","goggeroc bedrohung"}},{q="Was soll ich nach dem Sieg über Goggeroc mit dem Kristall tun?",a="Ihr müsst den Verzauberten Resonitkristall zusammen mit der Bestätigung, dass Goggeroc getötet wurde, zu Mor'rogal zurückbringen.",al={"resonitkristall zurückbringen","verzauberten resonitkristall abgeben"}}},fp="26,245,24.511.0,22.360.1,48.158.0,35.158.0,44.223.0,59.117.0"}
P.entries["item:encrypted-memorandum"] = {n="Verschlüsseltes Memorandum",s="Das Verschlüsselte Memorandum ist ein codiertes Schreiben, das angehenden Schurken überreicht wird, die ihre Reise im Coldridgetal beginnen. Obwohl es als offizielle Mitteilung getarnt ist, handelt es sich in Wirklichkeit um eine heimliche Einladung des örtlichen Schurkenlehrers Solm Hargrin, der zu Solidarität unter den Halunken im Exil aufruft.",h="Das Verschlüsselte Memorandum ist ein codiertes Schreiben, das angehenden Schurken überreicht wird, die ihre...",kw={"anvilmar","das coldridgetal","dun morogh","verschlüsseltes memorandum","gnomeregan","schurkenlehrer","solm hargrin"},ang={["class:Rogue"]="Dieser codierte Brief dient als Eure formelle Einberufung in die Schatten von Dun Morogh und verbindet Euch direkt mit Eurem örtlichen Ausbilder in Anvilmar.",["race:Gnome"]="Als Flüchtlinge unter den Zwergen nach dem Fall von Gnomeregan finden Gnomschurken in dieser Notiz ein stilles Angebot von Solidarität und Überleben."},sec={{t="Eine diskrete Aufforderung",b="In der geschäftigen Zwergenzuflucht Anvilmar müssen Schurken ein unauffälliges Profil wahren. Anstatt Rekruten offen anzusprechen, nutzt der Ausbilder Solm Hargrin das Verschlüsselte Memorandum zur Kontaktaufnahme. Als offizielle Anweisung entfernter Vorgesetzter getarnt, stellt das codierte Pergament sicher, dass junge Schurken wissen, wo sie Mentorschaft finden, ohne die unerwünschte Aufmerksamkeit der örtlichen Wachen oder misstrauischer Stadtbewohner zu erregen."},{t="Verbundenheit im Coldridgetal",b="Hinter der Chiffre verbirgt sich eine Botschaft des praktischen Überlebens. Da Gnomeregan verloren ist und vertriebene Gnome Seite an Seite mit ihren Zwergenverbündeten in die schneebedeckten Siedlungen von Dun Morogh gepfercht wurden, brodeln Spannungen dicht unter der Oberfläche. Solm nutzt die Nachricht, um eine stille Kameradschaft aufzubauen, und erinnert seine Schüler daran, dass Vertreter ihres Handwerks aufeinander achtgeben müssen, wenn Sündenbockmentalität und Vorurteile drohen, ihnen jedes fehlende Schmuckstück anzuhängen."}},faq={{q="Was ist das Verschlüsselte Memorandum?",a="Es ist ein codiertes Pergament, das angehenden Schurken im Coldridgetal überbracht wird und sie unter dem Deckmantel einer offiziellen Depesche anweist, Schurkentraining aufzusuchen.",al={"was ist das verschlüsselte memorandum","memorandum gegenstand","schurkennotiz"}},{q="Wer hat dieses Memorandum verfasst?",a="Es wurde von Solm Hargrin verfasst, dem in Anvilmar stationierten Schurkenlehrer, der es als offizielle Befehle tarnte, um seine Gaunerkollegen diskret zu versammeln.",al={"wer hat das memorandum geschrieben","wer hat das verschlüsselte memorandum geschickt","autor des memorandums"}},{q="Warum ist die Nachricht verschlüsselt?",a="Schurken, die im Coldridgetal operieren, meiden die öffentliche Aufmerksamkeit. Die Tarnung der Einladung als routinemäßiges bürokratisches Memorandum verhindert, dass örtliche Behörden und neugierige Zuschauer auf heimliche Ausbildungen aufmerksam werden.",al={"warum verschlüsselt","warum chiffriert","warum ist es codiert"}},{q="Was möchte Solm Hargrin?",a="Solm möchte Kampftraining, Führung und gegenseitigen Schutz anbieten und betont, dass Schurken im überfüllten Dun Morogh zusammenhalten müssen, wo Dieben schnell die Schuld an verschwundenen Gegenständen gegeben wird.",al={"was will solm","warum solm finden","solms ziel"}}},fp="20,279,18.422.0,20.439.1,33.159.0,26.156.0,29.198.0,28.187.0"}
P.entries["item:encrypted-parchment"] = {n="Verschlüsseltes Pergament",s="Das Verschlüsselte Pergament ist ein chiffriertes Schreiben, das angehenden Ork-Schurken überreicht wird, die im Tal der Prüfungen trainieren. Es wird von Gornek übergeben und leitet vielversprechende Rekruten diskret in die Schatten des Höhlenbaus, um den verdeckten Ausbilder Rwag zu treffen.",h="Das Verschlüsselte Pergament ist ein chiffriertes Schreiben, das angehenden Ork-Schurken überreicht wird, die...",kw={"durotar","verschlüsseltes pergament","gornek","ork schurke","rwag","die shattered-hand","der höhlenbau","das tal der prüfungen"},ang={["class:Rogue"]="Das Pergament steht für Eure Einführung in die geheime Unterwelt der Horde und weist Euch den Weg zu Mentoren, die der Shattered-Hand angehören.",["race:Orc"]="Während die Kultur der Orks normalerweise den offenen, ehrenhaften Kampf schätzt, heißt dieses Schreiben jene willkommen, deren Talente in den leiseren, tödlicheren Überlebenskünsten liegen."},sec={{t="Ein Ruf aus den Schatten",b="Junge Orks, die ihr kriegerisches Können im Tal der Prüfungen unter Beweis stellen wollen, kämpfen typischerweise unter freiem Himmel in der Sonne. Jene jedoch, die ein Talent für Heimlichkeit, Täuschung und Klingenkunst zeigen, ziehen eine ganz andere Art von Aufmerksamkeit auf sich. Das Verschlüsselte Pergament wird vielversprechenden Ork-Schurken von Gornek überreicht, sobald sie sich an der einheimischen Tierwelt bewährt haben. Statt einer offenen Ankündigung ist die Nachricht verschlüsselt, um sicherzustellen, dass nur jemand mit einem Blick für Täuschung und List diesem Ruf folgt."},{t="Verbindungen zur Shattered-Hand",b="Die Entzifferung des Pergaments führt den Neuling tief in die als der Höhlenbau bekannte Höhle, vorbei an den wachsamen Augen anderer Clan-Ausbilder, um Rwag zu finden. Dort erfährt der Rekrut, dass die Vorladung im Namen der Shattered-Hand arrangiert wurde – einem Orden, der innerhalb des verdeckten Netzwerks der Horde operiert. Indem der Schurke dem Pergament Folge leistet, macht er seinen ersten Schritt in eine Welt voller Spionage, Schattenkünste und wohlgehüteter Geheimnisse."}},faq={{q="Was ist der Zweck des Verschlüsselten Pergaments?",a="Es dient als verschlüsselte Vorladung, die angehende Ork-Schurken an ihren Klassenlehrer Rwag heranführt, der im Höhlenbau im Tal der Prüfungen lauert.",al={"was ist verschlüsseltes pergament","zweck des pergaments","warum verschlüsseltes pergament"}},{q="Wer schickt Euch das Pergament?",a="Die Nachricht stammt vom Schurkenlehrer Rwag, wird Euch jedoch von Gornek überreicht, nachdem Ihr Eure ersten Prüfungen im Tal abgeschlossen habt.",al={"wer schrieb das pergament","absender des pergaments","wer gab mir das pergament"}},{q="Warum ist die Nachricht chiffriert?",a="Rwag und seine Kontakte innerhalb der Shattered-Hand bevorzugen Geheimhaltung gegenüber offenen Erklärungen. Eine chiffrierte Nachricht stellt sicher, dass nur jemand, der für den subtilen Pfad eines Schurken geeignet ist, in ihre verborgenen Ränge geführt wird.",al={"warum ist es verschlüsselt","warum verschlüsselt","geheime nachricht"}},{q="Welche Organisation steckt hinter der Vorladung?",a="Rwag enthüllt, dass die Shattered-Hand ihn gebeten hat, nach fähigen Rekruten Ausschau zu halten. Sie bieten eine Ausbildung in Heimlichkeit und Spionage an, um der Horde aus den Schatten heraus zu dienen.",al={"wer will mich ausbilden","shattered-hand schurke","welche fraktion schickte dies"}},{q="Können Troll-Schurken dieses Pergament nutzen?",a="Nein. Obwohl Troll-Schurken ebenfalls im Tal der Prüfungen beginnen, erfolgt ihre geheime Vorladung in Form einer Verschlüsselten Schrifttafel und nicht über dieses Pergament.",al={"verschlüsseltes pergament der trolle","ist es auch für trolle"}}},fp="19,237,26.478.0,26.406.0,47.146.0,31.142.0,37.203.0,40.169.0,36.151.0"}
P.entries["item:encrypted-rune"] = {n="Verschlüsselte Rune",s="Eine Verschlüsselte Rune ist eine chiffrierte Vorladungsnachricht, die vielversprechenden neuen Schurken im Coldridgetal überreicht wird. Heimlich überbracht, fordert sie den Träger auf, ihren Inhalt zu entschlüsseln und den Schurkenlehrer Solm Hargrin in Anvilmar aufzusuchen.",h="Eine Verschlüsselte Rune ist eine chiffrierte Vorladungsnachricht, die vielversprechenden neuen Schurken im...",kw={"anvilmar","chiffre","das coldridgetal","dun morogh","verschlüsselte rune","schurke","solm hargrin"},ang={["class:Rogue"]="Diese Rune markiert Euren ersten formellen Kontakt mit dem Netzwerk der Schurken in Dun Morogh und weiht Euch in die Künste des Schleichgangs, der schnellen Klingen und des Überlebens ein.",["race:Dwarf"]="Im Coldridgetal weitergereicht, ruft die Rune ein weiteres Kind von Ironforge dazu auf, die Schatten zu meistern und die Interessen des Clans unter der Oberfläche zu schützen."},sec={{t="Eine chiffrierte Vorladung",b="Im geschützten, verschneiten Becken des Coldridgetals ist offene Rekrutierung selten der Stil der einheimischen Schurken und Kundschafter. Stattdessen wird Neulingen, die Geschick für Schleichen und List zeigen, eine Verschlüsselte Rune zugesteckt. Versehen mit subtilen Chiffren, birgt der beschriftete Stein eine diskrete Einladung von Solm Hargrin, dem in Anvilmar einquartierten Schurkenmentor. Er dient sowohl als diskrete Prüfung im Lesen des Gaunerzinkens als auch als Einführung in das schattenhafte Handwerk, das man benötigt, um in Dun Moroghs rauer Wildnis zu überleben."},{t="Augen in den Schatten",b="Das Entschlüsseln der Rune führt neue Schurken zu Solm, der die verdeckten Reihen des Tals angesichts wachsender lokaler Spannungen verstärken will. Über grundlegenden Klingenkampf und Schleichtechniken hinaus betont Solm Wachsamkeit und Kameradschaft und fordert neue Schurken auf, ein wachsames Auge auf ihre gnomischen Verbündeten zu haben, die nach dem Fall von Gnomeregan vor Kurzem vertrieben wurden."}},faq={{q="Was ist die Verschlüsselte Rune?",a="Es ist eine chiffrierte Nachricht, die angehenden Schurken im Coldridgetal überbracht wird und sie anweist, sich bei Solm Hargrin in Anvilmar zur Ausbildung zu melden.",al={"was ist diese rune","zweck der verschlüsselten rune","was macht die rune"}},{q="Wer hat die Verschlüsselte Rune geschickt?",a="Die Nachricht stammt von Solm Hargrin, dem in Anvilmar stationierten Schurkenlehrer, der sie nutzt, um neue Rekruten heimlich herbeizurufen, ohne unerwünschte Aufmerksamkeit zu erregen.",al={"wer hat sie geschrieben","wer hat dies gegeben","absender der rune"}},{q="Wohin sollte ich die Rune bringen?",a="Bringt die entschlüsselten Anweisungen zu Solm Hargrin, der im Inneren von Anvilmar im Coldridgetal zu finden ist.",al={"wohin muss ich","zu wem bringen","wo ist solm"}},{q="Warum ist die Nachricht verschlüsselt?",a="Schurken verlassen sich auf Geheimhaltung, Täuschung und verdeckte Kommunikation. Das Senden einer verschlüsselten Rune stellt sicher, dass nur ein aufstrebender Schurke, der die Chiffre lesen kann, dem Ruf folgt, wodurch ihre Methoden verborgen bleiben.",al={"warum chiffre","warum ist sie codiert","warum geheime rune"}}},fp="14,223,15.503.0,19.353.0,27.145.0,28.165.0,29.107.0,29.209.0"}
P.entries["item:encrypted-scroll"] = {n="Verschlüsselte Rolle",s="Die Verschlüsselte Rolle ist ein unauffälliges Pergament, das vielversprechenden, neu auferstandenen Schurken in Deathknell überreicht wird. Sie trägt das Siegel von David Trias und weist den Empfänger an, sich für die formelle Ausbildung unter den verdeckten Agenten der Forsaken vorzustellen.",h="Die Verschlüsselte Rolle ist ein unauffälliges Pergament, das vielversprechenden, neu auferstandenen Schurken...",kw={"david trias","deathknell","verschlüsselte rolle","schurken der forsaken","schurkenlehrer","shadowstalkers","tirisfal"},ang={["class:Rogue"]="Die Schriftrolle markiert den Beginn Eurer professionellen Ausbildung in Heimlichkeit, Schlossknacken und schmutzigen Kampfpraktiken unter den wachsamen Augen der Schurkenkader der Forsaken.",["race:Undead"]="Für die Neuauferstandenen in Deathknell stellt diese Vorladung eine frühe Gelegenheit dar, sich eine bedeutsame Rolle innerhalb von Sylvanas' aufstrebendem Königreich zu sichern."},sec={{t="Eine verdeckte Vorladung",b="Wenn ein frisch erwachter Forsaken eine Begabung für Heimlichkeit und Täuschung zeigt, bleibt dies nicht lange unbemerkt. Die Verschlüsselte Rolle wird in Deathknell überreicht, sobald sich ein Späher gegen die geistlose Geißel behauptet hat, die den nahegelegenen Friedhof durchstreift. Mit dem persönlichen Siegel des Schurkenlehrers David Trias versehen, weist die Schriftrolle ihren Träger an, ihn im örtlichen Gasthaus aufzusuchen. Sie dient als anfängliches Auswahlverfahren und lenkt angehende Agenten zu jener Disziplin, die erforderlich ist, um der Dunklen Fürstin zu dienen, anstatt ihre zweite Chance auf ein Leben als bloße Taschendiebe zu vergeuden."},{t="Augen der Schattenpirscher",b="Die Botschaft selbst ist kurz gehalten und weist den Schurken an, Kontakt innerhalb von Deathknell aufzunehmen, bevor er tiefer nach Tirisfal vordringt. Trias behält aufstrebende Talente im Auftrag der Shadowstalkers, des verdeckten Arms der Forsaken, im Auge. Um in Lordaeron zu überleben, verlassen sich die Forsaken stark auf lautlose Klingen und gerissene Späher, um dem Scharlachroten Kreuzzug, überlebenden Enklaven der Alliance und übrig gebliebenem Geißelunrat entgegenzutreten. Dieser verschlüsselten Vorladung zu folgen, ist der erste Schritt zum Beitritt in dieses verdeckte Netzwerk."}},faq={{q="Was ist der Zweck der Verschlüsselten Rolle?",a="Die Verschlüsselte Rolle ist eine einleitende Vorladung an neu auferstandene Schurken der Forsaken. Sie weist sie an, sich bei David Trias im Gasthaus von Deathknell einzufinden, um ihre professionelle Schurkenausbildung zu beginnen.",al={"was bewirkt rolle","warum verschlüsselte rolle","zweck der rolle"}},{q="Wer verschickt die Verschlüsselte Rolle?",a="Die Schriftrolle trägt das persönliche Siegel von David Trias, dem ortsansässigen Schurkenlehrer in Deathknell, der nach vielversprechenden neuen Rekruten Ausschau hält.",al={"wer schrieb rolle","absender der rolle","von wem ist die rolle"}},{q="Was sind die von David Trias erwähnten Shadowstalkers?",a="Die Shadowstalkers sind eine verdeckte Gruppierung von Schurken, Spähern und Attentätern der Forsaken, die in ganz Lordaeron operieren. Trias bewertet neue Talente, um zu bestimmen, wer würdig ist, sich schließlich ihren Rängen anzuschließen.",al={"wer sind shadowstalkers","shadowstalkers forsaken","orden der shadowstalker"}},{q="Wohin bringe ich die Verschlüsselte Rolle nach dem Lesen?",a="Bringt die Schriftrolle nach dem Lesen direkt zu David Trias, der im Inneren des Gasthauses von Deathknell lauert.",al={"wo rolle abgeben","zu wem rolle bringen","rolle abgabe"}}},fp="16,243,16.574.0,26.501.0,44.197.0,31.145.0,53.200.0,54.114.0"}
P.entries["item:encrypted-sigil"] = {n="Verschlüsselte Siegelzeichen",s="Das Verschlüsselte Siegelzeichen ist ein kodiertes Zeichen, das neu erwachten Schurken der Nachtelfen in Shadowglen überbracht wird. Es enthält verborgene Anweisungen des Ausbilders Frahun Shadewhisper und weist angehende Agenten an, ihre Ausbildung angesichts wachsender Bedrohungen für Teldrassil zu beginnen.",h="Das Verschlüsselte Siegelzeichen ist ein kodiertes Zeichen, das neu erwachten Schurken der Nachtelfen in...",kw={"aldrassil","verschlüsselte siegelzeichen","frahun shadewhisper","kaldorei schurke","schurkenlehrer","shadowglen","teldrassil"},ang={["class:Rogue"]="Das Siegelzeichen stellt den Ausgangspunkt der Reise eines Nachtelfenschurken dar und stellt Eure Fähigkeit auf die Probe, Anweisungen zu entschlüsseln und Kontakt zu Eurem örtlichen Mentor aufzunehmen.",["race:NightElf"]="Für die Kaldorei liefern verdeckte Agenten entscheidende Informationen in einer fragilen Ära, in der alte Waldgrenzen neuen Übergriffen der Horde ausgesetzt sind."},sec={{t="Eine verborgene Vorladung",b="In der geschützten Senke von Shadowglen werden aufstrebende Späher und Infiltratoren der Nachtelfen über diskrete Wege kontaktiert. Das Verschlüsselte Siegelzeichen wird einem Initianden von einem stillen Boten im Auftrag von Frahun Shadewhisper direkt übergeben. Das Siegelzeichen verbirgt seinen Inhalt auf eine für das Gewerbe angemessene Weise und weist den Empfänger an, sich bei Frahun in der Nähe von Aldrassil zu melden. Für Shadewhisper beweist das Lesen und Überbringen des Zeichens, dass ein Initiand subtile Anweisungen befolgen und mit verdeckten Botschaften umgehen kann."},{t="Augen in den Schatten",b="Frahun nutzt diese Vorladung, um die Notwendigkeit von Schurken in einer unruhigen Welt zu betonen. Da die Spannungen zwischen den Nachtelfen und der fernen Horde schwelen, erinnert Shadewhisper seine Rekruten daran, dass offene Kriegsführung nicht die einzige Gefahr ist, der ihr Volk gegenübersteht. Schurken müssen als die ersten Augen und ungesehenen Klingen der Kaldorei dienen, die in ganz Teldrassil Informationen sammeln und lernen zuzuschlagen, bevor Bedrohungen in den Ästen des Weltenbaums Wurzeln schlagen können."}},faq={{q="Was ist der Zweck des Verschlüsselten Siegelzeichens?",a="Es dient als einleitende Vorladung für angehende Nachtelfenschurken. Es enthält verborgene Anweisungen und weist den Träger an, sich bei Frahun Shadewhisper in der Nähe von Aldrassil zu melden, um die formelle Schurkenausbildung zu beginnen.",al={"was macht das siegelzeichen","wofür ist verschlüsseltes siegelzeichen","warum habe ich verschlüsseltes siegelzeichen"}},{q="Wer verschickt das Verschlüsselte Siegelzeichen?",a="Das Siegelzeichen wird von Frahun Shadewhisper entsandt, dem Schurkenlehrer, der in Shadowglen unter den Ästen von Aldrassil stationiert ist.",al={"wer schrieb dieses siegelzeichen","wer sandte verschlüsseltes siegelzeichen","von wem ist das siegelzeichen"}},{q="Was will Frahun Shadewhisper von mir?",a="Frahun möchte Eure Einsatzbereitschaft prüfen, die wachsenden Gefahren betonen, die die Nachtelfen bedrohen – einschließlich potenzieller Unruhen durch die Horde –, und grundlegenden Kampfunterricht erteilen.",al={"warum will frahun mich","frahun quest","warum mit frahun sprechen"}},{q="Wohin soll ich das Siegelzeichen bringen, sobald ich es gelesen habe?",a="Bringt es zu Frahun Shadewhisper, der in der Nähe der großen Hügelgräber und Pfade rund um die zentrale Senke von Aldrassil in Shadowglen zu finden ist.",al={"wohin verschlüsseltes siegelzeichen bringen","frahun standort","wo ist frahun"}}},fp="15,259,16.498.0,19.443.0,43.205.0,30.126.0,43.195.0,45.141.0"}
P.entries["item:encrypted-tablet"] = {n="Verschlüsselte Schrifttafel",s="Die Verschlüsselte Schrifttafel ist eine kodierte Botschaft, die angehenden Schurken der Darkspear überbracht wird, die im Tal der Prüfungen trainieren. Verfasst vom Schurkenlehrer Rwag, ruft sie vielversprechende Beutelschneider und Späher zu seinem Posten im Höhlenbau.",h="Die Verschlüsselte Schrifttafel ist eine kodierte Botschaft, die angehenden Schurken der Darkspear überbracht...",kw={"durotar","verschlüsselte schrifttafel","schurkenlehrer","rwag","shattered-hand","der höhlenbau","das tal der prüfungen"},ang={["class:Rogue"]="Die chiffrierte Tafel stellt Eure anfängliche Aufnahme in die formellen Ränge der Hordeschurken dar und weist Euch den Weg zu Rwags Ausbildung im Höhlenbau.",["race:Troll"]="Darkspear, die in Durotar trainieren, erhalten diese Schrifttafel als Beweis dafür, dass ihre Beweglichkeit und Heimlichkeit die Aufmerksamkeit der Ausbilder des Tals erregt haben."},sec={{t="Eine verborgene Vorladung",b="Angehende Schurken der Trolle, die im Tal der Prüfungen eintreffen, erhalten die Verschlüsselte Schrifttafel als ihre erste Anweisung. Versehen mit chiffrierten Instruktionen weist die Tafel sie direkt zu Rwag, einem Orc-Ausbilder, der in den schattigen Höhlen des Höhlenbaus weilt. Statt Gildenangelegenheiten öffentlich zu verkünden, nutzen die örtlichen Schattenagenten diese verschlüsselten Tafeln, um das Auffassungsvermögen zu prüfen und neue Talente diskret unter offizielle Anleitung zu stellen."},{t="Augen der Hand",b="Das Entziffern der Schrifttafel führt Rekruten an das größere Schattennetzwerk der Horde heran. Nach ihrer Meldung bei Rwag erfahren die Späher, dass ihre Fortschritte von finsteren Syndikaten wie der Shattered-Hand genau beobachtet werden, die auf die Ausbilder des Tals setzen, um sicherzustellen, dass angehende Beutelschneider, Spione und Attentäter scharfsinnig genug sind, um der neuen Nation zu dienen."}},faq={{q="Wofür wird die Verschlüsselte Schrifttafel verwendet?",a="Die Verschlüsselte Schrifttafel dient als verschlüsselte Vorladung, die junge Trollschurken anweist, sich bei Rwag zu melden, dem örtlichen Schurkenlehrer im Höhlenbau im Tal der Prüfungen.",al={"zweck der schrifttafel","was bewirkt verschlüsselte schrifttafel","warum habe ich verschlüsselte schrifttafel"}},{q="Wer hat die Nachricht auf der Schrifttafel verfasst?",a="Die Nachricht wurde von Rwag verfasst, dem Schurkenlehrer im Tal der Prüfungen, der die Ausbildung von Dieben, Beutelschneidern und Attentätern für die Horde überwacht.",al={"wer schickte verschlüsselte schrifttafel","autor der schrifttafel","wer hat das geschrieben"}},{q="Wo finde ich Rwag?",a="Rwag befindet sich tief im Inneren des Höhlenbaus, einem Höhlenkomplex am nördlichen Grat des Tals der Prüfungen in Durotar.",al={"wo ist rwag","rwag aufenthaltsort","schurkenlehrer tal der prüfungen finden"}},{q="Was ist 'die Hand', die von Rwag erwähnt wird?",a="Die Hand bezieht sich auf die Shattered-Hand, einen geheimen Orden, der innerhalb des Schurkennetzwerks der Horde operiert. Rwag erstattet ihnen Bericht über die Einsatzbereitschaft neuer Agenten, die aus dem Tal hervorgehen.",al={"welche hand","wer ist die hand","verbindung zur shattered-hand"}}},fp="16,223,16.432.0,16.331.0,38.175.0,36.152.0,21.114.0,37.190.0"}
P.entries["item:essence-of-nightlash"] = {n="Nachtseeles Essenz",s="Nachtseeles Essenz ist der verbleibende magische Rückstand, der von der besiegten Banshee Nightlash auf dem Todesfeld gesammelt wird. Sie dient Hochexekutor Hadrec als unwiderlegbarer Beweis dafür, dass die Streitkräfte der Geißel, die die örtlichen Moderfellgnolle verstärkten, gebrochen wurden.",h="Nachtseeles Essenz ist der verbleibende magische Rückstand, der von der besiegten Banshee Nightlash auf dem...",kw={"banshee","das todesfeld","staub","essenz","hadrec","nightlash","moderfell","das grabmal"},ang={["class:Mage"]="Arkanisten und Gelehrte untersuchen oft die Rückstände vernichteter Banshees, um zu erforschen, wie spektrale Untote nekrotische Magie an die physische Welt binden.",["race:Undead"]="Soldaten der Verlassenen betrachten die Beseitigung von Banshees wie Nightlash als entscheidende Aufgabe; als ehemalige Opfer der Herrschaft der Geißel ist die Vernichtung von Dienern des Lichkönigs von zentraler Bedeutung, um Lordaeron für ihr eigenes Volk zu sichern."},sec={{t="Die Banshee des Todesfelds",b="Auf einem verlassenen Gehöft im nördlichen Silverpine, bekannt als das Todesfeld, haben sich Rudel untoter Moderfellgnolle unter dem Befehl der Geißel verschanzt. Erste Angriffe der Verlassenen wurden wiederholt nicht von den wilden Gnollen abgewehrt, sondern von deren spektraler Befehlshaberin: der Banshee Nightlash. Mithilfe klagender Magie stärkte sie die Reihen der Gnolle und schlug die aus dem Grabmal entsandten Streitkräfte in die Flucht. Ihre Tötung lässt ihre unkörperliche Gestalt zu Staub zerfallen und hinterlässt eine kristalline, magische Essenz, die ihre endgültige Vernichtung darstellt."},{t="Beweis für die Niederlage der Geißel",b="Da Banshees keinen körperlichen Leichnam hinterlassen, ist Nachtseeles Essenz der einzige physische Beweis dafür, dass der bösartige Geist vernichtet wurde. Hochexekutor Hadrec im Grabmal verlangt nach dieser Essenz, um zu bestätigen, dass der örtliche Stützpunkt der Geißel zusammengebrochen ist, wodurch die Verlassenen endlich ihre nördliche Grenze sichern und die Bedrohung durch die Moderfelle unterdrücken können."}},faq={{q="Was ist Nachtseeles Essenz?",a="Es ist der kristallisierte Staub, der zurückbleibt, wenn die Geißel-Banshee Nightlash besiegt wird. Da Geister keine physischen Körper besitzen, dient dieser magische Rückstand als Beweis für ihr Ende.",al={"nachtseeles essenz","nightlash staub","was ist nachtseeles essenz"}},{q="Wer ist Nightlash?",a="Nightlash ist eine mit der Geißel verbündete Banshee, die die Moderfellgnolle anführt und verstärkt, die vom Todesfeld im nördlichen Silverpine aus operieren.",al={"wer ist nightlash","nightlash lore","banshee nightlash"}},{q="Wer möchte diese Essenz haben?",a="Hochexekutor Hadrec im Grabmal bittet Champions der Verlassenen darum, sie zu beschaffen, um zu beweisen, dass die Banshee, die seine Frontalangriffe abwehrte, neutralisiert worden ist.",al={"wer braucht nachtseeles essenz","wer nimmt essenz an","hochexekutor hadrec"}},{q="Warum arbeiten die Gnolle mit einer Banshee zusammen?",a="Die Moderfellgnolle auf dem Todesfeld sind der Seuche des Untods erlegen, was sie zu Knechten der Geißel macht. Nightlash wurde entsandt, um sie zu beaufsichtigen und magische Unterstützung gegen die Patrouillen der Verlassenen zu leisten.",al={"gnolle und geißel","moderfell geißel","warum gnolle mit banshee"}}},fp="20,256,30.536.0,23.370.0,33.178.0,17.148.0,23.155.0,42.203.0"}
P.entries["item:essential-artificial"] = {n="Grundlegendes Artifix",s="Ein Grundlegendes Artifix ist eine vielseitige, standardisierte mechanische Komponente, die für gnomische Tüftler und Ingenieure unerlässlich ist. Während der hektischen Evakuierung von Gnomeregan in Vorratslagern zurückgelassen, sind diese Teile bei Gnomen heiß begehrt, die ihre technologischen Bestrebungen aus dem Exil in Ironforge wieder aufbauen wollen.",h="Ein Grundlegendes Artifix ist eine vielseitige, standardisierte mechanische Komponente, die für gnomische...",kw={"künstlicher extrapolator","ingenieurskomponente","grundlegendes artifix","gnomeregan","klockmort spannerspan","tinker town"},ang={["profession:Engineering"]="Ingenieure wissen die Eleganz eines nahezu universellen mechanischen Bauteils zu schätzen, das sich nahtlos in die verschiedensten Maschinen und experimentellen Entwürfe einfügt.",["race:Gnome"]="Jede aus den verstrahlten Korridoren von Gnomeregan geborgene Komponente hilft den verbannten Gnomen dabei, ihre technologische Überlegenheit wiederzuerlangen, während sie in Ironforge Zuflucht suchen."},sec={{t="Genialität nach Standardausführung",b="Vor dem Fall von Gnomeregan diente das grundlegende Artifix als Eckpfeiler der alltäglichen gnomischen Ingenieurskunst. Von Tüftlern als nahezu universelle Komponente beschrieben, wurde es in den unterirdischen Hallen in unzählige Vorrichtungen, Uhrwerkwunder und schwere Maschinen integriert. Seine standardisierte Beschaffenheit machte es für Schmiede und Maschinisten unverzichtbar, die zuverlässige, austauschbare modulare Teile benötigten."},{t="Bergung aus den Tiefen",b="Als die Trogg-Invasion und die darauffolgende Strahlungskatastrophe die Gnome zu einem verzweifelten, panischen Exodus zwangen, wurden riesige Reserven dieser Komponenten an Ort und Stelle zurückgelassen. Sie lagern nach wie vor in schweren, dampfbetriebenen Spendern, den sogenannten künstlichen Extrapolatoren, die in den tieferen Gängen von Gnomeregan verstreut sind. In Tinker Town wirbt Handwerksmeister Klockmort Spannerspan tatkräftig wagemutige Abenteurer an, um sich wieder in die verseuchten Ruinen zu wagen und diese Teile zu bergen, damit Forschung und Erfindungsgeist weitergehen können."}},faq={{q="Was ist ein Grundlegendes Artifix?",a="Es ist eine standardisierte, äußerst vielseitige mechanische Komponente, die von gnomischen Schmieden und Tüftlern weithin für ihre Experimente, Maschinen und Vorrichtungen verwendet wird.",al={"was sind grundlegende artifixe","grundlegendes artifix gegenstand","was ist diese komponente"}},{q="Warum wurden sie in Gnomeregan zurückgelassen?",a="Als die Troggs einfielen und die Stadt mit tödlicher Strahlung überflutet wurde, flohen die Gnome in panischer Eile. In der Hektik der Evakuierung wurden die Vorräte alltäglicher Komponenten schlichtweg in Lagergeräten zurückgelassen.",al={"warum sind sie in gnomeregan","warum zurückgelassen"}},{q="Wer möchte diese Komponenten geborgen haben?",a="Klockmort Spannerspan, ein ehrgeiziger Gnomen-Erfinder mit Sitz in Tinker Town in Ironforge, sucht nach ihnen, um seine laufenden Experimente und technologischen Forschungen im Exil voranzutreiben.",al={"wer braucht grundlegende artifixe","wer nimmt diese an","klockmort spannerspan quest"}},{q="Wo sind sie in den Ruinen zu finden?",a="Sie lagern in großen, dampfbetriebenen mechanischen Behältern, den sogenannten künstlichen Extrapolatoren, die in den tieferen Ebenen des verseuchten Gnomeregan aufgestellt sind.",al={"wo finde ich grundlegende artifixe","künstlicher extrapolator standort"}}},fp="20,302,24.407.0,23.522.0,32.152.0,40.212.0,37.173.0,38.166.0"}
P.entries["item:etched-note"] = {n="Geätzte Notiz",s="Die Geätzte Notiz ist eine formelle Vorladung für vielversprechende junge Taurenjäger, die im Camp Narache verweilen. Verfasst von der Jägerlehrerin des Lagers, Lanka Farshot, heißt die Botschaft den Neuling in den Traditionen der Jagd willkommen und ruft ihn zu seiner ersten Unterweisung herbei.",h="Die Geätzte Notiz ist eine formelle Vorladung für vielversprechende junge Taurenjäger, die im Camp Narache...",kw={"camp narache","geätzte notiz","lanka farshot","mulgore","red cloud mesa","taurenjäger","lehrervorladung"},ang={["class:Hunter"]="Die Notiz markiert Eure formelle Aufnahme in die Jägertradition und verspricht Unterricht im Umgang mit Fernkampfwaffen sowie in der Zwiesprache mit den Bestien der Ebenen.",["race:Tauren"]="Im Bewusstsein der Erwartungen Eurer Ältesten und Eurer Blutlinie fordert Euch der Erhalt dieser Notiz dazu auf, das sanfte Grasland von Mulgore zu meistern, bevor Ihr in ferne Länder reist."},sec={{t="Ein Ruf zur Jagd",b="In den sicheren Grenzen von Camp Narache werden junge Shu'halo früh anhand ihrer natürlichen Neigungen und familiären Abstammungslinien erkannt. Die Geätzte Notiz wird von einem Läufer im Namen von Lanka Farshot überbracht, der ansässigen Jägermentorin. Sie lobt die Blutlinie und das angeborene Talent des angehenden Jägers und dient zugleich als ernste Mahnung, dass roher Instinkt durch strenge Unterweisung und tiefe Ehrfurcht vor der Wildnis von Mulgore gezähmt werden muss."},{t="Traditionen der Shu'halo",b="Für die Tauren ist die Jagd weit mehr als eine praktische Methode zum Überleben – sie ist eine geehrte, heilige Disziplin, die fest in der Stammesgesellschaft verwoben ist. Die Notiz fordert den Leser auf, jeden Flecken der Red Cloud Mesa und der umliegenden Ebenen genauestens zu studieren. Durch das Vorzeigen des Briefes bei Lanka unternimmt der Schüler seine ersten offiziellen Schritte, um das Waffenhandwerk zu erlernen, Bestien zu verstehen und seine Pflicht zu erfüllen, die Stämme zu verteidigen und zu ernähren."}},faq={{q="Was ist der Zweck der Geätzten Notiz?",a="Sie dient als einleitende Vorladung für angehende Taurenjäger. Das Lesen der Notiz weist den Träger an, sich bei Lanka Farshot in Camp Narache einzufinden, um die formelle Ausbildung in Treffsicherheit und Wildtierkunde zu beginnen.",al={"was bewirkt die notiz","geätzte notiz verwendung","warum geätzte notiz erhalten"}},{q="Wer hat diese Notiz geschrieben?",a="Die Botschaft wurde von Lanka Farshot verfasst, der Jägerlehrerin in Camp Narache. Sie entsendet Boten über die Hochebene, um junge Jäger bedeutender Blutlinien aufzuspüren, die bereit sind zu lernen.",al={"wer schickte geätzte notiz","wer hat sie geschrieben","geätzte notiz autor"}},{q="Warum ist die Jagd für die Tauren so wichtig?",a="Die Jagd ist ein Grundpfeiler des Überlebens, der Spiritualität und der Stammestradition der Tauren. Geschickte Jäger versorgen ihr Volk mit Nahrung und Materialien, während sie im direkten Einklang mit dem Land leben und die Geister der von ihnen erlegten Bestien ehren.",al={"tauren jäger lore","warum tauren jagen","jagd in der taurenkultur"}},{q="Wohin sollte diese Notiz gebracht werden?",a="Bringt die Notiz direkt zu Lanka Farshot, die nahe dem Pavillon und den Trainingsgründen in Camp Narache auf der Red Cloud Mesa steht.",al={"wohin mit der notiz","bei wem abgeben","geätzte notiz abgabe"}}},fp="11,274,18.438.0,26.430.0,39.217.0,20.196.0,42.235.0,34.133.0"}
P.entries["item:etched-parchment"] = {n="Geätztes Pergament",s="Das Geätzte Pergament ist eine schriftliche Vorladung, die an unerfahrene Jäger übergeben wird, die im Tal der Prüfungen in Durotar trainieren. Es wird von Gornek überreicht und weist angehende Pirschgänger der Wildnis an, bei der Trolllehrerin Jen'shan Unterweisung zu suchen.",h="Das Geätzte Pergament ist eine schriftliche Vorladung, die an unerfahrene Jäger übergeben wird, die im Tal...",kw={"durotar","geätztes pergament","gornek","jäger","jen'shan","ausbilder","das tal der prüfungen"},ang={["class:Hunter"]="Dieses Schreiben stellt die allererste Reifeprüfung eines Jägers in Durotar dar und bringt ihn formell mit Jen'shan in Kontakt, um mit dem Erlernen von Spurenlesen, Fernkampfwaffen und Überleben zu beginnen.",["faction:Horde"]="Jeder junge Krieger der Horde muss sein Handwerk verfeinern; für Jäger markiert dieses Pergament ihren ersten Schritt, um ihren Clan zu ernähren und die Grenzen von Durotar zu bewachen."},sec={{t="Eine Vorladung zur Jagd",b="Junge Orcs und Darkspear, die ihren Platz in der Horde suchen, beginnen ihre Riten im trockenen Becken des Tals der Prüfungen. Während sie sich gegen das hiesige Ungeziefer beweisen, fungiert Gornek als wachsamer Aufseher, der die Rekruten zu ihrer Berufung führt. Denjenigen, die dazu bestimmt sind, Bogen, Schusswaffe und Reißzahn zu führen, übergibt Gornek dieses geätzte Pergament. Es trägt eine direkte Botschaft von Jen'shan, einer geschickten Jägerausbilderin, die nach unverbrauchten Augen und ruhigen Händen sucht."},{t="Die erste Lektion",b="Das Pergament zu Jen'shan zu bringen, markiert den wahren Beginn der Ausbildung eines Jägers in Durotar. Jen'shan betont, dass das Beschreiten des Pfades der Wildnis keine leichte Aufgabe ist und ebenso viel Hingabe erfordert, um die Bestien der Wüste zu meistern, wie ein Arkanist der Magie widmet oder ein Schamane den Geistern schenkt. Das Lesen des Pergaments und das Befolgen ihres Rufs führt Novizen an die richtige Treffsicherheit und das Überleben in der Wildnis heran."}},faq={{q="Wofür ist das Geätzte Pergament gedacht?",a="Es ist eine einleitende Vorladung, die neu angekommene Jäger im Tal der Prüfungen zu ihrer Klassenlehrerin Jen'shan führen soll.",al={"geätztes pergament verwendung","was bewirkt geätztes pergament"}},{q="Wer gibt dieses Pergament aus?",a="Gornek, der in der Nähe des Höhlenbaus im Tal der Prüfungen stationierte Aufseher, überreicht die Notiz jungen Jägern bei ihrer Ankunft.",al={"wer vergibt geätztes pergament","questgeber geätztes pergament"}},{q="Wer hat das Geätzte Pergament verfasst?",a="Die Botschaft stammt von Jen'shan, einer im Tal der Prüfungen stationierten Jägerausbilderin der Trolle, die begierig darauf ist, neue Schützen auszubilden.",al={"wer sandte geätztes pergament","urheber des pergaments"}},{q="Wo ist Jen'shan zu finden?",a="Jen'shan befindet sich im Tal der Prüfungen in Durotar und wartet in der Nähe der Übungsplätze darauf, unerfahrene Jäger der Orcs und Trolle zu unterweisen.",al={"wo ist jenshan","jenshan finden"}}},fp="16,229,21.455.0,16.408.0,33.127.0,29.123.0,31.129.0,28.131.0"}
P.entries["item:etched-rune"] = {n="Geätzte Rune",s="Die Geätzte Rune ist eine behauene Steintafel, die angehenden Zwergenjägern im Coldridgetal überreicht wird. Sie dient als Einladung des Jägerlehrers Thorgas Grimson und weist Neulinge an, ihn in Anvilmar aufzusuchen, um ihre formelle Wildnisausbildung zu beginnen.",h="Die Geätzte Rune ist eine behauene Steintafel, die angehenden Zwergenjägern im Coldridgetal überreicht wird.",kw={"anvilmar","das coldridgetal","dun morogh","zwergenjäger","geätzte rune","jägerausbildung","thorgas grimson"},ang={["class:Hunter"]="Die Rune markiert Eure erste formelle Vorladung in das uralte Handwerk der Zwergenjagd, bei dem das Fährtenlesen, der Respekt vor Euren tierischen Gefährten und das Überleben in der rauen Wildnis allein durch Scharfsinn im Vordergrund stehen.",["race:Dwarf"]="Behauene Steine und Runen sind traditionelle Methoden der Zwerge, um Handwerkskunst und dringende Anweisungen weiterzugeben, selbst für abgehärtete Wanderer im Schnee des Coldridgetals."},sec={{t="Ruf der Wildnis",b="Diese kleine, mit besonderen Zwergenrunen behauene Steintafel wird an Neulinge weitergegeben, die in den Schneewehen des Coldridgetals Potenzial beweisen. Die von dem Bergsteiger und Jägerlehrer Thorgas Grimson gesandte Rune ermutigt angehende Fährtenleser, ihre Aufgaben im Freien zu unterbrechen und sich in Anvilmar zu melden. Das Lesen des Steins markiert für einen Jäger den ersten Schritt weg vom bloßen Überleben und hin zum Verständnis der tieferen Kunst der Wildnis – zu lernen, die Bestien von Dun Morogh zu respektieren, Gebirgsraubtiere aufzuspüren, Fernkampfwaffen zu pflegen und den unbarmherzigen Elementen zu trotzen."}},faq={{q="Was ist der Zweck der Geätzten Rune?",a="Die Rune fungiert als lehrreiche Vorladung für Zwergenjäger. Das Lesen der Schriftzeichen auf der Tafel weist den Träger an, Thorgas Grimson in der Wärme von Anvilmar aufzusuchen, um eine formelle Unterweisung in der Kunst des Jägers zu erhalten.",al={"was macht geätzte rune","geätzte rune nutzen","warum habe ich geätzte rune"}},{q="Wer hat die Geätzte Rune geschrieben oder gesendet?",a="Die Rune wurde von Thorgas Grimson gesandt, dem örtlichen Jägerlehrer, der in Anvilmar stationiert ist. Er übergibt diese behauenen Steine an unerfahrene Waldläufer im Coldridgetal, die ein Talent dafür zeigen, in der gefrorenen Wildnis zu überleben.",al={"wer schickte geätzte rune","wer gab mir diese rune","urheber geätzte rune"}},{q="Wohin bringe ich die Geätzte Rune, nachdem ich sie gelesen habe?",a="Bringt die Rune in die Haupthalle von Anvilmar im Coldridgetal. Ihr werdet Thorgas Grimson nahe der Schmiede und den Ausbildungshallen finden, bereit, Euch das Fährtenlesen, die Waffenpflege und die Traditionen der Zwergenjagd beizubringen.",al={"wohin bringe ich geätzte rune","geätzte rune abgeben","thorgas grimson aufenthaltsort"}}},fp="11,262,16.564.0,39.231.0,34.225.0,52.230.0"}
P.entries["item:etched-sigil"] = {n="Geätztes Siegelzeichen",s="Ein beschriftetes Zeichen, das aufstrebenden Jägern der Nachtelfen überbracht wird, die im Shadowglen erwachen. Von einem Waldläufer getragen, enthält es eine Vorladung von der Jägerlehrerin Ayanna Everstride hoch oben auf dem mächtigen Ast von Aldrassil.",h="Ein beschriftetes Zeichen, das aufstrebenden Jägern der Nachtelfen überbracht wird, die im Shadowglen...",kw={"aldrassil","ayanna everstride","geätztes siegelzeichen","jäger","shadowglen","teldrassil"},ang={["class:Hunter"]="Dieser beschriftete Talisman markiert den Beginn der Reise eines Kaldoreijägers, unter der Anleitung von Ayanna Everstride die Kunst des Bogens und die Bräuche der Wildtiere zu meistern.",["race:NightElf"]="Unter dem abgeschiedenen Blätterdach des Shadowglen überreicht, ehrt das Siegelzeichen die uralten Traditionen der Waldläufer der Nachtelfen, die sich dem Schutz von Teldrassil widmen."},sec={{t="Ruf der Wildnis",b="Mit den Zeichen der Jagd versehen, wird das Geätzte Siegelzeichen neu erwachten Jägern der Nachtelfen überreicht, sobald sie das Shadowglen betreten. Das Zeichen dient als offizielle Benachrichtigung und Willkommensgruß von Ayanna Everstride, der hiesigen Jägerlehrerin, die hoch oben in den ausgehöhlten Ästen von Aldrassil weilt. Es weist den Neuling an, sie aufzusuchen, und leitet eine lebenslange Ausbildung im Bogenschießen, Fährtenlesen in der Wildnis sowie dem uralten Band der Nachtelfen zwischen Pirscher und Wildtier ein."}},faq={{q="Was ist der Zweck des Geätzten Siegelzeichens?",a="Das Siegelzeichen ist eine direkte Vorladung, die einen angehenden Nachtelfenjäger anweist, seine Ausbilderin Ayanna Everstride hoch oben auf Aldrassil im Shadowglen aufzusuchen, um die formelle Unterweisung im Überleben, Fährtenlesen und Bogenschießen zu beginnen.",al={"was macht das geätzte siegelzeichen","geätztes siegelzeichen verwendung","warum habe ich dieses siegelzeichen"}},{q="Wer schickt das Geätzte Siegelzeichen?",a="Es wird von Ayanna Everstride gefertigt und versandt, der Jägerlehrerin, die über die frischgebackenen Waldpirscher im Shadowglen wacht.",al={"wer hat das geätzte siegelzeichen geschickt","woher stammt das geätzte siegelzeichen"}},{q="Wohin sollte das Siegelzeichen gebracht werden?",a="Es muss in die oberen Wipfel des großen Baumes Aldrassil im Herzen des Shadowglen gebracht werden, wo Ayanna Everstride wartet.",al={"wohin bringe ich das geätzte siegelzeichen","wem gebe ich das geätzte siegelzeichen"}},{q="Warum erhalten Nachtelfenjäger ein Siegelzeichen anstelle eines Papierbriefs?",a="Die Traditionen der Kaldorei bevorzugen natürliche Schnitzereien und beständige, mit heiligen Symbolen von Elune und der Wildnis versehene Zeichen gegenüber gewöhnlichem Pergament, was das Wesen der Verbundenheit des Jägers mit dem Wald widerspiegelt.",al={"warum ein siegelzeichen statt brief","woraus besteht das siegelzeichen"}}},fp="12,209,20.452.0,40.206.0,27.129.0,32.137.0,68.195.0"}
P.entries["item:explosive-stick-of-gann"] = {n="Dynamitstange von Gann",s="Die Dynamitstange von Gann ist eine maßgeschneiderte Sprengladung, die von Gann Stonespire mithilfe gestohlener Zwergenbaupläne zusammengesetzt wurde. Sie wurde speziell dafür entwickelt, die in Bael Modan im südlichen Brachland stationierte Zwergenflugmaschine zu sabotieren.",h="Die Dynamitstange von Gann ist eine maßgeschneiderte Sprengladung, die von Gann Stonespire mithilfe...",kw={"bael modan","dynamitstange von gann","flugmaschine","gann stonespire","prospektor khazgorm","stonespire stamm","brachland"},ang={["profession:Engineering"]="Die Waffe verdeutlicht die Ironie, dass einfache, gestohlene Pläne gegen hochentwickelte Zwergenmaschinerie eingesetzt werden.",["race:Tauren"]="Der Einsatz dieser Waffe rächt den vertriebenen Stamm der Stonespire und schlägt gegen die Prospektoren zurück, die den heiligen Boden von Kalimdor umgegraben haben."},sec={{t="Eine Waffe der Vergeltung",b="Als der Zwergenprospektor Khazgorm die Ausgrabung von Ironforge ins südliche Kalimdor führte, vertrieben die Zwerge die Tauren der Stonespire aus ihrem angestammten Dorf und machten ihre heiligen Stätten dem Erdboden gleich, um die Festungsgrabung Bael Modan zu errichten. Angetrieben von Rachedurst und dem Wunsch, sein vertriebenes und gefallenes Volk zu ehren, beschaffte sich Gann Stonespire Khazgorms Baupläne zurück, um die Ingenieurskunst der Zwerge gegen die Eindringlinge selbst einzusetzen. Durch das Studium der sichergestellten Pläne fertigte Gann diese spezialisierte Ladung an, die genug Erschütterungskraft besitzt, um schwere Maschinerie zu zerstören."},{t="Gegen die Himmelsmaschine gerichtet",b="Die Dynamitstange wurde für ein einziges Ziel angefertigt: die Flugmaschine der Zwerge, die auf einem Beobachtungsturm mit Blick auf die Ausgrabungsstätte thront. Für Gann ist dieser mechanische Flieger nicht bloß ein Lufttransportmittel oder eine Kriegswaffe; er steht als arrogantes Symbol für die Vorherrschaft der Allianz über heiligem Taurenboden. Die Zündung der Sprengladung zerstört einen Eckpfeiler der Infrastruktur des Zwergenaußenpostens und versetzt ihnen einen schweren Schlag zugunsten des verlorenen Stonespire-Stammes."}},faq={{q="Was ist die Dynamitstange von Gann?",a="Es handelt sich um eine Sprengladung, die von dem Tauren Gann Stonespire hergestellt wurde. Mithilfe erbeuteter Zwergenbaupläne baute Gann sie eigens dafür, um die Maschinerie der Prospektoren zu sabotieren, die seine angestammten Ländereien besetzen.",al={"dynamitstange von gann","ganns dynamitstange","gann bombe"}},{q="Wer hat diesen Sprengstoff hergestellt?",a="Sie wurde von Gann Stonespire zusammengesetzt, einem Tauren, der auf Rache sinnt, nachdem die Zwerge aus Ironforge in Bael Modan das Dorf seines Stammes zerstört und ihre Heimat im südlichen Brachland geschändet hatten.",al={"wer hat das hergestellt","wer ist gann","gann stonespire"}},{q="Was soll der Sprengstoff in die Luft jagen?",a="Sie wurde entworfen, um die Zwergenflugmaschine zu zerstören, die sich auf einem Aussichtsturm über der Ausgrabungsgrube von Bael Modan befindet. Die Zerstörung des Fluggeräts schwächt die Aufklärung der Ausgrabungsstätte und dient als symbolische Rache für den Stamm der Stonespire.",al={"was sprenge ich","flugmaschine ziel","wo benutze ich es"}},{q="Wie hat ein Taure gelernt, Zwergensprengstoff herzustellen?",a="Gann baute die Stange anhand von Ingenieurbauplänen, die er von Prospektor Khazgorm, dem Anführer der Zwergengrabung in Bael Modan, erbeutet hatte, und wendete so die Technologie der Invasoren gegen sie selbst an.",al={"wie hat gann es gebaut","sprengstoff bauplaene","khazgorm plaene"}}},fp="23,238,23.527.0,25.454.1,36.203.0,24.190.0,42.238.0,50.194.0"}
P.entries["item:faded-shadowhide-pendant"] = {n="Verblasster Schattenfellanhänger",s="Ein angelaufener Talisman, der einst von den Schattenfellgnollen des Rotkammgebirges getragen wurde und verzaubert ist, um als Kanal für finstere Befehle zu dienen. Zum Erstaunen jedes Trägers birgt der Anhänger zudem eine verzögerte magische Botschaft, gewirkt vom Zauberer Theocritus.",h="Ein angelaufener Talisman, der einst von den Schattenfellgnollen des Rotkammgebirges getragen wurde und...",kw={"elwynn","gnolle","morganth","anhänger","rotkammgebirge","schattenfell","theocritus","tower azora"},ang={["class:Mage"]="Der Anhänger verdeutlicht die Feinheiten magischen Abfangens und zeigt, dass selbst primitive oder dunkle Verzauberungen von einem disziplinierten Zauberer der Kirin Tor entschlüsselt und gekapert werden können.",["faction:Alliance"]="Die Bergung dieses Amuletts hilft Tower Azora dabei, die Schattenfellgnolle zu schwächen, welche die Stabilität sowohl des Walds von Elwynn als auch von Seenhain bedrohen."},sec={{t="Ein unterbrochenes Netzwerk",b="Die Schattenfellgnolle, die das Rotkammgebirge durchstreifen, unterstehen einem unheilvollen Meister namens Morganth und koordinieren ihre Bewegungen über verzauberte Anhänger. Während er diese Talismane von seiner Zuflucht im Tower Azora aus untersuchte, entwickelte der Erzmagier Theocritus einen experimentellen Zauber, um deren mystische Frequenz zu durchdringen. Obwohl seine magische Übertragung Wochen brauchte, um sich zu manifestieren, bewies dieser verblasste Anhänger, dass die Kommunikationslinie der Gnolle gekapert werden kann, was einen Weg eröffnet, die Reichweite ihres finsteren Meisters zu stören."},{t="Der Ehrgeiz des Magiers",b="Die persönliche Untersuchung des verblassten Anhängers bietet Theocritus weit mehr als nur abgefangene Gespräche. Indem er analysiert, wie die Verzauberung seinem Eindringen standgehalten hat, hofft der Magier, seine Zauberkunst zu einer Waffe weiterzuentwickeln, die lähmende Angriffe direkt durch alle passenden Amulette projizieren kann, die im Rotkammgebirge getragen werden. Das Artefakt zurück zum Tower Azora im Wald von Elwynn zu bringen, ist der entscheidende erste Schritt, um Morganths Einfluss auf die Gnolle der Region zu zerschlagen."}},faq={{q="Was ist der Verblasste Schattenfellanhänger?",a="Es ist ein verzaubertes Amulett, das ursprünglich von Schattenfellgnollen im Rotkammgebirge getragen wurde, um Befehle von ihrem Meister Morganth zu empfangen. Dieser besondere Anhänger wurde durch einen abgefangenen Übertragungszauber von Erzmagier Theocritus verändert.",al={"schattenfellanhänger","was ist dieser anhänger","theocritus anhänger"}},{q="Warum spricht eine Stimme aus dem Anhänger?",a="Erzmagier Theocritus verbrachte Monate damit zu erforschen, wie man die magische Kommunikationsverbindung der Anhänger durchbrechen kann. Die Stimme, die Ihr hört, ist das Echo eines Zaubers, den er Wochen zuvor projiziert hat, und beweist, dass seine Beschwörung erfolgreich in das Netzwerk der Gnolle eingedrungen ist.",al={"wer spricht da","körperlose stimme","theocritus stimme"}},{q="Wer ist Theocritus?",a="Theocritus ist der Erzmagier, der im Tower Azora im östlichen Wald von Elwynn residiert. Er widmet seine magischen Studien der Überwachung finsterer Bedrohungen jenseits der Grenze im Rotkammgebirge, insbesondere des abtrünnigen Hexers Morganth.",al={"theocritus lore","erzmagier theocritus","tower azora magier"}},{q="Wer ist Morganth?",a="Morganth ist ein abtrünniger, unheilvoller Magiewirker, der vom Rotkammgebirge aus operiert. Er übt dunklen Einfluss auf das hiesige Schattenfellgnollrudel aus und erteilt ihnen Befehle über diese verzauberten Anhänger.",al={"morganth identität","wer ist morganth","gnollmeister"}},{q="Was plant Theocritus mit dem Anhänger zu tun?",a="Theocritus beabsichtigt, die Verzauberung des Anhängers in seinem Labor zu studieren. Sein oberstes Ziel ist es, einen Weg zu finden, lähmende magische Angriffe über das Netzwerk zu projizieren und jeden Gnoll, der ein solches Exemplar trägt, sofort außer Gefecht zu setzen.",al={"warum will theocritus ihn","anhänger zweck","anhänger als waffe"}}},fp="24,240,16.500.0,19.447.1,37.240.0,40.241.0,18.210.0,16.189.0,49.212.0"}
P.entries["item:fallen-moonstone"] = {n="Gefallener Mondstein",s="Ein Gefallener Mondstein ist ein leuchtender, magisch aufgeladener Stein, der in den ruhigen Gewässern des Fallenskysees in Ashenvale gesammelt wird. Erfüllt von heiliger Mondenergie besitzen diese Steine wirkungsvolle wiederherstellende Eigenschaften, die imstande sind, Vitalität zu erneuern und schwere Schwächezustände zu heilen.",h="Ein Gefallener Mondstein ist ein leuchtender, magisch aufgeladener Stein, der in den ruhigen Gewässern des...",kw={"ashenvale","astranaar","gefallener mondstein","fallenskysee","mondstein","pelturas whitemoon","relara","shadethicket oracle"},ang={["class:Priest"]="Anhänger der Schwesternschaft von Elune betrachten das mondgleiche Leuchten dieser Steine als eine greifbare Manifestation heilender Gnade.",["race:NightElf"]="Für die Kaldorei sind Relikte, die mit dem Glanz von Elune verbunden sind, heilige Werkzeuge der Bewahrung, die göttliche Heilung spenden, wenn sterbliche Medizin versagt."},sec={{t="Gaben des Nachthimmels",b="Gefallene Mondsteine wurden einst in großer Zahl an den Ufern und in den seichten Gewässern des Fallenskysees südöstlich von Astranaar gesammelt. Von den Nachtelfen für ihre regenerative Magie und ihren Mondsegen hoch geschätzt, wurden sie oft gesucht, um bei der Genesung zu helfen, wenn gewöhnliche Heilmittel nicht ausreichten. Das Bergen dieser Steine wurde jedoch gefährlich, als verdorbene Woodkin der Shadethicket den See überrannten. Ihr Anführer, ein Shadethicket Oracle, hortete jeden Stein, den er finden konnte, auf einer kleinen zentralen Insel und schnitt die örtlichen Kaldorei so von einer lebenswichtigen Quelle der Heilung ab."},{t="Die Rettung eines Vaters",b="Als die junge Relara Whitemoon in Astranaar schwer erkrankte, senkten gewöhnliche Behandlungen zwar ihr Fieber, ließen sie jedoch entkräftet und mit nur noch wenigen Atemzügen am Leben hängend zurück. Ihr Vater, Pelturas Whitemoon, erkannte, dass nur die konzentrierte regenerative Kraft eines Mondsteins ihre schwindende Vitalität erneuern konnte. Die Bergung eines Steins aus dem Hort des Shadethicket Oracle lieferte den entscheidenden Funken, um das Leben des Kindes zu retten."}},faq={{q="Was ist ein Gefallener Mondstein?",a="Es ist ein seltener, leuchtender Stein, der am Fallenskysee in Ashenvale gefunden wird. Er ist von Mondmagie durchdrungen und besitzt wirkungsvolle wiederherstellende Energie, die Nachtelfen nutzen, um die Kräfte von schwer Geschwächten wieder aufzufüllen.",al={"was ist ein gefallener mondstein","gefallener mondstein lore","mondstein ashenvale"}},{q="Wo werden Gefallene Mondsteine gefunden?",a="Sie stammen aus dem Fallenskysee, der südöstlich von Astranaar in Ashenvale liegt. Während sie früher frei auf dem Grund des Sees lagen, wurden sie von den feindseligen Woodkin der Shadethicket gesammelt und auf einer Insel in der Mitte des Sees gehortet.",al={"gefallenen mondstein finden","gefallener mondstein ort"}},{q="Wer besitzt die Mondsteine am Fallenskysee?",a="Das Shadethicket Oracle, der Anführer der verdorbenen Woodkin am Fallenskysee, hortete die gefallenen Mondsteine auf einer Insel inmitten des Sees.",al={"wer hat den gefallenen mondstein","shadethicket oracle mondstein"}},{q="Warum benötigt Pelturas Whitemoon einen Gefallenen Mondstein?",a="Seine junge Tochter Relara überlebte ein kräftezehrendes Fieber, blieb jedoch kritisch geschwächt zurück und verfiel zusehends. Pelturas erkannte, dass natürliche Ruhe nicht genügen würde, um sie am Leben zu halten, und dass die dem Mondstein innewohnende Magie nötig war, um ihre Lebenskraft wiederherzustellen.",al={"pelturas whitemoon tochter","warum mondstein benötigt","relara heilung"}}},fp="16,264,22.554.0,20.413.1,27.206.0,34.218.0,48.159.0,52.243.0"}
P.entries["item:fandral-s-message"] = {n="Fandrals Nachricht",s="Fandrals Nachricht ist ein Schreiben, das von Erzdruide Fandral Staghelm in Darnassus verfasst wurde. Es wird einem Abenteurer anvertraut, um es über das Meer zu Onu, dem Urahnen der Lehren an der Dunkelküste, zu bringen.",h="Fandrals Nachricht ist ein Schreiben, das von Erzdruide Fandral Staghelm in Darnassus verfasst wurde.",kw={"urahn der lehren","auberdine","dunkelküste","darnassus","fandral staghelm","fandrals nachricht","der hain der uralten","onu","die lichtung des orakels"},ang={["class:Druid"]="Das Überbringen von Schreiben zwischen der Enklave des Cenarius in Darnassus und den Urahnen der Lehren an der Dunkelküste verdeutlicht die gegensätzlichen Philosophien zwischen Fandral Staghelms aggressivem Tatendrang und dem geduldigen Traditionalismus älterer druidischer Beschützer.",["race:NightElf"]="Das Überbringen dieser Depesche markiert einen der frühesten Schritte herab von der Krone Teldrassils und zurück in Richtung der uralten Wälder des Festlands von Kalimdor."},sec={{t="Eine Depesche des Erzdruiden",b="Diese versiegelte Depesche wurde von Erzdruide Fandral Staghelm in der Enklave des Cenarius verfasst und dient als direkte Korrespondenz zwischen dem amtierenden Anführer der nachtelfischen Druiden und Onu, dem ehrwürdigen Urahnen der Lehren, der im Hain der Uralten weilt. Nachdem er Berichte über den Zustand der Lichtung des Orakels auf Teldrassil erhalten hat, verliert Staghelm keine Zeit und verpflichtet Boten, um Nachricht südlich von Auberdine zu senden. Die Übergabe verlangt von den Reisenden, über das Meer zur Dunkelküste zu fahren und so das Herz des neuen Weltenbaums mit dem älteren, schattigen Festland zu verbinden."},{t="Gegensätzliche Tempi",b="Während der genaue Inhalt der Nachricht zwischen dem Erzdruiden und Onu verbleibt, verdeutlicht die Überbringung selbst eine subtile Kluft im Temperament innerhalb des Zirkels des Cenarius. Bei der Annahme des Dokuments stellt Onu fest, dass Fandral stets mit einer uncharakteristischen Ungeduld agiert und Angelegenheiten übereilt, die sich nach Ansicht der Uralten auf natürliche Weise entfalten sollten. Für die langlebigen, bedächtigen Treants der Dunkelküste steht Fandrals rasche Hast in starkem Kontrast zur geduldigen Weisheit, die einst von Erzdruide Malfurion Stormrage verkörpert wurde."}},faq={{q="Was ist Fandrals Nachricht?",a="Es handelt sich um eine offizielle schriftliche Depesche von Erzdruide Fandral Staghelm für Onu, den Urahnen der Lehren, der im Hain der Uralten an der Dunkelküste weilt.",al={"fandrals nachricht gegenstand","fandrals nachricht","brief des erzdruiden"}},{q="Wer sendet diese Nachricht und warum?",a="Erzdruide Fandral Staghelm verfasst sie aus Darnassus. Nachdem er Neuigkeiten über die Lichtung des Orakels auf Teldrassil erhalten hat, sendet er Kunde an Onu, der auf Nachrichten aus der Krone des Weltenbaums gewartet hat.",al={"wer hat das geschrieben","warum fandral nachricht sendet"}},{q="Wohin muss diese Nachricht gebracht werden?",a="Die Nachricht muss zu Onu in den Hain der Uralten gebracht werden, der sich an der Dunkelküste direkt südlich der Küstensiedlung Auberdine befindet.",al={"wer die nachricht erhält","wohin die nachricht geliefert wird","ziel von fandrals nachricht"}},{q="Was hält Onu von dem Brief?",a="Nach Erhalt bemerkt Onu, dass Fandral immer in Eile zu sein scheint. Der Uralte merkt an, dass die Natur sich in ihrem eigenen Tempo bewegt, und sinniert darüber nach, dass Shan'do Malfurion Stormrage diese Wahrheit weitaus besser verstanden hat als Fandral.",al={"onus reaktion","was onu sagt"}}},fp="17,182,29.563.0,18.503.1,26.157.0,31.207.0,35.149.0,34.232.0"}
P.entries["item:fang-of-vagash"] = {n="Fangzahn von Vagash",s="Der Fangzahn von Vagash ist ein gewaltiger Raubtierzahn, der der berüchtigten Bestie Vagash in den verschneiten Bergen von Dun Morogh entrissen wurde. Er dient den örtlichen Züchtern als handfester Beweis dafür, dass das marodierende Monster, das ihre geschätzten Widder bedrohte, endlich erlegt worden ist.",h="Der Fangzahn von Vagash ist ein gewaltiger Raubtierzahn, der der berüchtigten Bestie Vagash in den...",kw={"amberstill-ranch","dun morogh","fangzahn von vagash","ironforge","die herde beschützen","widder","vagash"},ang={["class:Hunter"]="Ein Spitzenraubtier wie Vagash in den eisigen Bergen von Dun Morogh aufzuspüren, ist eine frühe Prüfung für Fährtenlesekunst, Überleben in der Wildnis und die Jagd auf Bestien.",["race:Dwarf"]="Die Amberstill-Ranch stellt die robusten Gebirgswidder bereit, die sowohl für die Zwergen-Gebirgsjäger als auch für Reisende unentbehrlich sind. Die Beschaffung von Vagashs Fangzahn trägt direkt zum Schutz von Ironforges geschätztester Reittierrasse bei."},sec={{t="Trophäe der Jagd",b="Dun Moroghs schroffe Gipfel beherbergen bittere Kälte und grausame Raubtiere, doch keines hat die örtlichen Höfe so sehr heimgesucht wie Vagash. Hoch oben in den Bergen über der Amberstill-Ranch lauernd, schleicht diese wilde Bestie im Schutz der Dunkelheit häufig talwärts, um wertvolle Widder zu reißen. Da Ironforges Streitkräfte an fernen Fronten der Allianz gebunden sind, können die hiesigen Hirten nicht auf den Schutz der Stadtwache hoffen. Die Vernichtung der Bestie und das Herausschneiden eines ihrer bösartigen Zähne liefert den unumstößlichen Beweis, dass die Weidegründe wieder sicher sind."}},faq={{q="Wofür wird der Fangzahn von Vagash verwendet?",a="Der Fangzahn wird zu den Züchtern auf der Amberstill-Ranch in Dun Morogh gebracht, als handfester Beweis dafür, dass Vagash beseitigt wurde. Im Gegenzug belohnen die dankbaren Rancher den Jäger, der ihre Existenzgrundlage gesichert hat.",al={"fangzahn von vagash verwendung","was tun mit fangzahn von vagash","fangzahn von vagash abgeben"}},{q="Wer ist Vagash?",a="Vagash ist eine ungewöhnlich tödliche Bestie, die in den verschneiten Hügeln direkt über den Widderweiden in Dun Morogh haust. Er hat sich unter den ortsansässigen Zwergen einen furchterregenden Ruf erworben, da er des Nachts die Herden überfällt.",al={"was ist vagash","wo ist vagash","vagash lore"}},{q="Warum hat die Wache von Ironforge Vagash nicht getötet?",a="König Magni Bronzebeards Truppen und die Stadtwachen sind an verschiedenen Kriegsfronten zur Unterstützung der Allianz gebunden. Da kaum Soldaten für Patrouillen in den ländlichen Gebieten erübrigt werden können, müssen sich die Rancher auf durchreisende Abenteurer verlassen, um mit gefährlichen Raubtieren fertigzuwerden.",al={"warum wachen nicht helfen","wo ist armee von ironforge","gebirgsjäger vagash"}}},fp="14,246,18.549.0,36.207.0,14.195.0,45.249.0"}
P.entries["item:fangore-s-paw"] = {n="Fangors Tatze",s="Fangors Tatze ist die abgetrennte Hand von Lieutenant Fangore, einem kommandierenden Offizier der Shadowhide-Gnolle im Rotkammgebirge. Sie dient Magistrat Solomon in Seenhain als grausiger Beweis für das Ableben des Gnoll-Häuptlings. Das düstere Kopfgeld wurde ausgesetzt, um die Bedrohung durch den Kriegsherrn für die belagerte Siedlung zu zerschlagen.",h="Fangors Tatze ist die abgetrennte Hand von Lieutenant Fangore, einem kommandierenden Offizier der...",kw={"fangore","gnoll","seenhain","morganth","tatze","rotkammgebirge","shadowhide","solomon"},ang={["faction:Alliance"]="Das Ausschalten von Fangore und die Rückgabe seiner Tatze verschafft der bedrängten Stadt Seenhain entscheidende Erleichterung, da sie kaum militärische Unterstützung von Stormwind erhält."},sec={{t="Trophäe eines gefallenen Häuptlings",b="Lieutenant Fangore agiert als wichtiger Feldkommandant für die Shadowhide-Gnolle, die im Rotkammgebirge vordringen. Im direkten Dienst des abtrünnigen Magiers Morganth leitet Fangore gewaltsame Angriffe auf Handelsstraßen, abgelegene Höfe und die Verteidigungsanlagen rund um den Immerruhsee. Da Gnoll-Räuber keine traditionellen Uniformen, offiziellen Siegel oder Banner hinterlassen, um ihre Verluste zu bestätigen, sind die Behörden der Siedlung auf grausige physische Beweise angewiesen. Magistrat Solomon verlangte ausdrücklich Fangors Tatze als unmissverständlichen Beweis für seine Hinrichtung, damit die Stadt Seenhain inmitten wachsender Gefahren etwas aufatmen kann."}},faq={{q="Wem gehört diese Tatze?",a="Die Tatze gehört Lieutenant Fangore, einem berüchtigten Anführer des Shadowhide-Gnollclans, der das Rotkammgebirge heimsucht. Er organisiert Überfälle und führt Truppen unter der Leitung des dunklen Zauberers Morganth an.",al={"wer ist fangore","wem gehört diese tatze","fangore identität"}},{q="Warum will Magistrat Solomon die Tatze?",a="Magistrat Solomon hat einen offiziellen Steckbrief erlassen, der Fangore als verhassten Feind von Stormwind verurteilt. Er verlangt die abgetrennte Tatze als unbestreitbaren physischen Beweis dafür, dass der Lieutenant der Shadowhide getötet wurde.",al={"warum fangors tatze sammeln","solomon kopfgeld beweis","magistrat beweis"}},{q="Für wen arbeitet Lieutenant Fangore?",a="Fangore dient Morganth, einem abtrünnigen Ausüber dunkler Magie, der Seenhain von seinem Turm in den östlichen Bergen aus bedroht und die Aktivitäten der Gnolle gegen das Königreich lenkt.",al={"fangore meister","wer führt fangore","morganth verbindung"}},{q="Wo ist Lieutenant Fangore zu finden?",a="Lieutenant Fangore operiert in der Wildnis des Rotkammgebirges inmitten der feindlichen Lager der Shadowhide-Gnolle.",al={"fangore aufenthaltsort","wo ist fangore","fangore finden"}}},fp="13,321,28.647.0,28.209.0,41.207.0,38.171.0,34.119.0"}
P.entries["item:farren-s-report"] = {n="Farrens Bericht",s="Farrens Bericht ist eine offizielle Meldung, die von Lieutenant Farren Orinelle in Southshore verfasst wurde und seine Untersuchungen der einheimischen Naga darlegt. Farren nutzt dieses Dokument, um sich an seinen ehemaligen Mentor, Major Samuelson in Stormwind Keep, zu wenden, in der Hoffnung, eine Versetzung zurück in die Hauptstadt zu erwirken.",h="Farrens Bericht ist eine offizielle Meldung, die von Lieutenant Farren Orinelle in Southshore verfasst wurde...",kw={"farren orinelle","farrens bericht","major samuelson","naga","versetzung","redpath","southshore","stormwind keep"},ang={["faction:Alliance"]="Das Dokument verdeutlicht die bürokratischen Manöver innerhalb des Militärs der Allianz, bei denen entlegene Posten in Hillsbrad mit Offizieren kollidieren, die auf sicherere Dienste in Stormwind spekulieren.",["race:Human"]="Für Menschen der Allianz zeichnet das Überbringen von Farrens Bericht das beständige Band zwischen der belagerten südlichen Zuflucht von Southshore und dem königlichen Hof von Stormwind Keep nach."},sec={{t="Eine Fahrkarte weg aus Southshore",b="Stationiert an der umkämpften Küste im Vorgebirge von Hillsbrad, wurde Lieutenant Farren Orinelle der örtlichen Führung und der abgelegenen Grenze überdrüssig. Nachdem er Abenteurer damit beauftragt hatte, die Naga der Daggerspine zu jagen, um Beweise für ihre Bedrohung zu sammeln, fasste Orinelle seine Erkenntnisse in einem formellen Bericht zusammen. Anstatt ihn seinem befehlshabenden Offizier, Magistrat Henry Maleb, oder dem örtlichen Veteranen Marshal Redpath vorzulegen, beabsichtigte Farren, ihn direkt an Major Samuelson, den Hauptmann der Wache in Stormwind Keep, zu senden. Da er unter Samuelson ausgebildet worden war, hoffte Farren, dass das Dokument seine Kompetenz belegen und eine sofortige Versetzung zurück in die Annehmlichkeiten von Stormwind rechtfertigen würde."}},faq={{q="Was ist Farrens Bericht?",a="Es ist eine formelle militärische Meldung von Lieutenant Farren Orinelle, die seine Operationen gegen die Naga der Daggerspine zusammenfasst, welche die Strände von Southshore heimsuchen.",al={"farrens bericht","was ist dieser bericht","orinelles bericht"}},{q="Warum möchte Farren, dass dies nach Stormwind überbracht wird?",a="Farren möchte weg von Southshore und zurück nach Stormwind versetzt werden. Er adressiert den Bericht direkt an Major Samuelson, seinen ehemaligen Mentor und den Hauptmann der Wache von Stormwind, in der Hoffnung, eine vorteilhafte Versetzung zu erwirken.",al={"warum bericht nach stormwind senden","farrens ziel","warum samuelson"}},{q="Warum hält Farren den Bericht vor Redpath geheim?",a="Farren möchte die Aufmerksamkeit von Marshal Redpath und der örtlichen Führung meiden, die Anstoß daran nehmen könnten, dass ein Offizier eine lokale Bedrohung nur dazu nutzt, eine persönliche Versetzung zurück in die Sicherheit der Hauptstadt einzufädeln.",al={"warum vor redpath verbergen","geheimnis vor dem alten redpath"}},{q="Wie reagiert Major Samuelson auf den Erhalt?",a="Major Samuelson lobt seinen ehemaligen Schüler dafür, die Initiative gegen die Naga von Southshore ergriffen zu haben, und verspricht, den Bericht bei der Überprüfung der Wachpersonal-Zuteilungen im kommenden Monat zu berücksichtigen.",al={"samuelsons reaktion","versetzung abgeben"}}},fp="15,287,26.658.0,24.162.0,49.226.0,55.208.0,49.193.1"}
P.entries["item:fathom-core"] = {n="Fathomkern",s="Der Fathomkern ist ein spezielles Relikt, das aus einem versunkenen Fathomstein in den Tiefen der Blackfathom-Tiefe geborgen wird. Sobald er entschlüsselt ist, liefert er eine umfassende Aufzeichnung der elementaren Aktivitäten in der umliegenden Region. Der Irdene Ring sucht nach diesem Artefakt, um herauszufinden, welche finsteren Rituale der Schattenhammer-Kult unter Ashenvale vollzieht.",h="Der Fathomkern ist ein spezielles Relikt, das aus einem versunkenen Fathomstein in den Tiefen der...",kw={"blackfathom-tiefe","der irdene ring","fathomkern","fathomstein","je'neu sancrea","moonshrine ruins","schattenhammer","zoram'gar-außenposten"},ang={["class:Shaman"]="Als Artefakt, das die Strömungen der Elemente aufzeichnet, ist der Fathomkern für den Irdenen Ring von immensem Interesse und veranschaulicht, wie uralte Relikte elementare Manipulationen aufdecken können.",["faction:Horde"]="Die Bergung des Kerns hilft Je'neu Sancrea unmittelbar und sichert den Stützpunkt der Horde am Zoram'gar-Außenposten gegen die verderblichen Pläne des Schattenhammers ab."},sec={{t="Elementare Chronik",b="Eingebettet in einem uralten Fathomstein, der in den Moonshrine Ruins unter Wasser liegt, dient der Fathomkern als historische Aufzeichnung elementarer Phänomene. Er registriert und bewahrt Verschiebungen, Störungen und Wogen der Elemente über lange Zeiträume hinweg. Für die Schamanen des Irdenen Rings, die am Zoram'gar-Außenposten stationiert sind, ist die Bergung des Kerns unerlässlich, um zu verstehen, wie die Kultisten des Schattenhammers die regionalen Elemente manipulieren, um ihren eigenen Zwecken zu dienen."}},faq={{q="Was ist der Fathomkern?",a="Der Fathomkern ist eine magische Vorrichtung, die in der Lage ist, eine detaillierte Geschichte aller elementaren Aktivitäten in ihrer Umgebung aufzuzeichnen und wiederzugeben. Er befindet sich im Inneren eines uralten Fathomsteins in den Moonshrine Ruins.",al={"was macht der fathomkern","fathomkern lore","was ist das"}},{q="Wo befindet sich der Fathomkern?",a="Der Kern befindet sich tief in den höhlenartigen Hallen der Blackfathom-Tiefe an der Küste von Ashenvale. Er ruht eingeschlossen in einem Fathomstein unter den Gewässern der Moonshrine Ruins.",al={"fathomkern fundort","wo findet man den fathomkern","fathomstein fundort"}},{q="Wer will den Fathomkern und warum?",a="Je'neu Sancrea, ein Schamane des Irdenen Rings, der am Zoram'gar-Außenposten stationiert ist, sucht nach dem Kern. Durch die Analyse seiner Aufzeichnungen elementarer Verschiebungen hoffen Je'neu und sein Zirkel, die zersetzenden Aktivitäten des Schattenhammer-Kults innerhalb der Ruinen zu entschlüsseln und ihnen entgegenzuwirken.",al={"wer braucht den fathomkern","warum will je'neu den fathomkern","der irdene ring fathomkern"}},{q="Warum interessiert sich der Schattenhammer für die Blackfathom-Tiefe?",a="Die Kultisten haben sich in den versunkenen Ruinen niedergelassen, um die lokalen Elemente zu unterwerfen und zu verderben, in dem Bestreben, sie dunklen Zwecken dienstbar zu machen und die vollständige Kontrolle über den unterirdischen Tempel zu erlangen.",al={"schattenhammer blackfathom","kultisten in bfd"}}},fp="11,341,19.449.0,24.210.0,33.185.0,34.259.0,61.195.0"}
P.entries["item:feather-charm"] = {n="Federglücksbringer",s="Federglücksbringer sind grobe magische Schmuckstücke, die von Frostmane-Trollnovizen in den schneebedeckten Tälern des Coldridgetals getragen werden. Obwohl sie aus einfachen Materialien gefertigt sind, besitzen sie eine angeborene zauberhafte Resonanz, die die Aufmerksamkeit örtlicher Hexenmeisterlehrer erregt.",h="Federglücksbringer sind grobe magische Schmuckstücke, die von Frostmane-Trollnovizen in den schneebedeckten...",kw={"alamar grimm","anvilmar","das coldridgetal","dun morogh","federglücksbringer","frostmane-novize","hexenmeister"},ang={["class:Warlock"]="Für angehende Hexenmeister in Dun Morogh dient die Erbeutung von Federglücksbringern von Troll-Zauberwirkern als entscheidende Disziplinprüfung, bevor Alamar Grimm ihnen das Ritual zur Beschwörung eines Wichtels anvertraut.",["race:Gnome"]="Gnomische Hexenmeister, die von Anvilmar aus operieren, untersuchen diese rudimentären Trollfetische, um die rohe, ungeschliffene Magie zu analysieren, die von den primitiven Zauberwirkern der Frostmane kanalisiert wird."},sec={{t="Trollschmuckstücke und dunkle Studien",b="Die Frostmane-Trolle, die die verschneiten Höhlen südwestlich von Anvilmar bewohnen, sind vor allem für ihre territoriale Wildheit bekannt, doch ihre Novizen versuchen sich an primitiver Zauberkunst. Die Federglücksbringer, die diese jungen Trolle bei sich tragen, bergen eine schwache, aber unverkennbare magische Macht. In Anvilmar betrachtet der Hexenmeisterausbilder Alamar Grimm sie als ein faszinierendes Studienobjekt – überraschend für die grobe Handwerkskunst der Trolle – und nutzt sie als Bewährungsprobe für angehende Hexenmeister, die die Bindung ihres ersten Wichtels meistern wollen."}},faq={{q="Wer trägt diese Federglücksbringer?",a="Sie werden von Frostmane-Novizen getragen, die in der verschneiten Höhle südwestlich von Anvilmar im Coldridgetal lauern.",al={"woher kommen federglücksbringer","wer lässt federglücksbringer fallen","frostmane-novize glücksbringer"}},{q="Warum möchte Alamar Grimm sie haben?",a="Alamar Grimm findet die den Glücksbringern innewohnende Magie faszinierend und forschungswürdig, was er als äußerst unerwartet für Troll-Handwerkskunst bezeichnet. Er verlangt sie von aufstrebenden Hexenmeistern, um deren körperliche Stärke und magisches Potenzial auf die Probe zu stellen, bevor er ihnen beibringt, wie man einen Wichtel beschwört.",al={"warum braucht alamar glücksbringer","alamar grimm federglücksbringer","was macht grimm damit"}},{q="Sind die Frostmane-Trolle geübte Magiewirker?",a="Obwohl der Stamm der Frostmane größtenteils als primitiv und feindselig gilt, zeigen ihre Novizen rudimentäre Zauberkünste. Die Federglücksbringer, die sie tragen, fokussieren diese grundlegende Magie und beweisen, dass selbst ihre unerfahrenen Zauberwirker arkane oder schamanistische Energien nutzen.",al={"können frostmane trolle magie nutzen","frostmane-novize magie"}},{q="Wie sehen die Glücksbringer aus?",a="Es handelt sich um einfache Talismane, die aus Federn und Schnüren gewebt und von Frostmane-Novizen als Fokusse für ihre frühe magische Ausbildung in den kalten Höhlen von Dun Morogh gefertigt wurden.",al={"federglücksbringer beschreibung","aussehen von federglücksbringer"}}},fp="13,252,31.492.0,33.119.0,32.277.0,43.250.0,29.161.0"}
P.entries["item:fel-cone"] = {n="Teufelszapfen",s="Teufelszapfen sind verdorbene Samenkapseln, die von den Ästen von Teldrassil herabfallen und leicht an den giftigen grünen Schwaden zu erkennen sind, die aus ihren Schalen aufsteigen. Obwohl sie faulig und von dunklen Energien verdorben sind, finden einheimische Nachtelfenverteidiger clevere Verwendungsmöglichkeiten für sie gegen nahe gelegene Betrüger.",h="Teufelszapfen sind verdorbene Samenkapseln, die von den Ästen von Teldrassil herabfallen und leicht an den...",kw={"dolanaar","teufelszapfen","satyr","erlösung suchen","syral bladeleaf","teldrassil","zenn foulhoof"},ang={["class:Druid"]="Zu beobachten, wie heilsame Waldsamenkapseln zu rauchenden Teufelsresten gerinnen, ist für Druiden eine düstere Mahnung an das zerbrechliche Gleichgewicht, um das in ganz Teldrassil gerungen wird.",["race:NightElf"]="Die Existenz von Teufelszapfen ist ein beunruhigendes Zeichen von Krankheit tief in Teldrassils Wurzeln und beweist, dass selbst das noch junge Wachstum des Weltenbaums nicht vor dämonischer Verderbnis sicher ist."},sec={{t="Fäulnis im Blätterdach",b="Teldrassil ist jung, doch das Verderben ist bereits in sein lebendiges Holz gesickert. Teufelszapfen sind der sichtbare Beweis für diese tückische Fäulnis – knorrige, herabgefallene Kiefernzapfen, aus denen fauliger grüner Rauch quillt. Verstreut unter den Ästen östlich von Dolanaar sind diese Kapseln von verdorbener Magie durchdrungen, die die natürliche Flora verunstaltet und sie gefährlich macht, wenn man sie unvorsichtig berührt oder verzehrt."},{t="Eine bittere Medizin",b="Wenn unvorsichtige Reisende auf die Listen von Zenn Foulhoof hereinfallen – einem lauernden Satyr, der Vorbeigehende dazu verleitet, seine Befehle auszuführen –, fordern die örtlichen Wächter Buße. Syral Bladeleaf und die Schildwachen weisen reumütige Abenteurer an, diese giftigen Zapfen zu sammeln und Foulhoof unter dem Vorwand eines unschuldigen Snacks zu übergeben. Die konzentrierte Verderbnis im Inneren des Samens löst eine eigentümliche Verwandlung aus, die den fauligen Satyr vorübergehend in einen harmlosen Frosch verwandelt."}},faq={{q="Was ist ein Teufelszapfen?",a="Ein Teufelszapfen ist ein verdorbener Kiefernzapfen, der von den Ästen von Teldrassil herabfällt. Durch unnatürliche Magie verdorben, schwelt er mit unheimlichem grünem Rauch und birgt unbeständige, transformierende Energien.",al={"was sind teufelszapfen","teufelszapfen lore","was ist ein teufelszapfen"}},{q="Wo sind Teufelszapfen zu finden?",a="Sie liegen auf dem Waldboden unter den Bäumen direkt östlich von Dolanaar, im Herzen von Teldrassil.",al={"wo gibt es teufelszapfen","teufelszapfen fundort","teufelszapfen finden"}},{q="Warum möchte der Rat des Waldes, dass sie gesammelt werden?",a="Wenn Ihr dem Satyr Zenn Foulhoof unwissentlich dabei geholfen habt, den Kreaturen der Natur zu schaden, bietet der Rat des Waldes eine Gelegenheit, Euch reinzuwaschen. Sie weisen Euch an, Teufelszapfen zu sammeln und Zenn dazu zu verleiten, sie als Lektion zu verspeisen.",al={"zapfen erlösung suchen","warum teufelszapfen sammeln","wer will teufelszapfen"}},{q="Was passiert, wenn jemand einen Teufelszapfen isst?",a="Wenn Zenn Foulhoof die Teufelszapfen im Glauben isst, es handele sich um einen harmlosen Snack, verwandelt die konzentrierte Magie den ränkeschmiedenden Satyr augenblicklich in einen Frosch.",al={"was bewirkt teufelszapfen","teufelszapfen essen","zenn foulhoof frosch"}}},fp="8,264,20.376.0,17.455.1,19.191.0,29.114.0,55.219.0,42.151.1"}
P.entries["item:fel-moss"] = {n="Teufelsmoos",s="Teufelsmoos ist eine verdorbene pflanzliche Substanz, die sich in den Wäldern von Teldrassil ausbreitet. Es trägt dämonische und verderbende Energien in sich, wird von feindseligen Grells sowie Grellkin getragen und stellt eine tückische Bedrohung für die Tierwelt und die einheimischen Furbolgstämme des Weltenbaums dar.",h="Teufelsmoos ist eine verdorbene pflanzliche Substanz, die sich in den Wäldern von Teldrassil ausbreitet.",kw={"teufelsmoos","gnarlpine","grell","grellkin","shadowglen","tarindrella","teldrassil","ursal der raufer"},ang={["class:Druid"]="Für die Druiden vom Zirkel des Cenarius stellt Teufelsmoos ein alarmierendes Geschwür dar, das sich über Teldrassil ausbreitet und beweist, dass der neugeborene Weltenbaum zutiefst anfällig für dämonische Fäulnis ist.",["race:NightElf"]="Die Nachtelfen verehren Teldrassil als ihre neue Heimat, weshalb die Präsenz von Teufelsmoos ein erschütterndes Omen dafür ist, dass Frieden selbst auf ihren heiligen Ästen unerreichbar bleibt."},sec={{t="Fäulnis auf dem Weltenbaum",b="Teldrassil wurde gepflanzt, um die Unsterblichkeit der Nachtelfen wiederherzustellen und die natürliche Welt zu heilen, doch die Verderbnis hat sich bereits in seine unberührten Äste geschlichen. Teufelsmoos ist eines der sichtbarsten Zeichen dieses Verfalls. Dieses bösartige Gewächs, das an den wichtelartigen Grells und Grellkin haftet und von ihnen getragen wird, die Shadowglen heimsuchen, strahlt eine unnatürliche, finstere Magie aus. Waldschützer wie die Dryade Tarindrella haben begonnen, Proben zu sammeln, um zu ermitteln, wie tief diese Fäulnis bereits in das heilige Blätterdach eingedrungen ist."},{t="Saat des Wahnsinns",b="Die Gefahr des Teufelsmooses reicht weit über den bloßen Verfall des Waldes hinaus; es übt einen verheerenden Einfluss auf den Geist lebender Kreaturen aus. Einst friedliche Furbolgs, die auf den Höhen von Teldrassil heimisch waren, sind seiner Berührung erlegen, haben ihre traditionellen Behausungen verlassen und sich zum feindseligen Stamm der Gnarlpine zusammengeschlossen. Vom bösen Einfluss des Mooses in den Wahnsinn getrieben und unter Anführern wie Ursal der Raufer vereint, verdeutlichen diese geplagten Kreaturen die wachsende Krankheit, die im großen Baum Wurzeln schlägt."}},faq={{q="Was ist Teufelsmoos?",a="Teufelsmoos ist eine abscheuliche, magisch verdorbene Pflanzensubstanz, die auf Teldrassil vorkommt. Es ist von fauligen Energien durchdrungen, haftet an verpesteten Kreaturen und verbreitet Wahnsinn sowie körperliche Verderbnis im umliegenden Ökosystem.",al={"teufelsmoos lore","was ist teufelsmoos","was bewirkt teufelsmoos"}},{q="Woher kommt Teufelsmoos?",a="Auf Teldrassil erbeuten Abenteurer Klumpen von Teufelsmoos von den verkümmerten Grells und Grellkin, die die Hänge rund um Shadowglen durchstreifen. Es entstammt üblen, verderblichen Kräften, die im Weltenbaum selbst Fuß gefasst haben.",al={"wo findet man teufelsmoos","teufelsmoos beute","ursprung von teufelsmoos"}},{q="Wie wirkt sich Teufelsmoos auf die Furbolgs aus?",a="Teufelsmoos wirkt wie ein verderbender Katalysator. Der Kontakt mit seinen bösen Mächten treibt Furbolgs in gewalttätige Raserei und verwandelt die einst friedfertigen Stämme Teldrassils in den aggressiven und fremdenfeindlichen Stamm der Gnarlpine.",al={"furbolg verderbnis","warum gnarlpine wahnsinnig sind","gnarlpine teufelsmoos"}},{q="Wer versucht, die Ausbreitung von Teufelsmoos aufzuhalten?",a="Die Dryade Tarindrella in Shadowglen bittet angehende Verteidiger darum, Teufelsmoos von Grellkin zu sammeln, um ihren Verdacht einer Waldverderbnis zu bestätigen. Sie verweist besorgte Beschützer an Druiden wie Athridas Bearmantle in Dolanaar weiter.",al={"wer erforscht teufelsmoos","wer sucht teufelsmoos","tarindrella quest"}}},fp="8,264,24.512.0,16.473.1,17.211.0,30.222.0,38.207.0,45.242.0"}
P.entries["item:felix-s-box"] = {n="Felix' Kasten",s="Felix' Kasten ist ein kleiner Behälter für persönliche Habseligkeiten von Felix Whindlebolt, einem Flüchtling, der vor dem Fall von Gnomeregan entkam. Während der hektischen Evakuierung nach Dun Morogh verloren, wurde der Kasten von einheimischen Trollen der Frostmähne geplündert und in ihre Lager südwestlich von Anvilmar verschleppt.",h="Felix' Kasten ist ein kleiner Behälter für persönliche Habseligkeiten von Felix Whindlebolt, einem...",kw={"anvilmar","das coldridgetal","dun morogh","felix whindlebolt","felix' kasten","frostmaehne","gnomeregan","fluechtling"},ang={["profession:Engineering"]="Die geborgenen Werkzeuge und Behälter stellen die Lebensader eines Tüftlers dar und verdeutlichen die schiere Not, der sich vertriebene Gnomenhandwerker gegenübersehen, wenn sie von ihrer Ausrüstung getrennt werden.",["race:Gnome"]="Für Gnomenabenteurer, die im Coldridgetal beginnen, bringt die Wiederbeschaffung von Felix' persönlichen Gegenständen einem Mitverbannten unmittelbare Erleichterung, der unter den bitteren Folgen der Evakuierung Gnomeregans leidet."},sec={{t="Verloren auf der Flucht aus Gnomeregan",b="Als während des gescheiterten Versuchs, die Trogg-Bedrohung zu beseitigen, Strahlung Gnomeregan überflutete, schloss sich Felix Whindlebolt dem panischen Exodus der Gnome in das Coldridgetal an. In seiner Verzweiflung, den radioaktiven Dämpfen zu entkommen, ließ Felix seine wertvollsten persönlichen Besitztümer und seine Handwerksausrüstung an der verschneiten Straße fallen. Bevor er sie bergen konnte, plünderten einheimische Trolle der Frostmähne die Überreste am Wegesrand und schleppten seinen Kasten zusammen mit seiner Truhe und seinem Bolzeneimer in ihre primitiven Siedlungen südwestlich von Anvilmar."},{t="Dilemma eines Flüchtlings",b="Ungewohnt im Umgang mit körperlicher Gewalt und denkbar ungeeignet für die raue Wildnis von Dun Morogh war Felix gezwungen, vorbeikommende Abenteurer in Anvilmar um Hilfe bei der Bergung seiner Besitztümer zu bitten. Die Wiederbeschaffung von Felix' Kasten bedeutet mehr als nur die Rückgabe eines bescheidenen Behälters; sie gibt einem vertriebenen Handwerker, der bei der Katastrophe in seiner unterirdischen Heimat alles verloren hat, ein Stück Normalität und Lebensgrundlage zurück."}},faq={{q="Was ist Felix' Kasten?",a="Es ist ein Behälter mit den persönlichen Habseligkeiten von Felix Whindlebolt, einem Gnomenhandwerker, der nach der verheerenden Verseuchung der Stadt aus Gnomeregan floh.",al={"felix kasten","was ist dieser kasten","felix kasten lore"}},{q="Wie gelangte der Kasten zu den Trollen der Frostmähne?",a="Felix ließ seine Ausrüstung auf der Flucht vor den aus Gnomeregan quellenden verstrahlten Dämpfen zurück. Trolle der Frostmähne, die in den Hügeln südwestlich von Anvilmar patrouillierten, durchsuchten die am Wegesrand liegende Ausrüstung und brachten sie in ihr Lager.",al={"warum haben trolle felix kasten","wer stahl felix kasten","wie ging er verloren"}},{q="Wer ist Felix Whindlebolt?",a="Felix Whindlebolt ist ein ziviler Gnomenflüchtling, der sich derzeit in Anvilmar aufhält, traumatisiert durch den Fall von Gnomeregan und ohne seine lebenswichtigen Werkzeuge und persönlichen Gegenstände gestrandet ist.",al={"felix whindlebolt","wer ist felix"}},{q="Welche anderen Gegenstände hat Felix verloren?",a="Neben dem Kasten plünderten die Trolle der Frostmähne auch Felix' Truhe und seinen Bolzeneimer und verteilten alle drei auf ihre Lager südwestlich von Anvilmar.",al={"andere felix gegenstaende","felix habseligkeiten","felix verlorene ausruestung"}}},fp="11,281,34.514.0,20.412.0,20.154.0,49.210.0,25.174.0,32.150.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="Felix' Bolzeneimer",s="Felix' Bolzeneimer ist ein Behälter mit Ersatzteilen und Werkzeugen von Felix Whindlebolt, einem Gnom-Flüchtling, der vor dem Fall von Gnomeregan floh. Während seiner Flucht nach Dun Morogh wurde der Eimer von den einheimischen Frostmane-Trollen erbeutet und in ihre nahegelegenen Lager geschleppt.",h="Felix' Bolzeneimer ist ein Behälter mit Ersatzteilen und Werkzeugen von Felix Whindlebolt, einem...",kw={"anvilmar","bolzen","dun morogh","felix","frostmane","gnomeregan","flüchtling","trolle","whindlebolt"},ang={["profession:Engineering"]="Kein Tüftler kann ohne grundlegende Eisenwaren arbeiten, was einen einfachen Eimer voller Bolzen zu einem wertvollen Besitz macht, wenn man im Schnee von Dun Morogh von vorne anfängt.",["race:Gnome"]="Jeder geborgene Eimer voller Bauteile steht für ein kleines Stück Gnomeregan, das vor dem Untergang gerettet wurde, und hilft den Flüchtlingen, im Coldridgetal wieder Fuß zu fassen."},sec={{t="Die verstreuten Werkzeuge eines Flüchtlings",b="Als nach der Katastrophe gegen die Troggs Strahlung Gnomeregan überflutete, flohen Tausende Gnome mit allem, was sie tragen konnten, in die eisige Wildnis von Dun Morogh. Felix Whindlebolt gelang es, mit seiner lebenswichtigen Ausrüstung zu entkommen, doch im Chaos seiner Flucht in Richtung Anvilmar geriet er in einen Hinterhalt der Frostmane-Trolle, welche die Felsen südwestlich der Stadt bewohnen. Die Trolle plünderten seine Habseligkeiten, darunter diesen Eimer voller Bolzen und Bauteile, wodurch der Handwerker im Exil ohne die grundlegenden Materialien dastand, die er für sein Handwerk benötigte."}},faq={{q="Was ist Felix' Bolzeneimer?",a="Es ist ein schwerer Behälter voller Metallbolzen, Eisenwaren und Bastelbedarf von Felix Whindlebolt, einem verbannten Gnom, der in Anvilmar Zuflucht sucht.",al={"bolzeneimer","felix eimer","felix bolzeneimer"}},{q="Wer hat den Eimer gestohlen?",a="Die Frostmane-Trolle stahlen den Eimer zusammen mit Felix' anderen persönlichen Gegenständen, als er vor der Katastrophe in Gnomeregan floh.",al={"wer stahl die bolzen","trolle stahlen eimer","wer hat felix' bolzen"}},{q="Wohin haben die Trolle ihn gebracht?",a="Die Trolle trugen ihn zurück in ihre Lager in den Felsen südwestlich von Anvilmar im Coldridgetal.",al={"wo sind die bolzen","eimer standort","felix bolzen lager"}},{q="Warum ist dieser Eimer wichtig für Felix?",a="Gnomische Flüchtlinge entkamen ihrer Heimat mit so gut wie nichts. Für einen Ingenieur oder Handwerker wie Felix sind grundlegende Verbindungselemente und Bauteile unerlässlich, um fernab von Gnomeregan zu überleben und sich ein neues Leben aufzubauen.",al={"warum will felix bolzen","felix whindlebolt bolzen bedeutung"}}},fp="23,265,27.541.0,32.156.0,21.131.0,29.103.0,38.199.0"}
P.entries["item:felix-s-chest"] = {n="Felix' Truhe",s="Felix' Truhe ist ein Behälter mit persönlichen Gegenständen, die der verbannte Gnom Felix Whindlebolt auf der Flucht aus Gnomeregan verlor. Verschleppt von Frostmane-Trollen, die in der Nähe des Coldridgetals lauerten, steht sie verlassen in einem ihrer primitiven Berglager.",h="Felix' Truhe ist ein Behälter mit persönlichen Gegenständen, die der verbannte Gnom Felix Whindlebolt auf der...",kw={"dilemma eines flüchtlings","anvilmar","das coldridgetal","felix whindlebolt","felix' truhe","frostmane","gnomeregan"},ang={["race:Gnome"]="Die Truhe ist eine ergreifende Erinnerung an die chaotische Evakuierung von Gnomeregan, bei der fliehende Gnome beinahe alles an die Wildnis und opportunistische Plünderer verloren."},sec={{t="Die Verluste eines Flüchtlings",b="Als die unterirdische Technometropole Gnomeregan durch Trogg-Einfälle und giftigen radioaktiven Niederschlag fiel, flohen Tausende Gnome mit allen Besitztümern, die sie tragen konnten, an die verschneite Oberfläche von Dun Morogh. Felix Whindlebolt gelang die Flucht aus den verstrahlten Ruinen, doch inmitten der Panik der Evakuierung plünderten einheimische Frostmane-Trolle die Straßen und überwältigten die verstreuten Überlebenden. Felix verlor seine wichtigsten Werkzeugsätze und Habseligkeiten, und seine robuste Truhe wurde in die einfachen Lager geschleppt, die die Trolle in den Klippen südwestlich von Anvilmar unterhalten."}},faq={{q="Was befindet sich in Felix' Truhe?",a="Die Truhe enthält die persönlichen Habseligkeiten und Besitztümer, die Felix Whindlebolt bei seiner Flucht aus Gnomeregan retten konnte. Zurückgelassen bei seiner überstürzten Flucht vor der tödlichen Strahlung, ist ihr Inhalt für die Trolle von geringem Nutzen, stellt für ihn jedoch die überlebenden Überreste seines früheren Lebens dar.",al={"felix truhe inhalt","was ist in der truhe","felix' truhe beute"}},{q="Warum besitzen die Frostmane-Trolle Felix' Habseligkeiten?",a="Die Frostmane-Trolle überfallen regelmäßig Reisende und plündern das Coldridgetal. Als desorientierte gnomische Flüchtlinge sich über Dun Morogh zerstreuten, um ihrer zerstörten Stadt zu entkommen, lauerten Trolle den Nachzüglern auf und schleppten deren weggeworfene Ausrüstung und Gepäck zurück in ihre Lager.",al={"warum haben trolle felix truhe","wer stahl felix truhe","trolle felix whindlebolt"}},{q="Wo befindet sich die Truhe?",a="Die Truhe befindet sich südwestlich von Anvilmar im Coldridgetal, abgestellt nahe den Zelten einer Siedlung der Frostmane-Trolle neben anderen erbeuteten Vorräten.",al={"wo ist felix truhe","felix truhe standort","felix truhe finden"}}},fp="13,257,18.547.0,29.271.0,52.277.0,27.148.0"}
P.entries["item:felstalker-hoof"] = {n="Teufelspirscherhuf",s="Ein Teufelspirscherhuf ist ein greifbares Zeichen, das von dämonischen Bestien erbeutet wird, die den Koven der Burning Blade im Tal der Prüfungen in Durotar heimsuchen. Junge Schamanen müssen diese Hufe als Beweis ihrer Reife beschaffen, bevor sie lernen, Zwiesprache mit den Elementargeistern der Erde zu halten.",h="Ein Teufelspirscherhuf ist ein greifbares Zeichen, das von dämonischen Bestien erbeutet wird, die den Koven...",kw={"koven der burning blade","ruf der erde","canaga earthcaller","durotar","erdsapta","teufelspirscher","teufelspirscherhuf","das tal der prüfungen"},ang={["class:Shaman"]="Dämonen zu töten und ihre Hufe zu sammeln, ist Euer erster großer Schritt zur Zwiesprache mit den Erdgeistern und stellt die Geduld sowie die stoische Widerstandskraft auf die Probe, die das Führen eines Erdtotems erfordert.",["faction:Horde"]="Die Anwesenheit dämonischer Teufelspirscher auf Durotars Übungsfeldern ist eine ständige Mahnung an das anhaltende Verderben der Burning Blade auf den Ländereien der Horde."},sec={{t="Die Prüfung eines Schamanen",b="Im sonnenverbrannten Tal der Prüfungen beauftragt der Ausbilder Canaga Earthcaller angehende Schamanen damit, sich dem dämonischen Verderben zu stellen, das Durotar bedroht. Der Koven der Burning Blade im Norden beherbergt üble Familiare und dämonische Teufelspirscher. Diesen Unholden die Hufe abzunehmen, ist nicht bloß eine Ausrottung von Schädlingen, sondern eine harte Prüfung der Ausdauer, der Entschlossenheit und des Geistes. Nur indem sie diese chaotischen Bestien bezwingen, können sich angehende Schamanen als würdig erweisen, die Geheimnisse der Erde zu empfangen und die zeremonielle Sapta vorzubereiten, die für die direkte Zwiesprache mit Elementargeistern erforderlich ist."}},faq={{q="Wofür wird der Teufelspirscherhuf verwendet?",a="Zwei Teufelspirscherhufe werden zu Canaga Earthcaller in das Tal der Prüfungen gebracht. Sie dienen als Beweis dafür, dass ein Schamanennovize die nötige Stärke und den Geist besitzt, um mit dem Erdelement Zwiesprache zu halten.",al={"was bringt teufelspirscherhuf","huf questgegenstand","warum teufelspirscherhufe sammeln"}},{q="Woher stammen diese Hufe?",a="Sie werden von den dämonischen Teufelspirschern erbeutet, die im und um den Koven der Burning Blade im nördlichen Teil des Tals der Prüfungen in Durotar zu finden sind.",al={"woher teufelspirscherhuf","teufelspirscherhuf fundort","wer lässt hufe fallen"}},{q="Wer verlangt diese Hufe?",a="Canaga Earthcaller, der Schamanenausbilder nahe dem Höhlenbau im Tal der Prüfungen, verlangt sie während des Ritus „Ruf der Erde“.",al={"wer braucht teufelspirscherhufe","wer nimmt huf an","canaga earthcaller quest"}},{q="Kann jeder Abenteurer diese Hufe sammeln?",a="Teufelspirscherhufe werden gezielt von Schamanen gesucht, die ihre elementare Initiation durchlaufen. Krieger, Hexenmeister und Schurken haben ihre eigenen Prüfungen im Tal und benötigen sie nicht.",al={"können nicht-schamanen hufe bekommen","ist huf nur für schamanen"}}},fp="15,260,16.552.0,37.208.0,32.161.0,26.131.0,40.197.0"}
P.entries["item:fenwick-s-head"] = {n="Fenwicks Kopf",s="Fenwicks Kopf ist der grausige Beweis für die Hinrichtung von Fenwick Thatros an den Ufern des Lordamere Sees. Er wird von Schurken der Verlassenen eingefordert, die auf direkte Befehle von Lord Varimathras hin handeln.",h="Fenwicks Kopf ist der grausige Beweis für die Hinrichtung von Fenwick Thatros an den Ufern des Lordamere Sees.",kw={"todespirscher","fenwick","lordamere","mennet carkad","rogues' quarter","silberwald","thatros","varimathras"},ang={["class:Rogue"]="Die Erbeutung von Fenwicks Kopf ist ein entscheidender Meilenstein für aufstrebende Schurken der Verlassenen, der ihre Zuverlässigkeit als Todespirscher festigt und ihnen Zugang zu fortgeschrittenem Training verschafft.",["race:Undead"]="Die Jagd zeigt die unbarmherzige Unterdrückung rivalisierender untoter Gruppierungen durch die Verlassenen, die um die Kontrolle über den Silberwald und die Ufer des Lordamere Sees streiten."},sec={{t="Ein Kontrakt aus den Schatten",b="Im Rogues' Quarter von Undercity handelt Mennet Carkad auf dringende Informationen hin, die direkt von Schreckenslord Varimathras weitergeleitet wurden. Ein feindseliger untoter Anführer namens Fenwick Thatros hat in der Nähe der verfallenden Docks am Lordameresee im Silberwald Fuß gefasst. Um zu verhindern, dass diese Bedrohung feindliche Untote gegen die Verlassenen sammelt, entsendet Carkad vielversprechende Todespirscher, um Thatros aufzuspüren, ihn zu eliminieren und seinen Kopf als unbestreitbaren Beweis für die Tötung abzutrennen."},{t="Ein Übergangsritus",b="Die Übergabe von Fenwicks Kopf an Carkad ist mehr als nur das einfache Einfordern eines Kopfgeldes; sie dient als entscheidende Prüfung für Agenten der Todespirscher. Die Vorlage der abgetrennten Trophäe bestätigt die Kompetenz des Schurken in Infiltration und Attentat und öffnet die Tür zu vertiefter, spezialisierterer Unterweisung in den Schattenkünsten durch die Meister der Verlassenen."}},faq={{q="Wer war Fenwick Thatros?",a="Fenwick Thatros wurde von Lord Varimathras als ein im Silberwald verschanzter untoter Anführer identifiziert. Seine Anwesenheit in der Nähe der baufälligen Docks des Lordamere Sees machte ihn zu einer unmittelbaren Gefahr für die Interessen der Verlassenen in der Region.",al={"wer ist fenwick","fenwick thatros geschichte","wer war thatros"}},{q="Wer will Fenwicks Kopf?",a="Der Kopf wird von Mennet Carkad verlangt, einem Ausbilder der Todespirscher, der im Rogues' Quarter von Undercity weilt und damit einen dringenden Befehl von Lord Varimathras ausführt.",al={"wer will den kopf","bei wem abgeben","mennet carkad"}},{q="Wo befindet sich Fenwick Thatros?",a="Laut Berichten von Spähern der Todespirscher lauert Fenwick Thatros an den baufälligen Docks am Ufer des Lordamere Sees im Silberwald.",al={"fenwick thatros standort","wo ist fenwick","fenwick finden"}},{q="Warum muss sein Kopf abgetrennt werden?",a="Mennet Carkad verlangt einen unbestreitbaren physischen Beweis dafür, dass die Bedrohung vollständig beseitigt wurde, bevor er einen Agenten für das fortgeschrittene Schattentraining zulässt.",al={"warum seinen kopf nehmen","warum ihn enthaupten"}}},fp="14,205,27.472.0,17.334.0,24.229.0,25.171.0,33.158.0,29.160.0"}
P.entries["item:fey-dragon-scale"] = {n="Siechdrachenschuppe",s="Eine Siechdrachenschuppe ist ein schimmerndes Waldrelikt, das von den schwer fassbaren Feendrachen erbeutet wird, die um Den Steinkrallengipfel leben. Sie wird von dem Hexendoktor der Dunkelspeere, Jin'Zil, begehrt, der sie als exotisches Reagenz in einem alchemistischen Gebräu verwendet, das die Naturmagie der Nachtelfen verhöhnt.",h="Eine Siechdrachenschuppe ist ein schimmerndes Waldrelikt, das von den schwer fassbaren Feendrachen erbeutet...",kw={"feendrache","siechdrachenschuppe","waldmagie","jin'zil","malaka'jin","nal'taszar","der steinkrallengipfel"},ang={["faction:Horde"]="Jin'Zil zu helfen sichert den Halt der Horde im Steinkrallengebirge und trifft die Nachtelfenpräsenz direkt, die sich weiter oben an den Hängen verschanzt hat.",["race:NightElf"]="Feendrachen sind geschätzte Gefährten und Waldwächter der Kaldorei; zu sehen, wie ihnen für den tödlichen Hohn eines Troll-Hexendoktors die Schuppen entrissen werden, ist ein Frevel an der Natur."},sec={{t="Eine seltene Waldbeute",b="Feendrachen sind geheimnisvolle, scheue Wesen, die eng mit den wilden Hainen von Kalimdor verbunden sind, insbesondere mit den unberührten Wäldern um Den Steinkrallengipfel. Ihre Schuppen tragen einen natürlichen magischen Schimmer, der an die tiefen Wälder erinnert, die sie bewachen. Während sie von den Nachtelfen als harmlose Waldgeister und Verbündete verehrt werden, betrachten Außenstehende sie als ungezähmte Quelle seltener magischer Zutaten."},{t="Ein verhöhnendes Gebräu",b="In der Horde-Siedlung Malaka'jin braut Hexendoktor Jin'Zil eine finstere Mischung zusammen, die die heiligen Traditionen der Kaldorei parodiert. Indem er eine Siechdrachenschuppe mit Baumharz, Katzenschnurrhaaren und dutzenden Augen von Läufern kombiniert, braut Jin'Zil etwas, das er spöttisch als „Waldmagie“ bezeichnet. Weit entfernt von einem harmlosen Natursegen erweist sich das fertige Gebräu als tödliches Giftgas, das für seine gefangenen Nachtelfen bestimmt ist."}},faq={{q="Woher stammt diese Schuppe?",a="Die Schuppe wird von Feendrachen erbeutet, die durch die Haine des Hochlands um Den Steinkrallengipfel flattern, darunter schwer fassbare Kreaturen wie Wily Fey Dragons und Nal'taszar.",al={"siechdrachenschuppe beute","wo findet man siechdrachenschuppe","wer lässt siechdrachenschuppe fallen"}},{q="Warum will Hexendoktor Jin'Zil eine Siechdrachenschuppe?",a="Hexendoktor Jin'Zil in Malaka'jin verlangt die Schuppe zusammen mit anderen Waldreagenzien, um das zu brauen, was er hämisch als „Waldmagie“ für seine gefangenen Nachtelfen bezeichnet.",al={"warum will jin'zil das","wofür wird die schuppe verwendet","jin'zil waldmagie reagenz"}},{q="Was geschieht, wenn Jin'Zil sein Gebräu vollendet?",a="Sobald alles zusammengetragen ist, entfesselt Jin'Zil sein fertiges Gebräu in seiner Höhle. Statt harmloser Waldmagie ist das Gemisch ein tödliches Gift, das die drei gefangenen Nachtelfen tötet, sodass nur noch ihre Irrlichter übrig bleiben und in die Wildnis davonschweben.",al={"was macht jin'zil mit dem gebräu","jin'zil magie ergebnis","gefangene von jin'zil"}}},fp="16,269,21.382.0,20.441.1,32.169.0,54.170.0,44.241.1"}
P.entries["item:filled-amethyst-phial"] = {n="Gefüllte Amethystphiole",s="Die Gefüllte Amethystphiole enthält heiliges Wasser, das aus dem uralten Mondbrunnen unter den Ästen des Orakelbaums geschöpft wurde. Dieses gereinigte Wasser, das im Auftrag von Corithras Moonrage gesammelt wurde, wird von den Druiden des Cenarius verwendet, um das beunruhigte, unvollkommene Wachstum von Teldrassil zu untersuchen.",h="Die Gefüllte Amethystphiole enthält heiliges Wasser, das aus dem uralten Mondbrunnen unter den Ästen des...",kw={"amethystphiole","corithras moonrage","krone der erde","gefüllte amethystphiole","mondbrunnen","die lichtung des orakels","orakelbaum","teldrassil"},ang={["class:Druid"]="Druiden des Cenarius verehren Mondbrunnen als Kanäle für Natur- und Astralenergie und nutzen gereinigte Gefäße wie diese Phiole, um die zerrüttete Ökologie von Teldrassil zu untersuchen.",["race:NightElf"]="Für die Kaldorei markiert das Füllen dieser Phiole eine bittere Erkenntnis: Ihre prachtvolle neue Heimat wurde von den Drachenaspekten abgelehnt, und ihre verlorene Unsterblichkeit ist nicht zurückgekehrt."},sec={{t="Wasser des Orakelbaums",b="Weit im Nordwesten von Teldrassil liegt die Lichtung des Orakels, wo der älteste und mächtigste Mondbrunnen der Insel unter dem großen Orakelbaum ruht. Während die kleineren Mondbrunnen auf den Ästen den alltäglichen Bedürfnissen der Nachtelfen dienen, ist das Wasser dieses Brunnens mit der reinen Essenz von Elunes Anmut durchdrungen. Druiden, die mit der Überwachung des Gesundheitszustands des Weltenbaums betraut sind, verwenden spezielle Amethystphiolen, um diese mächtige Flüssigkeit für Tests und rituelle Reinigungen zu sammeln und aufzubewahren."},{t="Eine fehlerhafte Erneuerung",b="Die Rückbringung dieser Probe zu Corithras Moonrage dient einem düsteren Zweck. Trotz des Triumphs von Erz走druide Fandral Staghelm bei der Erschaffung von Teldrassil als Ersatz für das gefallene Nordrassil weigerten sich die Drachenaspekte, ihn zu weihen. Ohne den Segen von Nozdormu zur Wiederherstellung der Unsterblichkeit der Nachtelfen oder Alexstraszas Schutz für seine Lebenskraft bleibt das Wachstum von Teldrassil gehemmt und von Verderbnis geplagt. Proben aus der Lichtung offenbaren, dass selbst das heiligste Wasser der Insel das schleichende Unbehagen, das im Weltenbaum Wurzeln schlägt, nicht verbergen kann."}},faq={{q="Woher stammt das Wasser in dieser Phiole?",a="Das Wasser wird direkt aus dem Mondbrunnen in der Lichtung des Orakels geschöpft, der sich in den nordwestlichen Ausläufern von Teldrassil unter den gewaltigen Wurzeln des Orakelbaums befindet.",al={"wo fülle ich sie","mondbrunnen standort","brunnen des orakelbaums"}},{q="Warum ist der Mondbrunnen in der Lichtung des Orakels etwas Besonderes?",a="Er wird als der erste und mächtigste Mondbrunnen verehrt, der auf Teldrassil erschaffen wurde. Er birgt die konzentrierte Essenz von Elunes Macht und wird vom uralten Orakelbaum selbst bewacht.",al={"warum die lichtung des orakels","orakel mondbrunnen bedeutung"}},{q="Wer bittet Euch darum, dieses Wasser zu sammeln?",a="Corithras Moonrage, ein in Dolanaar stationierter Nachtelfendruide, beauftragt junge Abenteurer im Rahmen der Rituale um Krone der Erde mit dem Sammeln des Wassers.",al={"wer will die phiole","corithras quest"}},{q="Warum untersuchen die Druiden Teldrassils Mondbrunnen?",a="Teldrassil wurde ohne den Segen der Drachenaspekte erschaffen, was ihn verwundbar macht. Die Druiden entnehmen Proben aus den Mondbrunnen, um die Gesundheit des Weltenbaums zu überwachen, der beunruhigende Anzeichen von Verderbnis und verkümmertem Wachstum aufweist.",al={"warum das wasser testen","teldrassil krankheit"}}},fp="21,266,24.487.0,16.525.1,45.161.0,44.178.0,34.153.0,50.224.0"}
P.entries["item:filled-blue-waterskin"] = {n="Voller blauer Wasserschlauch",s="Der Voller blauer Wasserschlauch enthält unberührtes Wasser, das an einem Brunnen in den uralten Sternenstaubruinen in Ashenvale geschöpft wurde. Schamanen, die die Zwiesprache mit den Wassergeistern suchen, sammeln diese Probe als entscheidendes Reagenz für ihre Übergangsprüfung.",h="Der Voller blauer Wasserschlauch enthält unberührtes Wasser, das an einem Brunnen in den uralten...",kw={"ashenvale","brine","ruf des wassers","voller blauer wasserschlauch","lake mystral","die sternenstaubruinen","schamanenquest"},ang={["class:Shaman"]="Das Beschaffen dieses heiligen Wassers stellt den Höhepunkt Eurer Reise zur Beherrschung des Wassers dar und verlangt von Euch, feindliche Fraktionsgrenzen zu überqueren, um mit den reinsten Reservoirs der Natur in Einklang zu treten.",["faction:Horde"]="Der Vorstoß nach Norden in die umkämpften Wälder von Ashenvale birgt echte Gefahren für Initianden der Horde und zwingt Euch auf der Suche nach der Vollendung heiliger Riten in angestammtes Territorium der Nachtelfen."},sec={{t="Heilige Quelle von Ashenvale",b="Initianden, die sich dem Ruf des Wassers widmen, werden nach Norden über die Grenze aus dem Brachland in die dichten Wälder von Ashenvale geschickt. Eingebettet an den Bergen, die Ashenvale von Stonetalon trennen, jenseits des Lake Mystral, liegen die Sternenstaubruinen – ein abgelegenes elfisches Heiligtum, das von wilden Waldtieren bewacht wird. Im Zentrum dieses heiligen Sees steht ein unberührter Brunnen. Wer aus dessen Becken in einen blauen Wasserschlauch schöpft, erhält Wasser, das frei von Verderbnis oder Dürre ist und von Schamanenmeistern für rituelle Einstimmungen geschätzt wird."},{t="Ein Ritus der Harmonie",b="Das in diesem Gefäß gesammelte Wasser dient als letzte Probe, die von Brine benötigt wird, einer einsiedlerischen Wasserexpertin, die an den südlichen Sümpfen des Brachlands lebt. Zusammen mit Wasser aus anderen gegensätzlichen Brunnen und Quellen wird diese reine Essenz zu einer Opfergabe destilliert, die mächtig genug ist, um die Elementargeister des Wassers zu manifestieren und zu besänftigen, womit die Prüfung des Initianden vollendet wird."}},faq={{q="Wo wird das Wasser geschöpft, um diesen Wasserschlauch zu füllen?",a="Es wird aus einem kleinen Brunnen in der Mitte des Sees in den Sternenstaubruinen geschöpft, der im südwestlichen Ashenvale direkt hinter dem Lake Mystral liegt.",al={"wo fülle ich ihn","die sternenstaubruinen brunnen","wasser fundort"}},{q="Wer benötigt dieses Wasser?",a="Brine, eine erfahrene Einsiedlerin in den südlichen Weiten des Brachlands, weist angehende Schamanen an, dieses Wasser im Rahmen der Prüfungen zum Ruf des Wassers zu beschaffen.",al={"wer will den blauen wasserschlauch","brine wasser","ruf des wassers nsc"}},{q="Was ist der Zweck des Sammelns dieser Probe?",a="Es ist das letzte Reagenz, das Brine benötigt, um einen Trank aus außergewöhnlich reinem Wasser zu brauen, der es einem angehenden Schamanen ermöglicht, mit den Elementargeistern des Wassers in Zwiesprache zu treten und sie zu ehren.",al={"wofür brauche ich ihn","wofür voller blauer wasserschlauch genutzt wird"}},{q="Ist das Gebiet, in dem das Wasser geschöpft wird, gefährlich?",a="Ja. Die Sternenstaubruinen werden von feindseligen Wildtieren bewohnt, darunter einheimische Elementare und wilde Bestien, die die uralte Elfenlichtung gegen Eindringlinge verteidigen.",al={"die sternenstaubruinen gefahr","ist ashenvale brunnen sicher"}}},fp="21,233,26.515.0,17.380.0,51.160.0,24.155.0,46.178.0,50.164.0"}
P.entries["item:filled-brown-waterskin"] = {n="Voller brauner Wasserschlauch",s="Der Voller brauner Wasserschlauch enthält frisches Wasser, das aus einem seltenen Teich nahe Brines Hütte im Brachland geschöpft wurde. Von angehenden Schamanen gesammelt, bildet er den ersten grundlegenden Schritt beim Brauen des Saptas, das für die Zwiesprache mit den Geistern des Wassers benötigt wird.",h="Der Voller brauner Wasserschlauch enthält frisches Wasser, das aus einem seltenen Teich nahe Brines Hütte im...",kw={"brachland","brine","brauner wasserschlauch","ruf des wassers","voller brauner wasserschlauch","stacheleber","sapta","schamanenquest"},ang={["class:Shaman"]="Dieses Wasser zu beschaffen ist die erste praktische Prüfung, die Brine während der Quest „Ruf des Wassers“ auferlegt; sie lehrt Euch, das empfindliche Gleichgewicht und die wilden Leidenschaften rund um das flüssige Leben zu achten."},sec={{t="Ein lebensspendender Schluck",b="In den ausgedörrten Weiten des Brachlands ist Oberflächenwasser zugleich ein Segen und ein Schlachtfeld. Der unterhalb von Brines Hütte gelegene Teich spendet kostbare Feuchtigkeit, die die verzweifelten und verteidigungsbereiten Stacheleber anzieht, die in der Nähe hausen. Für einen Initianden auf dem Pfad des Schamanen ist das Füllen dieses einfachen Lederschlauchs nicht bloß eine Botenaufgabe zur Materialbeschaffung; es ist eine Lektion der Elemente. Indem der Novize an das Becken herantritt und den erbitterten Kampf um dieses Territorium miterlebt, erfährt er aus erster Hand, wie genau jener Stoff, der das Leben in der Wüste erhält, sterbliche Kreaturen zur Gewalt treiben kann."}},faq={{q="Wofür wird der Voller brauner Wasserschlauch verwendet?",a="Er wird direkt zu Brine an ihrer Hütte im südlichen Brachland gebracht. Sie verwendet das gesammelte Wasser, um mit der Zubereitung des elementaren Saptas zu beginnen – einem Trank, der es Schamanen ermöglicht, Wassergeister wahrzunehmen und mit ihnen zu kommunizieren.",al={"brauner wasserschlauch verwendung","was ist voller brauner wasserschlauch","was tun mit vollem braunen wasserschlauch"}},{q="Woher stammt dieses Wasser?",a="Es wird aus dem kleinen Süßwasserbecken geschöpft, das direkt unterhalb des Kamms unter Brines abgelegener Hütte liegt – eine Oase, die von den hiesigen Stachelebern erbittert umkämpft wird.",al={"woher wasser bekommen","teich standort","wo ist die wasserstelle"}},{q="Warum kämpfen die Stacheleber um diese Wasserquelle?",a="Im trockenen Brachland regnet es äußerst selten, weshalb jeder Teich einen gewaltigen Reichtum darstellt. Wasser ist so knapp, dass die Stacheleber Feste feiern, wenn es regnet, und natürliche Quellen bis zum Tod gegen Eindringlinge verteidigen.",al={"warum stacheleber angreifen","stacheleber wasser","warum wasser heilig für stacheleber ist"}}},fp="22,235,21.593.0,44.210.0,32.153.0,49.211.0"}
P.entries["item:filled-cliffspring-falls-sampler"] = {n="Gefüllte Cliffspring Falls-Probe",s="Die Gefüllte Cliffspring Falls-Probe enthält trübes Wasser, das aus den Quellgewässern nahe den Cliffspring Falls in Darkshore geschöpft wurde. Im Auftrag des Zirkels des Cenarius gesammelt, dient sie als entscheidendes Beweisstück, um aufzudecken, was die einheimische Hirschpopulation vergiftet.",h="Die Gefüllte Cliffspring Falls-Probe enthält trübes Wasser, das aus den Quellgewässern nahe den Cliffspring...",kw={"alanndarian nightsong","auberdine","zirkel des cenarius","cliffspring falls","darkshore","dendrite starblaze","vergiftetes wasser","probe"},ang={["class:Druid"]="Das Beschaffen und Analysieren dieses verdorbenen Wassers ist eine entscheidende Bewährungsprobe für Allianz-Druiden und bildet die investigative Grundlage für das Meistern von Vergiftung heilen.",["race:NightElf"]="Für die Nachtelfen von Darkshore ist die Sicherung der Quellgewässer von Cliffspring unerlässlich, um Auberdines Ökologie vor übler fremder Verderbnis zu bewahren."},sec={{t="Eine verdorbene Quelle",b="Cliffspring Falls liefert das Haupttrinkwasser für weite Teile von Darkshore, während es aus dem östlichen Hochland in Richtung Meer hinabstürzt. Kürzlich jedoch fiel die Tierwelt, die auf dieses Wasser angewiesen ist – insbesondere die einheimischen Hirsche –, einer schwächenden, unnatürlichen Krankheit anheim. Auf Geheiß von Dendrite Starblaze in Moonglade bergen druidische Initianden diese Probe direkt am Eingang einer von feindseligen Naga verseuchten Höhle. Die Phiole enthält sichtbar faulige Flüssigkeit und bestätigt damit, dass die wichtigste Süßwasserversorgung der Region aktiv korrumpiert ist."},{t="Weg zu einem Heilmittel",b="Zu Alanndarian Nightsong in Auberdine gebracht, liefert die faulige Probe den physischen Beweis, den der Zirkel des Cenarius benötigt, um das Gift zu untersuchen. Anstatt sie einfach zu entsorgen, nutzt Alanndarian das verschmutzte Wasser, um die Beschaffenheit des Schadstoffs zu analysieren. Die genauen Eigenschaften des Schlamms zu entschlüsseln, ermöglicht es den Druiden, eine heilsame Salbe herzustellen – ein wesentlicher Schritt bei der Entwicklung des Ritus, der Anwendern Macht über Gift verleiht."}},faq={{q="Was befindet sich in der Gefüllten Cliffspring Falls-Probe?",a="Sie enthält verseuchtes Wasser, das am Höhleneingang nahe den Cliffspring Falls in Darkshore geschöpft wurde. Das Wasser ist sichtlich verfärbt und trägt das Gift in sich, das die einheimischen Hirsche erkranken lässt.",al={"inhalt der probe","welches wasser ist in der phiole","was ist in der probe"}},{q="Wer verlangt diese Wasserprobe?",a="Dendrite Starblaze vom Zirkel des Cenarius weist junge Druiden an, die Probe zu sammeln, während Alanndarian Nightsong in Auberdine sie entgegennimmt, um das Gift zu analysieren und ein Heilmittel herzustellen.",al={"wer will die wasserprobe","wem gebe ich die probe","wer braucht die gefüllte probe"}},{q="Warum sind die Cliffspring Falls so wichtig?",a="Cliffspring Falls ist die wichtigste Trinkwasserquelle für die Region Darkshore. Jede Verderbnis, die in die Wasserfälle gelangt, breitet sich über die lokalen Wasserwege aus und beeinträchtigt die gesamte Wildnis.",al={"warum cliffspring falls","bedeutung von cliffspring falls"}},{q="Was führt dazu, dass das Wasser faulig wird?",a="Das Wasser entspringt nahe einer Höhle, die kürzlich von feindseligen Naga überrannt wurde. Ihre Anwesenheit fällt mit der Verschmutzung der Quellgewässer zusammen und verbreitet eine unnatürliche Krankheit unter der einheimischen Fauna.",al={"wer hat das wasser vergiftet","warum sind die falls vergiftet","naga cliffspring falls"}}},fp="32,252,16.544.0,16.429.1,52.195.0,31.184.0,38.197.0,39.184.0"}
P.entries["item:filled-containment-coffer"] = {n="Gefüllte Verwahrungskästen",s="Gefüllte Verwahrungskästen sind verzauberte Behälter, die von Zauberkundigen der Verlassenen genutzt werden, um unberechenbare magische Wesenheiten einzufangen. Durch den Einsatz einer Inkantation der Manifestation zur Enthüllung und Schwächung von Rissbruten im Apothecarium können Magier die Anomalien zur sicheren Untersuchung in diesen verstärkten Kästen bannen.",h="Gefüllte Verwahrungskästen sind verzauberte Behälter, die von Zauberkundigen der Verlassenen genutzt werden...",kw={"algernon","anastasia hartwell","apothecarium","arkane störung","inkantation der manifestation","verwahrungskasten","gefüllte verwahrungskästen","rissbrut"},ang={["class:Mage"]="Lehrlinge der Verlassenen handhaben diese Verwahrungskästen als praktische Lektion in der Bannmagie und lernen dabei, wie man verborgene magische Wesenheiten enthüllt und instabile arkane Energie in physische Schutzzauber bindet.",["race:Undead"]="Die Sicherheit des Apothecariums ist für die Verlassenen von höchster Bedeutung, weshalb die Untersuchung und Eindämmung jeder mysteriösen magischen Bresche eine dringende innerstädtische Priorität darstellt."},sec={{t="Das Unsichtbare fangen",b="Als sich in Algernons Laden im Apothecarium unerklärliche magische Störungen manifestierten, beauftragte die Magierin der Verlassenen Anastasia Hartwell arkane Zauberkundige damit, die verantwortlichen Wesenheiten einzufangen. Da die Risskreaturen rein aus lebendiger magischer Energie bestehen und unsichtbar umherwandern, sind gewöhnliche Käfige nutzlos. Stattdessen enthüllen Zauberkundige die Wesenheiten mit einer Inkantation der Manifestation, besiegen sie im Kampf und schnappen diese speziell präparierten Verwahrungskästen um sie herum zu. Die versiegelten Kästen schützen den Träger vor unberechenbaren magischen Rückkopplungen, während sie die Exemplare für magische Sektionen intakt halten."},{t="Arkane Forensik",b="Die Anwesenheit lebendiger Manakreaturen in Undercity stellt eine ernsthafte Bedrohung dar. Einmal in Verwahrungskästen versiegelt, werden die gefangenen Bestien zu Anastasia Hartwell und den Gelehrten der Stadt zurückgebracht. Das Hauptanliegen der Magier der Verlassenen besteht darin, herauszufinden, ob diese Übergriffe natürliche Risse im magischen Gefüge von Azeroth sind oder die ersten Sondierungen eines kalkulierten magischen Angriffs auf das Königreich."}},faq={{q="Was befindet sich in einem Gefüllten Verwahrungskasten?",a="Jeder Kasten enthält eine gefangene Rissbrut, eine unsichtbare Kreatur aus reiner, roher magischer Energie, die sich in Algernons Alchemieladen im Apothecarium manifestiert hat.",al={"was ist im kasten","kasten inhalt","gefüllter kasten monster"}},{q="Wie wird ein Verwahrungskasten gefüllt?",a="Ein Magier muss die Inkantation der Manifestation sprechen, um die verborgenen Kreaturen sichtbar zu machen, sie im Kampf besiegen und einen leeren Kasten einsetzen, um die verbleibende Energie einzufangen, bevor sie sich verflüchtigt.",al={"wie kasten füllen","wie fange ich die rissbrut","kasten füllen"}},{q="Wer benötigt diese gefüllten Kästen in Undercity?",a="Anastasia Hartwell, eine bedeutende Magierlehrerin im Magic Quarter von Undercity, verlangt diese versiegelten Kästen, um die Störung zu untersuchen, die die Stadt bedroht.",al={"wer nimmt die kästen","kasten questgeber","anastasia hartwell kasten"}},{q="Warum studieren die Verlassenen diese Kreaturen?",a="Die Gelehrten von Undercity müssen herausfinden, ob die Anomalie ein zufälliger Riss im lokalen Magiefluss war oder ein gezielter, koordinierter Angriff einer verfeindeten magischen Macht.",al={"warum rissbrut erforschen","undercity riss grund"}}},fp="25,294,19.619.0,16.414.0,43.164.0,35.186.0,44.166.0,46.173.0"}
P.entries["item:filled-crystal-phial"] = {n="Gefüllte Kristallphiole",s="Eine Gefüllte Kristallphiole enthält heiliges Wasser, das aus dem Mondbrunnen direkt nördlich von Aldrassil in Shadowglen geschöpft wurde. Auf Anweisung von Tenaron Stormgrip gesammelt, dient dieses Wasser als Einführung eines Neulings in die heilige und unbeständige Macht, die Teldrassil durchströmt.",h="Eine Gefüllte Kristallphiole enthält heiliges Wasser, das aus dem Mondbrunnen direkt nördlich von Aldrassil...",kw={"aldrassil","krone der erde","kristallphiole","gefüllte kristallphiole","mondbrunnen","shadowglen","tenaron stormgrip","brunnen der ewigkeit"},ang={["class:Druid"]="Druiden bringen dem Wasser der Mondbrunnen tiefe Ehrfurcht entgegen und nutzen seine revitalisierenden Energien, um verdorbene Pflanzenwelt zu pflegen und die großen Bäume zu erhalten.",["race:NightElf"]="Jeder junge Kaldorei, der seine Ausbildung unter Aldrassil beginnt, füllt diese Phiole und besinnt sich dabei auf das Opfer am Hyjal und seine heilige Pflicht zum Schutz der Natur."},sec={{t="Wasser des Mondbrunnens",b="Um junge Nachtelfen darauf vorzubereiten, in die weite Welt hinauszuziehen, schickt Tenaron Stormgrip sie aus, um Wasser aus dem in Shadowglen gelegenen Mondbrunnen zu sammeln. Die Phiole enthält mehr als einfaches Quellwasser; Mondbrunnen sind von Restenergien durchdrungen, die auf den uralten Brunnen der Ewigkeit zurückgehen. Während die Schildwachen diese Stätten als gesegnete Schreine von Elune ehren und Druiden ihre wiederherstellenden Eigenschaften zur Pflege der Natur einsetzen, bleibt die arkane Zauberei der Vorzeit streng verboten. Dieses Wasser zu schöpfen ist der erste Schritt zum Verständnis der Opfer am Hyjal und des empfindlichen Gleichgewichts, das zur Pflege von Teldrassil erforderlich ist."}},faq={{q="Was befindet sich in der Gefüllten Kristallphiole?",a="Die Phiole enthält Wasser, das aus dem Mondbrunnen nördlich von Aldrassil in Shadowglen geschöpft wurde. Diese Wasser tragen Überreste des uralten Brunnens der Ewigkeit in sich, gesegnet durch Elunes Licht und gepflegt durch druidische Fürsorge.",al={"welches wasser ist in der phiole","inhalt der phiole","was ist in der kristallphiole"}},{q="Wer bittet Euch darum, die Phiole zu füllen?",a="Tenaron Stormgrip, der oben in den Ästen von Aldrassil weilt, schickt angehende Abenteurer aus, um das Wasser als Teil ihres Übergangsritus und ihrer geschichtlichen Unterweisung zu schöpfen.",al={"wer will die phiole","wer vergibt kristallphiole quest","tenaron stormgrip quest"}},{q="Warum möchte Tenaron Stormgrip dieses Wasser?",a="Tenaron nutzt diese Sammelaufgabe als einleitende Lektion über die Geschichte der Nachtelfen nach dem Dritten Krieg und unterrichtet junge Abenteurer über das Opfer von Nordrassil, die Macht der Mondbrunnen und die fortwährende Fürsorge für Teldrassil.",al={"warum kristallphiole füllen","krone der erde zweck"}},{q="Sind die Wasser gefährlich?",a="Die Wasser tragen mächtige Magie in sich, die im uralten Brunnen der Ewigkeit wurzelt. Während Druiden und Priesterinnen sie gefahrlos für Segnungen und Heilung nutzen, führte rücksichtslose arkane Manipulation solcher Wasser in alten Zeiten zur Katastrophe und bleibt streng verboten.",al={"ist mondbrunnenwasser gefährlich","ist das wasser magisch"}}},fp="20,265,22.622.0,40.195.0,31.165.0,43.227.0,25.253.0"}
P.entries["item:filled-cursed-ooze-jar"] = {n="Gefüllter verfluchter Brühschlammerkrug",s="Ein Gefüllter verfluchter Brühschlammerkrug enthält die giftigen Überreste eines verfluchten Brühschlammers, die in den verderbten Wäldern des Teufelswalds gesammelt wurden. Er wird im Auftrag von Laris Geardawdle beschafft, einem Gnomengelehrten in Ironforge, der den urzeitlichen Ursprüngen der Schlämme auf ganz Azeroth auf den Grund gehen will.",h="Ein Gefüllter verfluchter Brühschlammerkrug enthält die giftigen Überreste eines verfluchten Brühschlammers...",kw={"cursed ooze","forscherliga","teufelswald","gefüllter verfluchter brühschlammerkrug","ironforge","laris geardawdle","schlamm"},ang={["faction:Alliance"]="Die Naturphilosophen der Allianz in Ironforge haben ein wachsames Auge auf die Bewegungen der Verlassenen und stellen fest, dass die Königliche Apothekervereinigung ebenfalls ein finsteres Interesse daran zeigt, Proben von Brühschlämmen auf ganz Azeroth zu sammeln.",["race:Gnome"]="Laris Geardawdles Besessenheit von der Schlammforschung ist zutiefst persönlicher Natur, angetrieben von dem Wunsch, den vertriebenen Gnomen Ehre zu machen und ihren intellektuellen Wert gegenüber den zwergischen Gastgebern in Ironforge zu beweisen."},sec={{t="Ein sonderbares Exemplar",b="Während die meisten Abenteurer die abscheulichen Pfützen und ätzenden Schlämme meiden, die durch Kalimdor kriechen, betrachtet der Gnomenforscher Laris Geardawdle sie als biologisches Rätsel. Da er bemerkte, dass Schlämme in den verschiedensten Umgebungen vorkommen, und beobachtete, wie Apotheker der Verlassenen sie emsig ernten, entwickelte Geardawdle eine umstrittene Theorie: Brühschlämmer könnten urzeitliche Sekrete sein, die direkt mit Azeroths Schöpfung verknüpft sind. Eine Probe zu sammeln erfordert es, den verheerten Wäldern des Teufelswalds zu trotzen, einen verfluchten Brühschlammer zu besiegen und die ätzende Materie in einen leeren Krug zu schöpfen, bevor sie sich vollends auflöst."},{t="Akademischer Ehrgeiz",b="Die Beschaffung dieser beißenden Proben erfüllt für Geardawdle einen doppelten Zweck. Über das Streben nach Naturwissenschaften hinaus hofft er, dass eine bedeutende Entdeckung seinen Ruf innerhalb der von Zwergen geführten Forscherliga festigt. Nach dem verheerenden Fall von Gnomeregan spüren viele Gnomenflüchtlinge in Ironforge einen enormen Druck, ihren zwergischen Gastgebern ihren Wert zu beweisen, und Geardawdle glaubt, dass die Entschlüsselung der uralten Geheimnisse des Brühschlamms allen zeigen wird, dass die Aufnahme der Gnome kein Fehler war."}},faq={{q="Woher stammt dieser Krug?",a="Er wird erhalten, indem ein Leerer verfluchter Brühschlammerkrug auf die Überreste eines besiegten Cursed Ooze in den verderbten Gefilden des Teufelswalds angewendet wird.",al={"woher bekommt man verfluchten brühschlammerkrug","gefüllter verfluchter brühschlammerkrug erhalten","brühschlammerkrug fundort"}},{q="Wer benötigt diese Brühschlammproben?",a="Laris Geardawdle, ein Gnomenforscher in der Hall of Explorers in Ironforge, bittet um sie, um seine naturgeschichtlichen Forschungen voranzutreiben.",al={"wer braucht brühschlammkrüge","laris geardawdle quest","wo brühschlammerkrug abgeben"}},{q="Warum erforscht Laris Geardawdle Brühschlämme?",a="Er bemerkte, dass sowohl die Natur als auch die Königliche Apothekervereinigung großes Interesse an Brühschlämmen zeigen. Er stellt die Hypothese auf, dass Schlämme uralte Sekrete sein könnten, die direkt mit der Entstehung und Entwicklung des Lebens auf Azeroth verbunden sind, benötigt jedoch physische Proben, um seine Theorien zu überprüfen.",al={"warum schlämme erforschen","geardawdle brühschlammtheorie","warum brühschlamm"}},{q="Warum liegt einem Gnomen die Forscherliga am Herzen?",a="Nach dem Fall von Gnomeregan fanden Gnomenflüchtlinge Zuflucht bei den Zwergen in Ironforge. Geardawdle hofft, dass ein bedeutender wissenschaftlicher Durchbruch durch die Forscherliga ihren Gastgebern beweisen wird, dass es die richtige Entscheidung war, den Gnomen Unterschlupf zu gewähren.",al={"warum forscherliga","gnome in ironforge"}}},fp="22,262,18.568.0,17.476.0,30.124.0,29.138.0,39.263.0,50.255.0"}
P.entries["item:filled-dreadmist-peak-sampler"] = {n="Gefüllte Glutnebelgipfelprobe",s="Die Gefüllte Glutnebelgipfelprobe ist eine Phiole mit verdorbenem Wasser, das aus den hochgelegenen Teichen auf der Spitze des Glutnebelgipfels im nördlichen Brachland geschöpft wurde. Von angehenden Druiden der Horde gesammelt, liefert sie die physischen Beweise, die der Zirkel des Cenarius benötigt, um eine abscheuliche Seuche zu untersuchen, die die Tierwelt der Region vergiftet.",h="Die Gefüllte Glutnebelgipfelprobe ist eine Phiole mit verdorbenem Wasser, das aus den hochgelegenen Teichen...",kw={"burning blade","zirkel des cenarius","glutnebelgipfel","druide","gefüllte glutnebelgipfelprobe","brachland","die eigentliche ursache","tonga runetotem"},ang={["class:Druid"]="Das Beschaffen dieser Probe ist ein wesentlicher Übergangsritus für Druiden der Horde, der sie lehrt, wie natürliche Wasserwege Verderbnis verbreiten, und sie darauf vorbereitet, heilende Magie zu meistern.",["faction:Horde"]="Die Untersuchung des Glutnebelgipfels offenbart die wachsende Bedrohung durch den Kult der Burning Blade mitten im Herzen des Territoriums der Horde im Brachland."},sec={{t="Eine verdorbene Quelle",b="Die steilen Klippen des Glutnebelgipfels beherbergen natürliche Teiche, deren Nebel historisch gesehen das Wetter und den Niederschlag im nördlichen Brachland prägen. Als der Dämonen anbetende Kult der Burning Blade seinen Zirkel auf dem Gipfel errichtete, verdarb das Wasser rasch. Da sie vermuten, dass dämonische Rituale die Dämpfe vergiftet haben, die die umliegende Savanne speisen, entsenden die Druiden von Cenarius Initianden, um mithilfe eines speziellen Probennehmers eine Probe zu entnehmen. Die übel riechende Flüssigkeit im Inneren bestätigt ihre schlimmsten Befürchtungen und zeugt von einer Verderbnis, die stark genug ist, um die darunter umherstreifenden Herden krank zu machen."},{t="Die Heilung der Savanne",b="Zu Tonga Runetotem im Crossroads gebracht, dient die abscheuliche Probe als Ausgangspunkt für die Entwicklung eines Gegenmittels. Während das Wasser die direkte Beteiligung der Burning Blade an der Verheerung der nördlichen Ebenen beweist, ermöglicht die Analyse seiner Eigenschaften dem Zirkel des Cenarius, das Wesen des Giftes zu verstehen. Indem sie die Verderbnis in dieser Phiole isolieren, entwickeln die Druiden die pflanzlichen Heilmittel, die erforderlich sind, um die Seuche aus sterbenden Gazellen auszutreiben und ihre eigene natürliche Macht über Gift zu meistern."}},faq={{q="Woher stammt diese Wasserprobe?",a="Die Probe wird aus einem Wasserbecken entnommen, das sich direkt auf dem Gipfel des Glutnebelgipfels befindet, einem schroffen Berg nordwestlich des Crossroads im Brachland.",al={"wo bekomme ich die probe","glutnebelgipfel probenort","wo fülle ich den probenehmer"}},{q="Warum ist das Wasser auf dem Glutnebelgipfel verdorben?",a="Der Kult der Burning Blade hat die Höhen des Glutnebelgipfels besetzt, um Dämonenanbetung und finstere Rituale zu praktizieren, wodurch die natürlichen Gewässer des Gipfels verdorben werden.",al={"warum ist das glutnebelwasser vergiftet","wer hat den glutnebelgipfel vergiftet","burning blade wasser"}},{q="Wer benötigt die gefüllte Probe?",a="Sie muss Tonga Runetotem überbracht werden, einem Druiden von Cenarius, der im Crossroads im Brachland stationiert ist und die plötzliche Krankheit untersucht, die die einheimische Tierwelt heimsucht.",al={"zu wem bringe ich die probe","tonga runetotem probe","glutnebelwasser abgeben"}},{q="Wie wirkt sich dieses vergiftete Wasser auf das Brachland aus?",a="Die luftigen Höhen und Teiche auf dem Glutnebelgipfel beeinflussen natürlicherweise die lokalen Wettermuster und den Nebel. Wenn sie vergiftet sind, legen sich die Dämpfe über die Savanne nördlich der Hauptstraße und verursachen weit verbreitete Krankheiten unter den einheimischen Gazellen.",al={"was bewirkt das wasser","kranke gazellen brachland","glutnebel nebeleffekt"}},{q="Wofür wird die Probe nach dem Einsammeln verwendet?",a="Tonga Runetotem analysiert die üble Flüssigkeit, um die genauen Eigenschaften der dämonischen Verderbnis zu entschlüsseln, und nutzt dieses Wissen, um eine heilsame Salbe zusammenzubrauen, mit der Druiden die befallenen Gazellen behandeln.",al={"was macht tonga damit","heilmittel gegen das gift","macht über gift erforschung"}}},fp="29,312,16.536.0,18.470.1,36.157.0,43.151.0,29.169.0,48.225.0,51.192.0"}
P.entries["item:filled-etched-phial"] = {n="Gefüllte geätzte Phiole",s="Eine Gefüllte geätzte Phiole ist ein kunstvolles Gefäß der Dryaden, gefüllt mit geweihtem Wasser, das direkt aus einem Mondbrunnen der Nachtelfen in Ashenvale geschöpft wurde. Von den Tauren aus Thunder Bluff angefordert, besitzt dieses geheiligte Wasser die seltene spirituelle Kraft, die nötig ist, um die ewige Flamme zu löschen, die ein heiliges Relikt der Zentauren schützt.",h="Eine Gefüllte geätzte Phiole ist ein kunstvolles Gefäß der Dryaden, gefüllt mit geweihtem Wasser, das direkt...",kw={"ashenvale","dryade","geätzte phiole","gefüllte geätzte phiole","galak","mondbrunnen","rau cliffrunner","tausend nadeln","zangen stonehoof"},ang={["race:NightElf"]="Nachtelfen betrachten den Diebstahl der Phiole einer Dryade und das Abschöpfen von Mondbrunnenwasser durch Agenten der Horde als einen unverzeihlichen Übergriff auf die heiligsten Refugien Ashenvales.",["race:Tauren"]="Für die Tauren ist die Sicherung dieses Wassers ein wohlüberlegter Schlag gegen die Galak-Zentauren, bei dem sie die gemeinsame Naturmagie der Kinder des Cenarius gegen ihre langjährigen Stammesfeinde wenden."},sec={{t="Mondbrunnenwasser und Dryadenhandwerk",b="Die Beschaffung dieser Phiole erfordert das Eindringen in das Territorium der Nachtelfen tief in Ashenvale. Das leere Gefäß muss zunächst von den Dryaden rund um Raynewood erbeutet werden, deren zarte Behälter dafür geschaffen sind, reine, stärkende Tränke zu fassen. Anschließend an einem heiligen Mondbrunnen nahe dem Westufer des Falfarren gefüllt, birgt die Phiole Wasser voller himmlischer, naturgebundener Macht. Für die Nachtelfen ist die ungeladene Entnahme dieses Wassers ein Akt unverhohlener Entweihung, doch die Tauren betrachten es als eine unverzichtbare Notwendigkeit, um einer regionalen Bedrohung weiter im Süden zu begegnen."},{t="Ein Schlüssel zur Zentaurenzauberei",b="Zangen Stonehoof und Rau Cliffrunner suchten nach genau diesem Wasser aufgrund der verborgenen mythischen Bande, die Dryaden und Zentauren miteinander verknüpfen. Beide Abstammungslinien führen ihr Erbe auf Cenarius zurück, was ihren magischen Traditionen eine tiefe, miteinander verwobene Resonanz verleiht. In Tausend Nadeln bewacht der Galak-Klan ein uraltes Relikt, das durch ein unnachgiebiges ewiges Feuer geschützt wird, welches bis auf die Erschaffung des Volkes der Zentauren zurückgeht. Wegen ihrer gemeinsamen urtümlichen Wurzeln ist das gesegnete Mondbrunnenwasser in dieser Dryadenphiole auf einzigartige Weise imstande, diese schützende Flamme zu durchdringen und zu löschen."}},faq={{q="Was befindet sich in der Gefüllten geätzten Phiole?",a="Sie enthält heiliges Wasser, das direkt aus einem Mondbrunnen der Nachtelfen in Ashenvale nahe dem Falfarren geschöpft wurde. Das Wasser befindet sich in einer kunstvollen Glasphiole, die von Dryaden nahe Raynewood erbeutet wurde.",al={"welches wasser ist in der phiole","womit ist die geätzte phiole gefüllt"}},{q="Warum brauchen die Tauren Mondbrunnenwasser?",a="Rau Cliffrunner benötigt das geheiligte Wasser, um eine ewige Schutzflamme zu durchbrechen, die von den Galak-Zentauren in Tausend Nadeln aufrechterhalten wird. Da Dryaden und Zentauren über Cenarius eine gemeinsame Abstammung teilen, ist das Mondbrunnenwasser darauf eingestimmt, den uralten Schutzbann um ihr Relikt aufzuheben.",al={"warum mondbrunnenwasser","warum braucht rau mondbrunnenwasser"}},{q="Woher stammt die leere Phiole?",a="Das Gefäß wird von Lachenden Schwestern getragen, jenen Dryaden, die durch die Wälder rund um Raynewood im zentralen Ashenvale streifen.",al={"wo finde ich die geätzte phiole","wie bekommt man die leere phiole"}},{q="Bei wem gibt man die Gefüllte geätzte Phiole ab?",a="Nachdem das Wasser geschöpft wurde, wird es zunächst zu Zangen Stonehoof auf die Anhöhe der Jäger in Thunder Bluff gebracht, der Euch dann anweist, es zu Rau Cliffrunner am Freiwindposten in Tausend Nadeln zu bringen.",al={"wer bekommt die phiole","phiole abgeben"}}},fp="19,303,31.568.0,24.563.1,39.197.0,38.279.0,37.126.0,46.200.0"}
P.entries["item:filled-jade-phial"] = {n="Gefüllte Jadephiole",s="Die Gefüllte Jadephiole enthält heiliges Wasser, das aus dem Mondbrunnen nahe Starbreeze geschöpft wurde. Nach Dolanaar zurückgebracht, dient sie als Teil eines fortlaufenden Rituals zur Wiederauffüllung der zentralen Gewässer der Hauptstadt, während junge Nachtelfen die Geschichte ihres Volkes erlernen.",h="Die Gefüllte Jadephiole enthält heiliges Wasser, das aus dem Mondbrunnen nahe Starbreeze geschöpft wurde.",kw={"corithras moonrage","krone der erde","dolanaar","gefüllte jadephiole","jadephiole","mondbrunnen","starbreeze","teldrassil"},ang={["class:Druid"]="Die Pflege der Mondbrunnen verbindet Druiden direkt mit der wiederherstellenden Magie, die Darnassus und die fortlaufenden Bemühungen des Zirkels des Cenarius zur Pflege des jungen Weltenbaums aufrechterhält.",["race:NightElf"]="Das Beschaffen des Wassers bekräftigt die heilige Pflicht junger Kaldorei gegenüber Teldrassil und vermittelt zugleich entscheidende Geschichte über den Verlust der Unsterblichkeit nach dem Hyjal."},sec={{t="Wasser von Starbreeze",b="Die Druiden von Darnassus verlassen sich auf heiliges Mondbrunnenwasser aus den gesamten Ästen von Teldrassil, um ihre zentralen Brunnen wieder aufzufüllen. Eigens gefertigte Gefäße wie die Jadephiole, die jungen Abenteurern von Corithras Moonrage in Dolanaar anvertraut wird, sind darauf eingestimmt, diese reinen Wasser sicher aufzubewahren. Indem sich die Initianden nach Osten zum Mondbrunnen außerhalb von Starbreeze wagen, sammeln sie das lebenswichtige Wasser und beweisen zugleich ihre Hingabe an den Erhalt des Weltenbaums."},{t="Eine Lektion in Geschichte",b="Die Gefüllte Jadephiole nach Dolanaar zurückzubringen, ist mehr als ein einfacher Botengang; jedes neu gefüllte Gefäß verdient ein weiteres Kapitel in der mündlichen Geschichte der Kaldorei. Nach Erhalt der vollen Phiole berichtet Corithras Moonrage von der verzweifelten Ära nach dem Dritten Krieg – dem Brennen von Nordrassil, dem Verlust der Unsterblichkeit der Nachtelfen, der Freilassung des Verräters und dem plötzlichen Verschwinden von Shan'do Malfurion Stormrage in den Smaragdgrünen Traum."}},faq={{q="Wo wird die Jadephiole gefüllt?",a="Die Jadephiole wird gefüllt, indem man mit dem heiligen Wasser des Mondbrunnens interagiert, der sich direkt außerhalb von Starbreeze östlich von Dolanaar auf Teldrassil befindet.",al={"wo fülle ich die jadephiole","gefüllte jadephiole bekommen","mondbrunnen starbreeze ort"}},{q="Wer benötigt die Gefüllte Jadephiole?",a="Corithras Moonrage, ein älterer Nachtelf, der in der Siedlung Dolanaar weilt, weist Reisende an, das Wasser als Teil der Ritualaufgaben für die Krone der Erde zu beschaffen.",al={"wer braucht die gefüllte jadephiole","corithras moonrage questgegenstand"}},{q="Warum wird Mondbrunnenwasser in Phiolen wie dieser gesammelt?",a="Die in Darnassus ansässigen Druiden müssen ihre primären Mondbrunnen regelmäßig wieder auffüllen. Sie verwenden eigens gefertigte Gefäße wie die Jadephiole, um unberührtes Wasser aus abgelegenen Brunnen auf ganz Teldrassil sicher zu transportieren.",al={"warum mondbrunnenwasser sammeln","wozu dient die jadephiole"}},{q="Welche Geschichte teilt Corithras bei der Abgabe mit?",a="Nach Erhalt der gefüllten Phiole schildert Corithras Moonrage die finsteren Nachwehen der Schlacht um den Hyjal und sinnt über den Verlust der Unsterblichkeit der Nachtelfen, die Freilassung von Illidan Stormrage und den rätselhaften Schlummer von Shan'do Malfurion Stormrage nach.",al={"was erzählt corithras","krone der erde lore"}}},fp="17,256,20.463.0,19.435.0,31.151.0,35.166.0,54.214.0,55.249.0"}
P.entries["item:filled-pure-sample-jar"] = {n="Gefüllter reiner Probenkrug",s="Ein Gefüllter reiner Probenkrug enthält eine unverdorbene Probe von urtümlichem Schleim, der in der abgelegenen Wildnis gesammelt wurde. Er dient dem Gnomengelehrten Laris Geardawdle in Ironforge als entscheidende Referenzbasis bei seinen Forschungen darüber, wie Umweltverderbnis lebende Materie verändert.",h="Ein Gefüllter reiner Probenkrug enthält eine unverdorbene Probe von urtümlichem Schleim, der in der...",kw={"gefüllter reiner probenkrug","klebriger schleim","ironforge","laris geardawdle","schlick","schleim","un'goro-krater"},ang={["faction:Alliance"]="Forscher der Allianz, die in extreme Gebiete wie den Un'Goro-Krater vordringen, liefern lebenswichtige naturgeschichtliche Daten an Gelehrte zurück, die sicher in Ironforge stationiert sind.",["race:Gnome"]="Gnomische Gelehrte betrachten die Feldbiologie durch eine streng empirische Brille; die Gegenüberstellung von kontaminierten Schleimen aus dem Teufelswald mit reinen Exemplaren aus Un'Goro veranschaulicht diese wissenschaftliche Standardmethode."},sec={{t="Die Suche nach unberührtem Schleim",b="Bei seinen Studien über die Schleime ganz Azeroths entdeckte der Gnomforscher Laris Geardawdle ein beunruhigendes Phänomen: Diese amorphen Kreaturen absorbieren und reflektieren die magische und ökologische Verderbnis ihres Lebensraums. Nachdem er die verseuchten Schleime im Teufelswald katalogisiert hatte, stellte Laris fest, dass die Entschlüsselung des Wesens dieser Fäulnis eine Kontrollgruppe erforderte. Ein Gefüllter reiner Probenkrug enthält Schleim, der aus unberührter, unverfälschter Wildnis geborgen wurde – wie etwa der urtümlichen Ökologie des Un'Goro-Kraters – und bietet Gelehrten ein unverändertes Exemplar zum Vergleich mit erkrankten und verdorbenen Stämmen."},{t="Urtümliche Ökologie",b="Da Schleime außergewöhnlich wandlungsfähige Organismen sind, können wahrhaft „reine“ Proben nicht in der Nähe moderner Zivilisation, dämonischer Seuchen oder nekromantischer Niederschläge gesammelt werden. Die klebrigen Schleime, die das ungezähmte Becken des Un'Goro-Kraters bewohnen, sind relativ isoliert von Verderbnis von außen geblieben, was sie zu einem idealen wissenschaftlichen Standard für die wissbegierigen Köpfe von Ironforge macht."}},faq={{q="Wer benötigt diese reinen Proben?",a="Laris Geardawdle, ein in Ironforge stationierter Gnomforscher, sucht nach diesen reinen Krügen, um seine laufenden Forschungen über Azeroths Schleimpopulationen fortzusetzen.",al={"laris geardawdle quest","wer braucht gefüllten reinen probenkrug","wer will die krüge"}},{q="Warum benötigt Laris reinen statt verdorbenen Schleim?",a="Laris erkannte, dass Schleime sich rasch anpassen und die Eigenschaften ihrer Umgebung absorbieren, wie etwa die dämonische Fäulnis im Teufelswald. Um das Ausmaß und den Mechanismus dieser Verderbnis zu verstehen, benötigt er unverdorbene Referenzproben für wissenschaftliche Vergleiche.",al={"warum reiner schleim","warum reine probe","zweck der schleimforschung"}},{q="Wo können reine Schleimproben gesammelt werden?",a="Reine Proben werden von den klebrigen Schleimen gesammelt, die die urtümliche Wildnis des Un'Goro-Kraters bewohnen, wo Flora und Fauna von äußeren Plagen isoliert geblieben sind.",al={"wo finde ich reinen schleim","fundort reiner probenkrug","wo reine krüge füllen"}},{q="Was geschieht, sobald die Proben in Ironforge abgeliefert werden?",a="Laris verwendet die Proben für Labortests zu Anpassung und Umweltresilienz und belohnt jene Abenteurer, die der gefährlichen Wildnis trotzen, um sie zu beschaffen.",al={"questbelohnung laris","was macht laris damit"}}},fp="22,263,30.573.0,18.354.0,29.145.0,54.263.0,41.172.0,57.157.0"}
P.entries["item:filled-red-waterskin"] = {n="Voller roter Wasserschlauch",s="Der Volle rote Wasserschlauch enthält unberührtes Quellwasser, das aus dem Dorfbrunnen in Tarrens Mühle geschöpft wurde. Das Sammeln dieses reinen Wassers inmitten der von den Verlassenen gehaltenen, verseuchten Ruinen dient als entscheidende Prüfung für junge Schamanen, die die Zwiesprache mit den Wassergeistern suchen.",h="Der Volle rote Wasserschlauch enthält unberührtes Quellwasser, das aus dem Dorfbrunnen in Tarrens Mühle...",kw={"brine","ruf des wassers","leerer roter wasserschlauch","voller roter wasserschlauch","sapta","schamane","tarrens mühle"},ang={["class:Shaman"]="Dieses Wasser bei sich zu tragen, stellt die Fähigkeit eines Schamanen auf die Probe, selbst in den verfallensten und traurigsten Winkeln der Welt das lebensspendende Gleichgewicht zu finden und zu ehren.",["faction:Horde"]="Der Besuch in Tarrens Mühle führt die jungen Champions aus Kalimdor mitten in den Kampf der Verlassenen gegen die Streitkräfte der Allianz in den Östlichen Königreichen."},sec={{t="Ein Leuchtfeuer in verseuchten Ländern",b="Während sie Schamanen in den Pfaden des Wassers unterweist, schickt die Einsiedlerin Brine im Brachland die Initianden auf eine weite Reise nach Tarrens Mühle im Vorgebirge von Hillsbrad. Inmitten des Verfalls und der Toten fördert der zentrale Brunnen der Stadt wie durch ein Wunder klares, unberührtes Quellwasser zutage. Brine betrachtet dieses heilige Relikt in einem unheiligen Land als Sinnbild eines unbezwingbaren Geistes – und zieht eine Parallele zwischen der unkorrumpierten Quelle und Kriegshäuptling Thralls unerschütterlicher Entschlossenheit trotz tiefen Leids. Das Beschaffen dieser Probe beweist die Ehrfurcht eines Initianden vor der Reinheit des Wassers ungeachtet einer feindseligen Umgebung."}},faq={{q="Was befindet sich im Vollen roten Wasserschlauch?",a="Er enthält reines, unkorrumpiertes Quellwasser, das direkt aus dem öffentlichen Brunnen im Zentrum von Tarrens Mühle geschöpft wurde.",al={"welches wasser ist darin","wasser aus tarrens mühle","inhalt roter wasserschlauch"}},{q="Warum möchte Brine Wasser aus Tarrens Mühle?",a="Brine hält die frische Quelle der Stadt für ein wundersames Zeugnis der Reinheit, das inmitten des Verfalls der Verlassenen überdauert hat. Sie benötigt diese heilige Probe als Zutat, um die für die Wasserprüfungen eines Schamanen erforderliche Sapta zu brauen.",al={"warum tarrens mühle","warum brine das braucht","zweck roter wasserschlauch"}},{q="Wie bleibt der Brunnen in einer untoten Stadt rein?",a="Die Quelle wird tief aus dem Untergrund gespeist und blieb von den Seuchen ringsum unberührt. Brine bemerkt, dass die Verlassenen, die Tarrens Mühle bewohnen, die Reinheit des heiligen Relikts in ihrer Mitte womöglich nicht einmal erkennen oder schätzen.",al={"warum der brunnen nicht verseucht ist","ist der brunnen in tarrens mühle vergiftet","heiliger brunnen tarrens mühle"}},{q="Welcher Bezug besteht in dieser Quest zu Thrall?",a="Brine vergleicht den reinen Brunnen, der in einer zerstörten Stadt überdauert, mit Thrall, der unermessliches Leid und Gefangenschaft ertrug und dennoch stark und unversehrt hervorging, um das Volk der Orcs durch finstere Zeiten zu führen.",al={"thrall vergleich","warum thrall erwähnt wird"}}},fp="20,255,26.577.0,40.108.0,43.206.0,47.218.0,37.191.0"}
P.entries["item:filled-tainted-ooze-jar"] = {n="Gefüllter besudelter Brühschlammerkrug",s="Ein Gefüllter besudelter Brühschlammerkrug enthält zähflüssigen, besudelten Brühschlamm, der direkt aus den Überresten von Brühschlammern geschöpft wurde, welche die verdorbenen Wälder von Teufelswald durchstreifen. In speziellen Auffangkrügen gesichert, werden diese Proben nach Ironforge gebracht, um radikale Theorien über den Ursprung des Lebens auf Azeroth zu stützen.",h="Ein Gefüllter besudelter Brühschlammerkrug enthält zähflüssigen, besudelten Brühschlamm, der direkt aus den...",kw={"forscherliga","teufelswald","ironforge","laris geardawdle","königliche apothekervereinigung","schleim","besudelter brühschlamm"},ang={["faction:Alliance"]="Späher der Allianz überwachen die Königliche Apothekervereinigung der Verlassenen genau; zu verstehen, warum Unterstadt kontinentübergreifend Schleim erntet, ist eine wichtige Aufklärungsaufgabe.",["race:Gnome"]="Für die in Ironforge lebenden Gnomengeflüchteten sind bahnbrechende wissenschaftliche Beiträge zur Forscherliga von entscheidender Bedeutung, um ihren Wert zu beweisen und die Gastfreundschaft der Zwerge nach der Tragödie von Gnomeregan zu vergelten."},sec={{t="Schleim des verdorbenen Waldes",b="Die besudelten Brühschlammer, die das nördliche Kalimdor durchstreifen, tragen die tiefe, anhaltende Verderbnis von Teufelswald in sich. Ihre Bergung erfordert eine sorgfältige Aufbewahrung in Krügen, die von Gnomenforschern bereitgestellt werden. Während die meisten Reisenden die giftigen Kreaturen gänzlich meiden, liefert das Sammeln dieser Proben seltenes Material für die Naturphilosophie und biologische Studien fernab der verheerten Wälder."},{t="Geardawdles große Theorie",b="Die Proben werden im Auftrag von Laris Geardawdle gesammelt, einem ehrgeizigen Gnomengelehrten, der bei der Forscherliga in Ironforge stationiert ist. Geardawdle ist fasziniert von der allgegenwärtigen Natur des Schleims und bemerkte, dass auch die Königliche Apothekervereinigung der Verlassenen ein reges Interesse an ihnen zeigt. Entgegen der gängigen akademischen Skepsis stellt er die Theorie auf, dass Schleime und Brühschlammer urtümliche Absonderungen sein könnten, die mit der eigentlichen Schöpfung von Azeroth selbst verknüpft sind. Die Sicherung dieser Proben ist sein Versuch, nach dem tragischen Fall von Gnomeregan sein Ansehen unter den Zwergengelehrten zu beweisen."}},faq={{q="Was befindet sich in einem Gefüllten besudelten Brühschlammerkrug?",a="Er enthält eine frische, gesicherte Probe aus den Überresten eines besiegten Tainted Ooze aus Teufelswald, versiegelt in einem Gnomen-Sammelkrug.",al={"was ist im krug","inhalt des besudelten brühschlammerkrugs","was ist besudelter brühschlamm"}},{q="Wer benötigt diese Brühschlammproben?",a="Laris Geardawdle, ein Gnomenforscher, der an der Seite der Forscherliga in der Hall of Explorers in Ironforge arbeitet, verlangt nach ihnen, um seine naturgeschichtlichen Studien voranzutreiben.",al={"wer nimmt den brühschlamm","laris geardawdle quest","wer sucht besudelten brühschlamm"}},{q="Warum erforscht Laris Geardawdle Brühschlammer?",a="Geardawdle beobachtete, wie die Königliche Apothekervereinigung Schleimproben sammelte, und war entschlossen, ihr Wesen als Erster zu ergründen. Er vertritt die unkonventionelle Theorie, dass Brühschlammer urtümliche Sekrete sind, die mit der Erschaffung Azeroths zusammenhängen, und hofft, damit seinen wissenschaftlichen Ruf in Ironforge zu festigen.",al={"warum schleim erforschen","geardawdle schleimtheorie","warum will der gnom brühschlamm"}},{q="Wo werden diese Proben gesammelt?",a="Sie werden in Teufelswald gesammelt, indem man Tainted Oozes besiegt und einen leeren Auffangkrug auf ihre Überreste anwendet.",al={"wo findet man besudelten brühschlamm","fundort besudelter brühschlammerkrug","wo fülle ich den krug"}}},fp="23,292,27.363.0,25.565.0,41.145.0,29.171.0,39.297.0,34.109.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Gefüllte Turmalinphiole",s="Die Gefüllte Turmalinphiole birgt verzaubertes Wasser, das aus dem Mondbrunnen an den Teichen von Arlithrien im südlichen Teldrassil geschöpft wurde. Auf Wunsch von Corithras Moonrage gesammelt, dient das Wasser dazu, die Gesundheit und das Gleichgewicht des wachsenden Weltenbaums zu überwachen.",h="Die Gefüllte Turmalinphiole birgt verzaubertes Wasser, das aus dem Mondbrunnen an den Teichen von Arlithrien...",kw={"corithras moonrage","krone der erde","gefüllte turmalinphiole","gnarlpine","mondbrunnen","teiche von arlithrien","teldrassil","turmalinphiole"},ang={["class:Druid"]="Für Druiden berührt das Tragen der Phiole unmittelbar das umstrittene Erbe von Erzdrude Fandral Staghelm, der das Pflanzen von Teldrassil während der unerklärlichen Abwesenheit von Shan'do Stormrage vorantrieb.",["race:NightElf"]="Das Wasser der Mondbrunnen stellt für die Kaldorei einen essenziellen spirituellen Lebensnerv dar, weshalb die Verderbnis der umliegenden Gnarlpine-Haine ein zutiefst beunruhigendes Omen für ihre neue Heimat ist."},sec={{t="Wasser von Arlithrien",b="Die Turmalinphiole wurde eigens dafür hergerichtet, Wasser aus dem Mondbrunnen zu schöpfen, der südöstlich der Straße nach Darnassus an den Ufern der Teiche von Arlithrien liegt. Das Schöpfen von Wasser an diesem Schrein ist durch die plötzliche Aggression der Gnarlpine-Furbolgs – einst friedliche Nachbarn, die rapide in gewaltsamen Wahnsinn verfielen – äußerst gefährlich geworden. Corithras Moonrage trägt Reisenden auf, den feindseligen Hainen zu trotzen und dieses Wasser zu beschaffen, um der sich vertiefenden Verderbnis auf den Grund zu gehen, die das Land erschüttert."},{t="Die Wurzeln von Teldrassil",b="Die Rückkehr mit der Phiole nach Dolanaar veranlasst Corithras Moonrage dazu, über den Ursprung der Äste hoch oben nachzudenken. Nach dem Verschwinden von Shan'do Malfurion Stormrage in den Smaragdgrünen Traum scharte Erzdrude Fandral Staghelm den Zirkel der Urahnen jenseits des Meeres an der Dunkelküste um sich, um Teldrassil in der Hoffnung zu pflanzen, ihre verlorene Unsterblichkeit zurückzuerlangen. Das in der edelsteinbesetzten Phiole getragene Wasser spiegelt den Zustand dieses heiligen Experiments wider – eine Ambition, die nun von einer unerklärlichen Krankheit heimgesucht wird, welche Tiere und Furbolgs gleichermaßen befällt."}},faq={{q="Wofür wird die Gefüllte Turmalinphiole verwendet?",a="Sie ist ein verzauberter Behälter mit Mondbrunnenwasser, das von Corithras Moonrage in Dolanaar angefordert wurde. Er sammelt Wasser aus Mondbrunnen in ganz Teldrassil, um die Ausbreitung der Verderbnis zu erforschen und neu eingetroffenen Verteidigern die Geschichte des Weltenbaums nahezubringen.",al={"gefüllte turmalinphiole verwendung","turmalinphiole zweck","warum phiole füllen"}},{q="Wo befindet sich der Mondbrunnen für die Turmalinphiole?",a="Der Mondbrunnen liegt südöstlich des Haupttors von Darnassus an den Ufern der Teiche von Arlithrien im südwestlichen Teldrassil. Das Gebiet ist von rasenden Gnarlpine-Furbolgs schwer umkämpft.",al={"wo fülle ich turmalinphiole","mondbrunnen teiche von arlithrien","arlithrien brunnen standort"}},{q="Warum greifen die Furbolgs in der Nähe des Mondbrunnens an?",a="Die Gnarlpine-Furbolgs, einst friedliche Bärenmenschen, die Seite an Seite mit den Nachtelfen lebten, sind einer schleichenden Verderbnis zum Opfer gefallen, die Teldrassil heimsucht. Ihr plötzlicher Abstieg in sinnlose Gewalt ist eines von mehreren Symptomen, die den jungen Weltenbaum plagen.",al={"warum gnarlpine verrückt","furbolg aggression arlithrien","rasende gnarlpine"}},{q="Wer ist Corithras Moonrage?",a="Corithras Moonrage ist ein Nachtelfengelehrter und Hüter, der in Dolanaar weilt. Er leitet junge Abenteurer durch den Ritus an, der als Krone der Erde bekannt ist, und unterweist sie in der Geschichte der Nachtelfen, dem Pflanzen von Teldrassil und dem Verschwinden von Malfurion Stormrage.",al={"corithras rolle","corithras dolanaar"}}},fp="23,279,20.507.0,23.526.1,45.246.0,55.206.0,49.247.0,26.278.0"}
P.entries["item:filled-vessel"] = {n="Gefülltes Gefäß",s="Das Gefüllte Gefäß enthält gereinigtes Wasser aus den verschiedenen heiligen Mondbrunnen auf ganz Teldrassil. Von Corithras Moonrage in Dolanaar Boten anvertraut, wird es zu Erzdruide Fandral Staghelm nach Darnassus gebracht, um ihm bei der Erforschung der Leiden des Weltenbaums zu helfen.",h="Das Gefüllte Gefäß enthält gereinigtes Wasser aus den verschiedenen heiligen Mondbrunnen auf ganz Teldrassil.",kw={"die enklave des cenarius","corithras moonrage","krone der erde","darnassus","fandral staghelm","gefülltes gefäß","mondbrunnenwasser","teldrassil"},ang={["class:Druid"]="Für cenarische Initianden stellt die Übergabe dieses Gefäßes ihren ersten offiziellen Botengang zu Erzdruide Fandral Staghelm dar und führt ihnen die ökologische Zerbrechlichkeit vor Augen, der Teldrassil ausgesetzt ist.",["race:NightElf"]="Das enthaltene Mondbrunnenwasser repräsentiert die heiligen Lebensadern der neuen Heimat der Kaldorei und verbindet die Magie von Elune mit dem ungewissen Wachstum des ungesegneten Weltenbaums."},sec={{t="Ein Zusammenfluss heiliger Wasser",b="Teldrassil wurde ohne den Segen der Großen Aspekte, Alexstrasza und Nozdormu, gepflanzt, wodurch seine gewaltigen Äste anfällig für unerwartete Verderbnis, seltsame Bestien und wahnsinnige Furbolgstämme wurden. Bei dem Versuch, die aufstrebenden Zweige zu überwachen und zu reinigen, werden Nachtelfenakolythen ausgesandt, um Wasserproben aus den über die Äste verteilten Mondbrunnen zu sammeln. Corithras Moonrage fasst diese gesammelten Phiolen in einem einzigen Gefüllten Gefäß zusammen und schickt es weiter in die Hauptstadt. Das Gemisch dient als lebenswichtige Probe von Teldrassils Vitalität für Erzdruide Fandral Staghelm, der in der Enklave des Cenarius unermüdlich daran arbeitet, ein Heilmittel für die allgegenwärtigen Makel des Großen Baumes zu finden."}},faq={{q="Was befindet sich im Gefüllten Gefäß?",a="Das Gefäß enthält Wasser aus mehreren über Teldrassil verteilten Mondbrunnen, das von Corithras Moonrage in Dolanaar in einem einzigen Behälter zusammengeführt wurde.",al={"inhalt des gefäßes","welches wasser ist das","was ist im gefäß"}},{q="Wer benötigt das Gefüllte Gefäß?",a="Das Gefüllte Gefäß wird zu Erzdruide Fandral Staghelm gebracht, der an der Spitze der Enklave des Cenarius in Darnassus weilt.",al={"wem gibt man das gefüllte gefäß","wohin gehört das gefäß","gefülltes gefäß abgeben"}},{q="Warum benötigt Fandral Staghelm diese Wasserproben?",a="Teldrassil fehlt der traditionelle Segen der Drachenaspekte, weshalb seltsame Verderbnis, aggressive Wildtiere und verrückte Furbolgs seine Äste plagen. Staghelm untersucht diese vermengten Wasser, um die Makel des Baumes zu diagnostizieren und nach einem Heilmittel für seine Leiden zu suchen.",al={"warum staghelm wasser will","staghelm mondbrunnenwasser zweck","warum mondbrunnenwasser sammeln"}},{q="Wer hat das Gefäß vorbereitet?",a="Corithras Moonrage, ein in Dolanaar stationierter Nachtelf, gießt die von jungen Abenteurern gesammelten Phiolen in das Gefäß, bevor er sie nach Darnassus entsendet.",al={"wer hat das gefüllte gefäß hergestellt","wer gibt das gefüllte gefäß","corithras gefülltes gefäß"}}},fp="13,265,29.675.0,33.159.0,28.121.0,51.256.0,24.155.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Final Clue to Sanders' Treasure",s="Der Final Clue to Sanders' Treasure ist eine mit Whiskey befleckte Notiz, die in einem alten Krug an der Küste von Westfall steckt. Sie enthält die abschließenden Wegbeschreibungen des verstorbenen Piraten Captain Sanders und führt Schatzsucher direkt auf das offene Meer hinaus, um seine vergrabene Beute zu bergen.",h="Der Final Clue to Sanders' Treasure ist eine mit Whiskey befleckte Notiz, die in einem alten Krug an der...",kw={"captain sanders","kiste","hinweis","pirat","schatz","westfall","whiskeykrug"},ang={["class:Rogue"]="Dem whiskeygetränkten Rätsel eines toten Piraten hinaus aufs offene Meer zu folgen, ist echtes Gaunerhandwerk – und beweist, dass die Küsten von Westfall mehr hergeben als nur die Taschen der Defias."},sec={{t="Die Abschiedsworte eines Seemanns",b="Dieses verschmierte Pergament, von dem ein schwerer Gestank nach Hochprozentigem ausgeht, markiert das Ende von Captain Sanders' verschlungener Fährte quer durch Westfall. Der verstorbene Freibeuter, bekannt dafür, kryptische Hinweise an der Küste zu hinterlassen, versteckte seine letzte Notiz tief in einem alten Whiskeykrug am Strand. Die Anweisungen sind grob, aber eindeutig: Reist vom Fundort der Flasche aus geradewegs nach Westen in die Meereswogen und trotzt der kalten Brandung, bis Ihr einen einsamen Felsen vor der Küste erreicht, wo seine eisenbeschlagene Seekiste auf Euch wartet."}},faq={{q="Was besagt der letzte Hinweis?",a="Trotz verlaufener Tinte und eines starken Whiskeygeruchs weist die Notiz den Leser an, sich vom Whiskeykrug aus nach Westen zu wenden, geradewegs ins Küstenwasser zu waten und nach Westen aufs Meer hinaus zu schwimmen, bis man eine kleine Insel vor der Küste erreicht, auf der die Schatztruhe versteckt liegt.",al={"hinweistext","was steht auf dem hinweis","sanders wegbeschreibung"}},{q="Wo wurde dieser Hinweis gefunden?",a="Der Hinweis steckte in einem alten Whiskeykrug nahe den westlichen Gestaden von Westfall, wo er als dritter Schritt in Captain Sanders' verstreuter Spur aus Hinweisen platziert worden war.",al={"wo finde ich den letzten hinweis","alter krug fundort","hinweis fundort"}},{q="Wer war Captain Sanders?",a="Captain Sanders war ein Seekapitän und Pirat, dessen Habseligkeiten und Schatzkarten an die Küste von Westfall gespült wurden. Obwohl Sanders selbst den Tod fand, hinterließ er eine Reihe versteckter Notizen und Markierungen im ganzen Land, die zu seinem Piratenhort führen.",al={"wer ist captain sanders","sanders piraten geschichte","wer hat den schatz versteckt"}},{q="Wohin führt dieser Hinweis letztendlich?",a="Die Notiz weist Euch an, von der Küste von Westfall aus nach Westen zu einer einsamen Insel im Ozean zu schwimmen, wo Captain Sanders' verrostete Seekiste mit seiner vergrabenen Beute ruht.",al={"wo ist die kiste","sanders insel","insel fundort"}}},fp="31,281,24.502.0,29.258.0,26.168.0,24.264.0,37.165.0"}
P.entries["item:fine-crab-chunks"] = {n="Feine Krebsbrocken",s="Feine Krebsbrocken sind erlesene Fleischstücke, die von den Küstenkrebstieren an den Stränden von Darkshore gesammelt werden. Sie werden wegen ihrer kulinarischen Vielseitigkeit hoch geschätzt und sind bei den örtlichen Küstenbewohnern sowie hungrigen Anglern begehrt, die damit eine endlose Vielfalt an Meeresfrüchtegerichten zubereiten möchten.",h="Feine Krebsbrocken sind erlesene Fleischstücke, die von den Küstenkrebstieren an den Stränden von Darkshore...",kw={"auberdine","krebs","darkshore","encrusted tide crawler","feine krebsbrocken","meeresfrüchte","gubber blump","reef crawler"},ang={["faction:Alliance"]="Die Versorgung der Bewohner an den Docks von Auberdine trägt dazu bei, den zerbrechlichen Außenposten der Allianz inmitten der düsteren Gefahren von Darkshore aufrechtzuerhalten.",["profession:Cooking"]="Jeder angehende Küstenkoch wird Gubber Blumps enzyklopädische Leidenschaft für Krebsfleisch zu schätzen wissen, die von Suppen, Salaten und Pfeffermischungen bis hin zu regionalen Köstlichkeiten wie der Ironforge-Überraschung reicht."},sec={{t="Meeresfrüchte",b="An den nebligen, zerklüfteten Küsten von Darkshore wimmelt es von umherhuschenden Krebstieren, insbesondere Reef Crawlers und Encrusted Tide Crawlers. Während viele Reisende diese gepanzerten Küstenstreuner als Schädlinge oder aggressive Gefahren an der Wasserlinie betrachten, halten geschäftstüchtige Feinschmecker ihr Fleisch für einen der erlesensten Schätze der Küste. Die von diesen Kreaturen gewonnenen, geschätzten Fleischstücke liefern reichhaltige, zarte Bissen, die sich für praktisch jede erdenkliche Zubereitungsart eignen – vom Kochen und Grillen bis hin zum Frittieren und für herzhafte Eintöpfe."}},faq={{q="Welche Kreaturen hinterlassen Feine Krebsbrocken?",a="Sie werden von den Reef Crawlers und Encrusted Tide Crawlers erbeutet, die an den felsigen Stränden und seichten Gezeitengewässern von Darkshore umherstreifen.",al={"wo droppen feine krebsbrocken","welche krebse droppen brocken","krebsfleisch quelle"}},{q="Wer sucht in Darkshore nach Feinen Krebsbrocken?",a="Gubber Blump, ein enthusiastischer Angler an den Docks von Auberdine, sucht nach diesen erlesenen Stücken. Als leidenschaftlicher Liebhaber von Meeresfrüchten schätzt er sie für ein ausgefeiltes Repertoire an hausgemachten Krebsgerichten.",al={"wer braucht feine krebsbrocken","bei wem krebsbrocken abgeben","gubber blump krebs"}},{q="Kann man daraus tatsächliche Mahlzeiten zubereiten?",a="Während diese speziellen rohen Stücke in erster Linie als gesammelter Proviant für Gubber Blump dienen und nicht als Zutat für direkte Herstellungsrezepte, gilt Krebsfleisch in der lokalen kulinarischen Tradition als bemerkenswert vielseitig – geeignet zum Backen, Grillen, Kochen, Braten, Frittieren und als Beigabe zu Salaten oder Eintöpfen.",al={"kann man feine krebsbrocken kochen","was kann man aus feinen krebsbrocken machen","krebsrezepte"}}},fp="16,281,16.516.0,38.136.0,40.202.0,40.296.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="Feiner Mondpirscherpelz",s="Ein Feiner Mondpirscherpelz ist der dicke, makellose Balg der ausgewachsensten räuberischen Mondpirscher, die die südliche Dunkelküste durchstreifen. Terenthis aus Auberdine nutzt diese geschätzten Felle, um einen verzauberten Umhang zu weben, der es Suchenden ermöglicht, unbemerkt an den feindseligen Bestien der Wälder vorbeizuschlüpfen.",h="Ein Feiner Mondpirscherpelz ist der dicke, makellose Balg der ausgewachsensten räuberischen Mondpirscher, die...",kw={"auberdine","darkshore","feiner mondpirscherpelz","matriarchin","mondpirscher","fürst","terenthis","volcor","der wildbend"},ang={["class:Hunter"]="Das Nachstellen der Fürsten und Matriarchinnen nahe dem Wildbend stellt die Fährtenlesekünste eines Jägers gegen einige der wildesten Raubtiere an den Küsten Kalimdors auf die Probe.",["race:NightElf"]="Nachtelfen respektieren die heilige Wildheit der Mondpirscher und nehmen ihre Felle nur aus äußerster Notwendigkeit, um gefallenen Verwandten wie Volcor beizustehen."},sec={{t="Häute der Rudelführer",b="Während gewöhnliche Mondpirscher durch die nebelverhangenen Wälder der Dunkelküste streifen, besitzen nur die älteren Mondpirscherfürsten und Mondpirschermatriarchinnen ein Fell, das dicht und gesund genug ist, um einen feinen Pelz abzuwerfen. Diese mächtigen Wildkatzen beanspruchen Reviere entlang des Wildbends und weiter südlich in Richtung der Grenzen von Ashenvale, wo sie mit tödlicher Geduld jagen."},{t="Ein Umhang der Täuschung",b="Das Sammeln dieser Felle ist keine bloße Trophäenjagd. Terenthis verlangt fünf intakte Pelze, um ein verzaubertes Gewand für Reisende herzustellen, die nach dem vermissten Nachtelfen Volcor suchen. Wenn sie gewebt und mit Naturmagie gebunden sind, formen die Pelze einen Umhang der Verschleierung, der seinen Träger in eine Illusion hüllt und seine Anwesenheit für die Tierwelt der Dunkelküste dämpft, solange aggressive Handlungen unterbleiben."}},faq={{q="Welche Kreaturen bringen einen Feinen Mondpirscherpelz hervor?",a="Nur die ausgewachsenen Anführer der Mondpirscherrudel werfen diese Pelze ab – namentlich Mondpirscherfürsten und Mondpirschermatriarchinnen. Jüngeren oder gewöhnlichen Mondpirschern fehlt die erforderliche Fellqualität.",al={"was droppt feinen mondpirscherpelz","wo gibt es mondpirscherpelz","welche katzen haben pelze"}},{q="Wo sind die ausgewachsenen Mondpirscher zu finden?",a="Diese gewaltigen Wildkatzen sind im Süden der Dunkelküste heimisch, insbesondere nahe den Ufern des Wildbends und weiter südlich entlang der Waldstraße in Richtung Ashenvale.",al={"wo sind die fürsten und matriarchinnen","mondpirscherfürst fundort","mondpirschermatriarchin fundort"}},{q="Warum benötigt Terenthis diese Pelze?",a="Terenthis verwendet fünf der Pelze, um einen verzauberten Umhang herzustellen. Dieser Umhang ist mit Magie erfüllt, die darauf ausgelegt ist, einen Retter vor raubtierhaften Bestien zu verbergen, während er nach dem vermissten Waldläufer Volcor sucht.",al={"wofür werden pelze gebraucht","warum mondpirscherpelze sammeln","terenthis pelz quest"}},{q="Macht Euch der fertige Umhang vollständig unsichtbar?",a="Der Umhang projiziert eine feine natürliche Illusion, die Bestien fernhält, doch sie ist zerbrechlich. Terenthis warnt davor, dass viel mehr als das Sprechen mit anderen die Verzauberung stören und die Tarnung auflösen wird.",al={"wie funktioniert der umhang","grenzen der umhangillusion","bricht umhang tarnung ab"}}},fp="21,275,25.348.0,20.387.1,45.191.0,43.172.0,36.192.0,54.197.0"}
P.entries["item:fire-tar"] = {n="Feuerteer",s="Feuerteer ist eine flüchtige Substanz, die von zauberwirkenden Stachelebern der Razormane im östlichen Brachland gesammelt wird. Für Schamanen der Horde dient er als entscheidende Ritualkomponente zum Brauen des Feuersaptas, das die spirituelle Zwiesprache mit dem Element des Feuers ermöglicht.",h="Feuerteer ist eine flüchtige Substanz, die von zauberwirkenden Stachelebern der Razormane im östlichen...",kw={"ruf des feuers","feuersapta","feuerteer","stacheleber","razormane","schamanen totem","telf joolam","brachland"},ang={["class:Shaman"]="Das Sammeln von Feuerteer markiert einen wesentlichen Übergangsritus, der Euch lehrt, in der weiten Welt nach elementarer Resonanz zu suchen, um das Feuersapta zu brauen und Euer Feuertotem zu verdienen.",["faction:Horde"]="Die Beschaffung von Feuerteer führt junge Abenteurer der Horde aus Durotar hinaus und über den Südstrom in das Brachland, wo sie sich den aggressiven Stämmen der Razormane stellen müssen."},sec={{t="Ein Gebräu der Borstennacken",b="Feuerteer wird fast ausschließlich von zaubernden Stachelebern der Razormane getragen – darunter ihre Geomanten, Mystiker und Dornweber – und ist eine alchemistische Substanz, die eng auf Flammen abgestimmt ist. Während die borstigen Stämme des Brachlands ihn für ihre eigene rohe Magie und Rituale verwenden, erkennen Schamanenlehrer darin ein unentbehrliches weltliches Reagenz, das die Kluft zwischen sterblichen Sinnen und reiner Elementarwut überbrücken kann."},{t="Der Weg zum Feuertotem",b="Wenn junge Schamanen der Orcs und Trolle zu Telf Joolam hoch oben in den Klippen von Durotar geschickt werden, tragen sie den Auftrag, ihr Feuertotem zu schmieden. Telf benötigt zwei Schlüsselelemente, die an Hitze und Flamme gebunden sind, um ein Feuersapta zu brauen: einen von Kultisten der Burning Blade erbeuteten Reagenzienbeutel und Feuerteer, der von den Razormane erlangt wurde. Das Trinken des fertigen Gebräus gestattet es dem Schamanen, den Schleier zu durchdringen und die elementaren Flammenspirits wahrzunehmen, die auf den nahen Gipfeln auf ihn warten."}},faq={{q="Wofür wird Feuerteer verwendet?",a="Feuerteer ist eine notwendige Ritualzutat, die dem Einsiedlerschamanen Telf Joolam in Durotar gebracht wird. Zusammen mit Reagenzien der Burning Blade wird er zu einem Feuersapta gebraut – einem Trank, der es einem Schamanen ermöglicht, Feuergeister zu sehen und Zwiesprache mit ihnen zu halten, um sein Feuertotem zu erlangen.",al={"feuerteer verwendung","was bewirkt feuerteer","wozu feuerteer"}},{q="Wer trägt Feuerteer bei sich?",a="Er wird von zauberwirkenden Stachelebern des Stammes der Razormane im östlichen Brachland getragen, wie etwa Geomanten, Mystikern, Dornwebern und Wassersuchern der Razormane.",al={"wer droppt feuerteer","feuerteer gegner","wo feuerteer bekommen"}},{q="Warum benötigen Schamanen Zutaten, die an feindliche Zauberwirker gebunden sind?",a="Saptas erfordern physische Komponenten, die tief mit dem entsprechenden Element durchdrungen sind. Da sowohl die Zauberwirker der Razormane als auch die Hexenmeister der Burning Blade intensive Hitze und zerstörerische Flammen kanalisieren, sind ihre alltäglichen Materialien bereits von jener feurigen Essenz erfüllt, die nötig ist, um die Elementarsicht eines Schamanen zu erwecken.",al={"warum stacheleber teer","warum hexenmeister und stacheleber"}},{q="Wo braut Telf Joolam das Feuersapta?",a="Telf Joolam weilt auf einer hohen Klippe über den Felsen von Durotar, nahe dem Pfad zwischen Klingenhügel und dem Brachland. Dort unterweist er Initianden darin, die zerstörerische und schöpferische Natur der Flamme im Gleichgewicht zu halten.",al={"wo ist telf joolam","feuerteer abgeben"}}},fp="8,250,32.406.0,26.454.0,26.269.0,21.157.0,61.300.0,43.207.0"}
P.entries["item:fizzle-s-claw"] = {n="Fizzles Klaue",s="Fizzles Klaue ist die abgetrennte Hand des Goblin-Hexenmeisters Fizzle Darkstorm. Sie stammt aus seinem Lager im Donnergrat und dient den Horde-Befehlshabern in Klingenhügel als physischer Beweis dafür, dass ein gefährlicher Verschwörer der Burning Blade getötet wurde.",h="Fizzles Klaue ist die abgetrennte Hand des Goblin-Hexenmeisters Fizzle Darkstorm.",kw={"burning blade","dunkle stürme","durotar","fizzle darkstorm","fizzles klaue","orgnil soulscar","klingenhügel","donnergrat"},ang={["class:Warlock"]="Fizzle Darkstorm nutzte die Teufelskünste im Dienste der subversiven Burning Blade und wandte seine dunklen Talente zur direkten Rebellion gegen die Horde an.",["faction:Horde"]="Das Überbringen von Fizzles Klaue nach Klingenhügel beweist die fortwährende Entschlossenheit, Durotar von den Schattenkulten zu reinigen, welche die fragile Sicherheit der jungen Nation gefährden."},sec={{t="Eine grausige Trophäe",b="Orgnil Soulscar, der beauftragt war, die die orkische Heimat bedrohenden Schattenkulte auszurotten, identifizierte Fizzle Darkstorm als einen Anstifter, der im Donnergrat Verderbnis verbreitete. Die Forderung nach Fizzles Klaue entsprang nicht bloßer Grausamkeit, sondern einer praktischen Notwendigkeit: Die Horde verlangt unumstößliche Beweise, wenn ein verdeckt operierender Hexenmeister unter dem Banner der Burning Blade eliminiert wird."},{t="Die Bedrohung im Donnergrat",b="Der Donnergrat war bereits durch unruhige Elemente erschüttert, was die Anwesenheit von Fizzles Kult zu einer unmittelbaren Gefahr für die umliegenden Gebiete machte. Indem Kundschafter der Horde die Klaue des Goblins abtrennten und nach Klingenhügel zurückbrachten, bestätigten sie, dass die Rituale des Hexenmeisters und seine Versuche, einen Stützpunkt für die Burning Blade zu errichten, vereitelt worden waren."}},faq={{q="Wem gehört diese Klaue?",a="Die Klaue gehörte Fizzle Darkstorm, einem tückischen Goblin-Hexenmeister, der mit dem als Burning Blade bekannten Schattenkult verbündet war.",al={"wer ist fizzle","fizzle darkstorm","besitzer der klaue"}},{q="Warum verlangt Orgnil Soulscar nach Fizzles Klaue?",a="Orgnil Soulscar benötigt einen endgültigen Beweis für Fizzles Tod. Da die Burning Blade aus den Schatten heraus operiert, bestätigt das Vorzeigen der Klaue des Goblin-Hexenmeisters, dass diese spezifische Bedrohung für Durotar dauerhaft beseitigt wurde.",al={"warum klaue benötigt","orgnil soulscar klaue","todesbeweis"}},{q="Wo wurde die Klaue gefunden?",a="Sie wird Fizzle Darkstorm in seinem versteckten Lager im Donnergrat abgenommen, einer Schlucht nordwestlich von Klingenhügel in Durotar.",al={"fizzles aufenthaltsort","wo ist fizzle","donnergrat klaue"}},{q="Was tut die Burning Blade in Durotar?",a="Die Burning Blade ist ein unheilvoller Kult, der versucht, die neue orkische Heimat durch dämonische Verderbnis, dunkle Zauberei und Unruhen zu untergraben. Hexenmeister wie Fizzle errichten versteckte Lager, um in der gesamten Region Chaos zu säen.",al={"burning blade durotar","warum kultisten im donnergrat"}}},fp="13,242,13.376.0,27.325.0,29.127.0,44.219.0,25.135.0,43.220.0"}
P.entries["item:flagongut-s-fossil"] = {n="Flagonguts Fossil",s="Flagonguts Fossil ist ein uraltes Fundstück, das aus den Ausgrabungsstätten des Sumpflands geborgen wurde. Der zwergischen Forscherliga anvertraut, birgt es verborgene Geheimnisse, die Archäologe Flagongut mithilfe eines geheimnisvollen Relikts namens Stein von Relu zu entschlüsseln versucht.",h="Flagonguts Fossil ist ein uraltes Fundstück, das aus den Ausgrabungsstätten des Sumpflands geborgen wurde.",kw={"ausgrabung","forscherliga","flagongut","fossil","relu","stein von relu","sumpfland","whelgar"},ang={["faction:Alliance"]="Die Sicherung von Artefakten aus Whelgars ruinierter Ausgrabungsstätte verhindert, dass wertvolle Geschichte von wilden Bestien zerstört oder von feindlichen Kräften im Moor geplündert wird.",["race:Dwarf"]="Für Zwergenforscher sind Fossilien wie das von Flagongut keine bloßen Kuriositäten; sie sind physische Verbindungen zur uralten Vergangenheit, deren Entdeckung sich die Forscherliga verschrieben hat."},sec={{t="Ausgrabung und Untersuchung",b="Dieses uralte Fossil wurde im Rahmen der Zwergenexpeditionen in Khaz Modan ausgegraben und stellt mehr als nur versteinertes Gestein dar. Archäologe Flagongut glaubt, dass es vergessene Mächte birgt, die mit der tiefen Urzeit der Welt verbunden sind – vergleichbar mit Artefakten, die jenseits des Meeres an der Dunkelküste gefunden wurden. Zur sicheren Verwahrung während regionaler Studien wurde das Fossil von Ausgrabungsleiter Whelgar an seiner Ausgrabungsstätte in den südlichen Hügeln des Sumpflands aufbewahrt."},{t="Das Relikt entschlüsseln",b="Als Flagongut den Stein von Relu entdeckte, erkannte er, dass dieser der Schlüssel zur Entschlüsselung der Geheimnisse des Fossils war. Ein Hinterhalt gescheckter Raptoren auf der Straße führte jedoch zum Verlust des Steins. Um das Fundstück endgültig zu entschlüsseln, benötigt Flagongut Abenteurer, die das Fossil aus Whelgars Ausgrabung bergen und den verschlungenen Stein von der Tierwelt des Sumpflands zurückholen."}},faq={{q="Was ist Flagonguts Fossil?",a="Es ist ein uraltes archäologisches Fundstück, das aus dem Sumpfland geborgen wurde und von der zwergischen Forscherliga untersucht wird, um Geheimnisse der fernen Vergangenheit der Welt aufzudecken.",al={"was ist das fossil","flagonguts fossil lore"}},{q="Wo befindet sich das Fossil?",a="Es befindet sich in der Höhle ganz oben in Whelgars Ausgrabungsstätte, eingebettet in die südlichen Berge des Sumpflands, bewacht von Raptoren und Schlämmen, die die Ausgrabung überrannt haben.",al={"fundort des fossils","wo ist flagonguts fossil","whelgars fossilhöhle"}},{q="Warum braucht Flagongut es zurück?",a="Flagongut glaubt, dass er zusammen mit dem Stein von Relu die verborgenen magischen Geheimnisse des Fossils entschlüsseln und dessen Natur mit ähnlichen Funden aus Kalimdor vergleichen kann.",al={"warum will flagongut es","was macht flagongut damit"}},{q="Wie hängt es mit der Dunkelküste zusammen?",a="Flagongut sieht eine Parallele zwischen diesem Fundstück aus dem Sumpfland und dem Fossil, das Ausgrabungsleiter Remtravel jenseits des Meeres an der Dunkelküste entdeckt hat, und glaubt, dass der Stein von Relu die Macht in beiden Relikten freisetzen könnte.",al={"verbindung zur dunkelküste","remtravels fossil"}}},fp="18,255,20.430.0,19.371.1,27.168.0,28.168.0,36.172.0,33.197.0"}
P.entries["item:flatland-cougar-femur"] = {n="Knochen eines Flachlandpumas",s="Ein Knochen eines Flachlandpumas ist ein dichter Oberschenkelknochen von den räuberischen Pumas, die durch das goldene Gras von Mulgore streifen. Er dient als lebenswichtiger Bestandteil eines traditionellen Volksheilmittels der Tauren, das gegen tödliche, giftige Infektionen eingesetzt wird.",h="Ein Knochen eines Flachlandpumas ist ein dichter Oberschenkelknochen von den räuberischen Pumas, die durch...",kw={"bloodhoof","knochen","flachlandpuma","maur raincaller","mazzranache","mulgore"},ang={["class:Hunter"]="Das Aufspüren von Flachlandpumas erfordert scharfe Augen im wiegenden Gestrüpp von Mulgore und stellt die Fähigkeit eines jungen Jägers auf die Probe, ein anderes Raubtier sauber zu erlegen.",["race:Tauren"]="Für die Tauren von Mulgore ist die Jagd auf den Flachlandpuma sowohl eine Prüfung der Wachsamkeit als auch eine Quelle lebenswichtiger Materialien für traditionelle Heilmittel der Ebenen."},sec={{t="Ein Heilmittel gegen einen giftigen Biss",b="Der Flachlandpuma ist einer der gefährlichsten einheimischen Lauerjäger Mulgores und verschmilzt nahtlos mit dem trockenen Gestrüpp, bis er sich auf ahnungslose Beute stürzt. Während Jäger Pumafelle und Klauen oft für die Lederverarbeitung und als Trophäen erbeuten, besitzen ihre schweren, markreichen Knochen einen praktischen Wert in der regionalen Medizin. Als Maur Raincaller, ein in Bloodhoof stationierter Schamane, eine giftige Wunde durch den monströsen rosafarbenen Schreiter Mazzranache erlitt, bat er dringend um einen Pumaknochen zusammen mit Teilen anderer einheimischer Bestien. Der Knochen wird zerkleinert oder ausgekocht, um seine wirksamen Eigenschaften zu extrahieren, wodurch ein Gegengift-Umschlag entsteht, der Fieber und nekrotisches Gift aus einem eiternden Biss ziehen kann."}},faq={{q="Wofür wird der Knochen eines Flachlandpumas verwendet?",a="Der Oberschenkelknochen wird von Maur Raincaller in Bloodhoof verwendet, um ein Notfallheilmittel zu brauen. Maur wurde von dem berüchtigten Ebenenschreiter Mazzranache gebissen und benötigt das Mark sowie den Knochen, um ein Gegengift herzustellen, bevor das bösartige Gift der Kreatur ihn tötet.",al={"pumaknochen verwendung","wozu dient dieser knochen","knochen quest"}},{q="Woher erhält man einen Knochen eines Flachlandpumas?",a="Er wird von Flachlandpumas erbeutet, die die zentralen und südlichen Ebenen von Mulgore durchstreifen; typischerweise findet man sie lauernd nahe den Hängen und umherstreifend im hohen Gras rund um Bloodhoof.",al={"wo knochen finden","pumaknochen fundort","welche mobs droppen ihn"}},{q="Warum benötigt Maur Raincaller ausgerechnet einen Pumaknochen?",a="Kräuterkundige und Schamanen der Tauren verwenden die dichten Knochen und das Mark von Raubtieren häufig in traditionellen Salben und Tinkturen. Man glaubt, dass die Stärke und Widerstandskraft der Spitzenprädatoren von Mulgore die notwendige regenerative Grundlage bieten, um wirksame Gifte zu neutralisieren.",al={"warum pumaknochen","warum oberschenkelknochen"}},{q="Wer ist Maur Raincaller?",a="Maur Raincaller ist ein Tauren-Bewohner von Bloodhoof. Nachdem er durch die Ebenen gewandert war, geriet er an Mazzranache, einen legendären Schreiter, gegen den einst schon sein Großvater gekämpft hatte, und entkam nur knapp mit einem infizierten, giftigen Biss in die Schulter.",al={"maur raincaller","wer braucht den knochen"}}},fp="21,232,28.686.0,43.246.0,44.189.0,58.283.0,23.232.0"}
P.entries["item:flatland-prowler-claw"] = {n="Flachlandstreunerklauen",s="Flachlandstreunerklauen werden von den gefährlichen Katzenraubtieren erbeutet, die durch die grasbewachsenen Ebenen von Mulgore streifen. Für angehende Jäger dient das Sammeln dieser Klauen als traditioneller Übergangsritus, um den Ältesten von Thunder Bluff List und kriegerische Entschlossenheit zu beweisen.",h="Flachlandstreunerklauen werden von den gefährlichen Katzenraubtieren erbeutet, die durch die grasbewachsenen...",kw={"flachlandstreuner","flachlandstreunerklauen","die anhöhe der jäger","melor stonehoof","mulgore","skorn whitecloud","der weg der jäger","thunder bluff"},ang={["class:Hunter"]="Das Erlegen heimlichtuerischer Streuner stellt die Aufmerksamkeit eines Jägers im Feld auf die Probe, was diese Klauen zu einem Symbol verdienten Respekts unter den Schützen macht, die sich auf der Anhöhe der Jäger in Thunder Bluff versammelt haben.",["race:Tauren"]="Für die Tauren ist die Jagd eine ehrenhafte spirituelle Tradition, und das Vorzeigen der Klauen eines gerissenen Raubtiers der Ebenen markiert die ersten Schritte eines Initiierten auf dem Weg, dem Stamm als Fährtenleser zu dienen."},sec={{t="Der Beweis eines Jägers",b="Flachlandstreuner gehören zu den gerissensten und territorialsten Raubtieren, welche die windgepeitschten Ebenen von Mulgore durchstreifen. Flink auf den Pfoten und geschickt darin, ihrer Beute im hohen Gras aufzulauern, stellen sie eine echte Bedrohung für Reisende und eine würdige Prüfung für junge Jäger dar. Ihre scharfen Klauen zu sammeln ist nicht bloß eine Aufgabe des Überlebens, sondern eine anerkannte Tradition. Skorn Whitecloud rät vielversprechenden Wanderern, diese Trophäen zu erbeuten und sie Melor Stonehoof auf der Anhöhe der Jäger in Thunder Bluff zu überbringen, um zu beweisen, dass sie die Entschlossenheit und das Naturgeschick besitzen, um den Weg der Jäger zu beschreiten."}},faq={{q="Wofür werden Flachlandstreunerklauen verwendet?",a="Sie dienen als handfester Beweis für Geschick und Mut. Junge Jäger bringen vier dieser Klauen zu Melor Stonehoof auf der Anhöhe der Jäger in Thunder Bluff, um ihre Bereitschaft zu beweisen, den Weg des Jägers zu beschreiten.",al={"streunerklauen nutzen","warum streunerklauen sammeln","der weg der jäger klauen"}},{q="Wer bittet Euch darum, sie zu sammeln?",a="Der ältere Jäger Skorn Whitecloud weist vielversprechende Fährtenleser an, Klauen von den Streunern Mulgores als Beweis zu sammeln, ehe sie vor Melor Stonehoof treten.",al={"wer will streunerklauen","questgeber streunerklauen"}},{q="Warum gelten Flachlandstreuner als angemessene Jagdbeute?",a="Flachlandstreuner sind zähe, heimlichtuerische und gerissene Fleischfresser, die in den Ebenen von Mulgore heimisch sind. Das erfolgreiche Aufspüren und Bezwingen solch wachsamer Raubtiere beweist, dass ein angehender Jäger die Geduld und die Kampfinstinkte besitzt, die nach der Tradition der Tauren verlangt werden.",al={"warum flachlandstreuner","sind streuner gefährlich"}}},fp="21,268,16.571.0,41.207.0,29.178.0,52.245.0"}
P.entries["item:foam-sword-rack-common"] = {n="Foam Sword Rack (common)",s="Ein Foam Sword Rack ist eine verspielte Sammlung harmloser Spielzeugwaffen, die während der Kinderwoche als Abschiedsgeschenk erworben wird. Es wird von umherziehenden Spielzeughändlern in Stormwind oder Orgrimmar bezogen und ermöglicht es einem ganzen Waisenhaus voller kriegsversehrter Kinder, an der Freude ausgelassener Raufereien teilzuhaben.",h="Ein Foam Sword Rack ist eine verspielte Sammlung harmloser Spielzeugwaffen, die während der Kinderwoche als...",kw={"battlewail","blax bottlerocket","kinderwoche","craggle wobbletop","foam sword rack","grunth","nightingale","randis"},ang={["faction:Alliance"]="In Stormwind von Craggle Wobbletop erworben, bringt das Gestell den Kriegswaisen des Kathedralenbezirks einen Moment unbeschwerter Heiterkeit und erntet großes Lob von Matrone Nightingale.",["faction:Horde"]="In der Gasse von Blax Bottlerocket bezogen, ermöglichen die Schaumstoffklingen den Jungen von Orgrimmar, ihren Kampfgeist in harmlosem Spiel zu üben, und bringen den Segen der Geister von Matrone Battlewail ein."},sec={{t="Ein Abschiedsgeschenk für das Waisenhaus",b="Während der Feierlichkeiten der Kinderwoche nehmen Abenteurer Waisenkinder unter ihre Fittiche, um ihnen die Wunder und Wahrzeichen der Welt zu zeigen. Am Ende dieser Reise bitten sowohl das Menschenwaisenkind Randis in Stormwind als auch das Orkwaisenkind Grunth in Orgrimmar vor der Heimkehr um einen letzten Gefallen: ein Foam Sword Rack. Anstatt nur für sich selbst ein Andenken zu suchen, möchte jedes Kind genügend Spielzeug mitbringen, damit jeder andere Junge und jedes Mädchen in der Obhut des Waisenhauses am Vergnügen teilhaben kann."},{t="Umherziehende Spielzeugmacher",b="Die Spielzeugschwertständer werden von umherziehenden Scherzartikelhändlern geführt und verkauft, die ihre hölzernen Karren durch die Straßen der Hauptstädte schieben. In Stormwind machen Abenteurer den Gnomen Craggle Wobbletop ausfindig, während er an den an den Trade District grenzenden Kanälen umherwandert. In Orgrimmar liefert der Goblin Blax Bottlerocket das Gestell, der seine Waren in der staubigen Schlucht der Gasse anpreist. Die Übergabe des Geschenks an Waisenmatrone Nightingale oder Waisenmatrone Battlewail löst sogleich eine Welle spielerischer Gefechte aus, während die Kinder mit Schaumstoffklingen in den Händen nach draußen stürmen."}},faq={{q="Wofür wird das Foam Sword Rack verwendet?",a="Es dient als letzte Questabgabe während der Kinderwoche. Nachdem Ihr ein Waisenkind durch die Welt begleitet habt, kauft Ihr dieses Gestell, damit es allen anderen im Waisenhaus lebenden Kindern ein gemeinsames Geschenk mitbringen kann.",al={"foam sword rack zweck","was bewirkt das foam sword rack"}},{q="Wo können Allianzspieler das Foam Sword Rack finden?",a="Allianzhelden kaufen es in Stormwind von Craggle Wobbletop, einem exzentrischen Gnomen, der seinen Spielzeugkarren an den Kanälen direkt außerhalb des Trade District entlangschiebt.",al={"foam sword rack stormwind kaufen","craggle wobbletop aufenthaltsort"}},{q="Wo erhalten Hordespieler das Foam Sword Rack?",a="Hordeabenteurer erwerben es in Orgrimmar von Blax Bottlerocket, einem Goblin-Hausierer, der seinen Kuriositätenkarren die Hauptstraße in der Gasse auf und ab schiebt.",al={"foam sword rack orgrimmar kaufen","blax bottlerocket aufenthaltsort"}},{q="Wer erhält das Gestell bei der Abgabe?",a="In Stormwind wird es zusammen mit dem Waisenkind Randis zu Waisenmatrone Nightingale im Kathedralenbezirk gebracht. In Orgrimmar wird es zusammen mit dem Waisenkind Grunth zu Waisenmatrone Battlewail in der Gasse gebracht.",al={"wem gebe ich den schwertständer","foam sword rack abgabe"}},{q="Was geschieht, nachdem das Gestell abgegeben wurde?",a="Nach Abgabe des Gestells nimmt die Matrone es dankbar entgegen und ruft die Kinder herbei. Aufgeregte Waisenkinder strömen von drinnen und draußen herbei, um sich Spielzeugklingen zu schnappen und sich auf der Straße begeistert miteinander zu duellieren.",al={"schwertständer event","was machen waisenkinder mit schaumstoffschwertern"}}},fp="24,287,32.505.0,19.547.0,37.218.0,52.157.0,50.152.0,42.210.0,41.236.0"}
P.entries["item:foreman-s-blackjack"] = {n="Großknecht-Totschläger",s="Der Großknecht-Totschläger ist ein schwerer, lederumwickelter Knüppel, der an frische Rekruten der Horde im Tal der Prüfungen verliehen wird. Vorarbeiter geben ihn als alltägliches Disziplinierungswerkzeug weiter, um schlummernde Peons zu wecken und das zermürbende Tempo beim frühen Aufbau von Durotar durchzusetzen.",h="Der Großknecht-Totschläger ist ein schwerer, lederumwickelter Knüppel, der an frische Rekruten der Horde im...",kw={"totschläger","durotar","großknecht-totschläger","faule peons","peon","thazzril","das tal der prüfungen"},ang={["faction:Horde"]="Der Totschläger verdeutlicht den unerbittlichen praktischen Einsatz, der nötig ist, um Durotar zu zähmen, wo die Besiedlung eines rauen Landes von jedem Arbeiter verlangt, ohne Unterlass zu schuften.",["race:Orc"]="Für junge Orcs, die das Tal der Prüfungen betreten, bietet das Führen des Totschlägers eine frühe Lektion in der Hierarchie der Horde: Wer weder die Stärke noch den Geist eines Kriegers besitzt, wird zur Arbeit degradiert und mit Gewalt auf Linie gehalten."},sec={{t="Ein Werkzeug orkischer Arbeit",b="Der Aufbau einer neuen Heimat in der rauen Wüste von Durotar erfordert gewaltige Holzvorräte, und die Arbeit lastet voll und ganz auf den Schultern der Peons der Horde. Im Tal der Prüfungen verlässt sich Großknecht Thazz'ril auf den Großknecht-Totschläger, um die Arbeitskolonnen in Bewegung zu halten. Anstatt tödliche Hiebe auszuteilen, ist dieser beschwerte Prügel dafür gedacht, Arbeitern, die beim Schläfchen unter den Schattenbäumen des Tals erwischt werden, einen unsanften Weckruf zu verpassen. Er dient als deutliche Erinnerung an das Leben der Peons in der neuen Horde: zermürbend, glanzlos und mit eiserner Faust beaufsichtigt."}},faq={{q="Wofür wird der Großknecht-Totschläger verwendet?",a="Aufseher übergeben den Totschläger an junge Abenteurer, um schlafende Peons im gesamten Tal der Prüfungen zu disziplinieren. Ein Schlag auf einen schlummernden Peon schreckt ihn auf und schickt ihn direkt zurück ans Holzfällen und Schleppen.",al={"totschläger verwendung","warum totschläger nutzen","peon-knüppel"}},{q="Wem gehört dieser Totschläger?",a="Er gehört Großknecht Thazz'ril, dem im Tal der Prüfungen stationierten Arbeitsaufseher, der die Beschaffung von Rohholz für die junge Orc-Siedlung überwacht.",al={"wer gibt totschläger","großknecht totschläger besitzer"}},{q="Warum schlafen die Peons bei der Arbeit ständig ein?",a="Orkische Peons leisten unerbittliche, erschöpfende Schichten beim Holzsammeln unter der sengenden Sonne von Durotar. Wann immer sie im spärlichen Schatten der Bäume des Tals Schutz finden, überwältigt sie die Erschöpfung, was zu häufigen unerlaubten Nickerchen führt.",al={"warum sind peons faul","faule peons schlafen"}},{q="Kann ich den Totschläger nach Abschluss der Aufgabe behalten?",a="Nein. Der Aufseher verlangt die unverzügliche Rückgabe des Werkzeugs, sobald die Drückeberger diszipliniert wurden, damit es künftigen Vorarbeitern zur Durchsetzung der Arbeitsquoten griffbereit bleibt.",al={"totschläger behalten","kann man großknecht totschläger behalten"}}},fp="19,261,22.544.0,41.211.0,24.159.0,48.220.0,50.174.0"}
P.entries["item:forged-steel-bars"] = {n="Schmiedestahlbarren",s="Schmiedestahlbarren sind veredelte Metallbarren, die dem Orcschmied Thun'grim Firegaze gehören. Sie wurden bei einem nächtlichen Überfall von opportunistischen Stachelebern der Razormane gestohlen und dienen als Beweis für die Entschlossenheit eines Kriegers, gestohlenes Eigentum im Brachland wiederzubeschaffen.",h="Schmiedestahlbarren sind veredelte Metallbarren, die dem Orcschmied Thun'grim Firegaze gehören.",kw={"brachland","geschmiedeter stahl","schmiedestahlbarren","eisentruhe","razormane","gestohlene eisentruhe","thun'grim firegaze"},ang={["class:Warrior"]="Die Wiederbeschaffung von Thun'grims gestohlenem Stahl beweist die Fähigkeit eines Kriegers, Diebe aufzuspüren und sich gefährlichen Stacheleberrudeln zu stellen – im Tausch gegen maßgefertigte Waffen.",["profession:Blacksmithing"]="Die veredelten Barren verdeutlichen den Unterschied zwischen rohem Schrottmetall der Wilden und dem Qualitätsstahl, der von ausgebildeten Schmieden der Horde gefertigt wird."},sec={{t="Gestohlenes Metall",b="Schmiedestahlbarren stellen hochwertigen Schmiedebedarf dar, der dem sehbehinderten Orcschmied Thun'grim Firegaze gehört, welcher ein Lager im nördlichen Brachland unterhält. Die örtlichen Razormane-Stacheleber machten sich Thun'grims nachlassendes Augenlicht zunutze und lenkten den Schmied mit Grunzen und Schnauben ab, während Diebe mit einer Eisentruhe voller Barren entkamen. Da die Stacheleber keine Erfahrung in der Verarbeitung von feinem Stahl besitzen, ließen sie den ungeöffneten Behälter bei einem zerstörten Wagen in ihrem Lager im Nordwesten zurück, sodass die Barren unversehrt blieben und von wiederbeschaffenden Kriegern geborgen werden können."}},faq={{q="Wem gehören diese Schmiedestahlbarren?",a="Sie gehören Thun'grim Firegaze, einem orcischen Rüstungs- und Waffenschmied, der in einem Lager im nördlichen Brachland lebt.",al={"wem gehören die barren","thungrim stahl","wessen stahl ist das"}},{q="Warum haben die Stacheleber sie gestohlen?",a="Die Razormane-Stacheleber überfielen Thun'grims Lager schlichtweg, um seine Wertsachen zu plündern. Da sie wussten, dass der Schmied unter schlechten Augen litt, verhöhnten und lenkten sie ihn ab, während andere Stammesmitglieder sich mit seiner Eisentruhe davonmachten.",al={"warum stahl stehlen","stacheleber motiv","razormane diebstahl"}},{q="Haben die Stacheleber den Stahl verwendet?",a="Nein. Wie von Thun'grim erwartet, fehlte den Razormane das metallurgische Wissen und das handwerkliche Geschick, um solch fein veredelten Stahl zu bearbeiten. Die Truhe blieb verschlossen und wurde neben einem kaputten Wagen in ihrem Lager zurückgelassen.",al={"haben stacheleber etwas geschmiedet","was machten stacheleber mit stahl"}},{q="Was bietet Thun'grim als Gegenleistung dafür an?",a="Als Gegenleistung dafür, den Lagern der Stacheleber zu trotzen und alle Barren zurückzubringen, belohnt Thun'grim aufstrebende Krieger mit einer handgefertigten Waffe.",al={"geschmiedeter stahl belohnung","was erhalte ich für den stahl"}}},fp="17,244,12.557.0,33.107.0,32.214.0,31.198.0,45.129.0"}
P.entries["item:fragments-of-rok-alim"] = {n="Fragmente von Rok'Alim",s="Fragmente von Rok'Alim sind die zerschmetterten steinernen Überreste eines urzeitlichen Erdelementars, der durch die Schluchten von Tausend Nadeln streift. Zu Dorn Plainstalker im Wetterwinkel gebracht, dienen sie als unbestreitbarer physischer Beweis dafür, dass ein Krieger einen uralten Schrecken im Zweikampf bezwungen hat.",h="Fragmente von Rok'Alim sind die zerschmetterten steinernen Überreste eines urzeitlichen Erdelementars, der...",kw={"dorn plainstalker","elementar","fragmente","zermalmer","rok'alim","test of strength","tausend nadeln","der wetterwinkel"},ang={["class:Shaman"]="Rok'Alim stellt einen uralten Erdgeist dar, der lange vor modernen schamanischen Bündnissen an die Welt gebunden war, was seine unnachgiebige Natur zu einer faszinierenden Studie über rohe elementare Zähigkeit macht.",["race:Tauren"]="Das Bezwingen fortdauernder Überreste von Azeroths Urvergangenheit steht in engem Einklang mit den Traditionen der Tauren, Harmonie, Standhaftigkeit und persönliche Stärke an den gewaltigsten Gefahren des Landes zu messen."},sec={{t="Überreste einer uralten Macht",b="Während die meisten Elementare nach der Verbannung der Alten Götter von Azeroth schwanden, besaß eine Handvoll genügend rohe Macht, um ohne Beschwörung durch sterbliche Magie auf der Oberfläche zu verweilen. Rok'Alim der Zermalmer ist ein solcher Überlebender, der durch die Schluchten südlich der Hauptverkehrsstraße streift. Die einheimischen Zentauren kennen ihn durch das donnernde Krachen seiner steinernen Fäuste, die alles zermalmen, was törichterweise seinen Weg kreuzt. Das Niederschlagen dieses lebenden Relikts der Urwelt hinterlässt gezackte Stücke aus dichtem, belebtem Gestein – eine Trophäe, die geeignet ist, unübertroffene körperliche Stärke zu beweisen."},{t="Die Prüfung der Stärke",b="Für den Tauren-Einsiedler Dorn Plainstalker ist die Bergung der Fragmente der entscheidende Bestandteil der Test of Strength. Als Teil einer Reihe spiritueller und kriegerischer Riten hoch oben im Wetterwinkel verlangt die Prüfung von einem Initianden, sich einem Wesen unnachgiebiger roher Gewalt zu stellen. Das Überbringen der zerschlagenen Trümmer von Rok'Alim beweist, dass ein Abenteurer den Mut und die körperliche Stärke besitzt, um die härtesten Gefahren von Kalimdor zu überstehen."}},faq={{q="Was sind die Fragmente von Rok'Alim?",a="Sie sind die zerbrochenen steinernen Überreste von Rok'Alim dem Zermalmer, einem uralten Erdelementar, der die nordwestlichen Schluchten von Tausend Nadeln unsicher macht. Sie dienen als Beweis für den Sieg über den Elementar.",al={"fragmente von rokalim","was sind fragmente von rokalim","rokalims stein"}},{q="Wer benötigt diese Steinfragmente?",a="Dorn Plainstalker, ein Tauren-Questgeber, der im Wetterwinkel hoch an den Klippen von Tausend Nadeln lebt, verlangt die Fragmente zum Abschluss der Test of Strength.",al={"wer nimmt fragmente von rokalim","fragmente von rokalim abgeben","dorn plainstalker quest"}},{q="Warum ist Rok'Alim von Bedeutung?",a="Anders als die meisten modernen Elementare, die von sterblichen Magiern herbeigerufen werden müssen, verweilt Rok'Alim seit der Ära der Alten Götter in der Welt. Die Zentaurenstämme in den Schluchten gaben ihm den Beinamen „der Zermalmer“ wegen des dröhnenden Lärms seiner Fäuste, wenn er seine Beute zermalmt.",al={"warum ist rokalim besonders","rokalim hintergrundgeschichte","wer ist rokalim der zermalmer"}},{q="Wo ist Rok'Alim zu finden?",a="Rok'Alim durchstreift das nordwestliche Becken von Tausend Nadeln und wandert südlich der Hauptstraße der Region zwischen den Sandsteinnadeln umher.",al={"rokalim standort","rokalim der zermalmer finden","wo spawnt rokalim"}}},fp="21,278,28.570.0,18.449.0,35.188.0,32.176.0,28.253.0,24.131.0"}
P.entries["item:frostwolf-banner"] = {n="Banner der Frostwolf",s="Das Banner der Frostwolf ist eine Stammesstandarte, die tief in der Höhle der Wildpfoten im Alteractal versteckt ist. Initianden der Horde werden ausgesandt, sie als uralten Initiationsritus zu bergen, um ihren Kampfgeist zu wecken und ihr erstes Klanabzeichen zu erlangen.",h="Das Banner der Frostwolf ist eine Stammesstandarte, die tief in der Höhle der Wildpfoten im Alteractal...",kw={"alteractal","banner der frostwolf","gnolle","insignie","flaggenjagd","kriegsmeister laggrond","höhle der wildpfoten"},ang={["faction:Horde"]="Die Bergung dieses Banners markiert die offizielle Feuertaufe und Aufnahme eines Kriegers in den legendären Frostwolfklan unter Kriegsmeister Laggrond.",["race:Orc"]="Für Orcs ehrt die Rückholung einer verlorenen Klanstandarte von wilden Gnollen das Erbe von Frostfeuer und Thralls angestammtes Erbe im Alteracgebirge."},sec={{t="Ein Initiationsritus",b="Für Krieger der Horde, die im Alteractal eintreffen, beginnt die Erlangung echten Ansehens beim Frostwolfklan mit einer Härteprüfung. Kriegsmeister Laggrond schickt neue Rekruten nach Süden in die feuchten, feindseligen Gänge der Höhle der Wildpfoten, eine von territorialen Gnollen wimmelnde Höhle. Das in ihren Tiefen verborgene Banner zu erreichen und unversehrt zurückzubringen, beweist Mut, zeigt, dass der Kampfrausch des Kriegers erwacht ist, und bringt ihm das Abzeichen des Frostwolf-Initianden ein."}},faq={{q="Warum befindet sich das Banner der Frostwolf in einer Gnollhöhle?",a="Kriegsmeister Laggrond und der Klan nutzen den Standort des Banners in der Höhle der Wildpfoten ganz gezielt als Initiationstest. Der Vorstoß in das Territorium der Gnolle zwingt neue Kämpfer dazu, jede Selbstgefälligkeit abzuschütteln, sich der Gefahr zu stellen und ihren Kampfgeist zu wecken.",al={"warum ist das banner in wildpfoten","gnolle haben banner","banner der frostwolf fundort"}},{q="Bei wem gebe ich das Banner der Frostwolf ab?",a="Das Banner muss zu Kriegsmeister Laggrond im Alteractal zurückgebracht werden. Ihm das Banner zu überreichen, heißt einen Initianden feierlich in den Reihen der Frostwölfe willkommen und bringt ein Abzeichen des Ansehens ein.",al={"wer will das banner der frostwolf","banner quest abgeben","laggrond banner"}},{q="Warum sieht die Standarte für ein Wappen der Frostwölfe ungewöhnlich aus?",a="Obwohl sie von Laggrond als Klan-Prüfungsstandarte anerkannt wird, ähneln ihre optischen Markierungen älteren Stammesabzeichen, darunter Symbolen, die mit frühen Orc-Klans der alten Horde in Verbindung gebracht werden.",al={"schattenhammer symbol banner","banner sieht falsch aus","banner der frostwolf design"}}},fp="16,231,17.460.0,48.235.0,40.179.0,57.180.0"}
P.entries["item:full-leaden-collection-phial"] = {n="Volle bleierne Sammelphiole",s="Eine schwere, bleiverkleidete Flasche, gefüllt mit verstrahltem radioaktivem Niederschlag, der von den Troggs gesammelt wurde, die Gnomeregan heimsuchen. Der Erfinder Ozzie Togglevolt bat um diese gefährliche Probe in der Hoffnung, ein Heilmittel für verstrahlte Lepragnome zu synthetisieren – oder vielleicht einen gefährlich starken Rum zusammenzubrauen.",h="Eine schwere, bleiverkleidete Flasche, gefüllt mit verstrahltem radioaktivem Niederschlag, der von den Troggs...",kw={"volle bleierne sammelphiole","gnogaine","gnomeregan","verstrahlter trogg","kharanos","bleierne sammelfiole","lepragnom","ozzie togglevolt"},ang={["profession:Engineering"]="Die bleierne Hülle demonstriert die gnomischen Standardsicherheitsmaßnahmen beim Umgang mit flüchtigem, giftigem Niederschlag für Labortests.",["race:Gnome"]="Für verbannte Gnome in Dun Morogh ist das Tragen dieser giftigen Probe eine düstere Erinnerung an die Katastrophe, die ihre angestammte Heimat vergiftet hat, doch sie steht zugleich für die verzweifelte Hoffnung, ihre verdorbenen Verwandten zu heilen."},sec={{t="Ein giftiges Gebräu",b="Die Bleiauskleidung dieser Sammelfiole ist unerlässlich, um den Träger vor dem flüchtigen grünen Niederschlag zu schützen, der Gnomeregan durchdringt. Der Niederschlag entstand, als die Berater von Hochtüftler Mekkatorque die unteren Korridore mit giftiger Strahlung fluteten, um die eindringenden Troggs aufzuhalten – eine Katastrophe, die stattdessen sowohl Troggs als auch überlebende Gnome in wahnsinnige, verstrahlte Schrecken verwandelte. Durch das Sammeln von Flüssigkeitsrückständen direkt von verstrahlten Eindringlingen und Plünderern versorgen wagemutige Abenteurer geflüchtete Tüftler wie Ozzie Togglevolt und Razzle Sprysprocket in Kharanos mit den Rohstoffen, die für Experimente an Heilmitteln benötigt werden."},{t="Heilung oder Gebräu",b="Während Gnoarn darauf fixiert bleibt, die Stadt zurückzuerobern, nähert sich Ozzie Togglevolt dem Problem des radioaktiven Niederschlags mit fieberhaftem Gnomengeist und Experimenten. Ozzie versucht, die in der Fiole gesammelte Flüssigkeit zu verwenden, um einen gefangenen Lepragnom zu behandeln – während er gleichzeitig hofft, die Mischung könnte seine eigene Kahlköpfigkeit rückgängig machen. Die Grenze zwischen einem wundersamen Gegenmittel und einem hochexplosiven Getränk bleibt in der Laborwissenschaft der Gnome gefährlich schmal."}},faq={{q="Warum besteht die Fiole aus Blei?",a="Die Bleiauskleidung verhindert, dass der intensive radioaktive Niederschlag, der von Gnomeregans kontaminierten Troggs gesammelt wurde, den Träger erkranken lässt oder tötet, der ihn nach Kharanos zurückbringt.",al={"warum bleifiole","warum bleiflasche","bleierne sammelfiole zweck"}},{q="Wer benötigt diese verstrahlte Flüssigkeit?",a="Ozzie Togglevolt, ein Gnomenforscher, der in Kharanos tätig ist, benötigt den verstrahlten Niederschlag, um mit Unterstützung von Razzle Sprysprocket an einem Heilmittel für von Lepra befallene Gnome zu experimentieren.",al={"wer braucht die fiole","ozzie togglevolt quest","wer gibt gnogaine ab"}},{q="Woher stammt die Strahlung in der Fiole?",a="Der leuchtend grüne Rückstand wird direkt von Irradiated Invaders und Irradiated Pillagers gewonnen, Troggs, die die verseuchten Korridore nach Gnomeregan durchstreifen.",al={"wie fiole füllen","verstrahlte troggs aufenthaltsort","grünes leuchten quelle"}},{q="Heilt Ozzie die Lepragnome tatsächlich damit?",a="Ozzies Experimente sind chaotisch und ungewiss. Sein Gebräu zielt darauf ab, einen gefangenen Lepragnom zu heilen und sein eigenes Haar wiederherzustellen, doch die Gnomenwissenschaft erfordert oft wiederholte Tests und verfeinerte Proben, bevor sichere, beständige Ergebnisse erzielt werden.",al={"funktioniert die heilung","gnogaine ergebnis","ist lepragnom geheilt"}}},fp="28,287,12.609.0,18.425.1,30.174.0,32.172.0,48.163.0,50.235.0"}
P.entries["item:fungal-spores"] = {n="Pilzsporen",s="Pilzsporen werden von vollgesogenen Pilzen geerntet, die rund um die seltsamen Oasen des Brachlands wachsen. Erfüllt von den geheimnisvollen Lebensenergien dieser Gewässer werden sie von Forschern der Königlichen Apothekervereinigung geschätzt, die nach wirkungsvollen Reagenzien für ihre chemischen Gebräue suchen.",h="Pilzsporen werden von vollgesogenen Pilzen geerntet, die rund um die seltsamen Oasen des Brachlands wachsen.",kw={"apotheker helbrim","apothekervereinigung","brachland","crossroads","die vergessenen teiche","pilzsporen","vollgesogener pilz","die blühende oase","die brackige oase"},ang={["profession:Herbalism"]="Botaniker und Sammler werden die dramatischen physiologischen Veränderungen dieser Pilze bemerken, die durch das lebensspendende, transformative Wasser der Oasen des Brachlands verursacht werden.",["race:Undead"]="Die Königliche Apothekervereinigung schätzt einzigartige regionale Reagenzien, um ihre Forschungen voranzutreiben, und die mutierten Pilze von Kalimdor bieten eine verlockende Alternative zur verseuchten Flora von Lordaeron."},sec={{t="Lebenskraft der Oasen",b="In den trockenen Ebenen des Brachlands pulsieren smaragdgrüne Oasen wie die vergessenen Teiche, die blühende Oase und die brackige Oase mit einer ungewöhnlichen Vitalität. Das Wasser stillt nicht bloß den Durst; es beschleunigt, verändert und belebt die umgebende Flora und Fauna aktiv. Pilze, die an den feuchten Ufern wachsen, schwellen an und werden schwer von Sporen, die dieses konzentrierte, unbeständige Wachstumspotenzial in sich tragen. Für Naturforscher ist dies ein ökologisches Kuriosum; für die Königliche Apothekervereinigung ist es eine erstklassige botanische Probe, die darauf wartet, als Waffe genutzt oder verfeinert zu werden."},{t="Alchemie der Verlassenen",b="In der Ferne stationierte Apotheker wie Apotheker Helbrim in Crossroads sammeln unablässig exotische einheimische Reagenzien, um sie an ihre Labore zurückzusenden oder mit fernen Kollegen wie Apothekerin Zamah in Thunder Bluff zu teilen. Die veränderte Physiologie der Sporen macht sie besonders wertvoll für das Brauen wirkungsvoller chemischer Lösungen. Die Verlassenen schätzen diese Proben gerade deshalb, weil ihre natürlichen Eigenschaften bereits durch die geheimnisvollen Kräfte verschoben wurden, die unter dem Boden von Kalimdor pulsieren."}},faq={{q="Wo sind diese Sporen zu finden?",a="Pilzsporen werden von vollgesogenen Pilzen gesammelt, die an den Ufern der großen Oasen des Brachlands wachsen: den vergessenen Teichen, der blühenden Oase und der brackigen Oase.",al={"sporen orte","wo man pilzsporen findet","fundorte vollgesogener pilze"}},{q="Warum interessieren sich die Verlassenen für sie?",a="Die Sporen sind von den veränderten, pulsierenden Lebensenergien der Oasen erfüllt. Apotheker Helbrim nutzt sie, um wirkungsvolle alchemistische Gebräue für die Königliche Apothekervereinigung und seine Kollegin Apothekerin Zamah in Thunder Bluff herzustellen.",al={"warum helbrim sporen will","apotheker verwendung der sporen","wofür sporen verwendet werden"}},{q="Warum wachsen die Pilze um die Oasen so groß?",a="Die Gewässer der Oasen des Brachlands besitzen eine ungewöhnliche Lebenskraft, die die umgebende Flora und Fauna belebt und mutieren lässt, wodurch die Pilze entlang der Ufer anschwellen und wirkungsvolle, veränderte Sporen bilden.",al={"warum die pilze mutiert sind","wirkung des oasenwassers","geheimnis der oasen"}},{q="Wer verlangt nach den Sporen?",a="Apotheker Helbrim, ein in Crossroads im Brachland stationierter Alchemist der Verlassenen, beauftragt Abenteurer damit, die Sporen für seine Forschungen zu sammeln.",al={"wer pilzsporen braucht","questgeber für sporen","apotheker helbrim"}}},fp="13,268,21.570.0,16.495.0,29.168.0,40.228.0,52.197.0,24.146.0"}
P.entries["item:furen-s-instructions"] = {n="Furens Anleitung",s="Furens Anleitung ist ein handgeschriebenes Pergament, das vom Meisterrüstschmied Furen Longbeard in Stormwind überreicht wird. Es beschreibt die seltenen und gefährlichen Reagenzien, die erforderlich sind, um eine feuergehärtete Kettenrüstung für vielversprechende Krieger der Allianz zu schmieden.",h="Furens Anleitung ist ein handgeschriebenes Pergament, das vom Meisterrüstschmied Furen Longbeard in Stormwind...",kw={"verkohltes horn","feuergehärteter panzer","furen longbeard","furens anleitung","galvanisiertes horn","der kral von razorfen","versengter spinnenfangzahn","steinkrallengebirge","phiole mit phlogiston","sumpfland"},ang={["class:Warrior"]="Diese Checkliste stellt einen Übergangsritus für Krieger der Allianz dar, die zu schwerer Kettenrüstung übergehen, und erfordert Prüfungen gegen wilde Bestien und finstere Borstenstacheln.",["profession:Blacksmithing"]="Furens exotisches Rezept zeigt, wie Meisterschmiede Bestienreagenzien und seltene alchemistische Destillate kombinieren, um Rüstungen weit über gewöhnliche Schmiedekunst hinaus zu härten."},sec={{t="Die Forderungen eines Meisterschmieds",b="Furen Longbeard vergibt außergewöhnliche Rüstungen nicht leichtfertig. Nachdem er die Entschlossenheit eines Kriegers bereits mit einfacheren Schmiedeaufgaben auf die Probe gestellt hat, bietet der zwergische Handwerker an, ein außerordentlich widerstandsfähiges Kettenhemd zu schmieden – vorausgesetzt, der Abenteurer beschafft die seltenen Komponenten selbst. Um sicherzustellen, dass nichts vergessen wird, stellt Furen diese detaillierte Checkliste zur Verfügung und schickt seinen Schützling auf eine beschwerliche Schnitzeljagd über Kontinente hinweg."},{t="Exotische Komponenten",b="Die Anleitung beschreibt eine gefährliche Reise, die sich sowohl über die Östlichen Königreiche als auch über Kalimdor erstreckt. Das Schmieden der gehärteten Kettenglieder erfordert Dutzende versengter Spinnenzähne aus den feuchten Höhlen des Sumpflands, Hörner von feuerspeienden Schimären aus den zerklüfteten Felsen im Steinkrallengebirge und ein wertvolles galvanisiertes Horn von der Schimärenmatriarchin selbst. Der letzte, alchemistische Katalysator ist eine Phiole mit flüchtigem Phlogiston, die tief in der Borstenstachel-Bastion des Krals von Razorfen aufbewahrt wird."}},faq={{q="Was ist Furens Anleitung?",a="Es ist eine schriftliche Checkliste, die Kriegern der Allianz vom Schmied Furen Longbeard in Stormwind überreicht wird. Sie listet die spezifischen exotischen Materialien auf, die zur Herstellung einer feuergehärteten Kettenrüstung benötigt werden.",al={"furens anleitung","was ist furens anleitung","furen liste"}},{q="Wer ist Furen Longbeard?",a="Furen Longbeard ist ein zwergischer Meisterrüstschmied, der im Dwarven District von Stormwind stationiert ist. Er ist darauf spezialisiert, erfahrene Krieger zu prüfen und widerstandsfähige Schutzausrüstung für sie herzustellen.",al={"wer ist furen","furen longbeard","furen stormwind"}},{q="Woher stammen die Materialien auf der Liste?",a="Die Liste schickt Krieger weit umher: Versengte Spinnenzähne werden von Spinnen im Sumpfland erbeutet, verkohlte Hörner und ein galvanisiertes Horn werden von Schimären im Steinkrallengebirge erjagt, und eine Phiole mit Phlogiston muss von Roogug im Kral von Razorfen erbeutet werden.",al={"wo finde ich die gegenstaende","furen materialien orte","materialien auf furens liste"}},{q="Was schmiedet Furen aus diesen Materialien?",a="Sobald alle gefährlichen Reagenzien und die Anleitung zu ihm zurückgebracht wurden, nutzt Furen seine Schmiedegeheimnisse, um ein spezielles Teil der Rüstung Feuergehärteter Panzer für den Krieger zu schmieden.",al={"welche ruestung stellt furen her","feuergehaerteter panzer belohnung","furen handwerksbelohnung"}}},fp="20,223,24.417.0,17.472.0,29.195.0,23.182.0,45.266.0,43.179.0"}
P.entries["item:furen-s-notes"] = {n="Furens Notizen",s="Furens Notizen sind schriftliche Folianten, die metallurgische und rüstungsschmiedetechnische Erkenntnisse enthalten, welche Furen Longbeard in Stormwind entdeckt hat. Verfasst nach dem Schmieden widerstandsfähiger Schutzausrüstung für erfahrene Krieger, werden sie in der gesamten Allianz verteilt, um die Techniken befreundeter Handwerker zu verfeinern.",h="Furens Notizen sind schriftliche Folianten, die metallurgische und rüstungsschmiedetechnische Erkenntnisse...",kw={"schmiedekunst","dwarven district","furen","furen longbeard","furens notizen","grimand elmore","klockmort spannerspan","mathiel"},ang={["class:Warrior"]="Diese Notizen werden direkt als Ergebnis Eurer Klassenrüstungsprüfungen in Stormwind verfasst und dienen als Beweis für die praktischen Neuerungen, die aus Euren Bedürfnissen an der Front hervorgegangen sind.",["profession:Blacksmithing"]="Die Folianten stehen für den fortlaufenden Austausch von Fachwissen im Rüstungsschmieden zwischen zwergischen, elfischen und gnomischen Kunsthandwerkern in der gesamten Allianz."},sec={{t="Die Entdeckungen eines Meisters",b="Wenn Furen Longbeard das anspruchsvolle Schmieden spezialisierter Kriegerausrüstung im Dwarven District von Stormwind abschließt, fasst er die Methoden und Durchbrüche, die er dabei entdeckte, in schriftlichen Notizen zusammen. Die Zwergenmetallurgie entwickelt sich ständig weiter, und Furen fertigt mehrere Abschriften dieser Abhandlungen an, damit seine Standesgenossen seine Erkenntnisse replizieren und erweitern können. Die Dokumente halten praktische Fortschritte beim Härten, Verstärken und Formen von Rüstungen gegen tödliche Kampfschläge fest."},{t="In der gesamten Allianz verteilt",b="Furen verteilt seine Notizen an vertrauenswürdige Kontakte innerhalb der Handwerksnetzwerke der Allianz. Während einheimische Meister wie Grimand Elmore vielleicht darüber spotten, von einem Gefährten belehrt zu werden, von dem sie behaupten, ihn selbst unterrichtet zu haben, lässt sich der Wert der Erkenntnisse nicht leugnen. Exemplare werden sogar über das große Meer zu nachtelfischen Handwerkern wie Mathiel auf der Terrasse der Krieger in Darnassus gebracht, wodurch die Kluft zwischen verschiedenen angestammten Traditionen durch geteilte kriegerische Notwendigkeit überbrückt wird."}},faq={{q="Was beinhalten Furens Notizen?",a="Die Notizen enthalten schriftliche Beschreibungen von Rüstungsschmiedetechniken und metallurgischen Entdeckungen, die Furen Longbeard bei der Anfertigung maßgeschneiderter Rüstungen für gestählte Krieger entwickelte.",al={"was sind furens notizen","was steht in furens notizen","furens notizen inhalt"}},{q="Wer ist Furen Longbeard?",a="Furen Longbeard ist ein meisterhafter Zwergenrüstungsschmied, der im Dwarven District von Stormwind stationiert ist und dafür bekannt ist, aufstrebende Krieger anzuleiten und spezialisierte defensive Kriegsausrüstung herzustellen.",al={"wer hat das geschrieben","wer ist furen","furen longbeard"}},{q="Warum ärgert sich Grimand Elmore über die Notizen?",a="Grimand Elmore ist ein überaus stolzer Waffen- und Rüstungsschmied, der behauptet, er habe Furen alles beigebracht, was der Zwerg weiß. Obwohl er über die Andeutung empört ist, sein ehemaliger Schüler könne ihm etwas Neues beibringen, gibt Grimand dennoch zu, dass die in den Notizen beschriebenen Techniken einen Versuch wert sind.",al={"warum ist grimand wütend","reaktion von grimand elmore","grimand stolz"}},{q="Wer erhält Exemplare von Furens Notizen?",a="Furen sendet Kopien seiner Schriften an vertrauenswürdige Kollegen in der gesamten Allianz, darunter den Waffenschmied Grimand Elmore in Stormwind, den Nachtelfenschmied Mathiel in Darnassus und den Gnomen-Schmied Klockmort Spannerspan in Ironforge.",al={"wer bekommt furens notizen","wohin gehen die notizen","furens notizen abliefern"}},{q="Wie reagiert Mathiel auf die Notizen?",a="Anders als die schroffen Schmiede von Stormwind nimmt Mathiel – ein Nachtelfenschmied auf der Terrasse der Krieger in Darnassus – die zwergischen Erkenntnisse mit offener Begeisterung auf und betrachtet Furens Entdeckungen als großartige Errungenschaft und Ehre, sie in sein eigenes Handwerk einfließen zu lassen.",al={"mathiel reaktion","mathiel darnassus","was denkt mathiel"}}},fp="13,287,22.471.0,30.465.0,39.184.0,23.172.0,50.276.0,37.244.0,36.261.0"}
P.entries["item:furlbrow-s-deed"] = {n="Furlbrows Urkunde",s="Furlbrows Urkunde ist der rechtliche Eigentumstitel von Bauer Theodore Furlbrow und seiner Frau Verna für ihr Land in Westfall. Von Banditen der Defias erbeutet, um als Vorlage für gefälschte Landansprüche zu dienen, steht sie stellvertretend für die prekäre Lage ehrlicher Bürger, die im gesamten Königreich aus ihren Heimen vertrieben wurden.",h="Furlbrows Urkunde ist der rechtliche Eigentumstitel von Bauer Theodore Furlbrow und seiner Frau Verna für ihr...",kw={"urkunde","defias","bauernhof","furlbrow","theodore","verna","planwagen","westfall"},ang={["faction:Alliance"]="Die Rückgabe der Urkunde spendet vertriebenen Untertanen, die von den militärischen Engpässen des Königreichs im Stich gelassen wurden, ein wenig Trost.",["race:Human"]="Der Diebstahl einfacher Eigentumstitel verdeutlicht, wie gründlich die Defias die zivile Ordnung in den Nachbargebieten von Stormwind untergraben haben."},sec={{t="Gestohlenes Land und gefälschte Ansprüche",b="Unterzeichnet von Theodore Furlbrow und mitunterzeichnet von seiner Frau Verna, begründet dieses Dokument das Eigentum an ihrem Familienbauernhof in Westfall. Als die Bruderschaft der Defias die Region überrannte, vertrieben Wegelagerer das Paar gewaltsam und nahmen das Dokument mit in den Wald von Elwynn. Gekritzelte Notizen auf der Rückseite verraten, dass die Diebe beabsichtigten, das offizielle Pergament als Vorlage für gefälschte Rechtsurkunden anderer Grundstücke zu verwenden. Ihres Heims und ihrer Existenzgrundlage beraubt, waren die Furlbrows gezwungen, sich auf den Weg zu machen, und strandeten nahe der Grenze, als ihr Wagen eine Panne hatte."}},faq={{q="Warum stahlen die Defias die Urkunde?",a="Notizen auf der Rückseite des Pergaments verraten, dass die Schläger der Defias beabsichtigten, das authentische Siegel und die Unterschriften zu studieren, um eigene Urkunden zu fälschen und so Ansprüche auf beschlagnahmte Gehöfte in ganz Westfall zu legitimieren.",al={"warum urkunde stehlen","warum wollten banditen die urkunde","defias zweck der urkunde"}},{q="Wem gehört diese Urkunde?",a="Die Urkunde gehört rechtmäßig Bauer Theodore Furlbrow und seiner Frau Verna, zwei Siedlern aus Westfall, die von Gesetzlosen schikaniert und von ihrem Hof vertrieben wurden.",al={"wem gehoert furlbrows urkunde","wer ist furlbrow","wessen urkunde ist das"}},{q="Wo sind die Furlbrows zu finden?",a="Das Paar ist direkt hinter der Grenze von Westfall an der Hauptstraße zu finden, die aus dem Wald von Elwynn kommt, gestrandet neben ihrem liegengebliebenen Wagen.",al={"wo sind die furlbrows","bauer furlbrow aufenthaltsort","wo urkunde abgeben"}},{q="Warum liegt den Furlbrows noch etwas an der Urkunde, wenn sie geflohen sind?",a="Obwohl die Furlbrows zugeben, dass Westfall für ehrliche Bürger viel zu gefährlich geworden ist, bietet der Besitz des rechtlichen Eigentumsnachweises ihre einzige Hoffnung, ihr Land jemals zurückzufordern, falls wieder Frieden einkehrt.",al={"warum wollen sie urkunde zurueck","kehren die furlbrows zurueck"}}},fp="15,297,29.547.0,34.216.0,29.160.0,33.133.0,60.195.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="Furlbrows Taschenuhr",s="Furlbrows Taschenuhr ist ein geschätztes Familienerbstück von Bauer Furlbrow aus Westfall. Die Uhr, die ihm am Tag seiner Hochzeit vom Vater seiner Frau Verna geschenkt wurde, wurde in aller Eile zurückgelassen, als Banditen der Defias ihren Kürbishof überrannten.",h="Furlbrows Taschenuhr ist ein geschätztes Familienerbstück von Bauer Furlbrow aus Westfall.",kw={"benny blaanco","defias","bauer furlbrow","furlbrows taschenuhr","das vergessene erbstück","verna furlbrow","kleiderschrank","westfall"},ang={["faction:Alliance"]="Den Furlbrows dabei zu helfen, ihr verlorenes Erbstück wiederzuerlangen, ist eine deutliche Erinnerung daran, wie vollkommen die Krone von Stormwind dabei versagt hat, die hart arbeitenden Bauern von Westfall vor dem organisierten Banditentum zu schützen."},sec={{t="Ein Andenken in den Ruinen",b="Als Randalierer der Defias das Furlbrow Pumpkin Patch überrannten, sahen sich Bauer Furlbrow und seine Frau Verna gezwungen, ihren Hof mitten in der Nacht aufzugeben. Auf der überstürzten Flucht ließ der Bauer eine kostbare Taschenuhr zurück, die er von seinem Schwiegervater als Hochzeitsgeschenk erhalten hatte. Das Erbstück blieb in einem Kleiderschrank im überrannten Bauernhaus verwahrt, bewacht von Halsabschneidern unter der Führung von Benny Blaanco. Für das vertriebene Paar, das am Straßenrand lagert, bedeutet die Wiederbeschaffung der Uhr die Rettung eines der wenigen Stücke ihres früheren Lebens, das die Gesetzlosen noch nicht zerstört haben."}},faq={{q="Warum ist die Taschenuhr für Bauer Furlbrow so wichtig?",a="Die Uhr wurde Bauer Furlbrow am Tag seiner Hochzeit von Vernas Vater geschenkt. Nachdem das Paar sein Land, sein Heim und seine Existenzgrundlage an Die Bruderschaft der Defias verloren hat, ist die Uhr der letzte zutiefst sentimentale Besitz, der ihnen noch geblieben ist.",al={"warum will furlbrow seine uhr","furlbrow uhr bedeutung","wer gab furlbrow die uhr"}},{q="Wo wird die Taschenuhr aufbewahrt?",a="Die Uhr wurde in einem Kleiderschrank im Bauernhaus der Furlbrows zurückgelassen, das inmitten der Kürbisfelder westlich der Hauptstraße liegt, an der die Furlbrows derzeit festsitzen.",al={"wo ist die taschenuhr","furlbrow kleiderschrank standort","wie findet man die uhr"}},{q="Wer bewacht die Uhr?",a="Das verlassene Bauernhaus wurde von der Bruderschaft der Defias übernommen, genauer gesagt von dem Banditen Benny Blaanco und seiner Gefolgschaft, die sich direkt in der Nähe des Kleiderschranks herumtreiben.",al={"wer hat furlbrows uhr","uhr wache westfall","benny blaanco uhr"}},{q="Haben die Defias die Uhr direkt gestohlen?",a="Nein. Als die Banditen das Kürbisfeld überfielen, flohen die Furlbrows in solcher Panik, dass der Bauer schlicht vergaß, sie einzupacken. Sie blieb im Kleiderschrank ihres Schlafzimmers verborgen, während der Hof überrannt wurde.",al={"haben defias die uhr geplündert","wurde die uhr gestohlen"}}},fp="23,242,23.580.0,56.223.0,31.166.0,26.159.0,40.200.0"}
P.entries["item:gaea-seed"] = {n="Gaeas Samenkorn",s="Gaeas Samenkörner sind widerstandsfähige Pflanzenkerne, die am Ufer des Mirkfallonsees im Steinkrallengebirge zu finden sind. Von Taurenschamanen hoch geschätzt, werden sie mit elementaren Segnungen erfüllt, um Gebiete wiederzubeleben, die von Krieg und Industrie verwüstet wurden.",h="Gaeas Samenkörner sind widerstandsfähige Pflanzenkerne, die am Ufer des Mirkfallonsees im Steinkrallengebirge...",kw={"das verbrannte tal","zyklus der wiedergeburt","erdenmutter","gaeas samenkorn","mirkfallonsee","steinkrallengebirge","sonnenfels","tammra windfield"},ang={["class:Shaman"]="Die Samen stehen für praktische Erdrenaturierung und zeigen, wie schamanistische Rituale und der Segen der Erdenmutter das natürliche Wachstum in beschädigten Umgebungen beschleunigen können.",["race:Tauren"]="Für die Tauren von Sonnenfels ist die Kultivierung von Gaeas Samenkörnern eine heilige Pflicht, um das Gleichgewicht des Landes zu heilen, das durch äußere Kriegsführung und Holzausbeutung gestört wurde."},sec={{t="Gefäße der Erneuerung",b="Gaeas Samenkörner sind im Steinkrallengebirge beheimatet und werden natürlicherweise an die Ufer des Mirkfallonsees gespült oder wachsen um diese herum. Obwohl sie von bescheidener Gestalt sind – sie ähneln kleinen, faserigen Kokosnüssen –, tragen sie eine ihnen innewohnende Widerstandskraft in sich. Während industrielle Ausbeutung und Konflikte das Steinkrallengebirge zeichnen, betrachten schamanische Praktizierende diese Samen als lebenswichtige Kanäle zur Heilung der verwundeten Erde."},{t="Segnungen der Erdenmutter",b="In Sonnenfels sammelt die Taurenschamanin Tammra Windfield Gaeas Samenkörner, um der Zerstörung entgegenzuwirken, die sich über die Gipfel ausbreitet. Durch traditionelle Gesänge und Elementarrituale erfüllen Schamanen diese ruhenden Hüllen mit dem Segen der Erdenmutter. Diese spirituelle Durchdringung beschleunigt ihr natürliches Wachstum drastisch und verwandelt einfache Samen in widerstandsfähige Schösslinge, die in der Lage sind, in verbranntem, unfruchtbarem Boden wie dem verbrannten Tal Wurzeln zu schlagen."}},faq={{q="Wo sind Gaeas Samenkörner zu finden?",a="Gaeas Samenkörner liegen verstreut entlang der Uferlinie des Mirkfallonsees, der in den Bergen nördlich von Sonnenfels im Steinkrallengebirge liegt.",al={"gaeas samenkorn fundort","wo man gaeas samenkörner findet","wie man gaeas samenkorn bekommt"}},{q="Wofür werden Gaeas Samenkörner verwendet?",a="Tammra Windfield sammelt sie in Sonnenfels, um einen elementaren Segen zu wirken. Sobald sie mit schamanistischer Macht erfüllt sind, werden die Samen genutzt, um die Pflanzenwelt in verwüsteten Gebieten wie dem verbrannten Tal wiederherzustellen.",al={"gaeas samenkorn zweck","warum gaeas samenkörner sammeln","was tammra mit gaeas samenkörnern macht"}},{q="Warum müssen Schamanen die Samen erfüllen?",a="Das Land in Teilen des Steinkrallengebirges wurde durch Feuer, Kriegsführung und Abholzung schwer in Mitleidenschaft gezogen. Die Kanalisierung der Macht der Erdenmutter in die Samen beschleunigt ihre Keimung und stärkt sie so weit, dass sie in lebensfeindlichem, zerstörtem Boden wachsen können.",al={"warum die samen gesegnet werden","schamanenmagie gaeas samenkorn"}},{q="Wie sehen Gaeas Samenkörner aus?",a="Sie liegen nahe am Wasserrand rund um den Mirkfallonsee und sehen aus wie kleine, braune, rundliche Schalen oder Kokosnüsse, die am Ufer ruhen.",al={"gaeas samenkorn aussehen","wie man gaeas samenkörner erkennt"}}},fp="9,234,18.363.0,28.435.1,27.137.0,29.204.0,39.235.0,29.128.0"}
P.entries["item:gaffer-jack"] = {n="Klemm-Muffen",s="Eine Klemm-Muffe ist ein spezielles Ingenieursbauteil, das für komplizierte mechanische Justierungen verwendet wird, wie etwa das Einstellen von Drehzapfen. Eine Kiste davon ging während der Seereise des exzentrischen Gnomen-Erfinders Wizbang Cranktoggle vor der Küste von Auberdine unvorsichtig in den Wellen verloren.",h="Eine Klemm-Muffe ist ein spezielles Ingenieursbauteil, das für komplizierte mechanische Justierungen...",kw={"auberdine","darkshore","angeln","klemm-muffen","ironforge","drehzapfen","wizbang cranktoggle"},ang={["profession:Engineering"]="Andere Tüftler werden den schieren Frust darüber nachvollziehen können, proprietäre Hardware wie Klemm-Muffen zu verlieren, ohne die empfindliche Mechanismen wie Drehzapfen nicht kalibriert werden können.",["race:Gnome"]="Den Trubel von Ironforge für ein ruhiges Leben in Auberdine hinter sich zu lassen, mag für einen Gnom ungewöhnlich sein, aber nach zu viel Alkohol eine ganze Kiste wichtiger Teile über die Schiffsreling zu werfen, passt vollkommen ins Bild."},sec={{t="Auf See verloren",b="Auf der Suche nach Ruhe und Frieden fernab der klappernden Schmiedewerke und lauten Tavernen von Ironforge buchte der Gnomen-Tüftler Wizbang Cranktoggle eine Überfahrt auf einem Schiff nach Auberdine. Nachdem er sich während der Seereise ein wenig zu sehr dem Trank hingegeben hatte, gelang es Wizbang, einen ganzen Behälter mit Klemm-Muffen ungeschickt über die Reling fallen zu lassen. Diese kleinen mechanischen Befestigungselemente sanken in die nebligen Küstengewässer der Darkshore und ließen ihn ohne die lebenswichtigen Teile stranden, die er zum Einstellen seiner Drehzapfen benötigte."},{t="Versunkene Bergung",b="Da Klemm-Muffen entlang der Küstenlinie in die Brandung gelangten, verfangen sie sich gelegentlich an den Haken geduldiger Angler, die ihre Ruten in den Küstengewässern der Darkshore auswerfen. Die Bergung dieser verlorenen Bauteile ermöglicht es Wizbang, seine bizarren Apparaturen zusammenzubauen, auch wenn das Heben winziger Metallkleinteile aus dem offenen Meer ein Zeugnis außergewöhnlicher Geduld und puren Glücks bleibt."}},faq={{q="Wofür wird eine Klemm-Muffe verwendet?",a="Laut dem Gnomen-Tüftler Wizbang Cranktoggle sind Klemm-Muffen unverzichtbare Ingenieursbauteile, die benötigt werden, um Drehzapfen für seine experimentellen Erfindungen einzustellen.",al={"klemm-muffen zweck","was macht eine klemm-muffe","klemm-muffen verwendung"}},{q="Wie landeten diese im Meer rund um Auberdine?",a="Wizbang Cranktoggle nahm ein Schiff aus den Östlichen Königreichen, um Ruhe und Frieden fernab von Ironforge zu suchen. Während der Überfahrt trank er zu viel und ließ versehentlich seine Kiste mit Klemm-Muffen über Bord in die Gewässer der Darkshore fallen.",al={"warum sind klemm-muffen im wasser","wer hat klemm-muffen fallen gelassen","klemm-muffe verloren"}},{q="Wer möchte, dass die Klemm-Muffen geborgen werden?",a="Wizbang Cranktoggle, ein exzentrischer Gnomen-Erfinder, der sich in der Hafenstadt Auberdine aufhält, benötigt acht davon zurück, um seine seltsamen Erfindungen weiterzubauen.",al={"wer braucht klemm-muffen","klemm-muffen abgabe","wer nimmt klemm-muffen"}},{q="Wo können Klemm-Muffen gefunden werden?",a="Sie liegen versunken entlang der Küstenlinie der Darkshore auf dem Meeresgrund, wo Angler sie gelegentlich beim Fischen in der Küstenbrandung an den Haken bekommen.",al={"wo man klemm-muffen bekommt","wie man klemm-muffen findet","klemm-muffen standort"}}},fp="11,291,11.493.0,14.379.0,31.165.0,51.233.0,33.161.0,32.143.0"}
P.entries["item:gallywix-s-head"] = {n="Gallywixs Kopf",s="Gallywixs Kopf ist eine abgetrennte Trophäe von Grand Foreman Puzik Gallywix, einem Aufseher der Venture Company, der im Schlickermoor im Brachland tätig ist. Er dient als grausiger Beweis für die Hinrichtung, die von der Shattered-Hand, dem geheimen Schurkensyndikat mit Sitz in Orgrimmar, gefordert wurde.",h="Gallywixs Kopf ist eine abgetrennte Trophäe von Grand Foreman Puzik Gallywix, einem Aufseher der Venture...",kw={"brachland","gallywix","orgrimmar","puzik","die shattered-hand","shenthul","das schlickermoor","venture company"},ang={["class:Rogue"]="Die Bergung von Gallywixs Kopf beweist die tödlichen Fähigkeiten eines Schurken bei verdeckter Infiltration, Tarnung und gezieltem Meuchelmord im Auftrag der Shattered-Hand.",["faction:Horde"]="Die Ausschaltung von Anführern der Venture Company wie Gallywix dämmt die ausbeuterischen industriellen Übergriffe ein, die die Grenzen des Brachlands und Durotars bedrohen."},sec={{t="Ein grausamer Beweis der Ausschaltung",b="Grand Foreman Puzik Gallywix leitete die Operationen vom Turm der Venture Company nördlich des Schlickermoors aus. Als Reaktion auf die vordringende industrielle Bedrohung und die dort hergestellten gefährlichen Gebräue entsandte die Shattered-Hand Agenten, um die Einrichtung vollständig zu zerschlagen. Die Erbeutung von Puzik Gallywix' Kopf dient Shenthul in Orgrimmar als unumstößlicher Beweis dafür, dass der Aufseher hingerichtet wurde, was das Ansehen des Schurken innerhalb der Gilde sichert."},{t="Der Einfall ins Schlickermoor",b="Der Auftrag, Gallywixs Kopf zu beschaffen, geht einher mit dem Befehl, einen gestohlenen Behälter mit Zanzils veränderter Mixtur zu bergen und das vergiftete Personal des Turms zu töten. Indem Agenten Gallywix auf seinem Ausguck ermorden und seinen Kopf in die Kluft der Schatten bringen, bestätigen sie die Vereitlung der toxischen Experimente der Venture Company im Brachland."}},faq={{q="Wessen Kopf ist das?",a="Der Kopf gehört Grand Foreman Puzik Gallywix, einem Goblin-Aufseher, der die Operationen der Venture Company im Schlickermoor im nördlichen Brachland überwacht.",al={"wer ist gallywix","puzik gallywix","gallywix kopf herkunft"}},{q="Wer will Gallywixs Kopf?",a="Die Trophäe wird Shenthul überbracht, einem Schurkenlehrer und Agenten der Shattered-Hand in der Kluft der Schatten unter Orgrimmar.",al={"wem gebe ich den kopf","gallywix kopf abgeben","shenthul kopf"}},{q="Warum will die Shattered-Hand seinen Tod?",a="Puzik Gallywix beaufsichtigte eine gefährliche Operation der Venture Company, bei der mit Zanzils veränderter Mixtur experimentiert wurde. Die Shattered-Hand gab ihn zum Abschuss frei, um eine lokale industrielle Gefahr zu beseitigen und das Gebräu zu sichern.",al={"warum gallywix töten","gallywix attentat grund"}},{q="Wo befindet sich Puzik Gallywix?",a="Er ist ganz oben auf dem Turm der Venture Company zu finden, der direkt nördlich des Schlickermoors im nördlichen Brachland liegt.",al={"wo ist gallywix","gallywix aufenthaltsort","schlickermoor turmboss"}}},fp="15,275,27.437.0,24.349.1,19.150.0,26.140.0,42.211.0,32.119.0"}
P.entries["item:galvanized-horn"] = {n="Galvanisiertes Horn",s="Ein Galvanisiertes Horn ist ein gehärtetes biologisches Gewächs, das von den furchterregenden Schimärenmatriarchinnen erbeutet wird, welche die verbrannten Felsen von Kalimdor heimsuchen. Dieses widerstandsfähige Exemplar ist bei Meisterrüstmeistern beider Fraktionen heiß begehrt und dient als Kernmaterial für spezialisierte Kriegerrüstungen.",h="Ein Galvanisiertes Horn ist ein gehärtetes biologisches Gewächs, das von den furchterregenden...",kw={"das verbrannte tal","schimärenmatriarchin","feuergehärteter panzer","furen longbeard","galvanisiertes horn","orm stonehoof","steinkrallengebirge"},ang={["class:Warrior"]="Das Erlegen einer Matriarchin und das Beschaffen ihres galvanisierten Horns ist eine Prüfung der Ausdauer und Kraft, die den Meisterrüstmeistern in Stormwind oder Thunder Bluff den Mut eines Kriegers beweist.",["profession:Blacksmithing"]="Das Horn verdeutlicht, wie organische Materialien, die in extremen Umgebungen gehärtet wurden, bearbeiteten Metallen bei der Verstärkung maßgefertigter Rüstungen ebenbürtig sein oder sie sogar übertreffen können."},sec={{t="Trophäe aus dem verbrannten Tal",b="Schimären sind wilde, zweiköpfige Bestien, die für ihre Wildheit bekannt sind, doch die älteren Matriarchinnen, die das verbrannte Tal im Steinkrallengebirge durchstreifen, tragen Hörner, die durch Asche, Flammen und das Überleben ungewöhnlich hart geschmiedet wurden. Während gewöhnliche Jungtiere brüchige, geschwärzte Hörner abwerfen, besitzt das Horn der Matriarchin eine natürlich gehärtete Stärke, ähnlich wie behandeltes Metall. Sowohl der Zwergenrüstmeister Furen Longbeard in Stormwind als auch Orm Stonehoof in Thunder Bluff begehren das Horn und fordern es als Prüfung kriegerischen Mutes sowie als entscheidende Zutat für die Herstellung außergewöhnlicher Kettenrüstung ein."}},faq={{q="Woher stammt ein Galvanisiertes Horn?",a="Es wird von Schimärenmatriarchinnen erbeutet, die im verbrannten Tal in den südwestlichen Ausläufern des Steinkrallengebirges hausen.",al={"wo man galvanisiertes horn bekommt","wie man galvanisiertes horn bekommt","galvanisiertes horn beute"}},{q="Warum wollen Schmiede genau dieses Horn?",a="Meisterrüstmeister schätzen das Horn wegen seiner natürlichen Dichte und seiner Hitzebeständigkeit und verwenden es zur Verstärkung spezialisierter Ketten- und Plattenrüstungen.",al={"wofür ist galvanisiertes horn","verwendung galvanisiertes horn"}},{q="Wer nimmt das Galvanisierte Horn an?",a="Für Krieger der Allianz verlangt Furen Longbeard in Stormwind das Horn, um feuergehärtete Rüstungen zu schmieden. Für Krieger der Horde fordert Orm Stonehoof in Thunder Bluff es als Beweis der Stärke, um einen Kriegerhelm anzufertigen.",al={"wer braucht galvanisiertes horn","galvanisiertes horn abgeben"}},{q="Wie unterscheidet es sich von einem regulären Verkohlten Horn?",a="Gewöhnliche verkohlte Hörner lassen sich leicht von niederen Schimärenjungtieren erbeuten. Das galvanisierte Horn stammt ausschließlich von einer ausgewachsenen Matriarchin und besitzt eine weitaus dichtere, gehärtete Struktur, die sich für meisterhafte Schmiedearbeiten eignet.",al={"verkohltes horn vs galvanisiertes horn","unterschied zu verkohltem horn"}}},fp="15,282,26.561.0,39.131.0,38.150.0,32.208.0,47.215.0"}
P.entries["item:gargantuan-tumor"] = {n="Riesengroßer Tumor",s="Der Riesengroße Tumor ist ein gewaltiges, krankhaftes Geschwulst, das der verderbten Holzlingskreatur Grimmeiche auf Teldrassil herausgerissen wurde. Er dient als unübersehbarer Beweis für die unnatürliche Krankheit, die sich unter den Kreaturen des Al'Amethsees ausbreitet.",h="Der Riesengroße Tumor ist ein gewaltiges, krankhaftes Geschwulst, das der verderbten Holzlingskreatur...",kw={"verderbnis","riesengroßer tumor","al'amethsee","grimmeiche","teldrassil","holzling"},ang={["class:Druid"]="Für Druiden, die sich um die jungen Zweige von Teldrassil bemühen, ist der groteske Tumor eine beunruhigende Mahnung daran, wie gefährlich anfällig die Natur in diesen Wipfeln für Verderbnis ist.",["race:NightElf"]="Zu sehen, wie ein angesehener Ältester der Holzlinge zu einem wahnsinnigen, verpesteten Monster herabsank, unterstreicht die wachsenden Umweltprobleme, mit denen die neue Heimat der Kaldorei konfrontiert ist."},sec={{t="Die Seuche über dem See",b="Nahe dem Südufer des Al'Amethsees birgt eine Höhle Grimmeiche, einst ein edler Ältester der Holzlinge, der einer finsteren Heimsuchung anheimgefallen ist. Die Kreatur wurde sichtlich durch ein enormes Geschwür vergiftet, das ihr Verhalten verzerrte und Verderbnis in die umliegende Tierwelt sickern ließ. Das Abtrennen dieses grotesken Tumors ist nicht nur entscheidend, um den gequälten Amoklauf der Bestie zu beenden, sondern ermöglicht es auch den hiesigen Forschern, die Fäulnis zu untersuchen und zu verstehen, wie eine solch üble Krankheit in den Ästen des frisch gewachsenen Weltenbaums Wurzeln schlagen konnte."}},faq={{q="Woher stammt der Riesengroße Tumor?",a="Der Tumor wird von Grimmeiche erbeutet, einem großen, verderbten Holzling, der in einer Höhle am Südufer des Al'Amethsees auf Teldrassil haust.",al={"tumor quelle","wie man riesengroßen tumor bekommt","grimmeiche beute"}},{q="Was lässt den Tumor an Grimmeiche wachsen?",a="Er ist ein äußerliches Symptom der seltsamen Verderbnis, die die Holzlinge und die Tierwelt rund um den Al'Amethsee vergiftet. Grimmeiche war einst ein stolzer Anführer seiner Art, erlag jedoch vollends diesem bösartigen Wuchs.",al={"warum hat grimmeiche einen tumor","holzling krankheit","al'amethsee verderbnis"}},{q="Wer möchte diesen Tumor erforschen?",a="Forscher in der Gegend benötigen den Tumor, um die seltsame Fäulnis zu untersuchen, die die hiesigen Holzlinge befällt, in der Hoffnung herauszufinden, wie die Seuche behandelt oder aufgehalten werden kann.",al={"wer nimmt den tumor","riesengroßen tumor abgeben","grimmeiche quest abgabe"}}},fp="16,222,20.499.0,42.141.0,48.207.0,30.152.0"}
P.entries["item:garrick-s-head"] = {n="Garricks Kopf",s="Garricks Kopf ist der abgetrennte Kopf von Garrick Padfoot, einem berüchtigten Halsabschneider, der in der Nähe der Weinberge des Nordhaintals sein Unwesen trieb. Er dient als grausiger Todesbeweis, um ein von den Behörden der Abtei von Nordhain ausgesetztes Kopfgeld einzufordern.",h="Garricks Kopf ist der abgetrennte Kopf von Garrick Padfoot, einem berüchtigten Halsabschneider, der in der...",kw={"kopfgeld","deputy willem","wald von elwynn","garrick padfoot","garricks kopf","abtei von nordhain","nordhaintal"},ang={["class:Rogue"]="Die Ausschaltung Padfoots zeigt den örtlichen Raufbolden, dass undiszipliniertes Banditentum von tödlicheren, professionelleren Klingen nicht unbeantwortet bleibt.",["race:Human"]="Padfoots Kopf zu erbeuten, markiert einen der ersten entscheidenden Schläge, die ein junger Rekrut aus Stormwind gegen die Gesetzlosigkeit führt, die sich im Wald von Elwynn ausbreitet."},sec={{t="Das Ende eines Banditen",b="Wochenlang schikanierten Garrick Padfoot und seine Bande von Schlägern die einheimischen Bauern und Händler im gesamten Nordhaintal. Garrick nutzte die überdehnten Verteidigungslinien des Königreichs Stormwind aus, verschanzte sich in einer Hütte nahe den Weinbergen von Nordhain und überfiel vorbeiziehende Händler. Da die örtlichen Wachen durch vordringende Kobolde und Defias-Banditen gebunden waren, setzte Deputy Willem ein Kopfgeld auf Padfoots Kopf aus, um einen geschäftstüchtigen Abenteurer zu finden, der den Gesetzlosen beseitigt und einen unbestreitbaren Beweis für sein Ableben vorlegt."}},faq={{q="Wer war Garrick Padfoot?",a="Garrick Padfoot war ein skrupelloser Halsabschneider, der die Bauern, Weinberge und reisenden Händler des Nordhaintals terrorisierte. Er errichtete mit einer Gruppe von Schlägern einen kleinen Außenposten östlich der Abtei von Nordhain jenseits des Flusses.",al={"wer ist garrick","garrick padfoot geschichte","wer war padfoot"}},{q="Warum wird ein abgetrennter Kopf benötigt, um das Kopfgeld einzufordern?",a="Das Grenzrecht im Wald von Elwynn verlangt unwiderlegbare Beweise. Deputy Willem und die Behörden von Nordhain fordern greifbare Beweise für Garricks Ableben, bevor sie die Belohnung auszahlen.",al={"warum sein kopf","todesbeweis","warum garricks kopf nehmen"}},{q="Wo versteckte sich Garrick Padfoot?",a="Padfoot schlug sein Lager an einer kleinen Holzhütte östlich der Abtei von Nordhain auf, jenseits der Flussbrücke nahe den Weinbergen von Nordhain.",al={"wo ist garrick","standort garricks hütte","wo man garrick padfoot findet"}},{q="Wer zahlt das Kopfgeld für Garricks Kopf?",a="Deputy Willem, der direkt vor dem Eingang der Abtei von Nordhain stationiert ist, hat das Kopfgeld ausgesetzt und zahlt es nach Erhalt des Kopfes aus.",al={"wer will garricks kopf","garricks kopf abgeben","wer garricks kopf abgab"}}},fp="14,229,14.485.0,24.222.0,51.190.0,33.139.0,39.130.0"}
P.entries["item:gazlowe-s-ledger"] = {n="Gazlowes Geschäftsbuch",s="Gazlowes Geschäftsbuch ist eine detaillierte Aufzeichnung von Handelsgütern und Beständen, die vom Goblinboss von Ratchet geführt wird. Es dient als Abrechnungsbuch, um aus Booty Bay eintreffende Frachtlieferungen mit dem Hafenmanifest abzugleichen.",h="Gazlowes Geschäftsbuch ist eine detaillierte Aufzeichnung von Handelsgütern und Beständen, die vom Goblinboss...",kw={"booty bay","dizzywig","freibeuter","gazlowe","geschaeftsbuch","ratchet","lieferung","dampfdruck"},ang={["class:Rogue"]="Das private Handelsbuch eines Goblinbosses bietet einen interessanten Einblick in den Fluss von Schmuggelware, wertvollen Importen und Piraterie an der Küste des Brachlands.",["faction:Horde"]="Ratchet fungiert als neutraler Hafen, der den Handel mit der Horde begrüßt; Gazlowe dabei zu helfen, gestohlene Lieferungen aufzuspüren, sichert ein gutes Ansehen bei den örtlichen Behörden des Dampfdruckkartells."},sec={{t="Ratchets Handelsaufzeichnungen",b="Die Beaufsichtigung eines geschäftigen Handelshafens wie Ratchet erfordert eine akribische Buchführung. Gazlowe führt dieses persönliche Hauptbuch, um importierte Kisten, ausgehende Fracht und Lagerbestände nachzuverfolgen. Als eine lang erwartete Lieferung aus Booty Bay unauffindbar bleibt, nutzt Gazlowe das Buch, um sein voraussichtliches Inventar mit den maritimen Aufzeichnungen abzugleichen, die unten an den Docks von Werftmeister Dizzywig geführt werden."},{t="Aufdeckung des Diebstahls",b="Durch den direkten Abgleich der Bucheinträge mit Dizzywigs Hafenprotokollen bestätigen die Goblins, dass die Fracht das Lagerhaus des Hafens nie erreicht hat. Die Diskrepanz bestätigt Gazlowes Verdacht, dass die fehlenden Kisten das Wasser nie unversehrt verlassen haben, und weist eindeutig auf die Südmeerfreibeuter hin, die entlang der nahe gelegenen Händlerküste operieren."}},faq={{q="Was ist Gazlowes Geschäftsbuch?",a="Es ist Gazlowes persönliches Inventarbuch, das Aufzeichnungen über in Ratchet erwartete und gelagerte Waren enthält. Gazlowe schickt es zu den Docks, um es mit den Werftaufzeichnungen abzugleichen, wenn eingehende Lieferungen fehlen.",al={"gazlowes geschaeftsbuch","ratchet geschaeftsbuch","gazlowe inventarbuch"}},{q="Wer muss das Geschäftsbuch einsehen?",a="Werftmeister Dizzywig, der die Docks von Ratchet beaufsichtigt, gleicht das Geschäftsbuch mit seinen eigenen Frachtlisten ab, um festzustellen, ob die fehlenden Waren verlegt oder gar nicht erst entladen wurden.",al={"wem bringe ich das geschaeftsbuch","empfaenger des geschaeftsbuchs","dizzywig geschaeftsbuch"}},{q="Welche Fracht fehlte im Geschäftsbuch?",a="Gazlowe wartete auf eine reguläre Warenlieferung aus Booty Bay. Dizzywig vermutet insbesondere, dass Gazlowe wegen eines fehlenden Paars Stiefel von Drizzlek besorgt ist.",al={"was fehlt gazlowe","fehlende lieferungsfracht"}},{q="Was geschieht, nachdem das Geschäftsbuch überprüft wurde?",a="Sobald Dizzywig bestätigt, dass die Lieferung die Docks nie passiert hat, wird das Geschäftsbuch an Gazlowe zurückgegeben, was bestätigt, dass Piraten der Südmeerfreibeuter die Fracht wahrscheinlich auf See abgefangen haben.",al={"was passiert mit dem geschaeftsbuch","nach dizzywigs pruefung"}}},fp="16,220,28.388.0,20.351.1,25.199.0,32.175.0,37.163.0,41.188.1"}
P.entries["item:gem-of-anacondra"] = {n="Edelstein von Anacondra",s="Der Edelstein von Anacondra ist einer von vier Traumsteinen, die von den verderbten Schlangenanführern in den Höhlen des Wehklagens getragen werden. Er wird von Lady Anacondra mitgeführt und dient als greifbarer Beweis für ihre Niederlage sowie die Eindämmung der Ausbreitung des Alptraums über das Brachland.",h="Der Edelstein von Anacondra ist einer von vier Traumsteinen, die von den verderbten Schlangenanführern in den...",kw={"traumstein","druiden des giftzahns","edelstein von anacondra","lady anacondra","anführer der giftzähne","nara wildmane","die höhlen des wehklagens"},ang={["class:Druid"]="Für cenarische Druiden ist die Erbeutung dieses Steins eine feierliche Pflicht, eine Schwester niederzustrecken, die ihren Verstand und ihre Gestalt dem verderbenden Smaragdgrünen Alptraum opferte.",["race:Tauren"]="Die Bergung des Steins hilft Nara Wildmane in Thunder Bluff unmittelbar und vertreibt die finsteren Visionen, die den Schlummer der Shu'halo auf der Anhöhe der Ältesten heimsuchen."},sec={{t="Ein verderbter Fokus",b="Als Naralex in seinen tiefen Schlummer fiel, um dem dürren Brachland Wasser und neues Leben zu schenken, drang der Smaragdgrüne Alptraum in seine Gedanken ein und verzerrte seine engsten Schüler. Lady Anacondra und ihre Mitverschwörer verließen ihre traditionellen Wege, um zu Druiden des Giftzahns zu werden, und verkehrten ihre edle heilende Bestimmung in einen toxischen Wahn. Der Edelstein von Anacondra ist einer der vier Traumsteine, die von diesen Schlangenanführern getragen werden, wodurch ihre verderbte Verbindung mit dem Smaragdgrünen Traum gebündelt und der Alptraum im Höhlensystem verankert wird."},{t="Die Läuterung der Vision",b="Nara Wildmane und der Zirkel der cenarischen Druiden in Thunder Bluff sahen ihren eigenen Schlummer von den Visionen und boshaften Gesichtern der Anführer der Giftzähne geplagt. Den Edelstein von Anacondra an sich zu bringen – zusammen mit den Steinen von Cobrahn, Pythas und Serpentis – ist notwendig, um zu bestätigen, dass Lady Anacondra niedergestreckt wurde, was den bedrückenden Alptraum aus dem Geist der Hüter des Gleichgewichts von Kalimdor bannt."}},faq={{q="Was ist der Edelstein von Anacondra?",a="Es ist ein Traumstein, der von Lady Anacondra getragen wird, einer der vier Anführer der verderbten Druiden des Giftzahns, die in den Höhlen des Wehklagens verweilen.",al={"was ist der edelstein von anacondra","edelstein von anacondra","was bringt der edelstein von anacondra"}},{q="Wer benötigt diesen Edelstein?",a="Nara Wildmane, eine Taurendruidin auf der Anhöhe der Ältesten in Thunder Bluff, sucht diesen Stein gemeinsam mit den anderen drei Traumsteinen, um ihren Geist von Alpträumen zu befreien und das Brachland zu schützen.",al={"wer braucht den edelstein von anacondra","wo gibt man den edelstein von anacondra ab","edelstein von anacondra abgabe"}},{q="Wo kann der Edelstein von Anacondra gefunden werden?",a="Der Stein wird von Lady Anacondra getragen, die in den verschlungenen unterirdischen Tunneln der Höhlen des Wehklagens im zentralen Brachland lauert.",al={"wo droppt er","wer droppt den edelstein von anacondra","lady anacondra aufenthaltsort"}},{q="Warum sind die Traumsteine wichtig?",a="Die vier Steine befinden sich im Besitz der verderbten Anführer der Druiden des Giftzahns. Sie zu sammeln bestätigt, dass die Rädelsführer beseitigt wurden, wodurch ihr Einfluss auf die Verderbnis des Smaragdgrünen Traums in der Region gebrochen wird.",al={"warum vier edelsteine","zweck der traumsteine","anführer der giftzähne edelsteine"}}},fp="16,241,17.531.0,20.388.1,29.139.0,19.183.0,40.149.0,33.205.0"}
P.entries["item:gem-of-cobrahn"] = {n="Edelstein von Kobrahn",s="Der Edelstein von Kobrahn ist ein Traumedelstein, den Lord Kobrahn bei sich trägt, einer der verderbten Anführer der Druids of the Fang in den Höhlen des Wehklagens. Er dient sowohl als Fokus seiner verderbten Träumerei als auch als physischer Beweis, den Nara Wildmane benötigt, um seine Niederlage zu bestätigen.",h="Der Edelstein von Kobrahn ist ein Traumedelstein, den Lord Kobrahn bei sich trägt, einer der verderbten...",kw={"traumedelstein","druids of the fang","edelstein von kobrahn","anführer der giftzähne","lord kobrahn","nara wildmane","die höhlen des wehklagens"},ang={["class:Druid"]="Für cenarische Druiden markiert die Rückholung des Edelsteins von Kobrahn das tragische, aber notwendige Ende eines gefallenen Bruders, der die Harmonie der Natur für den Smaragdgrünen Alptraum aufgab.",["race:Tauren"]="Die Druiden von Thunder Bluff wachen aufmerksam über das Brachland; die Erbeutung von Kobrahns Edelstein schützt die Ebenen und Jagdgründe unmittelbar vor unnatürlicher Verderbnis."},sec={{t="Ein Fokus verderbter Träume",b="Als der Nachtelfendruide Naralex in den Smaragdgrünen Traum eintrat, um die kargen Ebenen von Kalimdor wiederherzustellen, verzerrte sein Alptraum sowohl die Höhlen des Wehklagens als auch seine Jünger. Unter ihnen war Kobrahn, der die friedlichen Pfade des Zirkels des Cenarius aufgab, um die Gestalt der Schlange anzunehmen. Lord Kobrahn trägt einen der vier Traumedelsteine bei sich, welche die Macht der Anführer über die unterirdischen Wasserwege verankern, und nutzt ihn, um die verzerrten Träume zu kanalisieren, die das Brachland in einen giftigen Sumpf zu verwandeln drohen."},{t="Das Gleichgewicht wiederherstellen",b="In Thunder Bluff wird die Taurendruidin Nara Wildmane von Alpträumen gequält, die von den abtrünnigen Druids of the Fang gesandt werden. Um die unterirdischen Quellen zu reinigen und Kalimdor vor ihrer Vision zu schützen, müssen Abenteurer in die Höhlen vordringen, Lord Kobrahn zusammen mit seinen drei Mitverschwörern erschlagen und ihre Traumedelsteine bergen. Die Rückgabe von Kobrahns Edelstein an die cenarischen Druiden setzt seinem verderbenden Einfluss auf den schlummernden Naralex ein Ende."}},faq={{q="Was ist der Edelstein von Kobrahn?",a="Es ist ein Traumedelstein im Besitz von Lord Kobrahn, einem gefallenen Druiden, der die Druids of the Fang in den Höhlen des Wehklagens anführt. Er dient als Kanal für seine alptraumverzerrten Kräfte.",al={"edelstein von kobrahn","kobrahn edelstein","was ist kobrahns edelstein"}},{q="Wer benötigt den Edelstein von Kobrahn?",a="Nara Wildmane, eine Taurendruidin auf der Anhöhe der Ältesten in Thunder Bluff, verlangt den Edelstein zusammen mit drei weiteren, um den Druids of the Fang ein Ende zu bereiten.",al={"wer braucht edelstein von kobrahn","kobrahn edelstein abgeben","wer nimmt kobrahns edelstein"}},{q="Wie viele Edelsteine werden benötigt, um die Quest abzuschließen?",a="Vier Edelsteine sind erforderlich: der Edelstein von Kobrahn, der Edelstein von Anacondra, der Edelstein von Pythas und der Edelstein von Serpentis, die jeweils von einem der vier Schlangenanführer in den Höhlen getragen werden.",al={"wie viele traumedelsteine","anführer der giftzähne edelsteine","alle giftzahn edelsteine"}},{q="Wer ist Lord Kobrahn?",a="Lord Kobrahn war einst ein Jünger von Erzextruide Naralex. Als Naralex' Vision zu einem Alptraum wurde, nahmen Kobrahn und mehrere andere Druiden die Gestalt der Schlange an und gründeten die Druids of the Fang.",al={"wer ist kobrahn","lord kobrahn lore","kobrahn"}}},fp="14,256,27.491.0,17.430.1,27.170.0,29.155.0,47.171.0,20.202.0"}
P.entries["item:gem-of-pythas"] = {n="Edelstein von Pythas",s="Der Edelstein von Pythas ist einer von vier verdorbenen Traumsteinen, die von den Anführern der Druiden des Giftzahns in den Höhlen des Wehklagens getragen werden. Von Lord Pythas verwahrt, nährt er den Alptraum, der die unterirdische Oase verzerrt und das Brachland bedroht.",h="Der Edelstein von Pythas ist einer von vier verdorbenen Traumsteinen, die von den Anführern der Druiden des...",kw={"brachland","traumstein","druiden des giftzahns","edelstein von pythas","lord pythas","nara wildmane","die höhlen des wehklagens"},ang={["class:Druid"]="Für die Druiden des Cenarius ist die Bergung des Steins eine düstere Pflicht, da er den vollkommenen Niedergang von Naralex' engstem Kreis zu schlangenartigen Schrecken darstellt.",["race:Tauren"]="Die verdrehten Rituale in den Höhlen bedrohen das fragile Gleichgewicht des Brachlands, weshalb die Bergung dieser Steine unerlässlich ist, um die Heimat der Schamanen und Druiden zu schützen."},sec={{t="Ein Gefäß des Alptraums",b="Als Naralex den Smaragdgrünen Traum betrat, um das verdorrte Brachland wiederherzustellen, wurde seine edle Vision in einen lebenden Alptraum verzerrt. Seine treuesten Gefolgsleute fielen mit ihm, nannten sich fortan die Druiden des Giftzahns und strebten danach, die Oberwelt in einen giftigen Dschungel zu verwandeln. Lord Pythas trägt diesen widerhallenden Stein bei sich, einen von vier Traumsteinen, die das Verderben in den Höhlen verankern. Der Stein dient als Kanal für ihre finsteren Pläne und als Beweis für die Druiden von Thunder Bluff, dass Pythas' verdrehte Trance endlich gebrochen wurde."}},faq={{q="Wofür wird der Edelstein von Pythas verwendet?",a="Der Edelstein wird zusammen mit den Steinen von Kobrahn, Anacondra und Serpentis zu Nara Wildmane nach Thunder Bluff gebracht. Zusammen erfüllen sie die Aufgabe, den abtrünnigen Anführern der Druiden des Giftzahns ein Ende zu bereiten.",al={"edelstein von pythas nutzen","was tun mit edelstein von pythas","edelstein von pythas quest"}},{q="Wer trägt diesen Edelstein bei sich?",a="Er wird von Lord Pythas verwahrt, einem gefallenen Nachtelfendruiden, der tief in den Höhlen des Wehklagens im Brachland haust.",al={"wer lässt edelstein von pythas fallen","pythas aufenthaltsort","woher bekommt man edelstein von pythas"}},{q="Warum wollen die Druiden von Thunder Bluff den Edelstein haben?",a="Nara Wildmane und die Druiden des Cenarius in Thunder Bluff werden von dem Verderben heimgesucht, das von den Höhlen des Wehklagens ausgeht. Das Bergen der Steine beweist, dass die vier abgefallenen Anführer bezwungen wurden, und verhindert, dass der Alptraum weiter ins Brachland vordringt.",al={"warum will nara steine","nara wildmane pythas"}},{q="Gibt es noch weitere Steine wie diesen?",a="Ja. Lord Pythas ist einer von vier Anführern. Die anderen – Lady Anacondra, Lord Kobrahn und Lord Serpentis – tragen jeweils ihren eigenen Traumstein tief im Inneren der Höhle bei sich.",al={"andere traumsteine","giftzahnsteine","höhlen des wehklagens steine"}}},fp="13,235,25.518.0,35.209.0,21.111.0,48.259.0,35.159.0"}
P.entries["item:gem-of-serpentis"] = {n="Edelstein von Serpentis",s="Der Edelstein von Serpentis ist ein Traumjuwel, das von Lord Serpentis getragen wird, dem selbsternannten Anführer der Druids of the Fang in den Höhlen des Wehklagens. Er dient als fokussierender Kanal für den verzerrten Alptraum, der das Höhlennetzwerk umgestaltet und das Brachland bedroht.",h="Der Edelstein von Serpentis ist ein Traumjuwel, das von Lord Serpentis getragen wird, dem selbsternannten...",kw={"druids of the fang","edelstein von serpentis","anführer der giftzähne","lord serpentis","nara wildmane","brachland","die höhlen des wehklagens"},ang={["class:Druid"]="Die von Serpentis und seiner Kabale getragenen Traumjuwelen veranschaulichen das furchtbare Risiko, ohne wachsame spirituelle Disziplin in eine tiefe Trance-Kommunion mit dem Traum einzutauchen.",["race:Tauren"]="Das Brechen von Serpentis' Herrschaft über diesen Edelstein hilft dabei, die Schamanen und Druiden von Thunder Bluff von den dunklen Visionen zu befreien, die ihren Schlaf in ganz Mulgore stören."},sec={{t="Herz des schlangengleichen Traums",b="Als Naralex' Schlaf in den Höhlen des Wehklagens dem Smaragdgrünen Alptraum erlag, wurden seine treuesten Anhänger in die fanatischen Druids of the Fang verwandelt. An der Spitze dieser Kabale steht Lord Serpentis. Wie seine drei schlangenhaften Leutnants trägt Serpentis ein verzaubertes Traumjuwel, das ihren gemeinsamen Willen an die verdorbene Vision bindet. Die Bergung dieses Juwels bricht Serpentis' Herrschaft über das Ökosystem der Höhle und trifft die Führung direkt, die für die Ausbreitung der Verderbnis über das Brachland verantwortlich ist."},{t="Beweis für Thunder Bluff",b="Die Taurendruiden auf der Anhöhe der Ältesten in Thunder Bluff, insbesondere Nara Wildmane, leiden unter lebhaften Alpträumen, die durch die unter der Savanne lauernde Verderbnis verursacht werden. Die Bergung des Edelsteins von Serpentis zusammen mit denen von Cobrahn, Anacondra und Pythas liefert den greifbaren Beweis dafür, dass die Rädelsführer des abtrünnigen Ordens gefallen sind, und schwächt den Einfluss des Alptraums auf den Zirkel des Cenarius in Mulgore."}},faq={{q="Woher stammt der Edelstein von Serpentis?",a="Der Edelstein wird von Lord Serpentis getragen, dem Anführer der Druids of the Fang, der tief in den verwinkelten Wasserwegen der Höhlen des Wehklagens haust.",al={"wer droppt edelstein von serpentis","wo gibt es serpentis edelstein","fundort serpentis edelstein"}},{q="Was ist der Zweck des Edelsteins?",a="Er dient als einer von vier Fokussteinen, die von den Anführern der Druids of the Fang verwendet werden, um den Alptraum zu kanalisieren, der die unterirdische Oase verzerrt. Nara Wildmane in Thunder Bluff verlangt ihn als Beweis dafür, dass Lord Serpentis besiegt wurde.",al={"wofür edelstein von serpentis","nutzen edelstein von serpentis"}},{q="Wer möchte alle vier Traumjuwelen haben?",a="Nara Wildmane, eine Druidin auf der Anhöhe der Ältesten in Thunder Bluff, bittet Abenteurer darum, ihr die Edelsteine von Cobrahn, Anacondra, Pythas und Serpentis zu bringen, um den Einfluss des Alptraums auf die Region zu brechen.",al={"wer nimmt die edelsteine","serpentis edelstein abgeben","anführer der giftzähne abgeben"}},{q="Wer war Lord Serpentis, bevor er diesen Edelstein trug?",a="Ursprünglich war er ein Schüler von Naralex, der die Höhlen betrat, um das Brachland wieder in fruchtbares Leben zu tauchen. Doch der Smaragdgrüne Alptraum verdrehte seine edlen Absichten in das fanatische Verlangen, die Welt in Schlangengestalt neu zu erschaffen.",al={"lord serpentis lore","wer ist serpentis"}}},fp="16,246,29.518.0,23.375.1,42.145.0,31.226.0,30.199.0,48.227.0"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Gerenzos mechanischer Arm",s="Gerenzos mechanischer Arm ist das transplantierte Prothesenglied, das dem abtrünnigen Ingenieur Gerenzo Wrenchwhistle im Steinkrallengebirge abgenommen wurde. Es dient Goblin-Agenten, die die Konkurrenz ausschalten wollen, als unverkennbarer Beweis für sein Ableben.",h="Gerenzos mechanischer Arm ist das transplantierte Prothesenglied, das dem abtrünnigen Ingenieur Gerenzo...",kw={"arm","felskesselsee","gerenzo","mechanischer arm","sputtervalve","steinkrallengebirge","wrenchwhistle","ziz fizziks"},ang={["profession:Engineering"]="Der Arm veranschaulicht die gegensätzlichen Denkweisen der beiden Ingenieurstraditionen: Gnome opfern bereitwillig ihre eigene Biologie für mechanische Präzision, während Goblins externe Erweiterungen und rohe Feuerkraft bevorzugen.",["race:Gnome"]="Gerenzo stellt ein düsteres Extrem gnomischer Erfindungsgabe dar, da er den mechanischen Ersatz weit über konventionelle medizinische Prothesen hinaus zu einer morbiden Selbstoptimierung trieb."},sec={{t="Eine bizarre Erfindung",b="Gerenzo Wrenchwhistle trieb die Selbstmodifikation auf ein groteskes Extrem, indem er surrende Zahnräder und Metall direkt auf seinen verfallenden Körper transplantierte. Hoch über dem Felskesselsee ersetzte der abtrünnige Gnom natürliche Gliedmaßen durch komplizierte Maschinerie. Als der Goblin-Tüftler Ziz Fizziks Gerenzos Beseitigung anstrebt, um seinen Vorgesetzten zu imponieren, ist dieser unverwechselbare mechanische Arm die einzige Trophäe, die einzigartig genug ist, um als unbestreitbarer Beweis für den Tod des Ingenieurs zu dienen."},{t="Gnomische Philosophie, Goblin-Kritik",b="Für den Goblin-Verstand ergibt es wenig Sinn, einen voll funktionsfähigen Arm zu amputieren, nur um einen mechanischen Ersatz anzubringen. Ziz Fizziks bemerkte treffend, dass ein richtiger Goblin-Ingenieur einfach beide biologischen Arme behalten und stattdessen einen mechanischen dritten montieren würde. Trotz der philosophischen Kluft stellt die Ablieferung des abgetrennten Glieds Sputtervalve zufrieden und hilft Ziz dabei, ein Gesuch für eine Zuweisung in Gadgetzan oder Lorelei einzureichen."}},faq={{q="Woher stammt Gerenzos mechanischer Arm?",a="Er wird Gerenzo Wrenchwhistle abgenommen, der hoch über dem Felskesselsee nahe dem Wasserrad im Steinkrallengebirge die Holzfäller- und Ingenieursarbeiten überwacht.",al={"wer lässt gerenzos arm fallen","gerenzos arm fundort","wo gerenzos mechanischen arm bekommen"}},{q="Warum will Ziz Fizziks diesen Arm?",a="Ziz benötigt für seinen Vorgesetzten Sputtervalve einen endgültigen Beweis dafür, dass Gerenzo tot ist. Da Gerenzo seinen eigenen Körper stark verändert hat, ist seine einzigartige Armprothese unmöglich zu fälschen oder mit der eines anderen zu verwechseln.",al={"warum will ziz arm","arm quest abgeben","beweis für gerenzos tod"}},{q="Warum hat Gerenzo seinen eigenen Arm ersetzt?",a="Laut Ziz Fizziks schien Gerenzos Fleisch wegzufaulen. Getrieben von Verzweiflung oder obsessiver gnomischer Experimentierfreude transplantierte Gerenzo Maschinerie und ersetzte seine versagenden Gliedmaßen durch mechanische Gegenstücke.",al={"warum ist gerenzo ein cyborg","gerenzo faulendes fleisch","warum mechanischer arm"}}},fp="24,238,19.444.0,35.412.1,46.162.0,35.205.0,36.217.0"}
P.entries["item:ghost-hair-comb"] = {n="Geisterhaarkamm",s="Der Geisterhaarkamm ist ein unheimliches Pflegewerkzeug, in dem sich die gespenstischen Strähnen des Geistes Die blinde Mary verfangen haben. Von Madame Eva zu dem Geist gesandt, wird der Kamm zu einem Instrument tragischer Erkenntnis, bevor das gesammelte Haar zu unheimlichem Faden gesponnen wird.",h="Der Geisterhaarkamm ist ein unheimliches Pflegewerkzeug, in dem sich die gespenstischen Strähnen des Geistes...",kw={"die blinde mary","dunkelhain","dämmerwald","geisterhaarkamm","geisterhaarfaden","madame eva"},ang={["class:Priest"]="Marys qualvolle Reaktion auf den Kamm spiegelt die verbliebene sterbliche Eitelkeit und die tiefe seelische Qual wider, die unter den ruhelosen Toten des Dämmerwalds weit verbreitet sind.",["profession:Tailoring"]="Die ätherischen Strähnen, die aus dem Kamm gezupft werden, stellen ein unheimliches Textil dar, das nicht von Schafen oder Seidenraupen gewonnen, sondern direkt aus spektralem Kummer gesponnen wird."},sec={{t="Eine tragische Eitelkeit",b="Madame Eva aus Dunkelhain schickt den Kamm zu dem heimgesuchten Geist Die blinde Mary, die in einer einsamen, baufälligen Behausung am Rande vom Dämmerwald verweilt. Als ihr der Kamm überreicht wird, weicht der Geist in purem Entsetzen zurück, plötzlich mit der erschütternden Realität konfrontiert, dass sie nicht mehr die liebliche, lebende Frau von einst ist. In ihrer Trauer und Verzweiflung stößt Mary den Kamm von sich, wodurch er sich mit Strähnen ihres eigenen geisterhaften Haares verheddert."},{t="Aus Kummer gesponnen",b="Zurückgebracht zu Madame Eva in Dunkelhain, dient das in den Zinken des Kamms verfangene Haar einem weitaus esoterischeren Zweck. Eva sammelt die zarten spektralen Fasern, um sie zu Geisterhaarfaden zu spinnen, einem mystischen Handwerksmaterial, mit dem okkulte Schöpfungen im schattenhaften Reich vom Dämmerwald genäht und gebunden werden."}},faq={{q="Was ist der Geisterhaarkamm?",a="Es ist ein Kamm, der von Madame Eva aus Dunkelhain zu dem Geist Die blinde Mary geschickt wurde. Nachdem Mary ihn benutzt oder von sich geworfen hat, verfangen sich Strähnen ihres spektralen Haares darin, die Eva anschließend zu Geisterhaarfaden spinnt.",al={"geisterhaarkamm","was ist dieser kamm","evas kamm"}},{q="Warum schreit Die blinde Mary und weist den Kamm ab?",a="Der Kamm erinnert Die blinde Mary an ihre verlorene sterbliche Schönheit. Ihn zu erhalten zwingt sie dazu, sich ihrer wahren Natur als furchterregende, gespenstische Monstrosität zu stellen, anstatt der lieblichen Frau, an die sie sich aus Lebzeiten erinnert.",al={"warum schreit die blinde mary","die blinde mary kamm reaktion","warum hat mary den kamm weggeworfen"}},{q="Wer möchte den Kamm zurückhaben?",a="Madame Eva, die ansässige Wahrsagerin und Heckenmagierin in der Stadt Dunkelhain, bittet darum, dass der Kamm zu ihr zurückgebracht wird, damit sie das darin gefangene Geisterhaar ernten kann.",al={"wer will den kamm","wohin mit dem kamm","kamm zu wem zurückbringen"}},{q="Wofür wird das Geisterhaar verwendet?",a="Madame Eva spinnt die aus dem Kamm gesammelten geisterhaften Strähnen zu Geisterhaarfaden, einem ungewöhnlichen Reagenz, das für okkulte Rituale und Handwerksarbeiten im Dämmerwald benötigt wird.",al={"verwendung von geisterhaar","was ist geisterhaarfaden","zweck von geisterhaarfaden"}}},fp="15,247,15.431.0,16.300.1,28.194.0,47.202.0,28.167.0,32.157.0"}
P.entries["item:ghost-hair-thread"] = {n="Geisterhaarfaden",s="Geisterhaarfaden ist ein seltenes, übernatürliches Material, das von Madame Eva in Dunkelhain gesponnen wird. Erfüllt von mächtigen okkulten Eigenschaften, soll er spirituelle Energien binden und sogar Leben in unbelebte Dinge einnähen können. Der Einsiedler Calvinius bittet unter dem Vorwand darum, damit seine baufällige Hütte vor ruhelosen Geistern zu schützen.",h="Geisterhaarfaden ist ein seltenes, übernatürliches Material, das von Madame Eva in Dunkelhain gesponnen wird.",kw={"calvinius","dunkelhain","dämmerwald","geisterhaarfaden","madame eva","rabenflucht","geister"},ang={["class:Warlock"]="Die Fähigkeit des Fadens, spirituelle Wesenheiten zu binden und unbelebte Materie mit Leben zu erfüllen, spiegelt die dunklen Künste der Seelenmanipulation und Konstruktbindung wider.",["profession:Tailoring"]="Während gewöhnliche Schneider mit Wolle, Seide und Magiestoff arbeiten, beweist Madame Evas geisterhafter Faden, dass Stoff direkt aus übernatürlichen Essenzen gesponnen werden kann, um Verzauberungen in sich zu tragen."},sec={{t="Aus der Geisterwelt gesponnen",b="Von der Wahrsagerin Madame Eva in Dunkelhain gesponnen, ist Geisterhaarfaden weit mehr als ein gewöhnlicher Schneiderbedarf. Laut Eva besitzt der spektrale Faden vielseitige okkulte Eigenschaften, die vom Binden bösartiger Geister bis hin zum Einnähen von Lebenskraft in unbelebte Objekte reichen. Seine ätherische Natur macht ihn zu einem wertvollen Gut für Rituale und Schutzzauber im verfluchten Reich des Dämmerwalds."},{t="Calvinius' Schutzzauber",b="Der zurückgezogen lebende Einsiedler Calvinius, der in einer baufälligen Hütte nördlich des Friedhofs von Rabenflucht haust, bittet Reisende darum, den Faden aus Dunkelhain zu beschaffen. Er behauptet, den Faden dringend über seine Fenster und seinen Türrahmen spannen zu müssen, um die umherwandernden Untoten des Friedhofs daran zu hindern, in sein Heim einzudringen. Doch angesichts der seltsamen Fähigkeit des Fadens, lebloser Materie Leben einzunähen, bleibt sein eigentlicher Zweck ein beunruhigendes Geheimnis."}},faq={{q="Was ist Geisterhaarfaden?",a="Es ist ein arkanes Handwerksmaterial, das von Madame Eva in Dunkelhain gesponnen wird. Es besitzt ausgeprägte okkulte Eigenschaften, mit denen Geister gebunden oder unbelebten Dingen Leben eingenäht werden kann.",al={"geisterhaar","was ist geisterhaarfaden","geisterfaden"}},{q="Warum will Calvinius Geisterhaarfaden haben?",a="Calvinius behauptet, er benötige den Faden, um seine Fenster und seine Türöffnung zu bespannen und so eine schützende Barriere zu errichten, die die ruhelosen Geister abwehrt, die draußen nahe dem Friedhof von Rabenflucht umherwandern.",al={"calvinius faden","warum calvinius faden will","calvinius schutz"}},{q="Wer stellt den Faden her?",a="Madame Eva, die ortsansässige Seherin und Wahrsagerin von Dunkelhain, fertigt und überreicht den Faden auf Anfrage.",al={"wer spinnt geisterhaarfaden","madame eva faden"}},{q="Können Spieler den Faden für die Schneiderei verwenden?",a="Nein. Trotz seines Namens und seiner magischen Eigenschaften ist er ein spezieller Questgegenstand, der ausschließlich für die Übergabe an Calvinius bestimmt ist, und kann nicht für herkömmliche Handwerksrezepte genutzt werden.",al={"schneiderei geisterhaarfaden","kann man mit geisterhaarfaden herstellen"}}},fp="17,313,24.380.0,18.431.1,26.167.0,44.178.0,21.110.0,41.166.0"}
P.entries["item:ghoul-fang"] = {n="Ghulfangzahn",s="Ghulfangzähne sind grausige Trophäen, die von den Untoten erbeutet werden, welche die verheerten Haine und Friedhöfe des Dämmerwalds durchstreifen. In Dunkelhain nutzt die Seherin Madame Eva sie als wesentliche Bestandteile für die Herstellung defensiver Talismane für Reisende, die sich der herannahenden Dunkelheit stellen.",h="Ghulfangzähne sind grausige Trophäen, die von den Untoten erbeutet werden, welche die verheerten Haine und...",kw={"dunkelhain","dämmerwald","ghulfangzahn","ghule","madame eva","totem des gegenschlages","untote"},ang={["faction:Alliance"]="Für Abenteurer der Allianz, die dem bedrängten Dunkelhain beistehen, hilft das Erbeuten dieser Zähne dabei, die Schrecken des Dämmerwalds in Werkzeuge des Überlebens gegen das herandrängende, geißelartige Verderben zu verwandeln."},sec={{t="Trophäen der rastlosen Toten",b="Der schattenhafte Forst des Dämmerwalds wimmelt von unersättlichen Untoten – von Fleischfressern, die in der Nähe von Gräbern lauern, bis hin zu verrotteten Leichen, die durch die Wälder streifen. Diesen monströsen Kreaturen einen Fangzahn zu entreißen, ist zugleich finstere Arbeit und Beweis für das Überleben gegen die gefräßigen Toten, die Dunkelhains Grenzen bedrohen."},{t="Okkulte Reagenzien",b="Madame Eva, die ansässige Wahrsagerin und Mystikerin in Dunkelhain, sieht schreckliche Omen um Reisende kreisen, die es wagen, den Dämmerwald zu durchqueren. Sie bindet die latente nekrotische Essenz von Ghulfangzähnen zusammen mit Skelettfingern und Spinnengift, um das Totem des Gegenschlages zu verzaubern, wodurch die dunklen Mächte des Waldes in einen Schutzzauber gegen gewaltsame Angriffe verwandelt werden."}},faq={{q="Wo sind Ghulfangzähne zu finden?",a="Sie werden von verschiedenen Arten von Ghulen im gesamten Dämmerwald erbeutet, darunter Seuchenverbreiter, Gehirnfresser, Knochenkauer, übelriechende Leichen, Verrottete und Fleischfresser, die Friedhöfe und einsame Pfade heimsuchen.",al={"wo droppen ghulfangzähne","wer droppt ghulfangzähne","fundort ghulfangzahn"}},{q="Wer benötigt Ghulfangzähne?",a="Madame Eva, die in Dunkelhain ansässige Mystikerin, benötigt sie als Teil eines Rituals zur Herstellung eines defensiven Talismans, der als Totem des Gegenschlages bekannt ist.",al={"wer braucht ghulfangzähne","ghulfangzahn abgabe","madame eva quest"}},{q="Warum braucht Madame Eva sie?",a="Eva spürt die drohende Gefahr für Reisende und nutzt die Zähne zusammen mit Skelettfingern und Spinnengift, um ein schützendes Totem zu verzaubern, das jeden straft, der den Träger angreift.",al={"warum ghulfangzähne","totem des gegenschlages materialien","was macht madame eva mit fangzähnen"}}},fp="10,263,29.285.0,15.364.0,31.211.0,22.140.0,30.175.0"}
P.entries["item:ghoul-rib"] = {n="Ghulrippe",s="Ghulrippen werden von den Untoten erbeutet, die durch die heimgesuchten Haine und Friedhöfe des Dämmerwalds streifen. Der Einsiedler Calvinius behauptet, sie als Material für den Bau eines grotesken Bildnisses zu benötigen, um die fleischfressenden Schrecken in der Nähe seiner Hütte abzuwehren.",h="Ghulrippen werden von den Untoten erbeutet, die durch die heimgesuchten Haine und Friedhöfe des Dämmerwalds...",kw={"calvinius","bettlerschlupfwinkel","bone chewer","dunkelhain","dämmerwald","flesh eater","ghulrippe","ein ghulbildnis","untote"},ang={["class:Paladin"]="Der Umgang mit den geschändeten Gebeinen der rastlosen Toten ist eine widerwärtige Aufgabe, doch einem isolierten Einsiedler gegen unersättliche Monstrositäten beizustehen, deckt sich mit dem Schutz der Lebenden vor den Schrecken des Dämmerwalds.",["class:Priest"]="Die finstere Reanimation, die diese Knochen bindet, spiegelt den tiefen Schatten wider, der sich über den Dämmerwald gelegt hat und gefallene Dorfbewohner in unersättliche Aasfresser verwandelt."},sec={{t="Ein grausiger Schutz",b="Der verfluchte Wald des Dämmerwalds wimmelt von gewalttätigen Untoten, darunter unersättliche Ghule wie Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones und Plague Spreaders. Calvinius, ein exzentrischer Einsiedler, der isoliert in einer Hütte nördlich des Friedhofs von Rabenflucht lebt, erbittet diese zähen, verrotteten Knochen von durchreisenden Wanderern. Er behauptet, dass ihn das Leben außerhalb des Schutzes der Nachtwache von Dunkelhain verwundbar mache und dass das Zusammensetzen eines furchterregenden Bildnisses aus Ghulrippen als Vogelscheuche dienen werde, um herumstreifende Rudel der Toten zu vertreiben."},{t="Verdachtsmomente rund um die Hütte",b="Während das Sammeln von Teilen erschlagener Untoter zum Überleben in feindseligen Regionen durchaus üblich ist, lässt Calvinius' gezielte Faszination für die Anatomie der Ghule aufhorchen. Anstatt Zuflucht hinter den Palisaden von Dunkelhain zu suchen oder sich auf geweihte Schutzzeichen zu verlassen, besteht der Einsiedler darauf, rohe nekromantische Abfälle zu sammeln, um sein abgelegenes Heim zu befestigen."}},faq={{q="Welche Kreaturen tragen Ghulrippen bei sich?",a="Sie können von verschiedenen Arten von Ghulen im gesamten Dämmerwald erbeutet werden, darunter Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones und Plague Spreaders. Diese Monster suchen alte Friedhöfe, Ruinen am Wegesrand und verlassene Gehöfte im gesamten Wald heim.",al={"wo droppen ghulrippen","welche ghule haben rippen","ghulrippen quellen"}},{q="Warum will Calvinius diese Knochen haben?",a="Calvinius behauptet, zu weit von Dunkelhain entfernt zu leben, um sich auf den Schutz der Nachtwache verlassen zu können. Er verlangt nach den Rippen, um eine primitive Vogelscheuche oder ein Bildnis zu errichten, damit die umherstreifenden Untoten nicht länger gegen seine Wände hämmern.",al={"warum braucht calvinius rippen","zweck ghulbildnis","was macht calvinius mit rippen"}},{q="Halten Vogelscheuchen Ghule tatsächlich fern?",a="Untote empfinden im Allgemeinen keine Furcht und werden einzig von stumpfsinnigem Hunger oder dunklem nekromantischem Zwang getrieben. Die Vorstellung, dass geistlose Ghule vor einer Vogelscheuche aus Knochen fliehen würden, ist ungewöhnlich, doch Calvinius beharrt darauf, dass sie sein Heim schützen wird.",al={"funktioniert das bildnis","können bildnisse untote vertreiben","haben ghule angst vor vogelscheuchen"}},{q="Wo befindet sich die Hütte von Calvinius?",a="Calvinius lebt in einer baufälligen Hütte im westlichen Dämmerwald, direkt nördlich des Friedhofs von Rabenflucht.",al={"calvinius standort","wo ist der einsiedler","wo ghulrippen abgeben"}}},fp="9,237,15.545.0,27.334.1,32.255.0,38.206.0,40.237.0,37.95.0"}
P.entries["item:giant-crocolisk-skin"] = {n="Riesige Krokiliskenhaut",s="Riesige Krokiliskenhäute sind dicke Häute von den gewaltigen Reptilien, die in den Sümpfen des Sumpflands heimisch sind. Bei den Handwerkern im Hafen von Menethil sind sie für die Lederverarbeitung hoch geschätzt, doch ihre Beschaffung ist ein gefährliches Unterfangen, das schon so manchen unvorsichtigen Jäger verstümmelt hat.",h="Riesige Krokiliskenhäute sind dicke Häute von den gewaltigen Reptilien, die in den Sümpfen des Sumpflands...",kw={"lehrlingspflichten","krokilisk","riesige krokiliskenhaut","james halloran","der hafen von menethil","sumpfland"},ang={["class:Hunter"]="Das Nachstellen riesiger Krokilisken entlang der nebligen Küste stellt das Geschick eines Jägers auf die Probe, Wassertiere aufzuspüren und nicht unter die Sumpfgewässer gezerrt zu werden."},sec={{t="Ein gefährliches Handwerk",b="Die Moore und Wasserwege des Sumpflands beherbergen enorme Krokilisken, deren Häute dicht genug sind, um der feuchten Fäulnis der Sümpfe zu trotzen. Im Hafen von Menethil sind Handwerker wie James Halloran auf stetige Lieferungen von Häuten angewiesen, um robuste Lederwaren herzustellen. Doch einem ausgewachsenen riesigen Krokilisken die Haut abzuziehen erfordert es, tiefen Gewässern zu trotzen und wilde Raubtiere des Sumpfes zu überwältigen, wodurch jeder erbeutete Balg hart erkämpft ist."},{t="Die Torheit des Lehrlings",b="Die Beschaffung dieser dicken Häute war ursprünglich die Pflicht von Hallorans jungem Lehrling. Da dem Jungen das kriegerische Geschick fehlte, ausgewachsene Sumpfbestien zu erlegen, geriet er an der Nordküste in einen Hinterhalt. Zwar überlebte er die Begegnung in der Obhut einer örtlichen Hebamme nur knapp, verlor jedoch ein Bein an die Kiefer eines riesigen Krokilisken, was Halloran dazu zwang, erfahrene Abenteurer anzuheuern, um die Raubtiere zur Strecke zu bringen und die benötigten Häute zu beschaffen."}},faq={{q="Wofür wird eine Riesige Krokiliskenhaut verwendet?",a="Sie wird von James Halloran beschafft, einem Handwerker im Hafen von Menethil, der die dicken Häute für die Herstellung robuster Lederwaren schätzt, die dem feuchten Klima der Marschen standhalten können.",al={"krokiliskenhaut verwendung","warum riesige krokiliskenhaut sammeln","halloran haut zweck"}},{q="Wo sind die Krokilisken zu finden, die diese Häute liefern?",a="Riesige Krokilisken des Sumpflands durchstreifen die Küste und die Binnengewässer des Sumpfes nördlich vom Hafen von Menethil und ziehen jenseits der örtlichen Murlocsiedlungen durch die Untiefen.",al={"riesiger krokilisk standort","wo riesige krokilisken finden","krokilisken küste sumpfland"}},{q="Was geschah mit Hallorans Lehrling?",a="Halloran schickte seinen Lehrling allein in den Sumpf, um Häute zu sammeln. Der Lehrling wurde von riesigen Krokilisken angegriffen und so schwer zugerichtet, dass er ein Bein verlor, woraufhin er in der Obhut einer Menethiler Hebamme zurückblieb.",al={"lehrling verletzt","halloran lehrling","wer verlor ein bein"}},{q="Wie unterscheiden sich diese Häute von Häuten junger Krokilisken?",a="Junge Krokilisken liefern dünnere, geschmeidigere Häute, die ein unerfahrener Lehrling gefahrlos erbeuten konnte. Ausgewachsene riesige Krokilisken liefern weitaus zähere, dickere Häute, doch erfordert das Erlegen eines solchen Tieres erfahrene Kampffertigkeiten.",al={"junge gegen riesige krokiliskenhaut","krokiliskenleder unterschied"}}},fp="20,242,17.419.0,22.411.1,40.181.0,56.149.0,39.212.0,52.213.0"}
P.entries["item:gloom-weed"] = {n="Düsterkraut",s="Düsterkraut ist eine kränkliche Pflanze, die auf den verpesteten Böden von Tirisfal heimisch ist und häufig auf den Feldern zwischen Deathknell und Brill wächst. Sie ist vor allem als die falsche Pflanze bekannt, die von Gordo gesammelt wird, einer schwerfälligen Monstrosität der Verlassenen, die sie mit dem Alchimiereagenz Verdammniskraut verwechselt.",h="Düsterkraut ist eine kränkliche Pflanze, die auf den verpesteten Böden von Tirisfal heimisch ist und häufig...",kw={"monstrosität","brill","verdammniskraut","düsterkraut","gordo","meister holland","tirisfal"},ang={["profession:Herbalism"]="Ausgebildete Kräuterkundige können die Pflanze durch 'Kräutersuche' aufspüren, was es viel einfacher macht, sie im schattigen Unterholz von Tirisfal zu entdecken.",["race:Undead"]="Für neue Verlassene, die Deathknell verlassen, ist das Beschaffen von Düsterkraut eine schnelle Lektion über die Unzulänglichkeiten der Arbeit von Monstrositäten und das bissige Gemüt der Alchemisten von Undercity."},sec={{t="Eine verwechselte Ernte",b="Inmitten der Düsternis und des Verfalls von Tirisfal sprießend, gedeiht Düsterkraut in der brachliegenden Erde westlich von Brill und östlich von Sollidens Bauernhof. Trotz seines morbiden Namens ist das Kraut relativ harmlos und besitzt nicht die potente alchemistische Wirkung, die von der Königlichen Apothekervereinigung geschätzt wird. Seine Hauptbekanntheit rührt von der Monstrosität Gordo her, die an der Straße umherwandert und versucht, mit ihren riesigen, ungeschickten Händen Unkraut zu jäten. Da er die Befehle seines Meisters missverstanden hat, sammelt Gordo unentwegt Düsterkraut und spannt leichtgläubige Reisende ein, um Bündel davon zu Meister Holland auf den Friedhof von Brill zu bringen – sehr zum großen Ärger des Apothekers."}},faq={{q="Wofür wird Düsterkraut verwendet?",a="Praktisch für nichts, was für die Alchemisten der Verlassenen von Wert wäre. Es wird nur gesammelt, weil die Monstrosität Gordo es fälschlicherweise für das Verdammniskraut hält, das sein Meister eigentlich verlangt hatte.",al={"düsterkraut verwendung","was bewirkt düsterkraut","wer braucht düsterkraut"}},{q="Wo wächst Düsterkraut?",a="Es wächst verstreut auf den Feldern von Tirisfal zwischen Brill und Deathknell, insbesondere entlang der Straße und auf den Wiesen östlich von Sollidens Bauernhof.",al={"wo findet man düsterkraut","düsterkraut standort","düsterkraut fundorte"}},{q="Wer ist Gordo und warum pflückt er es?",a="Gordo ist eine Monstrosität, die von Meister Holland ausgesandt wurde, um Reagenzien zu ernten. Da seine zusammengenähten Hände zu ungeschickt sind und sein Verstand einfältig ist, wandert er an den Straßen umher, reißt die falschen Pflanzen aus und bittet Vorbeigehende um Hilfe.",al={"wer ist gordo","warum pflückt gordo unkraut","gordo monstrosität"}},{q="Was wollte Meister Holland eigentlich?",a="Meister Holland benötigt Verdammniskraut für seine Experimente auf dem Friedhof von Brill. Wenn man ihm Düsterkraut überreicht, spottet er über den Fehler und schickt die Reisenden los, um das zu beschaffen, was er wirklich brauchte.",al={"meister holland kraut","was braucht holland","verdammniskraut vs düsterkraut"}}},fp="10,278,18.640.0,28.177.0,27.164.0,38.220.0,38.181.0"}
P.entries["item:glowing-ember"] = {n="Leuchtendes Holzscheit",s="Ein Leuchtendes Holzscheit ist der verbleibende elementare Kern, der von einer besiegten Minor Manifestation of Fire auf den Klippen von Durotar erbeutet wird. Es dient als unverzichtbares zeremonielles Reagenz bei den Prüfungen eines Schamanen und wird verwendet, um die Feuerschale am Shrine of Eternal Flame zu entzünden.",h="Ein Leuchtendes Holzscheit ist der verbleibende elementare Kern, der von einer besiegten Minor Manifestation...",kw={"ruf des feuers","feuersapta","leuchtendes holzscheit","minor manifestation of fire","shrine of eternal flame","telf joolam","fackel der schlafenden flamme"},ang={["class:Shaman"]="Die Erlangung dieses brennenden Kerns ist ein entscheidender Übergangsritus, der einen Initianden dazu zwingt, seine Entschlossenheit gegen lebendiges Feuer auf die Probe zu stellen, bevor er dessen Totem befehligt."},sec={{t="Kern der Flamme",b="Wenn ein aufstrebender Schamane die Feuersapta trinkt und sich den feurigen Geistern auf dem Bergrücken nahe Telf Joolam stellt, konfrontiert er eine Minor Manifestation of Fire. Nach der Niederlage des Elementars ist dieser glimmende Überrest alles, was von seiner physischen Gestalt übrig bleibt. Das Holzscheit pulsiert noch immer vor roher Elementarhitze und trägt den lebendigen Funken des Feuers in sich, der nötig ist, um die heilige Feuerschale am Shrine of Eternal Flame zu erwecken."},{t="Entzünden der Fackel",b="Wird das Leuchtende Holzscheit in das ansonsten kalte Becken der Bergfeuerschale gelegt, entfacht dies eine plötzliche, weißglühende Flamme. Genährt von den Überresten des besiegten Elementars, ermöglicht die Feuerschale dem Initianden, die Fackel der schlafenden Flamme zu entzünden, wodurch die unbändige Essenz des Feuers an ein Gefäß gebunden wird, das er den Berg hinabtragen kann, um seine Beherrschung der Elemente zu beweisen."}},faq={{q="Woher stammt das Leuchtende Holzscheit?",a="Das Holzscheit wird aus den Überresten einer Minor Manifestation of Fire geborgen, einem feindseligen Elementar, dem man auf dem Gipfel über dem Shrine of Eternal Flame in Durotar begegnet.",al={"wie man leuchtendes holzscheit bekommt","leuchtendes holzscheit beute","wo leuchtendes holzscheit finden"}},{q="Wofür wird das Holzscheit verwendet?",a="Initianden legen das Holzscheit in die metallene Feuerschale am Shrine of Eternal Flame. Es erzeugt eine intensive, rhythmische Flamme, mit der die zeremonielle Fackel der schlafenden Flamme entzündet wird.",al={"was macht leuchtendes holzscheit","leuchtendes holzscheit nutzung","feuerschale holzscheit"}},{q="Warum benötigen Schamanen die Feuersapta, um es zu erhalten?",a="Die Elementargeister auf dem Berg verweilen jenseits der normalen sterblichen Sicht. Das Trinken der Feuersapta stimmt die Sinne eines Schamanen auf die Elementarebene ein und enthüllt die Minor Manifestation of Fire, sodass sie herausgefordert werden kann.",al={"warum sapta gebraucht wird","kann feuerelementar nicht sehen","feuersapta holzscheit"}},{q="Wer weist Schamanen an, dieses Holzscheit zu suchen?",a="Der Einsiedler Telf Joolam, der in den Klippen von Durotar lebt, braut die Feuersapta und leitet Schamaneninitianden durch die Prüfung, den Flammengeist zu besiegen.",al={"wer gibt die quest","telf joolam holzscheit","ruf des feuers questgeber"}}},fp="13,250,17.396.0,18.366.1,39.165.0,27.176.0,49.217.0,39.155.0"}
P.entries["item:glowing-fruit"] = {n="Leuchtende Frucht",s="Die leuchtende Frucht ist ein exotisches, lumineszierendes Exemplar, das zwischen seltsamen Wedeln auf den Ästen von Teldrassil wächst. Ihr unnatürliches Leuchten und ihre bizarre Wechselwirkung mit dem Boden des Weltenbaums machen sie zu einem Objekt dringlicher botanischer Untersuchungen für Naturforscher.",h="Die leuchtende Frucht ist ein exotisches, lumineszierendes Exemplar, das zwischen seltsamen Wedeln auf den...",kw={"botanik","denalan","leuchtende frucht","al'amethsee","pflanze","teldrassil","holzlinge"},ang={["class:Druid"]="Für Druiden, die auf das empfindliche Gleichgewicht von Teldrassil eingestimmt sind, stellt fremde Flora, die unberechenbar mit dem Boden interagiert, eine potenzielle Störung für den heranwachsenden Weltenbaum dar.",["profession:Herbalism"]="Kräuterkundige werden sofort bemerken, dass das seltsame Lumineszieren der Frucht auf eine exotische, mächtige Wechselwirkung zwischen externen Samensorten und verzaubertem Boden hindeutet."},sec={{t="Ein sonderbares Exemplar",b="Unter ungewöhnlichen Wedeln auf Teldrassil entdeckt, strahlt diese große, runde Frucht ein unverkennbares Licht aus. Der Botaniker Denalan am Al'Amethsee erkennt, dass sie nicht auf dem Weltenbaum heimisch ist, und vermutet, dass ihre Samen aus fernen Ländern jenseits des Meeres herangeweht wurden. Was auch immer ihr Ursprung sein mag, die Frucht reagiert seltsam auf den reichen, verzauberten Boden von Teldrassil, was zeigt, wie anfällig der junge Ast der Welt für fremde und unberechenbare Flora ist."}},faq={{q="Was ist die Leuchtende Frucht?",a="Sie ist eine exotische, runde Frucht, die unter ungewöhnlichen Wedeln auf Teldrassil wachsend entdeckt wurde. Sie strahlt ein ätherisches Leuchten aus und scheint auf ungewöhnliche Weise mit dem hiesigen Boden reagiert zu haben.",al={"leuchtende frucht teldrassil","was ist diese frucht","seltsame frucht quest"}},{q="Woher stammt diese Frucht?",a="Laut dem Naturforscher Denalan ist die Frucht nicht auf Teldrassil heimisch. Er vermutet, dass ihre Samen von weit her über das Meer getrieben oder transportiert wurden, vielleicht aus den Östlichen Königreichen von Azeroth, bevor sie im Boden Wurzeln schlugen.",al={"herkunft der frucht","woher kamen die samen","ist sie heimisch"}},{q="Wer möchte die Leuchtende Frucht untersuchen?",a="Denalan, ein Forscher der Nachtelfen, der am Al'Amethsee stationiert ist, untersucht die Äste und das Ökosystem von Teldrassil. Er hegt ein reges Interesse an fremdartiger Pflanzenwelt, die mit der Erde des Weltenbaums reagiert hat.",al={"wer braucht die frucht","wohin leuchtende frucht bringen","denalan frucht"}}},fp="13,250,18.441.0,26.168.0,31.228.0,39.200.0"}
P.entries["item:glowing-gem"] = {n="Leuchtender Edelstein",s="Der Leuchtende Edelstein ist ein verzauberter Stein, der aus den Murloc-Lagern an den Gewässern von Ashenvale geborgen wurde. Ursprünglich von dem gefallenen Späher Teronis gesucht, ist der Stein ein unverzichtbarer Bestandteil, der benötigt wird, um den legendären, von Dartol geschaffenen Reinigungsstab wieder zusammenzusetzen.",h="Der Leuchtende Edelstein ist ein verzauberter Stein, der aus den Murloc-Lagern an den Gewässern von Ashenvale...",kw={"astranaar","reinigungsstab","dartol","leuchtender edelstein","irissee","murloc","raene wolfrunner","shael'dryn","teronis"},ang={["class:Druid"]="Druiden hegen ein tiefes Interesse an Dartols Werk, da die reinigenden Eigenschaften des Edelsteins unerlässlich sind, um das verdorbene Wasser und den Boden des Waldes zu heilen.",["race:NightElf"]="Die Bergung des Edelsteins und die Erfüllung von Teronis' Mission hilft den Schildwachen, ihren gefallenen Späher zu ehren und Ashenvale vor der sich ausbreitenden Verderbnis zu schützen."},sec={{t="Ein verlorenes Relikt von Dartol",b="Entdeckt im Besitz der aggressiven Murlocs, die nahe dem Irissee hausen, ist der Leuchtende Edelstein von latenter magischer Energie durchdrungen. Der junge Nachtelf Teronis brach von Astranaar auf, um ihn aufzuspüren, mit dem Ziel, ein Werkzeug zusammenzusetzen, das fähig ist, die durch Ashenvales Wälder sickernde Verderbnis zurückzudrängen. Obwohl Teronis am See ein unzeitiges Ende fand, blieb der Stein selbst unter den Aasfressern am Ufer unversehrt erhalten."},{t="Wiederherstellung des Reinigungsstabs",b="Nach der Bergung des Steins zusammen mit Teronis' Tagebuch weist Schildwachenanführerin Raene Wolfrunner den Überbringer an, ihn nach Nordosten zu Shael'dryn zu bringen, einer Dryade, die an einem nahe gelegenen Mondbrunnen Wache hält. Die Dryade besitzt das uralte Wissen, das erforderlich ist, um den Leuchtenden Edelstein mit den anderen fehlenden Teilen des von Dartol geschaffenen Stabs zu verbinden, damit das Werk des gefallenen Spähers nicht vergebens war."}},faq={{q="Woher stammt der Leuchtende Edelstein?",a="Der Edelstein wird von den Murlocs getragen, die an den Ufern und in den seichten Gewässern rund um den Irissee im zentralen Ashenvale lauern.",al={"leuchtender edelstein fundort","wer lässt leuchtenden edelstein fallen","wo gibt es leuchtenden edelstein"}},{q="Warum suchte Teronis nach diesem Edelstein?",a="Teronis untersuchte Möglichkeiten, die wachsende Fäulnis in Ashenvale zu reinigen. Seinen Nachforschungen zufolge ist dieser spezielle Edelstein einer der Schlüsselbestandteile, die benötigt werden, um einen reinigenden Zauberstab wieder aufzubauen, den einst Dartol erdacht hatte.",al={"teronis quest","warum teronis den edelstein wollte","zweck des edelsteins"}},{q="Zu wem sollte ich den Leuchtenden Edelstein bringen?",a="Nachdem Ihr den Stein und Teronis' Tagebuch Raene Wolfrunner in Astranaar gezeigt habt, bringt den Leuchtenden Edelstein nach Nordosten zur Dryade Shael'dryn am Mondbrunnen östlich des Irissees.",al={"wer braucht leuchtenden edelstein","leuchtenden edelstein abgeben","was tun mit dem edelstein"}},{q="Was ist der Stab von Dartol?",a="Es ist ein uraltes, von Dartol geschaffenes Instrument, das dazu bestimmt ist, natürliche Fäulnis und Verderbnis zu reinigen. Seine Bestandteile wurden über den Wald verstreut, wobei der Leuchtende Edelstein als eines seiner primären Fokussierungsstücke dient.",al={"dartols stab","was hat dartol hergestellt"}}},fp="11,247,22.428.0,27.368.1,37.111.0,37.211.0,37.169.0,26.212.0"}
P.entries["item:glowing-soul-gem"] = {n="Leuchtender Seelenedelstein",s="Ein Leuchtender Seelenedelstein ist ein dunkles Ritualartefakt, das von Agenten des Kults des Dunklen Strangs im nördlichen Ashenvale getragen wird. Erfüllt von schattenhafter Zauberei fängt der Stein den Geist eines ahnungslosen Opfers ein, um die finsteren Machenschaften des Kults anzutreiben.",h="Ein Leuchtender Seelenedelstein ist ein dunkles Ritualartefakt, das von Agenten des Kults des Dunklen Strangs...",kw={"althalaxx","kult des dunklen strangs","dunkler strang","delgren der läuterer","leuchtender seelenedelstein","maestras posten","ordil'aran","seelenedelstein"},ang={["class:Priest"]="Priester, die den Seelenedelstein betrachten, können die Qual des darin gefangenen Geistes spüren und erkennen die dringende Notwendigkeit, das Artefakt zu läutern und der Seele Frieden zu schenken.",["class:Warlock"]="Hexenmeister verstehen die Kunst, Geister in Seelensteinen einzufangen, besser als jeder andere und erkennen im Edelstein des Dunklen Strangs ein gröberes, nekromantisches Abwandlungsprodukt der Seelenmanipulation."},sec={{t="Ein Gefäß dunkler Zauberei",b="Nordöstlich von Maestras Posten, in den schattenhaften Ruinen von Ordil'Aran, wirken Mitglieder des Kults des Dunklen Strangs unter den wachsamen Augen ihrer schattenhaften Meister dunkle Zauberei. In ihren Reihen tragen Agenten Leuchtende Seelenedelsteine bei sich – Gefäße, die verzaubert wurden, um die Seelen der Toten einzufangen und zu quälen. Weit mehr als bloße Zierstücke dienen diese Steine als Kanäle magischer Energie, die gebundene Geister verankern, um den schattenhaften Zielen des Kults zu dienen."},{t="Die Geheimnisse von Ordil'Aran",b="Mit dem Ziel, den Einfluss des Dunklen Strangs im nördlichen Kalimdor zu zerschlagen, untersucht Delgren der Läuterer an Maestras Posten diese Artefakte. Die Entzifferung der in einen Leuchtenden Seelenedelstein gewobenen Verzauberungen offenbart nicht nur finstere arkane Formeln, sondern auch eine gefangene Seele, die aus dem Inneren des Edelsteins herausschreit, und legt so die unheilvollen Experimente offen, die die Kultisten in Ashenvale mit ihrer Sippe am Turm von Althalaxx verbinden."}},faq={{q="Was ist der Leuchtende Seelenedelstein?",a="Es ist ein verzauberter Seelenstein, der vom Kult des Dunklen Strangs verwendet wird. Erfüllt von Schattenmagie sperrt er Geister in seinem Inneren ein, um deren Essenz zu nutzen und die abscheuliche Zauberei des Kults anzutreiben.",al={"was ist seelenedelstein","seelenedelstein dunkle küste","leuchtender seelenedelstein lore"}},{q="Woher stammt dieser Seelenedelstein?",a="Er wird von Mitgliedern des Kults des Dunklen Strangs getragen – darunter ihre Kultisten, Attentäter, Vollstrecker und Adepten –, die von den Ruinen von Ordil'Aran im nördlichen Ashenvale aus operieren.",al={"wer droppt seelenedelstein","leuchtender seelenedelstein fundort","ordil'aran edelstein"}},{q="Wer möchte diesen Seelenedelstein haben und warum?",a="Delgren der Läuterer, der an Maestras Posten stationiert ist, sucht nach dem Edelstein. Er glaubt, dass die Entzifferung seiner Verzauberungen die geheime Quelle der Macht des Kults aufdecken und offenbaren wird, was sie im Schilde führen.",al={"delgren seelenedelstein","warum will delgren seelenedelstein","maestras posten seelenedelstein"}},{q="Was geschieht, wenn der Seelenedelstein entziffert wird?",a="Das Lösen der Verzauberungen auf dem Edelstein lässt den darin gefangenen Geist frei, erlöst die gequälte Seele und legt die verdrehten Abgründe der Praktiken des Dunklen Strangs offen.",al={"was ist im seelenedelstein","geist im seelenedelstein"}}},fp="16,239,24.434.0,25.404.1,29.174.0,35.182.0,32.192.0,45.167.1"}
P.entries["item:glutton-shackle"] = {n="Nimmersattfessel",s="Nimmersattfesseln sind verzauberte Fesseln, die von Moonrage Glutton-Worgen im Silberwald getragen werden. Vom wahnsinnigen Erzmagier Arugal gefertigt, leiten diese Bänder Magie weiter, um seine ansonsten fehlerhafte Zauberei zu stützen und seine verfluchten wölfischen Schöpfungen aufrechtzuerhalten.",h="Nimmersattfesseln sind verzauberte Fesseln, die von Moonrage Glutton-Worgen im Silberwald getragen werden.",kw={"arugal","dalar dawnweaver","nimmersattfessel","moonrage glutton","das grabmal","silberwald","worgen"},ang={["class:Mage"]="Magier werden Dalar Dawnweavers bissige Kritik an Arugals minderwertiger Technik zu schätzen wissen, da die Verwendung physischer, verzauberter Krücken zur Stabilisierung einfacher Transmutations- und Beschwörungszauber als Zeichen mittelmäßiger Zauberkunst gilt.",["race:Undead"]="Agenten der Verlassenen betrachten das Sammeln dieser Fesseln als wesentlichen Schritt zur Neutralisierung der Worgengefahr, die direkt an die Grenzen des Grabmals heranreicht."},sec={{t="Eine Krücke für schwache Zauberei",b="Für die ausgebildeten Magier der Verlassenen sind die wilden Worgen, die den Silberwald heimsuchen, nicht bloß wilde Monstrositäten – sie sind der Beweis für grobe arkane Unfähigkeit. Dalar Dawnweaver, ein versierter Arkanist, der im Grabmal stationiert ist, hegt nichts als Verachtung für Erzmagier Arugal und hält ihn für einen inkompetenten Pfuscher, der der Kirin Tor unwürdig ist. Dawnweaver fand heraus, dass Arugal sich auf verzauberte Relikte verließ, um seine fragilen Zauber auszugleichen. Die Nimmersattfesseln, die von den schweren Moonrage Gluttons im nördlichen Silberwald getragen werden, fungieren als magische Anker, die den die Bestien bindenden Fluch verstärken."},{t="Treibstoff für Gegenmaßnahmen der Verlassenen",b="Weil Arugal rohe Verzauberungen direkt in diese schweren Eisenbänder bannte, behalten sie selbst nach dem Tod ihrer Träger magische Restenergie. Dawnweaver verlangt diese Fesseln von den Agenten der Verlassenen, um ihre Konstruktion zu studieren und ihre magischen Reserven abzuschöpfen. Durch die Analyse der primitiven Verzauberungen im Metall hoffen die Verlassenen, die Geheimnisse des Worgenfluchs zu lüften und den Untergang des in Burg Shadowfang verschanzten Bestienmeisters herbeizuführen."}},faq={{q="Was ist eine Nimmersattfessel?",a="Eine Nimmersattfessel ist eine verzauberte Eisenfessel, die von Moonrage Glutton-Worgen im Silberwald getragen wird. Von Erzmagier Arugal erschaffen, verleihen diese Bänder ihren Trägern magische Verstärkung, um seine fehlerhaften Zauber zu stützen.",al={"was sind nimmersattfesseln","nimmersattfessel geschichte","worgenmanschetten"}},{q="Warum möchte Dalar Dawnweaver Nimmersattfesseln?",a="Dalar Dawnweaver benötigt die Fesseln, um Arugals primitive Verzauberungen zu analysieren und ihre verbliebene magische Energie abzuschöpfen. Indem die Verlassenen die Gegenstände verstehen, die Arugal zur Stabilisierung seiner Bestien nutzte, können sie seiner Magie besser entgegenwirken.",al={"warum fesseln sammeln","dalar dawnweaver quest","fesseln für das grabmal"}},{q="Wer stellt diese Fesseln her?",a="Sie wurden von Erzmagier Arugal verzaubert, einem ehemaligen Magier von Dalaran, der die Worgen zur Bekämpfung der Geißel beschwor, schließlich den Verstand verlor und seine Schöpfungen mit magischen Schmuckstücken an seinen Willen band.",al={"wer fertigte die fesseln","arugal fesseln","woher stammen die fesseln"}},{q="Wo sind die Kreaturen zu finden, die diese Fesseln tragen?",a="Moonrage Gluttons durchstreifen die Wälder und verlassenen Gehöfte des zentralen und nördlichen Silberwalds, oft lauernd im Rudel an der Seite anderer verdorbener Moonrage-Worgen.",al={"wo spawnen gluttons","moonrage glutton standort","silberwald worgen fesseln"}}},fp="15,238,25.593.0,33.466.1,26.221.0,48.227.0,25.198.0,53.166.0"}
P.entries["item:glyph-of-azora"] = {n="Glyphe von Azora",s="Eine Glyphe von Azora ist ein arkanes Aufspürgerät, das vom Zauberer Theocritus am Turm von Azora gefertigt wurde. Gebunden an die Seherkräfte des Auges von Azora ermöglichen diese beschrifteten Steine dem Magier, über weite Entfernungen zu blicken und in die Gedanken seiner Feinde einzudringen.",h="Eine Glyphe von Azora ist ein arkanes Aufspürgerät, das vom Zauberer Theocritus am Turm von Azora gefertigt...",kw={"glyphe von azora","morganth","rotkammgebirge","fernsicht","burg steinwacht","theocritus","turm von azora","der turm von ilgalar"},ang={["class:Mage"]="Die Glyphe von Azora demonstriert praktische arkane Weissagung, indem sie herkömmliche Kristallbeobachtung um gezielte Telepathie und sensorische Fernrelais erweitert.",["faction:Alliance"]="Die Glyphen liefern entscheidende Aufklärung über feindliche Bewegungen im Rotkammgebirge und verfolgen den abtrünnigen Hexenmeister Morganth sowie die Besatzung der Schwarzfels-Orcs in Steinwacht."},sec={{t="Augen jenseits der Grenze",b="Von seinem Turm im Wald von Elwynn aus arbeitet der Zauberer Theocritus unermüdlich daran, feindliche Mächte zu überwachen, die das Reich bedrohen. Während sein Kristallrelikt, das Auge von Azora, visuelle Fernbeobachtung ermöglicht, reicht seine Reichweite nicht aus, um tiefer in den Geist und die Pläne von Widersachern vorzudringen. Um diese Beschränkung zu überwinden, setzt Theocritus Miniaturfokusse ein, die als Glyphen von Azora bekannt sind. Sobald eine Glyphe an einem abgelegenen Ort auf einer Oberfläche angebracht wird, fungiert sie als Anker für seine Magie; dadurch kann er nicht nur die Absichten der Feinde lesen, sondern auch seine Stimme über meilenweite Strecken projizieren, um direkt mit Feldagenten zu kommunizieren."},{t="Spionage im Rotkammgebirge",b="Theocritus entsendet diese Glyphen direkt in feindliches Territorium im Rotkammgebirge. Die erste wird an einer alten Löwenstatue angebracht, die den Turm von Ilgalar überblickt – die Festung seines abtrünnigen Rivalen, des dunklen Zauberers Morganth. Nachdem er sich in Morganths Gedanken eingeklinkt hat, entdeckt Theocritus einen unerwarteten Streit zwischen dem abtrünnigen Magier und den Schwarzfels-Orcs, die die nahegelegene Burg Steinwacht besetzt halten. Eine zweite Glyphe wird in die Höhen des intakten Wachturms der Burg getragen und in einem weggeworfenen Schnapskrug versteckt, um aufzudecken, warum Morganth und die Eindringlinge im Streit liegen."}},faq={{q="Was ist der Zweck der Glyphe von Azora?",a="Sie dient als arkanes Relais, das von Theocritus gefertigt wurde. Während sein Auge von Azora visuelle Fernbeobachtung ermöglicht, schafft das Platzieren einer Glyphe von Azora einen Ankerpunkt, der es ihm erlaubt, die Gedanken und Zukunftspläne seiner Widersacher zu lesen sowie seine Stimme zu projizieren, um mit entfernten Verbündeten zu sprechen.",al={"was macht die glyphe von azora","warum glyphe von azora benutzen","glyphe von azora zweck"}},{q="Wer hat die Glyphe von Azora erschaffen?",a="Sie wurde von Theocritus erschaffen, einem mächtigen Magier, der im Turm von Azora an der östlichen Grenze des Walds von Elwynn residiert.",al={"wer hat die glyphe erschaffen","glyphe von azora schöpfer","theocritus glyphe"}},{q="Wo werden die Glyphen von Azora platziert?",a="Eine Glyphe wird in den Sockel einer verwitterten Löwenstatue eingelassen, die den Turm von Ilgalar überblickt. Eine zweite Glyphe wird in den oberen Wachturm von Burg Steinwacht geschmuggelt und in einem leeren Schnapskrug versteckt, um die Schwarzfels-Orcs auszuspionieren.",al={"wo muss die glyphe platziert werden","glyphen platzierungsorte","wohin kommt die glyphe"}},{q="Warum spioniert Theocritus Der Turm von Ilgalar aus?",a="Der Turm von Ilgalar wird von Morganth besetzt, einem gefährlichen abtrünnigen Zauberer, der Theocritus' erbitterter Rivale ist. Theocritus nutzt die Glyphe, um Morganths Pläne aufzudecken, bevor dieser dunkle Magie über die Region entfesseln kann.",al={"warum morganth ausspionieren","theocritus ilgalar","morganth fehde"}},{q="Wie erlaubt die Glyphe Theocritus, mit Leuten zu sprechen?",a="Die Glyphe ist direkt an die arkanen Energien des Turms von Azora gebunden. Sobald sie an einer Zieloberfläche angebracht ist, baut sie eine Zwei-Wege-Leitung auf, die es Theocritus ermöglicht, seine körperlose Stimme direkt durch den Stein zu projizieren.",al={"sprechende glyphe","theocritus stimme in glyphe","kann die glyphe sprechen"}}},fp="14,256,22.588.0,21.554.1,42.286.0,31.126.0,37.237.0,49.210.0,55.218.0"}
P.entries["item:glyphic-letter"] = {n="Glyphen-Brief",s="Der Glyphen-Brief ist ein offizielles Schreiben, das das arkane Siegel von Khelden Bremen trägt, dem ansässigen Magierlehrer in der Abtei von Nordhain. Er wird vielversprechenden Novizen nach ihren ersten Diensten für die Garnison überreicht und fordert angehende Magier auf, sich nach oben zu begeben und sich den harten Realitäten des arkanen Studiums zu stellen.",h="Der Glyphen-Brief ist ein offizielles Schreiben, das das arkane Siegel von Khelden Bremen trägt, dem...",kw={"arkan","wald von elwynn","glyphen-brief","khelden bremen","magierlehrer","marshal mcbride","abtei von nordhain"},ang={["class:Mage"]="Dieses gekennzeichnete Schreiben markiert Eure formelle Einführung in die arkanen Traditionen der Allianz und ruft Euch nach oben, um unter Khelden Bremen zu lernen.",["race:Human"]="Die Abtei von Nordhain hat im Laufe der Geschichte des Königreichs vielen Schülern der arkanen Künste Schutz geboten, und dieser Ruf beginnt Euren Dienst an den magischen Disziplinen von Stormwind."},sec={{t="Ein Ruf zu den arkanen Künsten",b="Versiegelt mit den persönlichen Insignien des Magierlehrers Khelden Bremen, wird der Glyphen-Brief Zauberlehrlingen überreicht, sobald sie ihre Disziplin im Nordhaintal unter Beweis gestellt haben. Der Brief dient als formelle Einladung, einfache Pflichten im Feld hinter sich zu lassen und mit der gezielten magischen Ausbildung innerhalb der Abtei zu beginnen. Bremen nutzt diese Aufforderung, um die Entschlossenheit des Schülers zu prüfen und sicherzustellen, dass jeder, der sich mit den arkanen Künsten befasst, vollends darauf vorbereitet ist, gefährlichen Mächten, unnachgiebiger Genauigkeit und den Bürden roher magischer Kraft entgegenzutreten."}},faq={{q="Was ist der Glyphen-Brief?",a="Es ist eine Vorladung zur Ausbildung, verfasst und versiegelt von Khelden Bremen, dem ansässigen Magierlehrer der Abtei von Nordhain. Er weist angehende menschliche Magier an, ihn in den oberen Gemächern der Abtei für den formellen arkanen Unterricht aufzusuchen.",al={"was ist dieser brief","glyphen-brief gegenstand","kheldens brief"}},{q="Wer schickt den Glyphen-Brief?",a="Der Brief ist mit den Insignien von Khelden Bremen versiegelt, dem örtlichen Magierlehrer, der in der Abtei von Nordhain stationiert ist. Er wird von der Garnisonsführung überreicht, nachdem ein Lehrling seinen Mut gegen das nahe Ungeziefer bewiesen hat.",al={"wer hat ihn geschrieben","wer gab mir den glyphen-brief","absender des briefes"}},{q="Wohin bringe ich den Glyphen-Brief?",a="Ihr bringt ihn in die Abtei von Nordhain. Geht durch den Haupteingang hinter Marshal McBride, biegt in den linken Korridor ein, steigt die Treppe hinauf und seht zum hinteren Raum, wo Khelden Bremen seinen arkanen Unterricht abhält.",al={"wohin gehen","wo ist khelden bremen","aufenthaltsort von khelden"}},{q="Warum lässt Khelden nach jungen Magiern rufen?",a="Khelden möchte Eure Entschlossenheit auf die Probe stellen. Wie er in seinen einführenden Lektionen mahnt, bedeutet das Streben nach dem Arkanen sowohl Furcht als auch Respekt zu wecken, während man mächtigen Kräften trotzt – und er muss wissen, dass seine Lehrlinge den Willen besitzen, dieses Schicksal zu ertragen.",al={"warum will khelden mich","grund des magierlehrers","was will khelden"}}},fp="14,294,23.545.0,27.225.0,29.220.0,35.215.0,38.253.0"}
P.entries["item:glyphic-memorandum"] = {n="Glyphen-Memorandum",s="Das Glyphen-Memorandum ist eine schriftliche Mitteilung, die an angehende Magier übergeben wird, die im Coldridgetal eintreffen. Verfasst im Namen des Magierlehrers Marryk Nurribit, weist es junge Zauberwirker nach drinnen an, um ihre formelle arkane Ausbildung zu beginnen.",h="Das Glyphen-Memorandum ist eine schriftliche Mitteilung, die an angehende Magier übergeben wird, die im...",kw={"anvilmar","das coldridgetal","dun morogh","glyphen-memorandum","magier","marryk nurribit"},ang={["class:Mage"]="Für angehende Magier, die Dun Morogh durchstreifen, markiert diese Notiz den formellen Beginn ihrer arkanen Lehre unter Marryk Nurribit.",["race:Gnome"]="Gnomische Magier, die ihre Reise im Exil beginnen, werden von ihrem Lehrer daran erinnert, sich auf ihr Studium zu konzentrieren und sich von ihrer verlorenen Heimat Gnomeregan fernzuhalten."},sec={{t="Eine Vorladung nach Anvilmar",b="Angehende Zauberwirker, die in den bitteren Frost des Coldridgetals aufbrechen, erhalten dieses kurze Schreiben nach Abschluss ihrer ersten Aufgaben. Das vom örtlichen Magierlehrer Marryk Nurribit verfasste Memorandum ruft die jungen Praktizierenden in die Wärme von Anvilmar. Statt strenger akademischer Dogmen ist Marryks Anleitung ungezwungen und direkt: Lernt Eure Beschwörungen, legt Münzen für die Ausbildung und Tavernenbier beiseite und haltet Euch tunlichst von den verstrahlten Ruinen von Gnomeregan fern."}},faq={{q="Was ist das Glyphen-Memorandum?",a="Es ist eine kurze schriftliche Vorladung, die neu eingetroffenen Magiern im Coldridgetal überreicht wird und sie anweist, den örtlichen arkanen Lehrer in Anvilmar aufzusuchen.",al={"glyphen-memo","magiernotiz","was ist das glyphen-memorandum"}},{q="Wer hat dieses Memorandum verfasst?",a="Die Notiz stammt von Marryk Nurribit, einem gnomischen Magierlehrer, der in den Hallen von Anvilmar in Dun Morogh stationiert ist.",al={"wer hat es verfasst","wer schickte das glyphen-memorandum","verfasser der notiz"}},{q="Welchen Rat gibt der Lehrer bei Beantwortung des Memorandums?",a="Nach Vorlage der Notiz erinnert Marryk den Neuling daran, Zurückhaltung zu üben, Geld für Zauber und Tavernenbier zu sparen und die radioaktiven Hallen von Gnomeregan strikt zu meiden.",al={"marryk ratschlag","was sagt marryk"}}},fp="18,236,21.465.0,31.153.0,26.116.0,64.168.0"}
P.entries["item:glyphic-scroll"] = {n="Glyphen-Rolle",s="Die Glyphen-Rolle ist eine Vorladung, die neu auferstandenen Magiern der Forsaken in Deathknell überbracht wird. Sie trägt das Siegel von Isabella, der örtlichen Arkan-Lehrerin, und ruft angehende Zauberwirker in die geschändete Kirche, um ihr Handwerk im Untod zu verfeinern.",h="Die Glyphen-Rolle ist eine Vorladung, die neu auferstandenen Magiern der Forsaken in Deathknell überbracht...",kw={"arkan","deathknell","glyphen-rolle","isabella","magier","schriftrolle","tirisfal"},ang={["class:Mage"]="Die Schriftrolle ist die erste formelle Vorladung, die ein Magier der Forsaken erhält, und betont, dass der Untod einen Zauberwirker nicht von den verderblichen Süchten der arkanen Magie befreit.",["race:Undead"]="Für die Forsaken ist wiedergewonnenes arkanes Wissen nicht bloß ein wissenschaftliches Studium – es ist eine unverzichtbare Waffe, um ihre Souveränität sowohl gegen die Geißel als auch gegen lebende Feinde zu sichern."},sec={{t="Eine Vorladung aus der Kirche",b="Wenn ein frisch erwachter Magier der Forsaken von der Ausdünnung der geistlosen Geißel auf dem Friedhof von Deathknell zurückkehrt, erwartet ihn dieses versiegelte Schreiben. Verfasst unter dem Zeichen von Isabella, der ansässigen Magierlehrerin der Siedlung, ruft die Schriftrolle den Empfänger in das ruinierte Heiligtum der Gemeinde. Neu auferstandenen Magiern dient sie als erste Orientierung in der Disziplin des Arkane unter dem Banner der Forsaken – und erinnert sie daran, dass der Tod sie zwar von sterblicher Schwäche befreit haben mag, die verderblichen Versuchungen magischer Macht jedoch so beharrlich wie eh und je bleiben."}},faq={{q="Was ist die Glyphen-Rolle?",a="Sie ist eine einführende Botschaft, die neu auferstandenen Magiern der Forsaken in Deathknell überreicht wird. Sie trägt das persönliche Siegel der Arkan-Lehrerin Isabella und weist angehende Zauberwirker an, sich bei ihr in der Kirche des Ortes einzufinden, um ihre magische Ausbildung zu beginnen.",al={"was ist dieser gegenstand","glyphen-rolle verwendung","was bewirkt die schriftrolle"}},{q="Wer schickt die Glyphen-Rolle?",a="Die Schriftrolle wird im Namen von Isabella überbracht, der Magierlehrerin, die in der Kirchenruine von Deathknell stationiert ist. Sie wendet sich an jeden neu auferstandenen Untoten, der ein Talent für das Arkane besitzt.",al={"wer hat sie geschrieben","wer hat mir das gegeben","absender der schriftrolle"}},{q="Warum möchte Isabella neue Magier der Forsaken ausbilden?",a="Isabella sucht nach Seelenverwandten, die den Schmerz des Sterbens und den Wunsch teilen, ihre gestohlene Heimat und ihre Schicksale zurückzufordern. Sie bildet sie darin aus, genügend arkane Macht anzuhäufen, um jeden zu vernichten, der sich den Forsaken widersetzt, und mahnt sie zugleich, nicht der magischen Sucht und Verderbnis zu erliegen.",al={"isabellas motiv","warum magier ausbilden"}}},fp="14,233,25.552.0,27.247.0,29.195.0,51.285.0"}
P.entries["item:glyphic-tablet"] = {n="Glyphen-Schrifttafel",s="Die Glyphen-Schrifttafel ist eine beschriftete Schiefertafel, die angehenden Trollmagiern der Darkspear zu Beginn ihrer Prüfungen in Durotar überreicht wird. Sie wird durch den Aufseher Gornek überbracht und weist die frischgebackenen Zauberwirker an, sich von der Trollmagierlehrerin Mai'ah ausbilden zu lassen.",h="Die Glyphen-Schrifttafel ist eine beschriftete Schiefertafel, die angehenden Trollmagiern der Darkspear zu...",kw={"arkan","durotar","glyphen-schrifttafel","gornek","mai'ah","trollmagier","das tal der prüfungen"},ang={["class:Mage"]="Die Tafel markiert den Beginn Eurer arkanen Unterweisung bei den Darkspear und trägt eine Mahnung von Mai'ah in sich, dass die korrumpierende Verlockung der Magie Eure größte Gefahr ist.",["race:Troll"]="Als einziges Volk im Tal der Prüfungen, das die Zauberkunst praktiziert, erhalten Darkspearmagier diese Tafel, um ihren ganz eigenen Weg neben den traditionellen schamanischen und kriegerischen Pfaden zu beginnen."},sec={{t="Der erste Ruf eines Magiers",b="Im Tal der Prüfungen wird neuen Initianden der Darkspeartrolle, die eine Affinität zu arkaner Macht zeigen, die Glyphen-Schrifttafel überreicht. Gornek gibt sie weiter, während junge Rekruten ihre ersten Aufgaben in den roten Schluchten erledigen. Die Tafel enthält eine Einladung von Mai'ah, einer erfahrenen Trollmagierin, die vor dem Höhlenbau postiert ist. Für die Darkspear, deren arkane Traditionen sich von den Gelehrtenakademien der Menschen oder Hochelfen unterscheiden, dient die Tafel als formelle Aufforderung zur Disziplin. Mai'ah nutzt die Begegnung, um sowohl arkane Unterweisung als auch eine feierliche Warnung auszusprechen: Rohe Magie ist korrumpierend, trügerisch und für den Geist eines Anwenders weitaus gefährlicher als jeder feindliche Soldat."}},faq={{q="Was ist der Zweck der Glyphen-Schrifttafel?",a="Sie dient als schriftliche Vorladung, die einen angehenden Trollmagier anweist, sich bei Mai'ah, der örtlichen Magierlehrerin im Tal der Prüfungen, zu melden, um mit der eigentlichen Zauberausbildung zu beginnen.",al={"was bewirkt glyphen-schrifttafel","nutzen glyphen-schrifttafel","warum habe ich glyphen-schrifttafel"}},{q="Wer schickt die Glyphen-Schrifttafel?",a="Die Tafel wurde von der Magierlehrerin Mai'ah verfasst und jungen Trollrekruten von Gornek im Tal der Prüfungen überreicht.",al={"wer schrieb glyphen-schrifttafel","wer gab mir glyphen-schrifttafel"}},{q="Warum benötigen Trollmagier eine Warnung vor der Magie?",a="Mai'ah betont, dass arkane Magie von Natur aus korrumpierend ist. Sie warnt davor, dass sie Arroganz nährt und Zauberwirker glauben lässt, sie seien unbesiegbar, und mahnt, dass die unsichtbaren Gefahren des Arkans weitaus tödlicher sind als physische Widersacher.",al={"was sagt mai'ah","ist magie gefaehrlich"}},{q="Können andere Völker der Horde diese Tafel erhalten?",a="Nur Trollmagier erhalten die Glyphen-Schrifttafel im Tal der Prüfungen, da die Orcs von Durotar die arkanen Künste nicht ausüben.",al={"koennen orcs glyphen-schrifttafel erhalten","ist glyphen-schrifttafel nur fuer trolle"}}},fp="14,246,22.655.0,42.171.0,29.123.0,46.233.0,42.124.0"}
P.entries["item:glyphs-of-summoning"] = {n="Glyphe der Beschwörung",s="Die Glyphe der Beschwörung ist eine rituelle Inschrift, die von Hexenmeisterlehrlingen in Orgrimmar verwendet wird. Nach dem Vorbild der uralten Schrifttafel der Verga niedergeschrieben, ermöglicht sie es einem Zauberwirker, einen Leerwandler aus dem Äther in einen Beschwörungskreis zu ziehen und ihn an seine Dienste zu binden.",h="Die Glyphe der Beschwörung ist eine rituelle Inschrift, die von Hexenmeisterlehrlingen in Orgrimmar verwendet...",kw={"kluft der schatten","gan'rul bloodeye","glyphe der beschwörung","neeru fireblade","orgrimmar","schrifttafel der verga","die bindung","leerwandler"},ang={["class:Warlock"]="Die Glyphen stellen einen grundlegenden Übergangsritus für Hexenmeister der Horde dar und dienen als das Werkzeug, mit dem sie ihre Beherrschung der Leere beweisen und ihren Leerwandler-Diener beanspruchen."},sec={{t="Ein im Schatten geschmiedeter Pakt",b="In den unterirdischen Tiefen der Kluft der Schatten werden die dunklen Künste fernab der neugierigen Blicke der Wachen des Kriegshäuptlings studiert. Für einen aufstrebenden Hexenmeister unter der Anleitung von Gan'rul Bloodeye stellt das Befehligen eines Leerwandlers einen entscheidenden Schritt in seinem Handwerk dar. Die Glyphe der Beschwörung, hervorgegangen aus dem esoterischen Wissen auf der Schrifttafel der Verga, überbrückt die Grenze zwischen Azeroth und dem Äther. Wird sie im Beschwörungskreis in Neeru Fireblades Zelt ausgelegt, reißt sie eine Schwelle auf und zieht eine Kreatur der Leere in das Reich der Sterblichen. Das Ritual verlangt, dass der Hexenmeister das beschworene Wesen im Kampf bezwingt, bevor Gan'rul ihm die letzten Methoden der Bindung vermittelt."}},faq={{q="Wofür wird die Glyphe der Beschwörung verwendet?",a="Die Glyphen sind rituelle Schriftzeichen, die im Beschwörungskreis in Neeru Fireblades Zelt in Orgrimmar verwendet werden. Bei ihrer Aktivierung beschwören sie einen feindseligen Leerwandler aus dem Äther herauf, den der Hexenmeister unterwerfen muss, um die Kunst seiner Beschwörung zu meistern.",al={"was bewirkt glyphe der beschwörung","zweck glyphe der beschwörung","glyphe der beschwörung benutzen"}},{q="Woher stammt die Glyphe der Beschwörung?",a="Sie wird vom Hexenmeisterlehrer Gan'rul Bloodeye in der Kluft der Schatten bereitgestellt und basiert auf dem Wissen, das auf der Schrifttafel der Verga bewahrt wird.",al={"glyphe der beschwörung finden","wer vergibt glyphe der beschwörung"}},{q="Wo wird das Beschwörungsritual durchgeführt?",a="Das Ritual findet im Zelt von Neeru Fireblade statt, das sich auf der gegenüberliegenden Seite des Höhlenbodens in Orgrimmars Kluft der Schatten befindet.",al={"wo leerwandler beschwören","beschwörungskreis orgrimmar ort","neeru fireblade kreis"}},{q="Warum müssen Hexenmeister die beschworene Kreatur besiegen?",a="Ein Hexenmeister kann einen Dämon oder eine Kreatur der Leere nicht sicher kontrollieren, ohne seine Dominanz über sie zu etablieren. Das Besiegen des beschworenen Wesens beweist die Entschlossenheit des Hexenmeisters und ermöglicht es Gan'rul Bloodeye, ihm die Geheimnisse zu lehren, wie er diese Art an seinen Willen bindet.",al={"warum leerwandler bekämpfen","leerwandler unterwerfen"}}},fp="19,252,23.680.0,42.244.0,43.143.0,40.127.0,53.246.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="Gnoam-Sprecklesprocket",s="Das Gnoam-Sprecklesprocket ist eine hochentwickelte Energiequelle, die tief in den Todesminen aus Sneeds Schredder geborgen wurde. Gnomen-Ingenieure suchen nach diesem Bauteil, um spezialisierte Bohrmaschinen zu verstärken und so in einem ehrgeizigen Vorhaben ihre gefallene Heimat Gnomeregan zurückzuerobern.",h="Das Gnoam-Sprecklesprocket ist eine hochentwickelte Energiequelle, die tief in den Todesminen aus Sneeds...",kw={"die todesminen","gnoam-sprecklesprocket","gnomeregan","gyrobohrmatisch","shoni die schtille","sneed","sneeds schredder","sprecklesprocket"},ang={["profession:Engineering"]="Das Kettenrad ist ein Wunderwerk der miniaturisierten Energieerzeugung, das rohe Verbrennungsenergie in das nötige Drehmoment für gewaltige Bohrer umwandeln kann.",["race:Gnome"]="Jedes geborgene Bauteil bringt die verbannten Gnome näher daran, sich den Weg in ihre verlorene Heimat zu erbohren und die Trogg-Plage zu vertreiben."},sec={{t="Eine lebenswichtige Energiequelle",b="Obwohl es von Goblins hergestellt oder modifiziert wurde, die an der Seite der Bruderschaft der Defias arbeiten, stellt das Gnoam-Sprecklesprocket eine außergewöhnliche Meisterleistung kompakter mechanischer Energie dar. Tief im Inneren der schwerfälligen Maschine, die von dem Goblin-Zuchtmeister Sneed gesteuert wird, liefert dieser spezialisierte Kern genug dauerhafte Energie, um schwere industrielle Holzfäller- und Schneidklingen anzutreiben. Seine Stabilität und enorme Leistungskraft machen es zu einem unschätzbaren Bergungsgut in den unterirdischen Tunneln von Westfall."},{t="Der Durchbruch nach Gnomeregan",b="In Stormwind erkannte die Gnomen-Erfinderin Shoni die Schtille den Schredder aus den Todesminen als Schlüssel für eine größere Offensive. Die Truppen der Gnome versuchen, Gnomeregan von den Trogg-Horden zurückzuerobern, die die Stadt überrannt haben, doch die versiegelten Zugänge im Untergrund stellen ein gewaltiges Hindernis dar. Indem sie sich das Sprecklesprocket zunutze macht, beabsichtigt Shoni, schwere Gyrobohrmatische Exkavatoren anzutreiben, die imstande sind, direkt durch den massiven Fels rund um die verlorene Technostadt zu bohren und so einen unerwarteten Weg für einen unterirdischen Angriff zu schaffen."}},faq={{q="Was ist das Gnoam-Sprecklesprocket?",a="Es ist eine intakte, hochleistungsfähige mechanische Energiequelle, die tief in den Todesminen aus einem Goblins Schredder ausgebaut wurde. Sie besitzt genügend Leistung, um schwere unterirdische Bohrgeräte zu betreiben.",al={"sprecklesprocket","was ist dieses kettenrad","was ist der gegenstand"}},{q="Woher stammt das Gnoam-Sprecklesprocket?",a="Es wird aus Sneeds Schredder geborgen, einer industriellen Holzfällermaschine, die von dem Goblin-Zuchtmeister Sneed in den Sägewerken der Todesminen bedient wird.",al={"wer lässt es fallen","wie bekommt man das sprecklesprocket","schredder beute"}},{q="Warum benötigt Shoni die Schtille das Bauteil?",a="Shoni benötigt dessen Energieleistung, um Gyrobohrmatische Exkavatoren anzutreiben. Diese Maschinen sind dafür ausgelegt, das unterirdische Gestein rund um Gnomeregan zu durchbohren, damit die der Allianz treuen Gnome einen Angriff gegen die Troggs starten können.",al={"warum will shoni das","shoni questgegenstand"}},{q="Handelt es sich bei dem Kettenrad um Goblin- oder Gnomentechnologie?",a="Es war in einem Goblins Schredder verbaut, der von der Bruderschaft der Defias genutzt wurde, doch sein präziser Name und das gezielte Interesse der Gnome deuten darauf hin, dass es entweder von Gnomen entworfen, nach Gnomen-Bauplänen modifiziert oder ideal mit Gnomenmaschinerie kompatibel war.",al={"ist es goblintechnologie","gnomen- oder goblingerät"}}},fp="22,263,20.477.0,20.512.0,35.186.0,48.149.0,35.234.0,45.252.0"}
P.entries["item:gnoll-paw"] = {n="Gnolltatze",s="Gnolltatzen sind grobe physische Trophäen, die von den Flussbeißergnollen erbeutet werden, welche die Graslande von Westfall durchstreifen. Sie werden von Der Volksmiliz gesammelt und dienen als Beweis für den Erfolg einer Patrouille beim Ausdünnen der Rudel, die die örtlichen Gehöfte bedrohen.",h="Gnolltatzen sind grobe physische Trophäen, die von den Flussbeißergnollen erbeutet werden, welche die...",kw={"danuvin","gnolltatze","auf patrouille durch westfall","volksmiliz","flussbeißer","späherkuppe","westfall"},ang={["class:Hunter"]="Das Aufspüren aggressiver Flussbeißerrudel in den offenen Ebenen von Westfall bietet Jägern unkomplizierte Beute und hilft gleichzeitig dabei, ländliche Außenposten zu sichern.",["faction:Alliance"]="Für Streiter der Allianz ist die Annahme von Kopfgeldern für Die Volksmiliz unerlässlich, um zu verhindern, dass Stormwinds westliche Kornkammer vollends an umherstreifende wilde Bestien und organisierte Banditen fällt."},sec={{t="Kopfgeld der Miliz",b="Da die königliche Armee abwesend ist und die Krone die Not der ländlichen Siedlungen scheinbar ignoriert, ist die Verteidigung von Westfall einfachen Bürgern und freiwilligen Kräften anheimgefallen. Die Volksmiliz, die von der Späherkuppe aus operiert, kämpft ununterbrochen gegen Gesetzlose, abtrünnige Mechanoide und aggressive, hyänenköpfige Gnolle. Um der Gnollbedrohung Einhalt zu gebieten, setzte Captain Danuvin Kopfgelder aus, die handfeste Beweise für getötete Bestien verlangen. Das Sammeln abgetrennter Tatzen ist eine grausame Notwendigkeit, um sicherzustellen, dass angeheuerte Abenteurer das Buschland wirklich durchkämmen, anstatt im Schatten des Wachturms zu faulenzen."},{t="Eine koordinierte Bedrohung",b="Die Flussbeißergnolle in Westfall sind mehr als bloß wilde Bestien, die in den Ebenen nach Nahrung suchen. Beobachter der Miliz haben beunruhigende Anzeichen dafür bemerkt, dass diese Gnolle in enger Abstimmung mit den Defias-Dieben rund um Die Todesminen agieren. Indem sie abgelegene Gehöfte terrorisieren und durchreisende Versorgungswagen überfallen, schirmen die Gnollrudel die Banditen effektiv vor dem örtlichen Widerstand ab. Sie zurückzudrängen, indem man ihre Tatzen abliefert, trägt dazu bei, die prekären Überlandrouten zwischen der Späherkuppe und dem Wald von Elwynn offenzuhalten."}},faq={{q="Warum möchte Captain Danuvin Gnolltatzen?",a="Captain Danuvin nutzt die Tatzen als Beweis für eine erfolgreiche Patrouille durch die Ebenen von Westfall. Da die Ressourcen der Miliz knapp sind und die Krone keine Hilfe leistet, werden Kopfgelder nur ausgezahlt, wenn Rekruten greifbare Beweise für tote Gnolle vorlegen.",al={"warum tatzen sammeln","danuvin gnolltatzen","wofür sind gnolltatzen"}},{q="Welche Gnolle lassen diese Tatzen fallen?",a="Sie werden von den verschiedenen Flussbeißergnollen erbeutet, die überall in Westfall die Graslande, Hügel und verlassenen Höfe durchstreifen.",al={"woher gnolltatzen bekommen","welche gnolle haben tatzen","gnolltatze fundort"}},{q="Handeln die Gnolle in Westfall allein?",a="Nein. Captain Danuvin und die Miliz vermuten, dass die Flussbeißergnolle mit den Banditen und Dieben zusammenarbeiten, die von Den Todesminen aus operieren, was den örtlichen Gehöften doppelte Schwierigkeiten bereitet.",al={"arbeiten gnolle mit defias zusammen","gnoll verbindung todesminen","wer befehligt die gnolle"}},{q="Warum kümmert sich Stormwind nicht um die Gnollbedrohung?",a="Stormwind hat Westfall aufgrund innerer Unruhen und politischer Lähmung weitgehend sich selbst überlassen. Die Verteidigung des Umlands bleibt fast vollständig den örtlichen Bauern und Der Volksmiliz überlassen.",al={"warum keine armee von stormwind","wo ist die armee","warum bekämpft die miliz gnolle"}}},fp="9,240,21.582.0,20.523.0,41.240.0,29.133.0,40.206.0,50.206.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Kaugummikugel aus Gnomeregan",s="Eine Kaugummikugel aus Gnomeregan ist eine saisonale Süßigkeitenspezialität, die während der Schlotternächte im Namen der vertriebenen Gnome verteilt wird. Abenteurer beschaffen dieses Konfekt, um dem kranken Kind Jesper im Waisenhaus von Stormwind bei den Feierlichkeiten des Festes zu helfen.",h="Eine Kaugummikugel aus Gnomeregan ist eine saisonale Süßigkeitenspezialität, die während der Schlotternächte...",kw={"süßigkeiten","kaugummikugel aus gnomeregan","schlotternächte","ironforge","jesper","stormwind","talvash del kissel"},ang={["faction:Alliance"]="Das Beschaffen dieser Süßigkeit erfordert Reisen zwischen menschlichen, zwergischen und gnomischen Gemeinschaften und zeigt die engen Bande zwischen den Völkern der Allianz während der Festtage.",["race:Gnome"]="Selbst ohne eine zurückeroberte eigene Stadt sind die Gnome stolz darauf, dass ihre eigene charakteristische Süßware während der Schlotternächte unter den großen Hauptstädten der Allianz vertreten ist."},sec={{t="Ein Vorgeschmack auf gnomischen Erfindungsgeist",b="Während Gastwirte in der gesamten Allianz während der Schlotternächte regionale Leckereien verteilen, verfügen die im Exil lebenden Gnome von Gnomeregan über kein eigenes vollwertiges Gasthaus in einer Hauptstadt, das sie betreiben könnten. Stattdessen verteilt der erfinderische Gnom Talvash del Kissel, der im Mystic Ward von Ironforge lebt, Kaugummikugeln aus Gnomeregan an Reisende, die bereit sind, bei seinen festlichen Späßen mitzuspielen. Trotz der radioaktiven Katastrophe, die sein Volk aus seinem unterirdischen Königreich vertrieb, teilen die Gnome ihr unverkennbares Konfekt nach wie vor stolz mit der gesamten Allianz."},{t="Eine Leckerei für Jesper",b="Da Jesper krank ist und das Waisenhaus von Stormwind auf dem Cathedral Square nicht verlassen kann, ist es ihm nicht möglich, über die Kontinente zu reisen, um selbst nach Süßem oder Saurem zu fragen. Eine Kaugummikugel aus Gnomeregan ist eine der vier unverzichtbaren regionalen Süßwaren – neben Leckereien aus Stormwind, Ironforge und Darnassus –, die gutherzige Reisende in den Hauptstädten der Allianz sammeln, um ihm die Feierlichkeiten näherzubringen."}},faq={{q="Woher stammt eine Kaugummikugel aus Gnomeregan?",a="Sie wird von Talvash del Kissel ausgegeben, einem Gnomtüftler, der sich im Mystic Ward von Ironforge aufhält, wenn Ihr während der Schlotternächte ein Kunststückchen für ihn vollführt.",al={"wer vergibt kaugummikugel aus gnomeregan","kaugummikugel bekommen","kaugummikugel fundort"}},{q="Warum wird diese Süßigkeit nicht in Gnomeregan verteilt?",a="Gnomeregan wurde von Troggs überrannt und verstrahlt, was die überlebenden Gnome ins Exil zwang. Viele, darunter Talvash del Kissel, leben nun an der Seite der Zwerge in Ironforge.",al={"warum ironforge","warum ist talvash in ironforge"}},{q="Wofür wird diese Süßigkeit verwendet?",a="Sie ist eine von vier festlichen Süßigkeiten, die benötigt werden, um die Schlotternächte-Aufgabe für Jesper abzuschließen, einen kranken Waisenjungen im Waisenhaus auf dem Cathedral Square in Stormwind.",al={"was macht die kaugummikugel","jesper süßigkeiten"}},{q="Welche anderen Leckereien werden neben ihr gesammelt?",a="Jesper bittet außerdem um Nugat aus Stormwind, ein Pfefferminzbonbon aus Ironforge und Marzipan aus Darnassus, die jeweils in den entsprechenden Hauptstädten der Allianz gesammelt werden.",al={"weitere süßigkeiten","schlotternächte süßigkeiten"}}},fp="18,229,28.515.0,18.378.0,42.160.0,46.170.0,28.153.0,45.137.0"}
P.entries["item:gnomish-tools"] = {n="Gnomen-Werkzeuge",s="Gnomen-Werkzeuge sind kunstvolle mechanische Gerätschaften, die aus den versunkenen Kriegsschiffen der Flotte von Großadmiral Daelin Proudmoore vor der Küste von Durotar geborgen wurden. Die Horde sucht nach diesen geborgenen Vorrichtungen, um die Ingenieurskunst der Allianz zu studieren und die technologischen Vorteile ihrer Feinde zu ihrem eigenen Nutzen einzusetzen.",h="Gnomen-Werkzeuge sind kunstvolle mechanische Gerätschaften, die aus den versunkenen Kriegsschiffen der Flotte...",kw={"durotar","ingenieurskunst","gar'thok","gnomen-werkzeuge","proudmoore","klingenhügel","schipperküste","burg tiragarde"},ang={["faction:Horde"]="Die Bergung verlorener Allianz-Ausrüstung ermöglicht es der Horde, feindliche Konstruktionen zu untersuchen, fremde Mechanismen nachzukonstruieren und sich gegen zukünftige Invasionen von See her zu verteidigen.",["profession:Engineering"]="Diese Ausrüstungssets zeugen von der präzisen, komplexen Handwerkskunst der Allianz-Tüftler und bieten wertvolle Einblicke in Uhrwerkbaugruppen sowie Miniaturisierung."},sec={{t="Versunkene Bergungsgüter",b="Als Großadmiral Daelin Proudmoore die Streitkräfte von Kul Tiras und der Allianz an die Küsten von Durotar führte, transportierte seine Flotte gewaltige Vorräte an moderner Ausrüstung, darunter hochentwickeltes Gerät, das von ihren Gnomen-Verbündeten hergestellt worden war. Nach der Zerstörung von Proudmoores Flotte entlang der Schipperküste östlich von Burg Tiragarde sanken diese empfindlichen mechanischen Ausrüstungssets unter die Wellen. Heute liegen noch immer wasserdichte Werkzeugkästen verstreut zwischen dem verrottenden Holz und den von Seepocken überwucherten Rümpfen in den Untiefen."},{t="Augen in Orgrimmar",b="Gar'Thok, Aufseher von Klingenhügel, beauftragte Späher der Horde damit, diese Werkzeuge aus dem nassen Grab von Proudmoores Kriegsmarine zu bergen. Die Orcs erkennen an, dass Menschen und Gnome über fortschrittliche technische Handwerkskunst verfügen, insbesondere bei Belagerungsmaschinen, im Schiffbau und bei der Uhrwerkmechanik. Indem diese Sets gesammelt und per Karawane zu den Handwerkern und Gelehrten in Orgrimmar geschickt werden, beabsichtigt die Horde, die Apparaturen der Allianz zu zerlegen, Abwehrmöglichkeiten gegen ihre Kriegsmaschinen zu erlernen und fremde Innovationen für das eigene Überleben anzupassen."}},faq={{q="Warum liegen Gnomen-Werkzeuge vor der Küste von Durotar?",a="Sie wurden an Bord der Kriegsschiffe aus der Flotte von Großadmiral Daelin Proudmoore transportiert, als Kul Tiras Durotar angriff. Als Proudmoores Armada entlang der Schipperküste östlich von Burg Tiragarde zerschmettert wurde und sank, setzte sich ihre Schiffsladung auf dem Meeresgrund ab.",al={"warum gnomen-werkzeuge hier","herkunft der gnomen-werkzeuge","wie kamen werkzeuge nach durotar"}},{q="Warum will die Horde diese Werkzeuge?",a="Gar'Thok von Klingenhügel möchte sie bergen lassen, damit sie nach Orgrimmar geschickt werden können. Die Horde weiß, dass die Ingenieure der Allianz über ausgefeiltes mechanisches Wissen verfügen, und das Studium ihrer Werkzeuge hilft der Horde zu verstehen, wie feindliche Maschinen funktionieren und wie man selbst bessere Ausrüstung herstellt.",al={"warum will gar'thok werkzeuge","nutzen der horde für gnomen-werkzeuge","wofür sind die werkzeuge"}},{q="Wo sind die Werkzeuge zu finden?",a="Sie befinden sich in Werkzeugkästen, die in und um die versunkenen Wracks entlang der Schipperküste, direkt östlich von Burg Tiragarde in Durotar, verstreut liegen. Viele ruhen unter Wasser oder auf halb überfluteten, zerborstenen Rümpfen.",al={"gnomen-werkzeuge fundort","gnomen-werkzeuge finden","gnomen-werkzeugkästen fundort"}}},fp="13,293,14.485.0,17.521.0,53.259.0,36.280.0,26.201.0"}
P.entries["item:gold-dust"] = {n="Goldstaub",s="Goldstaub besteht aus feinen Flocken von Edelmetall, die von den Kobolden, welche die Minen im Wald von Elwynn heimsuchen, gesiebt und gehortet werden. Während gewöhnliche Bergleute nach intakten Erzadern suchen, zahlen örtliche Opportunisten jedem gutes Geld, der bereit ist, dem Ungeziefer diese gesammelten Partikel zu entreißen.",h="Goldstaub besteht aus feinen Flocken von Edelmetall, die von den Kobolden, welche die Minen im Wald von...",kw={"elwynn","tiefenschacht","goldstaub","goldhain","goldzahn","jaspis","kobold","remy zweifach"},ang={["class:Rogue"]="Der Handel mit unverarbeitetem, nicht zurückverfolgbarem Staub mit zwielichtigen Gestalten wie Remy \"Zweifach\" bietet eine praktische Lektion darin, wie die Unterwelt rohen Reichtum vor den Augen der Richter von Stormwind wäscht.",["profession:Mining"]="Während Bergleute mit Spitzhacke und Pfanne nach festen Kupfer- und Zinnadern suchen, beweist der Koboldstaub, dass die unterirdischen Gänge von Elwynn reichere Vorkommen bergen, als herkömmliche Gutachten vermuten lassen."},sec={{t="Ein Beutel voller Reste",b="Unter dem Boden des Walds von Elwynn scharren Kobolde in den unterirdischen Stollen der Tiefenschachtmine und der Jaspismine. Anstatt das freigelegte Erz ordnungsgemäß zu verhütten, horten die rattenartigen Kreaturen groben Goldstaub oft direkt in ihren Taschen und Beuteln. Diese kleinen, glitzernden Späne sind das Ergebnis mühsamer unterirdischer Sammlerarbeit – von echten Bergbau-Syndikaten leicht übersehen, aber von örtlichen Hausierern und Hehlern heiß begehrt, die ohne die Zahlung offizieller Schmelzzölle einen heimlichen Gewinn einstreichen wollen."},{t="Goldhains Schwarzmarkt",b="In der Ortschaft Goldhain hat es sich Remy \"Zweifach\" zur Gewohnheit gemacht, Reisende nach geborgenem Goldstaub zu fragen. Remy behauptet, den besten Preis im Ort zu zahlen, und tauscht im Namen seiner ungenannten Geschäftspartner Münzen und verdächtige Wertmarken gegen Beutel mit rohem Staub ein. Indem Hintergassen-Händler abenteuerlustige Söldner dafür einspannen, den Kobolden das Gold direkt aus ihren Klauen zu entreißen, behalten sie saubere Hände, während sie sich direkt vor den Augen der Wachen von Stormwind unauffindbaren Reichtum sichern."}},faq={{q="Woher stammt Goldstaub?",a="Goldstaub wird von Kobolden im gesamten Wald von Elwynn mitgeführt. Minenarbeiter, Tunnelgräber, Geomanten und ihr berüchtigter Anführer Goldzahn sammeln und horten die schimmernden Partikel, während sie sich durch die Hügel graben.",al={"wie man goldstaub bekommt","goldstaub beute","wo goldstaub finden"}},{q="In welchen Minen gibt es die meisten Kobolde mit Goldstaub?",a="Die Tiefenschachtmine südlich von Goldhain und die Jaspismine im Nordosten sind beide von Kobolden überrannt, die den Staub bei sich tragen.",al={"wo sind die minen","beste mine fuer goldstaub","minen standorte"}},{q="Wer kauft Goldstaub im Wald von Elwynn?",a="Remy \"Zweifach\", ein zwielichtiger Händler, der vor dem Lion's Pride Inn in Goldhain Geschäfte macht, kauft gesammelte Beutel mit Goldstaub eifrig gegen Geld und Wertmarken seiner Geschäftspartner an.",al={"wer will goldstaub","remy zweifach goldstaub","goldstaub abgeben"}},{q="Warum tragen Kobolde Staub statt Barren bei sich?",a="Kobolden fehlt es an der Disziplin und der nötigen Infrastruktur für eine ordnungsgemäße Verhüttung. Während sie mit primitiven Spitzhacken an den Felswänden scharren, sammelt sich loser Goldstaub an ihren Habseligkeiten und in kleinen Beuteln, die sie als glänzende Schmuckstücke bei sich tragen.",al={"warum haben kobolde staub","koboldgold"}}},fp="9,268,22.524.0,24.472.1,31.204.0,53.146.0,36.183.0,44.222.0"}
P.entries["item:golm-fragment"] = {n="Golm-Fragment",s="Das Golm-Fragment ist eines von vier fehlenden Bruchstücken, die vom Goazstein abgeschlagen wurden – einem uralten Relikt, das an der Ausgrabungsstätte im Wetlands freigelegt wurde. Von Abenteurern geborgen, die wilden Raptoren ausweichen mussten, hilft es Zwergenarchäologen dabei, geheimnisvolle Titaneninschriften zusammenzusetzen.",h="Das Golm-Fragment ist eines von vier fehlenden Bruchstücken, die vom Goazstein abgeschlagen wurden – einem...",kw={"ausgrabungsstätte","goazstein","golm-fragment","enthüllung der vergangenheit","wetlands","whelgar"},ang={["faction:Alliance"]="Die Bergung des Fragments unterstützt die Explorers' League dabei, unbezahlbares altes Wissen zu sichern, bevor die Ausgrabungsstätte gänzlich an die Raptoren verloren geht.",["race:Dwarf"]="Für Zwerge ist das Zusammensetzen der Bruchstücke des Goazsteins von entscheidender Bedeutung, um ihre Titanenabstammung und die in Khaz Modan verborgene Geschichte aufzudecken."},sec={{t="Ein Bruchstück des Goazsteins",b="Das an der Ausgrabungsstätte im südlichen Wetlands entdeckte Golm-Fragment ist Teil einer monumentalen Tafel namens Goazstein. Ausgrabungsleiter Whelgar entdeckte den Stein kurz bevor Raptoren die Explorers' League zurückdrängten, fand dessen Inschrift jedoch an vier entscheidenden Stellen durchtrennt vor. Das Golm-Fragment wurde inmitten von Schmutz und umgestürzten Kisten zurückgelassen, als die Grabung überrannt wurde, verborgen in einer uralten Reliktkiste, bis mutige Forscher es bergen konnten."},{t="Geheimnisse der Titanen",b="Zusammen mit den Ados-, Modr- und Neru-Fragmenten vervollständigt das Golm-Fragment einen kryptischen Titanentext, der einen 'göttlichen Plan' und eine 'düstere Prophezeiung' ankündigt. Das Zusammensetzen des Steins ermöglicht es Whelgar, Zeilen zu entziffern, die von uralten, unter der Erde angeketteten Wesenheiten sprechen, was bestätigt, dass die Stätte Überlieferungen birgt, die weitaus älter und gefährlicher sind als das schlichte Erbe der Zwerge."}},faq={{q="Wofür wird das Golm-Fragment verwendet?",a="Es ist eine von vier Steinscherben, die von Ausgrabungsleiter Whelgar an der Ausgrabungsstätte im Wetlands benötigt werden, um während der Quest Enthüllung der Vergangenheit den Goazstein wiederherzustellen.",al={"golm-fragment zweck","wozu golm-fragment","golm-fragment quest"}},{q="Wo kann das Golm-Fragment gefunden werden?",a="Man findet es in uralten Relikten und loser Erde, die über die von Raptoren heimgesuchte Ausgrabungsstätte in den südlichen Hügeln des Wetlands verstreut sind.",al={"golm-fragment fundort","golm-fragment finden","wo ist das golm-fragment"}},{q="Was besagt der Goazstein, sobald er zusammengesetzt ist?",a="Ausgrabungsleiter Whelgars erste Übersetzung enthüllt eine Titanenschrift, die eine düstere Prophezeiung beschreibt und 'Alte Götter... Angekettet unter dem Land' erwähnt.",al={"goazstein übersetzung","was steht auf der tafel","whelgars übersetzung"}},{q="Welche anderen Fragmente werden benötigt, um den Stein zu vervollständigen?",a="Neben Golm müsst Ihr die Fragmente Ados, Modr und Neru bergen, um die Tafel vollständig zusammenzusetzen.",al={"andere tafelfragmente","goazstein bruchstücke","vier fragmente"}}},fp="13,266,25.462.0,21.363.1,35.155.0,37.137.0,44.142.1,52.98.0"}
P.entries["item:gordon-s-crate"] = {n="Gordons Kiste",s="Gordons Kiste ist eine schwere Waffenlieferung, die in Undercity für die im Silberwald stationierten Streitkräfte der Verlassenen gepackt wurde. Sie dient als essenzielle Nachschubsendung, die direkt zur abgelegenen Garnison beim Grabmal transportiert werden soll.",h="Gordons Kiste ist eine schwere Waffenlieferung, die in Undercity für die im Silberwald stationierten...",kw={"fledermaushändler","todeswache podrig","gordons kiste","karos razok","michael garrett","silberwald nachschub","das grabmal","undercity"},ang={["faction:Horde"]="Die Lieferung demonstriert die wachsende Vernetzung der Flugrouten der Verlassenen, über die Nachschub und Kuriere zügig durch das umkämpfte Lordaeron transportiert werden.",["race:Undead"]="Jede Lieferung von Klingen und Ausrüstung aus der Hauptstadt festigt Lady Sylvanas' prekäre Grenzregionen im Silberwald."},sec={{t="Nachschub für den Silberwald",b="Um die Kontrolle der Verlassenen über den Silberwald aufrechtzuerhalten, bedarf es eines stetigen logistischen Nachschubs aus Undercity. Gordons Kiste enthält Rüstungsgüter, die Todeswache Podrigs Verteidiger beim Grabmal verstärken sollen, damit die Vorpostenwachen nicht von den Worgen, wilden Bestien oder menschlichen Überresten überrascht werden, die in den Wäldern lauern."},{t="Die Route des Fledermaushändlers",b="Da Überlandstraßen aus der Hauptstadt gefährlich und langsam sind, verlassen sich wertvolle Lieferungen auf die Fledermaushändler von Undercity. Die Kiste wird Michael Garrett übergeben, dem Fledermausmeister hoch über dem Trade Quarter der Stadt, der die Weiterreise auf einer trainierten Flugfledermaus zurück zum Horst von Karos Razok beim Grabmal sichert."}},faq={{q="Was befindet sich in Gordons Kiste?",a="Die Kiste enthält Waffen und wichtige Kampfausrüstung, die in Undercity angefordert wurden, um die im Silberwald stationierten Wachen der Todeswache zu verstärken.",al={"inhalt von gordons kiste","was enthält kiste"}},{q="Wer soll Gordons Kiste erhalten?",a="Todeswache Podrig beim Grabmal nimmt die Kiste in Empfang. Ihr Transport erfordert die Abstimmung mit dem Fledermaushändler Michael Garrett in Undercity, um einen direkten Flug zu arrangieren.",al={"wer bekommt gordons kiste","wohin geht die kiste"}},{q="Warum wird die Kiste mit einer Fledermaus anstelle eines Fußboten transportiert?",a="Der Silberwald bleibt umkämpft und gefährlich. Der Einsatz abgerichteter Fledermäuse unter der Aufsicht von Händlern wie Michael Garrett und Karos Razok gewährleistet einen schnellen Lufttransport, der feindliche Bedrohungen entlang der Bodenrouten umgeht.",al={"warum kiste fliegen","fledermaus reise kiste"}},{q="Warum verlangt Michael Garrett, dass Ihr zuerst Das Grabmal besucht?",a="Fledermäuse der Verlassenen kehren instinktiv in die Hauptstadt zurück. Um jedoch Außenposten wie Das Grabmal sicher zu erreichen, müssen Reisende zuvor eine Verbindung zum örtlichen Betreuer Karos Razok hergestellt haben, bevor Fledermäuse die Reise antreten können.",al={"warum flugpunkt nötig","fledermaus flugvoraussetzung"}}},fp="14,240,23.322.0,23.309.0,30.150.0,42.163.0,65.209.0,66.220.0"}
P.entries["item:grape-manifest"] = {n="Traubenliste",s="Die Traubenliste ist ein handschriftliches Verzeichnis, das die Ernte aus Milly Osworths Weinberg im Nordhaintal erfasst. Sie dokumentiert die Rückgewinnung frischer Früchte, nachdem örtliche Banditen die Felder überrannt hatten, bestimmt für die Keller der Abtei von Nordhain.",h="Die Traubenliste ist ein handschriftliches Verzeichnis, das die Ernte aus Milly Osworths Weinberg im...",kw={"bruder neals","elwynn","traubenliste","milly osworth","abtei von nordhain","weinberg","wein"},ang={["profession:Cooking"]="Für Köche verkörpert die Liste das empfindliche Gleichgewicht zwischen den Ernteerträgen der Felder und den Vorratskammern der Abtei und zeigt, wie lokale Zutaten eine ganze Klostergemeinschaft ernähren.",["race:Human"]="Das Dokument verdeutlicht die frühen Kämpfe im Kernland von Stormwind, wo selbst das klösterliche Leben und einfache Ernten der bewaffneten Verteidigung gegen umherziehende Gesetzlose bedürfen."},sec={{t="Ein Bericht über die Ernte",b="Die Abtei von Nordhain versorgt sich seit Langem durch die regionale Landwirtschaft, einschließlich der üppigen Weinberge, die von einheimischen Bauern wie Milly Osworth bewirtschaftet werden. Als Defias-Banditen in das Tal eindrangen und die Ernte an sich rissen, gerieten die Vorräte der Abtei an frischem Obst und gärenden Waren in Gefahr. Die Traubenliste dient als offizielle Bestätigung dafür, dass die Kisten von den Feldern zurückgeholt wurden. Sie führt die Menge der geretteten Weintrauben auf, damit die Quartiermeister der Abtei ihre Vorräte ausgleichen und Fässer für die Gärung vorbereiten können."},{t="Der Kellermeister der Abtei",b="Bruder Neals beaufsichtigt die Speisen und Getränke von Nordhain und hegt eine besondere Vorliebe dafür, den Jahrgang der Abtei in der erhabenen Stille des Glockenturms zu verkosten. Für ihn ist der Erhalt der Liste nicht bloß administrative Schreibarbeit; sie stellt sicher, dass die Mönche und eintreffenden Rekruten nicht durstig bleiben. Für die frommen Brüder der Abtei wird jeder gerettete Scheffel sowohl als logistischer Sieg als auch als stiller Segen des Heiligen Lichts gefeiert."}},faq={{q="Was ist die Traubenliste?",a="Sie ist ein von Milly Osworth verfasstes Inventardokument, das die von ihrem überrannten Weinberg zurückgeholte Ernte festhält. Sie erfasst die Menge der frischen Weintrauben, die an die Abtei von Nordhain geliefert werden.",al={"was ist traubenliste","traubenliste gegenstand"}},{q="Wer erhält die Liste?",a="Bruder Neals nimmt sie entgegen. Er wacht über die Vorräte der Abtei an Nahrung und Wein und ist gewöhnlich dabei anzutreffen, wie er oben im Glockenturm der Abtei von Nordhain Jahrgänge verkostet.",al={"wer erhält traubenliste","wem gebe ich traubenliste","wohin gehört traubenliste"}},{q="Warum waren die Weintrauben in Gefahr?",a="Defias-Banditen fielen im Nordhaintal ein und vertrieben Milly Osworth von ihrem Weinberg, womit sie die Ernte bedrohten und die Versorgung der Abtei mit frischen Früchten abschnitten, bis Rekruten eingriffen.",al={"warum trauben retten","weinberg banditen","was geschah mit millys ernte"}},{q="Was macht Bruder Neals mit den Weintrauben?",a="Bruder Neals verwendet sie, um die Nahrungsvorräte der Abtei aufzufüllen und frischen Nordhain-Wein zu keltern, der sowohl die ansässige Bruderschaft als auch die eintreffenden Verteidiger versorgt.",al={"wofür werden trauben verwendet","abteiwein"}}},fp="14,243,23.519.0,20.436.0,27.185.0,26.154.0,30.192.0,43.166.0"}
P.entries["item:gray-bear-tongue"] = {n="Graubärenzunge",s="Eine Graubärenzunge ist ein rohes Reagenz, das von den wilden Bären erbeutet wird, die das Vorgebirge von Hillsbrad durchstreifen. Sie wird von der Königlichen Apothekervereinigung in Tarrens Mühle gesucht, um als biologische Komponente in ihren experimentellen Toxinen zu dienen.",h="Eine Graubärenzunge ist ein rohes Reagenz, das von den wilden Bären erbeutet wird, die das Vorgebirge von...",kw={"apotheker lydon","big samras","elixier des leidens","graubärenzunge","vorgebirge von hillsbrad","königliche apothekervereinigung","tarrens mühle"},ang={["race:Undead"]="Die Beschaffung organischer Komponenten von der örtlichen Tierwelt unterstützt direkt die Mission der Königlichen Apothekervereinigung, neue Seuchen gegen die Lebenden herzustellen."},sec={{t="Apothekerforschung in Hillsbrad",b="Die ungezähmte Wildnis rund um Tarrens Mühle ist reich an einheimischer Fauna, darunter verschiedene Arten von robusten Graubären. Während natürliche Raubtiere eine ständige Bedrohung für Reisende darstellen, betrachten die Verlassenen sie als ergiebige Quelle für rohe Alchemiekomponenten. Apotheker Lydon erforscht die örtliche Tierwelt, um wirksame organische Wirkstoffe zu isolieren, und verwendet das schwere Muskelgewebe sowie die Flüssigkeiten von Graubärenzungen als Grundzutat zum Brauen tödlicher Lösungen wie dem Elixier des Leidens."}},faq={{q="Wer benötigt Graubärenzungen?",a="Apotheker Lydon, der im Außenposten der Verlassenen in Tarrens Mühle im Vorgebirge von Hillsbrad stationiert ist, sucht diese Zungen, um experimentelle tödliche Substanzen zu brauen.",al={"wer braucht bärenzungen","apotheker lydon zungen","bärenzunge abgabe"}},{q="Wofür verwendet der Apotheker diese Zungen?",a="Lydon entwickelt ein tödliches Gebräu namens Elixier des Leidens, das dazu bestimmt ist, die lebende menschliche Bevölkerung von Hillsbrad mit der Seuche zu überziehen. Die Zungen dienen neben Krabblersekret als einer der primären organischen Wirkstoffe.",al={"warum will lydon zungen","bärenzunge verwendung","elixier des leidens zutaten"}},{q="Welche Kreaturen lassen diese Zungen fallen?",a="Sie können von allen einheimischen Graubären erbeutet werden, die das Vorgebirge von Hillsbrad durchstreifen, darunter gewöhnliche Graubären, uralte Graubären, bösartige Graubären und die berüchtigte Bestie Großer Samras.",al={"wo droppen bärenzungen","welche bären haben zungen","hillsbrad bären"}}},fp="16,229,32.479.0,28.151.0,47.220.0,35.192.0"}
P.entries["item:gregor-s-remains"] = {n="Gregors sterbliche Überreste",s="Gregors sterbliche Überreste sind die physischen Gebeine, die von dem durch die Geißel versklavten Gregor Agamand geborgen wurden. Einst Teil der wohlhabendsten Dynastie in Tirisfal, werden seine Überreste von einem ehemaligen Mühlenarbeiter gesucht, der darauf brennt, eine alte Rechnung über das Grab hinaus zu begleichen.",h="Gregors sterbliche Überreste sind die physischen Gebeine, die von dem durch die Geißel versklavten Gregor...",kw={"agamand","brill","coleman","todesfälle in der familie","farthing","gregor","mühlen","überreste","geißel"},ang={["faction:Horde"]="Das Säubern von Agamands Mühlen versetzt den verbliebenen Geißelnestern, welche die Sicherheit von Tirisfal bedrohen, einen direkten Schlag.",["race:Undead"]="Die Agamand-Tragödie spiegelt das Schicksal vieler Verlassener wider: gewöhnliche Leute, die durch den Stolz des Adels verraten und den Schrecken der Seuche überlassen wurden."},sec={{t="Ein Vermächtnis des Ruins",b="Vor dem Dritten Krieg besaß die Familie Agamand ungeheuren Reichtum und weite Ländereien im Norden von Tirisfal. Als die Geißel in Lordaeron einfiel, entschieden sich die Patriarchen für Stolz statt Flucht, befestigten ihre Familienmühlen und überredeten ihre loyalen Arbeiter zu einem verzweifelten Widerstand gegen die Untoten. Die Verteidigung schlug völlig fehl. Das Anwesen wurde überrannt, und jene, die standhielten, wurden abgeschlachtet und im Untod wiedererweckt. Gregor Agamand wurde zu einem weiteren geistlosen Knecht im Dienste des Lichkönigs und sucht seither genau jene Mühlen heim, die seine Familie einst beherrschte."},{t="Der Preis der Vergeltung",b="Für Überlebende, die sich aus dem Griff des Lichkönigs befreiten, um sich den Verlassenen anzuschließen, bleibt die Erinnerung an jene verhängnisvolle Verteidigung eine bittere Wunde. Coleman Farthing, ein ehemaliger Mühlenarbeiter, der in Brill stationiert ist, gibt der Hybris der Agamands die Schuld daran, dass seine Seele in ewiger Fäulnis gefangen ist. Gregors sterbliche Überreste zu sammeln, bietet Farthing ein gewisses Maß an persönlicher Vergeltung und schließt das Kapitel über einen Herrn ab, der sein Gefolge geradewegs in die Verdammnis führte."}},faq={{q="Wer war Gregor Agamand?",a="Gregor Agamand war ein prominentes Mitglied der Agamand-Dynastie, der wohlhabendsten Landbesitzerfamilie in Tirisfal vor dem Dritten Krieg. Als die Seuche des Untods eintraf, entschieden er und seine Familie sich dafür, ihr Anwesen zu befestigen, statt zu fliehen, was zum Abschlachten und zur Wiedererweckung aller Anwesenden führte.",al={"gregor lore","wer ist gregor","gregor agamand"}},{q="Warum will Coleman Farthing Gregors sterbliche Überreste?",a="Coleman Farthing war im Leben ein Mühlenarbeiter im Dienst der Agamands. Er hegt tiefen Groll gegen die Familie, weil sie ihre Arbeiter überredete, zu bleiben und gegen die Geißel zu kämpfen – eine Fehlentscheidung, die sie alle zum Untod verdammte. Dass Gregors sterbliche Überreste zu ihm gebracht werden, dient als lang aufgeschobene Rache.",al={"warum coleman überreste will","coleman farthing groll","warum gregors knochen sammeln"}},{q="Wo sind Gregors sterbliche Überreste zu finden?",a="Die Überreste werden von der auferstandenen Gestalt von Gregor Agamand bei Agamands Mühlen erbeutet, die in den nördlichen Hügeln von Tirisfal liegen.",al={"wo gregor zu finden ist","gregor aufenthaltsort","agamands mühlen gregor"}},{q="Sind die Agamands Teil der Verlassenen?",a="Nein. Anders als die Verlassenen, die sich unter Königin Sylvanas befreiten, bleiben Gregor Agamand und seine Sippe geistlose Diener, die an den Willen der Geißel gekettet sind.",al={"ist gregor ein verlassener","gehören die agamands zur geißel","wer kontrolliert gregor"}}},fp="16,246,16.557.0,22.424.0,23.299.0,48.276.0,33.135.0,38.148.0"}
P.entries["item:grelin-s-report"] = {n="Grelins Bericht",s="Grelins Bericht ist eine von Grelin Whitebeard verfasste Depesche, welche die Lage der Frostmanetrolle im Coldridgetal darlegt. Da er einem Abenteurer statt einem ungeschickten Lehrling anvertraut wird, dient er als offizielle Verbindung zwischen den Spähern, die Anvilmar bewachen, und Senir Whitebeard, der in Kharanos stationiert ist.",h="Grelins Bericht ist eine von Grelin Whitebeard verfasste Depesche, welche die Lage der Frostmanetrolle im...",kw={"das coldridgetal","grelin whitebeard","grelins bericht","senat von ironforge","kharanos","gebirgsjäger thalos","senir whitebeard"},ang={["race:Dwarf"]="Das Überbringen dieses Berichts ist für einen Zwerg der Übergang von den sicheren Übungsplätzen von Coldridge in die umfassendere Verteidigung des Kernlandes von Dun Morogh und den Dienst für Ironforge.",["race:Gnome"]="Das Überbringen von Grelins Nachricht ermöglicht es gnomischen Flüchtlingen, ihren Mut vor den zwergischen Gebirgsjägern unter Beweis zu stellen, während sie die gemeinsamen Gebirgspässe von Dun Morogh durchqueren."},sec={{t="Eine Depesche an den Troggs vorbei",b="Grelins Bericht, verfasst nach der Beobachtung der Frostmanetrolle im Coldridgetal, kommt zu dem Schluss, dass sie keine große Bedrohung darstellen und von den bereits dort stationierten Gebirgsjägern sowie aus Senatsmitteln bezahlten Söldnern bewältigt werden können. Anstatt seinem ungeschickten Lehrling solch entscheidende Informationen anzuvertrauen, wirbt Grelin einen fähigen Reisenden an, um das Dokument durch den von Troggs verseuchten Coldridgepass zu bringen. Das Schriftstück dient als offizieller Passierschein durch die Blockade von Gebirgsjäger Thalos und beweist, dass der Überbringer in dringenden Angelegenheiten in die weiteren verschneiten Weiten von Dun Morogh reist."},{t="Aufruhr in Kharanos",b="Als der Bericht Senir Whitebeard in der Brauerei Donnerbräu in Kharanos überbracht wird, liefert er entscheidende Lageberichte für Ironforge. Senir stellt mit amüsierter Resignation fest, dass sein Bruder im gesamten Text freizügig den Namen von König Magni Bronzebeard bemüht hat. Grelin beruft sich für das Vorgehen auf die Billigung des Königs, und Senir erwartet, dass diese Berufung auf die königliche Autorität im Senat von Ironforge für einigen Wirbel sorgen wird."}},faq={{q="Was ist der Zweck von Grelins Bericht?",a="Der Bericht überbringt Grelin Whitebeards Einschätzung der Frostmanetrolle aus dem Coldridgetal an seinen Bruder Senir in Kharanos. Er versichert der Führung außerhalb des Tals, dass die Trolle keine große Bedrohung darstellen und von den örtlichen Gebirgsjägern sowie vom Senat finanzierten Söldnern in Schach gehalten werden können.",al={"was ist grelins bericht","warum den bericht senden","zweck von grelins bericht"}},{q="Warum kann Grelin ihn nicht selbst überbringen?",a="Grelin bleibt im Coldridgetal stationiert, um die Trolle im Auge zu behalten. Obwohl er anfangs erwog, seinen Lehrling zu schicken, veranlasste ihn die gefährliche Reise durch den von Troggs verseuchten Tunnel dazu, die wichtigen Papiere stattdessen einem kampferprobten Abenteurer zu übergeben.",al={"warum nicht selbst ueberbringen","warum einem abenteurer anvertrauen"}},{q="Warum lässt Euch Gebirgsjäger Thalos mit dem Bericht passieren?",a="Gebirgsjäger Thalos bewacht den Tunnel aus dem Coldridgetal, um Zivilisten vor bösartigen Troggs zu schützen. Der Besitz von Grelins Bericht beweist, dass Ihr in dringenden Angelegenheiten der zwergischen Verteidigung reist, was Thalos davon überzeugt, Euch passieren zu lassen.",al={"warum laesst thalos durch","tunnelblockade","coldridgepass troggs"}},{q="Warum ist der Senat von Ironforge über den Bericht verärgert?",a="Senir Whitebeard bemerkt, dass Grelin im gesamten Dokument freizügig den Namen von König Magni herangezogen hat. Das Umgehen üblicher diplomatischer Feinheiten, um königliche Aufmerksamkeit einzufordern, verärgert die Bürokraten im Senat von Ironforge oft – selbst wenn die Brüder sich einig sind, dass die Politiker einen Weckruf nötig haben.",al={"warum senat veraergert","fuer aufruhr sorgen","senir reaktion"}}},fp="15,291,26.564.0,29.414.0,39.279.0,36.253.0,57.230.0,50.280.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Grelin Whitebeards Tagebuch",s="Grelin Whitebeards Tagebuch ist ein persönliches Feldnotizbuch, das von dem Zwergenspäher Grelin Whitebeard im Coldridgetal geführt wurde. Das Tagebuch enthält wichtige Notizen über die lokalen Aktivitäten der Frostmanetrolle und wurde vom Häuptling Grik'nir the Cold gestohlen und in die Trollhöhle im Coldridgetal verschleppt.",h="Grelin Whitebeards Tagebuch ist ein persönliches Feldnotizbuch, das von dem Zwergenspäher Grelin Whitebeard...",kw={"das coldridgetal","dun morogh","höhle der frostmane","grelin whitebeard","grik'nir the cold","senir whitebeard","das gestohlene tagebuch"},ang={["race:Dwarf"]="Die Wiederbeschaffung dieses Tagebuchs sichert entscheidende Zwergenaufklärung über die Bedrohung durch die Frostmane, die bis an die Tore der Ausbildungsstätten vor den Toren von Ironforge heranreicht."},sec={{t="Das Hauptbuch eines Spähers",b="Während er die aggressiven Bewegungen der Frostmanetrolle nahe dem Coldridgetal beobachtete, hielt Grelin Whitebeard seine Erkenntnisse gewissenhaft in diesem ledergebundenen Notizbuch fest. Das Dokument enthält seine unverfälschten Feldbeobachtungen bezüglich der Stärke, Organisation und Bedrohungsstufe der einheimischen Wintertrolle. Bei einer Konfrontation oder einem Hinterhalt wurde das Tagebuch jedoch von Grik'nir the Cold – einem schwer gezeichneten Trollanführer – entwendet, was Grelin dazu zwang, vorbeikommende Abenteurer anzuheuern, um in die Trollhöhle vorzudringen und es zurückzuholen, bevor sein Bericht fertiggestellt werden konnte."},{t="Depesche an Senir",b="Sobald die Notizen aus den Klauen von Grik'nir geborgen sind, bieten sie Grelin genügend Gewissheit, um die Trollbedrohung im Coldridgetal als vorübergehend eingedämmt einzuschätzen. Anhand der wiederbeschafften Aufzeichnungen vollendet Grelin seine schriftliche Depesche über den Aufstand der Frostmane, die anschließend versiegelt und Kurieren anvertraut wird, die zu seinem weiter entfernt in Dun Morogh stationierten Bruder Senir Whitebeard unterwegs sind."}},faq={{q="Wer hat Grelin Whitebeards Tagebuch gestohlen?",a="Das Tagebuch wurde von Grik'nir the Cold entwendet, einem bedeutenden und schwer gezeichneten Frostmanetroll-Haudegen, der tief im Inneren der Trollhöhle im Coldridgetal haust.",al={"wer hat das tagebuch genommen","wer hat grelins tagebuch","dieb von grelins tagebuch"}},{q="Was steht in dem Tagebuch?",a="Das Tagebuch enthält Grelin Whitebeards direkte Aufklärungsnotizen über die hiesigen Frostmanetrolle, deren Bedrohungsstufe und die Sicherheitslage innerhalb des Coldridgetals.",al={"inhalt des tagebuchs","was steht im tagebuch","grelin whitebeard notizen"}},{q="Was geschieht, nachdem das Tagebuch wiederbeschafft wurde?",a="Nachdem er sein Notizbuch zurückerhalten hat, verfasst Grelin anhand seiner Notizen einen endgültigen Aufklärungsbericht über die Trollsituation, den er anschließend von einem Abenteurer zu seinem Bruder Senir Whitebeard bringen lässt.",al={"was macht grelin mit dem tagebuch","nach dem gestohlenen tagebuch"}},{q="Warum ist dieses Tagebuch für Grelin so wichtig?",a="Ohne sein Notizbuch kann Grelin keinen genauen Spähbericht über den Frostmane-Aufstand für die Zwergenbehörden und seinen Bruder Senir zusammenstellen, wodurch die Verteidigung des Coldridgetals ungewiss bliebe.",al={"warum will grelin es zurück","bedeutung des tagebuchs"}}},fp="27,291,16.571.0,17.417.1,38.153.0,31.175.0,44.195.1,43.195.0"}
P.entries["item:grell-earring"] = {n="Grell-Ohrring",s="Grell-Ohrringe sind primitive Schmuckstücke, die von den wilden Kreaturen gesammelt und getragen werden, welche die Ruinen von Bashal'Aran heimsuchen. Obwohl sie auf den ersten Blick unscheinbar wirken, erlaubt ihre Nähe zu uralten Relikten feinfühligen Geistern, den verbliebenen magischen Siegeln nachzuspüren, die sie in Qualen gefangen halten.",h="Grell-Ohrringe sind primitive Schmuckstücke, die von den wilden Kreaturen gesammelt und getragen werden...",kw={"asterion","bashal'aran","dunkelküste","grell-ohrring","siegel","vile sprite","wild grell"},ang={["class:Mage"]="Die Ohrringe veranschaulichen, wie unbelebte Metalle über lange Zeiträume hinweg passiv die magische Umgebungssignatur uralter Schutzzauber absorbieren und bewahren können.",["race:NightElf"]="Zu sehen, wie geheiligte Elfruinen von diebischen Sprites überrannt werden, die geplündertes Messing tragen, ist eine bittere Erinnerung daran, wie tief die einst prächtigen Anwesen des uralten Kalimdor gefallen sind."},sec={{t="Spuren im Messing",b="Die Wild Grells und Vile Sprites, die um den eingestürzten Marmor von Bashal'Aran lauern, horten verschiedenste Schmuckstücke und fertigen oft Ohrringe aus Abfällen an, die sie in den Ruinen plündern. Für die meisten Sterblichen sind diese Gegenstände wertloser Unrat. Doch für Asterion, einen uralten Nachtelfen, der als gequälter Phantomgeist an die Ruinen gebunden ist, dienen sie als Wünschelruten. Indem er die nachhallenden magischen Spuren untersucht, die von diesen Ohrringen absorbiert wurden, versucht Asterion, das uralte Siegel aufzuspüren, das seine spektrale Gestalt gefangen hält."}},faq={{q="Woher stammen Grell-Ohrringe?",a="Sie werden von den Leichen von Wild Grells und Vile Sprites erbeutet, welche die zerstörte Nachtelfensiedlung Bashal'Aran an der Dunkelküste bewohnen.",al={"grell-ohrring beute","wo man grell-ohrringe bekommt","wer grell-ohrringe fallen lässt"}},{q="Warum will Asterion diese Ohrringe?",a="Asterion ist ein uralter Geist, der durch mächtige Magie in Bashal'Aran gefangen gehalten wird. Er nutzt die Ohrringe als magische Leiter, um Spuren des nahegelegenen Siegels aufzuspüren, das seine Seele seit Jahrhunderten bindet.",al={"asterion ohrringe","warum grell-ohrringe sammeln","grell-ohrring verwendung"}},{q="Wissen die Grells, dass sie magische Spuren an sich tragen?",a="Nein. Die Grells und Sprites horten und tragen den glänzenden Tand lediglich aus primitiven Instinkten. Sie sind unwissentlich mit dem in den Ruinen verborgenen magischen Siegel in Berührung gekommen, wodurch Restspuren auf dem Metall zurückblieben.",al={"sind die ohrringe magisch","verstehen grells magie"}},{q="Findet Asterion durch die Ohrringe, was er braucht?",a="Die Ohrringe selbst enthalten das Siegel nicht, doch ihre Untersuchung offenbart, dass die Kreaturen vor Kurzem damit in Kontakt waren, was die Suche tiefer in die umliegenden Ruinen leitet.",al={"haben die ohrringe funktioniert","asterion siegel ort"}}},fp="13,264,19.508.0,34.141.0,38.190.0,45.209.0,51.182.0"}
P.entries["item:grenka-s-claw"] = {n="Grenkas Klaue",s="Grenkas Klaue ist eine physische Trophäe, die der furchterregenden Harpyie Grenka Bloodscreech in den Tiefen des Baus der Wildfedern abgenommen wurde. Wenn sie Dorn Plainstalker im Wetterwinkel überreicht wird, dient sie als unbestreitbarer Beweis dafür, dass ein aufstrebender Abenteurer eine zermürbende körperliche Prüfung in den Höhen der Schlucht überstanden hat.",h="Grenkas Klaue ist eine physische Trophäe, die der furchterregenden Harpyie Grenka Bloodscreech in den Tiefen...",kw={"dorn plainstalker","grenka bloodscreech","grenkas klaue","harpyie","bau der wildfedern","screeching canyon","test of endurance","tausend nadeln","der wetterwinkel"},ang={["faction:Horde"]="Das Säubern der tiefen Bereiche des Baus der Wildfedern und das Ausschalten von Grenka Bloodscreech schwächt die Harpyienbedrohung ab, die Reisende rund um den Freiwindposten unablässig heimsucht.",["race:Tauren"]="Ältester Dorn Plainstalker betrachtet es als seine heilige Pflicht, junge Champions der Horde durch die Weisheit und Härte der Tauren-Riten zu stählen, bevor sie sich der weiteren, raueren Welt stellen."},sec={{t="Eine Trophäe der Ausdauer",b="In den verwinkelten Höhlen des Baus der Wildfedern, westlich des Freiwindpostens, lagern Harpyien Nahrungsvorräte und verteidigen ihr Territorium gewaltsam gegen Eindringlinge. Um die körperliche Widerstandskraft junger Champions auf die Probe zu stellen, beauftragt Dorn Plainstalker sie damit, in die tiefen Nistplätze einzudringen und die Nahrungsvorräte des Schwarms zu vernichten. Eine derart dreiste Provokation zieht unweigerlich den Zorn von Grenka Bloodscreech auf sich. Das Abtrennen und Überbringen ihrer bösartigen Klaue beweist, dass ein Krieger Welle um Welle erboster Harpyien standhalten und den bösartigen Ansturm ihrer Matriarchin überleben kann."}},faq={{q="Wofür wird Grenkas Klaue verwendet?",a="Die Klaue dient als Siegesbeweis für Dorn Plainstalker, einen Tauren-Ältesten, der im Wetterwinkel in Tausend Nadeln weilt. Seine Übergabe schließt den Test of Endurance ab und beweist, dass Ihr die körperliche Härte besitzt, die erforderlich ist, um anhaltende Kämpfe zu überstehen.",al={"verwendung von grenkas klaue","warum brauche ich grenkas klaue","grenkas klaue quest"}},{q="Wer ist Grenka Bloodscreech?",a="Grenka Bloodscreech ist eine mächtige Harpyie, die im Bau der Wildfedern im Screeching Canyon an den südlichen Klippen von Tausend Nadeln nistet. Sie taucht erst auf, wenn Eindringlinge den Schwarm bedrohen, indem sie ihre gelagerten Nahrungsvorräte vernichten.",al={"wer ist grenka","grenka bloodscreech lore","was ist grenka"}},{q="Wohin bringe ich die Klaue, sobald ich sie erbeutet habe?",a="Bringt die Klaue zurück zu Dorn Plainstalker im Wetterwinkel, der in den Klippen von Tausend Nadeln liegt. Er nimmt die Trophäe entgegen, um zu bestätigen, dass Eure Prüfung der körperlichen Ausdauer erfolgreich war.",al={"wo grenkas klaue abgeben","wer will grenkas klaue"}},{q="Warum verlangt Dorn Plainstalker ausgerechnet diese Trophäe?",a="Dorn Plainstalker leitet junge Reisende durch strenge Prüfungen, um sicherzustellen, dass sie geistig, spirituell und körperlich für größere Gefahren gewappnet sind. Grenka zu töten und ihre Klaue einzufordern, beweist, dass ein Krieger sowohl dem Hinterhalt eines Schwarms als auch dem direkten Angriff eines tödlichen Anführers standhalten kann.",al={"warum dorn die klaue will","zweck der klaue"}}},fp="13,294,21.537.0,31.263.0,27.249.0,42.191.0,55.290.0"}
P.entries["item:grimtotem-satchel"] = {n="Grimmtotemranzen",s="Der Grimmtotemranzen ist ein Lederbeutel, der von dem gefallenen Tauren Maur Grimmtotem tief im Ragefireabgrund umklammert wird. Selbst als Troggs ihn in der unterirdischen Höhle unter Orgrimmar überwältigten, beschützte Maur dieses Bündel mit seinem letzten Atemzug. Wenn man ihn birgt und nach Thunder Bluff zurückbringt, zeigt sich, dass Die Ältestengreisin Magatha Grimmtotem ein reges Interesse an dem hatte, was ihr Clanbruder bei sich trug.",h="Der Grimmtotemranzen ist ein Lederbeutel, der von dem gefallenen Tauren Maur Grimmtotem tief im...",kw={"die anhöhe der ältesten","grimmtotem","magatha grimmtotem","maur grimmtotem","ragefireabgrund","rahauro","ranzen","thunder bluff","trogg"},ang={["faction:Horde"]="Die Entdeckung eines toten Grimmtotem-Kuriers tief in den Tunneln unter Thralls Hauptstadt zeigt, dass die Gefahren des Ragefireabgrunds weit über einfache Bestienplagen hinausgehen.",["race:Tauren"]="Dass ein Grimmtotem tief unter Orgrimmar operierte und an Magatha auf Die Anhöhe der Ältesten berichtete, verdeutlicht die subtilen, beunruhigenden politischen Schachzüge der Grimmtotem innerhalb der vereinten Taurenstämme."},sec={{t="Im Todesgriff",b="Unter dem geschundenen Körper von Maur Grimmtotem in den Tiefen des Ragefireabgrunds entdeckt, wurde dieser einfache Ranzen in einer verbissenen, eisernen Umklammerung gehalten. Maur kämpfte verzweifelt darum, dessen Inhalt zu beschützen, während er von wilden Troggs umzingelt und getötet wurde. Die schiere Entschlossenheit, die nötig war, um einen Ranzen über das eigene Leben zu stellen, lässt darauf schließen, dass sein Inhalt weitaus bedeutsamer ist als gewöhnliche Rationen oder Vorräte für den Weg."},{t="Das Interesse der Ältestengreisin",b="Bringt man den Ranzen zu Rahauro auf Die Anhöhe der Ältesten in Thunder Bluff, offenbart sich das größere Geheimnis. Rahauro nimmt das Bündel im Namen von Magatha Grimmtotem, der Matriarchin des Klans der Grimmtotem, entgegen. Während Rahauro hofft, dass er Antworten darauf liefert, warum Maur in den Höhlen unter Orgrimmar sein Schicksal ereilte, setzte Magatha eigens Belohnungen für dessen sichere Rückgabe aus – was beweist, dass die Führung der Grimmtotem gezielte, verdeckte Interessen in dem von Troggs verseuchten Abgrund verfolgte."}},faq={{q="Wo ist der Grimmtotemranzen zu finden?",a="Der Ranzen wird tief im Ragefireabgrund entdeckt, der vulkanischen Höhle unter Orgrimmar. Er liegt unter der Leiche von Maur Grimmtotem, eingeklemmt in seinen Armen, wo er den Troggs der Höhle zum Opfer fiel.",al={"ort des ranzens","wo ist der ranzen","wie man den ranzen findet"}},{q="Wem gehört der Ranzen?",a="Er gehörte Maur Grimmtotem, einem Mitglied des Klans der Grimmtotem, der sich in den Ragefireabgrund wagte. Selbst im Tod blieben seine Arme fest um den Ranzen geschlungen, um dessen Inhalt vor den angreifenden Troggs zu schützen.",al={"wem gehört der ranzen","maur besitzer des ranzens"}},{q="Wer möchte den Ranzen zurückhaben?",a="Der Ranzen wird zu Rahauro auf Die Anhöhe der Ältesten in Thunder Bluff gebracht. Rahauro nimmt ihn unter direktem Befehl von Magatha Grimmtotem entgegen, die eine Belohnung für jeden aussetzte, der die Habseligkeiten ihres gefallenen Clanbruders birgt.",al={"wer erhält den ranzen","wer gibt den ranzen ab","wer will den grimmtotemranzen"}},{q="Warum trug ein Grimmtotem diesen unter Orgrimmar bei sich?",a="Maur Grimmtotems genaue Mission im Ragefireabgrund bleibt ungesagt, doch das tiefe Interesse, das Die Ältestengreisin Magatha Grimmtotem zeigte, lässt vermuten, dass er direkt unter der Hauptstadt der Orcs heimliche Angelegenheiten im Namen ihres Klans ausführte.",al={"warum war maur im ragefireabgrund","was machte der grimmtotem in orgrimmar"}},{q="Was befindet sich in dem Ranzen?",a="Der genaue Inhalt des Beutels bleibt versiegelt und wird direkt an Rahauro in Thunder Bluff übergeben. Rahauro sucht nach Hinweisen, um Maurs Tod zu erklären, während Magatha schlichtweg sicherstellen will, dass das, was ihr Clanbruder bei sich trug, nicht verloren bleibt.",al={"inhalt des ranzens","was ist in der tasche"}}},fp="17,385,12.406.0,26.457.1,37.200.0,31.211.0,31.217.0,50.233.0,27.241.0"}
P.entries["item:grizzled-bear-heart"] = {n="Herz eines ergrauten Bären",s="Ein Herz eines ergrauten Bären ist ein biologisches Reagenz, das von den widerstandsfähigen Bären gewonnen wird, die den Silberwald durchstreifen. Es dient als unverzichtbare Komponente bei den finsteren Forschungen der Königlichen Apothekervereinigung zur Neuen Seuche.",h="Ein Herz eines ergrauten Bären ist ein biologisches Reagenz, das von den widerstandsfähigen Bären gewonnen...",kw={"rezept für den tod","apotheker renferrel","herz eines ergrauten bären","apothekermeister faranell","neue seuche","altkiefer","koenigliche apothekervereinigung","silberwald","huschendes blut"},ang={["class:Hunter"]="Die gewaltigen Bären des Silberwalds sind gefährliche Beute, und das Aufspüren von Bestien wie Altkiefer für biologische Proben stellt die Geduld und die Ausweidefähigkeiten eines Jägers auf eine harte Probe.",["race:Undead"]="Für die Verlassenen unterstützt das Sammeln dieser Organe Apothekermeister Faranell unmittelbar bei der Erschaffung der ultimativen Waffe gegen Arthas' Geißel sowie gegen die lebenden Sterblichen, die Lordaeron bedrohen."},sec={{t="Ein Reagenz für die Neue Seuche",b="Die Königliche Apothekervereinigung arbeitet unaufhörlich daran, eine künstliche Seuche zu entwickeln, die fähig ist, sowohl die Geißel als auch die lebende Menschheit auszurotten. In den Wäldern des Silberwalds entdeckte Apotheker Renferrel, dass ein einzigartiges Gift aus dem Herzen eines ergrauten Bären in Verbindung mit dem Ichor von Spinnentieren ein bemerkenswert tödliches Gebräu ergibt. Kuriere und Getreue der Verlassenen jagen wilde ergraute Bären, riesige ergraute Bären und die berüchtigte Bestie Altkiefer, um diese Organe herauszuschneiden und sie direkt zu Apothekermeister Faranell tief im Apothecarium von Unterstadt zu bringen."}},faq={{q="Wofür wird ein Herz eines ergrauten Bären verwendet?",a="Herzen eines ergrauten Bären werden als experimentelle Reagenzien für die Königliche Apothekervereinigung gesammelt. Apotheker Renferrel fand heraus, dass Toxine aus diesen Herzen zu einem tödlichen Elixier destilliert werden können – als Teil der Bemühungen der Verlassenen, die Neue Seuche zu brauen.",al={"was bewirkt baerenherz","baerenherz quest","rezept fuer todesreagenzien"}},{q="Wer benötigt diese Bärenherzen?",a="Apotheker Renferrel im Silberwald weist Reisende an, die Herzen zusammen mit Huschendem Blut zu sammeln und sie direkt zu Apothekermeister Faranell im Apothecarium von Unterstadt zu liefern.",al={"wer braucht baerenherz","faranell baerenherz","wem gebe ich baerenherz"}},{q="Woher stammen Herzen eines ergrauten Bären?",a="Sie werden aus den verschiedenen ergrauten Bären herausgeschnitten, die den Silberwald durchstreifen, darunter wilde ergraute Bären, riesige ergraute Bären und die furchterregende wandernde Bestie Altkiefer.",al={"wo finde ich baerenherzen","welche baeren lassen herz fallen","baerenherz fundort"}},{q="Warum benötigt die Königliche Apothekervereinigung natürliche Tiergifte?",a="Die Vereinigung sucht nach wirksamen biologischen Kampfstoffen, die sowohl lebendes Fleisch als auch untote Physiologie verseuchen und zerstören können. Die einzigartigen chemischen Eigenschaften im Herzgewebe der zähen Bären des Silberwalds bieten eine ideale reaktive Basis, wenn sie mit virulenterem Spinnenblut vermengt werden.",al={"warum nutzen apotheker baerengift","warum tierherzen fuer seuche"}}},fp="19,204,28.603.0,39.256.0,28.196.0,40.178.0,65.281.0"}
P.entries["item:grizzled-scalp"] = {n="Ergrauter Skalp",s="Ein Ergrauter Skalp ist das dicke, pelzige Fell, das von ergrauten Distelbären erbeutet wird, die die südlichen Wälder der Darkshore durchstreifen. Obwohl es scheinbar eine sonderbare Trophäe ist, begehrt der exzentrische Gnomentüftler Wizbang Cranktoggle diese Pelze, um seine verborgenen Wildnismaschinen zu versorgen.",h="Ein Ergrauter Skalp ist das dicke, pelzige Fell, das von ergrauten Distelbären erbeutet wird, die die...",kw={"auberdine","dröhnkiste 525","darkshore","ergrauter skalp","ergrauter distelbär","distelbärenbier","wizbang cranktoggle"},ang={["profession:Engineering"]="Das Dröhnkistennetzwerk demonstriert das Talent der Gnome, automatisierte Destillationsapparate als Feldreparatur-Kommunikationsanlagen zu tarnen.",["race:NightElf"]="Nachtelfen beschützen die Tierwelt der Darkshore und betrachten sowohl mutwillige Wilderei als auch heimliche Gnomendestillen, die ihre Wildnis verunstalten, mit Argwohn."},sec={{t="Eine eigenartige Gärung",b="Reisende, die entlang der Straße südlich von Auberdine jagen, stoßen auf die verwitterten ergrauten Distelbären, die für ihre rauen, dicken Pelze bekannt sind. Während das Häuten gefährlicher Raubtiere für Wildnispirscher zur zweiten Natur gehört, enthüllt das Abgeben von vier ihrer Skalpe bei Dröhnkiste 525 einen weitaus weniger würdevollen Zweck. Der Apparat benötigt das Bärenfell weder für Reparaturen noch für wissenschaftliche Analysen. Stattdessen nutzt der Gnom Wizbang Cranktoggle die verborgenen Dröhnkisten, die über die Darkshore verstreut sind, als verdeckte Destillerien. Da die einheimischen Nachtelfen illegale Brauereibetriebe in ihren Siedlungen missbilligen, verlässt sich Wizbang auf leichtgläubige Abenteurer, die Bärenskalpe und andere bizarre Zutaten sammeln, um sein geliebtes „Distelbärenbier“ herzustellen."}},faq={{q="Wo kann ich Ergraute Skalpe finden?",a="Ergraute Skalpe werden von ergrauten Distelbären und deren Matriarchin, der Den Mother, in den Wäldern südlich von Auberdine entlang des Hauptpfads in der Darkshore erbeutet.",al={"ergrauter skalp fundort","wer lässt ergraute skalpe fallen","distelbärenskalp"}},{q="Wofür werden Ergraute Skalpe verwendet?",a="Sie werden in Dröhnkiste 525 eingeworfen, ein automatisiertes mechanisches Terminal, das im Gebüsch an der Straße weit südlich von Auberdine verborgen liegt.",al={"ergrauter skalp verwendung","was tun mit ergrauten skalpen"}},{q="Warum benötigt Dröhnkiste 525 Bärenskalpe?",a="Wizbang Cranktoggle nutzt sein Dröhnkistennetzwerk heimlich, um abseits der wachsamen Augen der Nachtelfen Schwarzgebrannten zu destillieren. Die ergrauten Skalpe dienen als Zutat für sein selbstgebrautes Distelbärenbier.",al={"warum will wizbang skalpe","dröhnkiste 525 zweck"}},{q="Warum versteckt Wizbang seine Brauerei in der Wildnis der Darkshore?",a="Die in Auberdine lebenden Nachtelfen schätzen keinen unerlaubten, lärmenden Alkoholhandel in ihren heiligen Hainen. Wizbang versteckte seine Vorrichtungen im Unterholz entlang der Wildnisstraßen, um seinen Schwarzbrennereibetrieb unbemerkt aufrechtzuerhalten.",al={"warum dröhnkiste verstecken","wizbang schnaps darkshore"}}},fp="14,268,23.726.1,33.162.0,34.133.0,38.194.1,60.237.1"}
P.entries["item:gryshka-s-letter"] = {n="Gryshkas Brief",s="Gryshkas Brief ist eine persönliche Danksagung, die von Gastwirtin Gryshka aus Orgrimmar verfasst und an den Schlächter Zargh im Crossroads gerichtet wurde. Der Brief, der nach dem Erhalt einer Lieferung frischen Fleisches verschickt wird, dient sowohl als Zeichen der Dankbarkeit als auch als Vorwand, um jungen Kurieren der Horde den Umgang mit dem Windreiter-Flugnetz beizubringen.",h="Gryshkas Brief ist eine persönliche Danksagung, die von Gastwirtin Gryshka aus Orgrimmar verfasst und an den...",kw={"brachland","crossroads","doras","gryshka","gryshkas brief","fleisch","orgrimmar","windreiter","zargh"},ang={["faction:Horde"]="Die Zustellung von Gryshkas Brief stellt einen Initiationsritus für junge Abenteurer der Horde dar und dient ihnen als erste Einführung in das Flugmeisternetzwerk der Wyvern, welches Durotar und das Brachland miteinander verbindet."},sec={{t="Eine dankbare Gastwirtin",b="Als Zargh ein Bündel zubereiteter Steaks aus den kargen Weiten des Brachlands in Orgrimmars zentrale Taverne schickt, verfasst Gastwirtin Gryshka dieses Schreiben als Antwort. Neben ihrem Lob über die Fleischstücke des Schlächters offenbart der Brief eine herzliche – wenn auch raue – Wertschätzung für Zargh und erinnert an amüsante Missgeschicke, wie etwa das Mal, als er bei der Fleischzubereitung einen Finger verlor. Gryshka schließt mit liebevoller Belustigung ab und bemerkt, dass er selbst dann gut aussieht, wenn er von seiner Arbeit blutverschmiert ist."},{t="Kurier entlang der Flugrouten",b="Das Überbringen von Gryshkas Brief dient Reisenden als praktische Lektion in der Logistik der Horde. Um das Pergament ins Crossroads zurückzubringen, werden Abenteurer angewiesen, sich bei Doras zu melden, dem Windreitermeister auf dem Plateau von Orgrimmar. Indem Doras nachweist, dass ein Reisender bereits bei Devrak im Crossroads vorbeigeschaut hat, führt er angehende Kuriere an die Wyvern-Flugrouten heran, die die Siedlungen von Durotar und dem Brachland miteinander verbinden."}},faq={{q="Wer hat Gryshkas Brief geschrieben?",a="Gastwirtin Gryshka, die die belebte Taverne im Valley of Strength in Orgrimmar leitet, verfasste den Brief nach dem Erhalt einer Lieferung von frischem Fleisch.",al={"wer hat das geschrieben","gryshkas brief autor","absender"}},{q="Für wen ist der Brief bestimmt?",a="Der Brief ist an Zargh adressiert, einen Schlächter im Crossroads im Brachland, der Gryshka mit Fleisch beliefert hat.",al={"empfänger","wer bekommt gryshkas brief","wohin geht der brief"}},{q="Was steht in dem Brief geschrieben?",a="Gryshka dankt dem Schlächter für seine erstklassigen Fleischstücke, erinnert sich scherzhaft an ein Missgeschick, bei dem er während der Arbeit einen Finger verlor, und neckt ihn damit, dass er selbst dann bezaubernd aussehe, wenn er blutet.",al={"brieftext","was sagt gryshka","briefinhalt"}},{q="Warum muss Doras den Brief sehen?",a="Doras ist der Windreitermeister von Orgrimmar. Gryshka schickt Euch zu ihm, damit er eine Reise auf einem Wyvern zurück ins Crossroads buchen kann, was veranschaulicht, wie die Flugrouten der Horde funktionieren.",al={"warum doras zeigen","doras der windreitermeister","orgrimmar flugmeister"}}},fp="16,325,20.483.0,30.447.0,27.149.0,31.118.0,34.181.0,38.174.0"}
P.entries["item:gunther-s-spellbook"] = {n="Gunthers Zauberbuch",s="Gunthers Zauberbuch ist ein persönlicher arkaner Foliant von Gunther Arcanus, einem ehemaligen Zauberer der Kirin Tor, der in Tirisfal weilt. Von Bethor Iceshard mit einer Verzauberung belegt, dient das Buch Gunther als Beweis dafür, dass auch andere Magier sich erfolgreich der Kontrolle des Lichkönigs entziehen konnten.",h="Gunthers Zauberbuch ist ein persönlicher arkaner Foliant von Gunther Arcanus, einem ehemaligen Zauberer der...",kw={"arcanus","bethor","dalaran","gunther","iceshard","kirin tor","zauberbuch","tirisfal"},ang={["class:Mage"]="Für Ausüber der arkanen Künste verkörpert der Foliant die gemeinsamen Wurzeln in Dalaran, die die derzeitige magische Führung der Verlassenen mit abtrünnigen Zauberwirkern in der Wildnis verbinden.",["race:Undead"]="Das verzauberte Buch verdeutlicht die fortwährenden Bemühungen der Verlassenen, mächtige unabhängige Untote zu rekrutieren, die sich aus eigener Kraft vom Lichkönig losgesagt haben."},sec={{t="Ein Zeichen alter Verbundenheit",b="Vor dem Dritten Krieg studierte Gunther Arcanus die arkanen Künste in Dalaran an der Seite von Bethor Iceshard und Thule Rabenklaue als Mitglieder der Kirin Tor. Als die Seuche des Untods über Lordaeron hereinbrach, fiel Gunther und wurde zum Untod erweckt, schaffte es jedoch schließlich, seinen eigenen Geist von der Geißel zu befreien. In dem Glauben, völlig isoliert zu sein und unablässig von den Häschern des Lichkönigs gejagt zu werden, blieb er Fremden gegenüber zutiefst feindselig gesinnt. Nachdem der Foliant geborgen worden war, legte Bethor Iceshard eine arkane Verzauberung über seine Seiten – eine unverkennbare magische Signatur, an der Gunther Bethors Gegenwart erkennen und begreifen sollte, dass er nicht der einzige Magier mit freiem Willen ist."}},faq={{q="Wem gehört dieses Zauberbuch?",a="Es gehört Gunther Arcanus, einem mächtigen untoten Magier, der auf einer einsamen Insel im Blendwassersee in Tirisfal haust.",al={"wem gehört das buch","gunther buchbesitzer","zauberbuch besitzer"}},{q="Warum hat Bethor das Zauberbuch verzaubert?",a="Bethor belegte den Folianten mit einem persönlichen Zauber, um einen unmissverständlichen Beweis dafür zu liefern, dass er in Lordaeron überlebt hat und frei von der Kontrolle des Lichkönigs ist – in der Hoffnung, Gunther zu einem Bündnis mit den Verlassenen zu bewegen.",al={"warum buch verzaubern","bethor zauber auf buch","buchmagie"}},{q="Warum ist Gunther misstrauisch, als das Buch zurückgebracht wird?",a="Gunther vermutet hinter jedem, der sich seiner Zuflucht nähert, einen Agenten der Geißel, der ihn erneut versklaven will, und glaubt anfangs, Der Abenteurer sei schlicht der Dieb, der seinen Folianten entwendet hat.",al={"warum ist gunther wütend","gunther verärgert","gunther feindselig"}},{q="Woher kannten sich Gunther und Bethor?",a="Vor langer Zeit studierten Gunther, Bethor Iceshard und Thule Rabenklaue als Freunde und Lehrlinge der Kirin Tor gemeinsam die Magie in der Stadt Dalaran, bevor die Seuche sie holte.",al={"bethor und gunther vergangenheit","kirin tor verbindung","dalaran freunde"}}},fp="19,288,22.651.1,24.124.0,37.199.0,52.175.0,43.167.0"}
P.entries["item:gyromechanic-gear"] = {n="Gyromechanische Getriebeteile",s="Gyromechanische Getriebeteile sind geborgene Stücke feinster Ingenieurskunst, die aus dem radioaktiven Niederschlag vor Gnomeregan gerettet wurden. Gnomen-Erfinder in Kharanos suchen nach genau diesen Teilen, um ein experimentelles Gerät zu konstruieren, das die Mutationen der Lepragnome rückgängig machen kann.",h="Gyromechanische Getriebeteile sind geborgene Stücke feinster Ingenieurskunst, die aus dem radioaktiven...",kw={"gnomeregan","gyromechanische getriebeteile","kharanos","lepragnom","operation rekombobulationsgerät","razzle sprysprocket","rekombobulator","restabilisationszahnrad"},ang={["profession:Engineering"]="Die feinmechanische Ingenieurskunst der Gnome ist berühmt für ihre extreme Komplexität und verlässt sich auf hochpräzise gyromechanische Komponenten, um instabile Prototypmaschinen zu regulieren.",["race:Gnome"]="Jedes geborgene Getriebeteil bringt gnomische Tüftler einen Schritt näher daran, ihre verstrahlten Brüder und Schwestern zu retten, die durch den Schnee vor Gnomeregan irren."},sec={{t="Komponenten für die Rekombobulation",b="Als Gnomeregan mit Strahlung überflutet wurde, um die Invasion der Troggs aufzuhalten, verwandelte dies einen Großteil der überlebenden Gnombevölkerung in wahnsinnige, verstrahlte Lepragnome. Da sie sich weigerten, ihre entstellten Artverwandten aufzugeben, begannen die Erfinder Ozzie Togglevolt und Razzle Sprysprocket mit der Ausarbeitung von Bauplänen für den Rekombobulator – eine ehrgeizige Apparatur, die die schrecklichen Auswirkungen der Strahlung umkehren soll. Der Bau des Prototyps erfordert Präzisionsmechanismen, die flüchtigen Innendrücken standhalten können, insbesondere Gyromechanische Getriebeteile und ergänzende Restabilization Cogs. Da die lokale Fertigung mit dem Fall ihrer Hauptstadt zusammenbrach, sind Forscher gezwungen, diese empfindlichen Bauteile direkt von den feindseligen Lepragnomen und Plünderern zu erbeuten, die Dun Morogh durchstreifen."}},faq={{q="Wofür werden Gyromechanische Getriebeteile verwendet?",a="Sie dienen als wichtige mechanische Komponente, die von Razzle Sprysprocket in Kharanos benötigt wird. Zusammen mit Restabilization Cogs werden sie in den Rekombobulator eingebaut, eine Prototypmaschine, die verstrahlte Lepragnome heilen soll.",al={"gyromechanische getriebeteile zweck","was bewirken gyromechanische getriebeteile","gyromechanische getriebeteile quest"}},{q="Woher stammen diese Getriebeteile?",a="Sie werden aus den zerstörten Außenbezirken von Gnomeregan und in der Umgebung von Dun Morogh geborgen, wo sie typischerweise von verstrahlten Lepragnomen und opportunistischen Plünderern getragen werden, die Teile aus der gefallenen Stadt entwendet haben.",al={"wo gyromechanische getriebeteile finden","gyromechanische getriebeteile beute","wer lässt gyromechanische getriebeteile fallen"}},{q="Kann der Rekombobulator Lepragnome tatsächlich heilen?",a="Razzle Sprysprocket bleibt hinsichtlich Ozzies Bauplänen grenzenlos optimistisch und glaubt fest daran, dass Anpassungen an Verbrennungskolben und Elektrogummigel ihre Artgenossen wiederherstellen werden. Ob die Maschine eine verheerende Strahlenvergiftung in großem Maßstab wirklich rückgängig machen kann, bleibt eine ungetestete gnomische Theorie.",al={"funktioniert der rekombobulator","können lepragnome geheilt werden","erfolg der rekombobulation"}},{q="Warum schmieden die Gnome nicht einfach neue Getriebeteile?",a="Der Verlust von Gnomeregan hat die industrielle Leistungsfähigkeit der Gnome zerstört und ihnen den Zugang zu ihren fortschrittlichsten Werkzeugen, Werkstätten und automatisierten Gießereien versperrt. Unversehrte Präzisionsbauteile aus der Zeit vor dem Fall am Rand der Stadt zu bergen, ist oft weitaus schneller, als Teile von Hand zu fertigen.",al={"warum getriebeteile sammeln","warum gyromechanische getriebeteile nicht herstellen"}}},fp="17,247,30.756.0,37.221.0,31.195.0,50.284.0,40.266.0"}
